window.RB_SHARDS=window.RB_SHARDS||{};window.RB_SHARDS[1]=[{"i":6892,"n":"*ברלין, אריה ליב מוכיח מפרשבור","f":"מרדכי מוכיח (מוריס)","k":"ליב מוכיח","dt":"תקנ - יט כסלו","b":"חתן ר יצחק ברלין, ונכד בעל \"צאן קדושים\". רב ודרשן בפרשבורג. הצטיין באהבת ישראל (אמר כי את צדקתו של אדם מעריכים לפי אהבת ישראל שבו). בניו: ר ישעיה ברלין-פיק, ר צבי הירש ברלין, ר דוד אב\"ד אה\"ו, ר ליפמן מאיזנשטט. חתניו: ר יוסף שטינהרט מפיורדא בעל \"זכרון יוסף\", ר צבי הירש קצנלנבוגן אב\"ד שוואבק. (במורשת הונגריה תאריך פטירתו - יב כסלו תקג). תלמיד ר צבי הירש חריף מהלברשטט. חתן ר יצחק ברלין בן יהודה-אחיו של בעל \"נחלת בנימין\". מחכמי פרשבורג-תף, והיה מפשר בסכסוכים בין קהלות ליחידים ובין קהלות לקהלות, ועסק הרבה בגמילות חסד. גיסו-אחי אשתו - של הראב\"ד ר משה לבוב. בניו: ר ישעיה ברלין מברסלוי, ר דוד מאה\"ו, ר ליפמן מאיזנשטט, חתניו: ר הירש בן משה קצנלנבוגן - אב\"ד מדינת פפאלץ, ר יוסף שטינהרט בעל \"זכרון יוסף\" שאשתו היה ידועה בחכמתה והביא חדושי תורה בשם אשתו בספרו וכן הביא מחדושיה - אחיה - ר ישעיה. חיבר 13 ספרים ואבדו - מתורתו בספרי בניו וחתניו."},{"i":6893,"n":"ב' הרב אליהו ברוך פינקל - תשס\"ח אדר","r":"משגיח דישיבת חידושי הרי\"ם","dt":"כד אדר"},{"i":6894,"n":"באבא, אברהם מפרס","bt":"תרא","bp":"טהראן","b":"רב הכולל בטהרן-פרס."},{"i":6895,"n":"באבאני, חיים מקושטא","b":"רב בקושטא, מתלמידיו - ההיסטוריון שלמה רוזניס."},{"i":6896,"n":"באבאני, יעקב מצפת","f":"אברהם","k":"בעל ישרש יעקב","dt":"תקמא - לפני","b":"מחכמי קושטא, עלה לצפת ויצא בשליחות. בשנת תקיט היה באמשטרדם והוציא \"זכרון בירושלים\". בגלל הרעש המשיך בדרכו באירופה עוד 9 שנים, בשנת תקכח היה בהמבורג והדפיס באלטונה \"ישרש יעקב\" שכנראה לא היה מחברו (אלא ר אברהם בסן מאמשטרדם). לדעת יערי בסן היסס לחתום שמו על הספר והעדיף לתלותו באילן גדול ר יעקב הנ\"ל. ר בנימין איספינוזה מליוורנו כתב ספר \"יסוד הקיום\" כנגד הספר הזה וטען כי לא ר יעקב הוא שחברו. ישב גם בשלוניקי והניח כסף להדפסת \"אורחות צדיקים\" לר יצחק מולכו - נדפס בתקנא."},{"i":6897,"n":"באבד, אברהם אריה ליב ממיקולינץ","f":"יהושע השל","bt":"תקם","dt":"תרך","b":"מחכמי מיקוליניץ, תלמיד ר יהושע השל באב\"ד. מחותן עם ר מיכל הורביץ ברחא\"ל מקראקא. בנו ר יצחק ישב על כסאו אחריו. בנו ר יעקב סירב לרבנות לובלין."},{"i":6898,"n":"באבד, אברהם מבוסק","f":"יעקב","bt":"תקעה","dt":"תרסה","b":"אב\"ד בוסק ורדיחוב על מקום אביו, חתן ר ישכר דב רמרז אב\"ד סקוהל."},{"i":6899,"n":"באבד, אברהם מבוסק","f":"ישכר דב בר","k":"בעל כוכבי אברהם","bt":"תרם","dt":"תשא - תמוז","b":"חתן ר מרדכי אפרתי מחוליוב. רבה של בוסק על מקום אביו. חיבר \"כוכבי אברהם\" נלוה לספר \"אוצר יד החיים\" של אביו. נספה בשואה. בנו ר ראובן דוד נספה אף הוא."},{"i":6900,"n":"באבד, אברהם מסטריזוב","f":"שמואל","bt":"תרלג","dt":"תשג","b":"חתן דודו ר יהושע השל אב\"ד סטריסוב. אב\"ד סטריסוב(=סטריזוב)-תרנד על מקום גיסו ר דוד מנחם מוניש שעבר ליברוב, כנראה נספה בשואה."},{"i":6901,"n":"באבד, אברהם מפודקמין","f":"יהושע השל","b":"אב\"ד פודקמין-תרל."},{"i":6902,"n":"באבד, אברהם מפרמישלא","f":"שלום יעקב","bt":"תרם","dt":"תשב","b":"יתכן שהיה נכדו ולא בנו של ר שלום יעקב. חתן ר נתן הבנשטרייט אב\"ד זמושץ וראב\"ד פרמישלא. רב בפרמישלא על מקום חותנו."},{"i":6903,"n":"באבד, אברהם מרדכי מפוהורינסק","dt":"תש..","b":"רבה של פוהורינסק בין מלחמות העולם. נספה בשואה."},{"i":6904,"n":"באבד, אברהם משה","f":"יוסף דב","k":"בעל אמרי טבא","r":"אב\"ד סונדרלאנד שבאנגליה","bt":"תרסט","bp":"מיקוליניץ","dt":"תשכו","dp":"לונדון","b":"תלמיד דודו בעל החבצלת בלוזן-שוייץ-תרצה. רב במיקוליניץ-תרצב, רב קהלה בלונדון-תרצו. חתן דודו ר ישראל אריה מרגליות האדמור מפרמישלן. בזמן המלחמה היה חבר מועצת הממשלה הפולנית הגולה. רבה של סודרלנד-תשו. חיבר \"אמרי טבא\" בני ברק תשמג.","bk":[["אמרי טבא - תשובות וחידושים",""]]},{"i":6905,"n":"באבד, אברהם משה מהומורא","f":"מנחם מנדל מגורה-","bt":"תרנט","dt":"תשם - יא אב","dp":"ירושלים","b":"ממשפחת אדמורי ויזניץ, וגיסו של האדמור בעל \"מקור ברוך\". תלמיד ר מאיר ארק. חסיד צורטקוב. רב בגורה-הומורה על מקום אביו יחד עם גיסו ר יעקב משולם גינצבורג. חתן ר אליעזר ניסן הורביץ מדזיקוב וצפת (וחותנו חורגו שגידל את כלתו - ר ישראל \"אהבת ישראל\" מויזניץ. ניצל מהשואה ואחריה רב בהומורא וובריטשאן-בסרביה. עלה לארץ ושימש רב בקפריסין וביפו, מקורב לחזון איש. סייע לגיסו האדמור מויזניץ בעל \"מקור ברוך\" בהקמת ישיבת \"יחל ישראל\" בחיפה. בסוף ימיו התגורר ב\"מאה שערים\" בירושלים. נפטר ללא ילדים. הניח חיבורים בכת\"י."},{"i":6906,"n":"באבד, אורי שרגא פיבל מבוזנוב","f":"יעקב צבי","bt":"תרעו","dt":"תשג","dp":"טרנופול","b":"רבה האחרון של בוזנוב. חתן ר דוד מנחם מונד באבד. הגיע לארץ - חזר לפולין ונספה בשואה."},{"i":6907,"n":"באבד, אלכסנדר אשר מנירבטור","f":"יצחק מטרטקוב בן יהוש","bt":"תרע","bp":"טרטקוב","b":"תלמיד דודו ר דוד מנחם מניש מטרנופול בעל \"חבצלת השרון\", ונסמך ממנו ומאת: ר אברהם יעקב הורביץ מפרביזנא בעל \"צור יעקב\". חתן ר אהרן טיטלבוים אב\"ד וולובה(=וואלאווא)-נירבטור. ראב\"ד בנירבטור, בודפשט, דיין בבי\"ד מיוחד להתרת עגונות בהונגריה, עבר לארה\"ב-תשז והיה ר\"מ בישיבת מהרש\"ק. בזיוו\"ש חתן ר יחיאל גרינצווייג אב\"ד דלהא. ערך את הירחון \"עטרת תפארת\" - פודוולוטשיסק-בילגוריי תרצא, ומתורתו שם."},{"i":6908,"n":"באבד, אלעזר מדובנא","f":"ישכר בעריש מקרקא","dt":"תקא - טז שבט","dp":"ברודי","b":"נכד ר השל מקראקא. רב ברוזינאי, דובנא-רבתי-תעו-תעט על מקום ר יצחק איזיק גינצבורג ובנו ר יהושע השל על מקומו אחריו, עבר לברודי. נכדו(-בן בתו) ר יחזקאל לנדא בעל הנודע ביהודה ונזכר בספריו."},{"i":6909,"n":"באבד, אריה ליבוש מסנדובה-וישני","f":"שמואל מסנדובה וישניה","bt":"תרל","dt":"תשד","b":"אב\"ד סנדובה-וישניה, על כסא אביו. בנו ר שמואל רב בגדיניה. נספה בשואה."},{"i":6910,"n":"באבד, אשר","b":"תשובה אליו ב\"חסד לאברהם\"-תרד."},{"i":6911,"n":"באבד, אשר אלכסנדר מטרנופול","dt":"תשג","b":"רב בטרנופול"},{"i":6912,"n":"באבד, אשר מטרטקוב","b":"רב בטרטקוב. פרסם מאמרים ב\"עטרת תפארת\" - פודוולוטשיסק-בילגוריי תרצא."},{"i":6913,"n":"באבד, אשר מניו יורק","b":"רב בניו יורק-תשל"},{"i":6914,"n":"באבד, דב","b":"בנו של אב\"ד שטרוויץ. מתורתו ב\"עטרת תפארת\"-תרצא."},{"i":6915,"n":"באבד, דב בר מברוד","b":"רב בברודי-ת\"צ"},{"i":6916,"n":"באבד, דוד","b":"חתן הרב מקולבסוב. תשובה אליו \"חזון נחום\"-תרצו."},{"i":6917,"n":"באבד, דוד מאיר מסניאטין וצפת","f":"יוסף - מנחת חינוך","dp":"צפת","b":"אחיינו של ר חיים מצאנז. רבה של פרוביזא-תריד, סניאטין על כסא אביו, עלה לצפת לפני תרמח וכיהן שם כרב. חתנו ר יעקב יוסף המר על מקומו אחריו בסניאטין. עלה לצפת וכיהן כראבד, עבר לירושלים וחתם שם בשנת תרמג בהסכמה."},{"i":6918,"n":"באבד, דוד מדובראויץ","f":"יהושע העשל באב\"ד","dt":"תקח - ט תמוז","b":"רב בדובראוויץ"},{"i":6919,"n":"באבד, דוד מנחם מוניש מטרנופול","f":"יהושע השל מפודווליסק","k":"בעל חבצלת השרון","r":"רב בסטריסוב משנת תרנב, ואח\"כ ביברוב ואח\"כ ראב\"ד טרנופול","bt":"תרכה","bp":"ברודי","dt":"תרצו","b":"רב בסטריסוב על מקום אביו-תרנב, יברוב-תרנד על מקום חותנו וחתנו ר אלימלך פרנקל-תאומים על מקומו אחריו, טרנופול-תרעא. היה נשיא אגודת הרבנים בגליציה. בשנת תרצד נסע לשנתים לשוויץ ופגש את רבני מערב אירופה. תולדותיו בספר \"תהלה לדוד\" לר אברהם פוליסיוק. חיבר \"חבצלת השרון\" בילגוריי תרצא (הערות על ספרו ב\"בכורי ישראל\" לר שמואל באבד). פרסם מאמרים ב\"הכרם\" - וארשא תרצא, \"עטרת תפארת\" - פודוולוטשיסק-בילגוריי תרצא.","bk":[["חבצלת השרון - שו\"ת",""]]},{"i":6920,"n":"באבד, דוד משטרוויץ","b":"פרסם מאמרים ב\"עטרת תפארת\" - פודוולוטשיסק-בילגוריי תרצא."},{"i":6921,"n":"באבד, חיים מברוד","dt":"תריט - טז תשרי","b":"רב בברוד"},{"i":6922,"n":"באבד, חיים ממיקוליניץ","f":"משה","bt":"תקעה","dt":"תרמט","b":"אחיו של ה\"מנחת חינוך\", אב\"ד זלוויץ(=זלאויץ). במיקוליניץ על מקום חותנו. חתם על כרוז ההתפדות מהכופרים-תרמא."},{"i":6923,"n":"באבד, חיים מפודוולוטשיסק","f":"יהודה אריה ליב","b":"אב\"ד פודוולוטשיסק. עורך \"עטרת תפארת\" - פודוולוטשיסק-בילגוריי תרצא, יחד עם ר אלכסנדר אשר באבד."},{"i":6924,"n":"באבד, יהודה אריה ליב מפודבוליצ","f":"יהושע העשל מפודבוליצ","bt":"תרלג-ח","bp":"סטריסוב","dt":"תשג","b":"נכד ר חיים ממיקולינץ (אחיו של בעל מנחת חינוך). רבה של פודבוליצסק(=פודוולוטשיסק) על מקום אביו. חתן ר ראובן דוד אפרתי אב\"ד חוליוב. היה מחשובי רבני בלז, נספה בשואה עם עשרת ילדיו. פרסם מאמרים ב\"עטרת תפארת\" - פודוולוטשיסק-בילגוריי תרצא."},{"i":6925,"n":"באבד, יהודה זונדל מברוד","f":"יעקב שלום","bt":"תרל","dt":"תשב","b":"חתן ר יוסף דוד מייער מססוב. מחותן עם רש\"י קוטן מברודי. אב\"ד לעשנוב, שטרוויץ, ברודי על מקום מחותנו. נספה בשואה."},{"i":6926,"n":"באבד, יהושע השל מדובנא","f":"אלעזר מדובנא וברודי","bt":"תמז","dt":"תפט - כט תמוז","dp":"דובנא","b":"רב בדובנא-תעט על מקום אביו שעבר לברודי (ויש אומרים על מקום ר שמחה רפפורט) ור אברהם כהנא על מקומו אחריו (ולפי פעסיס - ר זלמן אפרים על מקומו אחריו ביניהם). הסכים על \"יד כל בו\" - פפד\"א תפו, ועוד .אחיינו(-בן אחותו) - ר יחזקאל לנדא בעל נודע ביהודה. בנו - ר ישער בעריש מברודי. הניח אחריו צדקה להחזקת לומדי תורה, וספר תורה בביהכ\"נ הגדול."},{"i":6927,"n":"באבד, יהושע השל מדוברומיל","b":"מחכמי דוברומיל-תרל, ובנרול."},{"i":6928,"n":"באבד, יהושע השל מטארלי","f":"ישכר בעריש","b":"נגיד,רב בטארלי-ת\"צ"},{"i":6929,"n":"באבד, יהושע השל מטרטקוב","f":"יצחק","bt":"תרסו","dt":"תשב","b":"רב בטרטקוב-תרפט על מקום אביו. חתן ר יצחק רובין האדמור מיברוב."},{"i":6930,"n":"באבד, יהושע השל מטרנופול","f":"יהודה אריה ליבוש","bt":"תרנב","dt":"תשב","b":"חתן דודו ר דוד מנחם מוניש מטרנופול, רבה של טרנופול על מקום חמיו. נספה בשואה (עם אשתו ובתו). פרסם מאמרים ב\"עטרת תפארת\" - פודוולוטשיסק-בילגוריי תרצא."},{"i":6931,"n":"באבד, יהושע השל מטרנופול","f":"יצחק","k":"בעל ספר יהושע","bt":"תקיד","bp":"ברודי","dt":"תקצח","dp":"מיקוליניץ או פשוורסק","b":"חתן ר שמואל באבד (ולפי קורות היהודים בלובלין - חתן ר ישראל איסר בן ר מרדכי ר ליבישיס בן ר ישראל איסר אב\"ד לובלין). רב בבוזנוב, טרנופול-תקסא (בעבר כיהן שם דודו זקנו בעל אותו השם), לובלין-תקפח וחזר לטרנופול בגלל מחלוקת בגלל חסידותו (המחלוקת היתה עם האחים הפרנסים ר וולף ור פיבל ור הירש חתן ר אברהם בעל \"מחזה אברהם\"). היה ממתנגדיו החריפים של המשכיל יוסף פרל. חיבר \"ספר יהושע\" זולקווא תקפט. מבניו: ר משה מפרשוורסק, ר אברהם אריה מקיליניץ."},{"i":6932,"n":"באבד, יהושע השל מטרנופול","f":"שמעון","bt":"תרכז","dt":"תרעט","b":"רב בטרנופול על מקום אביו-תרסט. חתם בתרעג ברשות בית דין צדק לצד ויזניץ."},{"i":6933,"n":"באבד, יהושע השל מיאס","f":"משה מסניאטין","bt":"תריט","b":"תלמיד ונכד ר יוסף באבד בעל \"מנחת חינוך\". חתן ר אורי שרגא פיבל טויבש מיאס. רב בסוליצה(=סעלוציא)-מחוז באטשאן-תרמז, יאסי-תרסח. נסמך מאת: ר יהודה לנדא מסדיגורא בעל \"יד יהודה\", ר משה תאומים בעל \"דבר משה\". בניו - ר משה-חתן ר נח רוסט מלובטשוב, חתנו - ר משה ברגמן מרומניק סאראט."},{"i":6934,"n":"באבד, יהושע השל ממיקוליניץ","f":"משה ממיקוליניץ","bt":"תרל","dt":"תרצה","b":"רב במיקוליניץ-תרסו על מקום אביו. בנו ר יוסף בן ציון רב אחריו."},{"i":6935,"n":"באבד, יהושע השל מסטריסוב","f":"חיים","bt":"תר","dt":"תרנה","b":"מחסידי בלז. אשתו גיטלה בת ר בריש פופרש מברודי (כנראה) והיתה למדנית שיצטטו ממנה פירושים לאגדות הש\"ס. אב\"ד סטריסוב-תרכח, פודוולוציסק-תרנב."},{"i":6936,"n":"באבד, יהושע השל מפודקמין","f":"יעקב צבי","bt":"תרעז","dt":"תשג","b":"אב\"ד פודמקין-תרצג."},{"i":6937,"n":"באבד, יוסף בן ציון ממיקוליניץ","f":"יהושע השל","bt":"תרע","dt":"תשב","b":"רבה של מיקוליניץ, על מקום אביו. נספה בשואה. פרסם מאמרים ב\"עטרת תפארת\" - פודוולוטשיסק-בילגוריי תרצא."},{"i":6938,"n":"באבד, יוסף דב מטויסט","f":"יהושע השל","bt":"תרלה","bp":"סטריסוב","dt":"תשב","b":"רב בטויסט-תרסד, מיקוליניץ-תרסח על מקום אביו."},{"i":6939,"n":"באבד, יוסף מוינה וארה\"ב","f":"משה","bt":"תרסח","bp":"ליביטשוב","dt":"תשנז","dp":"ירושלים","b":"רב ודוקטור מוינה. עבר לארה\"ב וכיהן כר\"מ בבימ\"ד לתורה בשיקגו. עלה לירושלים-תשמב."},{"i":6940,"n":"באבד, יוסף מטרנופול","f":"משה מפשעוורסק","k":"בעל מנחת חינוך","bt":"תקסא (באו' תקן)","dt":"תרלד - כד אלול","b":"תלמיד ר נפתלי צבי מרופשיץ, ר שמעון מירוסלב, וחותנו ר דוד מזבלטוב. היה מקורב לר נפתלי מרופשיץ. חתן ר שמעון רפפורט, ובזיוו\"ש חתן אריה ליבוש הלברשטם מטרניגד, ובזיוו\"ש חתן ר דוד הגר מזבלטוב. רב בהוסקוב, רודשין, זברז, סניאטין-תרב, הורודנקה-תריא, טרנופול-תריז על מקום חותנו. חיבר \"מנחת חינוך\"."},{"i":6941,"n":"באבד, יוסף מקאליש","f":"יעקב","bt":"תרלה","bp":"גליגורי","dt":"תשג","b":"דיין בטשודין-תרסה, לבוב-תרסח על מקום סבו, רבה של קלוש(=קאליש)-תרע, רב בוינה-תרפט על מקום הרב מאירזון המינוי היה שנוי במחלוקת ורבני ירושלים בראשות הרב קוק התנגדו לו - לעומת רבני פולין שתמכו בו. בשנת תרצט ברח לאמשטרדם, ואחר כך בת\"ש הגיע למנצ'סטר."},{"i":6942,"n":"באבד, יחיאל מיכל מבילקמין","f":"יעקב מרדכי באב\"ד","b":"רב בבילקאמין-ת\"ק"},{"i":6943,"n":"באבד, יעקב","f":"יצחק","bt":"תרטו","dt":"תרעו","b":"נבחר לאב\"ד זלוויץ אך סירב לתפקיד. חתן ר אלכסנדר שמואל הלפרין ראבד לבוב."},{"i":6944,"n":"באבד, יעקב מבוסק","f":"נתן","bt":"תקם","dt":"תרי","b":"אב\"ד בוסק-תקע על מקום אביו, ורדיחוב, ובנו ר אברהם ישב על כסאו בשתי הערים."},{"i":6945,"n":"באבד, יעקב מברוד","f":"יצחק מקרקא","dt":"תקח - כז אלול","b":"חתן ר שמואל מרישא. גביר ופרנס בברודי, הקים בית מדרש בברוד. בניו - ר שמואל(19034), ר יצחק(10505). חתניו - ר יצחק הורביץ(10595), ר נפתלי הרץ(16176), ר משה(14461), ר חיים לנדא(6054), ר דב בעריש(4475)."},{"i":6946,"n":"באבד, יעקב מיאנוב","f":"שמעון מיאנוב","bt":"תרמח","bp":"יאנוב","dt":"תשלב","b":"נכד המהרש\"ם מברזן. חתן ר שמחה גולדברג מלימנוב. ניצל מהשואה ועבר לארה\"ב."},{"i":6947,"n":"באבד, יעקב מרדכי מברודי","f":"יצחק באב\"ד","dt":"תק - כו תמוז","b":"חתן ר שאול קצנלנבוגן(17931). רב בברודי. בניו - ר מנחם מנדל(13402), ר יחיאל מיכל(9250). חתניו - ר יהושע השל(7700), ר יעקב חריף(9638), ר יחזקאל(9016)."},{"i":6948,"n":"באבד, יעקב צבי מאוסיצא","f":"שמחה מטרמבובלא","b":"אב\"ד אוסיצא-סקופיע(=בעסקאפיא) הנקראת פוהורינסק-תרע."},{"i":6949,"n":"באבד, יעקב צבי מזברז","f":"ישעיה מזברז","bt":"תר","dt":"תרסז","b":"חתן ר שמואל שמלקא הורביץ מסנוק שהביא מתורתו בספרו \"סמיכת משה\". אב\"ד זברז-תרנג על מקום אביו."},{"i":6950,"n":"באבד, יעקב צבי מפדהינסקא","dt":"תרצו","b":"רב בפדהינסקא"},{"i":6951,"n":"באבד, יעקב שמואל מסנדובה-וישנא","f":"חיים","k":"בעל תורת שמואל","bt":"תרא","dt":"תרסה","b":"אב\"ד סנדובה וישניה-תרלד. חיבר \"תורת שמואל\" - לא נדפס."},{"i":6952,"n":"באבד, יצחק איציק מדוברומיל","f":"שמואל משה","k":"בעל קול ברמה","bp":"טרנופול","b":"חתן ה\"מעשה רוקח\". התישב בדוברומיל. חסיד רוזין. חיבר \"קול ברמה\" פרזעמישל תרמד."},{"i":6953,"n":"באבד, יצחק מבוליחוב","f":"יחיאל מיכל באב\"ד","b":"ראש מדינה בבוליחוב-תקם. בנו - ר אליהו ונכדו ר אריה ליב בלחובר. חתנו - ר משלם הכהן מלבוב בעל עיקר תוי\"ט."},{"i":6954,"n":"באבד, יצחק מברוד","f":"יעקב יוקל באב\"ד","dt":"תקכא - כא אלול","b":"גדול בברודי"},{"i":6955,"n":"באבד, יצחק מברודי וזסלב","f":"ישכר בריש מקראקא","k":"יצחק קראקובר","dt":"תסה - ד תשרי","b":"נכד הרבי ר השלה. מגדולי דורו, אבי שושלת באב\"ד, רב בברעזאן, ברודי. חתנו ר ישראל הלפרין מאוסטרהא."},{"i":6956,"n":"באבד, יצחק מחרסקוב","f":"אברהם אריה ליב","bt":"תקעב","dt":"תרסב","b":"חתן ר צבי הירש תאומים אב\"ד קלוש. רבה של חרסקוב-תריב, אב\"ד קלוש-תרכב על מקום חמיו, בנו ר יוסף על מקומו (וביניהם ר שמעון באבד)."},{"i":6957,"n":"באבד, יצחק מטרטקוב","f":"יהושע השל","bt":"תרכט","dt":"תרפט","b":"חתן ר מרדכי אפרתי, אב\"ד טרטקוב-תרף על מקום חמיו. גבאי ארץ ישראל."},{"i":6958,"n":"באבד, יצחק מסאסוב","f":"חיים","bt":"תר","dt":"תרסב","b":"חתן ר יואל אשכנזי אב\"ד זלוטשוב. רבה של סאסוב-תרס."},{"i":6959,"n":"באבד, יצחק מקוזלוב","f":"משה","b":"אב\"ד קוזלוב ומיקוליניץ על מקום אביו."},{"i":6960,"n":"באבד, ישכר דב בער מברוד","f":"יהושע השל מדובנא","dt":"תקמט - כז ניסן","dp":"ברודי","b":"מחכמי ברוד"},{"i":6961,"n":"באבד, ישכר דב בר מבוסקא","f":"אברהם מבוסקא","k":"בעל אוצר יד החיים","r":"רב בבויסק","bt":"תרה-ט-יא-יט","dt":"תרצח - ז שבט","b":"מצאצאי ר השל מקראקא, ונכד ר ישכר דב רמר\"ז מסקול. חתן ר אליעזר אטינגר מברוד וזולקוא. מקורב לדוד השר שלום מבלז, וקרוביו ר יהושע ור ישכר אדמורי בלז, והגיש את ה\"קויטל\" הראשון לר אהרן מבלז. רב בבוסק-תרסה על מקום אביו, אב\"ד זולקוא על מקום אביו ובנו ר אברהם בעל \"כוכבי אברהם\" על מקומו אחריו, מגדולי חסידי בלז. חיבר \"אוצר יד החיים\" למברג תרצד. פרסם מאמרים ב\"בית ועד לחכמים\" - יאסי תרסט, \"בית ועד לחכמים\" - סטמר תרפב, \"רבותינו שבגולה\" - פרשבורג תרעה.","bk":[["אוצר י\"ד החיים - ליקוטים",""]]},{"i":6962,"n":"באבד, ישעיה מזברז","f":"משה","bt":"תקפא","dt":"תרנג","b":"אחיו של המנחת חינוך, אב\"ד קריווטש, זברז-תריח."},{"i":6963,"n":"באבד, מאיר מדוברומיל","f":"יצחק איציק","bp":"דוברומיל","b":"חסיד צורטקוב. חתן ר מיכל שטרק, עבר לוישנה, בוליחוב."},{"i":6964,"n":"באבד, מאיר מטרטקוב","b":"פרסם מאמרים ב\"עטרת תפארת\" - פודוולוטשיסק-בילגוריי תרצא."},{"i":6965,"n":"באבד, מנחם מנדל מברוד","f":"יעקב מרדכי באב\"ד","b":"מגדולי חכמי ברוד-ת\"ק"},{"i":6966,"n":"באבד, מנחם מנדל מגורא-הומורא","f":"צבי הירש","bt":"תרכג","bp":"קלוש","dt":"תרץ","b":"תלמיד רא\"ש הלפרין שהזכירו בספרו \"שו\"ת מהרא\"ש\". רב בגורא-הומורא-תרן, בנו ר אברהם משה וחתנו ר יעקב משולם גינצבורג על מקומו אחריו."},{"i":6967,"n":"באבד, מנחם מנדל מלבוב","f":"מרדכי באב\"ד","b":"מרבני גליל לבוב-תקי\"ב"},{"i":6968,"n":"באבד, מרדכי מאוסציא","f":"יעקב צבי","bt":"תקעה","dt":"תשג","b":"אב\"ד אוציא ביסקופיע על מקום אביו. נספה בשואה."},{"i":6969,"n":"באבד, משה מברוזדוביץ","f":"שלום יעקב","bt":"תרלה","dt":"תשג","b":"נכד האדמור מסטרטין. חתן ר חיים אייזן אב\"ד סווירז. אב\"ד רוזדוביץ-תרפה. נספה בשואה."},{"i":6970,"n":"באבד, משה מזולקוא","f":"שמואל","k":"בעל זכרון לראשונים","bt":"תרן","bp":"ווריש","dt":"תשג","b":"חסיד בלז ומקורב לאדמור. חתן ר יהודה ליבוש ציעשינובר מזולוקא. רב בזולקוא. חיבר \"זכרון לראשונים\" ו\"זכר פניני זולקוא\" - אבדו בשואה. נספה בשואה."},{"i":6971,"n":"באבד, משה מטרמבובלה","f":"יצחק מקאליש","bt":"תר (תריח)","dt":"תרעו","b":"חתן ר אברהם מנדל שטיינברג בעל \"מחזה אברהם\". אב\"ד טרמבובלה-תרלו ואחריו ר שמחה באבד, רב בלבוב-תרסח."},{"i":6972,"n":"באבד, משה מסניאטין","f":"יוסף-המנחת חינוך","bt":"תקף","dt":"תרכח","b":"בנו של ה\"מנחת חינוך\". חתן הגביר ר שמעון רפפורט. דיין בסניאטין-תרך, אב\"ד בסוליצה (בוקובינה)."},{"i":6973,"n":"באבד, משה מפרמישלא","f":"יהושע השל","dt":"תשג","b":"רב בפשעמישל"},{"i":6974,"n":"באבד, משה מפשוורסק","f":"יהושע השל","bt":"תקלה","dt":"תקצח","b":"אב\"ד פשוורסק-תקפג, חתן ר שמואל עטינגר מטרטקוב. בנו ר יוסף מטרנופול."},{"i":6975,"n":"באבד, משה מקוזלוב","f":"חיים מזלוזיץ","bt":"תקצט","dt":"תרסו","b":"חתן ר יעקב אביגדור אב\"ד פודקמין. אב\"ד קוזלוב ומיקוליניץ על מקום אביו, בנו ר שמואל על מקומו אחריו במיקוליניץ."},{"i":6976,"n":"באבד, נתן מיברוב","f":"יצחק","bt":"תקכ","dt":"תקף","b":"אחיו של ר יהושע השל בעל \"ספר יהושע\". אב\"ד יברוב-תקס, רבה של בוסק-תרכח. חתן ר נפתלי הירץ אשכנזי אב\"ד ראווא. בנו ר יעקב ישב על כסאו אחריו."},{"i":6977,"n":"באבד, צבי","b":"רב-שנת תר\"ל"},{"i":6978,"n":"באבד, צבי הירש","f":"יצחק","b":"נבחר לרבנות זולקוא אך ויתר לטובת הרב מייזלש-הורביץ ששב מטשרנוביץ."},{"i":6979,"n":"באבד, ראובן","dt":"תשג","b":"רב בלבוב"},{"i":6980,"n":"באבד, ראובן דוד מפודוולוטשיסק","b":"פרסם מאמרים ב\"עטרת תפארת\" - פודוולוטשיסק-בילגוריי תרצא."},{"i":6981,"n":"באבד, שלום מוואריש","f":"יהושע השל","bt":"תרלז","dt":"תרעח","b":"חתן ר פנחס אייזן מווריש, אב\"ד וואריש-וורונז על מקום חותנו."},{"i":6982,"n":"באבד, שלמה מפשמישל","dt":"תש..","b":"רב בפשמישל-תרצד. נספה בשואה."},{"i":6983,"n":"באבד, שמואל","f":"יעקב באב\"ד","b":"נגיד וקצין-תק\"מ"},{"i":6984,"n":"באבד, שמואל ממיקוליטשין","f":"משה ממיקוליניץ","b":"רב במיקוליטשין-תרסד. בנו ר יעקב עלה לירושלים והיה בעלים של מלון באב\"ד. (??? נכדו אברהם ארנן - מייסד סיירת מטכ\"ל)."},{"i":6985,"n":"באבד, שמואל מסנדובה-וישנא","f":"אריה ליבוש","k":"בעל בכורי ישראל","bt":"תרס","dt":"תשג","b":"רב בסנדובה-וישניה לצד אביו הראב\"ד. חתן ר בצלאל גוטסמן מיריטשוב, וחתן ר דובר שטיינברג מרישא בנו של \"המחזה אברהם\". חיבר \"בכורי ישראל\" ונספח לקובץ \"משכנות יעקב\" - דרוהוביטש-בילגוריי תרצב. פרסם מאמרים ב\"עטרת תפארת\" - פודוולוטשיסק-בילגוריי תרצא, \"תצא תורה\" - קריניצה תרצא."},{"i":6986,"n":"באבד, שמואל מפרמישלא","f":"משה","bt":"תרלח","dt":"תשב","b":"חתן ר יעקב יצחק תאומים. מיסד הישיבה בפשמישל ויו\"ר הקהלה."},{"i":6987,"n":"באבד, שמואל משטמפן","f":"נתן מן אורהולץ משטמפ","b":"חתם בפנקס קהלת שטמפן-תקמח. בנו - נתן (על שם אביו - רבה של שטמפן)."},{"i":6988,"n":"באבד, שמחה מאוסציא","f":"משה","bt":"תריז","dt":"תרעז","b":"אב\"ד אוסציא, טרמבובלה-תרסח על מקום אביו."},{"i":6989,"n":"באבד, שמחה מטרמבובלה","f":"יעקב שמואל ממיקולינץ","dt":"תרלז","b":"רב בטרמבובלה על מקום אביו."},{"i":6990,"n":"באבד, שמעון מיאנוב","f":"יוסף - מנחת חינוך","bt":"תקצט (ולא תריט)","dt":"תרסט","b":"כתב הקדמה והערות לספר אביו. רב בטרנופול-תרלה על מקום אביו (והיה שם מחלוקת עם ר יחיאל רפפורט). בנו ר יהושע השל כיהן אחריו."},{"i":6991,"n":"באבד, שמעון מיאנוב","f":"משה","bt":"תריט","dt":"תרצה","dp":"ברזאן","b":"חתן המהרש\"ם מברעזן. אב\"ד יאנוב-תרסט, בוזנוב-תרסט, ברזאן(=ברעזן) על מקום חותנו."},{"i":6992,"n":"באג'ילאר, יוסף ממצרים","b":"גביר ומקובל מחכמי מצרים-שמ, החזיק ישיבת האר\"י על חשבונו."},{"i":6993,"n":"באהמאן, משה אהרן","b":"פרסם מאמרים ב\"הלפיד\" - וארשא תרצז."},{"i":6994,"n":"באהר, יצחק מצפת","b":"נכד ר דוד לייקיס. תלמיד הרידב\"ז בצפת. שו\"ב בצפת, היגר לקנדה והיה שם שו\"ב."},{"i":6995,"n":"באהרער, ז'","b":"פרסם מאמרים ב\"המגיד\" - סטמר תרצט."},{"i":6996,"n":"באזאיו, דוד מגרוזיה","f":"מנחם","bt":"תרמב","b":"תלמיד ישיבת סלוצק. רב (גם רב מטעם) באוני-פלך קוטאיס בגרוזיה-תרסג. נזכר בזכרונות ר נחום שמריה שושנקין מבאטום - המספר על מחלוקת ביניהם בעניני חנוך."},{"i":6997,"n":"באזארג'יק = טאטאר באזארג'יק","b":"עיר ליד פיליפופולי."},{"i":6998,"n":"באזלו, דוד משלוניקי","b":"מחכמי שלוניקי-שנות ה-ת'."},{"i":6999,"n":"באזלון, וידאל מאיטליה","bt":"רן - בערך","bp":"סיציליה","b":"רופא באיטליה, לאחר גירוש סיציליה-רנב עבר לריגיו די קאלאבר. חיבר ספר ברפואה."},{"i":7000,"n":"באטוס, שלמה זלמן טוביה מסקולסק","b":"אב\"ד סקולסק. פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ."},{"i":7001,"n":"באטשע, יחזקאל (יחיאל?) מלודז","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":7002,"n":"באטשע, יחיאל מלודז","b":"פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח."},{"i":7003,"n":"באטשע, ישראל דוד מלודז","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":7004,"n":"באיי, אפרים שלמה מפוניביז","f":"טוביה מטירקשלי","b":"חתן ר פנחס דוברוביץ. גביר מחכמי פוניביז."},{"i":7005,"n":"באיי, טוביה מטירקשלי","f":"משה","bt":"תרו","b":"נכד ר שמואל-מו\"ץ בטלז. חתן ר אריה לוין מטלז. תלמיד ר חיים יהודה ממיר, ר אביגדות מרגליות מטלז. רב בציטיואן-תרלט, טירקשלי-פלך קובנא. נסמך מאת: ר יוסף רוזין-הרוגצובר, ר אלכסנדר משה לפידות מראסיין. בניו: ר משה, ר אפרים שלמה-גביר בפוניבז, ר מרדכי צבי מליבאוי. חתניו: ר אשר יחזקאל רובינשטין, ר יצחק יהודה מיכלסון מוילנא."},{"i":7006,"n":"באיי, מרדכי צבי מליבאוי","f":"טוביה מטירקשלי","b":"גביר מחכמי ליבאוי. חתן הגביר ר נפתלי ז\"ק."},{"i":7007,"n":"באיי, משה","f":"טוביה מטירקשלי","b":"חתן ר יהושע בן ר מרדכי פישל מבינישקי. בנו - ר טוביה מטירקשלי."},{"i":7008,"n":"באייא, יחיא מתאפילאלת-מרוקו","b":"מחכמי תאפילאלת, חתם-תקסא עם רבני סאלי ופאס."},{"i":7009,"n":"באייונה, מואיז משלוניקי","b":"רופא בשלוניקי-תרס."},{"i":7010,"n":"באייונה, משה אהרן משלוניקי","b":"מנצח באגודת הפייטנים \"נותן זמירות\" בשלוניקי-תרפו."},{"i":7011,"n":"באישה אברהם מירושלים","f":"שלמה","bp":"ירושלים","b":"הוציא לאור באמשטרדם \"גפן יחידית\" לר זאב בן יודה ליב מרוזינוי, ושם גם שירים ממנו"},{"i":7012,"n":"באך (בוכנר), שמשון מאוסטרהא","f":"יצחק","dt":"שצו - יא תמוז","dp":"אוסטרהא","b":"רב בלבוב, אוסטרהא על מקום המהרש\"א. בנו - ר צבי הירש בוכנר מקראטשין. מצאצאיו ר אליהו בן יעקב מלודמיר מו\"ל \"מנחת כהן\"."},{"i":7013,"n":"באך, אברהם אביש חיים מקולשיץ","bt":"תרי","bp":"טרנוב","dt":"תרצד","dp":"פריסטיק","b":"תלמיד ר ישראל רפפורט מטרנוב. רב בקולשיץ-תרלב (מעל 60 שנה)."},{"i":7014,"n":"באך, נפתלי הרץ מזולקוא","b":"מחכמי זולקוא- תשובה אליו ב\"אור המאיר\"-תרפג."},{"i":7015,"n":"באך, רפאל אהרן","k":"בעל הגדה לכל השנה","b":"חיבר הגדה היתולית - הצגה על האפיקומן בחרוזים באידיש - גלאזגוי תרפא."},{"i":7016,"n":"באך-ב\"ך, שמשון מבריסק ולבוב","f":"בנימין בייניש","dt":"תכח - ב טבת","dp":"לבוב","b":"רב בבריסק, ר\"מ ודיין בלבוב (באוצר מופיע דיין בקראקא). לדעת בובר - הוא זה שנזכר ב\"איתן האזרחי\" שהיה מחותנו. (במצבות קודש מובא שאביו היה רב בבריסק - לדעת בובר זו טעות). (באוצר הרבנים תאריך פטירתו - כ טבת תנג)."},{"i":7017,"n":"באלזק, בנימין מניו יורק","k":"בעל תורת האדם","b":"רב בניו יורק. חיבר \"תורת האדם\" וארשא תרע."},{"i":7018,"n":"באליטי, חיים אפרים מטארנאליא","f":"אברהם ממישקולץ","k":"בעל חמודי אפרים","bt":"תרכג או תרלז","bp":"מישקולץ","dt":"תשד - כה סיון","dp":"אושוויץ","b":"תלמיד השב\"ס, ור שמואל גינז-שלזינגר מאבראהאם. חתן ר שמואל מאיר האלדשטין מפרשוב ועבר לשם. רב בטארנאליא. נספה בשואה. חיבר \"אשל חיים\". פרסם מאמרים ב\"מקבציאל\" - גרבה תרצה, \"הנשר\" - טירנוי תרצג-תשד. מחותן עם: ר מאיר טננבוים מפוטנאק, ר חיים פריעד מסנטפעטר."},{"i":7019,"n":"באליי, שבתי","b":"מחדושיו ב\"אור חדש\"."},{"i":7020,"n":"באמפי, דב בער ממינסק","b":"מחכמי מינסק"},{"i":7021,"n":"באנדא, וולף מסערדאוהל","bt":"תקס","dt":"תרכד - כז חשון","dp":"סערדאוהל","b":"תלמיד החת\"ס, ור מרדכי בנט מניקלשבורג. אחיינו של ר שמואל קעלין בעל \"מחצית השקל\". חתן ר צבי כץ מסערדאוהל ועבר לשם. רב בסערדאוהל-תרג, הלישטאבא-תרי."},{"i":7022,"n":"באנון, יחיא מצפרו-מרוקו","f":"מימון","b":"תלמיד ר משה בן חמו. מו\"ץ בצפרו-מרוקו, חתם על פס\"ד-תפז עם ר יוסף עטייה."},{"i":7023,"n":"באנון, מימון מצפרו","b":"מחכמי צפרו, בנו - ר יחיא."},{"i":7024,"n":"באס, אברהם משה","b":"רב שנת-תרע."},{"i":7025,"n":"באסילה, אביעד שר שלום ממנטובה","f":"מנחם שמשון","k":"בעל אמונת חכמים","bt":"תמ","dt":"תקד - טו תשרי","dp":"מנטובה","b":"רב במנטובה, פילוסוף ומקובל. תלמיד אביו, מהר\"י בריאל, הרמ\"ז ומוהרב\"ך. חיבר \"אמונת חכמים\". חיבור בחכמת התכונה בכת\"י. תשובה ממנו ב\"פחד יצחק\", ו\"דברי דוד\". תמך ברמחל - במחלוקת כנגדו."},{"i":7026,"n":"באסילה, אברהם ידידיה מאיטליה","f":"מנחם שמשון","b":"רב במודנא, טורינו, רב ראשי במנטובה-תצ\"ה"},{"i":7027,"n":"באסילה, מנחם שמשון ממנטובה","f":"שלמה","bp":"מנטובה","dt":"תנד - כב תשרי","b":"רב במנטובה-תכא בזמן הרמ\"ז, גאזולו, אליסנדריא דילה פאניה. חתם על החרם נגד הצחוק. עסק באסטרונומיה ובלוח העברי, וכן בנו ר אביעד שר שלום ונכדו ר רפאל חיים. תשובות ממנו בשו\"ת הרמ\"ז ועוד. הספידו הרב\"ך ב\"גבול בנימין\"."},{"i":7028,"n":"באסילה, משה מלארוקה פיזרו","f":"מרדכי צרפתי","dt":"שמד","dp":"צפת או קפריסין","b":"בן אחותו של ר משה באסולה מאנקונה-תלמיד הארי, רב ומקובל בפיזארו, אנקונה ושם עמד בראש ישיבה, עבר לקפריסין. עלה לצפת-שמב?. תלמידו ר עמנואל מבנוינטו בעל \"לוית חן\". בין המקבלים פניו בצפת היה ר משה קורדובירו - שהיה אז בחור. נזכר בין תלמידי הארי, הוציא לאור \"אור נערב\" לר משה קורדובירו. תלמידו - ר יהודה אריה מודנא מזכירו בספרו \"מדבר יהודה\"."},{"i":7029,"n":"באסילה, משה צרפתי אנקונה","f":"מרדכי","bt":"רמ","bp":"פיזרו","dt":"שך","dp":"צפת או ירושלים","b":"ממגורשי ספרד, רב בפיזרו, ואחר כך באנקונה-שט שם עמד בראש ישיבה, עלה לצפת. (כנראה עלה פעם אחת בצעירותו וחזר לאיטליה). בשנת שטז חתם על כתב מחאת רבני אנקונה כנגד החרם שארגנה דונה גרציה נשיא בתמיכת רבני קושטא על אנקונה. תמך בתלמידו ר עמנואל בר יקותיאל מבנונטו שביקש להדפיס את ספר הזהר. עלה לצפת ונמנה על תלמידי האר\"י. לפי רוזניס התישב בירושלים."},{"i":7030,"n":"באסילה, עזריאל מאיטליה","f":"משה","b":"מחכמי איטליה בזמן ר שמואל יהודה קצנלבויגן. אביו עלה לצפת בזמן הרמ\"ק."},{"i":7031,"n":"באסילה, רפאל חיים ממנטובה","f":"אביעד שר שלום","bp":"מנטובה","dt":"תקלו","dp":"מנטובה","b":"מחכמי מנטובה, מלמד משורר, ומגיה ספרים."},{"i":7032,"n":"באסילה, שלמה מאיטליה","f":"שמשון","b":"רב במנטובה - במאה ה-16. היה מעורב בפרשת הגט - תמרי וינטורוצו. תשובה ממנו-שלג ממנטובה. בנו - ר רפאל חיים באזילאה."},{"i":7033,"n":"באסערס, ברוך מבארדיזן","b":"אב\"ד בארדיזן-תרפט."},{"i":7034,"n":"באער, ישראל אברהם","b":"חתן ר נתן נטע דאנר מקאלביעל. לתולדותיו ב\"מים רבים\" לר יחיאל מיכל מזלוטשוב - בהוצאת חותנו."},{"i":7035,"n":"באקאופן, שמעון מרודניץ ופרג","f":"יעקב ריישר","k":"בעל סולת למנחה","dt":"תעד - כ אלול","b":"רב ברודניץ,פפלאנץ,דיין ודרשן בפרג"},{"i":7036,"n":"באקון, משה מרזניץ","dt":"תשב - יד אלול","b":"רב ברזניץ"},{"i":7037,"n":"באקי, מאיר מאיטליה","f":"שמשון - א","b":"רב באיטליה-תפב. חברו של ר גבריאל פונטרימולי מטורינו - למדו יחד אצל ר שמשון באקי-אביו של ר מאיר."},{"i":7038,"n":"באקי, רפאל פנחס מגינואה","f":"ש\"א","b":"רב באיטליה-תקצח."},{"i":7039,"n":"באקי, שמשון מאיטליה א","k":"בעל רפואה למכה","bt":"ת","dt":"תנא - יא סיון","b":"רב ומקובל בקסאלי=קזאלה מונפיראטו - איטליה. היה בקשרים עם חכמי דורו ובהם הרמ\"ז ונזכר באגרות הרמ\"ז. מתשובותיו ב\"פחד יצחק\", שו\"ת הרב\"ך ועוד. חיבר גם ספר הכוונות לאר\"י עם תפלות על דרך הקבלה בכת\"י. נספד ע\"י הרמ\"ך."},{"i":7040,"n":"באקי, שמשון מאיטליה ב","bt":"תנג","b":"נכד ר שמשון הראשון. רב בקסאלי-איטליה, והחיד\"א התארח אצלו-תקלח והזכירו ב\"מעגל טוב\". דודו של ר יצחק רפאל פינצי מפדובה."},{"i":7041,"n":"באקי, שמשון מאיטליה וצפת","bp":"איטליה","b":"מחכמי איטליה, עלה לצפת-שמב והיה מקובל מחכמי צפת, תלמיד ר יוסף ן טבול תלמיד האר\"י, עבר לירושלים-שמד והיה בקשר עם ר חיים ויטאל, שלח מירושלים לאיטליה חיבור של ר חיים ויטאל בשם \"סדר האצילות בקיצור מופלג\". כיהן כראש ישיבה בירושלים."},{"i":7042,"n":"באקלייטשיק, דוד אריה ליב מברעז","k":"בעל דברי דוד","b":"רב בברזנה(=בערעזנע)-פלך צערניגוב-תרל."},{"i":7043,"n":"באקלייטשיק, זוסמן בן ציון מליו","f":"דוד אריה מבערעזנע","bt":"תרלב","b":"רב בליוביטש-תרנד."},{"i":7044,"n":"באר שבע - ישיבה בירושלים","b":"ישיבה לעדת הכורדים בירושלים-נוסדה אחרי תשא בידי ר חביב בן שבתי עלואן."},{"i":7045,"n":"באר, גדליה","f":"משה","b":"שו\"ת ממנו ב\"באר עשק\"."},{"i":7046,"n":"באר, משה שבתי מאיטליה וירושלים","f":"מנחם מנדל חיים","k":"בעל באר עשק","b":"מחכמי פוסאמברונו איטליה, תלמיד ר יצחק ברכיה מפאנו הוא חתנו של הרמ\"ע מפאנו, וכן אצל ר זכריה ממודנא בעל \"מעבר יבוק\", עלה לארץ ישראל. בשנת תלג בשליחות באיטליה מטעם שלש הערים הקדושות. חיבר \"באר עשק\" ונציה תלד, ועוד. נפטר בדרך שליחותו. היה מחלוקת עליו מר בנימין הכהן שאמר לתלמידו ר יוסף אירגס שאין ראוי לסמוך על ה\"באר עשק\"."},{"i":7047,"n":"באראז, יחיאל מיכל","f":"יחזקאל","bt":"תרמג","b":"מצאצאי ר פסח מזוויהל, ר איזיק מגיד מהאשט, ר אברהם המלאך ור שלמה מקרלין. רב בהורדניצה-ווהלין-תרסה. נסמך מאת: ר שלמה מרדכי מברעזן."},{"i":7048,"n":"באראזה, יצחק משלוניקי","dt":"שפה - כח אדר","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":7049,"n":"באראכת, אברהם מירושלים","b":"מחכמי ישיבת \"גדולת מרדכי\", אולי הוא (או נכדו) נזכר בשטר חזקה משנת תקצב, שמכר חזקת חצר לר נתן נטע בן מנחם מנדל האשכנזי. אולי הוא ר אברהם בראשית הספרדי המוזכר בכמה שטרות מהתקופה."},{"i":7050,"n":"באראני, יוסף מקצ'קאמאט","b":"רב בקהילה הניאולוגית בקאצ'קאמאט-1891. חיבר מסות על יהדות הונגריה."},{"i":7051,"n":"בארב, יצחק מירוסלב","k":"בעל ממשל משלים","bt":"תקפז","bp":"ירוסלב","dt":"תרסג","b":"מחכמי ירוסלב. חיבר \"ממשל משלים\" למברג תרכא, ועוד."},{"i":7052,"n":"בארב, מרדכי יעקב","k":"ר אלתר באריד","dt":"תרנח","b":"רב בבאר-תרט ובנו ר אברהם יהושע בארב-טרלו על מקומו אחריו, בעלז-בסרביה-תרכח, עלה לארץ-תרן."},{"i":7053,"n":"בארב-טארלו, אברהם יהושע השל","f":"מרדכי יעקב ברב","bt":"תרל","b":"רב בבאר-פודוליה-תרנה על מקום אביו (שעבר לבעלז). בניו: ר יחיאל ור ישראל. חתניו: ר ירוחם פישל זיידמן מקמניץ, ר דובער גולדנברג מטרנופול."},{"i":7054,"n":"בארב-טארלו, ישראל מויניצא","f":"אברהם יהושע השל מבאר","bt":"תרלה","b":"נכד ר מרדכי יעקב המכונה-אלתר באריד מבלז. חתן ר דובער למברסקי מויניצא. רב בויניצא. נסמך מאת: ר אלתר מקונסטנטין, ור מרדכי לרנר ממייקוביץ."},{"i":7055,"n":"בארבאדו, אליהו הרופא משלוניקי","dp":"שלוניקי","b":"רופא בשלוניקי-תי. כנראה חתן ר בנימין נסים משלוניקי."},{"i":7056,"n":"בארג, אליהו ממזריטש","f":"דוד","dt":"תרכו","dp":"ירושלים","b":"אבד סמיאטיץ(=סימיאטיץ), עלה לירושלים, מוזכר בספר \"אבל כבד\" (ירושלים תרלח)."},{"i":7057,"n":"בארו, ישעיה","f":"בן ציון","k":"בעל שיבת ציון","bt":"תרכז","bp":"נובוגרד יילינסק (רוסיה)","dt":"תרצז","dp":"תל אביב","b":"רב בעיר מולדתו, עלה לירושלים בשנת תרפא. חיבר \"שיבת ציון\" תל אביב תרצג, ועוד."},{"i":7058,"n":"בארוויק, אברהם שלמה מארה\"ב","f":"יעקב","bt":"תרלז","bp":"עזור-פלך גרודנא","b":"תלמיד ישיבות ביאליסטוק, סטוצין, סלובודקה אצל הרבנים ר צבי הירש שור בעל \"צבי וחמיד\" ר מנדל אוסטרובסקי בעל \"צמח מנחם\", ר ברוך בר ליבוביץ. נסמך מאת: ר אברהם יצחק הכהן קוק, ר מנחם סטוצינר, ר שמואל יוסף מוילקי. חתן ר משה גולד, ובזיוו\"ש חתן גיסו ר אברהם יצחק גולד. רב בעלמיירא-ניו יורק-תרעג, ברקטון-מסצוסס-תרעט, עלה לארץ-תרצה ויסד כולל לאברכים \"אהל תורה בית דוד\" - יחד עם ר שמואל יצחק הילמן, חזר לארה\"ב-תרצח וכיהן כרב בביהכ\"נ \"תקות ישראל\" בבוסטון. חבר אגודת הרבנים באמריקה, והסתדרות המזרחי."},{"i":7059,"n":"בארוך, יהושע איזיק מקובנא","b":"פרסם מאמרים ב\"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד."},{"i":7060,"n":"בארון אריה ליב","bt":"1912","dt":"ה'תשעא 2011","bk":[["ברכת ראובן",""],["ישמח חיים",""],["ישרי לב",""],["משמחי לב",""],["נצח יעקב",""],["נתיבות לב",""]]},{"i":7061,"n":"בארון, אליהו מצידון","b":"רב ראשי בצידון(לבנון)"},{"i":7062,"n":"בארון, אליעזר ירוחם מקראקא","f":"ישראל יצחק מרדושיץ","k":"אדמור מצאנז-קראקא","bt":"תקץ","dt":"תרנב-מה -ג ניסן","b":"בנו של האדמור מרדושיץ. חתן ה\"דברי חיים\" ובזיוו\"ש חתן ר ישכר דב מבריגל, ובזיוו\"ש חתן ר ניסן משינאווא. ישב אצל ה\"דברי חיים\" בצאנז עד פטירתו-תרלו. אחיו ר יעקב דוד היה האדמור מרדושיץ. אדמור בקראקא לחסידי צאנז-תרלו אחר פטירת ה\"דברי חיים\". הו\"ל \"דודאים בשדה\" לזקנו-אבי אמו - ר יהודה ליב הורביץ."},{"i":7063,"n":"בארון, אשר ליב מארה\"ב","b":"רב בוואבאלניק, בוסטון-ארה\"ב-תרע. חתנו - ר שלמה גרינברג בן דוד מקוברין."},{"i":7064,"n":"בארון, אשר קלמן (קלונימוס)","bt":"תרנא","dt":"תשא","b":"חתן ר אריה ליב רובין מוילקומיר. ר\"מ ומשפיע רוחני בישיבת פוניבז'. נספה בשואה עם משפחתו."},{"i":7065,"n":"בארון, חיים יהודה מאיקלוד","f":"ישראל מנחם מברזויץ","bt":"תרנו","dt":"תשד","dp":"אושוויץ","b":"תלמיד דודו-אחי אמו - ר משה גרינולד בעל \"ערוגת הבושם\". חתן ר יצחק יחיאל פנט האדמור מדעש. רב באיקלוד-תרפה והקים ישיבה. גיסו של האדמו\"ר מפאפא בעל \"ויגד יעקב\". נספה בשואה עם משפחתו ובני קהלתו."},{"i":7066,"n":"בארון, יונה מיאסלו","f":"מנחם מנדל מיאסלו","bt":"תרנא","dt":"תשב","b":"חתן דוד זקנו ר אלעזר רוזנפלד מאושפיצין. רב ביאסלו. נספה בשואה."},{"i":7067,"n":"בארון, יעקב דוד מרדושיץ","f":"ישראל יצחק","k":"אדמור מרדושיץ","b":"חתן ר בעריש וינברג-חתן ר ישעיה משפדבורז, ובזיוו\"ש חתן דודו ר יצחק מרדושיץ. אדמור ברדושיץ."},{"i":7068,"n":"בארון, ישראל יצחק מרדושיץ","f":"ישכר דב בער מרדושיץ","k":"אדמור מרדושיץ","bt":"תקע","dt":"תריח - כ כסלו","b":"חתן ר יהודה ליב הלוי הורביץ בן ר ראובן-דודאים בשדה. תלמיד ר חיים מאיר יחיאל ממוגלניצא ועוד צדיקים. נחשב לבעל מופת כאביו לפניו."},{"i":7069,"n":"בארון, ליב מארה\"ב","b":"פרסם מאמרים ב\"התבונה\" - נ\"י תשז - קובץ תלמידי ישיבת מיר."},{"i":7070,"n":"בארון, מאיר משילובצא","f":"ישכר דב בער מרדושיץ","dp":"לודז"},{"i":7071,"n":"בארון, מנחם מנדל מיאסלו","f":"אליעזר ירוחם מקראקא","k":"הו\"ל דודאים בשדה","bt":"תרלד","bp":"צאנז","dt":"תשב","b":"נכד ה\"דברי חיים\" מצאנז. חתן ר אברהם יהושע רובין אב\"ד יאסלו. רב ביאסלו. נספה בשואה. הו\"ל \"דודאים בשדה\" לזקנו ר ישראל יצחק בארון האדמור מרדושיץ. בנו ר יונה מיאסלו."},{"i":7072,"n":"בארון, שלמה מירושלים","b":"מחכמי ירושלים-שנות ה-ת'."},{"i":7073,"n":"בארון, שמואל מויליצקה","f":"משה","bt":"תרעט","bp":"ויליצקה","dt":"תש..","b":"תלמיד ר פנחס ליבוש פרנקל-תאומים בויליצקה. ר\"מ בישיבת בובוב בויליצקה. נספה בשואה."},{"i":7074,"n":"בארטה, י. מברלין","b":"ר\"מ בביהמ\"ד לרבנים בברלין. פרסם מאמרים ב\"בית ועד לחכמים\" - לונדון תרסב."},{"i":7075,"n":"בארי ן, אברהם משלוניקי","dt":"שיט - ה אב","dp":"שלוניקי","b":"מחכמי שלוניקי"},{"i":7076,"n":"בארי, אשר דוד מלובלין","b":"פרסם מאמרים ב\"העץ\" - לובלין תרצג."},{"i":7077,"n":"בארי, ישראל הלוי","dt":"תשלג","b":"רב בנס ציונה"},{"i":7078,"n":"באריוס, דניאל הלוי מספרד ואמשט","f":"שמעון","k":"בעל דברי העם היהודי","bp":"מונטילה-ליד קורדובה","dt":"תמז-ח","b":"משורר וסופר. מאנוסי ספרד, הגיע לאיטליה אל דודו ר יצחק הכהן דים וחזר ליהדות, עבר לסורינום-תך - בהזמנת ממשלת הולנד, חזר לאירופה והתישב בבריסל-תכד. חיבר ספר לתולדות עם ישראל - ובהם קורות היהודים בספרד ובאמשטרדם."},{"i":7079,"n":"בארכוביץ, חיים יהודה מפינטשוב","b":"פרסם מאמרים ב\"כרם בית שמואל\" - פיעטרקוב תרצב - כתב עת תלמידי ישיבת אלכסנדר."},{"i":7080,"n":"בארער, זלמן מוליקסברי","k":"בעל דברי מהר\"ז","b":"תלמיד בעל \"כוכב יעקב\" מהרימלוב. רב בוילקסברי-פנסילבניה. חיבר \"דברי מהר\"ז\" וינה תרפז."},{"i":7081,"n":"בארקר, בנימין מאנגליה","b":"מסיונר אנגלי באזמיר-תקפח, וכתב על בני כת ה\"דונמה\"."},{"i":7082,"n":"בארקר, יוסף מטוקאת","b":"רב בטוקאת-שנות ה-ת', ולצדו - ר יעקב ערב, ור יהודה הכהן מאנגורה."},{"i":7083,"n":"באשאוו, יהושע מגריווא","bp":"פלך מוהילוב","b":"רב בגריווא-תרס בערך."},{"i":7084,"n":"באשאן - משפחה","b":"משפחה בעיר חדש-הונגריה."},{"i":7085,"n":"באשאן, ליב מעיר חדש","b":"גביר בעיר חדש. חתנו - ר אברהם וינר מעיר חדש."},{"i":7086,"n":"באשיסטא, אליעזר יהודה מבנדין","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":7087,"n":"באתם, מרדכי מתבץ","f":"אברהם","b":"רב בתיביץ(=טיווה)-במוריאה-יון בדור שלאחר הגירוש."},{"i":7088,"n":"בבא, משה","b":"מחכמי ירושלים, בין הסובלים מפרעות אבן פארוך בשנת שפה."},{"i":7089,"n":"בבוהאן, אברהם מדמשק","f":"יוסף","b":"מחכמי המזרח-קן ופייטן, פיוטים ממנו במחזור דמשק - כת\"י."},{"i":7090,"n":"בבלי, הלל מליטא וניו יורק","f":"זלמן רשגולין","k":"בעל נגינות ארץ","bt":"1893","bp":"פילווישוק-ליטא","dt":"1961","dp":"ניו יורק - ירושלים","b":"תלמיד ישיבת קובנא. היגר לארה\"ב-1920 וכיהן כפרופ' לספרות עברית בביהמ\"ד לרבנים בנ\"י. חיבר \"שירים לרחלה, ועוד. תרגם וערך ספרים נוספים."},{"i":7091,"n":"בבלי, סעדיה מתימן","f":"יעבץ","dt":"מז (1267)","b":"רב בעדן בתחילת המאה ה-13. תלמידו ר יחיא בן סעדיה ן אלחואס חיבר הלכות שחיטה בצורת שות."},{"i":7092,"n":"בברוסא, יצחק (טולדנו)"},{"i":7093,"n":"בג'איו, אברהם נסים","b":"חתום בשנת תקמב (1782) עם רבני חברון על אגרת שליחות ר אברהם ישראל זאבי, ובשנת תקמח על אגרת שליחות ר שמואל הכהן, בשנת תקצט על סדרי הכוללות בעיר. חיבר חדושים על מסכתות שונות בכתי (ירושלים מוסיוף 56 ס' 22881)."},{"i":7094,"n":"בג'איו, חיים מחברון","f":"פריסיאדו","b":"מנהגי הכוללות בחברון-תרפט."},{"i":7095,"n":"בג'איו, חיים רחמים מחברון","b":"מחכמי ירושלים, חברון. בשנת תקד חתם על אגרת שליחות ר אברהם גדיליה. חתם על קבלת כספים מר יהודה אסיאו, מתלמידיו ר חיים יצחק קאריגל. בשליחות באמריקה-תקיח והיה בקורסאו ונרשם בפנקס הקהל שם. בשנת תקכג בשליחות עם ר יצחק זאבי לצפון אפריקה ואיטליה, ומשם המשיך לבד באירופה. בשנת תקלד הסכים בליוורנו על \"נהר שלום\" לר שלום וינטורה, ובשנת תקלה חתם על מכתב בונציה (שהה בשליחותו למעלה מ-10 שנים)."},{"i":7096,"n":"בג'איו, יונה או יהושע מטבריה","b":"ממשפחה מחברון, רב בטבריה אצל ר יצחק אבולעפיה-שנות ה-תק'. בשליחות באיטליה עם ר אברהם רוביו."},{"i":7097,"n":"בג'איו, נסים","f":"ראה באג'יו אברהם נסי"},{"i":7098,"n":"בג'איו, פנחס רפאל מרדכי מחברון","b":"מחכמי חברון, בשנת תקד חתם על כתב שליחות ר אברהם גדליה, ועל קבלת כספים מר יהודה אסיאו-תקי, ועל כתבים רבים בשנים תקד - תקלד."},{"i":7099,"n":"בג'איו, שלמה מחברון","b":"רב בחברון-תקמח, וחתם אז על כתב שליחות ר שמואל הכהן ועל אגרת בקשת עזרה של הקהלה."},{"i":7100,"n":"בג'איי, אליהו מאלגיר","bt":"תקל - בערך","dt":"תר - בערך","b":"חתן ר יעקב מרעלי, רב באלגיר. נזכר ברשימת הנפטרים של קהלת אלגיר."},{"i":7101,"n":"בגוכוואל, אברהם יעקב מקראקא","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":7102,"n":"בגוכוואל, אלתר חנינא מקראקא","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":7103,"n":"בגון, יצחק מז'ידיק","k":"בעל שדה יצחק","bt":"תרנח","dt":"תשג","b":"רב בזידיק-תרפח על מקום ר אברהם זאב הלר, רבה האחרון של ראדוילישוק על מקום ר יוחנן זרחי-זופוביץ. נספה בשואה."},{"i":7104,"n":"בגין, אברהם מואגר-ליד שאוולי","f":"צבי","b":"רב בואגר-תרסג."},{"i":7105,"n":"בגין, חיים מביחוב","f":"משה גרשון","b":"רב בביחאוו-פלך מוהילוב-תרלב, נאוואהארד-סיווערסק-פלך צרניגוב."},{"i":7106,"n":"בגין, יצחק","b":"פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":7107,"n":"בגמירסקי, שמואל פסח","dt":"תרצט - כג סיון","b":"רב בברונקס"},{"i":7108,"n":"בג'ראנו - משפחה","dt":"תקפז - ח ניסן","b":"דיין בירושלים"},{"i":7109,"n":"בג'ראנו, אברהם מבלגרד","bt":"תרב","bp":"זהרא-תורכיה","b":"רב בבלגרד-תרס."},{"i":7110,"n":"בג'ראנו, בכור חיים מאדרינופול","f":"משה","k":"בעל ארשת החיים","bt":"תרטז","bp":"אסקי זגורה או קושטא","dt":"תרצא - כ אב","b":"תלמיד ר חיים נסים אלקלעי מפיליפופולי. ראש קהילה ברוסג'וק-תרמ, מנהל ביה\"ס הספרדים בבוקרשט, רבה של אדרינופול-תרסח, רב ראשי בקושטא-תרפב. חיבר \"ארשת החיים\" דרושים."},{"i":7111,"n":"בדהב, יצחק מירושלים","f":"מיכאל","k":"בעל פרדס התורה","bt":"תרכ","bp":"ירושלים","dt":"תשז - כג סיון","b":"מחכמי ירושלים."},{"i":7112,"n":"בדהב, מיכאל מירושלים","f":"רפאל","bt":"תקעד","bp":"ירושלים","dt":"תרלח - כו אד\"ב","b":"מחכמי ירושלים, חתן ר יצחק קובו - ה\"ראשון לציון\". בשליחות בצפון אפריקה-תרה, תרכד, באדריאנופול-תרטז. חיבר דרושים, פנקס שליחות (אצל בניהו) והשאיר כתבים שלא נדפסו."},{"i":7113,"n":"בדוך, יצחק מאלגיר","bt":"תף - בערך","dt":"תקן - בערך","b":"רב ומשורר באלגיר. מפיוטיו בספרי חכמי אלגיר - ובהם \"שבחי אלקים\" - ווהראן תרטז."},{"i":7114,"n":"בדוך, מסעוד מאלגיר","bt":"תקפב","bp":"ווהראן","b":"רב ברוליזאן-אלגיר-תרך."},{"i":7115,"n":"בדוק, מסעוד מצפת","k":"בעל מרפא לנפש","bt":"תקצח","bp":"צפת","dt":"תרנט","dp":"אלכסנדריה","b":"מחכמי טבריה-תרכז. רב באלכסנדריה-תרמט."},{"i":7116,"n":"בדיחי, אברהם","f":"יהודה","bt":"תרב-ט","dt":"תרצט","b":"דרשן, מגדולי רבני צנעא-תימן"},{"i":7117,"n":"בדיחי, אברהם יוסף מתימן","k":"מזקני רבני תימן","bt":"תקצט","dt":"תרצט","b":"רב בצנעא"},{"i":7118,"n":"בדיחי, שלמה מיפו","k":"בעל עולת שלמה","bp":"צנעא","dt":"תרסה - אחרי","dp":"צנעא","b":"בנו של ראש הישיבה בצנעא."},{"i":7119,"n":"בדר, גרשון","b":"פרסם מאמרים ב\"היהודי\" - נ\"י תרצו."},{"i":7120,"n":"בדריקובצקי, צבי מרושקאן","bt":"תרכ","b":"רב בקיטהיירד(=קיטייהראד)-פודוליה-תרמט, רושקן(=רושקאן)-בסרביה-תרנד."},{"i":7121,"n":"בדרש, מאיר משלוניקי","dt":"שצב-ט - ב סיון","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":7122,"n":"בדרשי, אברהם מפרובנס","f":"יצחק","k":"בעל חותם תכנית","b":"תלמיד ר יוסף האיזובי בן חנן מפירפיניאן. פייטן ומדקדק מחכמי פרובנס-ן'. חיבר שיר \"בקשת הלמד\", \"לך אלי בגלגלי זבולי (בספר \"בחינת עולם\" - לבנו?), ועוד. ב\"משכיות כסף\" מביא התכתבות שלו עם ר טודרוס הלוי. כתב אגרות לר טודרוס הלוי ובהם משיריו. חיבר \"חותם תכנית\". (יש אומרים שהוא אביו של ר ידעיה הפניני הבדרשי)."},{"i":7123,"n":"בדרשי, אישטרוק משלוניקי","dt":"שמה - כג ניסן","dp":"שלוניקי","b":"גביר מחכמי שלוניקי."},{"i":7124,"n":"בדרשי, בכור חננאל","b":"פוסק, מחכמי שאלוניקי"},{"i":7125,"n":"בדרשי, חננאל הבחור (בכור) משלו","dt":"תרלט","dp":"שלוניקי","b":"פוסק מחכמי שלוניקי."},{"i":7126,"n":"בדרשי, חננאל משלוניקי","f":"יהושע","dt":"תקס","dp":"שלוניקי","b":"מחכמי שלוניקי. הו\"ל ספר זקנו \"הרי בשמים\", ו\"ערוגת הבושם\"-תקנג לאביו עם תוספות משלו. הניח חדושים בכת\"י."},{"i":7127,"n":"בדרשי, ידעיה הפניני מפרובנס","f":"אברהם הבדרשי","k":"בעל בחינות עולם","bt":"ל","bp":"פרובנס","dt":"ק","b":"מכונה בשם - אנבוניטו אברם. מגדולי התורה והחכמה, פייטן, בלשן, רופא, פילוסוף, רב במונפליה(=מונטפלייר)-פרובנס אחר גירוש צרפת ברח כנראה לברצלונה. חלק על הרשב\"א בעניני פילוסופיה ותמך ברמב\"ם, חיבר \"בחינת עולם\" ספר מוסר, ו\"מדבר קדמות\" פירוש להקדמת הרמב\"ם."},{"i":7128,"n":"בדרשי, יהושע משלוניקי","f":"יצחק","k":"בעל ערוגת הבושם","dt":"תקכב - ג אב","dp":"שלוניקי","b":"רב הכולל בשלוניקי. סייע בהוצאת \"זהורי חמה\"-תצח. בנו ר חננאל הו\"ל את ספרו \"ערוגת הבושם\"."},{"i":7129,"n":"בדרשי, יוסף משלוניקי","dt":"תרלט","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":7130,"n":"בדרשי, יוסף משלוניקי - א","b":"תלמיד ר מרדכי קלעי. מחכמי שלוניקי-שנות ה-ת'."},{"i":7131,"n":"בדרשי, יצחק משלוניקי","k":"בעל הרי בשמים","dt":"תקא - כ אייר","dp":"שלוניקי","b":"רב הגדול בשלוניקי, ור שאול בן שלמה בן דוד על מקומו אחריו. חתם על ההסכמה-תפה, חיבר עם בנו ר יהושע \"הרי בשמים\" שלוניקי תקנג, וערוגת הבושם\"."},{"i":7132,"n":"בדרשי, יצחק משלוניקי - א","dt":"של","b":"רב וראש ישיבה בשלוניקי. חתם על הסכמות הקהל. נספד ע\"י ר משה אלמושנינו."},{"i":7133,"n":"בדרשי, משה משלוניקי","dt":"תקיב","dp":"שלוניקי","b":"מחכמי שלוניקי. חיבר דרשות - בכת\"י."},{"i":7134,"n":"בדרשי, משה משלוניקי","dt":"שצד - ג ניסן","dp":"שלוניקי","b":"מחכמי שלוניקי. חתם על הסכמה-שפג בענין בחירת פרנסים."},{"i":7135,"n":"בדרשי, משה משלוניקי ואישקופיה","b":"מחכמי שלוניקי, רב באישקופיה-שן, בזמן ר אליהו ארבארו."},{"i":7136,"n":"בדרשי, משה משלוניקי וכניא","b":"תלמיד ר דניאל אישטרושא. מחכמי שלוניקי, רב בכניא-שנות ה-ת'."},{"i":7137,"n":"בדרשי-פרופיאט, אברהם","k":"בעל חרב המתהפכת","b":"מדקדק,משורר,מחכמי פרובינצה,נרבונה-שנת ל'"},{"i":7138,"n":"בהגאון, ישכר בער (בונם) מוילנא","f":"תנחום מהורדנא","k":"בעל מעשה רב","bt":"תקלט","bp":"גרודנא","dt":"תרטו - טז אב","dp":"וילנא","b":"חתן הגביר ר יעקב פרץ קלאצקי מוילנא. רב ודיין בוילנא על מקום ר יצחק שמעון הלוי. ממקורבי הגר\"א, וחיבר ספר על מנהגי הגר\"א שראה וחקר בשם \"מעשה רב\" עם חדושים מבנו בשם \"דברי מרדכי\", חיבר גם \"פעולת שכיר\". בנו ר אליהו פרץ מוילנא (שנולד ביום פטירת הגר\"א). אחיו - ר צבי הירש."},{"i":7139,"n":"בהגאון, צבי הירש מהורדנא","f":"תנחום מהורדנא","k":"בעל זרע גד","bp":"גרודנא","dt":"תקצא-ז -יז אייר","dp":"הורדנא","b":"רב בהורדנא, על מקום אביו וזקנו. אחיו - ר ישכר בר בהגאון בעל \"מעשה רב\". בנו - ר נחמן מהורדנא."},{"i":7140,"n":"בהלול מקירואן","f":"יוסף","bt":"ד'תרץ","dt":"ד'תשס","b":"מחכמי צפון אפריקה, ראש קהילת קיירואן. שלח שאלות לגאוני בבל."},{"i":7141,"n":"בהלול, אברהם משלוניקי","b":"מחכמי שלוניקי. מחותן עם ר סעדיה לונגו."},{"i":7142,"n":"בהלול, אלעזר מטבריה","k":"בעל חסדי ה","b":"מחכמי מכנאס, עלה לטבריה עם בנו - ר משה."},{"i":7143,"n":"בהלול, אלעזר ממכנאס","f":"דניאל","k":"בעל מראה עינים","b":"מחכמי מקנאס, חתם על פס\"ד-תץ עם ר שלמה טאפיירו. חיבר \"מראה עינים\"."},{"i":7144,"n":"בהלול, דניאל ממכנאס","f":"יהודה","b":"חתן ר יעקב ן צור-היעב\"ץ. מחכמי מכנאס, חתם שם-תעז. הניח דרושים בכת\"י, העתיק ספר \"ירח יקר\" לר אברהם גלנטי ובו הגהות מאת חותנו היעב\"ץ. בניו: ר שמואל, ר יוסף , ר אלעזר בעל \"מראה עינים\"."},{"i":7145,"n":"בהלול, יוסף ממכנאס","b":"מחכמי מכנאס, וסופר ביה\"ד, חתם-תקצד עם ר יוסף הלוי ן יולי. בנו - ר משה."},{"i":7146,"n":"בהלול, יוסף ממרוקו","b":"מחכמי תאהרת-מרוקו הקדמונים."},{"i":7147,"n":"בהלול, יוסף מפאס","b":"מחכמי פאס, חתם על פס\"ד-תץ עם ר שמואל ה\"ן דוד וחיון."},{"i":7148,"n":"בהלול, משה ממכנאס","f":"אלעזר או יוסף","bt":"תקסט","bp":"מכנאס","dt":"תרמג - ט אד\"א","dp":"טבריה","b":"רב במכנאס, עלה לטבריה-תריד עם אביו, בשליחות במצרים-תרלה. כל ילדיו נפטרו קטנים והתפלל על קבר ר עקיבא ור חייא ונולד בן שקראו עקיבא חייא."},{"i":7149,"n":"בהלול, עקיבא חייא מטבריה","bt":"תרך","bp":"טבריה","dt":"תרצה - כ אלול","dp":"טבריה","b":"מחכמי טבריה, נודע כצדיק וקדוש."},{"i":7150,"n":"בהלול, צאלח מקירואן","b":"רב בקירואן בזמן רבינו חננאל. נזכר בתשובות הגאונים ומכונה \"סנהדרא רבא\" - תואר שניתן מידי גאוני בבל לחכמי שאר המקומות."},{"i":7151,"n":"בהלול, שלמה ממכנאס","b":"מחכמי מכנאס-תקא."},{"i":7152,"n":"בהלול, שמואל ממכנאס","f":"דניאל","b":"מחמכי מכנאס-תצב וחתם אז עם ר מרדכי מלכא."},{"i":7153,"n":"בהלול, שמואל ממצרים","b":"מגדולי רבני מצרים-שנת ש'. נזכר ב\"ליקוט יוסף\" לר יוסף סמברי."},{"i":7154,"n":"בהם, גבריאל מגויטין ודרזניץ","b":"רב בגויטין,דרזניץ"},{"i":7155,"n":"בהמר, יוסף מסלוצק","b":"רב בסלוצק"},{"i":7156,"n":"בהר, זאב מפודהייץ","dt":"תשג","b":"רב בפורדהייץ"},{"i":7157,"n":"בהרב, אברהם הכהן המבורגר ממינס","f":"זכריה מנדל המבורג","dt":"תרך - ב חשון","dp":"מינסק","b":"תלמיד ר חיים מוולוזין. נכד ר אריה ליב-חתנו של ר רפאל הכהן מהמבורג ובנו של ר שמואל הכהן מאמדור. בנו - ר רפאל המבורג."},{"i":7158,"n":"בהרב, אריה ליב מדומברומיל","b":"רב בדומברומיל-תק\"ל"},{"i":7159,"n":"בהרב, חנוך זונדל","b":"פרסם מאמרים ב\"כרם ציון\" - ירושלים תרצה-תשיג."},{"i":7160,"n":"בהרב, יעקב מטישביץ","f":"משה בשקא","b":"רב בטישוויץ-תר\"כ"},{"i":7161,"n":"בהרב, משה אריה ליב אלתר","f":"יונה","k":"בעל דברי משה","dt":"תרלג - ח תמוז","b":"מו\"צ בבאטושן, רב בבאקוי-מולדובה."},{"i":7162,"n":"בהרן, דוד מירושלים","f":"נחום משאדיק","b":"מחכמי ירושלים-תרצט. מחותן עם ר חיים דוד קנטור. בנו - ר נחום נהרג עק\"ה-תרצח."},{"i":7163,"n":"בהרן, נחום מירושלים","b":"דיין בירושלים-תרסח."},{"i":7164,"n":"בהרן, שלמה זלמן הלוי מירושלים","f":"נחום משאדיק","dp":"ירושלים","b":"עלה עם אביו ושני דודיו ר אשר לעמיל ור יעקב יהודה ליב הידועים כ\"האחים הקדושים. לאחר פטירת אביו עמד בראש הישיבה שהקים אביו בביתו, והיה נקרא \"ראש הברזל\", עסק גם בבנין ירושלים והיה מעורב בהקמת שכונת מאה שערים, בית ישראל, בית יעקב ובית חולים שערי צדק."},{"i":7165,"n":"בהתית, יוסף ממכנאס","dt":"תעא - יג ניסן","dp":"מכנאס?","b":"מו\"ץ במכנאס ודיין אצל ר משה טולדנו ומלמד תורה לתלמידיו. חתם על פס\"ד ב\"משפט וצבי\". מתלמידיו - ר משה בירדוגו-המשבי\"ר שהביא מתורתו בספרו."},{"i":7166,"n":"בהתית, יעקב ממכנאס","b":"מחכמי מכנאס, חתם על שטר-תף עם ר אברהם ן חסין."},{"i":7167,"n":"בהתית, ישעיה ממכנאס","b":"רב במכנאס-מרוקו בזמנו של ר חביב טולדנו הראשון."},{"i":7168,"n":"בואינו די מוסקיטא, יוסף","b":"מחכמי המגרב. מוזכר בשיטה לבעל \"נימוקי שמואל\"."},{"i":7169,"n":"בואינו, אפרים הרופא מאמשטרדם","b":"גביר באמשטרדם-תך, הדפיס עם ר יעקב קאסטילו את השו\"ע והמגיה אצלם היה בעל באר הגולה."},{"i":7170,"n":"בואינו, יעקב מסרייבו","b":"מראשי קהלת סרייבו-שנות ה-ת' - אחד משבעת טובי העיר."},{"i":7171,"n":"בואינו, יצחק מירושלים","f":"אברהם","k":"בעל שלחן מלכים","b":"רב בירושלים, בראש בית הדין-תלז, בשנת תלט בשליחות באיטליה. ממתנגדי שבתי צבי וידידו של ר יעקב ששפורטש. חתם עם חכמי ליוורנו ר\"א גנסו ור יהודה אלחדיף בשנת תמה. בספר \"אוהל יעקב\" מביא הסכמה ממנו בפסק דין. חיבר ספר \"שלחן מלכים\" על שו\"ע ובו מנהגי ירושלים וביקש מקרובו ר יצחק יהושע בואינו מליוורנו להדפיסו אולם לא הסתייע, החיד\"א אמר כי אין דבריו הלכה למעשה."},{"i":7172,"n":"בואינו, שם טוב משלוניקי","f":"יצחק הרופא","dt":"שא","b":"רופא בשלוניקי."},{"i":7173,"n":"בואינו, שמואל מצפת","b":"מחכמי צפת, חתם עם ר שלמה אלקבץ-שלא."},{"i":7174,"n":"בוארון, אברהם מטריפולי","bt":"תן","dt":"תקי - בערך","dp":"טריפולי","b":"סופר דווקני בטריפולי. חתם בפנקס בי\"ד טריפולי."},{"i":7175,"n":"בוארון, דוד מתונס","bt":"תרמה","dt":"תשטו","b":"תלמיד ר שלמה דיאנה בעל \"שלמי תודה\", ר שיעוה הכהן בעל \"מעיני הישועה\", וסייע בהדפסת ספריהם, דיין בתונס-תרפג, רב ראשי בתונס-תשו. חותם לפעמים דב\"ב."},{"i":7176,"n":"בוארון, יוסף מבנגזי","bt":"תרי","bp":"טריפולי","dt":"תרף - בערך","dp":"טריפולי","b":"רב ודיין בבנגזי."},{"i":7177,"n":"בוארון, ציון מטריפולי וירושלים","b":"מחכמי טריפולי, עלה לירושלים וכיהן כדיין."},{"i":7178,"n":"בובליל, שמואל מתונס","b":"מחכמי תונס - בשנות התר'. נזכר ב\"פרי קדש\", וב\"חיים וחסד\" לר עוזיאל אלחאייך."},{"i":7179,"n":"בובליק, גדליה מגרודנה וארגנטינ","k":"בעל מן המיצר","bt":"1875","bp":"גרודנא","dt":"1948","b":"תלמיד ישיבות ליטא. ב-1900 ארגן קבוצת יהודים מביאליסטוק שיצאו לארגנטינה כדי לייסד שם מושבה, הגיעו למוזסויל כ-50 משפחות וב-1904 עבר לניו יורק. היה עורך העיתון \"אידישעס טאגעבלאט\". ממיסדי הקונגרס היהודי באמריקה וסגן הנשיא. ביקר בארץ-1920. חיבר ספרים ומאמרים על בעיות היהדות האורטודוכסית בארה\"ב."},{"i":7180,"n":"בובקובסקי, משה מגריבא","b":"רב בגריבה. פרסם מאמרים ב\"בית המדרש החדש\" - גריבה תרפח."},{"i":7181,"n":"בובר שלמה","bt":"1827","dt":"ה'תרסו 1906","bk":[["אגדת אסתר",""],["אנשי שם",""],["בקורת תהיה",""],["ירושלים הבנויה",""],["יריעות שלמה",""],["לקוטים",""],["מדרש אגדה",""],["קריה נשגבה",""]]},{"i":7182,"n":"בובר, אברהם","f":"יוסף צבי","bt":"תרם","dt":"תשג","b":"מחסידי בלז. חתן ר חיים אברהם הלוי וונדר. נספה בשואה."},{"i":7183,"n":"בובר, יוסף צבי מזולקווא","f":"אברהם","k":"בעל ילקוט יוסף","bt":"תרס","dt":"תשלו","b":"היה מראשי המזרחי בלבוב, עלה לתל אביב-תרצה והיה מבני סודו של ר אהרן רוקח מבלז. חיבר \"ילקוט יוסף\" תל אביב תשלו."},{"i":7184,"n":"בובר, מרטין"},{"i":7185,"n":"בובר, שלמה הלוי מלבוב","f":"ישעיהו אברהם","k":"בעל תולדות אליהו","bt":"תקפז","bp":"לבוב","dt":"תרסז","b":"תלמיד חכם ובקי בשפות ומדעים, ומגדולי החוקרים. חיבר \"תולדות אליהו\" לייפציג תרטז, ועוד, מדרש תנחומא-בובר ועוד. פרנס ומראשי הקהילה בלבוב, נפגש עם הקיסר בשליחות קהילת וינה. היה סבו של פרופ' מרטין בובר."},{"i":7186,"n":"בוברובסקי, יעקב","b":"פרסם מאמרים ב\"היכל התורה\" - מיר-נוברדוק תרצה, \"התבונה\" - נ\"י תשז - קובץ תלמידי ישיבת מיר."},{"i":7187,"n":"בוג'אנח, אברהם מטריפולי","f":"בדוסה - דוסא","bt":"תס","dt":"תקל - בערך","dp":"טריפולי","b":"רב וסופר בטריפולי. חתם בפנקס בי\"ד טריפולי."},{"i":7188,"n":"בוג'אנח, משה מטריפולי","f":"בדוסה - דוסא","bt":"שע - בערך","dt":"תם","dp":"טריפולי","b":"למד במצרים אצל מהר\"ם גלנטי. רב, דיין, ומשורר בטריפולי, ורב ראשי. חתם בפנקס בי\"ד טריפולי. חתם על תעודה בענין אברה קרדוזו (\"עאדא\" מרכז אור שלום - בת ים)."},{"i":7189,"n":"בוג'אנח, נפתלי מאלגיר","f":"משה","b":"גביר ונגיד מראשי קהלת קצמטינא-אלגיר, מקורב למלכות. נהרג עק\"ה-תקסה, ואחר כך נהרגו יהודים רבים ובהם שלמה נגידים."},{"i":7190,"n":"בוגוטין, יוסף מליעפלי","f":"יעקב","bt":"תרמ","b":"רב בלפל(=ליעפלי)-פלך ויטבסק-תרסז."},{"i":7191,"n":"בוגוסלאוישוק=בוגסולוישק- קהילה","b":"ליטא - מחוז וילקומיר. לפני השואה ישבו בה כמה עשרות יהודים. רוב הזמן לא כיהן בה רב רבנים: ר ירחמיאל ישפה הי\"ד לימים בוישינטה."},{"i":7192,"n":"בוגזלא, אהרן מפאס","b":"מחכמי פאס, חתם-רפו בענין הנפיחה."},{"i":7193,"n":"בוגיעויל, דוד בן ציון מאואיזד","b":"תלמיד ישיבת \"בית ישראל\" באלכסנדר. פרסם מאמרים ב\"בית שמואל\" לתלמידי ישיבת \"בית ישראל\" באלכסנדר - לודז'-פיעטרקוב תרצא."},{"i":7194,"n":"בוגלר, שמואל מהענמעג","b":"מחכמי הענמעג, עדלין. פרסם מאמרים ב\"הלכות החדש\" - טירוני תרצא - קובץ מאת תלמידי ר שמואל דוד אונגר מטירנוי, \"משא ומתן\" - טירנוי תרצא."},{"i":7195,"n":"בוגן, יצחק אליעזר","b":"מחכמי גלינא-תרצט, תשובה אליו ב\"חלקת יעקב\"."},{"i":7196,"n":"בוגנר, יחיאל מלמברג","b":"מחכמי למברג. תשובה אליו ב\"פרי העץ\"-תרסו."},{"i":7197,"n":"בודזון, יהושע מליטא ולונדון","bt":"1858","bp":"האנושישוק","dt":"1929","b":"תלמיד ישיבות ליטא. היגר לאנגליה. חיבר רומנים עממיים שנדפסו בוילנא. חזר לוילנא. חיבר מונוגרפיה על דבורה אסתר הלפר."},{"i":7198,"n":"בודיויצר, יהודה"},{"i":7199,"n":"בודנהיימר, יהודה ליב מקרעפעלד","b":"רב בקארלסרוהא, קרעפעלד. מתלמידיו: ר געטשליק שלזינגר."},{"i":7200,"n":"בודנהיימר, מנחם מהמבורג","f":"ישי","dt":"תרסב - א תשרי","dp":"המבורג","b":"תלמיד ר יעקב עטלינגר, ר יצחק דב במברגר, מחכמי המבורג, אפוטרופוס היתומים בהמבורג."},{"i":7201,"n":"בודניק, דוד מנוברדוק","bt":"תרנג","bp":"קנישן-ליד ביאליסטוק","dt":"תשא - תמוז","b":"תלמיד ישיבת ראדין אצל דודו ר משה לנדינסקי, נוברדוק והיה תלמיד מובהק לסבא מנוברדוק, גלה עם רבו לרוסיה בזמן מלחה\"ע ה-I ועזר להקים ואף עמד בראש הישיבה במוהילוב ובזיטומיר, ר\"מ בניזני-נובגורוד-תרעה, לאחר המלחמה סייע בהקמת ישיבת מזריטש, מנהל הישיבה בוארשא-תרפג, יסד ועמד בראש ישיבה בדוינסק. חיבר שירי מוסר ששרו בישיבות נוברדוק. נספה בשואה."},{"i":7202,"n":"בודנצקי, אליקים געץ מקורמאנד","b":"רב בקארמענד. בנו - ר שמואל מפאפא."},{"i":7203,"n":"בודנצקי, יצחק מקורמאנד","b":"רב בקורמאנד(=קורמנד), דומ\"צ בפאפא-תרמ. נזכר בשו\"ת הכת\"ס."},{"i":7204,"n":"בודנצקי, שמואל מפאפא","f":"אליקים גץ מקארמענד","b":"חתנו - ר משה אברהם מטשארנא."},{"i":7205,"n":"בודנר, מאיר","f":"חיים אהרן","b":"תלמיד ר מאיר ארק. חתן דודו הגביר ר יוסף יוחנן הלוי הניג מטורנא ועבר לטורנא. ניצל מהשואה ועסק בהצלה מבודפשט."},{"i":7206,"n":"בודק, אריה ליב מאונגואר","b":"הרב הראשון באונגוואר"},{"i":7207,"n":"בודק, יוסף מנחם יואל או יעקב","bt":"תקעט","bp":"למברג","dt":"תרטו","dp":"צ'רנוביץ","b":"ערך את \"הרואה\""},{"i":7208,"n":"בודק, ישעיה מלבוב","b":"דיין בלבוב, חתם-תקו בפנקס הקהלה."},{"i":7209,"n":"בודק, ישראל אלימלך מלמברג","b":"מחכמי למברג-תרטו. תלמיד השו\"מ המזכירו בספרו."},{"i":7210,"n":"בודק, ישראל מברוד","b":"פרסם מאמרים ב\"שומר ציון הנאמן\" - אלטונא תרו-תרטז."},{"i":7211,"n":"בודק, מנחם מנדל מלבוב","f":"ראובן שרגא","k":"בעל עינות מים","bt":"תקפה","bp":"לבוב","dt":"תרלה","b":"מחסידי זידיטשוב, תלמיד ר יוסף שאול נתנזון. חיבר \"עינות מים\" למברג תרטז, \"סדר הדורות החדש\" למברג תרטז. כמו כן חיבר בעילום שמו ספרי מעשיות חסידיים ובהם \"פאר מקדושים\" למברג תרטז, \"מפעלות הצדיקים\" למברג תרלד, \"ספורי קדושים\" לייפציג תרכו, \"זכרון מנחם\" למברג תרלה."},{"i":7212,"n":"בודק, משה","b":"רב באירשא-תק\"פ"},{"i":7213,"n":"בודק, צבי הירש","f":"ישראל","b":"חתן שי\"ר."},{"i":7214,"n":"בודרהם, אליהו","b":"מו\"צ בטיטואן(מרוקו)-תקצ\"ב"},{"i":7215,"n":"בודשפיץ, זעקל","b":"רב בנאדיקרש,דומ\"צ באויבן"},{"i":7216,"n":"בודשפיץ, שמואל מאסאד","k":"שמואל וייל","dt":"תקעח - כב סיון","b":"חתן ר ראובן מזשאמבעק. רב ניאולוגי באסאד(=אסויד)-1789 וראש ישיבה שם על מקום ר וולף בוסקוביץ. נזכר ב\"נודע ביהודה\", \"מקל נועם\"."},{"i":7217,"n":"בוהרר, מרדכי","bt":"תרנה","dt":"תרצט","b":"גדול בחכמה ומדע,רב בגיילינגן-תרפ\"ו"},{"i":7218,"n":"בוונוסובסקי, אריה מארה\"ב","b":"פרסם מאמרים ב\"התבונה\" - נ\"י תשז - קובץ תלמידי ישיבת מיר."},{"i":7219,"n":"בוזאלדו די, יצחק משלוניקי","dt":"תצח","dp":"שלוניקי","b":"רב ודיין ומלמד תורה בשלוניקי-שנות ה-ת'."},{"i":7220,"n":"בוזאלדו די, משה משלוניקי","dt":"תצה - לפני","dp":"שלוניקי","b":"רופא בשלוניקי."},{"i":7221,"n":"בוזאלדו, אברהם מרודוס","b":"רב ברודוס-תקן בערך."},{"i":7222,"n":"בוזאלדו, נסים מאלגיר","bt":"תקף - בערך","dt":"תרן - בערך","b":"רב בעין אלבידא-אלגיר - תרי-תרל. סייע בהוצאת ההגדה \"ויגד לאברהם\" - ליוורנו תרכב לר א' חלימי."},{"i":7223,"n":"בוזגלו, אברהם ממרוקו","b":"מחכמי מרוקו-תקמח, נזכר ב\"תקפו של יוסף\"."},{"i":7224,"n":"בוזגלו, אברהם ממרוקו","b":"רב במרוקו-סוף שנות ה-תק', מכתב ממנו אל ר יעקב אבוחצירא (בערבית יהודית)."},{"i":7225,"n":"בוזגלו, דוד","bt":"תרסד","bp":"קזבלנקה","dt":"תשלה - כד אב","b":"מגדולי המשוררים והפייטנים במרוקו, בקי בלמוד, הלכה ודקדוק, התעוור-תש\"ט, עלה לא\"י-תשכ\"ח, גר בקרית ים","bk":[["מזמור לדוד",""]]},{"i":7226,"n":"בוזגלו, יצחק מירושלים","b":"מחכמי \"בית אל\"-תרפז."},{"i":7227,"n":"בוזגלו, מרדכי מדרעא וצפת","k":"בעל מעינות חכמה","b":"תלמיד ר דוד הלוי בעל \"המלכות\". מקובל מחכמי דרעא-מרוקו-שנות ה-ר'-ש', עלה לצפת ופגש את ר חיים ויטאל. חיבר פירוש לתפלות."},{"i":7228,"n":"בוזגלו, משה מסאלי - הזקן","b":"רב בסאלי - בשנות ה-ש. זקנו של ר שלם בוזגלו בעל \"מקדש מלך\". מכתב רבני סאלי לפאס בענין היתומה בת ר משה בוזגלו ובחתימת ר אהרן צרפתי, ר שלמה הכהן, ור שלמה קארו."},{"i":7229,"n":"בוזגלו, משה מסאלי - הנכד","f":"שלום (אביו או סבו)","b":"מחכמי סאלי, אביו של ר שלם בעל \"מקדש מלך\"."},{"i":7230,"n":"בוזגלו, שלום ממרוקו - הזקן","b":"מחכמי מרוקו. נכדו - ר שלם בעל \"מקדש מלך\" המזכירו בספרו."},{"i":7231,"n":"בוזגלו, שלום ממרוקו ולונדון","f":"משה","k":"בעל מקדש מלך","bt":"[תע]","bp":"[מראקש]","dt":"תקם","dp":"לונדון","b":"תלמיד ר אברהם אזולאי, ר יעקב פינטו, ר ישעיה הכהן ור יעקב גדליה, ור חיים ן עטר הזקן. אב\"ד במראקש, בגלל רדיפות השלטונות עבר ללונדון-תפ, וכיהן כדיין, היה בהמבורג ופגש את ר יונתן אייבשיץ ושוכנע בצדקתו, בנוגע למחלוקת הקמיעות עם ר יעקב עמדן - אך בהיותו בלונדון חזר בו וביקש הבהרות נוספות מר יונתן איבשיץ. עלה לצפת. חיבר גם \"כסא מלך\", \"הדרת מלך\" ועוד."},{"i":7232,"n":"בוזגלו, שלמה מפאס-מרוקו","b":"מחכמי פאס-תנא, והספיד אז את ר שלמה עמאר."},{"i":7233,"n":"בוזגלו-אזולאי, אברהם ממרוקו","f":"ראובן בנחמן","b":"רב במראקש, נשלח לונציה-שסד ע\"י קרובו הנגיד ר אברהם ן ואעיש כדי לקנות למלך מרוקו אבני חן וכלים יקרים וישב שם כשנה וחצי, והדפיס משניות עם פירוש הרמב\"ם וברטנורה. נקרא גם בן ואעיש."},{"i":7234,"n":"בוז'ור, פליקס","b":"קונסול צרפת בשלוניקי-תקנג, כתב על כת ה\"דונמה\" בשלוניקי."},{"i":7235,"n":"בוזיד ן, מסעוד מסאפי","b":"מחכמי סאפי-תפה, מקובל ומשורר. נזכר ב\"מאור ושמש\"."},{"i":7236,"n":"בוחבוט, בכור מסעוד מטבריה","dt":"תרעג - כד כסלו","b":"מרבני טבריה, שד\"ר-תרכ\"ט"},{"i":7237,"n":"בוחבוט, חיים שלום מירושלים","b":"מחכמי ירושלים, חתם-תרלג עם ר יצחק אופלטקה, ר רפאל אהרן ן שמעון ועוד."},{"i":7238,"n":"בוחבוט, יוסף מאלקצר-מרוקו","b":"מחכמי אלקצר-מרוקו עם ר מסעוד מויאל, ר משה מויאל, ר יצחק מויאל, ר ישועה עטייה. מתלמידיו - ר יצחק מויאל."},{"i":7239,"n":"בוחבוט, יצחק מאלקצר-מרוקו","b":"רבו של מוהר\"י בן מוייאל. רב באלקצר ושם נהגו ע\"פ דבריו לדורות."},{"i":7240,"n":"בוחבוט, מרדכי ממכנאס","b":"דיין במכנאס. חתם עם ר שמואל ואעיש-תקסז, ועם ר רפאל ור מימון בירדוגו.."},{"i":7241,"n":"בוחבוט, שבתי מיפו וביירות","f":"שלמה","k":"בעל מגד ציון","bt":"תרל","bp":"יפו","dt":"תשח - יז ניסן","dp":"ביירות - ירושלים","b":"דיין ביפו-תרסו, רב בקילז-סוריה, חלב-תרפא, ביירות-תרפד. נשא ונתן עם חכמי דורו. תשובות ממנו בענין עגונות ב\"עם מרדכי\". חיבר ספרים באגדה, דינים, ומוסר - בכת\"י. חיבר גם \"שיר ציון\"."},{"i":7242,"n":"בוחבוט, שלום מירושלים","dp":"ירושלים","b":"רב עדת המערבים בירושלים. מתלמידיו ר אהרן ן שמעון בעל \"נהר מצרים\", ר עובדיה הדאיה בעל \"ישכיל עבדי\". כונה בשם המלוב\"ן על הנסים שארעו לו. חתם על כתב שליחות ר ברוך גד-תטז."},{"i":7243,"n":"בוחבוט, שלמה ממרוקו ויפו","k":"בעל קהלת שלמה","bt":"תקפג","bp":"רבאט-מרוקו","dt":"תרסא - יא תשרי","dp":"ירושלים","b":"עלה בצעירותו ליפו. מחכמי יפו ומלמד תורה. מתלמידיו ר מסעוד הכהן אלחדאד לימים ראש ישיבת \"בית אל\", ר שמעון אשריקי ראב\"ד עדת המערבים. עבר לירושלים והיה מחכמי \"בית אל\". נספד ע\"י חבריו ר נחמן בטיטו, ור מנשה שמעון. בנו ר שבתי רב בחלב ובביירות."},{"i":7244,"n":"בוחבוט, שמואל מירושלים","f":"שלום בחבוט","dt":"תרעח - ה שבט","b":"רב בעדת המערבים בירושלים. מחכמי \"בית אל\" בירושלים-תרף. מתורתו בספרי חכמי דורו."},{"i":7245,"n":"בוחבוט, שמעון ממרוקו","b":"רב במרוקו - בשנות ה-תר'."},{"i":7246,"n":"בוטאריל, ליאון מספרד","f":"משה","b":"מחכמי ספרד בדורות האחרונים. בנו - ר משה."},{"i":7247,"n":"בוטאריל, משה מספרד","f":"יצחק","k":"בעל פירוש לספר יצירה","bt":"קן-קסט","dt":"ר - בערך","b":"תלמיד ר יעקב אשכנזי בעל ספר הקמיעים. מקובל ופילוסוף בצנטריל-ספרד. חיבר פירוש לספר יצירה - מנטובה, ועוד חבורים בקבלה. השתתף בויכוח עם המומר הלורקי, ונזכר ב\"ישועות משיחו\" לר יצחק אברבנל. הוא או תלמידו ר יעקב אלקושנו הכריז על עצמו כמשיח."},{"i":7248,"n":"בוטאריל, משה מקושטא","f":"ליאון בן משה","b":"רופא בחצר השולטן בקושטא-ש'. תרגם מלטינית והדפיס \"עין משפט\" - קושטא שכא (אחרי)."},{"i":7249,"n":"בוטבול, אהרן מפאס","bt":"תקפא","dt":"תרטז - סיון","b":"מחכמי פאס-מרוקו, נכדו רב בעל אותו השם."},{"i":7250,"n":"בוטבול, דוד מפאס-מרוקו","b":"מחכמי פאס, חתם על פס\"ד-תקל עם ר אברהם אדהאן."},{"i":7251,"n":"בוטבול, יהודה","b":"חכם שלם-תק\"ב"},{"i":7252,"n":"בוטבול, מסעוד מפאס","k":"קריקב","b":"מחכמי פאס-תקעז."},{"i":7253,"n":"בוטבול, סלימאן מפאס","b":"רב בפאס, חתם-תנח על תקנה יחד עם ר מנחם סירירו, ר וידאל הצרפתי, היעב\"ץ, ועוד."},{"i":7254,"n":"בוטווינר, יוסף","bt":"תריז","dt":"תרפז - כ אלול","b":"רב במנהיים"},{"i":7255,"n":"בוטון (ביטון), מורנו מירושלים","dt":"תקצד - כב חשון","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":7256,"n":"בוטון - משפחה","b":"משפחת רבנים בשלוניקי וירושלים."},{"i":7257,"n":"בוטון די, אברהם","f":"יעקב די בוטין","bt":"1545","dt":"ה'שמח","b":"מגדולי חכמי דורו-ר\"פ","bk":[["לחם משנה","מפרשי רמב\"ם"],["לחם רב","שו\"ת - אחרונים"],["לחם רב [שו\"ת]",""]]},{"i":7258,"n":"בוטון די, אברהם חייא מירושלים","f":"אהרן (באוצר אברהם)","k":"נכד הלחם משנה","bt":"שפה","bp":"אזמיר","dt":"תס - אחרי","dp":"ירושלים","b":"עלה לירושלים-תלה. בשליחות בתורכיה, גבה עדות בסארייבו בענין עגונה בשנת תם. לאחר מכן חתום על תעודות שונות בירושלים. הסכים על ספר שער אפרים לר אפרים הכהן מוילנא זולצבך תמח. היה ממונה על הגטין,"},{"i":7259,"n":"בוטון די, אברהם מדרדנלים וירוש","f":"אהרן","bp":"שלוניקי?","dt":"תמא","dp":"ירושלים","b":"מחכמי שלוניקי, רב בדרדנלים-תיז, אזמיר-תכד, רב הכול במגנישיאה-תלא, אזמיר-תלב, עלה לירושלים. בשליחות-תלט בתורכיה והיה בסרייבו ובלגרד-תם. הסכים על \"שיירי כנסת הגדולה\"-תמב."},{"i":7260,"n":"בוטון די, אברהם מצפת","dt":"שצח - אחרי","b":"בשנת שסא חתום עם חכמי צפת, עבר לטבריה בשנת שסג חזר לצפת. בשנת שסח חתום על תשובה עם מהריט, וכן עם ר יום טוב צהלון בשנת שץ שדר בפאס, בשנת שצח חתום על אגרת לקהילת ונציא."},{"i":7261,"n":"בוטון די, אברהם משלוניקי","f":"משה בן אברהם","k":"בעל לחם משנה","bt":"שה","bp":"שלוניקי","dt":"שמח - או אחרי","dp":"שלוניקי","b":"תלמיד מהרשד\"ם, חברו של ר מרדכי קלעי. פוסק, מגדולי חכמי דורו, רב בשלוניקי. בעל \"לחם משנה\" על הרמב\"ם. בן דודו של ר משה טרני. בניו: ר מאיר, ר יעקב מגליפולי ור אהרן מגליפולי."},{"i":7262,"n":"בוטון די, אברהם משלוניקי","f":"יעקב","bt":"שע","bp":"שלוניקי","dt":"תמה - כד ניסן","dp":"שלוניקי","b":"תלמיד ר חנניה טאיטצק. רב בשלוניקי, פוסק, רב הכולל-תלח על מקום ר חסדאי פרחיה הכהן. תשובות ממנו בספר השו\"ת של בנו - ר יעקב, וב\"פרח מטה אהרן\"."},{"i":7263,"n":"בוטון די, אברהם משלוניקי","f":"יהודה","k":"בעל מחזה אברהם","bp":"שלוניקי","dt":"תקם - אחרי","dp":"שלוניקי?","b":"מחכמי שלוניקי-תקה, רב במונסטיר-תקכא, שלוניקי-תקל. תשובותיו ותשובות בנו ר יהודה-שנפטר צעיר נדפסו בידי נכדו \"ר דוד\" שחיבר גם הקדמה."},{"i":7264,"n":"בוטון די, אברהם משלוניקי","dt":"של - אחרי","b":"רב בק\"ק פולייא בשלוניקי."},{"i":7265,"n":"בוטון די, אברהם משלוניקי","f":"שאלתיאל","dt":"תקפד - אחרי","dp":"שלוניקי","b":"דיין בשלוניקי-תקעג."},{"i":7266,"n":"בוטון די, אברהם רפאל משלוניקי","f":"אהרן","k":"בעל מחזה אברהם","dt":"תרכד - יב שבט","dp":"שלוניקי","b":"דיין בשלוניקי. חיבר הקדמה ל\"ימי דוד\" לר יוסף דוד-תריא, הו\"ל עם ר משה קאשטרו את שער ב לר חיים ויטאל-תרכב. מלמד תורה, ממונה על הצדקה, ועוסק בצרכי ציבור."},{"i":7267,"n":"בוטון די, אהרן דוד משלוניקי","b":"מחכמי שלוניקי-תרס."},{"i":7268,"n":"בוטון די, אהרן משלוניקי","f":"אברהם","b":"מחכמי שלוניקי, רב בגליפולי-תך בערך."},{"i":7269,"n":"בוטון די, אהרן משלוניקי","b":"מחכמי שלוניקי-תקע. בנו - ר אברהם-דיין בשלוניקי."},{"i":7270,"n":"בוטון די, אשר שמואל משלוניקי","b":"מלמד גמרא בת\"ת שלוניקי-תרף."},{"i":7271,"n":"בוטון די, דוד אהרן משלוניקי","k":"שלוניקי","dp":"תרעה","b":"דיין בשלוניקי. נפטר ללא ילדים."},{"i":7272,"n":"בוטון די, דוד משלוניקי","f":"יהודה בן אברהם","k":"בעל יד דוד","b":"נכד ר אברהם בעל \"מחזה אברהם\". הו\"ל את ספר זקנו ובו גם מתורת אביו וחיבר הקדמה-תקנה. חיבר \"יד דוד\" על שו\"ע יו\"ד."},{"i":7273,"n":"בוטון די, דניאל משלוניקי","b":"מרבני שאלוניקי"},{"i":7274,"n":"בוטון די, דניאל משלוניקי","dt":"תרלט","dp":"שלוניקי","b":"דיין בשלוניקי."},{"i":7275,"n":"בוטון די, דניאל משלוניקי","dt":"תרסב","dp":"שלוניקי","b":"דיין בשלוניקי."},{"i":7276,"n":"בוטון די, חייא אברהם מאזמיר","f":"אהרן או יצחק","k":"הו\"ל לחם רב","dt":"תנג","dp":"ירושלים","b":"דיין באיזמיר-תח אצל ר יוסף אישקאפה, לחם בשבתי צבי, עלה לירושלים וכיהן כדיין אצל הרב גלנטי, ממונה על הגיטים בירושלים, רב ראשי בירושלים-תס עד פטירתו בסמוך לכך. בשליחות הקהלה בחו\"ל. הסכים על \"כנסת הגדולה\". חתם על העברת הקדש טבריה לצפת-תנא. (לדעת ריבלין - שם אביו - ר יצחק מירושלים, כנראה יש בלבול בינו לבין ר חיים אברהם בן יצחק - ואולי המדובר באותו החכם)."},{"i":7277,"n":"בוטון די, חייא אברהם משלוניקי","f":"משה","b":"מחכמי שלוניקי-שן."},{"i":7278,"n":"בוטון די, חיים אברהם מירושלים","f":"יצחק","b":"מחכמי ירושלים, בשנת תס בשליחות האשכנזים בירושלים למען בניית בית הכנסת של העדה שחרב, היה במרוקו ואלגיר, אך האניה נשרפה, הוא יצא בנס, ונאלץ שוב לבקש כסף בפאס. אביו הוא כנראה מחכמי צפת שחתם בשנת שצח על אגרת בענין טבריה. בשליחותו הגיע למרוקו ולאלגיר, בחזרתו נשרפה האוניה השליח ניצל אולם הכסף נשרף, והוא נאלץ לחזור על שליחותו. כמה ממכתביו פורסמו על ידי בניהו ב\"סיני\" לה. (כנראה יש בלבול בינו לבין ר חייא אברהם בן אהרן - ואולי מדובר באותו החכם)"},{"i":7279,"n":"בוטון די, חיים משה מירושלים","dt":"תשי - יא אייר","b":"דיין בירושלים"},{"i":7280,"n":"בוטון די, חיים משה מירושלים","dt":"תקו-י - יא אייר","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":7281,"n":"בוטון די, יהודה משלוניקי","dt":"תקד - לפני","dp":"שלוניקי","b":"גביר בשלוניקי, וממונה על גביית מיסי הקהלה."},{"i":7282,"n":"בוטון די, יהודה משלוניקי","b":"רב בשלוניקי-שפב, נזכר בשו\"ת מהרימ\"ט. אחיו של ר יעקב."},{"i":7283,"n":"בוטון די, יהודה משלוניקי - ב","f":"אברהם - מחזה אברהם","b":"מו\"צ בשלוניקי-תקע. הו\"ל ספר אביו \"מחזה אברהם\" עם הוספות ממנו. בנו - ר אברהם."},{"i":7284,"n":"בוטון די, יעקב מירושלים","b":"מחכמי שלוניקי, עלה לירושלים, בשליחות-תקיח. חתם-תקיד על שטר התקשרות עם חכמי ירושלים."},{"i":7285,"n":"בוטון די, יעקב משלוניקי","f":"אברהם","k":"בעל עדות ביעקב","bt":"שצח","dt":"תמו - ט ניסן","dp":"שלוניקי","b":"מגדולי חכמי דורו בשלוניקי. חיבר חדושים על הרשב\"א בשם \"עדות ביעקב\". חלק מכתביו - אבדו ובהם ביאור על ספר העיטור.","bk":[["עדות ביעקב [שו\"ת]",""]]},{"i":7286,"n":"בוטון די, יעקב משלוניקי","bt":"תרנג?","dt":"תקלד?","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":7287,"n":"בוטון די, יעקב משלוניקי","f":"אברהם","dt":"תרעא","dp":"שלוניקי","b":"מחכמי שלוניקי, וממלא מקום הרב הראשי על מקום ר אשר קובו עד למינוי ר יעקב מאיר. ממיסדי \"דובב שפתי ישנים\"-תרנו."},{"i":7288,"n":"בוטון די, יעקב משלוניקי","b":"מחכמי שלוניקי, חבר ב\"ועד הרוחני\"-תרף."},{"i":7289,"n":"בוטון די, יעקב משלוניקי","dt":"שיד - ט תשרי","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":7290,"n":"בוטון די, יעקב משלוניקי ולארסו","b":"מחכמי שלוניקי-שנות התק'. רב בלארסו."},{"i":7291,"n":"בוטון די, יצחק אברהם משלוניקי","k":"בעל לה ז'ודיאה סאלב'","bt":"תרנז","bp":"שלוניקי","b":"רופא, עתונאי ומנהיג ציוני בשלוניקי. הו\"ל \"איל שאמאר\", \"לה פואירסה\", \"איל פרוגריסו\" שפעל לזכויות היהודים בתורכיה, יסד אגודות \"אור ציון\", \"בני ציון\", ועוד, עלה לארץ והתישב בתל אביב-תרץ, סייע בהדפסת קטלוג ספרי לדינו - נדפס בתוך \"קרית ספר\"."},{"i":7292,"n":"בוטון די, יצחק מירושלים","b":"אחיו של ר יעקב די בוטון משלוניקי. תלמיד ר שמואל גארמיזנו."},{"i":7293,"n":"בוטון די, יצחק מצפת וירושלים","b":"מחכמי צפת, בשנת שצח חתם על אגרת בענין טבריה. עבר לירושלים והיה מתלמידי ר יעקב צמח וחתם אתו בשנת תיז על אגרת בענין ר ברוך גד. בנו - ר חייא אברהם."},{"i":7294,"n":"בוטון די, מאיר משלוניקי","f":"יעקב","dt":"תנט","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":7295,"n":"בוטון די, מאיר משלוניקי","f":"משה או שלמה","b":"משורר בשלוניקי-שנות ה-ש', מחברי ר גדליה ן יחיא המשורר משלוניקי."},{"i":7296,"n":"בוטון די, מאיר משלוניקי וגליפו","f":"אברהם-לחם משנה","k":"בעל שו\"ת מהרם די בוט","dt":"תי - בערך","dp":"קושטא","b":"חתן ר אהרן ששון משלוניקי. מחכמי שלוניקי, רב באליפלי(=גליפולי)-שץ-תך בערך יחד עם גיסו ר יוסף בן אהרן ששון. גיסו - ר יוסף מטרני מזכירו בספרו. בנו ר אברהם, וחתנו ר ישי אלמולי. הו\"ל ספר אביו \"לחם משנה\" יחד עם ר יוסף די נוביש."},{"i":7297,"n":"בוטון די, משה מאנגורה","b":"מחכמי שלוניקי, רב באנגורה-שנט."},{"i":7298,"n":"בוטון די, משה משלוניקי","dt":"של","dp":"שלוניקי","b":"מחכמי שלוניקי. נספד ע\"י ר משה אלמושנינו."},{"i":7299,"n":"בוטון די, משה משלוניקי","f":"חיים","dt":"תרמט","dp":"שלוניקי","b":"דיין בשלוניקי."},{"i":7300,"n":"בוטון די, משה משלוניקי","b":"תלמיד ר דניאל אישטרושא. חתן ר אברהם מוטאל-הנכד. מחכמי שלוניקי-שנות ה-ת'."},{"i":7301,"n":"בוטון די, עזריה","b":"מחכמי תורכיה, חתם על ספרים רבים."},{"i":7302,"n":"בוטון די, שמואל משלוניקי","b":"מחכמי שלוניקי-תרס."},{"i":7303,"n":"בוטון די, שניאור משלוניקי","dt":"תקך","dp":"שלוניקי","b":"גביר בשלוניקי."},{"i":7304,"n":"בוטון, אשר משלוניקי","b":"מורה בביה\"ס ת\"ת בשלוניקי-לפני השואה."},{"i":7305,"n":"בוטון, טוביה מליפאנטו","b":"דיין בליפאנטו-שנות ה-ת' אצל ר דניאל יצחק."},{"i":7306,"n":"בוטין די, יהודה ליב ממוהילוב","b":"נכד ר ברוך בנדט מרגליות מחסלביץ. מו\"צ במוהילוב, מינסק. חתנו - ר משה יצחק אביגדור בעל \"פרדס רמונים\" ומזכירו בספרו. הסכים על \"דרך תבונות\" מינסק תקצה עם ר שואל בן שלמה ור ישראל מיכל די בוטין."},{"i":7307,"n":"בוטפוס, יוסף מירושלים","b":"מחכמי פרג, עלה לירושלים עם בתו מלכה ובעלה ר שבתי, בימי ר אליהו מפירארה בערך בשנת קנד. מוזכר בשו\"ת מהרי ברונא."},{"i":7308,"n":"בוטקי, יעקב מירושלים","b":"מחכמי ירושלים, חבר ב\"אגודת שלום\"-תקיח."},{"i":7309,"n":"בוטראשוילי, יהודה","bt":"תרסד","dt":"תשמה","b":"מחסידי חב\"ד בגיאורגיה(=גרוזיה), רב במלחובקה-רוסיה - אחרי מלחמת העולם השניה, עלה לארץ-תשלא וכיהן כרב ראשי ליהודי גיאורגיה בארץ, דיין בביה\"ד של חב\"ד, ומונה ע\"י האדמור מלובאביטש לאחראי על מדינת רוסיה."},{"i":7310,"n":"בוטשאטשר, וולף מפיורדא","b":"מחכמי פיורדא-תן, נשא ונתן עם החכם צבי כשהיה בפיורדא."},{"i":7311,"n":"בוטשינסקי, משה יצחק","b":"פרסם מאמרים ב\"כרם בית שמואל\" - פיעטרקוב תרצב - כתב עת תלמידי ישיבת אלכסנדר."},{"i":7312,"n":"בויאר, אברהם מליבאוי","f":"אליהו קליקאלער מפילט","b":"רב בליבאוי, (נקרא ע\"ש אחוזת בויען ליד האזנפוט). אחיהם של ר שמעון מניישטט-סוגיגד, ר ברוך בנדט."},{"i":7313,"n":"בויאר, חיים מקומרנא","f":"אלעזר","k":"ר חיים ר אלעזר","b":"רב בקומרנא ואלעזר היה אביו או חותנו. תלמיד המהרי\"א מקומרנא."},{"i":7314,"n":"בויאר, יעקב מצרפת","b":"רב בניצה-תר\"ע"},{"i":7315,"n":"בויאר, צבי יהודה מבוצאץ","b":"מחכמי בוצאץ. תשובה אליו ב\"מנחת שי\"."},{"i":7316,"n":"בויבסקי, ירחמיאל ברוך מארה\"ב","b":"פרסם מאמרים ב\"המאסף\" - ירושלים-אלכסנדריה תרנו-תרעג."},{"i":7317,"n":"בוים מנחם מנדל בן אהרן","bt":"1800","dt":"ה'תרלג 1873","bk":[["קורות העתים לישורון בארץ ישראל",""]]},{"i":7318,"n":"בוים, אבא מארה\"ב","b":"רב בניו יורק-תריב."},{"i":7319,"n":"בוים, דוד יהודה ליב מעיר חדש","f":"נפתלי מאיר מהומנא","k":"בעל מנחת יהודה","bt":"תריז או תרכה","bp":"הומנא","dt":"תרעח - טז סיון","dp":"עיר חדש","b":"תלמיד השב\"ס, ור אברהם יהודה שוורץ מהעדילא-מאדע. חתן ר ישראל איסר טויבר בעל \"אזרח רענן\" מעיר חדש(=ניישטט,נאווא-מעסטא) ועבר לשם. דיין בעיר חדש-תרסח על מקום חותנו. חיבר גם \"נחלת יהודה\"."},{"i":7320,"n":"בוים, חיים מפטשוארשמאר","f":"יהודה ליב בוים","b":"רב בווערעשוואר-תרעד, עבר לבודפשט. פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":7321,"n":"בוים, יהודה ליב","b":"מו\"צ בפערבעטע-תר\"מ"},{"i":7322,"n":"בוים, יוסף מאיזביצה","k":"בעל בית המלך","dt":"תש..","b":"תלמידי ישיבת חכמי לובלין. חיבר \"בית המלך\" על הרמב\"ם. נספה בשואה."},{"i":7323,"n":"בוים, יחיאל","dt":"תשד","b":"רב בגוטא"},{"i":7324,"n":"בוים, יעקב מוערעשוואר","k":"בעל התלמוד בפרלמנט ה","b":"רב בפיליש וארוש וואר(=וערעשוואר) כ-50 שנה. חיבר ספר על עלילת הדם בטיסא אסלאר בשם \"התלמוד בפרלמנט ההונגרי\"."},{"i":7325,"n":"בוים, מנחם מנדל מבריסק וצפת","f":"אהרן בעל סייג לתורה","k":"בעל קורות העתים","bt":"תקס","bp":"בריסק","dt":"תרלג - יג אייר","dp":"ירושלים","b":"מחכמי ליטא, עלה לצפת-תקצג, עבר לירושלים-תרב. לאחר פרעות מרד הפלחים חיבר את \"קורות העתים\" על הרעש והביזה בצפת ועל הקורות אותו. בשליחות בליטא-תקצז-ח, חזר והתישב בירושלים-תרב. חיבר \"קורות העתים\" וילנא תר. הקים את מלון קמניץ המפורסם בירושלים."},{"i":7326,"n":"בוים, משה וולף מקאמארן","f":"דוד מקורטאקסי","b":"תלמיד הכת\"ס, ור עזריאל הילדהיימר. חתן ר מרדכי ראב מקאמארן, ועבר לשם-תרכד."},{"i":7327,"n":"בוים, שאול אלישע מקורטשין","f":"אברהם יעקב מסטריפקוב","b":"ניצל מהשואה ועבר ללונדון. חתן רא\"ח הורביץ. הו\"ל צילום \"הליכות עולם\" לונדון תשלז."},{"i":7328,"n":"בוימגלד, פרץ","b":"מחותן עם בעל \"נפש חיה\". בנו - ר מנחם מנדל."},{"i":7329,"n":"בוימגרטן, אהרן משה מירושלים","f":"בנימין זאב","bp":"קרעמזיר","dt":"תרלז - ז טבת","dp":"ירושלים","b":"תלמיד החת\"ס, ור מרדכי בנט מניקלשבורג ור ברוך פרנקל-תאומים מלייפניק. מצאצאי ר אברהם בעל \"כפת המנעול\". עלה לצפת-תקצד (בהשפעת שד\"ר שעבר בפרשבורג ולקחו עמו בחוזרו לצפת - בהמלצת החת\"ס). חתן ר נתן הלוי ספיר מוילנא בצפת. גיסו ר יעקב ספיר בעל \"אבן ספיר\". עבר לירושלים-תקצז והקים שם ישיבה בשם \"אהל משה\" ע\"ש החת\"ס. ממייסדי כולל אונגרן וביהמ\"ד \"דורש ציון\" (עם חביריו ר יונה ליב מנדלסון ור יצחק אופלטקה). אבי משפחת בוימגרטן בירושלים."},{"i":7330,"n":"בוימגרטן, אלתר חיים","b":"חתן האדמור מאלכסנדר. פרסם מאמרים ב\"נהור שרגא\" - אלכסנדר תרצט."},{"i":7331,"n":"בוימגרטן, דוד צבי מוינה","f":"יוסף מוינה","bp":"וינה","dt":"תשלח - ג אד\"א","dp":"ירושלים","b":"תלמיד הדעת סופר, ור שמואל רוזנברג מאונסדורף. חתן דודו ר יוסף שטרן מסערדאוהל. מלמד בוינה, עלה לירושלים-תרצט, ר\"מ בישיבת נייטרא במונט-קיסקא. הו\"ל חדושי חת\"ס לגיטין עם הערות ממנו."},{"i":7332,"n":"בוימגרטן, יוסף מוינה","k":"בעל פורת יוסף","bt":"תרכד או תרלט","dt":"תרצג - ו אדר","b":"מו\"צ בביה\"כ \"שיף שוהל\"-וינה-תרסה. חתן ר שלום דב בר שטרן מסערדאוהל. פרסם מאמרים ב\"תל תלפיות\"."},{"i":7333,"n":"בוימגרטן, יצחק איזיק מטרנוב","k":"בעל חדושים על שוע","bp":"טרנוב","b":"חסיד האדמור ר יהושע הורביץ מדזיקוב. תלמיד ר זאב דב שנקל. עבר לקורטשין. כתב חדושים על שו\"ע - אבדו."},{"i":7334,"n":"בוימגרטן, שלמה","f":"יוסף בוימגרטן","dt":"תרצה","b":"דיין בווינה"},{"i":7335,"n":"בוימהאקר, חיים מאוטואצק","b":"מעורכי \"תפארת ישראל\" - וארשא-נ\"י-תל אביב תרצו."},{"i":7336,"n":"בוימהולץ, שלמה","dt":"תשג","b":"ר\"מ בהיידה"},{"i":7337,"n":"בוימוול, אברהם","b":"דיין במושציסק-תרפט אצל ר חיים נחום הלברשטם. נפטר לפני השואה."},{"i":7338,"n":"בוימינגר, אביגדור","f":"ישראל","b":"חיבר \"קיצור דברי ימי ישראל\" בצורה היתולית ונשלח כמשלוח מנות בפורים לזקנו הגביר ר יואל בוימינגר."},{"i":7339,"n":"בוימינגר, יעקב יושע מקראקא","bt":"תקעב","bp":"קראקא","b":"גביר תלמיד חכם. חתן ר שמואל ליב פלסנר מקראקא."},{"i":7340,"n":"בוימינגר, יצחק איציק","dt":"תקצא - יט אייר","b":"דיין בקרקא"},{"i":7341,"n":"בוימינגר, יצחק מקראקא","b":"נכד החכם צבי. רב בקראקא. חתן ר השל מוישניצה."},{"i":7342,"n":"בוימל, דוד צבי","dt":"תרסח","b":"רב במעדיאש"},{"i":7343,"n":"בוימל, יהושע מקרשצינקה","f":"יואל משה","k":"בעל הרב הגדול","bt":"תרעג","bp":"בוצאץ","dt":"תשב","b":"נכד ר נפתלי הירץ לנדא מזוולין. מראשוני ישיבת חכמי לובלין. מחסדי צורטקוב. רב באופוצנו. חיבר \"הרב הגדול\" ביוגרפיה על מהרם מלובלין - ירושלים תשנא. נספה בשואה."},{"i":7344,"n":"בוימל, יהושע מקרשצינקה ונ\"י","f":"נחום מקרשצינקה","k":"בעל עמק הלכה","bt":"תרם","bp":"קרשצינקה-גליציה","dt":"תשח - ד אלול","dp":"ניו יורק","b":"בילדותו כונה העילוי מטרנוב. נסמך מאת: ר בנימין וייס מטשרנוביץ בעל \"אבן יקרה\", ר שמואל אנגדל מרדומישל. חתן ר שבתי וינברגר מחסידי צאנז. ר\"מ בישיבת \"בית ישראל\" בויזניץ. רב בסלטין-תרעא, קרשצינקה, ברין. היגר לניו יורק-תרף וכיהן כרב קהילת עדת ישורון בויליאמסבורג, וסגן נשיא אגודת ישראל באמריקה. חיבר \"עמק הלכה\" ניו יורק תרצד. פרסם מאמרים ב\"עמק הלכה\" - באטארקס תרפא."},{"i":7345,"n":"בוימל, יואל משה מקרשצינקה","f":"נחום","bt":"תרמו","bp":"קרשצינקה","dt":"תרצו","b":"חתן ר עזריאל אוירבך מבוצאץ. אב\"ד קרשצינקה על מקום אביו. חדושיו אבדו בשואה. נדפס מעט בסוף קונטרס \"שלשה דורות\"."},{"i":7346,"n":"בוימל, יוסף מרדכי","f":"יואל משה","bt":"תרעא","bp":"קרשצינקה","b":"בשנת תרצה עבר לארה\"ב. חיבר קונטרס \"שלשה דורות לתולדות המשפחה\" בספר \"עמק הלכה\". רב בברוקלין. עלה לירושלים-תשל."},{"i":7347,"n":"בוימל, ישראל משה מפאריצק","b":"פרסם מאמרים ב\"מציון תצא תורה\" - זאמושט תרפט."},{"i":7348,"n":"בוימל, מאיר רפאל מלנצק","f":"נחום","bt":"תרנג","dt":"תשג","b":"חתן ר חיים בקר אב\"ד לנצק, אב\"ד בלנצק על מקום חותנו. נספה בשואה."},{"i":7349,"n":"בוימל, מרדכי יעקב מליסקא","f":"יהושע","k":"א יעקנעלה ר שיעלעס","bt":"תרכא","dt":"תרצא","b":"רב בליסקא על מקום אביו. מחסידי רופשיץ."},{"i":7350,"n":"בוימל, נחום מקרשצינקה","f":"יהושע","bt":"תרכא","dt":"תרפו","b":"רב קרשצינקה-תרס ושצבניץ(=שצאווניץ) בקרפטים. חתן ר מאיר רפאל ציגלר. היה מחובר עם גדולי ליטא שבאו לנפוש במקומו וכן עם גדולי האדמורים."},{"i":7351,"n":"בוימל, נפתלי הרץ משצבניץ","f":"נחום מקרשצינקה","k":"בעל אמרי שפר","bt":"תרן","bp":"קרשצינקה","dt":"תשלה","dp":"ירושלים","b":"תלמיד ר שלום דוד אונגר מזבנא, ר דוד דב בריש מייזלש מאויהל. נסמך מאת: ר שמואל פיהרר מקרוסנא, ר אלימלך פרנקל תאומים מיאוורוב. חתן ר נפתלי וגשל. רב בשצבניץ-גליציה-תרפו על מקום אביו. היגר לארה\"ב וכיהן כרב בביהכ\"נ \"שומרי שבת\" בברוקלין-תרפט, שוב בשצבניץ-תרצג, עלה לארץ-תשכג קודם לחיפה ואחר כך ירושלים. חיבר \"אמרי שפר\" ירושלים תשכג."},{"i":7352,"n":"בוימן, אברהם מארה\"ב","b":"רב בניו יורק. נזכר ב\"קצות השלחן\" לר אברהם חיים נאה מירושלים."},{"i":7353,"n":"בוימן, אליעזר נפתלי מאיסטרחאן","f":"משה","bt":"תרכה","bp":"ריגא","b":"רב בשינבורג(=שינברג)-קורלנד, אסטרחן-ליד בוכרה."},{"i":7354,"n":"בוימן, יעקב מאיסטריק לוס אנגלס","b":"מחכמי רישא, איסטריק, רב לוס אנגלס. ממשתתפי הקובץ \"אסיפת חכמים\"-תרע. פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח, \"הבאר\" - זאמושץ-וארשא תרפד, \"הירדן\" - רישא תרץ."},{"i":7355,"n":"בוימן, יעקב מלוס אנג'לס","k":"בעל חמדת יעקב","b":"רב בלוס אנג'לס-תשב."},{"i":7356,"n":"בוימר, שמואל זנויל ממיהאלביץ","b":"פרסם מאמרים ב\"קובץ מפרשי התורה\" - מארגרטן תרצג."},{"i":7357,"n":"בויסק הורביץ, י' ליב","f":"שמואל שחור הורביץ"},{"i":7358,"n":"בוירסקי, גרשון מאיר מושלאקאוא","f":"אברהם","k":"בעל ירושלים הצרופה","bt":"תרכב","bp":"אסטרין","dt":"תרפה - כה אייר","b":"תלמיד ר יעקב צבי מאסטרין בעל \"תפארת יעקב\", תלמיד בכולל קובנא. רב בליברפול (בקהלת יוצאי רוסיה פולין), ניוקסל, הוסטין-ארה\"ב, יוטיקא-ארה\"ב, נאווידוואר, וושליקובה(=וושלקאווא)-פלך גרודנא-תרנו, ניו יורק-תרסד. חיבר גם \"רגש אמרינו\", ועוד. היה מעורב במחלוקת בירושלים בין כולל אמריקה לבין הועד הכללי ופעל בהיותו באמריקה למען הועד הכללי."},{"i":7359,"n":"בוירסקי, צבי הירש מביאליסטוק","f":"מאיר יצחק קמינקר","k":"בעל תוספת שבת","b":"נכד ר חיים קמינקר, ונינו של ר נח בלוך מוילנא. רב בביאליסטוק. חיבר ספר על בה\"ג ונדפס ממנו חלק בשם \"תוספת שבת\", בספרו מתאר את יחוס משפחתו."},{"i":7360,"n":"בוירסקי, שמואל שלמה","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":7361,"n":"בוירפרינד, משה מבובוב","b":"רב בבובוב-תרנו לפני ר שלמה הלברשטם."},{"i":7362,"n":"בוכ’בזה יצחק חי","bt":"1853","dt":"ה'תרצ 1930","bk":[["לחם לפי הטף",""]]},{"i":7363,"n":"בוכבזה, אברהם מאלגיר","bt":"תרי","dt":"תרץ - בערך","b":"מראשי חברת \"עץ חיים\" - של כי\"ח באלגיר. מו\"ל ומדפיס עם שותפיו ר' ש' בכאש, ור' מ' צרור - והדפיסו ספרים רבים בערבית יהודית."},{"i":7364,"n":"בוכבזה, יצחק חי מטריפולי","f":"גבריאל כמוס","k":"בעל לחם לפי הטף","bt":"תר-תריג","bp":"גאבס","dt":"תרצ - כא שבט","dp":"טריפולי - לוב","b":"תלמיד ר אברהם עלוש מגאבס בעל \"ברית ותורה\", ר משה זמור מתונס, ר דוד ג'אוי מתונס ולמד עם חברו ר ישראל זיתון שהיה לימים ראש הרבנים בתונס. רב בגאבס, מוכנין, גאבס, טריפולי. חיבר גם \"ביתה דרבנן\", \"גנזי ברכה\", \"ברכה ותהלה\", ועוד. מתורתו ב\"הירח\" - ג'רבה תשח."},{"i":7365,"n":"בוכבזה, מסעוד מתונס","b":"תלמיד ר חיים חורי בעל \"דברי התלמיד\". מחכמי גאבס, רב בספאקץ-תונס. מחדושיו בירחון \"הירח\" - תש. והעתיק עם ר סעייד חדאד מחדושי רבם."},{"i":7366,"n":"בוכהיים, דוד מאונגריש ברוד","bp":"פרוסטיץ","dt":"תרא","b":"דיין בגויטיין-תקפב, אב\"ד היינץ-תקפח, אב\"ד אונגריש בראד(-ברוד)-תקצג."},{"i":7367,"n":"בוכהיסטר, אריה ליב מצאנז","b":"תשובה אליו ב\"מנחת יחיאל\"."},{"i":7368,"n":"בוכהיסטר, זאב דב ממישלניץ","f":"שמואל","bt":"תרעב","bp":"מישלניץ","dt":"תשב","b":"תלמיד רצ\"ה מייזליש בניימרקט. חתן ר יצחק הלוי טורנר מודוביצה. ר\"מ בישיבות בובוב בודוביצה ובסנוק. נספה בשואה."},{"i":7369,"n":"בוכהלץ, מרדכי מפרמישלא","b":"פרסם מאמרים ב\"התפוח\" - בנדין תרפח."},{"i":7370,"n":"בוכוואלד, בצלאל מפרשבורג","f":"שלמה","k":"בעל עקב ענוה","bt":"תקנה","bp":"קדלבורג","dt":"תרל - ט חשון","dp":"פרשבורג","b":"תלמיד החת\"ס. מחכמי פרשבורג."},{"i":7371,"n":"בוכינגר, פיבל מהונגריה","b":"תלמיד ר שבתי וייס משימאני בעל 'הלכתא רבתא לשבתא', רשם מחברות מתורת רבו."},{"i":7372,"n":"בוכניק, אברהם מטריפולי","f":"שלמה","bt":"תם","dt":"תקי - בערך","dp":"טריפולי","b":"רב וסופר בטריפולי. חתם בפנקס בי\"ד בטריפולי."},{"i":7373,"n":"בוכניק, יוסף מטריפולי","k":"בעל ויאמר יוסף","bt":"תרי","bp":"טריפולי","dt":"תרסח","dp":"טריפולי","b":"רב ופייטן בטריפולי. חיבור קינות ופיוטים בערבית יהודית, \"ויאמר יוסף\" טריפולי תרפג."},{"i":7374,"n":"בוכניק, יצחק מתונס וירושלים","k":"בעל ויאמר יצחק","bt":"תרעה","bp":"גאבס-תונס","dt":"תשלה - כו שבט","dp":"ירושלים","b":"עבר עם משפחתו לתונס. תלמיד ר מצליח מזוז בישיבת \"חברת התלמוד\", ותלמיד ר דוד קטורזה, וחותנו ר ישעוה אלמליח. ר\"מ בישיבת חברת התלמוד. חיבר \"בני חי\" לזכר בנו ר מנחם שנפטר צעיר. עלה לירושלים-תשלה.","bk":[["ויאמר יצחק",""]]},{"i":7375,"n":"בוכנר, אבא מסוכא","f":"שמחה בריש","bt":"תרכה","dt":"תש","b":"מחכמי סוכא שרבים נהו אחריו למרות שלא שימש ברבנות."},{"i":7376,"n":"בוכנר, בנימין וולף מקראקא","b":"מגדולי חכמי קרקא-ש\"פ"},{"i":7377,"n":"בוכנר, בנימין זאב וולף","f":"צבי צזמיר","b":"רב בשטיקאטשין"},{"i":7378,"n":"בוכנר, בנימין זאב וולף","f":"שלמה בוכנר","k":"בעל שער בנימין","b":"רב בפיעטרקוב,ללוב"},{"i":7379,"n":"בוכנר, דוד יצחק מטשנסטחוב","f":"גרשון","k":"בעל בית דוד","dt":"תקפז - כח שבט","b":"רב בטשנסטחוב, פיעטרקוב-תקפא. חברו של החוזה מלובלין.","bk":[["בית דוד – עה\"ת ושו\"ת",""]]},{"i":7380,"n":"בוכנר, דוד כהנא מברוד","f":"משה הכהן","k":"בעל נפש דוד","bt":"תפד","dt":"תקסא","b":"התיתם בילדותו וגדל אצל אחיו ר דב בר מקרילוב. חתן ר משה אברהם אלטשולר מיברוב. תלמיד ר יחיאל מיכל בעל \"משנה לחם\". בזיוו\"ש חתן נכדת ר דוד מירלש מברודי. רב בפמורן, גלינא-תקסה, ליטין-פודוליה, רב בברודי-תקם. חיבר \"נפש דוד\" למברג תקן, ועוד. ספר \"קרן אור\" לאביו עם ספרו \"מראה כהן\" זולקוא תקלו."},{"i":7381,"n":"בוכנר, דוד נתן מביליץ","b":"שו\"ב בביליץ. תשובה אליו ב\"מין כנף\"."},{"i":7382,"n":"בוכנר, זאב וולף הכהן","f":"דוד - נפש דוד","k":"בעל זבד המליצה","b":"מדקדק ובקי בכתבי הקדש. חיבר גם \"שירי תהלה\" \"כתר מלכות\" - לבוב תקנד, \"צחות המליצה\" - פרג תקסה."},{"i":7383,"n":"בוכנר, זישא מקראקא","b":"מחכמי קראקא-תרנט - תשובה אליו \"הרי בשמים\"."},{"i":7384,"n":"בוכנר, חיים מבוכניה","b":"רב בבוכניה"},{"i":7385,"n":"בוכנר, חיים מקראקא","f":"בנימין וולף","k":"בעל אור חדש","r":"רבה הראשון של לאקנבעך","bt":"שע בערך","dt":"תמד - יז שבט","dp":"פיורדא","b":"מקובל, מדקדק, מרביץ תורה, גביר, רב באבנפורט, לקנבך, וינה, לאחר הגירוש-תל עבר לפיורדא. אולי הוא המחבר \"תוצאות חיים\" - קיצור פרק שירה - המבורג תע.","bk":[["אור חדש הנקרא אור החיים",""],["אורחות חיים וברכות הנהנין - שו\"ע או\"ח ודיני ברכות הנהנין (חלק קטן נדפס)",""],["לוח החיים - דרכי שמירת האדם את בריאותו",""],["מים חיים - תורה שבכתב ובע\"פ בדרך פרד\"ס (כת\"י)",""],["פתורא דדהבא - שו\"ע (כת\"י)",""],["תוצאות חיים - דקדוק",""]]},{"i":7386,"n":"בוכנר, יעקב אשר מקאשוב","b":"מחכמי קאשוב-תרעא. חשובה אליו ב\"דובב מישרים\"."},{"i":7387,"n":"בוכנר, מרדכי יצחק הכהן מבילקמי","b":"רב בבילקמין. תשובה אליו \"יד יוסף\"."},{"i":7388,"n":"בוכנר, משה מאנטורפן","dt":"תשמז","dp":"אנטורפן","b":"מחנך ומנהל בית יעקב באנטורפן."},{"i":7389,"n":"בוכנר, משה מקאשנוב","f":"אברהם יהושע השל","k":"בעל מחשבות משה","bt":"תרכג","bp":"קשאנוב","dt":"תשב","b":"חתן ר יוסף שולדנפריי מקראקא. סירב לכהן ברבנות על פי צוואת זקנו ר משה שהיה לו גילוי אליהו. חיבר \"מחשבות משה\" קראקא תרפה. נספה בשואה."},{"i":7390,"n":"בוכנר, משלם זוסיא מקראקא","b":"מחכמי קראקא. נכד ר שלמה בוכנר, תשובה אליו בשות מהרשם."},{"i":7391,"n":"בוכנר, נפתלי הרץ מפינטשוב","f":"שלמה מפינטשוב","b":"רב בפינטשוב-תק\"ל"},{"i":7392,"n":"בוכנר, צבי הירש מזברז","f":"שלמה בוכנר","dt":"תקלג","b":"רב בזבארז"},{"i":7393,"n":"בוכנר, צבי הירש מקרוטושין","f":"שמשון באך מאוסטרהא","b":"רב בקראטשין-ת\"י"},{"i":7394,"n":"בוכנר, שלמה מפינטשוב ושדה חדש","f":"בנימין וואלף בוכנר","dt":"תקכא - כב אלול","b":"רב בפינטשוב,שדה חדש"},{"i":7395,"n":"בוכנר, שלמה מקשאנוב","f":"משה","bt":"תקיב","bp":"עלקיש","dt":"תקפח - יח אייר","b":"תלמיד ר שמואל שמלקא מניקלשבורג ומראשי ה\"חבורה\" שם, והיה אומר שיעורים בישיבת רבו, חסיד ר אלימלך מליזנסק, החליף מכתבים עם \"מאור ושמש\". רבה הראשון של קשאנוב(=קרשנוב)-תקלח או תקנח. כיהן כאדמור-תקמו, תחת מרותו של החוזה מלובלין. כתביו אבדו ברובם. ציווה בצואתו לצאצאיו שלא יהיו רבנים או אדמורים. ממנו נדפס \"שלשה עדרי צאן\" קרית יואל תשמא, מתורתו ב\"אמרי קדוש\" בסוף \"דברי צדיקים\". על תולדות משפחתו ב\"ארזי לבנון\". תלמידו ר דב בעריש מאושפיצין."},{"i":7396,"n":"בוכריס, יוסף מזרזיס","b":"רב ומו\"צ בזרזיס-תונס, חתם-תרצו עם ר מכלוף עידאן ור כלפון הכהן."},{"i":7397,"n":"בוכריס, כמוס מג'רבה","k":"בעל רכב בחור","bt":"תרנט","dt":"תרעח - כג טבת","b":"תלמיד ר מכלוף עידאן, ותלמיד אחיו ר יוסף בוכריס. מחכמי ג'רבא ונפטר צעיר כבן 19.","bk":[["רכב בחור",""]]},{"i":7398,"n":"בוכריץ, אברהם"},{"i":7399,"n":"בוכריץ, גאלי"},{"i":7400,"n":"בוכריץ, יצחק מתונס","k":"בעל שיח יצחק","b":"נכד ר רחמים בוכריץ."},{"i":7401,"n":"בוכריץ, פראגי","b":"פרסם מאמרים ב\"הירח\" - ג'רבה תשח."},{"i":7402,"n":"בוכריץ, ציון מג'רבה","b":"מחכמי ג'רבא בזמן ר אברהם הכהן אב\"ד דיג'ת."},{"i":7403,"n":"בוכריץ, רחמים מדיג'ת-תונס","f":"משה","k":"בעל בגדי שש","bt":"תרי","bp":"ג'רבה","dt":"תרעג - כג טבת","dp":"ירושלים","b":"דיין בדיג'ת-תרן, עם גיסו ר דוד כהן גישא בעל \"שירי דוד\" וחתנו ר משה זקן מאזוז בעל \"שערי משה\" ומזכירו בספרו. רב בטריפולי, עלה לירושלים-תרעג. חיבר גם \"מנחה חדשה וקול ערב\", \"פטר רחם\" ועוד."},{"i":7404,"n":"בוכריץ, רחמים מתונס","k":"בעל לב רחב","dt":"תשסה","dp":"בני ברק","b":"רב בתונס, עלה לארץ והתישב בבני ברק."},{"i":7405,"n":"בוכריץ, שושן מטריפולי","bt":"תרל","dt":"תשכז","dp":"טריפולי","b":"רב באזאוויא-לוב, טריפולי-תשט."},{"i":7406,"n":"בול, חיים מאיר מארה\"ב","f":"מרדכי","k":"בעל שמירה טובה","b":"רב בארה\"ב-תרפח."},{"i":7407,"n":"בולא, יוסף משלוניקי","f":"שלמה","b":"מחכמי שלוניקי-תקן. חיבר הקדמה לספר אביו \"לחם שלמה\"."},{"i":7408,"n":"בולא, רפאל משה מירושלים","f":"יוסף","k":"בעל גט מקושר","bp":"שלוניקי","dt":"תקלג - כז אדר","dp":"ירושלים","b":"נכד ר משה זכות בעל \"קול הרמז\". מחכמי שלוניקי, רב באנקונה-איטליה, עלה לירושלים. רב בירושלים וראש ישיבת \"נוה שלום\" שיסד הגביר ר יצחק די מאיו מקושטא, חתם על תקנת הרווקים בשנת תקט. בשנת תקיב בשליחות בתורכיה, דיין עם מהרי\"ט אלגזי. ראש ישיבת \"נוה שלום\"-תקיח על מקום ר יעקב אלגזי. בשנת תקלב התמנה ל\"ראשון לציון\". בשליחות בתורכיה-תקיב. חיבר \"גט מקושר\" קושטא תקכז, \"זכות משה\", \"חיי עולם\". בנו - ר שלמה. נספד מאת ר ידידיה טאריקה בכנייא, ר רפאל אליעזר נחמיאש בשלוניקי, ועוד.","bk":[["גט מקושר",""]]},{"i":7409,"n":"בולא, שלמה מירושלים ושלוניקי","f":"רפאל משה","k":"בעל לחם שלמה","bt":"תצד","bp":"ירושלים","dt":"תקמו - כב-ג שבט","dp":"שלוניקי","b":"מחכמי ירושלים, עבר לשלוניקי והקים שם ישיבה (באוצר עבר לדמשק), חתם על החרם של ר יוסף ן לב - כנגד העיר אנקונא. היה בר פלוגתא של ר יוסף שמואל מודיליאנו בשלוניקי. חיבר \"חמשה קנינים\".בניו: ר אברהם, ור יוסף שהו\"ל את ספרו \"לחם שלמה\" - שלוניקי תקנה."},{"i":7410,"n":"בולא, שלמה מקושטא","f":"יעקב","b":"מחכמי קושטא-ש'."},{"i":7411,"n":"בולאט, אברהם","b":"מגדולי דורו-ת\"ק"},{"i":7412,"n":"בולאט, יהודה מספרד קושטא וצפת","f":"יוסף","k":"בעל כלל קצר","bp":"ספרד","dt":"שי","b":"מחכמי ספרד בדור הגירוש, גלה לקושטא-רנב, דיין-רעט אצל הרא\"ם, עלה לצפת. נזכר בשו\"ת הרא\"ם, \"אהלי תם\", \"בנימין זאב\". מסדר אותיות בדפוס קושטא."},{"i":7413,"n":"בולאקי, אברהם"},{"i":7414,"n":"בולדא, ראובן מדורבורג","b":"מגדולי חכמי אשכנז,רב בדורדבורג-ש\"נ"},{"i":7415,"n":"בולחין, נתן מאלגיר","f":"יעקב","bt":"תך - בערך","dt":"תץ - בערך","b":"רב ומשורר בתלמסאן, פיוטים ממנו ב\"אוצר טוב\" - ברלין 1880."},{"i":7416,"n":"בוליא ן, שלמה מקושטא","b":"מחכמי קושטא, חתם על פסקי של ר תם ן יחיא בעל \"אהלי תם\"."},{"i":7417,"n":"בוליחובר, אריה ליבוש מזסלב","f":"אליהו בן יצחק מבוליח","k":"בעל ערוגת הבושם","b":"מצאצאי הרבי ר השיל מקראקא. רב בזסלב(=זאסלב)-תרל. פרסם מאמרים ב\"מכילתא דרבנן\" - אודסה תרמו."},{"i":7418,"n":"בוליטר, סעדיה מהאראדיטש","f":"ירחמיאל","bt":"תרז","b":"רב ביאבלונוב-פולטובה-תרלג, האראדיטש(=האראדישטש)-פלך מוהילוב."},{"i":7419,"n":"בולקא, חיים יעקב","b":"פרסם מאמרים ב\"החיים\" - לונדון תש."},{"i":7420,"n":"בומבך, אברהם מקענטי","f":"יהושע פנחס","bt":"תרן","dt":"תשג","b":"חתן ר שלמה חיים בורשטין מצאנז. אב\"ד קענטי, אביו השיב לו ב\"אהל יהושע\"-תרעג"},{"i":7421,"n":"בומבך, אליהו מאושפיצן-אושוויץ","f":"יהושע פנחס מאושפיצין","k":"בעל מענה אליהו","bt":"תרמד","bp":"אוהנוב","dt":"תשג - יח אייר","b":"חסיד קומרנא. חתן ר יעקב ספרין האדמור מקומרנא. רב בקענטי, אושפצין(=אושביץ) על מקום אביו. חיבר \"מענה אליהו\" (דרשת הבר מצוה שלו) דרוהוביטש. פרסם מאמרים ב\"אסיפת חכמים\" - אושפצין תרצד, \"כתר תורה\" - אושפיצין תרצט."},{"i":7422,"n":"בומבך, אריה ליב מהולשיץ","f":"יהושע פנחס","bt":"תרמח","dt":"תשג","b":"רבה של הולשיץ."},{"i":7423,"n":"בומבך, הרצל מסאמבור","dt":"תשג","b":"רב בסאמבור"},{"i":7424,"n":"בומבך, חיים זאב מזייבוש","f":"יהושע פנחס","bt":"תרמו","dt":"תשג","b":"חתן ר שמחה גולדברג מסנוק. רבה של זייבוש. חידושיו בספר אביו \"אהל יהושע\". נספה בשואה."},{"i":7425,"n":"בומבך, חיים זאב מלבוב","bt":"תקי","dt":"תקע","b":"חתן ר דוד ב\"ר פתחיה לידא מלמברג. אביו של ר יהודה צבי הדיין מלבוב."},{"i":7426,"n":"בומבך, יהודה צבי ליביש","f":"יוסף","bt":"תרל (או תריח)","dt":"תרצו","b":"אחיו ותלמידו של ר יהושע פנחס בעל \"אהל יהושע\", דיין ברוה-רוסקה. בין תלמידיו ר שמעון פדרבוש."},{"i":7427,"n":"בומבך, יהודה צבי מלמברג","f":"חיים זאב","k":"בעל מנחת יהודא","bt":"תקלו","bp":"למברג","dt":"תרו","b":"דיין בלמברג אצל בעל \"ישועות יעקב\". חיבר \"מנחת יהודא\" זולקווא תקצא, \"ארץ צבי\"."},{"i":7428,"n":"בומבך, יהושע אפרים מליזנסק","f":"יהודה צבי","k":"בעל פני אפרים","bt":"תקס","bp":"למברג","dt":"תרלו","b":"חתן ר שמחה פרייא מדוברומיל. רב בליזנסק-תריח, קרעשוב-תרכד. חיבר \"פני אפרים\" תל אביב תשך."},{"i":7429,"n":"בומבך, יהושע פנחס מדרוהוביטש","f":"יוסף","k":"בעל אהל יהושע","bt":"תרכה","bp":"יברוב","dt":"תרפא- כח ניסן","b":"חסיד בלז, חתן ר אריה ליב הרושובסקי אב\"ד הובניס. רב במדיניץ-תרמט, בילקמין-תרנד, דרוהוביטש-תרנז, אושפצין (אושביץ)-תרפא, בוצאץ-תרסז. חיבר \"אהל יהושע\" דרוהוביטש תרסא. פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט, \"קהלת אשר\" - אושפיצין תרפג."},{"i":7430,"n":"בומבך, יואל","f":"יהודה צבי","bt":"תקנו","bp":"למברג","dt":"תקצא","b":"חתן ר יוסף מרגליות-שמוקלר. בנו ר יעקב מרדכי בומבך."},{"i":7431,"n":"בומבך, יוסף אשר מבובוב","f":"יהושע אפרים","bt":"תרסז","bp":"בובוב","dt":"תשנה","b":"תלמיד ישיבות גלנטא וטירנוי. ניצל מהשואה ועלה לארץ. חתן ר מרדכי אריה הורביץ מבנילא. עסקן באגודת ישראל."},{"i":7432,"n":"בומבך, יוסף מיברוב","f":"יעקב מרדכי","k":"בעל שו\"ת","bt":"תקצו","dt":"תרסו","b":"מחכמי יברוב-תרל. חתן ר דוד לאניר. חיבר ספר שו\"ת - בכתב יד."},{"i":7433,"n":"בומבך, יוסף מניסקא","bt":"תרסט","bp":"ניסקא","b":"נכד הפני יהושע. למד בביהמ\"ד לרבנים בברלין-תרץ. עבר לאנגליה, עלה לארץ והוציא חוברות בעניני הלכה."},{"i":7434,"n":"בומבך, יעקב מרדכי מברלין","f":"נפתלי הירץ","k":"בעל פרחי שושנים","bt":"תרלט","bp":"דוברומיל","dt":"תשיב","b":"חתן ר מרדכי דוד תאומים-פרנקל אב\"ד פשוורסק. עבר לברלין-תרסח ופתח בית מסחר לספרים. חיבר \"פרחי שושנים\" ברלין תרעא. פרסם מאמרים ב\"המאור\" - ברלין תרצג."},{"i":7435,"n":"בומבך, יעקב מרדכי מדוברומיל","f":"יואל","k":"בעל אפיקי מים","bt":"תקעו","dt":"תרלו","b":"חתן ר נפתלי הירץ ויקלר. חיבר \"אפיקי מים\" על מנחת יהודה, בכתב יד."},{"i":7436,"n":"בומבך, משיל מלבוב","bt":"תקץ","bp":"תרנג","dt":"תרנג","b":"מחכמי למברג, מלמד תורה ועסקן."},{"i":7437,"n":"בומבך, נפתלי הרץ מסמבור","f":"יוסף","k":"בעל גבעת הלבונה","bt":"תרמה","bp":"יברוב","dt":"תשג","b":"תלמיד אחיו ר יהושע פנחס. חתן ר ישראל יעקב קרוס מליביטשוב. רב במגרוב, דברצין, סמבור-תרפה. נספה בשואה. חיבר \"גבעת הלבונה\" לובלין תרצט."},{"i":7438,"n":"בומבך, שמואל מאושפיצין","f":"אליהו מאושפיצין","dt":"תש..","b":"רב בבירקנאו (רזזינקה)- שכונה באושפיצין ועל מקומו אחריו ר יוסף שיפמן. רב בבנדין. חתן ר שם קלינגברג. נספה בשואה."},{"i":7439,"n":"בומבך, שמואל מבנדין","f":"אליהו מאושפיצין","k":"אדמור מניישטט בבנדין","dt":"תש..","b":"מצאצאי בעל \"מאור ושמש\". נכד ר יעקב משה מקומרנא. אדמור מניישטאט בבנדין. נספה בשואה."},{"i":7440,"n":"בומברג, אהרן מפיורדא","f":"יואל","b":"סופר קהלת פיורדא-תקסה."},{"i":7441,"n":"בומברג, משה מברלין","b":"מראשי הקהילה בברלין. חתם על הסכם ויתור מס הקהילה ממשה מנדלסון-תקכג, חתם על כתב הרבנות של ר צבי הירש מלונדון וברלין."},{"i":7442,"n":"בומזה, אריה יהודה ליב מסטנוב","bt":"תק","dt":"תקפה","b":"תלמיד ר שמלקא מניקלשבורג. מחכמי סטנוב ופגש שם את הבעשט כשבא לשבות אצל האב\"ד ר ישראל חריף מסטנוב. עבר למיקוליניץ."},{"i":7443,"n":"בומנדיל, אהרן מאלגיר","bt":"תס - בערך","dt":"תקך - בערך","b":"רב בתלמסאן, והיה גם עשיר."},{"i":7444,"n":"בומס, מנחם מנדל מלאסק","f":"משה מלאסק","b":"מחמכי לאסק. הו\"ל ספר אביו \"יד משה\", ו\"כנפי נשרים\" לר אברהם ליכטנשטין."},{"i":7445,"n":"בומס, משה מלאסק","f":"הלל","k":"בעל יד משה","b":"שו\"ב בלאסק. חיבר פירוש לתורה \"יד משה\". בנו - ר מנחם מנדל מלאסק הו\"ל את ספרו."},{"i":7446,"n":"בון די, אברהם מפיררה","b":"רב בפיררה בזמן הרמ\"ע. הסכמה ממנו לפסק ר ישמעאל חנינא (רבו של הרמ\"ע) ב\"פחד יצחק\"."},{"i":7447,"n":"בון נין, דוד משלוניקי","dt":"רפז - כב כסלו","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":7448,"n":"בון, יונה הרופא מפפד\"מ","f":"משה","b":"רופא בפפד\"מ. חתם-תטז על תקנון הרופאים בזמן ר מנדל בס מפפד\"מ."},{"i":7449,"n":"בון, משה משלוניקי","dt":"שי","dp":"שלוניקי","b":"גביר מחכמי שלוניקי, חתם על החרם בענין הצמר-שי."},{"i":7450,"n":"בון, נתן מפפד\"מ","k":"בעל שכחת לקט","b":"מקובל, מחכמי פפד\"מ, רב בהמלבורג-תע."},{"i":7451,"n":"בונא, זלמן","b":"מגדולי חכמי אשכנז במגנצא-רט\"ז"},{"i":7452,"n":"בונא-דיאה, אברהם מאלכסנדריה","b":"רב באלכסנדריה. חתם-שכט על מכתב התמיכה של רבני קושטא ומצרים בדון יוסף נשיא."},{"i":7453,"n":"בונא-דיאה, דוד הכהן מאלגיר","bt":"קל","dt":"ר - בערך","b":"רב ודיין במסתגאנם. היה במחלוקת עם הדיין ר אברהם בן נתן הספרדי - ונזכר בשו\"ת הריב\"ש."},{"i":7454,"n":"בונא-וינטורה, גבריאל מקושטא","b":"גביר בחצר מלכי תורכיה-שנות ה-ש'."},{"i":7455,"n":"בונאן, אברהם מתונס וירושלים","f":"יצחק - אהלי יצחק","bp":"[תונס]","dt":"תרכו - כב חשון","dp":"ירושלים","b":"רב בתונס, עלה לירושלים."},{"i":7456,"n":"בונאן, חיים מרדכי","dt":"תקצג","dp":"צפת","b":"מחכמי צפת, בשנת תקכז בשליחות צפת באירופה עם ר ישראל בנבנשתי, ואחר כך בשליחות בארצות ערב ופאס. כפי הנראה נהרג ברעש בשנת תקצז"},{"i":7457,"n":"בונאן, יעקב מאזמיר","b":"מחכמי אזמיר-תקן בערך."},{"i":7458,"n":"בונאן, יצחק מתונס","k":"בעל אהלי יצחק","bt":"תקכב","b":"תלמיד ר אברהם לומברוזו בעל זרע יצחק. דיין בתונס-תקפ - בקהל פורטוגזיס, חבירו של ר יצחק טייב. חיבר \"ברית יצחק ועוד. בנו ר דוד אב\"ד קהל פורטוגזיס."},{"i":7459,"n":"בונאן, מסעוד מתונס וטבריה","bt":"תק","bp":"תונס","dt":"תקסב - אחרי","b":"מחכמי תונס, עלה לטבריה-תקז, בשליחות באיטליה, הולנד ואנגליה-תקח והיה באיטליה-תקיא ותיקן ששבת פרשת שקלים תהיה מגבית לקהילת טבריה ונשמר המנהג עוד בשנת תקסב. פגש בהמבורג את ר יונתן אייבשיץ והצדיק אותו במחלוקת הקמיעות. התיישב בצפת, ובשנת תקיב חתם על כתב שליחות שמעון די גילדרן. לאחר הרעש-תקך(?) שימש כרבה של צפת. בשנת תקכה פגשו ר שמחה מזאלוזיץ בצפת וכתב עליו. בשליחות צפת באירופה-תקלד עם ר אברהם ריוח, והיה מחלוקת ביניהם בהיותם בוינה, והגיעו לטריאסט בנפרד ופגשו בחיד\"א שכעס על המחלוקת. נכדו(-בן בתו) - ר מסעוד פינטו - שליח קהלת צפת-תקפו."},{"i":7460,"n":"בונאן, ציון מצפת","b":"מחכמי צפת, טבריה-תקצג, וחתם על אגרת לר יצחק כהן סקלי."},{"i":7461,"n":"בונאפו, הלל ממינסק","f":"מרדכי","bt":"תרג","dt":"תרנו - י אדר","dp":"מינסק","b":"מחכמי מינסק"},{"i":7462,"n":"בונאפוס הכהן משלוניקי","dt":"ש - א אב","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":7463,"n":"בונאפוס, דניאל מאזמיר","b":"מחסידי ש\"ץ גם אחרי המרתו, התחזה לנביא וניבא על חזרתו של ש\"ץ. התאסלם בקאסאבה-ליד אזמיר."},{"i":7464,"n":"בונאפוס, יצחק מספרד","f":"שאלתיאל","b":"תלמיד ר פרץ הכהן. חתן הריב\"ש. מחכמי ספרד בדור ה-יב. רופא בשלשונה, מחכמי פלסיט. היה היחיד ממשפחת הריב\"ש שנשאר בספרד אחר פרעות קנא. תשובה ממנו לקהילת פדובה בענין גט."},{"i":7465,"n":"בונאפוס, מנחם מן פרפיאנו","f":"אברהם","k":"בעל מכלל יופי","b":"חיבר \"מכלל יופי\" - ספר הנדרים - שלוניקי שכז."},{"i":7466,"n":"בונג'ואה ן, יעקב","dt":"תרסג - כד שבט","b":"חתם עם ר מרדכי מטיבולי(=טיוולי) על נוסח הגט ב\"הלכות קטנות\". לדעת רוזניס היה מירושלים ולדעת רבלין מקושטא."},{"i":7467,"n":"בונגודיש, שמואל מספרד","b":"מחכמי ספרד, תלמיד הרשב\"א, וחברו של ר יונה די פיארה."},{"i":7468,"n":"בונדווין, בונגודס","bt":"קי","dt":"קפ","b":"רופא, מחכמי סרדיניה, רבה של קליארי"},{"i":7469,"n":"בונדי, אברהם מפרג","f":"יום טוב מפרג","k":"בעל זרע אברהם","dt":"תקמז","b":"רב בפרג. אחיו - ר ליב מפרג. בנו - ר נחמיה פיבל מפרג בעל \"תורת נחמיה\". חתנו - ר יחזקאל מבומסלא בעל \"מראה יחזקאל\"."},{"i":7470,"n":"בונדי, אדם מליוורנו","b":"רופא דיין ודרשן בליוורנו. מוזכר בספר \"יד מלאכי\", \"שבר מצרים\" ועוד."},{"i":7471,"n":"בונדי, אליעזר מבומסלא","f":"יום טוב?","dt":"תקנ","b":"רב בבומסלא,ביהם"},{"i":7472,"n":"בונדי, חנניה מזל טוב מליוורנו","b":"רב בליוורנו. רבו של ר יצחק נוניס ואיס בעל \"שיח יצחק\" וכתב הקדמה לספרו של תלמידו."},{"i":7473,"n":"בונדי, טבלי מפפד\"מ","f":"משה יונה","bt":"תקנו","b":"אחיו של ר שמואל ממגנצא. נקרא ע\"ש זקנו ר דוד טבלי שייאר. מחכמי פפד\"מ. חיבר פירוש להגדה-תרנח. דרשות ממנו בספר אחיו \"שקל הקודש\"."},{"i":7474,"n":"בונדי, יום טוב מפרג - א","f":"יום טוב?","dt":"תפט","dp":"פרג","b":"היה רב ודיין בפרג ובעל סמכות לדון יחידי (ובו שמשו רק דיינים בודדים בדור). רב בפרוסטיץ. מבניו: ר אליעזר מבוסלמא, ר אברהם בעל \"זרע אברהם\" (ואולי הוא נכדו), ר יום טוב (האם יש בן שנקרא על שמו?), אחיו - ר אליעזר מבומסלא."},{"i":7475,"n":"בונדי, יום טוב מפרג - הבן","f":"יום טוב מפרג","b":"רב בפרג - נקרא על שם אביו.?"},{"i":7476,"n":"בונדי, יונה ישכר בער מאיזנשטט","f":"יהושע יחזקאל פיבל","dt":"תקפו - יז תמוז","dp":"איזנשטט","b":"חתן ר אברהם נפתלי שייאר. רב-שנת תק\"פ"},{"i":7477,"n":"בונדי, יונה מדרזדן וניו יורק","bt":"תקסד","bp":"דרזדן","dt":"תרלד - כב אדר","dp":"ניו יורק","b":"מצאצאי ר יונתן איבשיץ, תלמיד ישיבת פרג, הגיע לארה\"ב-תריט וכיהן כרב בניו יורק. התיר להציב פסל לזכרון הנדיב יהודה טורא, בתשובה בשם \"יונתי בחגוי הסלע\". הו\"ל כתב עת באנגלית."},{"i":7478,"n":"בונדי, יחיאל מיכל","b":"רב במנגנצא-תר\"ע"},{"i":7479,"n":"בונדי, יעקב מליוורנו","f":"אדם","b":"רב ורופא בליוורנו-תק. חתנו - ר יעקב נוניס ואיס. תשובותיו בספרי חכמי דורו."},{"i":7480,"n":"בונדי, ליב מפרג","f":"יום טוב מפרג","b":"דיין בפרג. אחיו - ר אברהם בעל \"זרע אברהם\"."},{"i":7481,"n":"בונדי, משה יונה מפרג","bt":"תקכח","dt":"תקסו","b":"תלמיד הנודע ביהודה. חתן ר הרץ אברהם נפתלי שייאר ממיינץ. נפטר צעיר. בנו ר שמואל - רב בפרג."},{"i":7482,"n":"בונדי, נחמיה פיבל מפרג","f":"אברהם - זרע אברהם","k":"בעל תורת נחמיה","b":"רב בפרג."},{"i":7483,"n":"בונדי, שמואל ממגנצא","f":"משה יונה","k":"בעל ברית קודש","bt":"תקנד","dt":"תרלח - יט כסלו","b":"נכד ר אברהם הרץ שייאר בעל \"תורי זהב\" וגדל אצלו לאחר שנתייתם. מראשי קהלת מגנצא ומנהל הישיבה, יזם את פרישת הקהלה האורטודוכסית-תריג בראשות חתנו - ר מאיר להמן. חיבר גם \"תורה אור\". הו\"ל ספרי זקנו עם הוספות ממנו בשם \"ברית קדש\", \"תורה אור\". אחיו - ר טעבאלע."},{"i":7484,"n":"בונדר ן, מצ'מון מתימן","f":"יפת","dt":"ד'תתקיא (1151)","b":"מחכמי תימן הקדומים. נגיד בדרום תימן על מקום אביו שהיה הנגיד הראשון - היה אחראי על המסחר בין עדן להודו. מכתבים ממנו נמצאו בגניזה בקהיר. היה אחראי על נמל עדן, והיו לו ספינות שהפליגו לציילון, וכן היה מתווך בין בעלי הספינות לשודדי הים בדרך. היה בקשר עם ר מצליח בן שלמה הכהן גאון ארץ ישראל. בנו ר חלפון על מקומו אחריו."},{"i":7485,"n":"בונהארד","k":"ראה: באניהאד","b":"רב בקיצע, דיין אצל החת\"ס ואצל הכת\"ס בפרשבורג-תקץ על מקום ר משה טריטש, ולראב\"ד על מקום ר דניאל פרוסטיץ."},{"i":7486,"n":"בונוס, אפרים מאמשטרדם","b":"רופא באמשטרדם."},{"i":7487,"n":"בונופוצו, גרשון מקורפו","f":"יוסף","b":"רב בקורפו, רבו או חברו של ר בנימין טריווש בעל שו\"ת בנימין זאב. היה במחלוקת עם הר\"י מינץ שאף נידהו."},{"i":7488,"n":"בוני, משה מירושלים","dt":"תעז - בערך","dp":"ירושלים-חברון","b":"מחכמי ירושלים, חברון? נהרג בדרכו בין ירושלים לחברון."},{"i":7489,"n":"בוניט, שם טוב מאלגיר","bt":"קפ - בערך","dt":"רס - בערך","b":"מחכמי הוניין-אלגיר, בג'איה, והתכתב עם הרשב\"ש."},{"i":7490,"n":"בונימוביץ, אהרן מוולוזין וילנא","f":"יצחק","dt":"תקצח - טז אדר","b":"תלמיד ר חיים מוולוזין, מראשי הדיינים וספרא בבית דינו של ר חיים בוולוזין. הסכים על ש\"ס וילנא-תקצה, וגם על ש\"ס סלאויטא. חתם בפנקס הגר\"א-תקצח. בנו ר הירש וולוזינר. (לפי אוצר הרבנים נפטר - כט סיון)."},{"i":7491,"n":"בונימוביץ, יוסף אליהו מלובטשי","f":"יצחק בונימוביץ","bt":"תרטו","b":"מו\"צ בלובאטשי-תרמ לצד אביו, ורב-תרסה על מקומו אחריו."},{"i":7492,"n":"בונימוביץ, יצחק הלוי מלובטשי","b":"רב בלובטשי-תרל, ובנו ר יוסף אליהו רב לצדו ועל מקומו אחריו."},{"i":7493,"n":"בונין, יצחק מטורונטו","f":"צבי הירש מסלוצק","k":"בעל דברי יצחק","bt":"תרלב-מב","bp":"מאלאסטווקא-פלך מוהילוב","b":"תלמיד אביו, ישיבת ר מאיר רפפורט במאלאסטווקא(=מלסטובקה), ישיבת ר ישראל מלאך בחסלביץ, ישיבת חב\"ד בצעריגוב, ישיבת ר זאב וולף בבוברויסק, סמרגון, כולל קובנא. נסמך מאת: ר צבי הירש רבינוביץ מקובנא, ר משה דנישבסקי, ר חיים יהודה סאסניצר מסמרגון, ר רפאל שפירא מוולוזין-בוברויסק, ר חיים ברלין, ר יצחק יעקב ריינס מלידא. חתן ר צבי מנחם מסיראז-פלך צערניגוב. רב בראוונא-פלך חרסון-תרנח, נאווא-אוקריינקא-פלך חרסון-תרעד, היגר לארה\"ב וכיהן כרב ביהכ\"נ \"תפארת ישראל אנשי בריסק\" בניו יורק-תרפג, רב בטרנטון-תרפד, ביהכ\"נ \"בית יעקב אנשי שלום\" בניו יורק. (טורונטו-תרפג - אולי בלבול עם טרנטון ניו יורק). חיבר \"דברי יצחק\" נ\"י תרצא. חבר בועד הרבנים באמריקה, סגן יו\"ר הועד למען גן יבנה בארץ ישראל. עוסק בפעילות צבור, נואם מוכשר."},{"i":7494,"n":"בונם","f":"יעקב","b":"רב-שנת-ש\"נ"},{"i":7495,"n":"בונם מלוורטוב","b":"תלמיד החוזה מלובלין, היהודה הקדוש מפשיסחא, ור שמחה בונם מפשיסחא."},{"i":7496,"n":"בונם מקראקא","b":"רב בקרקא-שנת ת'"},{"i":7497,"n":"בונם, מזיכלין","b":"תלמיד ר מנחם מנדל מקוצק. חברו של ר יחיאל מאיר מגוסטינין."},{"i":7498,"n":"בונפאצו, גרשון מאיטליה","b":"מחכמי איטליה, היה במחלוקת עם ר יהודה מינץ, שאלה ממנו לרא\"ם."},{"i":7499,"n":"בונפיד, דוד ממונטפלייר","f":"ראובן","b":"תלמיד הרמב\"ן, רב במונטפלייר-שנת נ', חיבר חידושים לש\"ס"},{"i":7500,"n":"בונפיד, יהודה ממרוקו","b":"סופר שטרות במרוקו (כנראה מרבאט או סאלי), חתם על פס\"ד עם ר שמעון ן עמראן."},{"i":7501,"n":"בונפיד, מימון פאס","b":"מחכמי פאס, חתם על שטר-שפח."},{"i":7502,"n":"בונפיד, שלמה מספרד","f":"ראובן","b":"רב בספרד, כנראה גם בסרגוסה-ספרד. השתתף בויכוח-קעג בטורטוסה. חיבר שירים."},{"i":7503,"n":"בונפייר, דוד מספרד","k":"תלמיד הרמב\"ן","b":"מגדולי הראשונים בספרד-שנת ק'. חיבר חדושים על סנהדרין."},{"i":7504,"n":"בונפיל, זכריה מסופיה","b":"פרנס מראשי קהלת פליבנא-שנות ה-ש'."},{"i":7505,"n":"בונפיל, יוסף ממצרים","b":"רב במצרים-שנות ה-ת'."},{"i":7506,"n":"בונפיל, יעקב מקושטא","b":"גביר בקושטא-תקך, סייע בהדפסת \"דברי אמת\" לר יצחק בן דוד."},{"i":7507,"n":"בונפיליו, פרץ מאיטליה ואבילונא","b":"רב באבילונא-אלבניה, ור דוד מסיר ליאון על מקומו אחריו-רעב."},{"i":7508,"n":"בונצלאו, גומפריך מאיזנשטט","b":"דיין באיזנשטט, חתם-תריד עם ר עזריאל הילדסהיימר ור וולף אוסטרליץ."},{"i":7509,"n":"בונשיניור, יעקב מקושטא","b":"חתן ר אפרים ן שאנג'י מקושטא. רב בקושטא."},{"i":7510,"n":"בונשתרוק, יצחק ממיורקה","f":"שלמה","bt":"ק - בערך","dt":"קפ - בערך","b":"מחכמי מיורקה-ספרד, עבר בזמן הגירוש-קנא לאלג'יר, ואחריו הגיעו הרשב\"ש והריב\"ש ותקנו ביחד תקנות. רב באלגיר על מקום ר שאול אשתרוק - שפינה לו את מקומו, לאחר כשנתיים נתמנה הריב\"ש על מקומו ונאלץ לעזוב את אלג'יר בגלל מחלוקת עם ר שאול הכהן אשתרוך - מנהיג הקהלות שם. דיין בקונסטנטין(=קצמטינא) והיה במחלוקת עם ראשי הקהל - ונעשה שלום בהתערבות הריב\"ש. היה במחלוקת עם ר מימון בן דוד."},{"i":7511,"n":"בוסוחובסקי, יצחק אשר מברדיטשוב","b":"רב בברדיטשוב-תר, ובנו ר פנחס אליהו על מקומו אחריו."},{"i":7512,"n":"בוסוחובסקי, פנחס אליהו מברדיטש","f":"יצחק אשר מברדיטשוב","k":"בעל אליהו רבא","b":"רב בברדיטשוב-תרם על מקום אביו."},{"i":7513,"n":"בוסוחובסקי, שמואל מטהנטשא","f":"פנחס אליהו מברדיטשוב","bt":"תרכד","b":"רב בטאהנטשא-פלך קיוב-תרנז."},{"i":7514,"n":"בוסטנאי גאון מבבל","b":"ראש הגולה בבבל. השולטן עומר נתן לו את בתו של יזדגירד מלך פרס - ונשאה לאישה לאחר שהתגיירה."},{"i":7515,"n":"בוסי, סעדיה מתימן","b":"דיין בתימן-תקעח וחתם עם ר שלמה בסיס, ור יחיא דחבאש."},{"i":7516,"n":"בוסידאן, דוד ממכנאס","bp":"אזאווייא-מרוקו","b":"צדיק ומלומד בניסים מחכמי מכנאס-שנות ה-ת'. רבים באים להשתטח על קברו."},{"i":7517,"n":"בוסידאן, יוסף מפאס","b":"מחכמי פאס-שנות ה-ת'. בנו - ר מימון."},{"i":7518,"n":"בוסידאן, מימון מפאס","f":"יוסף","bp":"אזאוויא-מרוקו","b":"רב בפאס, אחיו של הצדיק ר דוד בוסידאן ממקנאס. חתם על פסק עם ר חיים טולידנו. (ואולי הוא זהה לר מימון אפלאלו)."},{"i":7519,"n":"בוסידאן, שמואל ממכנאס","f":"מימון","b":"מחכמי מכנאס, חתם-תקמז עם ר רפאל דוד ן עטר. אחיו של ר דוד ממכנאס."},{"i":7520,"n":"בוסייא, יהודה","b":"רב בפאס,חכם שלם"},{"i":7521,"n":"בוסקוביץ בנימין זאב וולף בן שמואל","bt":"1740","dt":"ה'תקעח 1818","bk":[["מאמר אסתר",""],["סדר משנה",""],["שושן עדות",""]]},{"i":7522,"n":"בוסקוביץ חיים בן יעקב","bt":"1705","dt":"ה'תקלה 1775","bk":[["תוצאות חיים",""]]},{"i":7523,"n":"בוסקוביץ, אליעזר"},{"i":7524,"n":"בוסקוביץ, בנימין זאב וולף הלוי","f":"שמואל - מחצית השקל","k":"בעל סדר משנה","bt":"תק","dt":"תקעח - י סיון","b":"מגדולי רבני הונגריה, רב באויבן-תקכט, רב וראש ישיבה באסאד-תקמב, קעלין, פרוסטיץ-תקמו, פעסט-תקנג והיה מחלוקת עם ר משה מינץ מאויבן(=בודה) שהתנגד להפרדות קהלת פעסט - ונאלץ לעזוב, יארמוט ור\"מ בישיבה שם על מקום ר וולף באכלוי, בוניהאד(=בניהאד)-תקסט על מקום ר אברהם ליב מניקלשבורג. בידידות עם החת\"ס. חיבר גם \"מאמר אסתר\". מאמר ממנו ב\"תל תלפיות\" - וייצען תרנב-תרעד. חתם שמו - אזו\"ב. בנו - ר יוסף הו\"ל את ספר אביו \"סדר משנה\".","bk":[["אור המאיר","חסידות"],["אור המאיר (זיטומיר)",""]]},{"i":7525,"n":"בוסקוביץ, דוד מאויבן","b":"רב באויבן-תקמ. חתניו: ר בנימין וולף בוסקוביץ, ר בנימין זאב רפפורט מפאפא."},{"i":7526,"n":"בוסקוביץ, דן יעקב מוינה","dt":"תכז - כט אלול","dp":"וינה","b":"גביר מחכמי וינה, מנהיג מדינה."},{"i":7527,"n":"בוסקוביץ, חיים יעקב מירושלים","f":"יעקב","k":"בעל תוצאות חיים","bp":"ירושלים","b":"מחכמי ירושלים, בשנת תקכט או תקנט בשליחות בפולין, היה בברודי והסכים שם על ספר \"לחם תרומה\" לר אהרן בלטרונמץ, חיבר \"תוצאות חיים\" זאלקווא תקלב."},{"i":7528,"n":"בוסקוביץ, יוסף","f":"בנימין זאב-סדר משנה","b":"הו\"ל ספר אביו - פרג תקף."},{"i":7529,"n":"בוסקוביץ, מרדכי","b":"תלמיד החת\"ס. תלמידו ר יוסף פיש מרוזנברג וכתב עליו."},{"i":7530,"n":"בוסקוביץ, משה מבריסק","b":"רב בבריסק-רע\"ד"},{"i":7531,"n":"בוסקוביץ, פיבל מדיאנ-דיאש","dt":"תקנט - כה אדר","b":"אב\"ד בדיאנדיאש. נכדו ר כלב פיבל ברוין מבודפשט."},{"i":7532,"n":"בוסקוביץ-קעלין, ישכר בר","f":"יעקב","b":"כנראה נכדו של ר שמואל קעלין בעל \"מחצית השקל\"."},{"i":7533,"n":"בוסקילה, דוד מאיגיניסאין","b":"רב באיגיניסאין"},{"i":7534,"n":"בוסקילה, רפאל ממרוקו","b":"רב בכפר יונילאן וסביבתו - מחוז תלוואת בהרי האטלס במרוקו. תלמיד ר משה אזאגורי בעל \"ירים משה\". החל לכהן כרב בגיל 15!."},{"i":7535,"n":"בוסתה, יהודה מאלגיר","f":"שמואל","bt":"קך - בערך","dt":"קץ - בערך","b":"רב בברשך-אלגיר. נזכר בשו\"ת הריב\"ש."},{"i":7536,"n":"בוסתה, שלמה ממראקש","b":"רב במראקש, אחד מארבעה רבנים שנתפסו עם ר אברהם אזולאי."},{"i":7537,"n":"בוסתי, נתן מפאס","b":"מחכמי פאס, בזמן הרשב\"ש שהשיב לו, ור יוסף ששפורטש המזכירו בספרו, ושהביע את קורת רוחו שכבדוהו שנשאל גם הוא יחד עם הרשב\"ש. היה במחלוקת כנגד שילוב האנוסים - בענינים שונים בקהלה."},{"i":7538,"n":"בוסתנאי - ראה הגולה","f":"חנינאי","b":"ראש הגולה בבל."},{"i":7539,"n":"בועבט, אברהם מאלגיר","b":"רב ובקי בדקדוק. מתורתו ב\"עומר השכחה\", וכמה מבני משפחתו נזכרים בשטרות מתלמסאן."},{"i":7540,"n":"בועז, אברהם טוביה מאוסטרליה","f":"טוביה","bt":"תרד","b":"תלמיד ביהמ\"ד לרבנים באמשטרדם. רב באדליד-אוסטרליה-תרל."},{"i":7541,"n":"בוצאל די, משה מרודוס","bp":"שלוניקי","b":"רב ברודוס-שנות ה-ת'."},{"i":7542,"n":"בוצ'קו, אליהו","dt":"תשטז","b":"מייסד ישיבה במונטרה-שוייץ. פרסם מאמרים ב\"בית המדרש\" - מונטרה תש.."},{"i":7543,"n":"בוק, יצחק זאב מדיולא","k":"בעל תולדות יצחק","b":"רב בדיולא-תרל\"ד"},{"i":7544,"n":"בוקאנץ, שלמה נתן הלוי","bt":"תרכז","dt":"תרצח - ה אב","b":"רב פעלים,רב בהלסינגפורס-תרמ\"ט,עלה לא\"י-תרפ\"ד"},{"i":7545,"n":"בוקאעי, יצחק מדמשק","dt":"תרלא - כח אייר","b":"רב בדמשק"},{"i":7546,"n":"בוקארט, אברהם הלוי","f":"שלמה","k":"בעל ספר הזכרון","dt":"רעו","dp":"תוניס","b":"תלמיד ר יעקב לואל-מתלמידי ר יצחק קנפנטון. פילוסוף, מחכמי ספרד, מקובל, פייטן, רב במלגה, בגירוש עבר לתוניס-רנב, פאס. חיבר \"ספר הזכרון\", ספר הקבלה (ונדפס בתוך \"סדר החכמים\"), חיבר גם קונטרס על כללי הניקוד, ועוד. פיוטים ממנו במחזור אלגיר(=ארגיל) ובהם \"מי כמוך אביר יעקב\" ונקרא ר אברהם בן שלמה הצרפתי."},{"i":7547,"n":"בוקיעט, חיים מאיר מחמלניק","b":"פרסם מאמרים ב\"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד."},{"i":7548,"n":"בוקסבוים, אברהם מצאנז","f":"משה גולדס","dt":"תרעט","b":"עבר מצאנז לכהן כשו\"ב בטיסא-עסלר (הונגריה), נאסר שם בעלילה-תרמח. חזר לצאנז והיה מלמד, אחיו ר ירחמיאל אל מקומו אחריו."},{"i":7549,"n":"בוקסבוים, ארמין צבי מפרשבורג","b":"סגן המנהל בביה\"ס של הקהלה החרדית בפרשבורג - לפני השואה."},{"i":7550,"n":"בוקסבוים, דב בר מצאנז","b":"מו\"צ בצאנז-תרפז."},{"i":7551,"n":"בוקסבוים, יהושע מגלנטא","k":"בעל אור פני יהושע","bt":"תרלז","dt":"תשד","b":"תלמיד ר משה הופמן. חסיד מונקאץ. רב במוגנדורף-תרע, רבה האחרון של גלנטא-תרפב על מקום ר יוסף צבי דושינסקי. נספה בשואה. פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":7552,"n":"בוקסבוים, יוסף","dt":"תשד","b":"רב במיהלעוויץ"},{"i":7553,"n":"בוקסבוים-וולף, דב בר מצאנז","f":"משה מצאנז","dt":"תרף","b":"ר משה אב\"ד צאנז היה אביו או זקנו. רב בצאנז (גם בזמן הדב\"ח). גיסו של ר פייביש וולף שהיה גם הוא רב בצאנז (וצאצאיו משפחת וולף-לנדמן)."},{"i":7554,"n":"בוקסבוים-וולף, משה גולדס מצאנז","f":"אברהם מצאנז","b":"אולי אביו ר יצחק יבורניק מצאנז. רב בצאנז ובקראקא אצל ר צבי דוד הלוי. לימד את הדב\"ח בילדותו. חתן ר נתן שהיה רב בצאנז (בזמן הדב\"ח)."},{"i":7555,"n":"בוקסבוים-פטרזייל, נתן מרדכי","f":"ירחמיאל הלוי מצאנז","dt":"תשב","b":"נכד ר משה גולדס. תלמיד ר יהושע פנחס בומבך. חתן ר צבי יעקב ללר מצשינוב. רב בצשינוב, ר\"מ בצאנז. מתלמידיו האדמורים מצשינוב ודומברובה בניו יורק. נספה בשואה."},{"i":7556,"n":"בוקשטנסקי, יהונתן ממינסק","f":"מרדכי מקידאן","b":"גביר במינסק. סייע בהדפסת, \"זרע יצחק\" לר יואל יצחק קצנלנבוגן."},{"i":7557,"n":"בוקשפן, שמעון","b":"פרסם מאמרים ב\"כרם ציון\" - ירושלים תרצה-תשיג - קובץ \"מדרש בני ציון\"."},{"i":7558,"n":"בורג, דוד אבא מנדבורנא","f":"יוסף יוסקא גוטסמן","bt":"תרכא","bp":"נדבורנא","dt":"תרצז","dp":"ירושלים","b":"חתן ר יואל הכהן, היגר לניו יורק-תרעא, עלה לירושלים-תרפט."},{"i":7559,"n":"בורג, יוסף יוסקא מנדבורנא","k":"גוטסמן","b":"מחכמי נדבורנא. בניו ר שמשון זליג, ר דוד אבא."},{"i":7560,"n":"בורגה, שמואל","b":"תלמיד הרדב\"ז המזכירו בשו\"ת הרדב\"ז."},{"i":7561,"n":"בורגו, יוסף חזקיה מפיררה","f":"יצחק ידידיה","b":"רב ורופא בפיררה-תעב, בנו ר ברוך רב לצדו. הסכים על \"ראשית בכורי קציר\" - ונציה-פיררה תעה."},{"i":7562,"n":"בורגו, יצחק ידידיה מפיררה","b":"חתם על פסקים עם רבני פיררה משנת ת\"ו והלאה. דרש בביכ\"נ אשכנזים יחד עם ר פנחס ברוך מונציליסי. מוזכר פסק שלו בהגהות ר חיים מורפורגו ל\"שמש צדקה\". מוזכר גם ב\"עפר יעקב\" לר נתנאל סגרי."},{"i":7563,"n":"בורגו, שמואל ברוך מפיררה","dt":"תצו","b":"רב ורופא בפיררה-תפז. מתשובותיו ב\"פחד יצחק\"."},{"i":7564,"n":"בורגוש, חיים ממצרים","b":"מחכמי מצרים-שנות ה-ת'."},{"i":7565,"n":"בורגוש, שמואל מרודוס","b":"גביר ברודוס-שעה, היה מחלוקת בענינו, ור משה הכהן פסק כנגדו ולמרות תמיכת ר יחיאל באסאן נאלץ ר משה הכהן לעזוב את רודוס לאי כיאו."},{"i":7566,"n":"בורגיל - משפחה","b":"משפחה עתיקה בתונס ויתכן שראשיתה בבעל התוספות ר אברהם מבורג'ל שהיה מגדולי החכמים בצרפת, ויתכן שקשורים גם לר אברהם בן עזוז בורג'ל בעל \"לחם אבירים\" - רבו של המהרשד\"ם בקושטא. ב\"מכלי רבנן\" מספר שהיתה משפחה בשם זה במרוקו ונעלמה - כפי הנראה ברעב הכבד של שנת תץ שבו נספו יהודים רבים, ויתכן שהניצולים עברו אז לתונס."},{"i":7567,"n":"בורגיל, אברהם חיים מתונס","f":"נתן","k":"בעל חוקי חיים","dt":"תרנד - ז שבט","b":"דיין בתונס, חיבר \"חוקי חיים\""},{"i":7568,"n":"בורגיל, אברהם מניקופול","f":"עזוז","k":"בעל לחם אבירים","b":"רב וראש ישיבה בניקופול-שן, תלמיד המהרשד\"ם. גיסו ותלמידו - ר יוסף די נוביש - הו\"ל את ספרו. חברו של ר שמואל איריסה."},{"i":7569,"n":"בורגיל, אליהו חי מתונס","f":"נתן","k":"בעל מגדנות נתן","bt":"תקכ","dt":"לפני ה'תקנב","b":"מחכמי צפון אפריקה, רב בתונס, חיבר \"מגדנות נתן\". הסכים על \"ברית יעקב\"-תקנז.","bk":[["מגדנות נתן [עהש\"ס]",""]]},{"i":7570,"n":"בורגיל, יוסף מתונס","f":"אליהו חי בורגיל","k":"בעל זרעא דיוסף","bt":"תקן","dt":"תרכט-תרלד","b":"רב בתונס. נפטר ללא ילדים. חיבר גם \"ויקן יוסף\". לתולדותיו ב\"מלכי תרשיש\"."},{"i":7571,"n":"בורגיל, משה מפרידבורג","b":"רב בפרידבורג-ש\"פ"},{"i":7572,"n":"בורגיל, נתן מתונס","f":"אברהם","k":"בעל חוק נתן","bp":"תונס","dt":"תקנב - ד חשון","dp":"ירושלים","b":"מחכמי תונס, רב הקהלה האפריקאית והאיטלקית באסא (תונס), בנו - ר אליהו חי, גם צאצאיו שמשו רבנים בתונס. עלה לירושלים. חיבר \"חוק נתן\" ליוורנו תקלח, ועוד."},{"i":7573,"n":"בורגיל, נתן מתונס - ג","f":"אליהו חי","b":"דיין בסוסא-תונס בשנות ה-תר, יחד עם חביריו ר יוסף מועטי ור ישראל כהן טנוג'י."},{"i":7574,"n":"בורגיל, שלמה מתונס","f":"אברהם","k":"שנ\"א - כך חתם","b":"מחכמי תונס. אחיו של ר נתן בעל \"חק נתן\"."},{"i":7575,"n":"בורגין, שמואל הרץ","k":"בעל פון דער אידישער","bt":"1870","bp":"מאליאט","dt":"1949","dp":"ניו יורק","b":"תלמיד ישיבת מייליס בוילנא. רב מטעם בסאבז' ומנהל בי\"ס ממשלתי, עבר לריגה והיה פעיל בתנועת פועלים, גורש לסיביר-1903, ברח והגיע לניו יורק, והיה עתונאי ב\"פארווערטס\", ועוד. חיבר ספרים באידיש, ערך עתון ברוסית \"נובי מיר\" בניו יורק."},{"i":7576,"n":"בורג’ל אליהו חי בן נתן","dt":"ה'תקכ 1760","bk":[["מגדנות נתן",""],["מגדנות נתן א",""],["מגדנות נתן ב",""]]},{"i":7577,"n":"בורגמן, ירחמיאל יצחק מניעשויז","b":"פרסם מאמרים ב\"קובץ דרושים\" - פיעטרקוב תרפג, \"שערי ציון\" - ירושלים תרפא."},{"i":7578,"n":"בורגנסקי, אהרן","bt":"תרמה","dt":"תשב - ו אב","b":"רב בקוזימיר,סנוב"},{"i":7579,"n":"בורגנסקי, ישראל מירושלים","b":"פרסם מאמרים ב\"תורת ירושלים\" - \"תפארת ירושלים\"- \"תורה מציון\" ירושלים תרצו."},{"i":7580,"n":"בורגר, חיים מרדכי","f":"שמואל מאדאסטעבל","bt":"תרלח","bp":"אדאסטעבל","b":"תלמיד השב\"ס. הו\"ל \"שבעה עינים\" לאביו."},{"i":7581,"n":"בורגר, טוביה אברהם מאנטורפן","f":"שמואל מגאלאנטא","k":"בעל טפה מן הים","bt":"תרמד","dt":"תשל - יד אד\"ב","b":"תלמיד הדעת סופר, ור יוסף צבי דושינסקי שסמך אותו-גאלאנטא תרסט. חתן ר נח צבי אולמן מאנטורפן, עבר לשם וכיהן כמלמד. ניצל מהשואה והגיע לאנגליה, עלה לארץ-תשה והתישב בתל אביב."},{"i":7582,"n":"בורגר, יוסף צבי מגאלאנטא","f":"שמואל מזאלא-מיהאלפא","bt":"תרלה","b":"תלמיד השב\"ס. רב בגאלאנטא."},{"i":7583,"n":"בורגר, שמואל מגאלאנטא","f":"משה אברהם מסלק","k":"בעל שבעה עינים","bt":"תרב","bp":"סלק (ליד פאפא)","dt":"תרסו - יט אב","dp":"גאללאנטא","b":"תלמיד הכת\"ס, ור מרדכי רייכנפלד מיאנושהאזא. חתן ר שמשון ויינר משטיינמאנגר. רב בזאלא-מיהאלפא-תרכו, אדאס-טעבעל-תרלט, סעמערין-תרמב, גאלאנטא-תרן."},{"i":7584,"n":"בורד, אליהו מליביטשוב","b":"מחכמי ליביטשוב. תשובה אליו ב\"זיו הלבנון\"."},{"i":7585,"n":"בורה, והב","b":"מחכמי תימן ראב\"ד בקהילות שרעב לפני העליה לא\"י"},{"i":7586,"n":"בורובסקי, יוסף מנ\"י","b":"רב בניו יורק. גיסו של ר אורי מוינשטר מנ\"י. עורך \"היכל התורה\" - נ\"י תרצג, פרסם מאמרים ב\"תבונה\" - קובנא תרפא."},{"i":7587,"n":"בורודיאנסקי, אפרים","b":"פרסם מאמרים ב\"היכל התלמוד\" - ת\"א תשא, \"כנסת ישראל\" - סלובודקה - ירושלים תשא, \"שילה\" - ירושלים תשה."},{"i":7588,"n":"בורוכוב, אבא יעקב הכהן","f":"יחיאל מיכל","k":"בעל חבל יעקב","bt":"תרח - טבת","bp":"דרושנישוק-פלך וילנא","dt":"תרצו - ה אייר","dp":"ירושלים","b":"חתן ר יעקב כהנא משניפישוק. תלמיד ר יהושע ליב דיסקין. נסמך מאת: ר יצחק אלחנן מקובנא. רב במאישיגולא(=מיישאגאלה, מישיגאלע)-תרלג, קופישוק-תרמד-ז, ווקשנה(ואקשנה)-תרנ, פלאצק-תרסא, וילקוביסק-פלך גרודנא-תרסד וראש ישיבה שם (נוסדה ע\"י ר ברוך מרדכי ליפשיץ-תרמז) - ולמדו בה כ-300 תלמידים, פעיל בתנועה הציונית, עלה לירושלים-תרפג והצטרף לבניו הסופרים א.מ. ברכיהו ומ. ברכיהו. בניו גם: ר יחיאל מיכל, ר דובער אב\"ד מאלדן-ארה\"ב. חתנו (לפי יהדות ליטא) ר ישראל יעקב יפה ממנצסטר. מאמר לתולדותיו ב\"היהודי\" - נ\"י תרצו. פרסם מאמרים ב\"מכילתא דרבנן\" - אודסה תרמו, \"שערי ציון\" - ירושלים תרפא."},{"i":7589,"n":"בורוכוב, דב בר הכהן מארה\"ב","f":"אבא יעקב בורוכוב","k":"בעל ראשית בכורים","bt":"תרלג","dt":"תרצט - טז ניסן","b":"רב בגורד, מאלדן-ליד בוסטון-תרסה. פרסם מאמרים ב\"היהודי\" - נ\"י תרצו."},{"i":7590,"n":"בורוכוב, יחיאל מיכל","f":"אבא יעקב בורוכוב","b":"רב במולדן(ארה\"ב)-תר\"צ"},{"i":7591,"n":"בורוכוביץ, ישעיה מאודסה","k":"בעל תקוני הזבח","b":"חסיד ר ישראל מרוזין, ראש השו\"ב באודסה, עבר לסדיגורה-תרנה ומונה ע\"י ר ישראל מסדיגורה לכהן כראש הישיבה. חיבר גם 'אסיפת מאמרים', 'יסוד העבודה'."},{"i":7592,"n":"בורטון, מונטגיו. סיר","bt":"1885","bp":"קורקלי-ליטא","dt":"1952","b":"למד לרבנות בליטא, היגר לאנגליה והקים מפעל בגדים והתעשר. תרם להקדמת קתדרה לשלום העולם באוניברסטיה העברית בירושלים."},{"i":7593,"n":"בורייר, פנחס","dt":"תרצה","b":"דיין בווינה"},{"i":7594,"n":"בורלא יוסף נסים בן חיים יעקב","bt":"1828","dt":"ה'תרסג 1903","bk":[["לקט יוסף",""]]},{"i":7595,"n":"בורלא, אליעזר יהודה מאמריקה","f":"יוסף נסים","bt":"תרמ","b":"מרבני ירושלים, רב באמריקה"},{"i":7596,"n":"בורלא, אפרים מירושלים","b":"מחכמי ירושלים -תרי, ראש ישיבת \"מגן דוד\"-תרי עם ר יעקב שמעון מטאלון."},{"i":7597,"n":"בורלא, דניאל יוסף מקושטא","dt":"תקפא - לפני","b":"גביר בקושטא, אזמיר. סייע בהדפסת \"בעי חיי\"."},{"i":7598,"n":"בורלא, דניאל יוסף משלוניקי","b":"מתורגמן בשלוניקי-תקכה - והיה דין ודברים בינו לראשי הקהלה בענין תשלום המס."},{"i":7599,"n":"בורלא, דניאל יוסף משלוניקי","dt":"תקנא","dp":"שלוניקי","b":"גביר מחכמי לאריסה, עבר לשלוניקי. סייע בהדפסת \"אשדות הפסגה\" לר יוסף נחמולי-תקן. נספד מאת ר רפאל יעקב מנשה."},{"i":7600,"n":"בורלא, דניאל יעקב משלוניקי","b":"מתורגמן בשלוניקי-תקו - והיה דין ודברים בינו לראשי הקהלה בענין תשלום המס."},{"i":7601,"n":"בורלא, דניאל יעקב משלוניקי","dt":"תקנג - יט אדר","dp":"שלוניקי","b":"גביר בשלוניקי ועסק בפדיון שבויים, היה חליפת מכתבים בינו לבין קהלת אמשטרדם בענין זה."},{"i":7602,"n":"בורלא, דניאל משלוניקי","dt":"תרסה","dp":"שלוניקי","b":"דיין בשלוניקי."},{"i":7603,"n":"בורלא, חיים יעקב","b":"רב-שנת תק\"צ"},{"i":7604,"n":"בורלא, חיים יעקב מירושלים","f":"יוסף נסים","k":"חיבר דרוש-כת\"י","bt":"תרז","bp":"ירושלים","dt":"תרפט - יז אב","dp":"ירושלים","b":"מחכמי ירושלים, ראש ישיבת \"חמד בחורים\" לבעלי בתים. בשליחות בצפון אפריקה-תרנט וערביסטן, סייע לאביו והגיה את ספרו \"מקור ישראל\". חתם על קיום גט עם ר חיים דוד סורנגה ור שמעון אשריקי."},{"i":7605,"n":"בורלא, יהודה בכור מירושלים","f":"ישראל יעקב-מקור ישרא","k":"בעל נחלת יהודה","dt":"תקסד - כא תשרי","dp":"ירושלים","b":"מחכמי ירושלים, חתם על תקנה בשנת תקנז, על כתב שליחות ר רפאל אברהם לב אריה ועוד בשנת תקנט, בשליחות ירושלים לארצות ערב-תקס, בהיותו בבגדד אישר את תשובת ר משה חיים עבדאלה בענין עגונה. היה חבר בבית דינו של ר יום טוב אלגזי. הדפיס ספר ובו תשובות אביו ותשובותיו שלו בשם \"מקור ישראל ונחלת יהודה\" ירושלים תרמב. נספד בספר \"מערכי לב\" ח\"א. יש רושמים תאריך פטירתו - תקעד וריבלין קובע תקסד."},{"i":7606,"n":"בורלא, יהודה בכור מירושלים - ב","f":"חיים יעקב","bt":"תקעג","bp":"ירושלים","dt":"תריח - כג שבט","dp":"ירושלים","b":"נכד-אבי אמו מהרי\"ט אלגזי, חתן הגביר נסים פרחי. דיין, חזן, מלמד תינוקות, גבאי צדקה. בניו: ר יעקב חי, ר משה שלמה, ר יהושע."},{"i":7607,"n":"בורלא, יהודה מירושלים","f":"יהושע","k":"בעל בין שבטי ערב","bt":"תרמו","bp":"ירושלים","b":"סופר בירושלים."},{"i":7608,"n":"בורלא, יהושע מירושלים","f":"בכור יהודה","bt":"תריב","bp":"ירושלים","b":"חתן ר יעקב תורג'מן מחברון. גבאי ביה\"כ איסטמבולים בירושלים, וממונה על קבר רחל. בנו - הסופר יהודה בורלא."},{"i":7609,"n":"בורלא, יוסף נסים מירושלים","f":"חיים יעקב","k":"בעל לקט יוסף","bt":"תקפח","dt":"תרסג - א סיון","dp":"ירושלים","b":"מחכמי ירושלים, בשנת תרי חתם על שטר תנאים לר אברהם בכר שמואל הלוי. ור יעקב שאול אלישר כותב עליו בהקדמה לספרו \"וישב יוסף\". היה בשליחות בטריפולי בשנת תרלח. ונבחר לראבד. חיבר \"לקט יוסף\" ירושלים תרס. פרסם מאמרים ב\"המאסף\" - ירושלים תרנו, \"תורה מציון\" - ירושלים תרנה-תרסה.","bk":[["וישב יוסף",""]]},{"i":7610,"n":"בורלא, יעקב מירושלים","f":"יהודה","k":"בעל מרפא לנפש","bp":"ירושלים","dt":"תרנב - כט אדר","dp":"ירושלים","b":"דיין מחכמי ירושלים ומגדולי חזניה, היה חשוך בנים ועסק הרבה בצרכי ציבור. חתם על תקנות שונות. הוציא לאור מספר ספרים וביניהם \"ישמח ישראל\" לר ישראל נג'ארה ירושלים תרלה, ועוד"},{"i":7611,"n":"בורלא, יעקב מירושלים","b":"מחכמי ישיבת \"נוה שלום\" בירושלים-תקיח, מחכמי ירושלים-תקם. תשובה ממנו-תקסד ב\"חקרי לב\". בנו - ר מנחם מחברון."},{"i":7612,"n":"בורלא, יעקב משאראי","b":"חתן הגביר יעקב פלורנטין. הגיע עם חותנו מאישקופיא לשאראי-תצז."},{"i":7613,"n":"בורלא, יצחק משלוניקי","dt":"תקנד","dp":"שלוניקי","b":"גביר בשלוניקי."},{"i":7614,"n":"בורלא, ישראל יעקב מירושלים","k":"בעל מקור ישראל","dt":"תקנז - ד-ח תשרי","dp":"ירושלים","b":"נקרא ע\"ש קרובו ר ישראל יעקב אלגזי. ראב\"ד בירושלים בזמנו של ר יום טוב אלגזי, בשנת תקלד בשליחות עם ר אליהו צבי ור יקר בן אברהם גרשון מקיטוב, חתם בקרפנטרץ-תקלה, והיה אז גם בליוורנו עם החיד\"א. חיבר \"מקור ישראל ונחלת יהודה\" ירושלים תרמב. חתם על תקנות שונות. בנו ר יהודה והשתתף עמו בספרו \"מקור ישראל ונחלת יהודה\". מחכמי ישיבת \"נוה שלום\"-תקיח. הסכים על \"דרך ישרה\"-תקמח. דיין מחכמי ירושלים ומגדולי חזניה, היה חשוך בנים ועסק הרבה בצרכי ציבור. חתם על תקנות שונות. בשליחות באירופה-תקלד יחד עם ר אליהו צבי ור יקר בן אברהם גרשון מקיטוב - שליחות משותפת לקהלה הספרדית והאשכנזית - והיה באיטליה אצל החיד\"א-המזכירו בספרו בהמשך נפרדו ור יעקב הגיע להולנד. הוציא לאור מספר ספרים וביניהם \"ישמח ישראל\" לר ישראל נג'ארה ירושלים תרלה, ועוד"},{"i":7615,"n":"בורלא, מואיז עובדיה משלוניקי","b":"למד רפואה בפאריס. רופא בשלוניקי-תרס."},{"i":7616,"n":"בורלא, מנחם מחברון","f":"יעקב","b":"מחכמי חברון-תקף, נאלץ לצאת בשליחות עצמו-תקצה לאחר הפרעות של הערבים-תקצד - מהם סבל ביותר וקיבל הסכמות מגדולי הרבנים בחברון וירושלים, לאחר זמן בשליחות קהלת חברון."},{"i":7617,"n":"בורלא, משה משלוניקי","dt":"תקסב - כט תמוז","dp":"שלוניקי","b":"גביר בשלוניקי, סייע רבות ליהודי שלוניקי, גם כשתדלן וגם בכספו. נספד ע\"י ר יעקב מנשה."},{"i":7618,"n":"בורלא, עובדיה מנחם משלוניקי","dt":"תרס","dp":"שלוניקי","b":"רופא בשלוניקי, נדב מגרש לטובת פליטי רוסיה שהתישבו בעיר."},{"i":7619,"n":"בורלא, שבתי מיפו","f":"שלמה","k":"בעל מגד ציון","bt":"תרל","bp":"יפו","b":"חתן הגביר ר עזריה די בוטון, ותלמיד בישיבתו בירושלים, דיין ביפו, בזמן מלחמת העולם ה-I נאלץ לעזוב את הארץ וכיהן כרב בקליז, קליקיה-סוריה, ארם צובא-תרפא, ביירות-תרפד. פרסם מאמרים ב\"המאסף\", ועוד. חיבר ספרים בעניני מוסר ושו\"ת - בכת\"י. מתורתו ב\"ישכיל עבדי\" לר עובדיה הדאיה."},{"i":7620,"n":"בורלא, שמואל מירושלים","bt":"ינינה-יון"},{"i":7621,"n":"בורלינר, אלחנן מטבריה","dp":"טבריה כנראה","b":"מחכמי האשכנזים בטבריה הגיע כנראה בשנת תקכד, בעליה הראשונה של החסידים, חתם על כתב שליחות ר רפאל אברהם לב אריה בשנת תקמה, נכדו ר שמריה בן משה בעל \"תקנתא דמשה\","},{"i":7622,"n":"בורלנד, אלחנן יהודה מאנושישק","dt":"תשג","b":"רב באנושישק"},{"i":7623,"n":"בורמן, חיים משה (מרדכי)","f":"יעקב","bt":"תרלב","bp":"אלקניק-פלך וילנא","b":"תלמיד ישיבת באלטערמאנין-פלך וילנא אצל הר\"מ ר יוסף יאנקעלעוויץ, ישיבת סלובודקא, רב בקאלוגה-תרס\"ד"},{"i":7624,"n":"בורנפרינד, יעקב דוד מאושפיצין","k":"הו\"ל דרכי חיים","b":"חסיד בובוב מאושפיצין-תרעז. הכין לדפוס \"דרכי חיים\"-תרפג."},{"i":7625,"n":"בורנשטין, א' בן ציון מבנימינה","f":"שמואל בורנשטיין","k":"בעל רסיסי טל","dt":"תשכג - א אלול","b":"רב בבנימינה"},{"i":7626,"n":"בורנשטין, א' יהושע השל","k":"בעל סנהדרי קטנה","b":"שנת תר\"מ"},{"i":7627,"n":"בורנשטין, אברהם אליהו מירושלים","f":"יחיאל מיכל בן זרח","k":"בעל לחם שעורים","dt":"תרפח - אחרי","dp":"ירושלים","b":"ממשפחת הגר\"א - ונקרא ע\"ש הגר\"א וע\"ש אחיו - ר אברהם. פרסם מאמרים ב\"ועד חכמים\" - ירושלים תרפג. חיבר גם \"שובע שמחות\", \"מנחה חדשה\"."},{"i":7628,"n":"בורנשטין, אברהם מסוכטשוב","f":"זאב נחום מביאלא","k":"אדמור מסוכטשוב","bt":"תקצט","dt":"תרע - יא אד\"א","b":"חתן ר מנחם מנדל מקוצק, בעל חדושי הרי\"ם ור חנוך הניך מאלכסנדר. רב בפרצוב(=פארצווא)-תרכג, רב ואדמור בקרשניביץ-תרל, נשלסק-תרלו, סוכטשוב-תרמג והקים שם ישיבה. בעל \"אבני נזר\", \"נאות דשא\", ועוד. מתורתו ב\"כרם בית שמואל\" - פיעטרקוב תרצא. לתולדותיו ב\"אביר הרועים\" לר צבי הירש ממלוק.","bk":[["אבני נזר",""]]},{"i":7629,"n":"בורנשטין, אברהם מפלונגיאן","b":"מו\"ץ בפלונגיאן-תקע. בנו - ר צבי הירש מליבאוי."},{"i":7630,"n":"בורנשטין, אברהם מקוטנא","f":"שמואל מסוכטשוב","k":"אדמור מסוכטשוב קוטנא","bt":"תרעא","dt":"תשב - אלול","dp":"אוטואצק","b":"חתן ר יעקב בונם בן ר שמואל צבי מאלכסנדר. רב בקוטנא-תרצד אצל גיסו ר יצחק יהודה טרונק, ורב ואדמור על מקומו אחריו-תרצט. פרסם מאמרים ב\"בית אברהם\" - וארשא תרצד."},{"i":7631,"n":"בורנשטין, אברהם מראווא","b":"ראב\"ד בראווא-תר\"ס"},{"i":7632,"n":"בורנשטין, אהרן מלודז","dt":"תש","b":"רב בלודז"},{"i":7633,"n":"בורנשטין, אהרן משטוקשטין","b":"תלמיד החוזה מלובלין, היהודי הקדוש מפשיסחא ור דוד מללוב. רב בשטוקטשין. בנו ר זאב נחום מביאלא ונכדו האדמור ר אברהם מסוכטשוב."},{"i":7634,"n":"בורנשטין, אליעזר דוד מקראקא","f":"נחמן הלוי","bt":"תקס","bp":"זאוויחוואסט","dt":"תריח","b":"אחיו ר שאול - חותנו של ר אהרן הירשברג. חתן ר שלמה הכהן ברטרם אב\"ד שטעקטשין וקראקא. היה רב בקראקא, רב בזלושיץ."},{"i":7635,"n":"בורנשטין, דוד מסוכטשוב","f":"שמואל-שם משמואל","k":"אדמור מסוכטשוב","bt":"תרל-תרלח","bp":"נשלסק","dt":"תשג - ח כסלו","dp":"וארשא","b":"חתן ר חיים ישראל מפילוב-ונפטרה לפני הנישואין, ובזיוו\"ש חתן החסיד ר מרדכי וינגוט מזדונסקא-ואליא. רב בוישגראד-תרסז וראש ישיבה שם, טומשוב-תרעט, זגירז, אדמור על מקום אביו-תרפו והתישב באוטואצק, פביאניץ, קולומנא ולודז-תרצז (חילק זמנו ביניהם) והקים בלודז את ישיבת אביו \"בית אברהם\". ביקר בארץ-תרפד ותרצה. נספה בשואה. חיבר \"חסדי דוד\", ועוד. מתולדותיו ב\"מלכות בית דוד\". הניח כת\"י רבים - ואבדו."},{"i":7636,"n":"בורנשטין, זאב נחום אליהו מביאל","f":"אהרן משטוקטשין","k":"בעל אגודת אזוב","r":"אבי האבני נזר","bt":"ה'תקפא","dt":"תרמה - יט אלול","b":"מגדולי תלמידי ר מנחם מנדל מקוצק. רב בבנדין, אלקוש(=עלקוש), ביאלא. מתורתו ומאמר לתולדותיו ב\"בית אברהם\" - וארשא תרצד. בניו - ר אברהם בעל אבני נזר, ר מאיר.","bk":[["אגודת אזוב",""]]},{"i":7637,"n":"בורנשטין, זלמן מויליצקה","b":"מחכמי ויליצקה (ליד קלסני - ולשאר היהודים לא הותר לעבור לויליצקה). החזיק בביתו למדנים כדי ללמוד עם ילדיו ובהם - ר יוסקי צנזר ור משה חריף גולדז בוקסבוים."},{"i":7638,"n":"בורנשטין, חנוך הניך מסוכטשוב","f":"שמואל מסוכטשוב","k":"אדמור מסוכטשוב","bt":"תרנז","dt":"תשכה - כו אלול","b":"חתן ר נתן נחום רבינוביץ מקרימלוב האדמור מרדומסק. סירב לרבנות ועלה לארץ-תרפד. עורך ה\"הד\". לאחר השואה נתמנה לאדמור מסוכטשוב בירושלים. הו\"ל ספרי אבותיו ואחיו האדמור. מתורתו ב\"נאות דשא\"."},{"i":7639,"n":"בורנשטין, יוסף מזלושיץ","f":"אליעזר דוד מקראקא","b":"רב בזלושיץ."},{"i":7640,"n":"בורנשטין, יחיאל מיכל מטרסטינא","f":"זרח ן תומר","bt":"תקעח","dt":"תרנב","b":"אב\"ד טרעסטינא-ליד הורדנא. בנו ר אברהם אליהו (ע\"ש הגר\"א ואחיו ר אברהם)."},{"i":7641,"n":"בורנשטין, יקותיאל זלמן מקרעזין","b":"פרסם מאמרים ב\"קובץ דרושים\" - פיעטרקוב תרפג."},{"i":7642,"n":"בורנשטין, ישראל אהרן מקראקא","f":"זלמן מויליצקה","dt":"תרמו","b":"תלמיד דייני קראקא - ר משה חריף ור יוסקי צנזר. חתן הגביר ר זלמן פוזנר מוארשא. גיסו של רד\"ב מייזלש אב\"ד קראקא, (היה במחלוקת עם החסידים בקראקא). התישב באייזנשטט (ליד וינה)."},{"i":7643,"n":"בורנשטין, ישראל הלוי","k":"בעל כרם ישראל","bt":"תרם","bp":"זליחוב","dt":"תשג","b":"רב ברייוויץ, קאמינקא-תרעח, פלונסק-תרפג. נספה בשואה."},{"i":7644,"n":"בורנשטין, מאיר","f":"זאב נחום -אגודת אזוב","bt":"תריא","dt":"תרצב","b":"חתן אחיו ר אברהם מסוכטשוב בעל אבני נזר. מקורב לר מנחם מנדל מקוצק ואחר כך לאדמור מאלכסנדר. סירב לרבנות ועסק במסחר. הגיע לארץ-תרנא עם גיסו בעל שם משמואל בשליחות האדמור מסוכטשוב. מתורתו בספר 'אגודת אזוב'"},{"i":7645,"n":"בורנשטין, מנחם מלודז","b":"פרסם מאמרים ב\"קול תורה\" - וארשא תרסח."},{"i":7646,"n":"בורנשטין, מנחם שלמה מסוכטשוב","f":"חנוך הניך מסוכטשוב","k":"אדמור מסוכטשוב רדומס","bt":"תרצה","dt":"תשל - כז אב","b":"נכד אדמורי סוכטשוב ורדומסק. חתן ר דניאל הלוי מובשוביץ מתל אביב-נכד ר מרדכי האדמור מלכוביץ. רב שכונת \"יד אליהו\" בתל אביב, אדמור מסוכטשוב על מקום אביו-תשכה ואדמור גם לחסידי רדומסק (בהיותו נכד האדמור). מתורתו ב\"נאות דשא\"."},{"i":7647,"n":"בורנשטין, מרדכי שרגא פיבל","f":"יעקב קופיל","k":"בעל זכרון בספר","bt":"תרי","dt":"תרס","b":"מחכמי טארנוב. חיבר \"זכרון בספר\" קראקא תרמו."},{"i":7648,"n":"בורנשטין, נח מארה\"ב","b":"ר\"מ בישיבת מיר. פרסם מאמרים ב\"מרכז התורה\" - מונטריאול תשב, \"התבונה\" - נ\"י תשז - קובץ תלמידי ישיבת מיר."},{"i":7649,"n":"בורנשטין, צבי הירש מליבאוי","f":"אברהם מפלונגיאן","bt":"תקעב","bp":"פלונגיאן","dt":"תרד - ז ניסן","b":"מחכמי לויקאווא, רב בליבאוי-תר על מקום ר משה יצחק סגל (לבקשתו של ר משה יצחק)."},{"i":7650,"n":"בורנשטין, שמואל יצחק","f":"מנחם שלמה מסוכטשוב","k":"אדמור מסוכטשוב א\"י","b":"חתן ר אליהו שטרנבוך מאנטורפן-חתנו של ר ברוך מסערט (שושלת קוסוב). ראש ישיבת \"אבני נזר\" בירושלים. אדמור מסוכטשוב בירושלים על מקום אביו."},{"i":7651,"n":"בורנשטין, שמואל מסוכטשוב","f":"אברהם מסוכטשוב","k":"אדמור מסוכטשוב","bt":"תרטו","dt":"תרפו - כד טבת","b":"חתן ר ליפמן ליטמנוביץ-חתנו של ר שלמה מרדומסק, ובזיוו\"ש חתן ר משה נתן כהנא שפירא מקשונז בעל \"שמן למאור\". אדמו\"ר בסוכאטשוב-תרעא על מקום אביו וראש הישיבה \"בית אברהם\", בזמן מלחה\"ע ה-I עבר עם הישיבה ללודז, ומשם לזגירז. סייע לאביו בהדפסת ספריו. ביקר בארץ-תרנא בשליחות אביו כדי לרכוש אדמה ולא עלה בידו. ממייסדי אגו\"י. חיבר \"שם משמואל\", \"נאות דשא\" ועוד.","bk":[["שם משמואל – תורה ומועדים והגדה של פסח",""]]},{"i":7652,"n":"בורק, אהרן דוד מנ\"י","f":"חיים נתן","k":"בעל פרחי אהרן","bt":"תרנג","bp":"פופליאן-ליטא","dt":"תשכא - טז תשרי","b":"תלמיד קבוץ זאגער אצל ר בן ציון פלדמן, ישיבת טלז. נסמך מאת: ר יוסף ליב בלוך, ר יהודה ליב גורדון מלוזמה, ועוד. חתן ר אלי' אינזלבוך. רב ביהכ\"נ \"עץ חיים וולוזין\" בניו-יורק-תרעג, רב ביהכ\"נ \"אהל משה\" בניו יורק, ר\"מ בישיבת ר יצחק אלחנן. פרסם מאמרים ב\"הדנו\" - נ\"י תרפה, \"נר מערבי\" - נ\"י תרפד - קובץ ישיבת ר יצחק אלחנן, \"פרי עץ חיים\" - טלז תרצט - קובץ תלמידי ישיבת טלז, \"קונטרס מיוחד\" - נ\"י תשא - דברי תורה מועידת המזרחי, \"תלפיות\" - נ\"י תשד. חבר בועד הרבנים באמריקה, פעיל צבור."},{"i":7653,"n":"בורר, אברהם יהושע מפודקמין","b":"דיין בפודמקין-תרך, בנו ר מרדכי אריה מילא את מקומו."},{"i":7654,"n":"בורר, זלמן מארה\"ב","b":"רב בוילקסבורי-ארה\"ב. פרסם מאמרים ב\"כרם בית שמואל\" - פיעטרקוב תרצב - כתב עת תלמידי ישיבת אלכסנדר, \"כרמנו\" - אלכסנדר-לודז תרצג."},{"i":7655,"n":"בורר, ישראל ליב מיבלונוב","b":"שו\"ב ביבלונוב-תרע."},{"i":7656,"n":"בורר, מרדכי אריה ליב מפודקמין","f":"אברהם יהושע מפודקמין","b":"רב בפודקמין על מקום אביו. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד."},{"i":7657,"n":"בורר, שלמה זלמן מהרימלוב","f":"יחיאל","k":"בעל דברי מהרז","bt":"תרך","dt":"תש","b":"חסיד וגבאי האדמור ר ברניו פרידמן מבויאן, תושב צ'ורטקוב ועבר לבויאן. חיבר \"דברי מהר\"ז\" וינה תרפז."},{"i":7658,"n":"בורריץ-זרזים, חואתי","b":"פרסם מאמרים ב\"אוצר התורה\" - ג'רבה תרץ."},{"i":7659,"n":"בורשודי-קליין, משה יוסף","b":"חתן ר יהודה גרוסמן מאיפאלשאג. רב בקעטשקעמט."},{"i":7660,"n":"בורשטין, אביעזר מאושפיצין","f":"אלתר משה מרדכי","k":"בעל מורי דעה","bt":"תרעה","bp":"גובורובה","dt":"תשנו","b":"התישב באושפיצין. ניצל מהשואה, עלה לחיפה וניהל כפר נוער. חיבר \"מורי דעה\" תל אביב תשך, ועוד."},{"i":7661,"n":"בורשטין, אברהם אהרן מטאווריג","f":"יהושע הכהן בלומנטל","k":"בעל נר אהרן","bt":"תרכז","bp":"קמניץ-ליטא","dt":"תרפו - יט כסלו","dp":"ירושלים","b":"חתן ר ליב קיידונר מוויסוקי-ליטובסק. כונה העילוי מויסוקי. ר\"מ בסלובודקה-בגיל 18, בגלל מחלוקת על סדרי הלימוד עבר לקעלם. רב בציטוביאן(=ציטליאן), ריטובה, אניקשט, סלנט-תרס, שאדובה-תרסא, טאווריג-תרסב על מקום ר שלמה שלוסברג ור שמואל אביגדור פיבלזון על מקומו אחריו., הוצעה לו רבנות נוברדוק ובסובאלק על מקום ר יחיאל מיכל אפשטין - אך סירב כשנודע לו על מיעוט המתנגד לו. בהיותו בשאוולי בזמן מלחה\"ע ה-I העלילו עליו כי הוא מרגל גרמני ונידון למות אך בהשתדלות הכומר המקומי בוטל העונש ונידון לגירוש, ראש ישיבה בבוגורודסק - עד סגירתה בידי הרוסים, רב בצ'רקסי, ניצל מהפרעות שם וחזר לליטא. עלה לירושלים-תרפד והיה ראש ישיבת \"מרכז הרב\". חתנו ר משה פרנקל הו\"ל את ספרו \"נר אהרן\" תל אביב תש. ספרים נוספים בכת\"י נשרפו בתלאותיו באירופה. פרסם מאמרים ב\"מאסף דרושי\" - וילנא תרסט. מתורתו בספרי גדולי דורו ובהם \"מקור ברוך\" לר ב\"מ גינצבורג, ועוד."},{"i":7662,"n":"בורשטין, אלחנן","dt":"תש","b":"רב בריגא"},{"i":7663,"n":"בורשטין, אלתר משה מרדכי","bt":"תרלט","b":"רב בטשערווין-פלך לומזה-תרסט."},{"i":7664,"n":"בורשטין, אלתר משה מרדכי","dt":"תשג","b":"רב בנדבורנה"},{"i":7665,"n":"בורשטין, בן ציון מיארישוב","f":"צבי אריה מיארישוב","bt":"תרנז","b":"רב ביארישוב-פודוליה-תרסח על מקום אביו."},{"i":7666,"n":"בורשטין, דב בר מבוטושאן","f":"יחיאל מיכל","k":"בעל חכמה ומוסר","bt":"תרנב","dt":"תשלד - יג ניסן","b":"חתן ר משלם פיבש מיאסי בן ר יעקב יצחק. רב בבטושאן, דיין בתל אביב-תשיח. פרסם מאמרים ב\"המגיד\" - סטמר תרפח."},{"i":7667,"n":"בורשטין, חיים דוד","b":"ר\"מ בריגה-תרפ\"ה"},{"i":7668,"n":"בורשטין, חיים זאב וולף מזלוטשו","f":"צבי הירש","dt":"תרג (או תקעא)","b":"תלמיד ר ישכר דב בער מזלוטשוב ורשם את תורתו ב\"מבשר צדק\". רב בבוזנוב-תקעה, זלוטשוב-תקעז על מקום ר אברהם חיים מזלוטשוב. בנו ר יצחק פנחס דוד על מקומו אחריו (ויתכן שדוקא בנו ר דב מבוזנוב)."},{"i":7669,"n":"בורשטין, חיים ישראל","b":"מחכמי דזיקוב-תרנט, ממשתתפי \"אהל מועד\"."},{"i":7670,"n":"בורשטין, יהודה מגודיליעווא","f":"משה","bt":"תרלב","b":"רב בגאדלווע-פלך סובאלק-תרס."},{"i":7671,"n":"בורשטין, יהושע מארה\"ב","f":"מנחם מנדל","bt":"ויסקוב-פולין","bp":"תרעח","b":"תלמיד ישיבות \"תפארת ירושלים\", תורה ודעת\", ישיבת ר ישראל מאיר הכהן בניו יורק. נסמך מאת: ר יהודה ליב פדר, ר יוסף רוזן, ר אלחנן צבי גוטרמן. רב בביכנ\"ס ישראל הצעיר בניו יורק, וושינגטון-תשב. חבר אגודת הרבנים באמריקה ומזכיר ועד הרבנים בעיר וושינגטון."},{"i":7672,"n":"בורשטין, יוסף חיים מלובלין","b":"מנהל ישיבת \"תורת נצח\" בלובלין-תרצה."},{"i":7673,"n":"בורשטין, יוסף יחיאל מיכלמן","b":"אב\"ד זבריז-תרכה, תשובות אליו \"בית שלמה\"."},{"i":7674,"n":"בורשטין, יוסף מזבריזא ויארישוב","b":"רב בזבריא, יארישוב-פודוליה-תרכ. הניח חדושים בכת\"י. בנו - ר ישעיה מליטניוועץ"},{"i":7675,"n":"בורשטין, יחזקאל","b":"פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":7676,"n":"בורשטין, יחיאל מיכל מפילעשט","f":"יהושע","k":"בעל מי השילוח -בכת\"י","bt":"תרלב","b":"נכד ר יוסף מגריידינג, ונכד-אבי אמו ר ליבוש מסטניסלב. חתן נכדת המגיד ממזריטש. רב בפילשט(=פילעשט)-בסרביה-תרנה. נסמך מאת:ר אלתר מקונסטנטין, ר ישראל קיטובר מפעלשטין, ועוד. בנו - ר דב."},{"i":7677,"n":"בורשטין, יעקב יצחק מבוטושן","b":"פרסם מאמרים ב\"דגל התורה\" - אויבר-וישווה תרפח."},{"i":7678,"n":"בורשטין, יצחק איזיק מזלוטשוב","f":"יחיאל מיכל","k":"בעל חיבת הקדש","b":"רב בזלוטשוב. חיבר \"חיבת הקדש\" למברג תרט."},{"i":7679,"n":"בורשטין, יצחק מאסטרלנקה","f":"שלמה","bt":"תרכט","bp":"לומזה","dt":"תשג","b":"רב בפנטניצא-פלך לומזה-תרנד, אסטרלנקה-פלך לומזה-תרסח."},{"i":7680,"n":"בורשטין, יצחק פנחס דב מזלוטשוב","b":"אב\"ד בוזנוב-תרד, על מקום אביו, רב בזלוטשוב על מקום אביו, ובנו ר צבי על מקומו אחריו. תשובה אליו \"חסד לאברהם\"."},{"i":7681,"n":"בורשטין, ישעיה מליטניוועץ","f":"יוסף מזבריזא","bt":"תרכב","b":"רב בלייטניוועץ-פודוליה-תרנז."},{"i":7682,"n":"בורשטין, משה אליהו מארעל","f":"יעקב","k":"בעל ויואל משה - כת\"י","bt":"תריח","b":"תלמיד ר ישראל נפתלי מוילקומיר. רב בבאבט-פלך קובנא-תרלח. נסמך מאת: ר יצחק אלחנן מקובנא."},{"i":7683,"n":"בורשטין, משה יוסף מבורשטין","f":"צבי הירש מברודי","dt":"תקסג","dp":"בורשטין","b":"אבי משפחת בורשטין. רב בבורטשין. בניו ר צבי הירש מזלוטשוב, ר שמואל ישראל רוהטינר."},{"i":7684,"n":"בורשטין, משה מטראג","b":"רב בטראג-תר\"ע"},{"i":7685,"n":"בורשטין, מתתיהו מזולטנשה","bt":"תרח","b":"מו\"צ בזולוטונושה-תרמח, רב שם-תרסא. פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס. תשובה אליו מר חיים ברלין ב\"המסלה\" - נ\"י תרצו (ע\"י אחיינו - ר משה דוד ריבקין)."},{"i":7686,"n":"בורשטין, נחום מלבוב ונדבורנה","f":"צבי הירש מסאסוב","bt":"תר","bp":"סאסוב","dt":"תרעה","b":"חסיד פרימישלן. תלמיד ר יהודה ליבישי הלפרין מחורוסטקוב. אב\"ד נדבורנה-תרסא, עבר להונגריה. גיסו של ר ברוך פנחס רבינוביץ האדמור מימפולי-סקוליע. חתן ר אברהם חיים רדליך ממיקולייב. פרסם מאמרים ב\"יגדיל תורה\" - ברלין-קראקא תרנא."},{"i":7687,"n":"בורשטין, פנחס משה מבראזן","f":"צבי הירש","r":"חידושיו נמצאים אצל ר\"י וויס גאב\"ד נוה אחיעזר","bt":"תקפט","bp":"בראזן","dt":"תרסו - כא חשון","b":"נכד ר דב הלפרין מבריסק. בזיוו\"ש חתן ר משלם ישכר הורביץ מסטניסלב בעל \"בר ליואי\". מחכמי בראזין, אב\"ד סרעט-תרס (בוקובינה). ממיסדי \"מחזיקי הדת\" בלמברג. הגהות ממנו למסכת פסחים נדפסו ב\"זכור לאברהם\" תשסב. לתולדותיו \"סיני\" מאת ר משה ליטר.","bk":[["חידושים על העין יעקב (כת\"י)",""]]},{"i":7688,"n":"בורשטין, צבי","b":"רב בפרימישלן-תרי."},{"i":7689,"n":"בורשטין, צבי אריה מיארישוב","dt":"תרסח","b":"רב ביארישוב, ובנו ר בן ציון על מקומו אחריו-תרסח."},{"i":7690,"n":"בורשטין, צבי הירש מססוב","dt":"תרמז - בערך","b":"רב בסאסוב-תרי. המהרשק השיב לו."},{"i":7691,"n":"בורשטין, צבי מזלוטשוב","f":"יצחק פנחס (או דב)","b":"רב בזלוטשוב על מקום אביו וזקנו - ר חיים זאב."},{"i":7692,"n":"בורשטין, ראובן דוד מקמניץ","f":"יהושע הכהן בלומנטל","k":"בעל דברי רד\"ק","dt":"תשג","b":"רב בקמניץ-ליטא. נספה בשואה. בספרו \"דברי רד\"ק\" מתיחס לחדושים בקובץ \"נר מערבי\" - נ\"י תרפד - קובץ ישיבת ר יצחק אלחנן."},{"i":7693,"n":"בורשטין, שמואל הכהן משיטאווא","f":"שמחה מפראנפיל","k":"בעל מעדני שמואל","bt":"תרכ","dt":"תרעז","b":"נכד ר שמואל מלחוביץ בן ר שמחה כהנא מדקטירבורג בן אברהם כהנא מדוישוביץ בן ישראל כהנא מדליזענציק - מצאצאי הרמ\"א. חסיד האדמור ר דוד משה מצורטקוב. רב בשאטאווא(=שיטאווא)-פודוליה-תרמז. חיבר גם \"מנחת שבת\", \"מנחת יו\"ט\" - עם הערות ר שלום מרדכי מברעזן."},{"i":7694,"n":"בורשטין, שמחה הכהן מפראנפיל","f":"שמואל","bt":"תקצח","b":"רב בפראנפיל(=פרמאפיל)-פודוליה-תרלה. בניו - ר שמואל משיטאווא, ר נחום. חתנו - ר גדליה פעחטיר מדמביץ."},{"i":7695,"n":"בורשטין, שמעון פנחס מירושלים","dt":"תרצג","dp":"ניו יורק - ירושלים","b":"מחכמי ירושלים, עבר לניו יורק."},{"i":7696,"n":"בוש, שלום","b":"רב בקראסילוב-תר\"ס"},{"i":7697,"n":"בושאל די - משפחה","b":"משפחה ותיקה בשלוניקי במשך כמאתים שנה, קמו מהם רופאים, פרנסים ותלמידי חכמים."},{"i":7698,"n":"בושאל די, דוד משלוניקי","dt":"תף","dp":"שלוניקי","b":"גביר בשלוניקי, וגבאי התלמוד תורה."},{"i":7699,"n":"בושאל די, דוד משלוניקי","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":7700,"n":"בושאל די, דוד משלוניקי - א","dt":"תיט - א ניסן","dp":"שלוניקי","b":"גביר מראשי קהלת שלוניקי, פקיד על חברת ת\"ת."},{"i":7701,"n":"בושאל די, חיים עובדיה משלוניק","f":"יעקב עובדיה","k":"בעל באר מים חיים","dt":"שכה","b":"גלה מספרד-רנב ועבר לקושטא, מחשובי הפוסקים, תלמיד הרא\"ם בקושטא, מרביץ תורה בקהילת קטלוניה בשלוניקי-רצ על מקום ר אליעזר השמעוני, חיבר \"באר מים חיים\", \"מקור חיים\". מחותמי \"הסכמות הקהל\" בשלוניקי. נספד ע\"י ר סעדיה לונגו."},{"i":7702,"n":"בושאל די, יוסף משלוניקי","dt":"רפט - כב שבט","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":7703,"n":"בושאל די, יצחק משלוניקי","k":"די בושלדו","dt":"תצח","dp":"שלוניקי","b":"רב בשלוניקי וראש ישיבה. מתלמידיו ר אהרן אמריליו שהביא ממנו בספרו"},{"i":7704,"n":"בושאל די, יצחק משלוניקי","dt":"רפג","b":"רופא בשלוניקי"},{"i":7705,"n":"בושאל די, יצחק משלוניקי","dt":"תיב - יז אייר","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":7706,"n":"בושאל די, משה מצידון ורודוס","f":"שלמה בן משה","k":"בעל ישמח משה","dt":"תם","dp":"רודוס","b":"בן לאחד מראשי קהילת צידון יחד עם אביו, עלה לצפת בילדותו ולמד אצל גדולי צפת. לאחר שנהרגו אביו וזקנו, הגיע לרודוס ונתמנה שם לרב-תכא ור דוד חיים הלחמי ממצרים על מקומו אחריו. בנו - המיר את דתו."},{"i":7707,"n":"בושאל די, משה עובדיה","f":"חיים עובדיה די בושל","b":"רב בלמגורשי קטלוניה בשאלוניקי-ש\"מ"},{"i":7708,"n":"בושבילא, מרדכי מפאס","b":"מקובל מחכמי פאס - שנות ה-ת'. בנו - ר יוסף שרצה לעלות לארץ-תצז."},{"i":7709,"n":"בושושה, יוסף מאלגיר","bt":"תמ - בערך","dt":"תקי - בערך","b":"רב בקצמטינא."},{"i":7710,"n":"בושושה, נתן מקצמטינא","b":"נזכר ב\"חוט המשולש\"."},{"i":7711,"n":"בושושה, פרג' מאלגיר","f":"משה","b":"רב ומשורר בקצמטינא. פיוט ממנו ב\"זמירות ישראל\" לר\"י בן עולייל - כת\"י. העתיק מחזור מנהג קצמטינא."},{"i":7712,"n":"בושושה, שלום מאלגיר","bt":"שן - בערך","dt":"תי - בערך","b":"רב ודיין בקצמטינא-אלגיר. נזכר ב\"חוט המשולש\"."},{"i":7713,"n":"בושושה, שלום מקצמטינא","bt":"[שן]","dt":"תי - בערך","b":"רב דויין בקצמטינא."},{"i":7714,"n":"בושכין, אברהם מלוקא","b":"מחכמי אשכנז-ר' וישב בעיר לוקא עם חברו ר משה רשם. נזכר בשו\"ת מהר\"ם מינץ."},{"i":7715,"n":"בושערה, אברהם מאלגיר","f":"רפאל יעקב","k":"בעל ברית אברהם","b":"רב ומקובל, נגיד באלגיר על מקום אביו. תמך בהוצאת ספרי רבני אלגיר, וסייע ליהודי ארץ ישראל. חתנו - ר דוד מועטי מליוורנו בעל \"יוסף דוד\"."},{"i":7716,"n":"בושערה, יוסף מאלגיר","f":"יעקב","bt":"תס - בערך","dt":"תקל - בערך","b":"תלמיד ר יהודה עייאש. רב בקהלת \"רב\" באלגיר. חיבר הקדמה לספר רבו - \"וזאת ליהודה\". חיבר שירים ובהם לכבוד הספרים \"חסד לאברהם\", \"פי צדיק\". קובץ תשובות ממנו - ואבד. תשובות ממנו בספרי חכמי דורו. התנגד להתפשטות לימוד הקבלה. תמך ביהודי ארץ ישראל, וסייע בהדפסת ספרי חכמי אלגיר. נזכר גם ב\"פרי צדיק\"."},{"i":7717,"n":"בושערה, יוסף מאלגיר","f":"אברהם","dt":"תקכד - לפני","b":"מחכמי אלגיר. הו\"ל \"פרי צדיק\", וסייע בהדפסת \"חסד לאברהם\" ועוד. תמך ביהודי ארץ ישראל. אחיו של ר רפאל יעקב."},{"i":7718,"n":"בושערה, רפאל יעקב מאלגיר","f":"אברהם","dt":"תקכח","b":"נמנה על קהל ליוורנו באלגיר, נגיד הקהלה-תצה ומקורב למלכות. סייע בהדפסת \"לחם יהודה\" לר יהודה עייאש."},{"i":7719,"n":"בושקא, הלל מניו יורק","dt":"תשכ","b":"רב בברוקלין"},{"i":7720,"n":"בושקא, משה מטומשוב","f":"צבי הירש בשקא","bt":"תקכה","dt":"תרח","b":"רב בטאמשוב,עבר לברודי"},{"i":7721,"n":"בושקא, משה שלמה זלמן מקוריץ","f":"בנימין בושקא","dt":"תקעו - ו שבט","b":"רב בקוריץ, קראקא-תקסה, בגלל מחלוקת החסידים והמתנגדים עבר לוארשא. הסכים על \"שירה לחיים\" וארשא תקעד, ועוד. שמו היה משה והמגיד מקוזניץ הוסיף לו את השם \"שלמה זלמן\". אחיו - ר צבי הירש זאמושט בושקא בעל \"תפארת צבי\". גיסו ר עזריאל הורביץ - \"ראש הברזל\". (תאריך פטירתו נרשם גם ו טבת)"},{"i":7722,"n":"בושקא, צבי הירש מברוד","f":"בנימין בושקא","k":"בעל תפארת צבי","bt":"תצט-תק","bp":"זמושץ","dt":"תקסז - יח אלול","dp":"אה\"ו","b":"רב בטישוויץ-תקכד, הוצנפלץ, ברודי-תקלא, גלוגא-תקמה והקים שם ישיבה, אה\"ו-תקסא על מקום ר נח חיים צבי ברלין (האחרון שהיה רב בשלש הקהלות). חתן ר אריה ליב מדובנקא. חיבר \"תפארת צבי\" למברג תקעז, ועוד. מחותן עם ר עקיבא איגר. בניו: ר משה מטומשוב, ר יהודה ליב וואהל מקומרנא, ר בנימין מהמבורג. חתנו - ר אליעזר ליפמן מצילץ.","bk":[["תפארת צבי – שו\"ת",""]]},{"i":7723,"n":"בושקילא, מרדכי ממרוקו","b":"מקובל מחכמי פאס-תס. מתלמידיו - ר משה בן אברהם ן מוסא."},{"i":7724,"n":"בותראשווילי, אהרן","f":"אליהו","bt":"תרלז","dt":"תשיט","dp":"קולאשי","b":"רב ראשי בקולאסי-תרס\"ד"},{"i":7725,"n":"בותראשווילי, יהודה","f":"מרדכי","bt":"תרסה","bp":"קולאשי(גרוזיה)","dt":"תשמה - כז סיון","b":"נסמך לרבנות ברוסטוב,חזר לגרוזיה-תרצ\"ג,בגלל רדיפות השלטון עבר לרוסטוב,חזן שוחט ומוהל במלאחובקה,עלה לא\"י תשל\"א,עמד בראש איסוף הילדים לישיבות ובתי הספר של חב\"ד,הוציא ספר על כשרות בגורגית"},{"i":7726,"n":"בזיז, יעקב מאלגיר","b":"נכד ר יעקב סוסאן. חתן ר יהודה אנקאווה. מחכמי מסתגאנם בזמן הרשב\"ש."},{"i":7727,"n":"בזילה אביעד שר שלום בן מנחם שמשון","bt":"1680","dt":"ה'תקג 1743","bk":[["אמונות חכמים",""],["אמונת חכמים",""]]},{"i":7728,"n":"בזין, משה ברוך מפודהייץ","dt":"תרמז - בערך","b":"מחכמי פודהייץ. תשובה אליו בשו\"מ."},{"i":7729,"n":"בזרגי, שמואל מפיררה","b":"רב בפיררה-תפח, בזמן ר מרדכי צהלון, ר שבתי ריקנטי, ר יצחק למפרונטי."},{"i":7730,"n":"בזשיליאנסקי, משה יהושע אלתר","f":"אשר זליג","k":"בעל התשתפכות הנפש","dt":"תרעט - יב אד\"ב","b":"תלמיד ר נתן מנמירוב, ר נחמן מטשעהרין. מחשובי חסידי ברסלב בטעפליק. בזיוו\"ש חתן ר נחמן מטולטשין. ביקר בארץ-תרמב. נהרג עק\"ה. חיבר גם \"משיבת נפש\", אמונת עתיך\", ועוד."},{"i":7731,"n":"ב\"ח, אברהם","k":"בעל מקור חיים","b":"פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס."},{"i":7732,"n":"ב\"ח, יוסף חיים מאפטא","b":"חסיד אלכסנדר. רב באפטא. פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח, \"בית ועד לחכמים\" - סטמר תרפב, \"בית ישראל\" - לודז תרץ, \"בית שמואל\" - לודז תרצא, \"יגדיל תורה\" - פראגא-וארשא תרפז, \"קובץ דרושים\" - פיעטרקוב תרפג, \"המאסף\" - ירושלים תרנו, \"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":7733,"n":"בחור-אשכנזי, אליהו הלוי","f":"אשר","k":"בעל ספר הבחור","bt":"רכח או רל","bp":"ניישטט או איפסהיים","dt":"שט - כט שבט","dp":"פדובה","b":"הגיע מאשכנז לאיטליה לפני רסט. רב ומדקדק מגדולי חכמי איטליה, מופלא בדקדוק ומסורת, מגיה בדפוס בומבירגי. רב בפאדובה-רנו, רומא-רעו. היה מחלוקת עליו מצד כמה רבנים שהתנגדו לכך שלימד עברית לגויים (טענו שהגויים השתמשו בידע בעברית כדי לתקוף את התלמוד והוא ענה להם שכל מי שלמדו היה אדם שהטיב לישראל ולימדם רק לשום עברית ולא סתרי תורה), (מנכדיו המומרים שלמה מאראנו ואחיו ויטורי אוליאני מוראנו - שגרמו לשריפת ספרי התלמוד-שיג).","bk":[["הרכבה","דקדוק"]]},{"i":7734,"n":"בחיי","f":"אשר","k":"בעל כד הקמח","bp":"סרקסטה(ספרד)","dt":"ק - בערך","b":"מגדולי הראשונים, מפרש, דרשן, מקובל, מחכמי ספרד, תלמיד הרשב\"א, לדעת הרב גבישון הוא בנו של הרא\"ש. חיבר \"כד הקמח\" ו \"מדרש רבינו בחיי על התורה\""},{"i":7735,"n":"בחיי מספרד","f":"משה","b":"רופא מחכמי סאראגוסה-ספרד, הגן על הרמב\"ם מהחולקים עליו."},{"i":7736,"n":"בטאג', שמעיה ממכנאס","b":"מחכמי מכנאס-שנות ה-תר'. נזכר באוצר המכתבים."},{"i":7737,"n":"בטאן, אברהם ממרוקו","b":"מחכמי מרוקו-שנות ה-תק'. בנו - ר רפאל אליהו."},{"i":7738,"n":"בטאן, חיים ממראקש","f":"יעקב","b":"מחכמי מראקש-מרוקו. מצאצאי המקובל ר מרדכי."},{"i":7739,"n":"בטאן, יעקב ממראקש","f":"מרדכי","dt":"תרלג - כט ניסן","b":"תלמיד ר משה רוזליו בעל \"קול מבשר\". מו\"ץ במראקש, חתם על פס\"ד-תרט. מתורתו ב\"קול מבשר\". נזכר ע\"י השד\"ר ר ברוך פינטו שפגשו בהיותו במראקש."},{"i":7740,"n":"בטאן, מימון ממרוקו","b":"רב בפאס-תרם."},{"i":7741,"n":"בטאן, מרדכי ממראקש","b":"מחכמי מראקש. בנו - ר יעקב."},{"i":7742,"n":"בטאן, רפאל אליהו ממרוקו","b":"מחכמי פאס-תקצט."},{"i":7743,"n":"בטאן, שמואל יעקב ממראקש","b":"מו\"ץ במראקש, חתם-תריט עם ר רפאל מסעוד ן מוחא, ור ברוך אסבאג, וחתם גם עם ר אליעזר חזן."},{"i":7744,"n":"בטיטו, יהודה מירושלים","dt":"תרל - ג אייר","dp":"ירושלים","b":"מחכמי ורבני ירושלים"},{"i":7745,"n":"בטיטו, נחמן ממרוקו וירושלים","k":"בעל דין ומשפט","bt":"תרו","bp":"מראקש","dt":"תרעה - טו אלול","dp":"ירושלים","b":"רב במראקש, עלה לירושלים בילדותו. רב עדת המערבים בירושלים על מקום ר דוד בן שמעון. היה בשליחות העדה. דיין אצל ר דוד בן שמעון (=צוף דבש), ראשון לציון בירושלים-תרסט והיה מחלוקת על כך. חיבר \"דין ומשפט\" ירושלים תרע, וחיבר עם ר חזקיה שבתי חלק שמות מספר \"עם לועז\". חתנו ר נסים בנימין אוחנה אב\"ד קהיר. פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":7746,"n":"בטיטו, רפאל יצחק מירושלים","dt":"תרל - ט-יט טבת","dp":"ירושלים","b":"מראשי קהלת המערבים בירושלים בזמן ר דוד ן שמעון-תרכו. כנראה אביו או אחיו של ר נחמן-רבה של ירושלים."},{"i":7747,"n":"בטייאס, חיים יעקב","b":"רב ודיין בבואנוס איירס-תר\"צ"},{"i":7748,"n":"בטינו, חיים רפאל","b":"מו\"ץ בקורפו"},{"i":7749,"n":"בטלהיים, אליעזר זוסמן מפרשבורג","f":"רפאל הלוי מפרשבורג","bt":"תריב","dt":"תרלב - ח כסלו","b":"תלמיד הכת\"ס. נפטר בבחרותו, נספד ע\"י רבו."},{"i":7750,"n":"בטלהיים, יעקב סגל מפרשבורג","b":"מחכמי פרשבורג, חתם-תקס על תקנות הח\"ק."},{"i":7751,"n":"בטלהיים, ליאופולד מפרשבורג","b":"ממיסדי ביה\"ס בפרשבורג-תקף כנגד דעת החרדים."},{"i":7752,"n":"בטלהיים, ליב מפרשבורג","b":"מראשי קהלת פרשבורג-תסט."},{"i":7753,"n":"בטלהיים, משה הלוי מפרשבורג","f":"יעקב","bt":"תקלג","dt":"תקצו - יג סיון","dp":"פרשבורג","b":"ראש הקהל בפרשבורג בזמן החת\"ס, משכיל, עשיר ותלמיד חכם ותרם הרבה לקהלה - יחד עם גיסיו ר וולף פפנהיים, ור שמואל גוטמן (שהיו נשואים לאחיות והתעשרו כאשר גיסם-אחי נשותיהם המומר מוינה הוריש להם את כל רכושו העצום). \"הוא הגבר אשר בזכות השתדלותו נמנעה בוטלה גזירת הסגירה על ישיבת החת\"ס\" (כך הספידו החת\"ס)."},{"i":7754,"n":"בטלהיים, משה הלוי מפרשבורג","f":"קלונימוס קלמן","bt":"תקצח","bp":"פרשבורג","dt":"תרנז - כג ניסן","dp":"פרשבורג","b":"תלמיד הכת\"ס. מראשי קהילת פרשבורג. חתן ר משה פרייא-פאל מסערדאוהל."},{"i":7755,"n":"בטלהיים, קלונימוס קלמן מפרשבור","f":"משה הלוי מפרשבשורג","dt":"תרן - כט אדר","dp":"פרשבורג","b":"תלמיד החת\"ס. אביו היה השתדלן שמנע את סגירת הישיבה בפרשבורג."},{"i":7756,"n":"בטלהיים, קלמן מפרשבורג","f":"נטע הלוי מפרשבורג","bt":"תקסא","bp":"פרשבורג","dt":"תרכד - ו תשרי","dp":"פרשבורג","b":"תלמיד החת\"ס. חתן ר דניאל פרוסטיץ-שטינשנידר מפרשבורג. גיסו של ר משה גרינספלד מפרשבורג. רב בקיצע-תקצז, פרשבורג-תריח. נבחר כאחד משלושת נציגי פרשבורג לקונגרס יהודי הונגריה בפעשט."},{"i":7757,"n":"בטלהיים, רפאל פיליפ מפרשבורג","f":"משה","b":"מראשי קהלת פרשבורג על מקום אביו - בזמן הכת\"ס."},{"i":7758,"n":"בטלהיים, שמואל מפרשבורג","b":"גביר בפרשבורג-תף, השתתף ביריד לייפציג-תפג. כנראה שממנו משפחת בטלהיים (שהיה במקור - בית לחם)."},{"i":7759,"n":"בטלהיים, שמואל מפרשבורג","f":"קלמן","k":"בעל צוריק צור ביבעל","bt":"תרלב","bp":"פרשבורג","dt":"תשב","dp":"בודפשט","b":"בקי בשפות. ממיסדי האגודה הציונית \"יגדיל תורה\" (ששינתה שמה ל\"אהבת ציון\") בפרשבורג - אחרי תרנז - שעסקה בלימוד גמרא למשתתפיה. ציר בקונגרס הציוני מטעם \"אהבת ציון\" ופעל לבקשת הרצל בהקמת סניפים ברחבי הונגריה. הו\"ל את העתון הציוני \"אונגרלנדישע יידישע ציטונג\". נשלח לארה\"ב בזמן מלחה\"ע ה-I ע\"י ממשלת אוסטריה כדי להשפיע על דעת הקהל היהודי. הצטרף לאגודת ישראל והיה עורך ה\"יידישע פרעסע\" בפרשבורג ואח\"כ בוינה., הו\"ל \"יודאיקה\"-תרצד ובו מאמרים לדברי ימי רבנים בפרשבורג והונגריה, עורך \"אונגרלנדישע יידישע צייטונג\" - פרשבורג תרע, \"יידישע צייטונג\" פרשבורג תרפב."},{"i":7760,"n":"בטליע, ישראל מאמשטרדם","b":"רב ומו\"צ באמשטרדם. חיבר ערכים באנציקלופדיה \"אוצר ישראל\"."},{"i":7761,"n":"בטלן, יהודה ליב מדוינסק","dt":"תרלט","dp":"דוינסק","b":"רב בדינאבורג(=דוינסק)-תרי ור אהרן שאול גוריון הכהן על מקומו אחריו."},{"i":7762,"n":"בטניצקי, יהונתן מליטא ודרו\"א","f":"שלמה פנחס","k":"בעל ישראל בין המזרח","bt":"1899","bp":"מאריאמפול","b":"תלמיד ישיבת סלובודקה, פעיל בועד הלאומי של יהודי ליטא, מזכיר ה\"חלוץ\". עלה לארץ-1926, היגר לדרום אפריקה, וערך עתון באידיש ואת \"די אידישע פאסט\", ועוד."},{"i":7763,"n":"בטניצקי, שלמה פנחס","f":"משה שמואל","bt":"תרי","bp":"אלקוסט-ליד קובנה","dt":"תרצב","b":"תלמיד ישיבות קובנה. דיין במריאמפול - למעלה מ-50 שנה. באוצר מופיע נולד תרמה נפטר תרצח"},{"i":7764,"n":"בטעהר, וולף","b":"רב-שנת תק\"ע"},{"i":7765,"n":"ביאלוכלוצקי, אריה ליב","f":"שמואל שרגא","k":"בעל ראש אריה","bt":"תריא","bp":"פילוישוק-ליטא","dt":"תרסז","dp":"דראצ'ין","b":"נכד ר יעקב-נהרג עק\"ה ע\"י הפולנים במרד-1863. רב בדראצין. אחיו ר מרדכי מפילוישוק חיבר קונטרס שנדפס בספרו \"ראש אריה\", וכן מחדושי אביו בספרו. הניח חדושים רבים בכת\"י."},{"i":7766,"n":"ביאלוכלוצקי, שמואל שרגא מליטא","k":"בעל מרכזי התורה בליט","bt":"1891","bp":"פילוישוק-ליטא","dt":"1960","dp":"תל אביב","b":"חוקר תלמוד, עלה לארץ וכיהן כראש המחלקה לתלמוד באוניברסיטת בר אילן, אורך ראשי של הש\"ס הארץ ישראל השלם. חיבר \"ירושלים בהלכה\" בתוך ספר היובל שוקן, בעלי תשובה בספורי עגנון בספר היובל עגנון."},{"i":7767,"n":"ביאלוסטוצקי, אפרים מדרעטשין","b":"גביר מחכמי דרעטשין. מחותן עם הגדול ממינסק - חתנו-ר שלמה זלמן מוארשא, ועם ר מרדכי גימפל יפה מרוזינאי"},{"i":7768,"n":"ביאלוסטוצקי, בנימין יעקב","f":"חיים יצחק מפוסבול","bt":"1892","bp":"פומפיאן","dt":"1962","dp":"ניו יורק","b":"בן המגיד מפוסוואל. תלמיד ישיבות ליטא, היגר לארה\"ב-1911, עורך עתונים באידיש ובהם\"אידישער קעמפפער\", \"צייט\", \"די קינדער וועלט\". חיבר \"ביים ברייטן וועג\", ועוד."},{"i":7769,"n":"ביאלוסטוצקי, חיים יצחק מפוסבול","k":"המגיד מפוסבול","bp":"פוסבול","dt":"תש","dp":"גרודנא","b":"דרשן,מגיד בפאסוואל(=פוסבול), פוניבז, קידאן, שירווינט(=ניישטט-שאקי), טאווריג, גרודנא."},{"i":7770,"n":"ביאלוסטוצקי, מאיר יהודה מירושל","b":"פרסם מאמרים ב\"בית מדרש\" - תל אביב תשא, \"כנסת ישראל\" - סלובודקה - ירושלים תשא, \"תבונה\" - ירושלים תשא, \"תבונה\" - ירושלים תשא-תשח, \"תורת ירושלים\" - ירושלים תרצו."},{"i":7771,"n":"ביאליק מנוח לבנון","bt":"1902","dt":"ה'תשכב 1962","bk":[["גמרא מבוארת",""]]},{"i":7772,"n":"ביאליק, חיים נחמן","bt":"תרלג","bp":"ראדי-פלך וואהלין","b":"מגדולי המשוררים בדורו. תלמיד ישיבת וולוזין. פרסם מאמרים ב\"המליץ\", ועוד. מורה בסאנסוויץ, עבר לאודסה והיה בחבורת המשכילים יחד עם רבניציקי, \"אחד העם\", ועוד. עלה לארץ והתישב בתל אביב."},{"i":7773,"n":"ביאליק-ביליצקי, חיים אברהם","f":"תנחום גרשון ביליצקי","bt":"תרנז","bp":"ישניקובה-פלך גרודנא","dt":"תשכה- ב ניסן","b":"נכד ר חיים אברהם שפירא מסמרגון. תלמיד ישיבות לומזה, וולוזין. נסמך מאת: ר רפאל שפירא, ר משה סולוביציק, ר דוד פאיאנס מביאליסטוק, ר שלמה דוד כהנא מוארשא. רב בראגאז'נא-פולין, קליבלנד-תרפו, ברוקלין. חבר אגודת הרבנים באמריקה."},{"i":7774,"n":"ביאליר, יוסף","b":"מקובל,עלה לירושלים בקבוצת חסידים-ת\"ס"},{"i":7775,"n":"ביבאס, אברהם מאיסטאנקיואי","b":"רב הכולל באיסטאנקיואי-תקג עד תקז."},{"i":7776,"n":"ביבאס, אברהם מארגון","f":"שם טוב","k":"בעל דרך אמונה","b":"רופא ופילוסוף מחכמי ספרד בסרגוסה וושקה-רמ. היה בקשר עם המלך חואן מארגון ובספרו מספר על ויכוח שהיה לו עם המלך. חיבר ספרים בפילוסופיה ועוד. היה מחלוקת כנגדו ב\"עין יעקב\", בעבוה\"ק, ב\"מנות הלוי\", ובספר העקידה. חיבר גם \"מחזה שדי\", \"זה ינחמנו\", ועוד."},{"i":7777,"n":"ביבאס, אברהם מסאלי-מרוקו","b":"מחכמי סאלי, חתם על שאלה לחכמי פאס-תסז עם ר אברהם ן מוסא, ר שלם ן צור."},{"i":7778,"n":"ביבאס, אברהם מפאס","b":"מחכמי פאס, היה מעורב במחלוקת בענין נפיחת הריאות עם ר חיים גאגין."},{"i":7779,"n":"ביבאס, אברהם משלוניקי","k":"בעל זה ינחמנו","b":"מחכמי שלוניקי-שכ."},{"i":7780,"n":"ביבאס, אליהו מטיטואן-מרוקו","b":"מחכמי טיטואן-מרוקו, חתם על פס\"ד-תריא עם ר יצחק ן ואליד, ר יעקב אדהאן, ור שמואל ברגילון."},{"i":7781,"n":"ביבאס, דוד ממצרים","b":"רב במצרים-שס."},{"i":7782,"n":"ביבאס, וידאל מטיטואן","b":"מחכמי טיטואן-מרוקו-שנות ה-תק', שאלה ממנו על ר יצחק ן ואליד משי\"ח."},{"i":7783,"n":"ביבאס, חיים מטיטואן","f":"וידאל","b":"רב בטיטואן עם ר משה בן אליהו ביבאס."},{"i":7784,"n":"ביבאס, חיים מטיטואן-מרוקו - ב","f":"יוסף מטיטואן","b":"רב בטיטואן על מקום אביו-שנות ה-ש', יחד עם ר אברהם ן זמרא, ר יעקב הלוי, ר חנניה ארובאש. בקשה ממנו ב\"עת לכל חפץ\". בניו: ר יוסף מהררי\"ץ, ר יהודה, ר וידאל, ר אליהו."},{"i":7785,"n":"ביבאס, חיים מסאלי - ד","f":"חיים","dt":"תרלה","b":"מחכמי סאלי, נקרא ע\"ש אביו."},{"i":7786,"n":"ביבאס, חיים מסאלי וטיטואן - ג","f":"יעקב","bp":"טיטואן","dt":"תצג - כט תמוז","b":"מחכמי סאלי, אחיו של ר יוסף. בנו - ר יעקב מסאלי."},{"i":7787,"n":"ביבאס, חיים מספרד וטיטואן - א","f":"אברהם - אולי","bp":"ספרד","b":"ממגורשי ספרד, עבר לפאס, מו\"ץ בטיטואן-מרוקו-רץ (בכתבי היעב\"ץ נזכר שחתם בפאס-שכח לפני לכתו לטיטואן), ונזכר ב\"ויאמר יצחק\" שקיבל את שררת השחיטה לו ולזרעו אחריו. בנו - ר יוסף על מקומו אחריו."},{"i":7788,"n":"ביבאס, חיים משאטיבה","b":"רב בשאטיבה"},{"i":7789,"n":"ביבאס, יהודה","f":"שמואל","k":"בעל אנשי חיל","bt":"תקמב","dt":"תריז","dp":"חברון","b":"ילדותו בגיברלטר ולאחר פטירת אביו עבר לליוורנו אל זקנו ושם קיבל תורתו ואף קיבל תואר דוקטור שבו השתמש בחתימתו הלועזית. רב בקורפו-תקצא. בשנת תקצט בסיור באירופה ובאסיה ובו תיקן תקנות ועסק בארגון הקהלות, ובחיזוק הישוב היהודי בארץ ישראל, ראשון להטיף לגאולת אדמות ארץ ישראל, ובעקבותיו גם תלמידו ר' יהודה אלקלעי. עלה לארץ-תריב והתישב בחברון ושם הקים ישיבה. הביא את ספרייתו הגדולה לחברון,נפטר באמצע דרשה. חיבר \"אנשי חיל\" טריאסט תרו."},{"i":7790,"n":"ביבאס, יהודה מטיטואן-מרוקו","f":"חיים בן יוסף","b":"מחכמי טיטואן-מרוקו-שנות ה-ת', אחיו - ר יצחק."},{"i":7791,"n":"ביבאס, יום טוב מצפת","b":"מחכמי צפת-שנות ה-ש'."},{"i":7792,"n":"ביבאס, יוסף הלורקי מספרד - א","f":"יהושע","k":"בעל היסודות?","b":"תרגם \"מלת ההגיון\" לרמב\"ם לעברית-ה'קלא. אולי הוא מחבר ספר \"היסודות\" שהועתק בידי ר סעדיה ן דאנון."},{"i":7793,"n":"ביבאס, יוסף הלורקי מספרד - ב","b":"פילוסוף ורופא. חיבר פרוש על ספרי פילוסופיה ורפואה, ובהם על ספר הקאנון לאבן סינא ותרגמו בקיצור לעברית."},{"i":7794,"n":"ביבאס, יוסף מטיטואן - א","f":"חיים מטיטואן","b":"רב בטיטואן על מקום אביו-שהיה ממגורשי ספרד-תחילת שנות הש'. נזכר במכתב ר שאול סירירו לחכמי ארץ ישראל. בנו - ר חיים-השני."},{"i":7795,"n":"ביבאס, יוסף מטיטואן - ב","f":"חיים","b":"רב בטיטואן על מקום אביו, יחד עם ר מנחם עטייה, והיו בשליחות עירם בפאס-תסד בזמן צרה שנפלה עליהם. (במלכי רבנן נפלה ט\"ס ונכתב שמו יצחק - אך במקום אחר מופיע יוסף והוא הנכון)."},{"i":7796,"n":"ביבאס, יוסף מסאלי-מרוקו","f":"יעקב מטיטואן וסאלי","k":"בעל ספר זמנים","b":"מצאצאי ר וידאל הצרפתי מפאס. רב בסאלי. חיבר ספר על עיבור השנים בשם ספר זמנים. נזכר ב\"משפט וצבי\". אחיו - ר חיים."},{"i":7797,"n":"ביבאס, יוסף מצפת","b":"מחכמי צפת בשנת תמה, חתם על כתב שליחות בשנת תעג, ובשנת תע בערך על פסק דין של ר משה חיון בענין קהלת טבריה."},{"i":7798,"n":"ביבאס, יוסף מקושטא","f":"יואל","b":"מדפיס ומסדר אותיות בקושטא-רפ."},{"i":7799,"n":"ביבאס, יעקב מטיטואן - ב","b":"מו\"ץ בטיטואן-מרוקו, ונזכר ב\"ויאמר יצחק\" לר\"י ן ואליד."},{"i":7800,"n":"ביבאס, יעקב ממצרים","dt":"תטו או תיב","dp":"מצרים","b":"ג'יליבי במצרים-תיא-ו על מקום ר פרץ, ור יצחק בן ראובן על מקומו אחריו. נהרג עק\"ה בידי המשנה למלך במצרים."},{"i":7801,"n":"ביבאס, יעקב מסאלי","f":"חיים","b":"רב בסאלי עם ר חיים טולדנו, חתם על אגרת נחומים-תקיג לר רפאל עובד ן צור - עם ר חיים טולדנו, ור אהרן הלוי."},{"i":7802,"n":"ביבאס, יעקב מסאלי - א","f":"יוסף","bp":"טיטואן-מרוקו","dt":"תפז - לפני","b":"חתן נכדת ר וידאל הצרפתי השני מפאס. מו\"ץ בסאלי-מרוקו, חתם על פס\"ד-תמו ועוד, עם ר\"י ן מלכא, ר שמואל ן ואעיש, ר יוסף צבע, ועוד. בניו - ר יוסף, ר חיים."},{"i":7803,"n":"ביבאס, יצחק (או יוסף) מטיטואן","f":"חיים בן יוסף","b":"מחכמי טיטואן-תמו עם ר דוד הכהן ור חיים אלמושנינו. שליח טיטואן בפאס עם ר מנחם עטייה לבקשת עזרה."},{"i":7804,"n":"ביבאס, יצחק מסאלי-מרוקו","dt":"תסג","b":"רב בסאלי-מרוקו, חתם על פס\"ד-תנו ונזכר אצל היעב\"ץ. יתכן והוא ר יצחק מטיטואן."},{"i":7805,"n":"ביבאס, משה מטיטואן","f":"אליהו בן יוסף בן חיי","dt":"תקיח - אחרי","b":"דיין בטיטואן, חתם-תקטז עם ר יוסף ן מלכא. נזכר ב\"עדות ביהוסף\"."},{"i":7806,"n":"ביבאס, משה מפלורינה-יוון","b":"רב בפלורינה-יוון בזמן השואה."},{"i":7807,"n":"ביבאס, משה מצפת","b":"מחכמי צפת, וממונה מטעם ראשי הקהלות על החאן - שכונת היהודים."},{"i":7808,"n":"ביבאס, רפאל מסאלי - א","bp":"סאלי","dp":"סאלי","b":"בן למשפחה ידועה מספרד וסאלי-מרוקו, (פירוש השם ביבאס = חיים בספרדית). דיין בסאלי. זקנו של ר רפאל בעל \"קרני ראם\". נקבר בחלקת המשפחה בבית העלמין בסאלי. תלמידו היה ר אברהם אלנקאווה. נזכר ב\"הערצת קדושים\" על המנהג להשטתח על קברו הנמצא בסמוך לקבר ר חיים ן עטר הקדמון. יתכן שהוא המחבר \"ישיר ישראל\" תקעט, ואולי הוא קרוב משפחתו בעל אותו השם."},{"i":7809,"n":"ביבאס, רפאל מסאלי - ב","bt":"תרך","bp":"סאלי","dt":"תשיג","dp":"טבריה","b":"נכדו של ר רפאל ביבאס הראשון. תלמיד דודו ר רפאל אלנקאוה, ור מסעוד אלנקאוה מסאלי. עלה לארץ-תרסב והתישב בטבריה, ויסד שם תלמוד תורה."},{"i":7810,"n":"ביבאס, שם טוב מפאס-מרוקו","b":"מחכמי פאס, שאלה ממנו-תנו לחכמי מרוקו."},{"i":7811,"n":"ביבאס, שם טוב מצפת","b":"רב בצפת בזמן האר\"י. נזכר בשות המבי\"ט."},{"i":7812,"n":"ביבאס, שמואל מאלגיר","dt":"תקנו","b":"רב באלג'יר בזמן ר אברהם בושערא ונזכר בספרו \"ברית אברהם\", נזכר גם ב\"שער שלמה\" לר שלמה זוראפה."},{"i":7813,"n":"ביבאס, שמואל מגיברלטר","b":"רב בגיברלטר-תק\"נ"},{"i":7814,"n":"ביבאס, שמואל ממרוקו","b":"מחכמי מרוקו. נזכר ב\"משפטים ישרים\"."},{"i":7815,"n":"ביבאס, שמואל מספרד","b":"פילוסוף מחכמי ספרד, בזמן הרשב\"ץ. תלמיד ר חסדאי ן קרשקש."},{"i":7816,"n":"ביבי, יצחק מפאס","dt":"שעז - לפני","b":"מחכמי פאס, ומכנאס. חתם על תקנה-שסו, עם חבריו ר סעדיה ה\"ן רבוח, ש שמואל ן דנאן, ר וידאל הצרפתי ועוד. מתורתו בספרי חכמי דורו. חיבר או העתיק \"פירוש על קהלת\"."},{"i":7817,"n":"ביבי, שלמה מירושלים","b":"מחכמי ירושלים, בשנת שץ חתם על כתב שליחות ר אברהם ביטון ור שמואל רימון שיצאו מטעם עדת המערבים."},{"i":7818,"n":"ביבלמן, אביגדור","b":"רב בטרנוב. תשובה אליו ב\"עטרת חכמים\"."},{"i":7819,"n":"ביבלמן, נח מבוכניה","b":"מראשי מחז\"ה בבוכניה-תרלט."},{"i":7820,"n":"ביבער, אריה ליבוש מאוסטרהא","f":"אברהם יצחק","dt":"תרנה - ו טבת","dp":"אוסטרהא","b":"מחכמי אוסטרהא ומלומדי הקלויז הגדולה. תלמיד הדיין ר גבריאל בן דוד מאוסטרהא וזיטומיר. החשיב את הבעשט והחסידים הקדומים אך לא את כל חסידי זמנו והיה מחלוקת כנגדו מצד החסידים בגלל זה. בנו ר מנחם מנדל בעל \"מזכרת לגדולי אוסטרהא\"."},{"i":7821,"n":"ביבער, מאיר אליהו מאוסטרהא","f":"שמחה מאוסטרהא","b":"אב\"ד קופיל, דיין באוסטרהא. סדר לדפוס את כתבי ר חיים רפפורט שנדפסו ב\"מים חיים\"."},{"i":7822,"n":"ביבער, מנחם מנדל מאוסטרהא","f":"אריה ליבוש מאוסטרהא","k":"בעל מזכרת לגדולי אוס","b":"מחכמי אוסטרהא. חיבר \"מזכרת לגדולי אוסטרהא\". פרסם מאמר ב\"הפלס\" - ברלין תרסא-תרסה - ובו סליחות מבעל הט\"ז."},{"i":7823,"n":"ביבער, שמחה מאוסטרהא","f":"אברהם יצחק","b":"אביו היה ר אברהם יצחק בן אריה ליב מאוסטרהא. פרנס באוסטרהא. חתם על כתב רבנות ר יעקב רפפורט מאוסטרהא. בנו ר אברהם יצחק מאוסטרהא."},{"i":7824,"n":"ביברי, יהודה","f":"משה","dt":"תלד","dp":"אמשטרדם","b":"ציר קושטא בשבדיה לצד אביו. (תאריך הפטירה מיוחס לו בטעות ובאמת זהו תאריך פטירת אביו)."},{"i":7825,"n":"ביברי, משה מקושטא","f":"יהודה","dt":"תלד","dp":"אמשטרדם","b":"ציר תורכיה בשבדיה יחד עם בנו יהודה."},{"i":7826,"n":"ביברפלד, אברהם","b":"מגדולי רבני גרמניה-תר\"נ"},{"i":7827,"n":"ביגא, אברהם משלוניקי","dt":"תקלב","dp":"שלוניקי","b":"רופא בשלוניקי."},{"i":7828,"n":"ביגא, אברהם משלוניקי","dt":"שפט","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":7829,"n":"ביגא, אברהם משלוניקי","dt":"שפט - טז ניסן","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":7830,"n":"ביגא, אליה","f":"חיים","k":"בעל חיים עד העולם","b":"מחכמי טורקיה, חיבר \"חיים עד העולם\""},{"i":7831,"n":"ביגא, בנבנשתי משלוניקי","dt":"תצב","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":7832,"n":"ביגא, חיים מאזמיר - הנכד","f":"אליהו","b":"נכד ר חיים בעל \"חיים עד העולם\". שוחט באזמיר."},{"i":7833,"n":"ביגא, חיים מטירייא - הזקן","k":"בעל חיים עד העולם","dt":"תרמא","b":"מחכמי ורבני טורקיה,רב בטיריא, דיין,דרשן,חיבר \"חיים עד העולם\""},{"i":7834,"n":"ביגא, יהודה משלוניקי","f":"משה","k":"בעל מלכי יהודה","bp":"שלוניקי","dt":"תיג","dp":"צפת","b":"מחכמי קושטא, שלוניקי, בשנת שע חתום על גביית עדות. עלה לצפת והיה מחכמיה, חותנו של ר שם טוב פילו. חיבר \"מלכי יהודה\" לובלין שעו. (יש אומרים שנפטר לפני שצו כי בשות \"שער יהושע\" לר יהושע בנבנשתי מצויה תשובה שלו משנת תצו בברכת המתים)."},{"i":7835,"n":"ביגא, יצחק משלוניקי","dt":"תצד","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":7836,"n":"ביגא, יצחק משלוניקי וסופיה","f":"משה","k":"בעל בית נאמן","bp":"שלוניקי","dt":"שפח - לפני","b":"מחכמי שלוניקי, רב ודרשן, נדד ולימד במקומות שונים, רב בניקופול ור ראובן חדידה(=חדידאי) על מקומו אחריו. חיבר \"בית נאמן\"."},{"i":7837,"n":"ביגא, שלום מטורקיה","f":"חיים - חיים עד העולם","b":"מחכמי טורקיה. נזכר אצל ר חיים פלאג'י."},{"i":7838,"n":"ביג'אג'ו, אברהם מירושלים","f":"אהרן","k":"בעל שמך אברהם","bt":"תריח","bp":"קושטא","dt":"תרפג - ל אב","dp":"ירושלים","b":"מחכמי ירושלים, עלה עם אביו מקושטא, תלמיד \"דורש ציון\" בירושלים. בשליחות מספר פעמים והיה גם בהודו וסין, רב בפארו-פורטוגל. בשנת תרסט דיין אצל ר מרדכי תג'יר בירושלים. חיבר גם \"ושחטתם בזה\" ירושלים תרצב, ועוד. פרסם מאמרים ב\"המאסף\"."},{"i":7839,"n":"ביגון, יוסף מגרודנא","dt":"תשג","b":"מחנך,ראש ישיבה בגרודנא"},{"i":7840,"n":"ביגון, יוסף ממיר","b":"מחכמי מיר."},{"i":7841,"n":"ביגון, יוסף מקראקא","f":"בנימין","k":"בעל עינא פקיחא","bt":"תרסא","bp":"ויסוקי ליטבסקי","dt":"תשב","b":"תלמיד ישיבות ליטא, התיישב בוארשא ועבר לקראקא ויחד עם אשתו חינך בסמינר \"בית יעקב\", היה משגיח בישיבת היידה (באנטורפן). חיבר תזכיר בשם \"עינא פקיחא\" ירושלים תשלב."},{"i":7842,"n":"ביגזביץ, בן ציון מאויאזד","b":"פרסם מאמרים ב\"כרמנו\" - אלכסנדר-לודז תרצג."},{"i":7843,"n":"ביגל, יעקב","b":"חסיד בובוב. האדמור ר בן ציון כתב אליו בתרפז."},{"i":7844,"n":"ביגלאיזן, יוסף חיים מברנוב","f":"משה יהודה","k":"בעל חמדה גנוזה","bt":"תריח","dt":"תש","b":"נכד ר יעקב קופל (חסיד דזיקוב שעלה לצפת). חתן ר ישראל יקיר הכהן מאושפיצן. בחוותו בכפר נגניוב היתה חוות החלוצים הראשונה של צא\"י-תרץ. חיבר \"חמדה גנוזה\" וינה תרף. עבר לניו יורק-תרפא ופתח שם בית מסחר לספרים. פרסם מאמרים ב\"הפרדס\" - צאנז תרצא."},{"i":7845,"n":"ביגלאיזן, ישראל יקר מנ\"י","b":"פרסם מאמרים ב\"הפרדס\" - צאנז תרצא."},{"i":7846,"n":"ביגלאיזן, שלמה מלוביטש","f":"יוסף חיים","k":"בעל זכרון שלמה","b":"רב בלוביטש-תרעג, אושפצין. חיבר \"זכרון שלמה\" פיעטרקוב תרצג."},{"i":7847,"n":"בידינגן, משה ממיץ","f":"ישראל","k":"בעל חנוך לנער","b":"רב במיץ. חיבר גם \"אם למקרא\" - מיץ תקעו, \"כף אחת ערה זהב\" על הפיוט אלה אזכרה (נדפס עם הסליחות - מיץ תקפב)."},{"i":7848,"n":"בידנוביץ, זאב וולף","f":"ישכר","k":"בעל דברי זאב","b":"מחכמי יעדוואבנע, ויסאקי-מאזועצקי, עלה לירושלים, היה גם בניו יורק."},{"i":7849,"n":"בידרמן, אביגדור","f":"דוד מללוב","b":"בן האדמור מללוב, אחיו של האדמור ר משה מללוב ירושלים."},{"i":7850,"n":"בידרמן, אברהם שלמה מללוב","f":"משה מרדכי מללוב","k":"אדמור מללוב ירושלים","bt":"תרפח","b":"חתן ר יהודה זינדל מסאווראן. אדמור מללוב בירושלים."},{"i":7851,"n":"בידרמן, אלעזר מנחם מנדל","f":"משה מללוב","k":"אדמור מללוב","bt":"תקפז","bp":"ללוב","dt":"תרמג - טז אד\"ב","dp":"ירושלים","b":"האדמור מללוב, נכדו של \"היהודי הקדוש\" מצד אמו, חתן ר צבי בן החוזה מלובלין. עלה לארץ-תריא עם אביו ואחיו, כיהן כאדמור על מקום אביו ועמד בראש הישוב החסידי בירושלים. מדברי תורתו הובאו בספר \"לקוטי דברי דוד\" ירושלים תרכח. מתולדותיו ב\"תפארת בית דוד\". חתנו - ר יוסף יהושע אהרן אדלר."},{"i":7852,"n":"בידרמן, אלתר אברהם בצלאל נתן","f":"אלעזר מנחם מנדל מללו","k":"אדמור מארץ ישראל ללו","bt":"תרכב","dt":"תרצג - כה אלול","dp":"פולין - ירושלים","b":"חתן ר בנימין יהוד הליב ברנשטיין. עבר לפולין בזמן מלחה\"ע ה-I והתישב בסוסנובצא וכיהן כאדמור מארץ ישראל."},{"i":7853,"n":"בידרמן, אלתר אלעזר מנחם מללוב","f":"משה מרדכי מללוב","b":"חתן ר שמעון אהרן הרשקוביץ מבני ברק. הקים ישיבה בבני ברק."},{"i":7854,"n":"בידרמן, בצלאל נטע שלמה","f":"יעקב דוד מקוזניץ","bt":"תרד","b":"רב בטשרווינסק ביזוין-תרכח, וישגארד על מקום אביו, לוביטש-פלך וארשא. מבניו - ר משה דוד, ר יעקב מאיר."},{"i":7855,"n":"בידרמן, דוד יוסף מללוב","f":"שלמה יחיאל מללוב","k":"אדמור מללוב","bt":"תקפז","dt":"תרנז - טו אב","b":"חתן ר אלעזר מקוזניץ, תלמיד ר עמנואל מפשדבורז, ר מנחם מנדל מווארקא, ור יחיאל מאלכסנדר. ובזיוו\"ש חתן ר שמחה בונם פויזנר-נכד ר שמחה בונם מפשיסחא, ובזיוו\"ש חתן ר נחום ריישער נכד החוזה מלובלין. גדל אצל דודו ר מנחם נחום ממקארוב. רב בללוב-תריא (כשזקנו האדמור ר משה - עלה לירושלים). אדמור בללוב-תרלו."},{"i":7856,"n":"בידרמן, דוד יצחק מזאריק","f":"אביגדור מללוב","b":"נכד האדמור ר דוד מללוב. צדיק ומקובל. נכדו ר אלתר יחיאל מעלקוש."},{"i":7857,"n":"בידרמן, דוד מללוב","f":"שלמה צבי","k":"אדמור מללוב","r":"האדמו\"ר הראשון מלעלוב","bt":"תקו","dt":"תקעד - ז שבט","b":"תלמיד ר אלימלך מליזנסק, והחוזה מלובלין. חברו ומחותנו של היהודי הקדוש מפשיסחא. חתן ר יעקב מכפר נעגיווען. מראשוני המשפיעים לחסידות - החזיר בתשובה את הפרופ' ר חיים דוד ברנהרד. מתורתו ב\"לקוטי דברי דוד\". מתולדותיו ב\"מגדל דוד\" וב\"קודש הלולים\".","bk":[["דברי דוד",""],["ליקוטי דברי דוד",""],["מגדל דוד - סיפורים על ר' דוד בידרמן",""],["פרי קודש הילולים",""],["קודש הילולים",""]]},{"i":7858,"n":"בידרמן, דוד צבי שלמה מללוב","f":"אלעזר מנחם מנדל מללו","k":"אדמור מללוב","bt":"תרד","dt":"תרעח - ה אלול","dp":"ירושלים","b":"חתן ר נח פנחס ממאגרוב-ברוד (שושלת ניקלשבורג). עלה כילד עם אביו לירושלים, נסע לאירופה ולמד אצל ר אהרן מקרלין וקבלו כרבו ונחשב לגדול תלמידיו. אדמור מללוב בירושלים-תרס ומנהיג החסידים בירושלים. הקים את שכונת בתי וארשא, חדושי תורתו בספר \"לקוטי דוד\" ירושלים תשכח. מתולדותיו ב\"תפארת בית דוד\". חתנו ר אברהם שלמה-נפטר צעיר."},{"i":7859,"n":"בידרמן, יהודה ליב","f":"יעקב מאיר בידרמן","dt":"תשג","b":"רב בועד הרבנים בוורשה"},{"i":7860,"n":"בידרמן, יעקב דוד מקוזניץ וישגר","f":"ישראל איסר","k":"בעל הגהות מהריד","bt":"תקסח","dt":"תרכג - ב-כ אב","dp":"וארשא","b":"נכד ר יחזקאל מקוזניץ (וי\"א חתנו של ר יחזקאל). תלמיד ר מנחם מנדל מקוצק, ור שלמה יהודה ליב מלענטשנא. רב במזריטץ, קוזניץ, וישגרד(=וישגארד). כונה \"שומר שבת\" על זהירותו בשבת. בניו - ר ישראל איסר, ר בצלאל נטע מלוביטש, מצאצאיו ר יעקב בידרמן - חתנו של בעל \"שפת אמת\"."},{"i":7861,"n":"בידרמן, יעקב יהושע","f":"משה דוד","dp":"ארה\"ב","b":"נכד (אבי אביו) ר שלמה נתן בצלאל מלאויטש. ניצל מהשואה והגיע לארה\"ב. קרוב משפחה לאדמורי גור."},{"i":7862,"n":"בידרמן, יעקב יצחק מללוב ירושלי","f":"שמעון נתן נטע מללוב","bt":"תרסז","dt":"תשמא - כג אלול","b":"חתן ר אלתר חיים שיפמן-מחשובי חסיד קרלין בירושלים. בנו ר שמעון נתן נטע אדמור בירושלים."},{"i":7863,"n":"בידרמן, יעקב מאיר מוארשא","f":"נתן שלמה בצלאל","k":"בעל מאור יעקב","bt":"תרל","dt":"תשא - יג סיון","dp":"גיטו וארשא","b":"רב בלויביטש, ראב\"ד בועד הרבנים בוארשא-תרצה. חתן השפת אמת, והו\"ל את ספר חותנו יחד עם גיסו ר צבי חנוך לוין מבנדין עם הגהות ממנו. חבר ועד הרבנים בוארשא וחבר במועצת גדולי התורה. ביקר בארץ בשליחות מועצת גדולי התורה. פרסם מאמרים ב\"דגל התורה\" - וארשא תרפב, \"עמק הלכה\" - וארשא תרפו, \"קובץ דרושים\" - פיעטרקוב תרפג, \"קול תורה\" - פאביאניץ תרפו.","bk":[["מאור יעקב",""]]},{"i":7864,"n":"בידרמן, יעקב מאפטא","f":"נחמיה מללוב","bt":"תקסו","dt":"תריח - יח טבת","b":"נכד האדמור ר דוד מללוב. חתן קרובו ר יעקב קופיל-חתנו של ר מאיר מאפטא. תלמיד דודו זקנו ר מאיר מאפטא, ר אריה ליביש מאופלא, ור ישכר דב מרודשיץ שהכתירו לאדמור. רב ואדמור באפטא, איוואנצק. בנו ר משה-חתן ר קלונימוס קלמיש."},{"i":7865,"n":"בידרמן, יעקב משידלוב","f":"מאיר מרדכי דוד משידל","k":"אדמור מללוב בשידלוב","dt":"תש","dp":"שידלוב","b":"חתן דודו ר יחיאל אלתר פרלגר מאיוואנצק-חתן ר יעקב מאפטא. אדמור בשידלוב, אוייאנצק(=איוונצק). חתנו ר אלימלך אריה רבינוביץ בן יחזקאל מרדמוסק על מקומו אחריו בשידלוב."},{"i":7866,"n":"בידרמן, יצחק דוד מוארשא","f":"יעקב מאיר בידרמן","dt":"תשג","b":"רב בועד הרבנים בוורשה"},{"i":7867,"n":"בידרמן, יצחק דוד מללוב","f":"משה מללוב","k":"אדמור מללוב","bt":"תקעה","dt":"תרמז - ג תשרי","dp":"ירושלים","b":"חתן ר ישעיה הכהן. עלה לארץ-תריא עם אביו האדמור ואחיו. סירב לאדמורות בחיי אחיו ר אליעזר מנחם מנדל. מתולדותיו ב\"תפארת בית דוד\"."},{"i":7868,"n":"בידרמן, ירחמיאל יוסף","f":"אלעזר מנחם מנדל מללו","bt":"תרכו","dt":"תרעח - י טבת","b":"חתן ר שלמה מסטולין וחברון-מצאצאי ר מרדכי מלכוביץ."},{"i":7869,"n":"בידרמן, ישעיה מנדל","b":"ר\"מ בישיבה בקראקא. נספה בשואה."},{"i":7870,"n":"בידרמן, ישראל איסר","f":"יעקב דוד מקוזניץ"},{"i":7871,"n":"בידרמן, מאיר מרדכי דוד משידלוב","f":"יעקב מאפטא","dt":"תרלג - ב אייר","dp":"אוסטרובצא","b":"חתן ר ישראל מסטביחוב (נסכיז)."},{"i":7872,"n":"בידרמן, מרדכי אלעזר מנחם מסוסנ","f":"ירחמיאל יוסף","k":"אדמור מסוסנובצא","dt":"תשג","b":"נכד האדמור ר אלעזר מנחם מנדל בידרמן מללוב. חתן דודו ר אלתר אברהם בצלאל נתן נטע מסוסנובצא, אדמור בסוסנובצא על מקום חותנו. נספה בשואה עם בנו יחידו ר משה."},{"i":7873,"n":"בידרמן, מרדכי מירושלים","b":"פרסם מאמרים ב\"קול תורה\" - ירושלים תרץ."},{"i":7874,"n":"בידרמן, משה","f":"יעקב מאפטא","b":"מצאצאי האדמור ר דוד מללוב. חתן ר קלונימוס קלמיש מקראקא בעל \"מאור ושמש\"."},{"i":7875,"n":"בידרמן, משה יחזקאל","f":"יעקב דוד מקוזניץ","dt":"תרסז - יח טבת","b":"רב בוונגראבי, וענווישעגארד."},{"i":7876,"n":"בידרמן, משה מללוב","f":"דוד","k":"אדמור מללוב","bt":"תקלז","dt":"תריא - יג טבת","dp":"ירושלים","b":"חתן ר יעקב יצחק היהודי הקדוש מפשיסחא. מגדולי האדמורים בדורו ובית מדרשו שימש מקום ריכוז לרוב אדמורי פולין שלא מבית פשיסחא. רב בפשדבורז-תרג, עלה לירושלים-תריא ונפטר אחר 72 יום, בדרכו לירושלים עבר בצפת ודחה בקשה לכהן כרבה של צפת, הגיע לירושלים והקים את החצר החסידית הראשונה בירושלים. מתורתו ב\"לקוטי דברי דוד\". מתולדותיו ב\"פרי קודש הלולים\". בניו - ר יצחק דוד, ר אליעזר מנחם."},{"i":7877,"n":"בידרמן, משה מרדכי מללוב","f":"שמעון נתן נטע","k":"אדמור מללוב בירושלים","r":"האדמו\"ר מלעלוב","bt":"תרסד","dt":"תשמז - כד טבת","b":"חתן ר אברהם שוורץ. אדמור מללוב בירושלים, תל אביב ובני ברק, וקבוצה מחסידי קרלין-תשכב שקבלו עליהם את מרותו (אביו ר שמעון היה מקורב לאדמורי קרלין). מתורתו ב\"קדושת מרדכי\". נכדו ר דוד צבי שלמה הורונציק הקים בימ\"ד בבני ברק ע\"ש ראודשיץ.","bk":[["ברכת משה (לעלוב [קרלין-לעלוב])",""],["ברכת משה",""]]},{"i":7878,"n":"בידרמן, משה שלמה יחיאל משילץ","f":"דוד יוסף מללוב","k":"אדמור מפילץ","r":"מו\"ץ בוורשא","bt":"תרכא","dt":"תרעד - יג אדר","b":"חתן ר יוסף אריה ליב ערליך-נכד ר שמואל אריה מאוסטרובצא, ובזיוו\"ש חתן ר אפרים פישל רפפורט-נכד ר ירחמיאל מפשיחסא. אדמור בשילץ. חיבר \"דברי משה.","bk":[["דברי משה - זמן קבלת שבת והלכות ציצת ותפילין",""]]},{"i":7879,"n":"בידרמן, נחמיה","f":"דוד מללוב","b":"בן האדמור מללוב, אחיו של האדמור ר משה מללוב ירושלים. חתן ר מרדכי מסטבניץ-תלמיד החוזה מלובלין. ממפיצי החסידות."},{"i":7880,"n":"בידרמן, פנחס יצחק"},{"i":7881,"n":"בידרמן, שלמה יחיאל","f":"משה מללוב","bt":"תקעג","dt":"תקצה - י תשרי","b":"חתן ר יוסף מטורטשין (לובלין). נפטר בחיי אביו."},{"i":7882,"n":"בידרמן, שמואל","dt":"תרג - ג תשרי","b":"אדמו\"ר מללוב בירושלים"},{"i":7883,"n":"בידרמן, שמעון נתן נטע מירושלים","f":"יעקב יצחק מירושלים","k":"אדמור מללוב קרלין","b":"נכד ר אלתר חיים שיפמן מחשובי חסידי קרלין בירושלים ונכד אדמורי ללוב בירושלים. אדמור קרלין ללוב בירושלים."},{"i":7884,"n":"בידרמן, שמעון נתן נטע מללוב","f":"דוד צבי שלמה","k":"אדמור מללוב","bt":"תרכט-ל","dt":"תרץ - ג תשרי","b":"חתן ר יוסף ציינוירט, ובזיוו\"ש חתן הרב שווארץ. תלמיד אדמורי קרלין. מחכמי ישיבת המקובלים \"שער השמים\" עבר מירושלים לקראקא-תרעג, וחזר לארץ-תרפו. מתולדותיו ב\"תפארת בית דוד\"."},{"i":7885,"n":"בידרמן, שמעון נתן נטע מללוב","f":"משה מרדכי מללוב","k":"אדמור מללוב בני ברק","r":"אדמו\"ר מלעלוב","bt":"תרץ","dt":"יום כיפור תשע","b":"חתן ר שלמה פריינד מירושלים. אדמור מללוב בבני ברק הנהיג גם את חסידי פינסק קרלין בירושלים על מקום אביו - אך פרש. חיבר \"הר בשן\"","bk":[["הר בשן – רמב\"ם",""]]},{"i":7886,"n":"ביזונסקי, ישעיה מישיצלאוצי","f":"בריי\"א","b":"מאסף לישיבת חכמי לובלין (כך חתם על ספר שנתרם לישיבה)."},{"i":7887,"n":"ביזיטי, יוסף","b":"מחכמי חברון, בשנת תכא חתם על כתב שליחות של ר חייא דיין."},{"i":7888,"n":"ביזנץ, ישראל","dt":"תקמא - יא שבט","b":"דומ\"צ בבוניהאד(=באניהאד)"},{"i":7889,"n":"בי\"ח, צבי הירש מניקלשבורג","b":"תלמיד ר דוד אופנהיים בפרג, ר אברהם ברודא. מחכמי ניקלשבורג. חיבר חדושים על הש\"ס - בכת\"י, וביאור לתורה \"תורת חיים\" - בכת\"י. חתנו - ר משה אריה פילבוגן בי\"ח מניקלשבורג, ונכדו ר יעקב הירש בעל \"חשרת מים\"."},{"i":7890,"n":"ביחובסקי, וולף מחאלמי","f":"חיים אליעזר","dt":"תשב - יג אדר","dp":"גיטו מינסק","b":"גביר בחאלמי-פלך צרניגוב. חתן הגדול ממינסק. נספה בשואה."},{"i":7891,"n":"ביחובסקי, חיים אליעזר","f":"דב בער הכהן","k":"הו\"ל גנזי נסתרות","dt":"תרפד - יז אב","b":"מחשובי חסידי חב\"ד, ממנהלי כולל חב\"ד-תרנא. עורך ומו\"ל ספרי אדמורי חב\"ד. עלה לארץ. יש שטענו שבספרו גנזי נסתרות היו גם זיופים."},{"i":7892,"n":"ביטאן, משה מגיברלטר","b":"רב בגיברלטר, חתם-תצט על שאלה לחכמי טיטואן עם חבריו: ר דוד כלפון, ר משה טולדנו."},{"i":7893,"n":"ביטון, אברהם מירושלים","b":"מחכמי עדת המערבים בירושלים, בשליחות-שץ עם ר שמואל רימון במרוקו."},{"i":7894,"n":"ביטון, אברהם מפאס","dt":"של - בערך","dp":"פאס?","b":"מחכמי ספרד, מו\"ץ בפאס-ש', חתם על תקנות-שה יחד עם ר שמואל חאגיז ור יהודה הכהן ור יצחק דון."},{"i":7895,"n":"ביטון, אליהו ממרוקו","k":"בעל מורשת","bp":"מרוקו","b":"חיבר \"מורשת א\"ב\""},{"i":7896,"n":"ביטון, בכור יצחק"},{"i":7897,"n":"ביטון, חיים ממרוקו","k":"בעל לב חיים","dt":"תשלה - כח סיון","b":"מחכמי ורבני מרוקו,דיין ומו\"ץ,דרשן,אב\"ד ור\"מ במילילייא,הקים את ישיבת \"עץ חיים\" בצפון מרוקו,עלה לא\"י תשכ\"ט,חיבר \"לב חיים\" על שו\"ע אבן העזר"},{"i":7898,"n":"ביטון, יהודה","b":"רב-שנת ת\"ס"},{"i":7899,"n":"ביטון, ימין ממרוקו","b":"רב בפאס-תרם."},{"i":7900,"n":"ביטון, יעקב מירושלים - א","f":"אברהם","k":"בעל עדות ביעקב","dt":"תקלד","dp":"לארסו","b":"מחכמי ירושלים, חתם על שטר התקשרות עם ר שלום שרעבי בשנת תקיא ותקיד. ידיד נעוריו של החיד\"א. לפני שנת תקיח בשליחות בחו\"ל. חיבר \"עדות ביעקב\" שלוניקי תפ. נספד בידי ר ידידיה טאריקה ב\"קדש ידיד\"."},{"i":7901,"n":"ביטון, יעקב מירושלים - ב","b":"מחכמי ירושלים-תקפו, נזכר בשטר חזקה."},{"i":7902,"n":"ביטון, יצחק מירושלים","b":"מגדולי רבני ירושלים-ת\"פ"},{"i":7903,"n":"ביטון, יצחק ממראקש","dt":"תשט - ח אב","dp":"מרכאש","b":"חתן ר יעיש רקיספין. מחכמי מרכאש(=מראקש)-תשו, רב בכפר תיזנין."},{"i":7904,"n":"ביטון, מאיר ממרוקו","dt":"תשטז - ח תמוז","dp":"תמסטינת-מרוקו","b":"מחכמי מרוקו."},{"i":7905,"n":"ביטון, רפאל ממרוקו והוד השרון","dt":"תשסא","b":"מחכמי מרוקו, עלה לארץ וכיהן כרב בהוד השרון."},{"i":7906,"n":"ביטון, שלמה לעזיז ממרוקו","b":"מחכמי מרוקו. חיבר הקדמה ל\"מגן דוד\" לר דוד פרץ."},{"i":7907,"n":"ביטון, שלמה מהמגרב","b":"רב במגרב, במאה ה-ד' (שנות ה-ש')."},{"i":7908,"n":"ביטון, שלמה ממרוקו","b":"רב במרוקו-תל, חתם אז על פסק דין."},{"i":7909,"n":"ביטון, שמעון ממרוקו וצרפת","f":"חיים - לב חיים","k":"בעל שלמי שמעון","r":"אב\"ד חוג חת\"ס","bt":"תרצג","bp":"מרוקו","dt":"תשמב - יז תמוז","b":"תלמיד ישיבות סונדרלנד וגייטסהד באנגליה. רב במרסיי-צרפת"},{"i":7910,"n":"ביטי, חיים מאישקופיה","b":"דיין באישקופיה-שנות ה-ת'."},{"i":7911,"n":"ביטי, שמואל מאישקופיה","b":"דיין באישקופיה-שנות ה-ת'."},{"i":7912,"n":"ביטראן - משפחה","b":"משפחת רבנים בקושטא."},{"i":7913,"n":"ביטראן, חיים מישאל","dt":"תרטו","b":"מחכמי ודייני קושטא,חיבר שו\"ת"},{"i":7914,"n":"ביטראן, רפאל אהרן מקושטא","k":"בעל מדות טובות","r":"מגדולי רבני קושטא","bt":"תקץ - בערך","bp":"קושטא","b":"רב וראש ישיבה בקושטא. תלמיד ר מנחם צונצין ור יהושע צונצין. ידידו של ר שלמה אליעזר אלפנדרי שהזכירו בספריו, מתשובותיו בספרי חכמי דורו. חיבר גם \"זכור לטוב\", ועוד. רבים מכתביו אבדו.","bk":[["זכור לטוב - מערכות תשובות ודרשות (כת\"י)",""],["מדות טובות - מכילתא",""],["רב טוב - הל' נדה להרמב\"ן (כת\"י)",""]]},{"i":7915,"n":"ביטרואו, אליהו הרופא","b":"חיבר פירוש על משלי - בכת\"י."},{"i":7916,"n":"ביטרמן, יעקב הכהן מסקאלא","b":"מחכמי סקאלא. תשובה אליו \"וישב משה\"."},{"i":7917,"n":"בייאט, נסים ממרוקו","b":"מחכמי מרוקו. נזכר חדוש משמו ב\"מעט דבש\" לר יעקב נחמני."},{"i":7918,"n":"בייאלר, יוסף מירושלים","f":"פסח","dt":"תפט - אחרי","dp":"ירושלים","b":"מחכמי ירושלים, בשנת תסז חתם על כתב הרבנות של ר דוד אופנהיים. בתו שרה נשאה לר רפאל יצחק זרחיה אזולאי, ונכדו הוא החידא."},{"i":7919,"n":"בייז, יהודה ליב מאילוקסט","b":"מחכמי אילקוסט, יסד חברת \"גמילות חסד\" יחד עם ר אידל בן אברהם שלוסברג."},{"i":7920,"n":"בייזער, דוד מסעלץ","b":"גביר וסוחר י\"ש בסעלץ, והגדול ממינסק היה שותפו בסתר בעסקיו - בתקוה שיתעשר ויוכל להשתחרר מעול הרבנות."},{"i":7921,"n":"בייט, אליעזר ליפמן מהמבורג","f":"שלמה זלמן","dt":"תקנה - כד אייר","dp":"אלטונא","b":"חתן ר מרדכי קנדר. דיין באה\"ו. חתם בהמבורג-תקמט על החרם כנגד הספר \"מצפה יקותיאל\" - שפנה נגד ר רפאל הכהן מהמבורג."},{"i":7922,"n":"בייט, יעקב מהמבורג","b":"מחכמי המבורג-תקלח."},{"i":7923,"n":"בייט, רפאל מאה\"ו","f":"מרדכי","dp":"אלטונא","b":"מחכמי אה\"ו."},{"i":7924,"n":"בייט, שלמה מהמבורג","f":"אליעזר ליפמן","dt":"תקפה - כו תמוז","dp":"אלטונא","b":"מו\"צ בהמבורג, ודיין. חתם בהמבורג-תקמט על החרם כנגד הספר \"מצפה יקותיאל\" - שפנה נגד ר רפאל הכהן מהמבורג."},{"i":7925,"n":"בייטום, שלמה זלמן ממילדוי","f":"יעקב מקורט","k":"בעל דעת שלמה","bt":"תרה או תרכ","bp":"קורט","dt":"תרעד - טז חשון","b":"תלמיד הכת\"ס, ור יהודה אסאד. חתן ר משה הרצפלד מסילאש-באלהאש ועבר לשם-תרכח. רב במילדוי(=מאלדוי)-תרמד."},{"i":7926,"n":"ביילא אלמנת הסמ\"ע","f":"ישראל אידלס","dp":"ירושלים","b":"אחר פטירת בעלה עלתה לירושלים. הרבנית חידשה שני דינים לנשים בעניני הדלקת נרות ביום טוב. חדושים אלו עוררו ויכוח בין הפוסקים"},{"i":7927,"n":"בייליש, יעקב הלוי מיאנושי","f":"ברוך","k":"בעל פרי משנת יעקב","dt":"תרפג - כב חשון","b":"תלמיד הכת\"ס, ור בנימין זאב לעוו מוערבא ור יהודה אסאד. חתן ר נפתלי הירצקא זילברמן מיאנושי ורצפערט. רב בקאזינץ-תרלו, מארימפאטש-תרמב, יאנושי על מקום חותנו-תרמח."},{"i":7928,"n":"ביימל, דוד צבי","dt":"תרנט","b":"תלמיד ר שלמה זלמן אולמן ממאקובה בעל \"יריעות שלמה\". רבה הראשון של מעדיאש(=מג'ש)-תרמה. תשובה ממנו ב\"תל תלפיות\"-תרסז."},{"i":7929,"n":"ביין, נפתלי הכהן","bt":"תקפו","dt":"תרסו - כה כסלו","b":"רב במינסנט,למש"},{"i":7930,"n":"ביינוש מוילנא","f":"יוסף מוילנא","dt":"תקפו - טו טבת","dp":"וילנא","b":"שומר בית העלמין בוילנא - בן למשפחה שבמשך דורות התגוררו ליד בית העלמין בוילנא והיו שומריו."},{"i":7931,"n":"בייניש קליין, יונה בנימין","b":"תלמיד הדעת סופר. חתן ר שמעון טיטלבוים מטארנליא. מחכמי בערגסאז."},{"i":7932,"n":"ביינש מאילוקסט","b":"רב באילקוסט-תרטז עד תרכג - על מקום ר משה אברהם מבריסק ור בנימין פוטרמן על מקומו אחריו, סירוטשנע-תרכד."},{"i":7933,"n":"בייעא-רוט, ברוך מפרשבורג","dt":"תקצב - יז תמוז","dp":"פרשבורג","b":"תלמיד החת\"ס. דרשן, מג\"מ בחברת \"תפארת בחורים\" בפרשבורג ור יוסף דוקס על מקומו אחריו. מתורתו ב\"שערי חיים\" לבעל \"מחנה חיים\"."},{"i":7934,"n":"ביירן, ישעיה משאראש","f":"בנציון","dt":"תרמו - כח כסלו","dp":"שאראש-פאטאק","b":"תלמיד הכת\"ס, ור בנימין זאב לעוו מוערבא. חתן ר שמואל זיידל מאהיי. רב בקאטה, האנשוביץ-תרטז, סערעדנא, שאראש-פאטק-תרכא."},{"i":7935,"n":"ביכלר, אברהם מבודפשט ולונדון","f":"מרדכי","bt":"תרכח","b":"תלמיד ביהמ\"ד לרבנים בבודפשט. מורה בביהמ\"ד לרבנים בלונדון ובהמשך ראש המוסד-1908 עד 1939."},{"i":7936,"n":"ביכלר, אהרן מיאסבערני","f":"דוד סודיץ ביכלר","bt":"תקפח","dt":"תרעד - י תשרי","b":"תלמיד הכת\"ס, ור יהודה אסאד. חתן רבו ר יהודה אסאד. רב קהילת הסטטוס-קוו ביאס-בערני(=יאס-באראני)-תרכא. (באוצר הרבנים מופיע - נפטר תרסה)."},{"i":7937,"n":"ביכלר, אלכסנדר מקאסטהאי","dt":"תשד","b":"רב הקהילה הניאולוגית בקאסטהאי-מחוז זאלא. הסטוריון, מרצה לתולדות יהודי הונגריה באונ' בבודפשט. חיבר מונוגרפיה על יהדות הונגריה. נספה בשואה."},{"i":7938,"n":"ביכלר, זיגמונד","b":"רב באירשא-תרמו. חיבר את תולדות הקהלה"},{"i":7939,"n":"ביכלר, יהודה ממינדסענט","f":"אהרן מיאסערעני","b":"רב ביאסבערעני."},{"i":7940,"n":"ביכלר, יהושע זליג מאירשא","f":"אהרן מיאסערעני","k":"בעל מחשבות ורעיונות","bt":"תרך","b":"רב באלברטי-אירשא-תרמו. חיבר תולדות זקנו - בעל שו\"ת מהרי\"א - בלשון אשכנז."},{"i":7941,"n":"ביכלר, יצחק מפוטנאק","b":"תלמיד השב\"ס. חתן ר מאיר טננבוים מפוטנאק, ועבר לשם-תרנח. עבר למישקולץ. תשובה אליו ב\"דעת סופר\"."},{"i":7942,"n":"ביכלר, פנחס ממאר","f":"אליעזר","bt":"תר","b":"נכד ר יהושע פאלק ביכלר-סודיטץ. תלמידי ישיבת פאסט, סערדאהלי, פרשבורג, תלמיד ר דוד ביכלר, ר יהודה אסאד, הכת\"ס. רב בפיעלק, שאלקא טאריאן, מאאר. בנו - ר שמעון מקעסטאוהל. חתנו - ר יוסף פרנק מפיאמע."},{"i":7943,"n":"ביכלר, ש' מפרשבורג וניו יורק","b":"מראשי חברת \"אהבת ציון\" בפרשבורג, היגר לניו יורק."},{"i":7944,"n":"ביכלר, שמעון מקעסטהאל","f":"פנחס","b":"רב בקעסטהעל."},{"i":7945,"n":"ביכלר-סודיטץ, אליעזר","f":"פאלק סודיטץ","bt":"תקעח","dt":"תרלט","b":"רב בסעטשין"},{"i":7946,"n":"ביכלר-סודיטץ, דוד מביצ'קא ופאס","f":"יהושע פאלק","bt":"תקעה","dt":"תרסח - י תשרי","b":"תלמיד ר יהודה אסאד, ר יעקב קופל חריף מוערבוי. בזיוו\"ש חתן ר יהודה אסאד. רב בביטשקע(=ביצ'קא)-מחוז פאיר-תקצט וראש ישיבה, פאסטא(=פאסטו)-תרז כ-60 שנה. נזכר בשו\"ת \"חתם סופר\"."},{"i":7947,"n":"ביכלר-סודיטץ, יהושע פאלק מסטשי","f":"חנוך ביכלר","bt":"תקנג","bp":"סודיטץ","dt":"תרט - כח אדר","dp":"סעטשין","b":"תלמיד החת\"ס. רב בסודיטץ-תקעח, סעטשין-תקצז."},{"i":7948,"n":"בילאסקו די, יצחק משלוניקי","b":"חתן הגביר יצחק די מאייו מלאריסה. גביר ורופא בשלוניקי, עלה לירושלים-לפני תקטו. סייע בהדפסת \"פרי האדמה\" לר מיוחס בן שמואל."},{"i":7949,"n":"בילאסקו, אברהם משלוניקי","dt":"תקז-יז - כ ניסן","dp":"שלוניקי","b":"גביר בשלוניקי."},{"i":7950,"n":"בילוסטוצקי, אהרן","b":"פרסם מאמרים ב\"אהל תורה\" - ירושלים תרצט."},{"i":7951,"n":"בילוסטוצקי, שמעון לוי מדיסנא","dt":"תשג","b":"רב בדיסנא"},{"i":7952,"n":"ביליא ן, דוד מפורטוגל","f":"יום טוב","k":"בעל יסודות המשכיל","b":"מחכמי פורטוגל בדורו של הרשב\"ץ, תוכן, פילוסוף, רופא, פייטן, מפרש המקרא, חיבר \"ספר יסודות המשכיל\" - מאמר כנגד יג העקרים של הרמב\"ם - נדפס בתוך \"דברי חכמים\" - מיץ תרט, חיבר גם \"ספר \"מאיר\" - \"מאור עינים\"."},{"i":7953,"n":"ביליג, אהרן","b":"תשובה אליו ב\"מחזה אברהם\"."},{"i":7954,"n":"ביליג, חיים אורי ליביש מגוליגו","b":"חתן ישכר דב בער מגזע צבי מזלוטשוב. רב בגוליגור, ולאחר פטירתו נישאה אלמנתו לר אברהם חיים מזלוטשוב."},{"i":7955,"n":"ביליג, יוסף עזריאל מגליגור","f":"חיים אריה ליבוש","bt":"תקן","dt":"תרטו","b":"אב\"ד גליגור, רב בסדיגורא. גדל אצל ר אברהם חיים מזלוטשוב שהיה אביו החורג והדפיס את ספרו \"אורח לחיים\"."},{"i":7956,"n":"ביליג, צבי אריה","b":"מאמרים ממנו ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד. (אחר פטירתו?)"},{"i":7957,"n":"ביליטירו, אברהם משלוניקי","dt":"תצג - כא שבט","dp":"שלוניקי","b":"מחכמי שלוניקי"},{"i":7958,"n":"בילינסון, משה אלעזר מאודסה","f":"נחמן","b":"מדפיס באודסה. הו\"ל \"יגדיל תורה\" - אודסה תרלט, \"שמעתתי דרבנן\" - אודסה תרמז, \"מכילתא דרבנן\" - תרמו, סייע בהדפסת \"כנסת חכמי ישראל\" - אודסה תרנג."},{"i":7959,"n":"ביליסיד, גדליה משלוניקי","dt":"שא - ו חשון","dp":"שלוניקי","b":"פייטן וחזן מחכמי שלוניקי. חתם עם חזנים נוספים על שאלה לרא\"ם בדבר החזרה על \"ה אלוקיכם אמת\"."},{"i":7960,"n":"ביליץ, דניאל מסעגעד","b":"רב בסעגעד בזמן החת\"ס. היה מחלוקת כנגדו מצד היראים."},{"i":7961,"n":"ביליצקי, גרשון תנחום פויז'נאק","f":"אליהו בנימין ממיר","k":"בעל אילנא דחיי","dt":"תרמא-ד -טו אד\"א","b":"תלמיד ר אליהו רגולר. חתן ר אברהם חיים שפירא מסמרגון. מו\"ץ ור\"מ ב\"בלומקעס קלויז\" במינסק-תרמג, ויחד עם חבריו ר אריה רבינוביץ בעל \"באר היטב\", ור משה ליב-חתן ר דוד טעביל בעל \"מילי דאבות\" - מנהיגי קהלת מינסק בזמן שבין רבנות ר דוד טעביל בעל \"בית דוד\" ועד למינוי של הגדול ממינסק, רב ביאנישובקה-תרס עד תרץ. פרסם מאמרים ב\"היהודי\" - נ\"י תרצו. בנו ר יצחק אריה מיאזנה ומאליאט. חתניו: ר ישעיה קרלינסקי, ר אברהם מאיר אפשטין, ר בצלאל טרעפעל. פרסם מאמרים ב\"שערי ציון\" - ירושלים תרפא."},{"i":7962,"n":"ביליצקי, דוד צבי","dt":"תשג","b":"רב בקובנה"},{"i":7963,"n":"ביליצקי, יחיאל מווידישק","dt":"תשג","b":"רב בווידישק. פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":7964,"n":"ביליצקי, יצחק אריה מיאזנה","f":"גרשון תנחום מישינקוב","bt":"תרמג-ז","bp":"יאסינובקה","dt":"תרצג-ד -כא אלול","b":"חתן ר יעקב קנציפוביץ מסלובודקה. רב ביעזנא(=יאזנה)-תרסז, מאלטש(=מאליאט)-תרפא ובנו ר נטע על מקומו אחריו. (ביהדות ליטא תאריך פטירתו - תרפט)."},{"i":7965,"n":"ביליצקי, נטע ממאליאט","f":"יצחק אריה ממאליאט","bt":"תרסח","dt":"תשא - אב","b":"רבה האחרון של מאליאט על מקום אביו. נספה בשואה."},{"i":7966,"n":"ביליצקי, תנחם גרשון מיאנישוק","dt":"תרץ - בערך","b":"אולי נכדו של ר גרשון תנחום ממינסק. חתן ר אברהם חיים שפירא. רב ביאנישובקה(=יאשינאווקא)-תרס. בניו ר יצחק אריה מיאזנה ומאליאט, ר חיים אברהם ביאליק. חתניו: ר ישעיה קרלינסקי, ר אברהם מאיר אפשטין. פרסם מאמרים ב\"שערי ציון\" - ירושלים תרפא, \"היהודי\" - נ\"י תרצו."},{"i":7967,"n":"ביליצר, אורי ליפמן מאלטנדורף","f":"יצחק איזיק הלוי מנאד","bp":"נאדי אידא","dt":"תרסו - יד טבת","b":"תלמיד הכת\"ס, ור אהרן דוד דייטש מבאלאש ירמוט. רב באלטנדורף-תרטו, חתנו ר מרדכי הכהן שטרסר על מקומו אחריו-תרסו. פרסם מאמרים ב\"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז."},{"i":7968,"n":"ביליצר, אפרים הלוי מבעטלאן","f":"פנחס הלוי מסערענטש","k":"בעל יד אפרים","bt":"תרם-תרנא","bp":"סערענטש","dt":"תשד - ז סיון","dp":"אושוויץ","b":"תלמיד הדעת סופר, וגיסו ר אשר אנשל יהודה מילר מפעטרזשען. חתן ר יהודה ליכטנשטין מבעטלאן, ר\"מ בישיבת חותנו בבעטלאן ודיין שם. נספה בשואה. חיבר \"פותח שערים\", \"יד אפרים\". פרסם מאמרים ב\"עמוד התורה\" - דעש תרצב."},{"i":7969,"n":"ביליצר, יהודה","dt":"תשד","b":"רב בנ' עלאוואד"},{"i":7970,"n":"ביליצר, יואב הלוי מאלטנדורף","f":"אורי ליפמן מאלנטדורף","k":"בעל אלה המצות"},{"i":7971,"n":"ביליצר, יואל","b":"תלמיד החת\"ס. חתנו - ר שמואל קורניצר בן ר אליהו-חתנו של החת\"ס."},{"i":7972,"n":"ביליצר, יוסף שמואל סגל","b":"ראש מדינה ובית דין של ועד ארבע ארצות-ת\"צ"},{"i":7973,"n":"ביליצר, יצחק איזיק הלוי מנאדי","f":"פנחס מאונסדורף","k":"בעל באר יצחק","bt":"תקסא","bp":"אונסדורף","dt":"תרמז - ט סיון","dp":"נאדי-אידא","b":"תלמיד ר יוסף יעקב ניישלס מסערדאוהל, ר משה מינץ מאויבן. חתן ר משה רוט מגינץ-רוסקא ועבר לשם. רב בנאדי-אידא-תקצח על מקום ר משולם ליברמן."},{"i":7974,"n":"ביליצר, עמרם ישי סגל מסערנטש","f":"יצחק איזיק הלוי מנאד","dt":"תרמט - כד תמוז","b":"רב בסערענטש(=סאראנץ') ובנו ר פנחס על מקומו אחריו. הניח חבורים בכת\"י."},{"i":7975,"n":"ביליצר, פנחס סגל מאונסדורף","f":"שמואל","b":"נכד בעל \"מסורת הש\"ס. רב וגביר באונסדורף-תקפ. בנו - ר יצחק איזיק מנאדי-אידא."},{"i":7976,"n":"ביליצר, פנחס סגל מסערנטש","f":"עמרם ישי מסערנטש","k":"בעל גבעת פנחס","bt":"תרכ","dt":"תרעג - א אלול","b":"חתן הגביר ר לוי יצחק ממונקטש ועבר לשם. דרשן, רב בסערענטש-תרמט על מקום אביו. נכד ר יצחק איזיק מנאדי-אידא. שאלה ממנו לר שמואל דוד יונגרייז."},{"i":7977,"n":"ביליצר, שמעון או שמשון הלוי","dt":"תשד","b":"רב בריטשע"},{"i":7978,"n":"ביליקוף, יעקב מליטא וארה\"ב","bt":"1883","bp":"וילנא","dt":"1950","b":"עיגר לארה\"ב-1897, עסקן ציבור, מנהל בפועל של \"ועד העזרא היהודי אמריקאי\"-1917 בזמן מלחה\"ע ה-I, וחבר הנהלת הג'וינט וחקר את מצבם של יהודי מזרח אירופה. גזבר אוניברסיטת הארוורד."},{"i":7979,"n":"בילכובסקי, הירש מלומזא","b":"פרסם מאמרים ב\"שערי אורה\" - מיהאלביץ תרץ-תרצד."},{"i":7980,"n":"בילמונטי - משפחה","b":"משפחה מספרד (פירוש השם בלימונטי = מקום יפה), גלו לתורכיה."},{"i":7981,"n":"בילמונטי, יעקב ישראל מאמשטרדם","dt":"שץ","dp":"אמשטרדם","b":"גביר ממגורשי ספרד באמשטרדם, קבע מנין בביתו באמשטרדם, יסד ביכ\"נ בפיררה-שעד עם ר רעואל ישורון ור יוסף ישראל פיררה. חיבר ספרים בספרדית ושירים. לזכרו יסד ר שאול מורטירה ישיבה באמשטרדם."},{"i":7982,"n":"בילמונטי, משה הספרדי","k":"בעל מאמר נגד האלילים","b":"חיבר מאמר נגד האלילים. תרגם לספרדית פרקי אבות."},{"i":7983,"n":"בילעסקי, גרשון מאנגליה","f":"יוסף","bt":"תרכח","b":"תלמיד ישיבת ראמסגט-אנגליה (ישיבה שנוסדה ע\"י משה מונטיפיורי), ביהמ\"ד לרבנים בלונדון. ספרן אחראי על ספריית מונטיפיורי בלונדון. הו\"ל ספרי קדמונים."},{"i":7984,"n":"בילר, אברהם אבא מזברז'","f":"דוד אליהו","k":"בעל אבא בגבורות","bt":"תקפד","dt":"תרסה","b":"מחכמי זברז'. חיבר \"אבא בגברות\" הוסיאטין."},{"i":7985,"n":"בינאש, יוסף מצפת","b":"מראשי קהלת צפת-תנו בזמן ר שמעון גויוזו, יחד עם ר יצחק נעמיאש, ור יוסף שאלתיאל קנפנטון."},{"i":7986,"n":"בינג - משפחה","b":"משפחה בפפד\"א."},{"i":7987,"n":"בינג, אברהם מפפד\"מ","k":"בעל זכרון אברהם","r":"אבד\"ק ווירצבורג","bt":"תקיב","bp":"פפד\"מ","dt":"תרא - ה אדר","b":"תלמיד ר נתן אדלר בפפד\"מ. רב בהמ\"ד אופנבך, דומ\"צ בפפד\"מ, רב בהיידינגספלד-וירצבורג-תקן בערך. חבר ילדות של החת\"ס, ונזכר בשו\"ת החת\"ס.","bk":[["זכרון אברהם",""],["שלמה לאברהם - יו\"ד",""]]},{"i":7988,"n":"בינג, געץ מפפד\"מ","b":"מחכמי פפד\"מ-שכה, תמך אך לא חתם לצד ר אליעזר טרוויש וחכמי פפד\"מ על מכתב לרבני שוואבן בנוגע למחלוקת בין ר שמעון גינצבורג בתמיכת ר יצחק איזיק גינצבורג לבין ר נתן שאטין בתמיכת ר אליעזר טרוויש מפפד\"מ - בגלל שהיה טרוד בעסקים."},{"i":7989,"n":"בינג, הרץ מברלין","b":"מראשי הקהילה בברלין, חתם על כתב הרבנות של ר צבי הירש מלונדון וברלין-תקלב."},{"i":7990,"n":"בינג, יהודה מיכל מפפד\"מ","dt":"תקכג-ז","b":"מראשי קהילת פפד\"מ-תקך, ונמנה על קבוצת הרבנים שמילאו את מקומו של ר יעקב יהושע בעל ה\"פני יהושע\". היה במשלחת אל הקיסר-תקכו."},{"i":7991,"n":"בינג, יהודה מפפד\"מ","f":"מיכל","dt":"תקלז - יט אלול","dp":"פפד\"מ","b":"מראשי קהילת פפד\"מ-תפ בערך."},{"i":7992,"n":"בינג, יצחק מירושלים","f":"שמואל","k":"הו\"ל מגיד מישרים","b":"מקובל מחכמי ירושלים, בשנת תה בשליחות בפולין. בשנת תו הוציא לאור \"מגיד מישרים\" המיוחס לר יוסף קארו (יחד עם ר אלישע חיים בן יעקב אשכנזי - שאולי היה אביו של נתן העזתי), בשנת תיד בשליחות באירופה והדפיס חלק שני מהספר על פי כתב יד שהגיע אליו מירושלים על ידי ר אלישע אשכנזי."},{"i":7993,"n":"בינג, יצחק מפפד\"מ - א","f":"ליב?","b":"מחכמי פפד\"מ, היה חבר בועדה בראשות ר מיכאל שפייאר שניסחה את תקנות הקהילה-תקמד."},{"i":7994,"n":"בינג, יצחק מפפד\"מ - ב","b":"פרסם מאמרים ב\"המסדרונה\" - פפד\"מ-ירושלים תרמה."},{"i":7995,"n":"בינג, יצחק מצפת","f":"ברוך","b":"מחכמי צפת, מראשי עדת האשכנזים, בשנת שפב חתם על המכתב לר ישכר בר איילנבורג אודות רבנות צפת."},{"i":7996,"n":"בינג, ישי בער ממיץ","bt":"תקיט","dt":"תקסה","dp":"פאריס","b":"משכיל מחכמי מיץ. חיבר ספר בצרפתית להגן על יהודי אלזס."},{"i":7997,"n":"בינג, מיכאל חיים מפפד\"מ","f":"יצחק מפפד\"מ","b":"תלמיד השב\"ס-תרלט."},{"i":7998,"n":"בינג, פנחס זליגמן מפפד\"מ","f":"משה נפתלי","dt":"תיג - ב טבת","dp":"פפד\"מ","b":"מחכמי פפד\"מ."},{"i":7999,"n":"בינג, קלונימוס","b":"כתב הקדשה לבנו לבר המצוה-תרכז. בנו - יונה שבתי."},{"i":8000,"n":"בינג, שניאור זיסקינד מפפד\"מ","f":"שמואל","dt":"שלה - כה כסלו","b":"מחכמי פפד\"מ."},{"i":8001,"n":"בינדיגר, אלימלך אלעזר משינאווא","dt":"תשג","b":"רב בשינאווא. נספה בשואה."},{"i":8002,"n":"בינדיגר, אלימלך משינאווא","f":"אלעזר","k":"אדמור משינאווא","bt":"תרך או תרמא","bp":"שיניבה","dt":"תרצה - כ תשרי","dp":"מארוש-ואשארהי","b":"מצאצאי ר אלימלך מליזנסק וה\"דברי חיים\" מצאנז, נכד ר יחזקאל הלברשטם משינאווא. גדל אצל זקנו ר יחזקאל שרגא משינאווא. חתן דודו ר משה הלברשטם משינאווא. רב בשינאווא-תרסו על מקום אביו וחותנו - שעבר לצאנז. בזמן מלחה\"ע ה-I התישב בדעש וכיהן כאדמור משינאווא, עבר למארוש-ווארשארהי-תרץ. בנו ר חיים אלעזר משינאווא. (אצל וונדר תאריך הפטירה - תרפה ובאוצר הרבנים - תשג)."},{"i":8003,"n":"בינדיגר, אלעזר ליפא ממולדביצה","f":"ברוך אברהם","bt":"תרסג","bp":"דעש","dt":"תשה","b":"תלמיד בעל \"זכרון יעקב\". חתן ר מאיר מושקוביץ משאץ. רב במולדביצה (רומניה). ניצל מהשואה ואחריה רב בדעש. בנו ר מאיר ראש ישיבה בויינלנד - ארה\"ב."},{"i":8004,"n":"בינדיגר, אלעזר משינאווא","f":"שמואל זנויל","bt":"תר","dt":"תרם","b":"חתן האדמור ר יחזקאל הלברשטם משיניבה. חתנו - ר אברהם מרדכי רוזנפלד ממושציסק."},{"i":8005,"n":"בינדיגר, ברוך אברהם מדעש","f":"צבי יוסף","bt":"תרמה","bp":"פשמישל","dt":"תשד - יח סיון","dp":"אושויץ","b":"חתן ר משה פנט מדעש, ועבר לשם, רב בדעש-תרץ. נספה בשואה."},{"i":8006,"n":"בינדיגר, ברוך אברהם מהנישביץ","f":"שרגא פיבל","dt":"תרלה - א אלול","b":"מצאצאי הב\"ח. תלמיד ר ישראל המגיד מקוזניץ, ר נפתלי צבי מרופשיץ, והדברי חיים מצאנז. אב\"ד הנישביץ. שרף את כל כתביו לפני פטירתו. בנו ר שמואל זנויל מברדיוב שעלה לארץ. וחתנו ר יעקב צבי ולדמן מבורשא."},{"i":8007,"n":"בינדיגר, חיים אליעזר","dt":"תשג","b":"רב בשינעווע"},{"i":8008,"n":"בינדיגר, ישכר בריש מקאלווריה","dt":"תשג","b":"רב בקאלווריע(=קלווריה)-גליציה. חתנו ר אלעזר בלויגרונד על מקומו אחריו."},{"i":8009,"n":"בינדיגר, שמואל זנויל מברדיוב","f":"ברוך אברהם מהנישביץ","dp":"ירושלים","b":"חתן ר נפתלי (או אלעזר) מליזנסק נכד הנועם אלימלך, ובזיוו\"ש חתן ר משה אליקים בריעה מקוזניץ. עלה לארץ."},{"i":8010,"n":"בינדר, יעקב מוילמסדורף ופיורדא","f":"נפתלי","b":"מדפיס בדפוס חיים בן צבי הירש בפיורדא - תקל."},{"i":8011,"n":"בינהורן, אביש מטורקא","f":"שלמה","bt":"תרן","bp":"טורקא","dt":"תרפו","b":"תלמיד ר\"א מישל מטורקא ומהרש\"ג מסמיהלי. חסיד בלז. חתן ר חיים דים מקורטשין ועבר לשם. רב בבלז ומתלמידיו ר מרדכי רוקח מבילגורי. חדושיו אבדו."},{"i":8012,"n":"בינהורן, מאיר מוורצקי","f":"צבי מסטניסלב","bp":"סטניסלב","dt":"תרלג","b":"אחיו - ר שמואל - שו\"ב בטורקא. חתן ר מאיר רולר. תלמיד ר יצחק חרי ףמסמבור ועוד. חסיד רמ\"מ מרימנוב. שו\"ב בוורצקי ואח\"כ רב. הבי\"ש התיעץ עמו בהלכה."},{"i":8013,"n":"בינהורן, צבי אריה מברזנא","f":"שמואל","bt":"תקעז","dt":"תרסא","b":"חתן ר שלמה אליעזר האדמור מטורקא. שו\"ב בוויבלא, ברזנא. חסיד דינוב ומקורב לגדולי האדמורים."},{"i":8014,"n":"בינהורן, שלמה אליעזר מטורקא","f":"צבי אריה","bt":"תריט","dt":"תרפד","dp":"מונקטש","b":"חתן ר שמואל שרייבר מטורקא ועבר לשם. חסיד בלז. עבר למונקטש."},{"i":8015,"n":"בינושביץ, קלמן מקלם","f":"יחזקאל","k":"העילוי מז'אזמיר","bt":"תרמו-נג","bp":"ז'אזמיר-ליטא","dt":"תשא","dp":"קעלם","b":"תלמיד החפץ חיים בראדין, וישיבת סלובודקה. חתן ר צבי יעקב אופנהיים מקלם, רבה האחרון של קלם-תרפו על מקום חותנו. הו\"ל כתבי חותנו בלונדון. חיבר חיבור להתרת עגונות ממלחה\"ע ה-I. נספה בשואה."},{"i":8016,"n":"בינטורא, אליהו","b":"רב בווינה-תר\"ח"},{"i":8017,"n":"ביני, אפינדה הקראי מקושטא","b":"מראשי עדת הקראים בקושטא-ת'. אחיו - שמואל ביני."},{"i":8018,"n":"ביני, בנימין הקראי מקושטא","b":"מראשי עדת הקראים בקושטא-ת'."},{"i":8019,"n":"ביני, שמואל הקראי מקושטא","b":"מראשי עדת הקראים בקושטא-ת'. אחיו - אפינדה ביני."},{"i":8020,"n":"ביניש, יוסף ברדשי משלוניקי","b":"מחכמי שלוניקי-ת'."},{"i":8021,"n":"ביניש, משה ברדשי משלוניקי","b":"מחכמי שלוניקי-ת'."},{"i":8022,"n":"ביננפלד, זאלי","dt":"תרלא - כט שבט","b":"דיין בוורשה"},{"i":8023,"n":"ביננפלד, צבי יהודה","f":"משה","dt":"תרד","b":"מחכמי קראקא, בנו ר זאלי היה דיין בוארשא."},{"i":8024,"n":"ביננשטוק, לוי מקראקא","f":"דוד יצחק","k":"בעל בית לוי","bt":"תרף","bp":"קראקא","dt":"תרן","b":"דיין בזלושיץ. חיבר \"בית לוי\" וארשא תרמג."},{"i":8025,"n":"בינקוביץ, אריה ליב מניו יורק","f":"אברהם שלמה מביאליסטו","k":"בעל מעון אריה","bt":"תריב","bp":"ביאליסטוק","b":"מו\"ץ בביאליסטוק כ-10 שנים אצל ר שמואל מוהליבר. היגר לארה\"ב-תרנו, וכיהן כרב בניו יורק-תרסו;. חיבר \"מעון אריה\" וארשא תרמו, \"ראשון לציון\", ועוד. הניח חבורים בכת\"י."},{"i":8026,"n":"בינר, מיכל מבאריש","b":"רב בבאריש-תרנח. (השם מיכל ולא משה!)"},{"i":8027,"n":"בינשטוק, חיים אורי","dt":"תש..","b":"רב בפודמקין בין מלחמות העולם. גבאי ארץ ישראל. שם אמו גולדה ואשתו רבקה בת מרים."},{"i":8028,"n":"בינשטוק, שמעון מיאנדזוב","b":"מו\"צ ביאנדזוב-תר\"ע"},{"i":8029,"n":"ביסודו, אברהם מצפת","dt":"רסט","dp":"עין זיתים","b":"מחכמי צפת וחתם על מכתב רבני צפת לרבני ירושלים, חתום על תעודה משנת רסד."},{"i":8030,"n":"ביסודו, משה מצפת","b":"מחכמי צפת בזמן ר יוסף קארו, רב קהלת הסיציליאנים בדמשק. נזכר ב\"אבקת רוכל\" ובשות המבי\"ט."},{"i":8031,"n":"ביסודו, נסים חיים מקושטא","b":"דיין בקושטא-תקעו."},{"i":8032,"n":"ביסטריץ, דוד כץ ממילכדורף","f":"קלונימוס קלמן זאב","k":"בעל בית דוד","bt":"תקעג","dt":"תרכד - ו תמוז","dp":"מילכדורף","b":"נכד ר בנימין זאב עמריך מעיר חדש. תלמיד החת\"ס. חתן ר שמעון מנדל מסמניץ (בהמלצת החת\"ס) ועבר לשם. רב במילכדורף-תרט, העדילא-מאדע-תרכד (ונפטר בטרם התחיל רבנותו)."},{"i":8033,"n":"ביסטריץ, חיים","dt":"תשג","b":"רב בפלדניצה"},{"i":8034,"n":"ביסטריץ, יוסף מואג-ביסטריץ","f":"עזריאל","b":"תלמיד החת\"ס. אחיו של ר גרשון ביסטריץ - מופיע במכתב מאת ר חיים יוסף פולק שנשלח אליו - על אודות אחיו יוסף תלמיד בישיבה."},{"i":8035,"n":"ביסייא, יהודה מפאס","b":"רב בפאס בזמן ר חיים גאגין, על ידו נשלחה ההסכמה בענין הנפיחה."},{"i":8036,"n":"ביסליכס, מרדכי ליב מברוד","f":"משה","k":"הו\"ל ישועות משיחו","bt":"תקס","bp":"ברודי","dt":"תריא","b":"נדד בארצות אירופה, איטליה, צרפת, הולנד ואנגליה. חוקר וביבליוגרף שחקר כתבי יד קדומים. הוציא לאור כתבי קדמונים וביניהם: \"ישועות משיחו\" לדון יצחק אברבנל, קרלסרוא (ובאמת אוסטרהא) תקפח, ועוד. חיבר מודעא \"קול קורא\" למברג תקצד."},{"i":8037,"n":"ביסמוט, יוסף מתונס","b":"ראש ישיבה בתונס-תקי, מתלמידיו ר שמואל צוייד."},{"i":8038,"n":"ביסמוט, שלום חי מתונס","b":"דיין בתונס-תרכא אצל ר ישועה בסיס, ור נתן בורג'ל השני."},{"i":8039,"n":"ביסנדו, יהודה מירושלים","dt":"תטו","dp":"ירושלים","b":"מחכמי ירושלים, בשנת תו חתם על תקנת פטור המסים. ר דוד קונפורטי פגשו בירושלים בשנת תיב. הסכים על ספר \"זהרי חמה\" בשנת תח."},{"i":8040,"n":"ביעלסקי, יהושע","b":"רב-שנת תר\"ל"},{"i":8041,"n":"ביעלסקי, יצחק נפתלי הערץ ממוצי","f":"יהושע","bt":"תרל","b":"רב במוציד-פלך גרודנא-תרסא."},{"i":8042,"n":"ביציק, זוסמן גרשון מגלוואן","b":"שו\"ב בגלוואן-ליטא שנים רבות."},{"i":8043,"n":"ביק אברהם יהושע","bt":"1913","dt":"ה'תשנ 1990","bk":[["חזון התקופה",""],["חסידות מאטיוון",""],["משנת פועלים",""]]},{"i":8044,"n":"ביק, אברהם יהושע מניו יורק","k":"בעל חזון התקופה","b":"רב בניו יורק-תרצד. חיבר גם \"משנת פועלים\"."},{"i":8045,"n":"ביק, אברהם יצחק מסוכסטוב","b":"אב\"ד סוכסטוב(=סוכטשוב) - תרלה-תרמג. תשובות אליו ב\"ארץ צבי\" ובשו\"ת מהרשם."},{"i":8046,"n":"ביק, אברהם מפרשבורג","f":"יעקב","k":"בעל בכורי אביב","bt":"תקצז","bp":"פרשבורג או רוסיה","dt":"תרסב","dp":"פרשבורג","b":"גיסו של ר יצחק יעקב ריינס מלידא. מחכמי פרשבורג, עלה לירושלים, חזר לפרשבורג ויסד שם בית דפוס. חיבר \"בכורי אביב\" למברג תרלג, ועוד. פרסם מאמרים ב\"המסדרונה\" - פפד\"מ-ירושלים תרמה."},{"i":8047,"n":"ביק, אליעזר מלמברג","b":"מחכמי למברג. תלמיד השו\"מ שהזכירו בספרו \"יוסף דעת\"."},{"i":8048,"n":"ביק, חיים יחיאל מיכל ממזבוז","b":"רב במזבוז, ניו יורק. אביו של ר משה צבי רב בניו יורק."},{"i":8049,"n":"ביק, חיים ממאהליב","f":"שמחה ממוהליב","bt":"תריד","b":"רב במאהליב-תרמז על מקום אביו."},{"i":8050,"n":"ביק, יחיאל מיכל מטרנופול","b":"מחכמי טרנופול-תקצט."},{"i":8051,"n":"ביק, יצחק ממזיבוז","b":"רב במזיבוז-תר\"ס"},{"i":8052,"n":"ביק, מאיר מנחם מנדל ממזיבוז","k":"בעל אבות מלאכות","b":"אב\"ד מזיבוז. חיבר גם \"ספר החיים\", \"חקת הפסח\", ועוד."},{"i":8053,"n":"ביק, מנחם מנדל","f":"פיבוש ביק","b":"רב בראוונע"},{"i":8054,"n":"ביק, משה מברודי","b":"גביר בברודי. חתן ר שלמה זלמן זוסמן מאוסטרהא."},{"i":8055,"n":"ביק, משה צבי מניו יורק","f":"חיים יחיאל מיכל","b":"מחשובי הרבנים בניו יורק."},{"i":8056,"n":"ביק, סנדר מנדל מברוד","b":"מחכמי ברודי. תשובה אליו ב\"חדושי אנשי שם\"."},{"i":8057,"n":"ביק, פייביש","f":"שמואל ביק","b":"רב בלענטשנא-תק\"נ"},{"i":8058,"n":"ביק, שאול ישכר מארה\"ב","f":"יצחק ממזיבוז","k":"בעל יד שאול","bt":"תרמג","bp":"יאמפולי","dt":"תשלא - כג אייר","b":"נסמך מאת האמדור ר\"מ מהורניסטפל. רב במזיבוז-תרסד, קמרון-תרעב, מוהליב-תרפא, היגר לארה\"ב וכיהן כרב קהלת \"קשר אחים\" ברוקלין-תרפט, עלה לארץ והתישב בבני ברק-תשט. חבר אגודת הרבנים באמריקה."},{"i":8059,"n":"ביק, שמואל","b":"מגדולי ונכבדי ברודי-תק\"ל"},{"i":8060,"n":"ביק, שמואל","f":"משה סגל","b":"תלמיד השו\"מ בלמברג - השיב לו ב\"יוסף דעת\"."},{"i":8061,"n":"ביק, שמחה ממאהליב","b":"רב במאהליב-תרל ובנו ר חיים על מקומו אחריו-תרמז"},{"i":8062,"n":"ביקייאם, מאיר משלוניקי","f":"חלפא","k":"בעל מאיר בת עין","bt":"תע - בערך","bp":"אזמיר","dt":"תקכט - כט תמוז","dp":"אזמיר","b":"רב ומקובל בשלוניקי-תק. חיבר גם \"גולל אור\", \"מאיר לארץ\" ועוד."},{"i":8063,"n":"ביקלס, גדליה מלמברג","b":"עבר לברלין ולמד בביהמ\"ד לרבנים-תרמה."},{"i":8064,"n":"בירב, אברהם","f":"יעקב","dt":"שיט - לפני","b":"מחכמי צפת-שן. בנו של ר יעקב בירב, והסכים עמו בכמה פסקים, חברו של המבי\"ט ונזכר בתשובותיו. בניו: ר יעקב בירב השני, ר משה."},{"i":8065,"n":"בירב, אהרן ממצרים","f":"יעקב השני","b":"נינו של ר יעקב המוסמך. רב במצרים-ת' בערך. נזכר בספרי חכמי דורו ובהם \"אבקת רוכל\"."},{"i":8066,"n":"בירב, אהרן מצפת","f":"יעקב המוסמך","dt":"שפה","dp":"צפת","b":"בנו של ר יעקב בירב הזקן, ואחריו היה ראש הישיבה בצפת"},{"i":8067,"n":"בירב, יוסף מקושטא","b":"נכד ר יעקב בירב מצפת. רב במצרים, קושטא-שנות ה-ש'."},{"i":8068,"n":"בירב, יעקב (הנכד)","f":"אברהם","bt":"שה","bp":"צפת","b":"מחכמי צפת, נכדו של ר יעקב בירב הראשון. כיהן כרב במצרים. היה בקשר עם ר יוסף קארו ועם המבי\"ט. ר ישראל נג'ארה מזכירו באחד משיריו. נספד על ידי ר נפתלי אשכנזי בספר \"אמרי שפר\". חתנו - כלב פינטו מדמשק."},{"i":8069,"n":"בירב, יעקב - המוסמך","f":"משה","k":"בעל שו\"ת","bt":"רלד","bp":"ליד טולדו-ספרד","dt":"שו - א אייר","dp":"צפת","b":"תלמיד ר יצחק אבוהב, רב בפאס, תלמסאן, דיין אצל הנגיד ר יצחק שולאל במצרים, עלה לירושלים לפני רפ שם עמד בראש ישיבה. לימים הגיע לצפת והיה רבם של גדולי צפת, למרות שלפרנסתו עסק במסחר ולצורך כך נסע הרבה גם לדמשק ולחלב. חידש את הסמיכה בצפת אך נכנס למחלוקת עם רב ירושלים ר לוי ן חביב, הספיק לסמוך 4 תלמידים וביניהם ר יוסף קארו. חיבר שו\"ת ונציה תכג, ועוד. בניו: ר משה, ר אהרן מצפת, ר יצחק מצפת, ר אברהם-חברו של ר משה מטרני - נפטר בחיי אביו, וחתנו - ר חיים אבולעפיה מדמשק."},{"i":8070,"n":"בירב, יעקב ממצרים הנכד","f":"אהרן","b":"רב במצרים-תל. נכדו של ר יעקב מחדש הסמיכה."},{"i":8071,"n":"בירב, יעקב מצפת הנכד","f":"חיים","k":"בעל זמרת הארץ","bp":"צפת","dp":"טבריה","b":"סופר ומשורר מחכמי צפת-תק, מצאצאי ר יעקב בירב מחדש הסמיכה, חתן ר חיים אבולעפיה, בשנת תע יצא עם חותנו לאזמיר, בשנת תק עלה עם חותנו לטבריה. חיבר \"זמרת הארץ\" מנטובה תקה, ובספר תיאר את קורות הקהלה בטבריה - סייעו לו הגיבר ר הלל פדואה ור שלמה רוקח מטבריה. היה משורר ופייטן."},{"i":8072,"n":"בירב, יצחק","b":"חכם השלם,דיין-שנת ר'"},{"i":8073,"n":"בירב, יצחק מצפת","f":"יעקב המוסמך","b":"רב בצפת על מקום אביו."},{"i":8074,"n":"בירב, משה","f":"יצחק בירב","b":"רב-שנת ר\"מ"},{"i":8075,"n":"בירב, משה מצפת ומצרים","f":"יעקב המוסמך","b":"רב בצפת לצד אחיו ר יצחק. מחכמי מצרים. ידידו של ר ישראל נג'ארה, נזכר בשו\"ת חכמי דורו, חתם בשנת שנז ושפה על תקנות. והיה מחלוקת בינם לבין ר שמואל הכהן שנתמך ע\"י ר בצלאל אשכנזי, והמבי\"ט סייע בעדם כמובא בספרו."},{"i":8076,"n":"בירבה, חיים יעקב מירושלים","dt":"תרי - כח שבט","dp":"ירושלים","b":"חזן מחכמי ירושלים."},{"i":8077,"n":"בירבראייער חיים אלטיר","bt":"1860","dt":"ה'תש 1940","bk":[["קול נהי בכי תמרורים",""]]},{"i":8078,"n":"בירברויאר, אלתר חיים","f":"ישעיה מקמניץ פודוליא","k":"בעל אסיפת חכמים","bt":"תרך","dt":"תש","b":"נסמך מאת: ר שואל מחאטין. חסיד בויאן ונלוה לאדמור ר מנחם נחום בביקורו בארץ-תרפז. ראב\"ד אטיניא. הוציא לאור קובץ \"אסיפת חכמים\" - אטיניא - בויאן - תרסט. חיבר הספד \"קול נהי ובכי תמרורים\" טשרנוביץ תרצו."},{"i":8079,"n":"בירברויאר, ישעיה מקמניץ-פודולי","b":"דומ\"צ בסקווירא,רב בקמניץ-פודוליא-תרמ. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא תרע (בעריכת בנו ר אלתר)."},{"i":8080,"n":"בירברייער, חיים אלתר מקמניץ","b":"מתורתו ב\"קובץ מפרשי התורה\" - מארגרטן תרצג."},{"i":8081,"n":"בירגר, שמואל","k":"בעל שבעה עינים","dt":"תרסה","b":"דומ\"צ בסעמערין,גלנטא"},{"i":8082,"n":"בירדוגו - משפחה","b":"מקור המשפחה בקסטיליה ולאחר הגירוש התישבו בפאס-מרוקו. נדדו למכנאס בגלל המחלוקת בין יהודי מרוקו הותיקים לבין מגורשי ספרד, והקימו את הקהלה שם. הנהיגו את הקהלה ושמשו כרבנים ודיינים במשך מאות שנים יחד עם משפחת טולידנו."},{"i":8083,"n":"בירדוגו, אברהם ממכנאס","b":"מחכמי מכנאס, חתם על הסכמה-תקץ."},{"i":8084,"n":"בירדוגו, אברהם ממכנאס - הנכד","f":"רפאל-מהר\"ף","b":"מחכמי מכנאס-מרוקו. נזכר בהקדמה ל\"ראש משביר\"."},{"i":8085,"n":"בירדוגו, אברהם ממרוקו - הזקן","f":"יצחק ממכנאס","b":"מחכמי מרוקו, בנו - ר משה-המשבי\"ר."},{"i":8086,"n":"בירדוגו, אליעזר","f":"שלמה"},{"i":8087,"n":"בירדוגו, אליעזר ממכנאס","b":"רב במכנאס-תר בערך."},{"i":8088,"n":"בירדוגו, אלישע ממכנאס","f":"יקותיאל","k":"בעל גלי עמיקתא","b":"מו\"ץ במכנאס, חתם על פס\"ד-תרטז עם ר אברהם אביטבול, ור אהרן אלמליח. חיבר \"גלי עמיקתא\" יחד עם דודו ר יעקב בירדוגו."},{"i":8089,"n":"בירדוגו, דוד","b":"מחכמי ורבני מרוקו"},{"i":8090,"n":"בירדוגו, דניאל","f":"שלמה","b":"מרבני מקנאס, ראש השוחטים"},{"i":8091,"n":"בירדוגו, דניאל ממכנאס","f":"שלמה","b":"מחכמי מכנאס-שנות ה-תק', בנו - ר שלמה."},{"i":8092,"n":"בירדוגו, חיים","f":"אברהם","bt":"תרכג","bp":"מרוקו","dt":"תשד - כז שבט","b":"מגדולי הרבנים במרוקו וראש ישיבת \"עץ חיים\"-תרמח."},{"i":8093,"n":"בירדוגו, יהודה","f":"יהושפט","bp":"מכנאס","dt":"תקסה - לפני","dp":"טבריה","b":"מחכמי טבריה, עלה עם אביו ונמנה עם חכמיה-תקן, חתם על כתב שליחות ר יהודה בן ישראל סגרי."},{"i":8094,"n":"בירדוגו, יהודה","f":"יוסף","bp":"מכנאס","dt":"תרמז","dp":"טבריה","b":"מחכמי מכנאס, בשנת תקצח חתם על מעשה בית דין עם חכמי מכנאס, עלה לטבריה בשנת תרכב. בשנת תרלד חתם בקונטרס \"כנסיה לשם שמים\", עם חכמי טבריה. בשנת תרלו בשליחות במרוקו."},{"i":8095,"n":"בירדוגו, יהודה מירושלים","k":"בעל מים עמוקים","b":"מחכמי ירושלים-תר\"ג"},{"i":8096,"n":"בירדוגו, יהודה ממכנאס - א","f":"יוסף","k":"בעל מים עמוקים","bt":"תן","dt":"תקד","b":"תלמיד המשבי\"ר. דיין במכנאס על מקום ר משה בירדוגו-המשבי\"ר יחד עם ר יעקב טולדנו ור משה אדהאן. חברו של ר חיים ן עטר בעל \"אור החיים\". אחיו של ר מרדכי. חיבר \"מים עמוקים\" ו \"מקוה המים\". בנו - ר שלמה."},{"i":8097,"n":"בירדוגו, יהודה ממכנאס - ב","f":"משה-המשבי\"ר","b":"מחכמי מכנאס-שנות ה-ת-תק'."},{"i":8098,"n":"בירדוגו, יהודה ממכנאס - ג","f":"מרדכי","b":"מו\"ץ במכנאס, חתם על פס\"ד-תריז עם ר יוסף בירדוגו, ור מתתיה בירדוגו. חתם בהקדמה ל\"ראש משביר\"."},{"i":8099,"n":"בירדוגו, יהושע ממכנאס ורבאט","b":"רב במכנאס ובנו ר רפאל על מקומו אחריו, עבר לרבאט-תשא וכיהן כרב ראשי במרוקו על מקום קרובו - ר חיים יקותיאל בירדוגו."},{"i":8100,"n":"בירדוגו, יהושע ממרוקו","bt":"תקסב - אחרי","dt":"תקפא - כה חשון","b":"מחכמי מרוקו. נפטר צעיר ללא ילדים, נזכר ב\"קול יעקב\" לאחיו ר יעקב."},{"i":8101,"n":"בירדוגו, יהושפט מצפת","b":"מחכמי צפת, חתם-תקכד על כתב שליחות ר מרדכי בונאן."},{"i":8102,"n":"בירדוגו, יוסף ממכנאס","f":"יהודה","k":"בעל כתנות יוסף","bt":"תקסב","dt":"תרטו-מט","b":"רב במכנאס על מקום ר יעקב בירדוגו, חתם על פס\"ד-תריב עם ר יהודה ור מתתיה בירדוגו. חיבר גם \"שרשים\", \"מגלה עמוקות\", ועוד."},{"i":8103,"n":"בירדוגו, יוסף ממכנאס","f":"יצחק","b":"מחכמי מכנאס-שנות ה-ת'. בניו: ר יהודה בעל \"מים עמוקים\", ר מרדכי-המרבי\"ץ. אחיו של ר אברהם-אביו של המשבי\"ר."},{"i":8104,"n":"בירדוגו, יוסף ממכנאס","f":"מימון","dt":"תקפו - יג חשון","b":"מחכמי מכנאס. נזכר בהקדמת \"ראש משבי\"ר\"."},{"i":8105,"n":"בירדוגו, יוסף ממרוקו","f":"יקותיאל","b":"מחכמי מרוקו. בנו - ר אלישע."},{"i":8106,"n":"בירדוגו, יחיא מפאס וטיטואן","f":"אהרן","dt":"שעז - לפני","b":"מחכמי מרוקו, עזב בגלל הרדיפות-שסט והתישב בטיטואן, כיהן כסגן הרב-שעד. חתם על תקנה-שסה עם ר סעדיה ן רבוח, ר שמואל ן דנאן, ר ישעיה בקיש, ועוד. חיבר חדושים על הש\"ס. (אולי הוא שישב גם במכנאס או שהיה רב אחר באותו השם)."},{"i":8107,"n":"בירדוגו, יעקב חי מטבריה","b":"מחכמי טבריה. נכד ר יוסף בן יהודה בירדוגו. הו\"ל ספר זקנו."},{"i":8108,"n":"בירדוגו, יעקב ממכנאס","f":"יקותיאל","k":"בעל קול יעקב","bt":"תקמז","dt":"תרג","b":"רב במכנאס-תר. חיבר שירים בשם \"קול יעקב\", ובסופו \"הלכתא למשיחא\", חיבר שו\"ת על השו\"ע בשם \"שופריה דיעקב\", ועוד. בנו - ר מאיר-שהו\"ל \"ישמח ישראל\"."},{"i":8109,"n":"בירדוגו, יעקב ממכנאס","f":"מרדכי","k":"בעל גלי עמקתא","dt":"תרן","b":"אב\"ד מכנאס. חיבר הקדמה ל\"משפטים ישרים\". לפי מלכי רבנן לא הוא שחיבר \"גליא עמיקתא\" על \"מים עמוקים\". הניח פסקים בכת\"י בידי ר יהושע בירדוגו."},{"i":8110,"n":"בירדוגו, יעקב ממכנאס","f":"משה","b":"מו\"ץ במכנאס, חתם על פס\"ד- עם ר יקותיאל בירדוגו, ר רפאל בירדוגו, ור יעקב בן משה בירדוגו. אולי הוא שחתם עם ר מתתיהו סירירו הראשון-תקכד (ואולי החותם הוא ר יעקב בן יקותיאל)."},{"i":8111,"n":"בירדוגו, יצחק ממכנאס","f":"יקותיאל","bt":"תקכח","dt":"תקף - טו חשון","b":"רב במכנאס, אחיו של ר פתחיה מרדכי, ור יעקב בעל \"קול יעקב\". חתם עם רבני מכנאס-תקסד. לתולדותיו בהקדמה ל\"ראש משביר\"."},{"i":8112,"n":"בירדוגו, יקותיאל חיים מרבאט","f":"אלישע","r":"רבה הראשי של מרוקו, נשיא וראב\"ד ביה\"ד הגדול ברבאט","bt":"תריח","bp":"רבאט-מרוקו","dt":"תש - כג אלול","b":"נינו של ר מרדכי ברדוגו-המרבי\"ץ. תלמיד דודו - ר יוסף בירדוגו בעל \"יבין שמועה\". רב במכנאס, רבאט-תרנג, חבר בית הדין הגדול במרוקו, רב ראשי במרוקו-תרצה על מקום ר רפאל אנקווה. תלמיד חבר שלו - ר דוד צאבח.","bk":[["דברי יקותיאל - פסקי דין ותשובות",""]]},{"i":8113,"n":"בירדוגו, יקותיאל מהורדלא","b":"רב בהורדלה-תר\"מ"},{"i":8114,"n":"בירדוגו, יקותיאל ממכנאס - ב","f":"מרדכי","dt":"תקסב - י תשרי","dp":"מכנאס","b":"רב במכנאס, אחיו של ר רפאל. בניו: ר פתחיה מרדכי, ר יעקב, ר יוסף, ר יצחק, ר יהושע. חיבר נימוקים. . אחד מ'בית דין של שלשה במכנאס' (ר שלמה בן אליעזר טולדנו, ר משה בן דניאל טולדנו, ר יקותיאל בן מרדכי בירדוגו)."},{"i":8115,"n":"בירדוגו, מאיר ממכנאס","f":"יעקב-בן יעקב","b":"רב במכנאס. מראשי חברת \"יחזקאל הנביא\", הו\"ל \"ישמח ישראל\" מכנאס תרצא."},{"i":8116,"n":"בירדוגו, מאיר ממרוקו","f":"רפאל-מהר\"ף","b":"רב במרוקו. נהרג עם אשתו עק\"ה, נזכר ב\"ראש משביר\"."},{"i":8117,"n":"בירדוגו, מימון ממכנאס","f":"רפאל-מהר\"ף","k":"המבי\"ן-בעל פני מבין","bt":"תקכז","dt":"תקפד","b":"רב במקנאס. חתום על תקנות רבות במכנאס. חיבר ספרים רבים, את הראשון בהיותו בן 15, ובהם \"פני מבין\"."},{"i":8118,"n":"בירדוגו, מרדכי ממכנאס","bp":"מכנאס","dt":"תרנה-ח","dp":"יפו","b":"מחכמי מכאנס, חתם שם בשנת תקץ, עלה לטבריה-תרכה ונתמנה לדיין. יצא לביקור במרוקו-תרנה וטבע ביפו."},{"i":8119,"n":"בירדוגו, מרדכי ממכנאס - א","f":"יוסף","k":"המרבי\"ץ - דברי מרדכי","bt":"תעה","dt":"תקכב - יד אב","b":"חתן קרובו המשבי\"ר (=ר משה בירדוגו). רב במכנאס על מקום אחיו יהודה עם מהרי\"ט. בניו ר משה ור רפאל, ר יקותיאל, וחתנו ר דוד חסין. חיבר עוד \"דורש טוב\", \"פרשת מרדכי\" ועוד."},{"i":8120,"n":"בירדוגו, מרדכי ממכנאס - ב","f":"רפאל-מהר\"ף","b":"רב במכנאס. חתם-תקסב עם דייני מכנאס."},{"i":8121,"n":"בירדוגו, מרדכי ממכנאס - ג","f":"יעקב","dt":"תרלט","b":"מחכמי מכנאס. נפטר צעיר בחיי אביו."},{"i":8122,"n":"בירדוגו, משה ממכנאס","f":"יוסף","dt":"תרנד - כז אייר","b":"רב במכנאס. חיבר פרושים פסקים ודרושים - בכת\"י."},{"i":8123,"n":"בירדוגו, משה ממכנאס - המשבי\"ר","f":"אברהם","k":"בעל ראש משביר","bt":"תלא","bp":"מכנאס","dt":"תצא - ה חשון","dp":"ירושלים","b":"תלמיד ר יוסף בהתית ור חביב טולידנו, היה רב במכנאס בשנים תעה-תפג - בזמן הגזרות של השליט מולאי איסמעיל ור משה אדהאן על מקומו אחריו. בבית דינו כיהנו גם ר יעקב ן צור ור יהודה ן עטר כאשר שהו במכנאס שהיתה אז עיר הבירה. עלה לירושלים והיה רבו וחברו של ר חיים בן עטר. חיבר \"ראש משביר\" ליוורנו תר, ועוד. בנו ר יהודה - נפטר צעיר."},{"i":8124,"n":"בירדוגו, מתתיהו ממכנאס","f":"יצחק בן יקותיאל","b":"דיין במכנאס, חתם-תריו עם ר יוסף הלוי ור אברהם עמר, ועם דודו-ר יעקב בעל \"שופריה דיעקב\"."},{"i":8125,"n":"בירדוגו, סעדיה ממכנאס","f":"יקותיאל","b":"מחכמי מכנאס בשנות ה-תק'. אחיו של ר יעקב בעל \"שופריה דיעקב\"."},{"i":8126,"n":"בירדוגו, עמרם ממרוקו","b":"רב במרוקו."},{"i":8127,"n":"בירדוגו, פתחיה מרדכי - ב","f":"יקותיאל","bt":"תקצח","dt":"תרפח","b":"רב במרוקו, והשיב הרבה תשובות. בניו ר אברהם ור יקותיאל."},{"i":8128,"n":"בירדוגו, פתחיה מרדכי ממרוקו","f":"יקותיאל","k":"בעל נפת צופים","bt":"תקכד","dt":"תקפ - יז אדר","b":"רב במקנאס. חיבר שיטה על התלמוד בשם \"פתוחי חותם\". שיר לכבודו חיבר ר דוד ן חסין ב\"תהלת לדוד\"."},{"i":8129,"n":"בירדוגו, רחמים דוד ממקנאס","bt":"[תריז]","dt":"תרסט - תשרי","b":"רב במכנאס."},{"i":8130,"n":"בירדוגו, רפאל דוד ממכנאס","f":"יעקב - קול יעקב","bt":"תקצב","b":"מו\"ץ במכנאס. חיבר הקדמה ומפתחות ל\"משפטים ישרים\"."},{"i":8131,"n":"בירדוגו, רפאל ממכנאס","f":"מרדכי","k":"בעל מי מנוחות","bt":"תקז","bp":"מכנאס","dt":"תקפב - כג תשרי","b":"אחיו ותלמידו של ר יקותיאל. רב במכנאס. דודו של ר יעקב אביחצירא בעל \"אביר יעקב\". חיבר שו\"ת, וחדושים לש\"ס. חיבר גם \"כף זהב\", \"לשון למודים\", \"מי מנוחות\", ועוד. בניו ר מימון-המבי\"ן, ר מרדכי ור אברהם ור מאיר שכיהנו כרבנים במרוקו."},{"i":8132,"n":"בירדוגו, רפאל ממכנאס","f":"יהושע ממכנאס","b":"רב במכנאס-תשי על מקום אביו - שעבר לרבאט לכהן כרב ראשי למרוקו."},{"i":8133,"n":"בירדוגו, רפאל ממכנאס","f":"מאיר בן יעקב ממכנאס","b":"נכד ר רפאל בעל \"קול יעקב\". רב במכנאס-תרצא."},{"i":8134,"n":"בירדוגו, שלמה","b":"רב במכנס-תק\"ס"},{"i":8135,"n":"בירדוגו, שלמה ממכנאס","f":"דניאל","k":"בעל די השב","bt":"תרטו","bp":"מכנאס","dt":"תרסו - א ניסן","b":"רב במכנאס, אחיו של ר יהודה ממכנאס. חיבר גם \"ידא דטבחא\", \"זכר עשה ואם למסורת\" ועוד."},{"i":8136,"n":"בירדוגו, שלמה ממכנאס","f":"יהודה - מים עמוקים","b":"מו\"ץ במכנאס-תקע, חיבר פירוש על רש\"י לתורה, וחדושים על הש\"ס."},{"i":8137,"n":"בירדוגו, שלמה ממרוקו","f":"יעקב - שופריה דיעקב","b":"מחכמי מרוקו."},{"i":8138,"n":"בירידאר, יעקב ממרוקו","f":"אברהם","b":"ציר ממשלת מרוקו באנגליה ואירופה."},{"i":8139,"n":"בירמן, יעקב מקאקינדא","f":"חיים","b":"תלמיד הכת\"ס. מחכמי קאקינדא-תרכה."},{"i":8140,"n":"בירמן, ישראל יוסף","bt":"תרמד","bp":"סנדובה-וישניה","b":"פרסם בכתבי עת שונים."},{"i":8141,"n":"בירנבוים, אשר ממאלטש","b":"גביר מחכמי מאלטש-פלך גרודנא. גיסו-בעל אחות אשתו של הגדול ממינסק."},{"i":8142,"n":"בירנבוים, אשר שמואל מאמשטדם","b":"גבאי פקידים ואמרכלים באמשטרדם-תרסה."},{"i":8143,"n":"בירנבוים, גרשון","dt":"תשג","b":"רב בזשאבנע"},{"i":8144,"n":"בירנבוים, חיים שמעון מקראקא","b":"מחכמי קראקא. ממשתתפי \"אהל מועד\" תרנח."},{"i":8145,"n":"בירנבוים, יוסף הכהן מקראקא","dt":"תש..","b":"מחכמי קראקא-תרץ. חתן ר ישכר בלויגרונד-אב\"ד קלווריה-גליציה. נספה בשואה. תשובה אליו ב\"משיב שלום\"."},{"i":8146,"n":"בירנבוים, יוסף מבסרביה","dt":"תשג","b":"רב במרקולשטי. פרסם מאמרים ב\"בית ועד לחכמים\" - סטמר תרפב."},{"i":8147,"n":"בירנבוים, מיכל מניו יורק","b":"דיין אצל ר משה פינשטיין בניו יורק."},{"i":8148,"n":"בירנבוים, מנחם מנדל הכהן","f":"אברהם","bt":"תרכח","b":"תלמיד ר אברהם יוסף מקריסלאווע, ר נחום גרינהויז מטראק. חתן ר יקותיאל ליב עליון מזזמיר בעל \"גליון מהרי\"ל\". מו\"צ ביוחביץ(=יוחאוויץ)-פלך ויטבסק-תרנה. נסמך מאת: ר שלמה הכהן מוילנא, ר לוי יצחק משעביז, ומאת רבותיו."},{"i":8149,"n":"בירנבוים, משה אליהו מפרדס חנה","bt":"תריח","dt":"תרצז - יד סיון","b":"חובב ציון, רב בבילכטוב, עלה לארץ-תרפו, רב בג'דה(=רמת ישי), פרדס חנה. מכתב המלצה עליו מהרב קוק."},{"i":8150,"n":"בירנבוים, שמואל ישעיה מליזנסק","f":"שלמה","bt":"תריד או תרטז","bp":"טשיטש","dt":"תרצח","b":"רב בליזנסק-תרלז - תרצח. חבר אגודת הרבנים לחדוש הסמיכה-תרעד."},{"i":8151,"n":"בירנבוים, שמואל סגל מדובנא","f":"דוד - דודל שרה'ס","k":"בעל מעשה חושב","bt":"תקעא","bp":"פילץ (או פוזנא)","dt":"תרמז - א ניסן","b":"תלמיד וחתן ר עקיבא איגר. רב בדובנא ובזיוו\"ש חתן הגביר ר יצחק מארשלקוביץ מדובנא, חזר לפילץ. גיסו - ר ליב הירשברג מפילץ. בנו - ר צבי, חתניו - ר זלמן ברודסקי מקיוב, אב\"ד בלבוב (לא נודע שמו), בנו גם יו\"ט ליפמן נפטר בילדותו (ע\"ש התוי\"ט שהתיחס אליו). נספד מאת ר אברהם בנימין קלוגר שהיה אז בדובנא, ור משה נתן רובינשטין."},{"i":8152,"n":"בירנשטוק, שמעון זאב","b":"מרבני פולין"},{"i":8153,"n":"בירקן, יצחק חיים רפאל שאול הכה","k":"בעל ריח שדה","bt":"תקמה","bp":"חברון","dt":"תריב","dp":"חברון","b":"מחכמי חברון, תלמיד בעל חקרי לב המזכירו בספרו. חתם-תקפח על כתב שליחות ר יוסף דוד עייאש, שליחות ר יוסף מולכו-תקפב, ר נתן עמרם-תקצד, בשנת תקץ חתם על יסוד ישיבת \"מגן אבות\" בחברון. בשנת תרו התמנה לראש הרבנים אחר פטירת ר יום טוב אליקים. נספד ע\"י ר חיים פאלג'י ב\"ארצות החיים\"."},{"i":8154,"n":"בישיץ, דוד מסעדאוהל","f":"משה מסערדאוהל","bt":"תר","dt":"תרפד - כא חשון","dp":"סערדאוהל","b":"תלמיד הכת\"ס, ור יהודה אסאד ומהרם שיק. מחכמי סערדאוהל."},{"i":8155,"n":"בישיץ, יוסף מסערדאוהל","f":"דוד מסערדאוהל","bt":"תרלז","bp":"סערדאוהל","dt":"תשד - כז סיון","b":"תלמיד השב\"ס, ור נח ברוך פישר מפרעשוב. חתן ר אהרן הלוי טויבר. רב בסערדאוהל. נספה בשואה."},{"i":8156,"n":"בישיץ, משה מסערדאוהל","b":"בנו ר דוד מסערדאוהל וחתנו ר בניין זאב וולף קאהן מבאדען."},{"i":8157,"n":"בישיץ, פאלק יהושע מיארמוט","f":"שלמה","k":"בעל נחלת יהושע","dt":"תרט - א חשון","b":"דיין בראלאש-יארמוט-תקץ וכיהן כממלא מקום מהר\"ם אש שעבר לאונגואר, יחד עם הדיין ר מנשה ליב, עד למינוי ר יעקב יהושע רפפורט."},{"i":8158,"n":"בישיץ, שלמה משארבוגארד","dt":"תקעו - יב אייר","b":"רב בשארבוגארד. בנו - ר פאליק מיארמוט בעל \"נחלת יהושע\"."},{"i":8159,"n":"בישקא מדרוהוביטש","b":"רב בדרוהוביטש-תריג. תשובה אליו ב\"נדרי זריזין\"."},{"i":8160,"n":"בישקא, הלל הכהן מקידאן","f":"אברהם","dt":"תרכח - יו אדר","dp":"קידאן","b":"נכד(-אבי אמו) ר הלל רוצקי בעל \"הילל בן שחר\", מצאצאי ר זלמן מירלס מאה\"ו. תלמיד ר שמעון זרחי מטאוריג בעל \"נחלת שמעון\" המזכירו בספרו. רב בקידאן-לפני תר. חתנו - הגביר אהרן יהושע שפירא מביאליסטוק."},{"i":8161,"n":"בישקוביץ, יהושע הכהן מירושלים","k":"בעל דעת לנכון","b":"מחכמי ירושלים, חיבר פירוש לדרך תבונות בשם \"דעת לנכון\"."},{"i":8162,"n":"בית אהרן - ישיבה בירושלים","b":"ישיבה בירושלים, נוסדה מאת ר אהרן פארדו מלונדון-שנות ה-תק'."},{"i":8163,"n":"בית אל -ישיבת המקובלים ירושלים"},{"i":8164,"n":"בית גדליה - ישיבה בירושלים","b":"ישיבה בירושלים, נוסדה מאת ר יהודה גדליה מלונדון-שנות ה-תק'."},{"i":8165,"n":"בית הלל, יצחק מוילנא","f":"שמואל","k":"הו\"ל בית הלל","dt":"תריח - כא אייר","dp":"וילנא","b":"נכד ר יצחק איזיק מקרוז ווילנא. נינו של ר משה בן ר הלל מאלטונא בעל \"בית הלל\" - ומכאן כינויו. הגיע עם אביו לוילנא ולמד עם ר יצחק ר זלמן ר אורי'ס אצל ר ישעי'לע גראממער. חתן דודו ר ירמיה בן נחום השתדלן מוילנא המכונה שרה זאהן. מעתיק קהילת וילנא על מקום חותנו (ע\"פ חוקי הממשלה) כ-50 שנה, והיה בקי בחוקי רוסיה וליטא ומיעץ לכל שואל, ובנו ר אברהם אריה ליב על מקומו אחריו כמעתיק הקהלה."},{"i":8166,"n":"בית יעקב פירירה-ישיבה בירושלים"},{"i":8167,"n":"ביתאן, אברהם מג'רבה","b":"מחכמי ג'רבה-תקפב."},{"i":8168,"n":"ביתאן, אליהו מאלגיר","k":"בעל עשרת הדברות","b":"רב באלוואד-(מחוז סוף)-אלגיר. הו\"ל הגדה, ו\"עשרת הדברות\" מתורגמים לערבית יהודית."},{"i":8169,"n":"ביתאן, בן ציון מג'רבה וטריפולי","f":"נסים","bt":"תריז-תרך","bp":"ג'רבא","dt":"תשטז - יח חשון","dp":"תונס או [טריפולי]","b":"תלמיד ר יהודה צרמון בעל \"גור אריה\", ור יצחק בעל \"זרע יצחק\". הגיע מג'רבה וכיהן כרב בטריפולי. ראש הישיבה \"דאר סויד\" של הגביר ר רפאל נחום, ור\"מ בישיבת \"יגדיל תורה\", והעמיד מאות תלמידים. חיבר שיטות לתלמוד, דרשה ממנו ב\"מאמר אסתר\" ג'רבה תשו."},{"i":8170,"n":"ביתאן, יצחק מג'רבה","b":"פרסם מאמרים ב\"הירח\" - ג'רבה תשח."},{"i":8171,"n":"ביתאן, משה מג'רבה","f":"אברהם","b":"רב בג'רבא. נזכר ב\"המעלות לדוד\" לר דוד חדאד חזקיה. אביו של ר נסים."},{"i":8172,"n":"ביתאן, נסים מג'רבה","dt":"תרנו - אחרי","b":"רב ראשי בג'רבא ותונס ור רחמים חדאד על מקומו אחריו."},{"i":8173,"n":"ביתאן, פראזי","b":"פרסם מאמרים ב\"אוצר התורה\" - ג'רבה תרץ."},{"i":8174,"n":"ביתאן, רחמים מתונס","bt":"תרלו","dt":"תשל - כג חשון","b":"רב בג'רבא, תונס."},{"i":8175,"n":"ביתן, ישראל מליטא וארה\"ב","bt":"1889","bp":"קובנה","dt":"1957","dp":"סינסינטי","b":"תלמיד ישיבות ליטא, היגר לארה\"ב, למד בהיברו יוניון קולג' והתצרף לתנועה הריפורמית, נשיא הועידה המרכזית של רבני אמריקה-1956, פרסם מונוגרפיות מאמרים ומחקרים ובהם על ר יהודה מוסקטו, ר אפרים לונטשיץ, ר יהונתן איבשיץ, ר יעקב אנטל, ועוד."},{"i":8176,"n":"בכאש, שלום מהודו ואלגיר","f":"יצחק רפאל","bt":"תרח","bp":"בומבי-הודו","dt":"תרפז","b":"נולד בהודו, גדל בצפת, עבר לאלגיר וכיהן כרב בתניית אל חאד (מחוז אלגיר)-תרמ, עבר לאלגיר-תרמד. הו\"ל ספרים רובם בערבית יהודית. פרסם מאמרים ב\"המגיד\", \"הצפירה\", ו\"המליץ\", ופעל למען השכלה צרפתית ליהודי אלגיר ובעל השפעה על הצעירים."},{"i":8177,"n":"בכור - שם פרטי","k":"בעל עין המים","b":"מנהגי יהודי תורכיה היה לכנות את הבן הראשון בשם \"בכור\" והיו מוסיפים אותו לשמו, ולפעמים היה הופך לשמו העיקרי."},{"i":8178,"n":"בכור מיכאל אברהם אליעזר מאזמיר","dt":"תקמה - ו תשרי","dp":"אזמיר","b":"מחכמי אזמיר."},{"i":8179,"n":"בכור שור, יוסף מצרפת","f":"שלמה? יצחק?","k":"בעל פירוש על התורה","b":"מגדולי בעלי התוספות ומפרשי המקרא החשובים,מרביץ תורה באורליינס-ד'תתק\"נ. חיבר פירוש על התורה."},{"i":8180,"n":"בכור, אברהם הכהן","b":"רב בירושלים"},{"i":8181,"n":"בכטינש, יצחק יעקב מקראקא","b":"שו\"ב וסופר דמתא בקראקא-שנת ש'"},{"i":8182,"n":"בכטינש, צבי מקראקא","f":"יצחק יעקב מקראקא","k":"מהר\"ץ - שחיטות ובדיק","dt":"שנג - כח חשון","dp":"קראקא","b":"תלמיד הרמ\"א. שו\"ב מומחה בשחיטה וניקור, חזן ומוהל בקראקא. חיבר הגהות על שחיטות ובדיקות למהר\"י וייל. מתלמידיו - ר יעקב סוריוינה מונציה בעל ספר הניקור."},{"i":8183,"n":"בכייר אל, שמואל מתורכיה","b":"מחכמי תורכיה בזמן מהר\"ם פאדובה."},{"i":8184,"n":"בכמוהר\"ר, יום טוב מאדרינופול","f":"מרדכי שמעון בכמוהר\"ם","k":"בעל תולדות אישים","bt":"תרך","bp":"אדרינופול","b":"מחכמי אדרינופול, פרסם מאמרים ב\"המגיד\", יזרעאל\", ועוד. חובב ציון ועסקן ציוני. דיין בסופיה-תרצב."},{"i":8185,"n":"בכמוהר\"ר, מנחם מאדרינופול","f":"מרדכי או יצחק","bt":"תכו","bp":"טימישואר או אשכנז","dt":"תצד - ד טבת","dp":"אדרינופול","b":"עלה עם משפחתו בילדותו לארץ, בגיל שנתיים עברו באדרינופול ושם נשארו. רב באדרינופול-תפב יחד עם ר אברהם גירון. אבי משפחת בכמוהר\"ר. (לדעת רוזניס - אביו הגיע כדי לחבור לש\"ץ, ורק אחרי המרתו עזב את השבתאות). הניח חבורים בכת\"י - ונשרפו. בנו - ר מרדכי. מתורתו בספר נכדו \"מנחת זכרון\", וב\"מכתב שלמה\"-שלוניקי תרטו, חיבר פזמון שנוהגים לאמרו בברית המילה."},{"i":8186,"n":"בכמוהר\"ר, מנחם מאדרינופול","f":"מרדכי - מאמר מרדכי","k":"בעל דברי מנחם","bt":"תפ","dt":"תקמא - יז שבט","dp":"אדרינופול","b":"מקובל, רב באדרינופול-תקח על מקום אביו, ובנו ר מרדכי על מקומו בחייו-תקל. והיה מחלוקת בעיר בין הקהלות וחלקן היו כפופות לר רפאל יעקב אברהם גירון וצאצאיו, והשאר לר מרדכי ומנחם וצאצאיהם. הניח פסקים בכת\"י. הו\"ל ספר אחיו שנפטר צעיר - ר שלמה - \"חשק שלמה\". (לפי רוזניס תאריך פטריתו יד טבת, ולדבריו גם: נתמנה בשנת תקסא-לאחר תאריך פטירתו לרב האחראי על רוסג'וק ממקומו באדרינופול)."},{"i":8187,"n":"בכמוהר\"ר, מנחם מאדרינופול","f":"מרדכי","dt":"תקע","b":"רב באדרינופול-תקסה על מקום אביו ובחייו, היה גם רב ברוסג'וק והסירוהו-תקסט ומינו את ר יקיר גירון (הקהלה היתה כפופה לאדרינופול - שהיתה מחולקת בין שני הרבנים). בנו - ר יוסף רפאל בכר. (לפי רוזניס נפטר ללא ילדים). נפטר בחיי אביו."},{"i":8188,"n":"בכמוהר\"ר, מנחם מאדרינופול","f":"יצחק","k":"בעל מנחת זכרון","dt":"תרמז - טו שבט","dp":"ירושלים","b":"רב באדריאנופול(=אדרינופול), ובשנת תרלח בקושטא, בשנת תרם עלה לירושלים. חיבוריו בכתב יד נשרפו באדרינופול-תרסה."},{"i":8189,"n":"בכמוהר\"ר, מנחם מאדרינופול","f":"שמעון מרדכי","k":"הו\"ל דברי מנחם","b":"מחכמי אדרינופול. זקנו של ר יום טוב בכמוהר\"ר מסופיה. חיבר גם \"אצבע קטנה\" והוא ליקוטים מ\"מורה באצבע\" לחיד\"א. חתם שמו \"מנחם משי\"ב\". הו\"ל ספר זקנו \"דברי מנחם\"."},{"i":8190,"n":"בכמוהר\"ר, מרדכי מאדריאנופול","f":"מנחם","k":"בעל מאמר מרדכי","dt":"תקח - ג אב","dp":"אדרינופול","b":"רב באדריאנופול-תצד על מקום אביו. רוב חיבוריו אבדו בשריפה. ונינו ר משה בן יוסף רפאל הו\"ל \"מאמר מרדכי\" ממנו. אחיו ר שמואל רב באדריאנופול. בניו ר מנחם על מקומו אחריו ור שלמה נסים בעל \"חשק שלמה\"."},{"i":8191,"n":"בכמוהר\"ר, מרדכי מאדרינופול","f":"מנחם - דברי מנחם","k":"ג'יליבי","dt":"תקפא - ז אד\"א","dp":"אדרינופול","b":"רב באדרינופול-תקל על מקום אביו ובחייו ובנו ר מנחם על מקומו אחריו. היה במחלוקת עם ר שלמה פאלומבו בענין זכיון הלוט(=מסטיקה)."},{"i":8192,"n":"בכמוהר\"ר, משה רחמים מאדרינופול","f":"יוסף רפאל","k":"בעל מאמר מרדכי","dt":"תרלח - ח תמוז","dp":"אדרינופול","b":"רב באדרינופול-תרו על מקום אביו (עוד בחיי אביו). היה מחלוקת בינו לבין ר אברהם ן ארלוייא מפיליפופולי. חיבר \"מאמר מרדכי\" ובו ליקוטים מתורת אבותיו ובסופו שו\"ת ממנו בשם \"נטפל לקדש\" - שלוניקי תרלד. בנו - ר רפאל על מקומו אחריו."},{"i":8193,"n":"בכמוהר\"ר, רפאל יוסף מאדריאנופו","f":"מרדכי (או מנחם)","k":"רפאלאג'י","dt":"תרט","b":"רב באדרינופול-תקע בחיי אביו (לפי רוזניס על מקום אחיו - ר מנחם שנפטר בחיי אביו), בנו ר משה על מקומו אחריו עוד בחייו. נזכר ב\"מאמר מרדכי\" ושם גם נוסח כתב מינויו מטעם קהילת פיליפופולי. רוב כתביו אבדו בשריפה באדריאנופול-תרס. מתשובותיו ב\"חיים ושלום\" לר חיים ן ארלויא, וב\"נטפל לקדש\" בתוך \"מאמר מרדכי\" לבנו ר משה. נספד ע\"י ר חיים פלאג'י."},{"i":8194,"n":"בכמוהר\"ר, רפאל מאדרינופול","f":"משה","dt":"תרנט","b":"רב באדרינופול. הרב האחרון לבית בכמוהר\"ר באדרינופול, ור אברהם צמח נתמנה על מקומו."},{"i":8195,"n":"בכמוהר\"ר, שלמה נסים מאדרינופול","f":"מרדכי - מאמר מרדכי","k":"בעל חשק שלמה","bt":"תצז","dt":"תקלה - בערך","dp":"אדרינופול","b":"דיין באדרינופול. אחיו - ר מנחם-רבה של אדרינופול הו\"ל את ספרו \"חשק שלמה\" על השו\"ע (והוא השלמת הספר כנסת הגדולה - מספרי אחרונים שאחרי זמנו של כנסת הגדולה), ומצאצאיו - ר שמעון - השלים את הספר בשם \"מכתב שלמה\" ונדפס בידי צאצאו ר שמעון מרדכי במאסף \"מאמר מרדכי\" - תרלד."},{"i":8196,"n":"בכמוהר\"ר, שמואל מאדרינופול","f":"מנחם מאדרינופול","b":"דיין באדרינופול. הניח חבור בכת\"י ונשרף בתרסח. אחיו - ר מרדכי בעל \"מאמר מרדכי\"."},{"i":8197,"n":"בכמוהר\"ר, שמעון מאדרינופול","f":"שלמה נסים - חשק שלמה","b":"השלים את ספר אביו - \"חשק שלמה\" בשם \"מכתב שלמה\", ונדפס ע\"י בנו או נכדו ר שמעון מרדכי בתוך המאסף \"מאמר מרדכי\"-תרלד."},{"i":8198,"n":"בכר וילמוש, בנימין זאב מבודפש","k":"בעל אגדות התנאים","bt":"1850","dt":"1913","b":"ראש ביהמ\"ד לרבנים בבודפשט-1907 על מקום משה ברוך. חיבר \"אגדות התנאים\", ו\"אגדות האמוראים\" - תורגמו לעברית. הו\"ל \"שרשים\" לאבן ג'נאח. חיבר ספרים בבלשנות עברית.","bk":[["אגדות התנאים",""],["אגדת אמוראי ארץ ישראל",""],["הרמב\"ם פרשן המקרא",""],["ר’ אברהם אבן עזרא המדקדק",""]]},{"i":8199,"n":"בכר, דניאל מקורפו","b":"מחכמי קורפו(יוון)"},{"i":8200,"n":"בכר, וידאל מלאריסה","b":"מראשי קהלת לאריסה-תפב."},{"i":8201,"n":"בכר, מנחם מאדריאנופול","f":"שמעון מרדכי","k":"בעל מרפא לשון","dt":"תרטז","dp":"ירושלים","b":"רב באדרינופול, עלה לירושלים. חיבר \"מרפא לשון\" שלוניקי תקצא. (ראה גם בכמוהר\"ר מנחם)"},{"i":8202,"n":"בכר, נסים מירושלים","f":"אליהו או אליעזר","bt":"תרח","bp":"ירושלים","dt":"תרצא","b":"נכד(-אבי אמו) ר ידידיה רפאל חי אבולעפיה. מיסד ביה\"ס \"התורה והמלאכה\" לחברת כי\"ח בירושלים."},{"i":8203,"n":"בכ\"ר, רפאל מאדרינופול","f":"משה רחמים בכר","k":"מלאך רפאל","dt":"תרנט","b":"רב באדרינופולי"},{"i":8204,"n":"בכר, שלמה מאזמיר","b":"רב באזמיר-תקפז עם ר דוד אמאדו, ר יצחק נבארו ור שמואל חכים,"},{"i":8205,"n":"בכר, שמואל מירושלים","b":"מחכמי ירושלים, בשנת תרה חתם על כתב שליחות ר מיכאל בדהב עבור \"בית אל\"."},{"i":8206,"n":"בכרך יהושע","bt":"1914","dt":"ה'תשסב 2002","bk":[["מדברי ראשונים",""]]},{"i":8207,"n":"בכרך, אברהם אהרן מפפד\"מ","f":"מנחם","k":"בעל אורים ותומים","b":"מראשי קהילת פפד\"מ - בעל תואר \"מורנו\". אולי אחיו של ר משה מנדלס מפוזנא. לפי גירונדי חיבר \"אורים ותומים\"."},{"i":8208,"n":"בכרך, אברהם שמואל","f":"יצחק","r":"אב\"ד טורבין קעלין פראליץ ואחר כך בורמייזא","bt":"שלה","dt":"שעה - כז אייר","dp":"ורמייזא?","b":"חתן ר יצחק הכהן-חתנו של המהר\"ל. רב בטורבין, קעלין, פארליץ, וורמייזא, עבר לגרנסהים (בגירוש)-שעה. פייטן, חיבר פיוט לחנוכה - \"שדי סלעי ומצודתי\". נכדו - ר יאיר בעל \"חוות יאיר\". אשתו חוה - נכדת המהר\"ל - היתה מלומדת מאוד ובעלה מביא מפירושיה למדרש ובהם חולקת על בעל \"מתנות כהונה\", וכן בפירוש רש\"י, מחזורים וסליחות, ובתרגומים ועוד, נפטרה בדרכה לארץ. נכדה ר יאיר קרא לספרו \"חות יאיר\" על שמה.","bk":[["חוט השני - שו\"ת",""],["שו\"ת חוט השני",""]]},{"i":8209,"n":"בכרך, אלחנן הנדל","f":"משה אהרן","k":"בעל פרחי שושנה","bt":"תצד","dt":"תקעה - כו ניסן","dp":"אלטונא","b":"מצאצאי ר נפתלי הרץ בכרך מפפד\"מ. ש\"ץ באלזס, ברייט, אה\"ו-תקכד, נאמן קהלת אה\"ו - חתם על צוואת ר יחיאל ואליך. סידר מחזור עם \"פרחי שושנה\" עם ר חיים פירשט והמדפיס ר משה באנן."},{"i":8210,"n":"בכרך, אליהו מחסלביץ","k":"בעל בכורי האביב","b":"פרסם מאמרים ב\"כנסת הגדולה\" - וארשא תרן, \"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס, \"שמעתתי דרבנן\" - אודסה תרמז."},{"i":8211,"n":"בכרך, אליעזר חנוך מסובלק","f":"יהודה-נמוקי הגרי\"ב","dt":"תרכד - ה ניסן","dp":"הורדנא","b":"רב בהורדנא, סובאלק. בנו - ר יצחק איזיק."},{"i":8212,"n":"בכרך, אפרים גומפרט","b":"מגדולי חכמי דורו,רב במגנצא-ר\"ו,פפד\"מ-רי\"ז"},{"i":8213,"n":"בכרך, אריה ליב מגרייוא","b":"רב בגרייווא-תרכ\"ד"},{"i":8214,"n":"בכרך, אריה ליב מליסא","f":"יעקב","b":"רב בליסא-תמג על מקום ר יעקב יצחק הלוי. חתם על בקשת עזרה עבור קהלת שטרים-ליטא (שבה כיהן ר יעקב יצחק מליסא לפני שעבר לליסא)."},{"i":8215,"n":"בכרך, אשר אנשיל","b":"מגדולי חכמי וורמס-ר\"פ"},{"i":8216,"n":"בכרך, דוד מפפד\"מ","b":"מגדולי חכמי אשכנז,רב בפפד\"מ-ק\"צ-ר\"כ"},{"i":8217,"n":"בכרך, חיים דוד מארה\"ב","f":"זאב אליהו","k":"בעל דברי דוד","bt":"תרכה","dt":"תרצט","b":"מצאצאי בעל \"נמוקי הגרי\"ב\". תלמיד אחיו ר יהודה מטשכנוביץ, ר יהושע מקוטנא, ר אברהם מסוכטשוב, ר יצחק אלחנן מקובנא. היגר לארה\"ב וכיהן כרב ברב בטרנטון-תרמט, פרובידנס-רוד אילנד. חיבר \"דברי דוד\", \"הגיון לדוד\" - בכת\"י."},{"i":8218,"n":"בכרך, חיים יאיר (שמעון)","f":"משה שמשון","k":"בעל חוות יאיר","bt":"שפח","bp":"מזריטש-ברודי","dt":"תסב - א טבת","dp":"ורמייזא","b":"אב\"ד בקובלנץ-תטו, רב במגנצא, עבר לוורמייזא-תל מקום רבנות אביו - אך לא נבחר על מקומו אחריו (אלא ר אהרן תאומים), לאחר חורבן העיר-תן יצא לפפד\"מ, רב בוורמייזא על מקום ר אהרן ועל מקום אביו. קרא לספרו \"חוות יאיר\" על שם זקנתו - חוה אשת ר אברהם שמואל - שהיתה מלומדת והביא מתורתה בספרו. אחיו החורג - ר טוביה הרופא בעל \"מעשה טוביה\".","bk":[["חוט השני","שו\"ת - אחרונים"],["חוות יאיר","שו\"ת - אחרונים"],["חוות יאיר - שו\"ת , מקור חיים , מר קשישא - כללים,",""],["חוות יאיר - שו\"ת",""],["מקור חיים",""],["מר קשישא - כללים",""],["מקור חיים [על או\"ח]",""]]},{"i":8219,"n":"בכרך, חיים מסבדקי","f":"מיכאל בכרך","b":"רב בסבדקי-תק\"ע"},{"i":8220,"n":"בכרך, חנוך הניך","f":"יהושע השל","b":"מו\"צ בברסטוביץ"},{"i":8221,"n":"בכרך, טוביה","dt":"תכ","dp":"רוזינאי","b":"עק\"ה,על ידי עלילה"},{"i":8222,"n":"בכרך, טוביה חסיד מטיקטין","dt":"תצא - ב שבט","b":"גדול בנגלה ונסתר,מרביץ תורה בטיקטין"},{"i":8223,"n":"בכרך, יהודה","b":"רב בטשרנאווצע-תר\"מ"},{"i":8224,"n":"בכרך, יהודה ליב","dt":"תצט","b":"אחיינו של ר מיכאל בעל \"ערוגת הבושם\"."},{"i":8225,"n":"בכרך, יהודה מסייני","f":"יהושע השל יחזקאל","k":"בעל נמוקי הגרי\"ב","bt":"תקלה","dt":"תרו - כט ניסן","b":"ממשפחת ר טוביה בכרך מקדושי רוזנוי שנהרג עק\"ה בעלילת דם יחד עם ישראל בן שלום. נכד ר חנוך הניך מקלוואריה וזבלודובה - מצאצאי היסו\"ד בוילנא. חתן הגביר ר ישראל בורליונר מסערהייא (שהגר\"א התארח בביתו וברכו שיזכה לחתן מפורסם בתורה, ושתאריך ימים - וברכתו התקיימה). עשיר ובעל חסד, ידע בע\"פ ש\"ס רמב\"ם ושו\"ע, רב בסייני. חיבר \"נימוקי הגרי\"ב\" על המשנה, ש\"ס, עין יעקב, מהרש\"א, ועוד. בנו - ר משה, ר אליעזר חנוך."},{"i":8226,"n":"בכרך, יהושע השל מגלינדיץ","f":"אייזיק בכרך","b":"חתן ר חנוך הניך מקאלווריה וזבלדובה בעל \"משפחת החנוכי\". רב בגלינדיץ-פלך אמדור-תקן."},{"i":8227,"n":"בכרך, יוסף","f":"יעקב בן יצחק מחסלביץ","k":"בעל תולדות יעקב יוסף"},{"i":8228,"n":"בכרך, יעקב","f":"יצחק איזיק מחסבליץ","b":"בנו - ר יוסף בעל \"תולדות יעקב יוסף\" (אולי הוא שנרשם - ר יעקב מחסלביץ וצפת)."},{"i":8229,"n":"בכרך, יעקב מביאליסטוק","f":"משה","k":"בעל המסע לארץ הקדושה","bt":"תקפד","bp":"סייני","dt":"תרנו","dp":"ביאליסטוק","b":"תלמיד זקנו ר יהודה בכרך בעל נמוקי הגרי\"ב, רב בביאליסטוק, בעל דפוס בקניגסברג והדפיס ספר יוחסין לר אברהם זכות עם הערות ממנו. עבר לסבסטופול-קרים והכיר שם את הקראים וספרותם והתווכח עם חכמיהם. ביקר בארץ-1882 בעניני התישבות וכתב על כך \"המסע לארץ הקדושה\", חיבר גם \"היחש לכתב אשורי\", ועוד. הגיה את הטור - קניגסברג, התווכח עם שד\"ל בענין קדמות הניקוד והטעמים."},{"i":8230,"n":"בכרך, יצחק איזיק מאמדור","f":"אליעזר חנוך מסובלק","b":"רב באמדור-תרמ"},{"i":8231,"n":"בכרך, יצחק איזיק מחסלביץ","b":"רב בחסלביץ. בנו - ר יעקב, ונכדו - ר יוסף בעל \"תולדות יעקב יוסף\". (אולי הוא שנרשם - ר יצחק איזיק הלוי מחסלביץ וצפת)."},{"i":8232,"n":"בכרך, יצחק איזיק מספאטקין","f":"יהושע העשל בכרך","b":"רב בסאפאטקין-תק\"פ"},{"i":8233,"n":"בכרך, יצחק מוורמייזא","b":"מגדולי חכמי וורמייזא-ש\"מ"},{"i":8234,"n":"בכרך, ישכר בער מניקלשבורג","f":"מיכאל בכרך","dt":"תקסז","b":"בקי,רב בניקלסבורג"},{"i":8235,"n":"בכרך, מאיר מפשרבורג","f":"שמואל זנויל","dt":"תפא - ד שבט","b":"נכד ר יאיר בעל \"חוות יאיר\". רב בפרשבורג."},{"i":8236,"n":"בכרך, מיכאל מפרג","f":"שמואל זנוול","k":"בעל ערוגת הבשם-כת\"י","bt":"תץ","bp":"פרג","b":"דיין בפרג-תקם אצל הנודע ביהודה, ראש ישיבה וראב\"ד-תקסא על מקום ר שלמה זלמן עמריך, ור אלעזר פלקלש בעל \"תשובה מאהבה\" על מקומו אחריו. חיבר חדושים על שו\"ע בשם \"ערוגת הבושם\" - בכת\"י."},{"i":8237,"n":"בכרך, מנדל מפפד\"מ","dt":"שנט - כ אלול","b":"מגדולי חכמי פרנקפורט"},{"i":8238,"n":"בכרך, מנחם מהנאו ופולדא","f":"חנן או יעקב אלחנן","dt":"שצו - ב שבט","dp":"הנאו","b":"רב בפולדא, הנאו-שעז, ואז פנו אליו בשאלה מקהילת פפד\"מ - שבאותו הזמן החלה להשתקם אחרי גירוש-שעד ולא היה להם רב."},{"i":8239,"n":"בכרך, מנחם מורמיזא","k":"רבי מן","b":"מגדולי חכמי אשכנז,רב בוורמס(=וורמייזא)-רסו-רצ."},{"i":8240,"n":"בכרך, מנחם מפפד\"מ","b":"פרנס בפפד\"מ-שלד, חתם על החלטות הקהל-שלב-שלד. בנו - ר משה מינדלס מפפד\"מ."},{"i":8241,"n":"בכרך, משה","f":"יהודה - הגרי\"ב","dt":"תרך","b":"מגדולי התורה - לא כיהן ברבנות. בנו - ר יעקב."},{"i":8242,"n":"בכרך, משה מוורמייזא","b":"דיין בוורמס-ר\"צ"},{"i":8243,"n":"בכרך, משה מנדלס מפוזנא ופפד\"מ","f":"מנחם מנדל מפפד\"מ","dt":"שפ - יא אלול","b":"רב בזידלוב, קראקא, פוזנא-שצט, פפד\"מ. הסכים על \"גנת אגוז\" יחד עם ר ישעיה הורביץ בעל השל\"ה. נזכר ב\"יוסף אומץ\". בתו - אדל מנדלס חיברה \"יוסיפון\" בלשון אשכנז. אולי אחיו של ר אברהם מפפד\"מ."},{"i":8244,"n":"בכרך, משה שמשון מרמייזא","f":"שמואל בכרך","k":"בעל חוט השני","bt":"שסז","dt":"תל - כט ניסן","b":"פוסק, פייטן, מגדולי חכמי דורו, רב בגיידינג-שפז, לייפניק-שצ, דרשן בפרג-תד, רב בוורמייזא-תי. בנו - ר חיים יאיר בעל \"חוות יאיר\". בזיוו\"ש נשא את אלמנת ר משה נראל הכהן-אמו של ר טוביה הרופא בעל \"מעשה טוביה\".","bk":[["שמן המאור - על התורה",""]]},{"i":8245,"n":"בכרך, נפתלי הרץ מפרנקפורט","f":"יעקב אלחנן","k":"בעל עמק המלך","bp":"פולין או פפד\"מ","b":"מחכמי פרנקפורט, עלה לצפת, חזר לפרנקפורט והביא עמו את קבלת האר\"י לאשכנז. חיבר \"עמק המלך\" אמשטרדם תח. היה מחלוקת כנגדו מר חיים הכהן-תלמיד ר חיים ויטאל - בעל \"מקור חיים\", וגם החיד\"א כותב כי הצנועים מושכים ידיהם מלקרוא בו. היה במחלוקת עם יש\"ר מקנדיא בענין שיטתו בקבלה ואמר עליו \"האלקים עשה את האדם יש\"ר והוא ביקש חשבונות רבים...\"."},{"i":8246,"n":"בכרך, נפתלי מפולדא","f":"דוד","b":"מחכמי פולדא. חתם על תקנות אסיפת הרבנים בפפד\"מ-שסג מטעם פולדא ומדינת מינדן."},{"i":8247,"n":"בכרך, שלמה מטיקטין","f":"טוביה הי\"ד","b":"ראב\"ד בגליל טיקטין-תכ\"ט"},{"i":8248,"n":"בכרך, שמואל","b":"מגדולי הראשונים,מבעלי התוספות,מרביץ תורה בטיירי-ד'תתק\"נ"},{"i":8249,"n":"בכרך, שמואל זנוול","f":"יאיר - חוות יאיר","b":"מגדולי נכבדי ווינה-ת\"צ. בנו - ר מאיר מפרשבורג."},{"i":8250,"n":"בכרך, שמואל מטיקטין","f":"שלמה בכרך","dt":"תקיח - ב תמוז","b":"דיין בטיקטין"},{"i":8251,"n":"בכרך-גנז, ישכר בר","f":"משה בכרך","dt":"תלח - ו אלול","b":"רב בפפד\"מ"},{"i":8252,"n":"בל-חזן, דוד ממוגאדור-מרוקו","dp":"מראקש","b":"גביר ומו\"ץ במוגאדור-מרוקו, חתם על פס\"ד-תקפז עם ר' חיים פינטו ונזכר ב\"שופריה דיעקב\"."},{"i":8253,"n":"בלאהשטיין","k":"ראה: בלושטיין","b":"אב\"ד נאדי-קאוועשעד. בנו ר קלונימוס שלום מטענקע - ניו גרסי."},{"i":8254,"n":"בלאיש, אברהם מירושלים ואנגליה","f":"שלום","k":"בעל באר לחי רואי","bp":"[תונס]","b":"עלה לירושלים-תקע, בשנת תקעז שליח באירופה ורב בניצה. חיבר \"באר לחי רואי\" לונדון תקץ, \"עפרות תבל\" עם תרגום לאנגלית, \"אחרית לאיש שלום\" ליוורנו תקץ. חרות על הלוחות לונדון תרח. ועוד הרבה בדפוס ובכת\"י."},{"i":8255,"n":"בלאך שלמה בן אפרים הלוי","bt":"1780","dt":"ה'תריח 1858","bk":[["סדר ההגדה של פסח",""],["סדר ההגדה של פסח עם תרגום גרמני",""]]},{"i":8256,"n":"בלאניש, יהודה ממרוקו","b":"מחכמי מרוקו. שאלה ממנו למוהריב\"ע."},{"i":8257,"n":"בלאנסי, אברהם ממרוקו","f":"משה?","b":"מגולי ספרד, הגיע למרוקו וכיהן כסופר ביה\"ד. נזכר ב\"זכות אבות\" אודות תקנה שתקן-שה. הניח חדושים בכת\"י."},{"i":8258,"n":"בלאנסי, משה מספרד ופאס","f":"שמואל?","b":"תלמיד ר יצחק קנפנטון, ממגורשי ספרד, עבר לפורטוגל ונאסר ועונה ע\"י האינקביזיציה שם, הגיע לפאס-רנז וכיהן כסופר בי\"ד. חתם-רנז על תקנה בספר התקנות עם ר יעקב פריינטי. תלמידו - ר משה חלאווה."},{"i":8259,"n":"בלאנסי, שמואל מספרד","f":"אברהם","b":"רב בספרד בזמן ר יצחק אבוהב. נזכר ב\"בית יוסף\", בספר \"מהררי נמרים\" - כללי הק\"ו שלו."},{"i":8260,"n":"בלאס, זאב מדברצין","b":"חתן ר משה נתן יונגרייז בעל תורת משה נתן. רב בדברצין. לאחר פטירתו נישאה אלמנתו לר יונתן בנימין הורביץ מביסטריץ וירושלים."},{"i":8261,"n":"בלאס, שמחה בונם הכהן מרדומסק","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":8262,"n":"בלאשקע, ליב","b":"רב בקאשמין-ת\"ר"},{"i":8263,"n":"בל\"ב, בנימין","b":"מגדולי חכמי רומי-שנת ס'. חיבר פירוש לתנך"},{"i":8264,"n":"בלבול, ראובן מבגדד","dt":"תרסז","b":"תלמיד ר אלישע דנגור. מחכמי בגדד ומלמד לתלמידים. חיבר פירוש לתורה ותלמידו ר יהודה פתייה העתיק את חיבורו על התורה. חיבר גם דרוש על אבות."},{"i":8265,"n":"בלבן, דב בריש מלמברג","b":"מחכמי למברג. תשובה אליו \"קנאת סופרים\""},{"i":8266,"n":"בלבן, יעקב מיברוב","b":"מחכמי יברוב. תשובה אליו בטוט\"ד."},{"i":8267,"n":"בלבן, מאיר","k":"בעל יידן אין פוילן","b":"פרסם מאמרים ב\"בית הכנסת\" - תל אביב תשו."},{"i":8268,"n":"בלג, זליג מפירניץ","bp":"לייפניק","dt":"תקפט","b":"תלמיד החת\"ס. רב בפירניץ (ברטניץ). נספד ע\"י החת\"ס"},{"i":8269,"n":"בלגרדי, שמואל יצחק מאיטליה","b":"רב באיטליה, תלמיד ר נתנאל טרבוט ממודנא, ורשם את דברי רבו בזמן פטירתו."},{"i":8270,"n":"בלה, טנן מליפובה","b":"רבה האחרון של הקהילה הניאולוגית בליפובה."},{"i":8271,"n":"בלוזנשטין, אורי מיבלונוב","b":"רב ביבלונוב-תרנט, על מקומו אחריו ר קלמן צוקרמן."},{"i":8272,"n":"בלוזנשטין, יצחק מניו יורק","k":"בעל אמרי יצחק","b":"מחמכי ניו יורק. חיבר \"אמרי יצחק\" מתורתו של האדמור יצחק מסטמר. נ\"י תשמח."},{"i":8273,"n":"בלוזנשטין, ישראל מזמיגרוד","b":"רב בזמיגרוד, בובוב. ממשפחת ר שמואל זנויל מצאנז."},{"i":8274,"n":"בלוט, שמואל מרופשיץ","b":"רב ברופשיץ. תשובה אליו במהר\"י הכהן."},{"i":8275,"n":"בלוי לאיוש, יהודה אריה מבודפשט","bt":"1861","dt":"1936","b":"מלמד בביהמ\"ד לרבנים בבודפשט. חוקר המשפט התלמודי והספר העברי. עורך הרבעון המדעי \"ביטאון יהודי הונגריה\"-1891 כ-40 שנה. יסד את כתב העת \"הצפה מארץ הגר\"."},{"i":8276,"n":"בלוי משה יהודה","bt":"1912","dt":"ה'תשסג 2003","bk":[["דקדוקי סופרים לפרש\"י",""],["מפתח",""],["סיפורי גלגולים ורוחות",""],["שיטת הקדמונים",""],["ספר הפרדס ותרומות הפרדס",""]]},{"i":8277,"n":"בלוי עמרם בן משה","bt":"1904","dt":"ה'תשלח 1978","bk":[["שומר החומות",""]]},{"i":8278,"n":"בלוי, אברהם מאיר מבודפשט","f":"יעקב מסאנטוב","bt":"תרכד","bp":"סאנטוב","dt":"תרסג - טו כסלו","dp":"בודפשט","b":"תלמיד השב\"ס. חתן ר משה פריידיגר מבודפשט בעל משה ידבר. מחכמי בודפשסט, פיאומע."},{"i":8279,"n":"בלוי, בנימין זאב מסנטוב","f":"יעקב מסנטוב","b":"חתן ר ירמיה לעוו באויהל."},{"i":8280,"n":"בלוי, ברוך יודא","b":"פרסם מאמרים ב\"אור תורה\" - ירושלים תרנז."},{"i":8281,"n":"בלוי, ברוך מפאקש","b":"חתן ר עקיבא קליין מנייטרא, ובזיוו\"ש חתן ר יעקב יהודה ליב הכהן שטרסר מטאב - חתנו של הכת\"ס. בנו ר עקיבא מקראסנא."},{"i":8282,"n":"בלוי, יהודה מפרשבורג","f":"מיכאל","bp":"סערדאוהל","dt":"תרכח - בערך","dp":"סערדאוהל","b":"תלמיד החת\"ס. מחכמי פרשבורג."},{"i":8283,"n":"בלוי, יהושע מירושלים","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":8284,"n":"בלוי, יהושע ממאקווא","b":"מחכמי מאקווא. חתנו - ר ישראל הלוי פולק ממאקווא."},{"i":8285,"n":"בלוי, יו\"ט ליפמן מגיסינג","b":"תלמיד השב\"ס. חתן ר קלונימוס קלמן וייס באויהל. אב\"ד גיסינג."},{"i":8286,"n":"בלוי, יעקב קופל מוערבוי","f":"יוחנן הכהן מוערבא","bt":"תריב","bp":"וערבא(=וערבוי)","dt":"תרעח - כח תשרי","dp":"וויצען","b":"לאחר שנתייתם גדל אצל הכת\"ס, תלמיד ר חיים צבי מנהיימר מאונגוואר. חתן ר אפרים לעווי מאונגריש-בראד. רב בוערבוי(=וורבוי)-תרלז, וויצען. מחותן עם ר שלום שורץ בעל \"קול אריה\"."},{"i":8287,"n":"בלוי, יצחק יהודה ליב מבני ברק","b":"חתן הדעת סופר. רב בבני ברק."},{"i":8288,"n":"בלוי, יצחק ישראל מיארמוט","b":"שו\"ב ומו\"צ ביארמוט. פעל להפרדות הקהלה ביארמוט מקהלת טשאנגר יחד עם הגביר ר אליהו גרינשטין, וכנראה כיהן כרבה הראשון של הקהלה."},{"i":8289,"n":"בלוי, יצחק שלמה","k":"בעל מלוא העומר","bt":"תריז","dt":"תשג","b":"תלמיד מהרי\"ל דיסקין בירושלים, ושליחו בעניני ציבור. ממיסדי בית היתומים דיסקין, וישיבת \"אהל משה\". פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה. בניו: ר משה - ממנהיגי אגודת ישראל, ור עמרם - מנהיג \"נטורי קרתא\"."},{"i":8290,"n":"בלוי, מרדכי יהודה","b":"ניצל מהשואה והגיע לשנחאי-סין. פרסם מאמרים ב\"מאור תורה\" - שנחאי-סין תשד - קובץ תלמידי ישיבת מיר בשנחאי."},{"i":8291,"n":"בלוי, מרדכי יהודה ליב מטשענגר","b":"תלמיד השב\"ס, ור שמואל דוד יונגרייז מפעהר-ירמוט. רב בטשענגער-תרמד. תשובה אליו ב\"שבט סופר\"."},{"i":8292,"n":"בלוי, משה הלוי","b":"תלמיד הכת\"ס. תשובה אליו ב\"כתב סופר\"."},{"i":8293,"n":"בלוי, משה יהודה מארה\"ב","b":"פרסם מאמרים ב\"התבונה\" - נ\"י תשז - קובץ תלמידי ישיבת מיר."},{"i":8294,"n":"בלוי, משה מאלסק","b":"רב באלסק"},{"i":8295,"n":"בלוי, משה מבודפשט","b":"חתן ר שלמה ברוך שמאלהוזן. רב בבודפשט, עלה לארץ וכיהן כרב שכונת פרדס כץ בבני ברק."},{"i":8296,"n":"בלוי, משה מדוקלא","k":"בעל תפארת משה","b":"מחכמי דוקלא. חיבר \"תפארת משה\" פיעטרקוב תרצח. מתורתו ב\"אהל תורה\" - קראקא תרפט."},{"i":8297,"n":"בלוי, משה מירושלים","b":"רב בירושלים-תרפז."},{"i":8298,"n":"בלוי, עמרם מירושלים","bt":"תרנג","dt":"תשלד - טו תמוז","b":"לוחם וקנאי,מגדולי חכמי ירושלים"},{"i":8299,"n":"בלוי, עמרם מירושלים הסבא","f":"יהודה מפרשבורג","bt":"תקץ","dt":"תרס - ח אד\"א","dp":"ירושלים","b":"תלמיד הכת\"ס. חתן ר בירך. רב בסלובקיה, קאסטאלן, טירנא. עלה לירושלים-תרכט. בנו ר יצחק שלמה בעל \"מלא העומר\", וזקנם של ר עמרם ור משה בלוי מירושלים."},{"i":8300,"n":"בלוי, עקיבא מקראסנא","f":"ברוך מפאקש","bt":"תרמג","bp":"פאקש","dt":"תשד - סיון","b":"נכד ר עקיבא קליין מנייטרא. תלמיד השב\"ס, ור אליעזר זוסמן סופר מפאקש, ור יצחק קרפל מפאקש ועוד. חתן ר אהרן צבי פריד מוואלקא ועבר לשם. מחכמי קראסנא-תרסט ועמד בקשרי מכתבי תורה עם רבים מגדולי הדור. מאמר ממנו ב\"המעין\" - בודפשט תשז (לאחר השואה!)."},{"i":8301,"n":"בלוי, פרץ מבודפשט","b":"מחכמי בודפשט. חתניו - ר אברהם שטינר מגרוסורדין, ור יעקב יחיאל גאבעל מגרוסורדין."},{"i":8302,"n":"בלויגרונד, אפרים מבובוב","f":"יעקב דוד","b":"מחכמי בובוב-תרנג. חתן הגביר ר זישא מלימנוב."},{"i":8303,"n":"בלויגרונד, ברוך אברהם מקלווריה","f":"ישכר","bt":"תרן","dt":"תשג","b":"רב בקאלווריה-גליצה על מקום אביו. נספה בשואה."},{"i":8304,"n":"בלויגרונד, זישא מלימנוב","f":"מנשה יחזקאל","b":"מחכמי לימנוב. גיסו של ר צבי הירש רינמן מלימנוב."},{"i":8305,"n":"בלויגרונד, יוסף מרדומישל","b":"רב ברדומישל-תרצא."},{"i":8306,"n":"בלויגרונד, ישכר מקאלווריה","f":"זישא מלימנוב","bt":"תרל","bp":"לימנוב","dt":"תש","b":"חתן ר אלעזר בינדיגר. היה סופרו של האדמור משיניבה. אב\"ד קלווריה-גליציה-תרנז. בניו: ר ברוך. חתנו - בנו של ר אשר מאיר הלברשטם."},{"i":8307,"n":"בלוישטין, אהרן נח כהן מגריבוב","b":"מחכמי גריבוב-תרפב. תשובה אליו ב\"דובב מישרים\"."},{"i":8308,"n":"בלוישטינר, משה יהודה ליב","k":"בעל אהל משה","b":"מחכמי נאדי-וואשאן(=ואז'וני)."},{"i":8309,"n":"בלוך, אברהם אבא מדלטין","f":"גדליה","bt":"תרך","bp":"דלטין","dt":"תרף","dp":"וינה","b":"תלמיד ר מנחם מנדל מקוסוב. מחכמי דלטין."},{"i":8310,"n":"בלוך, אברהם יצחק מטלז","f":"יוסף יהודה ליב מטלז","k":"בעל שעורי הגרא\"י מטל","bt":"תרן","bp":"טלז-ליטא","dt":"תשא - כ תמוז","b":"נכד ר אליעזר גורדון מטלז, ראש ישיבת טלז-תרפא בחיי אביו, ועל מקומו אחריו-תרץ גם כרב העיר. בשליחות באמריקה-תרפח. חבר מועצת גדולי התורה של אגו\"י. מתורתו בספר אביו \"שעורי דעת\". רבה האחרון של טלז, נספה בשואה עם כל בני עדתו. אחיו ר אליהו מאיר, וגיסו ר חיים מרדכי קאטץ, הצליחו להמלט והגיעו לאמריקה, והקימו בקליבלנד את ישיבת טלז."},{"i":8311,"n":"בלוך, אברהם מבריסל","b":"רב ראשי בבריסל-תרע."},{"i":8312,"n":"בלוך, אברהם מדלטין","f":"צבי","bt":"תקן","dt":"תר","b":"חתן הגביר ר גדליה אבוש מדלטין. רב בדלטין-תקצג. מחסיד רמ\"מ מקוסוב."},{"i":8313,"n":"בלוך, אברהם מזולקווא","f":"יעקב","b":"חתם-תסד על תקנות קהלת זולקווא."},{"i":8314,"n":"בלוך, אברהם מליאון","b":"רב הכולל בליאון-צרפת-תרע."},{"i":8315,"n":"בלוך, אברהם מצרפת ואלגיר","f":"משה","bt":"תריט","dt":"תרעד","b":"רב בווהראן מטעם הקונסיסטואר, אלגיר-תרנז. ביהכ\"נ הגדולה באלגיר נקרא על שמו. נהרג במלחה\"ע ה-I."},{"i":8316,"n":"בלוך, אהרן יוסף מבאפלו","k":"בעל לב אדם","b":"רב בבאפלו-ארה\"ב-תשכה, נסמך מאת ר יצחק אלחנן בקובנה."},{"i":8317,"n":"בלוך, אליהו חיים","b":"פרסם מאמרים ב\"הדנו\" - נ\"י תרפה."},{"i":8318,"n":"בלוך, אליהו מאיר מטלז וקליבלנד","f":"יוסף יהודה ליב מטלז","k":"בעל שיעורי דעת","r":"ראש ישיבת טלז","bt":"תרנד-ה","bp":"טלז","dt":"תשטו - כט שבט","dp":"קליבלנד","b":"ר\"מ בטלז בישיבת אביו, בשנת תש הצליח לצאת מליטא והגיע לארה\"ב, והתישב בקליבלנד-תשב והקים את ישיבת טלז בקליבלנד-ארה\"ב עם גיסו ר חיים מרדכי קאטץ, ור מרדכי גיפטר מטלז, ור ברוך סורוצקין, ור חיים שטיין. חבר מועצת גדולי התורה באמריקה. פרסם מאמרים ב\"מרכז התורה\" - מונטריאול תשב, \"שעורי דעת\" - שנחאי תשו.","bk":[["שיעורי ופניני דעת",""],["זכרון אליהו",""],["זכרון אליהו - אוסף מאמרים, הלכה, שיחות, נאומים",""],["שעורי רבי אליהו מאיר - יבמות",""]]},{"i":8319,"n":"בלוך, אליקים","f":"חיים צבי","k":"בעל דרכי ישרים","b":"חיבר \"דרכי ישרים\" למברג תרכח."},{"i":8320,"n":"בלוך, אריה ליב מוילנא","f":"יוסף","dt":"תקטז - כד חשון","dp":"וילנא","b":"גביר מגדולי חכמי וילנא, נשלח ע\"י ראשי הקהלה לתהות על הגר\"א שהגיע לוילנא. חתם על כתב רבנות ר שמואל בוילנא. חתנו ר דב בר בן ר אליהו פעסעלעס מוילנא."},{"i":8321,"n":"בלוך, אריה ליב מלאבובה","dt":"תרמד","dp":"קראקא","b":"רב בלאבובה-תרל."},{"i":8322,"n":"בלוך, בנימין מריגא","dt":"תרצח - לפני","b":"מו\"צ בריגא. חתנו - ר גרשון הכהן קפלן מריגא."},{"i":8323,"n":"בלוך, זלמן מטלז","f":"יוסף יהודה ליב מטלז","bt":"תרמו","bp":"טלז","dt":"תשא","b":"תלמיד ישיבות טלז, וורנה, שאדובה, סלובודקה. חתן הגביר ר בנימין דיניס מחרקוב. בזמן מלחה\"ע ה-I ישב ביקטרינוסלב, חזר לטלז וכיהן כר\"מ בישיבת אביו-תרפד. נספה בשואה. פרסם מאמרים ב\"פרי עץ חיים\" - טלז תרצט - קובץ תלמידי ישיבת טלז."},{"i":8324,"n":"בלוך, זלמן משה מקאפאלטש","b":"רב בקאפאלטש-תר\"כ"},{"i":8325,"n":"בלוך, חיים גבריאל מאלסק","f":"יוסף","k":"בעל יפה נוף","bt":"תקיד","dt":"תקפד","b":"ראב\"ד קוניב-תקף. חיבר \"יפה נוף\" למברג תקנה."},{"i":8326,"n":"בלוך, חיים יצחק הכהן מפולנגיאן","f":"חנוך זונדל","k":"בעל דברי חיב\"ה","bt":"תרכה-ו","bp":"פלונגיאן","dt":"תשח - ז אד\"ב","dp":"ניו ג'רסי","b":"תלמיד ישיבות גרובין, וולוזין, נסמך מאת: ר חיים סולוביציק, ר אליעזר מטלז. חתן ר אברהם שמיד מטלז. רב בפלונגיאן-תרנו וראש ישיבה שם, בויסק-תרסב-ז על מקום הראי\"ה קוק, היגר לארה\"ב-תרפב וכיהן כרב בג'ורג'י סיטי-ניו ג'רסי. נשיא כבוד של אגודת הרבנים בארה\"ב. פרסם מאמרים ב\"הצפירה\", ו\"הפרדס\", \"היכל התורה\" - נ\"י תרצג, יגדיל תורה\" - נ\"י תרעו, \"מגדל תורה\" - נ\"י תרפה. חיבר גם \"ודע מה שתשיב\" נ\"י תשג, \"תלפיות\" - נ\"י תשד."},{"i":8327,"n":"בלוך, חיים ישראל מסקאלא","b":"רב בסקאלא-תרנו. תשובה אליו ב\"הרי בשמים\"-תרמב."},{"i":8328,"n":"בלוך, חנוך זונדל הכהן"},{"i":8329,"n":"בלוך, יהודה מציריך","b":"מחכמי ציריך. חתנו - ר צבי קורנפיין רב בציריך."},{"i":8330,"n":"בלוך, יהושע מליטא וארה\"ב","bt":"1890","bp":"דארביאן","dt":"1957","b":"היגר לארה\"ב, ולמד ב\"היברו יוניון קולג'\", ועוד. ספרן וביבליוגרף, מנהל המחלקה היהודית של הספריה הציבורית בניו יורק, ומזכיר החברה ההיסטורית היהודית בארה\"ב. חיבר ספרים בנושאי יהדות באנגלית."},{"i":8331,"n":"בלוך, יונה (יהונתן אליעזר)","f":"אברהם דוד בן נח","k":"בעל אוצר נחמד -כת\"י","bt":"תקעט","dt":"תרמג - ט חשון","dp":"וילנא","b":"גביר מחכמי וילנא. חיבר גם \"קורץ פרייטאג\" בכת\"י. נדב סכום גדול לצדקה בצוואתו."},{"i":8332,"n":"בלוך, יוסף חיים","f":"שאול מקובליץ","b":"חתן ר צבי הירש שיינעש."},{"i":8333,"n":"בלוך, יוסף יהודה ליב מטלז","f":"מרדכי מראסיין","k":"בעל שיעורי דעת","r":"ראש ישיבת טלז","bt":"תריט-כ","bp":"ראסיין","dt":"תרצ - ז חשון","dp":"טלז","b":"תלמיד דודו-אחי אמו ר משה זאב ברוידא(המכונה ר משה חריף) מואקשנא, ישיבת קעלם, וולוזין. חתן ר אליעזר גורדון מטלז. ר\"מ בטלז-תרמד, רב בוורנה(=וארנא)-תרסב, שאדובה(=שאדעווא)-תרסד, רב בטלז וראש ישיבת טלז-תרעא על מקום חותנו, ולידו ר שמעון שקופ ור יהודה ליב חסמן. נשאר בטלז גם במלחה\"ע ה-I וניהל את הישיבה עם ר חיים רבינוביץ. בניו הו\"ל את ספרו \"שעורי דעת\". הספד עליו ב\"קול תורה\" - ירושלים תרץ, \"תבונה\" - ירושלים תשא-תשח.","bk":[["משעורי רבנו",""],["שעורי דעת",""],["שעורי הלכה",""],["שעורי רבותינו",""],["שיעורי דעת",""],["שיעורי הלכה (מהרי\"ל בלוך)",""]]},{"i":8334,"n":"בלוך, יוסף מהולשיץ-סטנוב","f":"אברהם","k":"בעל גנזי יוסף","bt":"תפד","dt":"תקן - כב אדר","b":"תלמיד המגיד ממזריטש. רב באלעסק, סטאנוב. ראב\"ד באלסק, סטנוב ואולי גם בהולשיץ. חיבר \"גנזי יוסף\" למברג תקנב. בנו ר חיים גבריאל-בעל \"יפה נוף\"."},{"i":8335,"n":"בלוך, יוסף מוילנא","f":"צבי הירש מוילנא","dt":"ג שבט - תצד","dp":"וילנא","b":"גביר בוילנא כאביו לפניו."},{"i":8336,"n":"בלוך, יוסף שמואל מדוקלא","k":"בעל לקוטים מתלמוד","bt":"תריא","bp":"דוקלא","dt":"תרפד","dp":"וינה","b":"מצאצאי ר יוסף שמואל אב\"ד קראקא. תלמיד ר יצחק שמלקיס בברזן. בעל תואר ד\"ר ונבחר לפרלמנט האוסטרי. ניצח בויכוח את האנטישמי רוהלינג. (היתה מחלוקת בקשר אליו - ספר \"מלחמות בלוך\" לר יהודה הלוי לייזנר מבוצץ לטובתו - כנגדו ספר \"ברקאי\" למיכאל רודקינזון ועוד). חיבר \"לקוטים מתלמוד בבלי\" - וינה תרמז (לצורך המשפט נגד רוהלינג)."},{"i":8337,"n":"בלוך, יצחק מצרפת","f":"נפתלי","k":"בעל גירוש היהודים מא","bt":"תרט","b":"תלמיד ר שלמה הלוי מרימאטה, ר יצחק בער מבישהיים, ביהמ\"ד לרבנים בפאריס. רב ברמירמנט(=רעמירמאנט)-צרפת, אורן(=ווהראן)-אלגיר-תרלח, אלגיר-תרמג מטעם הקונסיסטואר, נאנסי-צרפת. חיבר קונטרס בצרפתית על יהודי ווהראן, וספר על ציוני קברים באלגיר,\"מצבות עתיקות באלגיר\", ועוד. הסכים על \"זה השלחן\" לר א' ח' גיג'."},{"i":8338,"n":"בלוך, ישכר בער מגוטיין","f":"שמשון חסיד מהמבורג","k":"בעל בינת יששכר","bt":"תץ","dt":"תקנח","b":"תלמיד ר יונתן איבשיץ. רב באייבנשיץ, גויטיין(=גוטיין)-תקכח ור אלעזר פלקלש על מקומו אחריו, סמניץ-תקם, בסקוביץ-תקנו, מטרסדורף-תקנז והחת\"ס על מקומו אחריו."},{"i":8339,"n":"בלוך, מרדכי מברלין","k":"בעל טבע הדגים","bp":"אנשפך","b":"רב ורופא שעבר מאנשפך לברלין. חיבר ספר על טבע הדגים ונדפס."},{"i":8340,"n":"בלוך, מרדכי מראסיין","dt":"תרנז","b":"מצאצאי ר טודרוס לוריא מראסיין. מחכמי ראסיין. בנו - ר יוסף יהודה ליב מטלז."},{"i":8341,"n":"בלוך, משה אריה מלייפניק","k":"בעל שערי המעלות","bt":"תקעה","bp":"רנשבורג-בוהמיה","dt":"תרסט - כג אב","b":"נכד ר אלעזר לעוו בעל \"שמן רוקח\", תלמיד דודו ר בנימין לעוו בעל \"שערי תורה.רב בלייפניק-תרטז-תרלז, מלמד בסמינר וראש המרצים. מכתביו נדפס - \"שערי המעלות\" - \"שערי תורה\". לכבודו נדפס (בגיל 90) ספר יובל - בודפשט תרסו."},{"i":8342,"n":"בלוך, משה זאב מצפת","f":"אהרן","b":"נמנה בין העולים לצפת עם ר מנחם מנדל משקלוב, וחתם-תקעג בענין ר יוסף יעקבקא פרנקל מברסלוי."},{"i":8343,"n":"בלוך, משה חיים אפרים מדלטין","f":"אברהם אבא","k":"בעל זעקת שבר","bt":"תרמא","bp":"דלטין","dt":"תשל","b":"חתן ר משולם פיבוש הלוי לנדמן-הלר. תלמיד ר משה גרינולד בעל ערוגות הבשם בחוסט, והמהרש\"ם. עבר לוינה ועסק בהוראה וכתיבת ספרים, התפרסם כחוקר וכמייצג עם ישראל בויכוחים עם הנוצרים. ברח לניו יורק-תרצט. חיבר \"זעקת שבר\" קאלאמעא תרסט, \"ודע מה שתשיב\" נ\"י תשג, ועוד. התפרסם בתשובתו לספרו האנטישמי של ה\"מלומד\" הגרמני אריך בישוף \"הדם\" - ובישוף התאבד-1936 על רקע זה, ובעתון הנאצים איימו על ר חיים בלוך שיבוא היום והוא יעמוד לדין על חוצפתו. הו\"ל \"דובב שפתי ישנים\" - מכתבי רבנים נגד הציונות - נחשד כזיוף."},{"i":8344,"n":"בלוך, משה מארה\"ב","f":"אהרן","bt":"תרנט","bp":"בוצאץ","b":"מצאצאי ר מאיר מפרימישלן. נכד ר שמואל ישכר שטרק, התבואות שור. תלמיד ר מנחם שטינברג מברודי, ר מאיר אריק מטרנוב, ר\"ח הלר. נסמך מאת: ר מאיר אריק, ר חיים גלרנטר, ר משה מרדכי אפשטין, ר ישעיהו פירשט מוינה. רב ביהכ\"נ \"בני ברית\" בוינה-תרפד, ביהכ\"נ \"אהל אברהם\" ו\"מקדש מעט\"-תרץ, היגר לארה\"ב וכיהן כרב בקהלת \"חתם סופר\" בניו יורק, רב בקוני איילנד-תשז. חיבר \"תולדות המהרי\"ט ומשפחת הטראנים\" - בכת\"י. חבר אגודת הרבנים באמריקה, ופעיל בתנועת ה\"מזרחי\"."},{"i":8345,"n":"בלוך, משה מזולצבך","b":"מדפיס בזולצבך-תמד."},{"i":8346,"n":"בלוך, משה ממזריטש","f":"שמשון חסיד מהמבורג","b":"דיין במזריטש-תקכ\"ד"},{"i":8347,"n":"בלוך, משה משטרסבורג","b":"רב בשטרסבורג-תרי\"ג"},{"i":8348,"n":"בלוך, מתתיהו מירושלים","b":"מחכמי ירושלים, שליחו של ש\"ץ לבשר על התגלותו."},{"i":8349,"n":"בלוך, נח מוילנא - הזקן","f":"שרגא פיבש","dt":"תקסט - ב ניסן","dp":"וילנא","b":"חתן ר אריה ליב הכהן. מחכמי וילנא. קרובו של הגביר ר נח פעטליצעס (לפי ברוורמן-אנשי שם - הוא עצמו מכונה נח פעטליצעס). בנה את עזרת הנשים בביה\"כ הגדול בוילנא ותרם לחברות שונות בוילנא. בניו: ר שרגא פיבש, ר ליב, ר יקותיאל, ר אברהם דוד. חתנו: ר חיים קמינקר מהורדנא. מחותניו: ר אלכסנדר מרגליות מסנוב בעל \"תשובת הרא\"ם\", ר אברהם בן ר יחזקאל מלאזדיי-מחותנו של הגר\"א."},{"i":8350,"n":"בלוך, נח מוילנא - הנכד","f":"אברהם דוד בן נח","dt":"תרו - טו אב","b":"ממשכילי וילנא. הסכים על מסכת ברכות בתרגום אשכנזי לפיננער. היה מחלוקת כנגדו מצד היראים - וגם בזמן קבורתו - ועל כך חיבר אד\"ם הכהן מליצה על מצבתו. בנו ר מאיר מוארשא חיבר מאמר \"זכרון לחכם\" ב\"המליץ\" אודות אביו ובה מספר כי אביו חתם על אגרת המשכילים לממשלה לצוות לבני ישראל לשנות בגדיהם וכו'."},{"i":8351,"n":"בלוך, פיבל מפוזן","k":"בעל האמונה והדעת","bt":"תרא","b":"תלמיד ביהמ\"ד לרבנים בברסלוי, בעל תואר ד\"ר. רב קהלת \"עדת אחים\" בפוזנן(=פוזען)-תרכז. חיבר גם \"חרות הדעת\", \"תולדות הקבלה והחקירה\"."},{"i":8352,"n":"בלוך, צבי הירש","f":"שמעון","k":"בעל תאומי צביה"},{"i":8353,"n":"בלוך, צבי הירש מוילנא","f":"אליה יהודה ליב","b":"גביר בוילנא, נדב-תעב ספר תורה. בנו - ר יוסף מוילנא."},{"i":8354,"n":"בלוך, צבי מחרסון","b":"רב בחרסון-תר\"ע"},{"i":8355,"n":"בלוך, צבי מסקאלא","f":"יוסף","bt":"תקכ","dt":"תקס","b":"חתן אחותו אשת ר יצחק מאניפולי. רב בסקאלא. בנו ר אברהם אב\"ד דלטין."},{"i":8356,"n":"בלוך, שאול הכהן מקובליץ","f":"זלמן","bt":"תר","b":"רב באביניץ-תרכב, קובליץ-פלך ויטבסק-תרל. נסמך מאת: ר זלמן פרודקין מפאלצק ולובלין. בנו - ר יוסף חיים, חתנו - ר יוסף חיים יעקובסון מלוקאמליע."},{"i":8357,"n":"בלוך, שלמה זלמן","f":"יוסף בלוך","bt":"תרמה","dt":"תשא - כ תמוז","b":"מרביץ תורה בטלז"},{"i":8358,"n":"בלוך, שמריה יצחק מאנגליה","f":"שבתי משה","bt":"תרכג","bp":"קרטינגא-פלך קובנא","b":"תלמיד ישיבת סלובודקא. רב בדרוסקניק-פלך גרודנא-תרמח, סנדרלנד-אנגליה-תרנד, בירמינגהם-תרסב, לונדון. נסמך מאת: ר יצחק אלחנן מקובנא, ר שלמה הכהן מוילנא, ר יעקב חריף מוילנא וניו יורק, ר ירחם יהודה \"הגדול ממינסק\". חיבר שו\"ת, חדושים לש\"ס, הלכות ריבית - בכת\"י."},{"i":8359,"n":"בלוך, שמשון הלוי מלבוב","k":"בעל שבילי עולם","bt":"1784","dt":"1845","b":"תלמיד חבר לרנ\"ק (נחמן קרוכמל), חברו של יוסף פרל. משכיל מלבוב. כנראה הוא המחבר של \"זמיר עריצים\" שנכתב בעילום שם כנגד החסידים (אולי בעזרתו של ידידו יוסף פרל), חיבר גם \"שבחי אלכסיי\" - כנגד החסידות."},{"i":8360,"n":"בלוך, שמשון חסיד מאה\"ו","f":"משה","k":"בעל נזירות שמשון","r":"דיין בהמבורג","dt":"תצח - י כסלו","dp":"אלטונא","b":"גדול בנגלה ונסתר, דיין וראש חכמי ביהמ\"ד של ר ישכר בער הכהן בהמבורג. נזכר אצל ר יעקב עמדן בענין מחלוקת הלכתית וב\"אגרת בקורת\" יצא כנגד פסקו. מתורתו ב\"תוספות חדשים\" על המשנה, ובספר בנו \"בינת ישכר\", עוד מבניו ר משה ממזריטש, חתנו - ר מרדכי הענא.","bk":[["נזירות שמשון - הגהות על שלחן ערוך אורח חיים",""],["תוספות חדשים - משניות",""]]},{"i":8361,"n":"בלוך, שמשון מלמברג","b":"מחכמי למברג. תשובה אליו בשו\"ת המצרף."},{"i":8362,"n":"בלוך, שרגא פיבל מוילנא - הנכד","f":"נח מוילנא","dt":"תקפט - ט סיון","dp":"וילנא","b":"מחכמי וילנא."},{"i":8363,"n":"בלולו, אברהם מדמנאת-מרוקו","b":"מקובל מחכמי דמנאת-מרוקו."},{"i":8364,"n":"בלולו, יוסף מדמנאת-מרוקו","b":"רב בדמנאת-מרוקו."},{"i":8365,"n":"בלולו, משה מטריפולי","f":"חי","bt":"תרס","bp":"אל זאוויא אל גרבייא-לוב","dt":"תשכה","dp":"ישראל","b":"רב, פייטן ודרשן במצראתה-לוב-תקץ, סרת-לוב-תקצב, נאסר ע\"י האיטלקים בזמן השואה-תש, שוחרר וחזר לכהן כרב במצראתה-תשג, עלה לארץ-תשי וכיהן כרב בנתניה."},{"i":8366,"n":"בלולו, עטייה מטריפולי","bt":"תס","dt":"תקל - בערך","dp":"טריפולי","b":"רב וסופר בטריפולי. חתם בפנקס בי\"ד טריפולי."},{"i":8367,"n":"בלולו, ראובן מדמנאת-מרוקו","b":"מחכמי דמנאת-מרוקו."},{"i":8368,"n":"בלולו, שלם מדמנאת-מרוקו","f":"שלמה","b":"מחכמי דמנאת-מרוקו."},{"i":8369,"n":"בלולו, שלמה מדמנאת-מרוקו","b":"רב בדמנאת-מרוקו."},{"i":8370,"n":"בלום, אברהם יצחק","dt":"תקפז - יח אייר","b":"רב בפריישטטל-תקס\"ד"},{"i":8371,"n":"בלום, אברהם מאלמאש","b":"רב באלמאש-תר\"כ"},{"i":8372,"n":"בלום, אברהם מארה\"ב","b":"מטיף בגלבסטון-טקסס-תרלא עד תרמה."},{"i":8373,"n":"בלום, אליהו חיים מנ\"י","b":"עורך \"הדנו\" - נ\"י תרפה - בטאון ישיבת ר יצחק אלחנן בנ\"י."},{"i":8374,"n":"בלום, אליעזר מסיקסא","f":"משה יעקב מבעזעד","dt":"תרעד - בערך","b":"תלמיד הכת\"ס, ור מנחם אש מאונגוואר, ור אברהם יצחק ויינברגר מקלינורדין. חתן ר צבי יעקב רייכמן מסיקסא. רב בסיקסא אצל האב\"ד ר שמואל עהרנפלד. בנו ר שמואל מקאשוי. פרסם מאמרים ב\"הכוכב\" - מונקטש-נ\"י תרצה."},{"i":8375,"n":"בלום, אריה ליב","bt":"תרלב","dt":"תשיז - טו כסלו","b":"דיין בווינה תר\"פ"},{"i":8376,"n":"בלום, אריה מבוצאץ","b":"מחכמי בוצאץ. מתורתו ב\"ועד חכמים\"."},{"i":8377,"n":"בלום, בנציון מבערעטי","f":"עמרם מהעדילא-מאדע","bt":"תרם או תרמה","bp":"העדילא-מאדע","dt":"תשה - כ טבת","dp":"בודפשט","b":"תלמיד השב\"ס, והדעת סופר. חתן ר ישראל זאב פנט מטעגלאש, ועבר לשם-תרסא. רב בסארוואש-תרסח, בערעטי-אויפאלו-תרפט. נספה בשואה."},{"i":8378,"n":"בלום, חיים משה","dt":"תשג","b":"רב בזאמוטשט"},{"i":8379,"n":"בלום, יהודה צבי מהאנשוביץ","f":"עמרם מבערטי-אויפלו","k":"בעל שארית יהודה-תשלג","dt":"תרעז - ה סיון","b":"רב בהנשוויץ(האנשוביץ)-תרנז וראש ישיבה. חתן ר ישעיה ארנפלד משוראן."},{"i":8380,"n":"בלום, יוסף מרדכי מגוליגור","f":"משה מצאנז","bt":"תרסג","bp":"עיר ישן","dt":"תשג","b":"מחכמי צאנז, תלמיד ר מאיר ארק. חתן ר נפתלי הירץ בומבך מסמבור בעל \"גבעת הלבונה\". אב\"ד גליגור-תרצג. נספה בשואה."},{"i":8381,"n":"בלום, יצחק יהודה מקליבלנד","f":"עמרם מקליבלנד","b":"רב בקליבלנד-תשל על מקום אביו."},{"i":8382,"n":"בלום, יצחק יעקב מברט-אויפלו","f":"עמרם - בית שערים","bt":"תריח","dt":"תרצח - כא אד\"א","b":"נכד ר משה ליב פישר מבאגמעיר. תלמיד השב\"ס. חתן ר אליעזר זוסמן סופר מפאקש. רב בנאדי-סנט מיקלוש-תרמ. בזיוו\"ש חתן ר אלעזר שמחה בונם גינז-שלזינגר מאבראהאם ועבר לשם-תרנד. דיין בבערטי-אויפלו-תרנט אצל אביו. אחיו - ר משה נחום שחיבר הקדמה לספר אביהם."},{"i":8383,"n":"בלום, יצחק יעקב מקרולה","k":"בעל בית יעקב","dt":"תריא - יא אייר","b":"תלמיד ר קאפיל חריף, חתן ר עמרם חסידא רוזנבוים ממאד. רב בשאמשון על מקום ר יעקב אופנהיים ור אלכסנדר זלנפרינד על מקומו אחריו, קרולה אצל ר מאיר פרלס. בנו ר עמרם בעל \"בית שערים\". חיבר \"בית יעקב\" ונדפס בספר בנו ר עמרם בעל \"בית שערים\"."},{"i":8384,"n":"בלום, ישראל משה מבובוב","b":"מחכמי בובוב. תשובה אליו \"שדה יצחק\"."},{"i":8385,"n":"בלום, כתריאל מקראלי","f":"עמרם מבערעטי-אויפלו","b":"חתן ר מנחם גרינולד משופרון. בנו ר עמרם - רב בארגנטינה וקליבלנד."},{"i":8386,"n":"בלום, משה יהודה ליב מקראקא","dt":"תש..","b":"תלמיד האדמור מרדומסק. ראש חבורת רדומסק בשטיבל קראקא. נספה בשואה."},{"i":8387,"n":"בלום, משה יעקב מבעזדעד","dt":"תרמח - יט סיון","b":"תלמיד ר מאיר א\"ש מאונגוואר. מחכמי בעזדעד."},{"i":8388,"n":"בלום, משה מצאנז","bt":"תרמג","bp":"מעליץ","dt":"תשג","b":"תלמיד בעל \"הרי בשמים\". חתן ר שאול ראטה. רב בצשינוב-תרסז, דיין בצאנז(=סאנדז)-תרמו - תרפז, תשובות אליו בשו\"ת מהר\"ש."},{"i":8389,"n":"בלום, משה מקראקא","b":"סופר בקראקא-תרצא. תשובה אליו \"מנחת אברהם\"."},{"i":8390,"n":"בלום, משה נחום-נתן מגרוסורדין","f":"עמרם-בית שערים","k":"הו\"ל בית שערים","dt":"תשד","b":"חתן ר מוזס חיים ליטש רוזנבוים מקלינורדין. דיין במישקולץ על מקום ר יחיאל פירט ור שמעון נייפלד על מקומו אחריו, דומ\"צ בקלינורדין, דיין בגרוסורדין-תרפו. נספה בשואה. הו\"ל ספר אביו \"בית שערים\", עם הקדמה ותוספות ממנו."},{"i":8391,"n":"בלום, עמרם מבערטי-אייפאלו","f":"יצחק יעקב משאמשון","k":"בעל בית שערים","r":"האדמו\"ר הראשון מבעלזא","bt":"תקצד","bp":"שאמאן","dt":"תרסז - כו אלול","dp":"בערטי-אויפלו","b":"נכד ר עמרם חסידא-רוזנבוים. תלמיד הכת\"ס, ור מאיר פרלס מקאלי, הדברי חיים מצאנז. חתן ר משה ליב פישר מבאגאמעיר ועבר לשם, בזיוו\"ש חתן ר חיים יוסף דב כהנא-הלר מקראסנא. רב בשאמשון, אלמאשד-תריח, העדילא-מאדע-תרכד, חוסט-תרמא - ועזב בגלל מחלוקת, בערטי-אויפלו-תרמג וראש ישיבה שם, בנו ר בנציון על מקומו אחריו. מחותמי האיסור על הקמת הסמינר לרבנים. חיבר גם פירוש על הגדה של פסח - וי\"ל ע\"י בנו.","bk":[["בית שערים","שו\"ת - אחרונים"],["ערבי פסחים – הגדה של פסח",""],["ערבי פסחים – הגדה של פסח , בית שערים",""]]},{"i":8392,"n":"בלום, עמרם מקליולנד - הנכד","f":"כתריאל מקראלי","bt":"תרעג","bp":"קראלי","dt":"תשל - י אב","dp":"ירושלים","b":"נכד ר עמרם בלום מבערטי-אויפלו. גדל אצל זקנו - ר מנחם גרינולד משופרון. תלמיד הדעת סופר, ור אברהם אינהורן משטינמאנגר ועוד. חתן ר יצחק יהודה שטיינר מאראניאש-מארוטה. עלה לירושלים-תש, רב בבואנוס-אירס-תשח והרב הראשי לארגנטינה, רב בניו יורק-תשטו, לוס אנגלס-תשיח, קליבלנד-תשכב, ובנו ר יצחק יהודה על מקומו אחריו. הו\"ל ספר דודו זקינו \"הלכה למשה\"."},{"i":8393,"n":"בלום, קופל","b":"פרסם מאמרים ב\"בית הכנסת\" - תל אביב תשו."},{"i":8394,"n":"בלום, רפאל מקאשוי וארה\"ב","f":"שמואל מקאשוי","k":"בעל ברכות שמים","b":"תלמיד ר שאול בראך מקאשוי. רב במיהאלביץ, היגר לארה\"ב וכיהן כרב בקרית קאשוי בבדפורד הילס. ר\"מ בישיבת \"אהל שמואל\" קאשוי באיוינגטאון-ארה\"ב. חיבר גם \"שלל רב\" נ\"י תשיח, \"פתח האהל\", \"טל השמים\"."},{"i":8395,"n":"בלום, שמואל חיים מעמדין","dt":"תשיב - כז חשון","b":"רב בפלישין-תרע\"ד, חמניץ-תר\"פ, עמדין-תרפב. עלה לא\"י-תרצ\"ט."},{"i":8396,"n":"בלום, שמואל מבריסק ונ\"י","k":"בעל אמר ודברים","bp":"בריסק","b":"רב ודרשן בארה\"ב. חיבר \"אמר ודברים\" נ\"י תרפג."},{"i":8397,"n":"בלום, שמואל מקאשוי","f":"אליעזר מסיקסא","bt":"תרלה","bp":"סיקסא","dt":"תשד - ד סיון","dp":"אושוויץ","b":"תלמיד השב\"ס, ור נתנאל פריש מאויווארוש ועוד. חתן ר רפאל קליין מקאשוי. מחכמי טרנאליא, רב בקאשוי-תרס. מתורתו ב\"תל תלפיות\" ו\"וילקט יוסף\". בנו ר רפאל רב בקאשוי, וניו יורק."},{"i":8398,"n":"בלומברג, ב' צ' מדרזשין","b":"פרסם מאמרים ב\"ירושלים\" - וארשא תרצו."},{"i":8399,"n":"בלומברג, בנימין בינם","b":"תשובה אליו ב\"תפארת יוסף\"."},{"i":8400,"n":"בלומברג, משה יחזקאל מסמארא","f":"דובער","k":"בעל מי הים","bt":"תריח","bp":"בויסק-קורלנד","b":"תלמיד קבוץ תורה באיישישוק. חתן הגביר ר צמח הכהן רידזינסקי מאסמינא-פלך וילנא. ממלא מקומו של ר דב ליפשיץ בסרדניק-תרמד, רב בסמארא-תרמט. נסמך מאת: ר יצחק אלחנן מקובנא, ר דובער ליפשיץ מסרדניק. חיבר \"מי הים\" - בכת\"י."},{"i":8401,"n":"בלומברג-הררי יונה דב בן יהודה","bt":"1850","dt":"ה'תרצא 1931","bk":[["מאמר הדבור העברי",""],["מצות ישיבת ארץ ישראל",""]]},{"i":8402,"n":"בלומברג-הררי, יונה דב מדוינסק","f":"יהודה","k":"בעל מצות ישיבת א\"י","bt":"תרי-ב","bp":"סרדניק-ליטא","dt":"תרצא","dp":"תל אביב","b":"סוחר יערות ותלמיד חכם מחכמי דוינסק, חבר \"בני משה\" וראש הלשכה בדוינסק. מראשי המזרחי, ציר בקונגרס השישי. חיבר קונטרס \"מצות ישיבת ארץ ישראל\" - וילנא תרנח - בהוצאת קלונימוס ויסוצקי. עלה לארץ."},{"i":8403,"n":"בלומגרד, יהודה מוירבאלן-ליטא","b":"רב בוירבאלן, ור דוד טבלי קצנלנבוגן על מקומו אחריו."},{"i":8404,"n":"בלומגרונד, נפתלי מאבאני","f":"נתן צבי בבאלעשף","k":"בעל תולדות","bt":"תרלג","b":"תלמיד ר כלב שלזינגר מטופאלשן, ר אברהם גרינבורג מקעזמרק, ר ליפמן אדלר מבאיא, ביהמ\"ד לרבנים בברלין, ביהמ\"ד לרבנים בוינה אצל ר אברהם שוורץ. נכד-אבי אמו ר יחזקאל לעווי מאונסדורף בעל \"תורת יחזקאל\". רב בנאדי-אבאני. נסמך מאת ר משה בלוך-ראש ביהמ\"ד לרבנים בבודפשט.. הו\"ל ספרים בהונגרית ובהם: ספרי ר סעדיה גאון, תולדות? חיי?."},{"i":8405,"n":"בלומגרונד, נתן צבי מבאלעשף","f":"דב בר ווישניץ","bt":"תקפו","bp":"טרנטשין","dt":"תרמט - טו אב","dp":"אלעשאף","b":"נכד ר מרדכי ליב לאשברין-בריל מזשמבקרעט. תלמיד החת\"ס, ור יצחק משה פרלס מבאניהאד. חתן ר מרדכי הלוי שפיץ מאונסדורף, ובזיוו\"ש חתן ר יחזקאל הלוי מטרנטשין ועבר לשם. רב באלעשאף-תריט."},{"i":8406,"n":"בלומלן, אהרן (פלומיל)","k":"בעל פסקי הלכות","dt":"קפ - ט ניסן","b":"תלמיד ר שלום \"השר מנורשטט\", יחד עם חברו מהר\"י וייל, דודו ורבו של ר ישראל איסרלן בעל \"תרומת הדשן\" ונזכר בספרי חכמי דורו. רב בניישטט. נהרג עק\"ה."},{"i":8407,"n":"בלומנברג, יוסף אפרים","bt":"תרפב","bp":"לאשיע (גורליץ)","dt":"תש..","b":"תלמיד ישיבת בובוב בפודגורזע ובבובוב. נספה בשואה."},{"i":8408,"n":"בלומנברג, מרדכי אברהם מהוסקוב","b":"מחכמי הוסקוב. פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח, \"אסיפת חכמים\" - אטוניא-בויאן תרע-תרעד."},{"i":8409,"n":"בלומנטל אהרן שמחה בן יעקב","bt":"1870","dt":"ה'תשכג 1963","bk":[["שיחת חכמים",""]]},{"i":8410,"n":"בלומנטל, אברהם יוחנן מירושלים","f":"יעקב","k":"בעל מזכה הרבים","bt":"תרלח","bp":"ירושלים","b":"מיסד בית היתומים \"ציון\" בירושלים. עורך כתב העת \"אור תורה\" - ירושלים תרנז."},{"i":8411,"n":"בלומנטל, אהרן שמחה מירושלים","f":"יעקב","bp":"ירושלים","b":"תלמיד ישיבות ירושלים. חתן ר טוביה גולדנברג. הו\"ל \"חדושי החת\"ס\" עם הערות ממנו. פרסם מאמרים ב\"תורה מציון\", \"המאסף\", \"אהל מועד\" - פודגורזע תרנח, \"המאסף\" - ירושלים-אלכסנדריה תרנו-תרעג, \"תורה מציון\" - ירושלים תרנה-תרסה. חיבר \"שיחת חכמים\" בכת\"י."},{"i":8412,"n":"בלומנטל, יהושע הכהן מקמניץ","f":"ראובן","bt":"תקעה","bp":"אוגוסטוב","dt":"תרם - יא שבט","dp":"בריסק","b":"תלמיד החת\"ס, ור אריה ליב צונץ מפלאצק, ור יהודה בכרך מסייני. חתן ר גבריאל פרידקעס מסוחוואליע. רב בלאזדיי (ליטא), מארימפאלי (ליטא), ביאליסטוק ושם הקים ישיבה, יאניווע, קמניץ (ליטא)-תרכז, ובנו ר ראובן על מקומו אחריו. עוד מבניו - ר אברהם אהרן בורשטין על מקומו בטאווריג, ירושלים. מתלמידיו - ר ישראל דוד מילר."},{"i":8413,"n":"בלומנטל, יעקב מירושלים","b":"מחכמי ירושלים. חתם על קבלה של \"ועד משמרת הקדש\"-תרסא."},{"i":8414,"n":"בלומנפלד מאיר בן שלמה","bt":"1905","dt":"ה'תשמ 1980","bk":[["אור חדש",""],["אור עולם",""],["אור תורה",""],["מנחת מאיר",""],["נתיבות נביאים",""],["פרח שושנה",""],["פרי שלמה",""],["שמחת עולם",""],["שער המלך",""],["תורת חיים",""]]},{"i":8415,"n":"בלומנפלד, אליהו מאפטא","b":"פרסם מאמרים ב\"שערי חכמה\" - אוזרוב תרפד."},{"i":8416,"n":"בלומנפלד, בנימין זאב וולף מלבו","f":"דוד שמואל","k":"בעל גליון מוצל מאש","bt":"תקנד","dt":"תרלה - ח כסלו","b":"רב בלבוב-תרם, חיבר \"גליון מוצל מאש\" בסוף לקוטי בתר לקוטי על חמש מגילות."},{"i":8417,"n":"בלומנפלד, בעריש מברודי","b":"מחכמי ברודי, משורר. תרגם ספר איוב ללשון אשכנז. שירים ממנו ב\"בכורי העתים\" - תקפד."},{"i":8418,"n":"בלומנפלד, דוד שמואל מלבוב","dt":"תריא - כז שבט","b":"רב בלבוב"},{"i":8419,"n":"בלומנפלד, זאב וולף מלבוב - א","b":"מגיד ומו\"צ בלבוב, נזכר ב\"יד אליעזר\", \"מאמר מרדכי\", \"שואל ומשיב\"."},{"i":8420,"n":"בלומנפלד, יהודה מירושלים","k":"יודל לאמזער","b":"תלמיד ר משה יהודה ליב זילברברג מקוטנא. מלמד תורה בחורבה בירושלים-תרך. אבי משפחת בלומנפלד בירושלים. נזכר ב\"בני אשר\" לר\"י גולדמן."},{"i":8421,"n":"בלומנפלד, יהושע השל","f":"נפתלי הרץ","b":"רב בזמיגראד-תק\"ל"},{"i":8422,"n":"בלומנפלד, יוסף ברוך מקניגסהוטא","f":"שמואל יעקב","k":"בעל גן יוסף","bt":"תרן","bp":"קיצלה-פולין","dt":"תשכ","dp":"תל אביב","b":"מצאצאי ר איצלה מאופושטנה, מהר\"ם פאדובה. תלמיד ר\"י אנגל. נסמך מאת: הרי\"נ קורניצר מקראקא, ר שמעון שקופ, ובעל \"משמרת שלום\". רב בקארולבסקה-הוטא(=רב בקניגסהוטא), ניו יורק, ראב\"ד בתל אביב. פרסם מאמרים ב\"סיני\" - ירושלים תרצז."},{"i":8423,"n":"בלומנפלד, יחזקאל צבי מרישא","f":"יצחק חיים","bt":"תקם","dt":"תרטז","b":"חתן ר מרדכי בן זאב וולף מברודי. רב בשנדישוב, אב\"ד רישא-תקע על מקום אביו. חתנו ר אריה יהודה ולרשטין, ונכדו ר יצחק חיים ולרשטין - רב בריישא."},{"i":8424,"n":"בלומנפלד, יחיאל מאיר","f":"שמואל יעקב בלומנפלד","k":"בעל כל המצוה","bt":"תרנג","dt":"תשג - י תשרי","b":"רב ברציצה-תרעד, ר\"מ בוארשא. עורך כתב העת \"ירושלים\" - וארשא תרצו."},{"i":8425,"n":"בלומנפלד, יצחק חיים מרישא","f":"יהושע השל מזמיגרוד","bt":"תק","dt":"תקעא","b":"חתן ר שלמה זלמן סגל מברישא. אב\"ד רישא-תקמב. התנגד לחסידות. ר יחזקאל צבי ישב על כסאו."},{"i":8426,"n":"בלומנפלד, ישראל נחמן מירושלים","b":"גבאי ישיבת \"תורת חיים\" בירושלים בעיר בריסק-תרע בערך. פרסם מאמרים ב\"אור תורה\" - ירושלים תרנז, \"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":8427,"n":"בלומנפלד, מאיר מאמריקה","f":"שלמה","k":"בעל אור תורה - תשכב","bt":"תרסה","bp":"קיעלץ-פולין","b":"תלמיד האדמור מסוקולוב, וכונה \"העילוי מקיעלץ\". נסמך מאת: ר מנחם זעמבא, ר צבי יחזקאל מיכלזון, האדמור מראדזין, הרי\"מ קאנאל, ר מאיר הכהן וארשוויאק, ר יעקב זילברשטין מפראגא, ר אברהם אבלי רפפורט מקיעלץ. רב בקיעלץ, ניו יורק וכמה קהלות באמריקה, תל אביב-תשה. חיבר \"אור תורה\" ניו יורק תשכב, \"גן מאיר\". פרסם מאמרים ב\"בית ועד לחכמים\" - סטמר תרפב, פרסם מאמרים ב\"בית שמואל\" - וארשא תרצו, \"חדרי תורה\" - קראקא תרפו."},{"i":8428,"n":"בלומנפלד, מנחם מנדל ממיטאוי","f":"מרדכי","b":"גביר במיטאוי."},{"i":8429,"n":"בלומנפלד, משה צבי מסנוק","f":"[יואל]","b":"עלה מסנוק לירושלים. תשובה אליו ב\"בית יצחק\"-תרלו. השיב לרצ\"פ פרנק-תרעד."},{"i":8430,"n":"בלומנפלד, צבי הירש מצאנז","bp":"גורליץ","b":"חסיד בובוב. תלמיד קרובו ר\"ש פירר במילובקה - ורשם את תורת רבו. מוכר ספרים בצאנז."},{"i":8431,"n":"בלומנפלד, שלמה זלמן מקוזובה","f":"נחום","bt":"תקע","bp":"למברג","dt":"תרם","b":"נכד \"משאת בנימין\". חסיד קומורנא. מחכמי קוזובה והיה מקובל."},{"i":8432,"n":"בלומנפלד, שמואל יעקב","b":"רב בשידלוב-תר\"ס"},{"i":8433,"n":"בלומנפלד, שמעון ממיטאוי","k":"בעל פני משה","bt":"תקל","bp":"מיטאוי","dt":"תקפו","dp":"מיטאוי","b":"מחכמי מיטאוי, סופר, צייר, ואומן, ישב במקומות שונים וחזר למיטאוי. כתב חומש מיניאטורי שנכנס בתוך טבעת, יצר עבודות אומנות גם עבור הקיסר ומלכי אירופה. חיבר \"פני משה\" על התורה - בכת\"י. בנו - יוסף."},{"i":8434,"n":"בלומנפרוכט, יחזקאל מטורנא","f":"משה","bt":"תרעב","bp":"טורנא","dt":"תשנה","b":"עבר מטורנא לקראקא. תלמיד ר ישעיה מנדל בידרמן. ניצל מהשואה, (סייע בהצלת האדמור מבלז). עבר לאנטורפן."},{"i":8435,"n":"בלומנצויג, יהושע","b":"דומ\"צ בהרובאשוב-תר\"ל"},{"i":8436,"n":"בלומנצוייג, אליהו מאזיראן","f":"יהושע בלומנצוייג","bt":"תרכז","dt":"תרצג - יח טבת","b":"רב באזיראן-תרנז. חתנו - ר זירא בן ר גרשון ברוך חבנסקי."},{"i":8437,"n":"בלומנקרנץ, אברהם שלמה מנ\"י","k":"בעל דברי שלמה","b":"ניצל מהשואה והגיע לשנחאי-סין. רב בניו יורק. מחבר \"דברי שלמה\" נ\"י תשכח. פרסם מאמרים ב\"מאור תורה\" - שנחאי-סין תשד."},{"i":8438,"n":"בלומנקרנץ, יעקב יצחק אפרים פיש","b":"רב ברדומסק. פרסם מאמרים ב\"יגדיל תורה\" - פראגא-וארשא תרפז."},{"i":8439,"n":"בלומנקרנץ, רפאל צבי מרדומישל","b":"דיין ברדומישל-תרסה אצל ר דודל קאהן."},{"i":8440,"n":"בלומנריך, יהושע השל מוישנה","b":"מחכמי וישנה. תשובה אליו ב\"שושנים לדוד\"."},{"i":8441,"n":"בלומנריך, יעקב זליג מרוהטין","b":"מחכמי רוהטין. תשובה אליו בטוט\"ד."},{"i":8442,"n":"בלומנריך, ישראל גרשון","f":"שלמה מוישניובטשיק","dt":"תש..","b":"עלה לירושלים-תרצה. דיין בבית הדין של רא\"צ שור בירושלים."},{"i":8443,"n":"בלומענפעלד יצחק","bt":"1812","dt":"ה'תרנ 1890","bk":[["אוצר נחמד",""]]},{"i":8444,"n":"בלומפלד, ליביש חיים מברנוב","f":"שלמה אפרים","k":"בעל טעם לשבח","bt":"תרנא","dt":"תרעב","b":"חתן ר מעכיל בורר מציעשינוב. חיבר \"טעם לשבח\" לא נרשם בבילגיוגרפיות."},{"i":8445,"n":"בלומקס - משפחה","b":"משפחה עשירה במינסק. יסדו בימ\"ד שנשא את שמם."},{"i":8446,"n":"בלומש, דוד מזלצבורג וארץ ישראל","f":"משה","dt":"שנ","b":"סופר סת\"ם. רב בזלצבורג-שיד, מתלמידי ר שלמה לוריא ונזכר בשו\"ת מהרש\"ל בענין תפילין, עלה לארץ. יש הסבורים שהוא ר דוד זולצברוג מחתנו של ר יוסף כהן המזכירו בספרו \"שארית יוסף\" סימן לא. החיד\"א מזכירו כגאון דוד בלומא."},{"i":8447,"n":"בלונדוין, צבי אלימלך מקרניץ","b":"פרסם מאמרים ב\"תלפיות\" - טרנוב תרצח."},{"i":8448,"n":"בלונדס, דוד מוילנא","b":"קרבן לעלילת דם בוילנא-תרס - הואשם בפציעת משרת נוצריה לצרכי דת ונידון למאסר שוחרר אחרי שנתיים בעזרת הסניגור אוסר גרוזנברג ואחרים."},{"i":8449,"n":"בלונקיש, אברהם מקוריץ","f":"שמשון מקרמניץ","b":"רב בקורץ(=קוריץ)-שפ. אחיינו של המהר\"ל מפרג."},{"i":8450,"n":"בלוקסנהים, שמעון מקלויזנבורג","bt":"תרן","bp":"[אויברלאנד]","dt":"תש..","b":"תלמיד ישיבת פרשבורג. חתן ר יעקב מאיר ואלד מקלויזנבורג, דיין בקלויזנבורג על מקום חותנו-תרפח, ורב שם. נספה בשואה."},{"i":8451,"n":"בלושטיין, אליהו הכהן מקוזין","b":"רב בקוזאן. פרסם מאמרים ב\"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד."},{"i":8452,"n":"בלושטיין, יוסף איזיק מניו יורק","bt":"תרך","bp":"קאלואריא","b":"פרסם בעתונים כבר בגיל 15. היגר לארה\"ב-1879, למד רפואה והיה רופא בביה\"ח היהודי \"בית ישראל\". פרסם ב\"המגיד\", \"העברי\", ועוד. פעל ליסוד הת\"ת בניו יורק והיה אחד ממנהליה. ציר בקונגרס הציוני."},{"i":8453,"n":"בלז, אברהם מלנצהוט","f":"יהודה יעקב","dt":"תרע","b":"שו\"ב בבלז, ולנצהוט שם עסק בצרכי צבור וכן היה חזן ובעל מקהלה מפורסם."},{"i":8454,"n":"בלז, יהודה יעקב מלנצהוט","f":"אברהם מועדייקה","bt":"תר","bp":"ועדייקה (ליד פשמישל)"},{"i":8455,"n":"בלז, יצחק","dt":"תשד","b":"רב בטערנאווע"},{"i":8456,"n":"בלז, מנחם מנדל ממיהאלביץ","dt":"תשד","b":"חתן ר משה גרינברגר ממיהאלביץ. מו\"צ במיהלוביץ(=מיהאלביץ)."},{"i":8457,"n":"בלז, משה חיים מלנצהוט","f":"אברהם מלנצהוט","b":"שו\"ב בבלז ובלנצהוט - כאביו. בעל תפלה. חתן ר פנחס הויזרמן."},{"i":8458,"n":"בלז, פיבל מלנצהוט","f":"משה חיים מלנצהוט","bt":"תרסד","bp":"לנצהוט","b":"עבר מלנצהוט לארה\"ב-תרעא, איש עסקים ונדבן . חתן ר אהרן צבי הלוי תמוז."},{"i":8459,"n":"בלזם, דוד ממליץ","b":"עבר ממליץ לברלין ולמד בביהמ\"ד לרבנים-תרפה."},{"i":8460,"n":"בלזם, מאיר ממליץ","f":"דוד","b":"הדפיס פרקי אבות עם לקוטים - ברדיוב תרסה."},{"i":8461,"n":"בלזם, רפאל מרדומישל וחיפה","f":"אפרים יעקב","k":"בעל נחלי אפרסמון","bt":"תרמד-ו","bp":"רדומישל","dt":"תשלה","b":"חתן ר ישראל אליהו הכהן וואהל מדזיקוב. רב ברדומישל. הנובר-תרעג. עלה לחיפה-תרצו. התכתב עם השדה חמד בנערותו. חיבר \"נחלי אפרסמון\" ירושלים תשם. פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח, \"הכוכב\" - מונקטש תרצה."},{"i":8462,"n":"בלזק בנימין","bt":"1855","dt":"ה'תרצ 1930","bk":[["הלכתא למשיחא",""],["פסוקי בנימין",""],["תורת האדם",""]]},{"i":8463,"n":"בלזר, יעקב משירווינט","b":"רב בשירווינט-ליטא."},{"i":8464,"n":"בלזר, יצחק מפטרבורג וירושלים","f":"שלמה","k":"בעל פרי יצחק","bt":"תקצז","bp":"שניפישוק-וילנא","dt":"תרסז","dp":"ירושלים","b":"חתן ר חיים ליב רוטנברג-מישקובסקי מטאויסק. מחכמי ליטא, אביו ר שלמה ליפאל'ס מחכמי וילנא. תלמיד ר ישראל סלנטר בקובנה. רב בפטרבורג-תרכב כ-16 שנה, רב בקובנה-תרלח ומנהל כולל הפרושים-תרם של ר יצחק אלחנן ועזב בגלל מחלוקת המוסר-תרמא. עורך כתב העת \"תבונה\" של תנועת המוסר. ממיסדי ישיבת המוסר בסלובודקה, עבר לקלם על מקום ר שמחה זיסל זיו. שיטתו במוסר היתה של התלהבות והתפעלות ולא של בירורים שכליים. חיבר גם \"אור ישראל\"-לבירור שיטת המוסר, ועוד. עלה לירושלים-תרסד וכיהן כראש כולל וילנא ועוד. מאמר ממנו ב\"תבונה\" - ירושלים תשא. גיסו של ר חזקיה יוסף מישקובסקי (או שהיה חותנו של ר חזקיה). חתנו גם - ר אליהו אבעסט ממוסקבה."},{"i":8465,"n":"בלזר, מאיר מנדבורנה","dt":"תש..","b":"חתן ר משה לייפר (אחיו של ר מרדכי מנדבורנה). רב בנדבורנה על מקום ר מאיר ויסבלום. נספה בשואה."},{"i":8466,"n":"בלזר, שלמה מירושלים","f":"יצחק מפטרבורג וירושל","bt":"תרמט","bp":"קובנא","dt":"תשך","b":"עלה לארץ-תרסד עם אביו. מנהל כולל וילנא בירושלים, ישיבת תורת חיים ועוד. פרסם מאמרים ב\"אהל יצחק\" סטמר - תרסג - תרעד. הו\"ל \"שערי ציון\" - ירושלים תרפא."},{"i":8467,"n":"בלחובר, אליהו","f":"יצחק","bp":"בוליחוב","b":"מחכמי סטנוב. אביו של ר אריה ליב ליפשיץ מחבר \"שם אריה\"."},{"i":8468,"n":"בלחובר, אפרים מזלישטשיק","b":"ראב\"ד זלישטשיק-תרנז."},{"i":8469,"n":"בלחובר, יצחק מקאליש","b":"מחכמי קאליש, התנצח בהלכה עם בעל ה\"חוות דעת\" שהיה הראב\"ד שם."},{"i":8470,"n":"בלחובר, שמואל מזלישטשיק","b":"מחכמי זלישטשיק. חתנו של ר איסר הכהן ברונשטין מלנצקרינין, וגיסו של ר יהודה ליבש לנדא מסדיגורא."},{"i":8471,"n":"בלחנס, שלמה ממרוקו","dt":"תקמב","dp":"כפר אית תאגאנת-מחוז מראקש","b":"מצדיקי מרוקו. פירוש שמו בן לחנס = בן הנחש, על שם נס שאירע לו עם נחש. לפי המסורת מוצאו מארץ ישראל, מופיע ברשימות דמנאת של שבעה רבנים שהגיעו למרוקו כמגיירים (אחד מארבעה השליחים מירושלים במרוקו, ונפטרו בשליחותם, ומהם - ר עמרם דיואן. קברו נחשב למקום מקודש ובאים להשתטח שם). יתכן והוא אחיו של ר חיים לשקר."},{"i":8472,"n":"בלחסן, יצחק ממכנאס - א","dt":"תקסא - ז אדר","b":"מחכמי מכנאס."},{"i":8473,"n":"בלחסן, יצחק ממכנאס - ב","b":"מחכמי מכנאס, חתם על הסכמה-תקץ."},{"i":8474,"n":"בלטוך, יחיאל","b":"תשובה אליו ב\"מנחת שי\"."},{"i":8475,"n":"בלטנר, קופל מיפו","b":"מחכמי יפו-תריז. חתנו - ר מאיר הירשפלד."},{"i":8476,"n":"בלטרומנץ, יעקב מוילנא","f":"שבתי מלזדייא","k":"יעקב אבא'ס","dt":"תרו - כה סיון","dp":"וילנא","b":"חתן הגביר ר אבא בן אשר. מחכמי \"ישיבת הארבעים\" בוילנא-תקפז. גביר מחכמי וילנא, גבאי בישיבת מייליס. בנו ר עקיבא."},{"i":8477,"n":"בליאה ן, יעקב","b":"מגדולי חכמי ספרד בזמן הגירוש-רנ\"ב"},{"i":8478,"n":"בליאשוב, אשר ממראחווא","f":"ברוך","bt":"תרה","b":"רב במרחווא(=מראחווא)-פודוליה-תרלה. בנו - ר זלמן רב לצדו."},{"i":8479,"n":"בליאשוב, זלמן ממראחווא","f":"אשר ממראחווא","b":"רב במראחווא-פודוליה לצד אביו. נסמך מאת: ר צבי הירש רבינוביץ מקובנא, ר משה דנישבסקי."},{"i":8480,"n":"בלידה, משה מתימן","f":"יוסף","k":"אלמעלם-המורה","b":"נכד לר משה אלבלידה. מחכמי תימן-רסט, מאזור חצ'ור אלעליא, ממכ'לאף סנחאן, אלגרן , בני אלאצב. חיבר \"שרח אשת חיל\", \"שרח אלדאלה\", ועוד. בקולופון לאחד הספרים מתאר את ההסטוריה של תימן והיהודים בה."},{"i":8481,"n":"בלידשטין, יעקב מחאראשץ","f":"ברוך יוסף","bt":"תרלב","b":"חתן ר שלמה זלמן סנדר כהנא-שפירא מקריניק. רב בחארשץ-פלך גרודנא-תרסב."},{"i":8482,"n":"בליטץ, פנחס זאב מסוסנוביץ","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":8483,"n":"בליטשטין, דוד מסטניסלב","b":"שו\"ב בסטניסלב. תשובה אליו בטוט\"ד."},{"i":8484,"n":"בליי, אהרן הלוי מטולטשוב","b":"מחכמי טולטשוב (ליד למברג). תשובה אליו במהרש\"ם."},{"i":8485,"n":"בלייא, מאיר מאונגוואר","b":"חתן ר משה חיים ליטש-רוזנבוים מגרוסורדין. רב באונגוואר."},{"i":8486,"n":"בלייויס, אברהם יצחק מבריסק","dt":"תרצו","b":"דיין בבריסק, ואב\"ד-תרנד."},{"i":8487,"n":"בלייח, חיים מאלגיר","k":"בעל פתח השער","bt":"תקצד","b":"תלמיד ר יוסף קרסינטא, יהודה אלשקר, ר יעקב אלמדיוני, ר אברהם אלנקאוה. רב בתלמסאן-תרכח כ-50 שנה. היה מעורב במחלוקת בענין מקום קבורת יעקב עקריש ותשובות ממנו ב\"כבוד יעקב\" - תרנב, וכנגדו בקונטרס \"חזות קשה\", ותגובתו ב\"אתם קשות-תרנג. הו\"ל \"שער כבוד ה\" לר אפרים אנקאווה עם פירו ש ממנו. השיב תשובות רבות ובהם בענין הפקעת קדושין ב\"שערי רחמים\". כיהן אצלו כדיין - ר שמואל צולטאן."},{"i":8488,"n":"בלייכרודה, אברהם יצחק","bt":"תרכח","dt":"תשיד - יא אדר","b":"רב בברלין-תרע\"ו,עלה לא\"י-תרצ\"ה"},{"i":8489,"n":"בלייכרודה, נפתלי הרש","b":"רב באובוזיצקי-ת\"ר"},{"i":8490,"n":"בליימן, צבי יעקב","dt":"תשג","b":"רב בווארענאל"},{"i":8491,"n":"בלייער, מנחם","k":"בעל כבוד הלבנון","dt":"תרמ - ו סיון","b":"רב בטשאטה,פורוסלו,איגור"},{"i":8492,"n":"בליך, אריה ליב מלאבאווא","f":"אלחנן אשכנזי","dp":"קראקא","b":"בנו של ר אלחנן אשכנזי שברח מרוסיה לגליציה ושינה שמו. אב\"ד וואליע-מיכובה, לאבאווא ואישטשע. מחסידי צאנז. בנו ר צבי אלימלך רב על מקומו בלאבאווא."},{"i":8493,"n":"בליך, יעקב אשכנזי מזולקוא","f":"שמואל מזולקוא","b":"מחכמי זולקוא, חתם-תם על תקנה בענין הכנסות השמשים בקהלה."},{"i":8494,"n":"בליך, יעקב מאיר מויפנישטשיק","b":"רב בוויפנישטשיק-תר\"ח"},{"i":8495,"n":"בליך, יעקב מאיר מוישניובטשיק","f":"מתתיהו","bp":"טרנופול","dt":"תשב","dp":"צפת","b":"עלה לצפת-תרצג. הדפיס הגדת באר מים - ירושלים תרצה."},{"i":8496,"n":"בליך, יעקב שלמה מאנדריכוב","f":"צבי אלימלך","bt":"תרי","dt":"תרף","b":"רב באנדריכוב-תרסט, מעהירש-אוסטרה (מורביה). בניו ר חיים ברוך ור משה ישבו על מקומו אחריו."},{"i":8497,"n":"בליך, יצחק יוסף מגאווע","f":"נתן בליך","bt":"תקפ","dt":"תרנט - כו אדר","b":"רב בגאווע. חתנו וגיסו - ר ישכר דב קאהן מערדי סענזארץ."},{"i":8498,"n":"בליך, משה מוינה","b":"מחכמי וינה. תשובה אליו בשו\"ת רב\"ז."},{"i":8499,"n":"בליך, נתן מטשאבא","b":"מו\"צ בטשאבא-תק\"צ"},{"i":8500,"n":"בליך, צבי אלימלך מלאבאווא","f":"אריה ליב","bt":"תקפה","dt":"תרנה","b":"אב\"ד לאבאווא. חסיד צאנז. חתן ר חיים ברוך וולף אב\"ד וישניצה. מקורב לדברי חיים."},{"i":8501,"n":"בליך, שמואל מזולקוא","b":"מחכמי זולקוא, חתם-תמו ובשנת תנד, ועל בחירת ראשי הקהל-תמט, ועוד."},{"i":8502,"n":"בליכפלד, פנחס זליג מקורטשין","f":"אברהם יהושע","bt":"תרצב","bp":"קורטשין","dt":"תשנד","b":"חתן ר חיים דים מקראקא. גלה לסיביר בילדותו. הגיע לאנטורפן. חסיד בלז. חתן ר מאיר לוינטל מירוסלב."},{"i":8503,"n":"בליכר, אפרים ישראל מאושפיצין","f":"שמשון","k":"בעל מרפא לשון ארמי","bt":"תקעד","bp":"גלוקסדורף","dt":"תרמב","b":"רב בפרשבורג, קאסאן ובודפסט, אושפיצין. אב\"ד נייהייזל-תקף. הקים בי\"ס בוינה. פרופ' לשפות באוניברסיטת למברג-תרי, רב באושפצין (אושביץ)-תריד, וואדוביץ-תריז. חיבר \"מרפא לשון ארמי\" וינה תקצט."},{"i":8504,"n":"בליכר, דוד ממזריטש","dt":"תשד - כה אלול","b":"איש מוסר,מרביץ תורה,ר\"מ במזריטש"},{"i":8505,"n":"בליכר, יצחק יוסף מקראקא","b":"ראש ישיבת אלכסנדר בקראקא עם ר ישראל יצחק וולהנדלר."},{"i":8506,"n":"בליכר, משה שמואל מקראקא","f":"אברהם","bt":"תרלב","bp":"קראקא","dt":"תרצה","dp":"קראקא","b":"תלמיד רחא\"ל הורביץ. דיין אצל ר יוסף ענגיל בקראקא ואחר כך ראב\"ד שם."},{"i":8507,"n":"בליכרוירט, נפתלי הירש מוילען","b":"תלמיד ר עקיבא איגר, וחתן בנו - ר אברהם איגר מראויטש. רב בוילען-ליד פוזנא, קרניק. נזכר בשו\"ת ר עקיבא איגר."},{"i":8508,"n":"בליליוס, אלעזר מקורפו","b":"בלשן, מומחה לשפות שמיות, מרצה בשלוניקי. חיבר ספר על הגניזות הארמיות באסואן ואלפנטינה - תרפב."},{"i":8509,"n":"בליליוס, דניאל מאיטליה ואמשטרד","k":"בעל תולדות אדם","b":"מגדולי חכמי איטליה, דרשן, חזן, משורר, מרביץ תורה. רב בונציה-שס, אמשטרדם. חיבר גם \"כרם חמד\"."},{"i":8510,"n":"בליליוס, יעקב מונציה","f":"עמנואל","k":"בעל בנין נערים","b":"מקובל, רב בונציה-תקי. חיבר \"בנין נערים\" - כנגד \"תקון סופרים\" לר שמואל אבוהב. הסכים על \"השתערות מלך הנגב|. בשליחות קהלת ונציה באמשטרדם."},{"i":8511,"n":"בליליוס, יצחק מונציה","f":"יעקב בליליוס","b":"מגדולי רבני איטליה,רב בויניציאה-תקמד. שלם בדיעות,מגדולי ירושלים"},{"i":8512,"n":"בליליוס, רפאל עמנואל מהודו","f":"שמחה סימה","b":"בנה של הנדיבה שמחה סימה. היגר מבבל להודו והתעשר. ביקר בירושלים-תרמז, חבר המועצה המחוקקת בהונג קונג. תרם לצדקה במקומות מגוריו ובירושלים."},{"i":8513,"n":"בליליוס, שמחה סימה מהודו","dt":"תרפו - כג כסלו","dp":"הונג קונג","b":"תושבת כלכתא-הודו, הונג קונג. תרמה לעניני צבור ולקהלת ירושלים. בנה - רפאל עמנואל."},{"i":8514,"n":"בלימאוויץ, דובער ממינסק","b":"גביר מחכמי מינסק-תרן."},{"i":8515,"n":"בלין, אליהו מורמיזא","f":"יצחק","b":"ר\"מ ודיין מחכמי וורמייזא-רן, בזמן חיבר פירוש לרש\"י על התורה כמובא בספר קרובו - בעל \"דבק טוב\" המזכירו בספרו. ברשימת ספרי רד\"א - \"קונטרס ריב\" על המחלוקת שהיתה בינו לבין ר הירץ בן גרשון מוורמייזא. חיבר פירוש לרש\"י על התורה - בכת\"י."},{"i":8516,"n":"בלין, אליעזר אשכנזי","f":"יעקב","k":"בעל הוספות לעברונות","b":"חיבר הוספות לספר עברונות לר יעקב מרקריאה - בזל שכא."},{"i":8517,"n":"בלינפנטי, אליהו חזקיה","k":"בעל אורה ושמחה","b":"רב באמשטרדם, חיבר \"אורה ושמחה\" - להכנסת ספר תורה - אמשטרדם תקך. בנו - ר יצחק."},{"i":8518,"n":"בלינפנטי, יצחק מאמשטרדם","f":"אליהו חזקיה הכהן","k":"בעל שפר תהלים","dt":"תקמא - ט תשרי","b":"מחכמי ישיבת עץ חיים באמשטרדם-תקיג - הסכמה ממנו ל\"דברי דוד-תקיג. חיבר \"עטרת פז\", \"ברית כהונת יצחק\", \"שי\"ח יצחק\" - קובץ זכרון לספרים רבים לעדת הספרדים, וכן חיבר שירים. לדעת שטיינשניידר חיבר הקדמה ל\"אבני חפץ\"-תקן (ואם כן שנת פטירתו מאוחרת יותר)."},{"i":8519,"n":"בלינפנטי, מאיר הכהן מברבדוס","bt":"תסה","dt":"תקיג","b":"רב בברידג'טאון-ברבדוס. קרובו של ר יצחק אליהו בן חזקיה הכהן בלינפנטי מאמשטרדם."},{"i":8520,"n":"בלינקה, חיים אלכסנדר סנדר","f":"יהודה","bt":"תרלג","bp":"רוגטשוב","b":"תלמיד ר שניאור זלמן מרוגצוב. רב באיצניה(=איטשניא)-תרסז."},{"i":8521,"n":"בליץ, אברהם","f":"מרדכי בליץ","b":"רב בבזדן-תר\"מ"},{"i":8522,"n":"בליץ, יוסף מבוזנוב","b":"מחכמי בוזנוב. תשובה אליו \"ארץ צבי\"."},{"i":8523,"n":"בליץ, יקותיאל מויטמונד","k":"בעל תנ\"ך אשכנזי","b":"תרגם את התנ\"ך ללשון אשכנז-אמשטרדם תלט."},{"i":8524,"n":"בליץ, מרדכי","b":"רב בבעזדאן-תר\"י"},{"i":8525,"n":"בליצר, ליב מזבלוטשיע","b":"רב בזלוטשיע-תרנה."},{"i":8526,"n":"בליצשטין, חיים מסובוטש","dt":"תש..","b":"רבה האחרון של סובוטש. נספה בשואה."},{"i":8527,"n":"בליק, פיביש מירטשוב","b":"רב ביריטשוב-תרמו. חתן ר שמואל גרסטל."},{"i":8528,"n":"בלך (בלעך), מרדכי","f":"שמואל","bt":"תרמה","bp":"חודרוב","dt":"תרצה","b":"אב\"ד אוסציא-תרמה."},{"i":8529,"n":"בלך, חיים מברודשין","f":"צבי הירש","bt":"תריד","dt":"תש","b":"מחכמי ברודשין ועבר לספינקא והיה גבאי אצל האדמורים שם. כתב הקדמה לספר משנת חסידים עם פירוש מגיד משנה - למברג תרלח."},{"i":8530,"n":"בלך-שור, מרדכי מאוסציא","f":"שמואל","bt":"תרמה","dt":"תשג","b":"רב באוסציא זילוני(=אושטי זשילנה, אומצע-זילאנע). אחיו של ר אהרן מחודרוב. עבר לוינה, ציריך, קובה וארה\"ב. נכד ר שמואל ישכר רוזנגרטן - ראש ישיבת בלז."},{"i":8531,"n":"בלכי, רפאל הלוי ממיץ הקדוש","b":"נהרג עק\"ה בעלילת דם במיץ. על המעשה בכתב יד בשם \"מעשה עלילת הדם וקידוש השם של ר רפאל הלוי...\"."},{"i":8532,"n":"בלכמן, דוד מסובוליבקה","f":"ברוך אריה","bt":"תרלא","b":"רב בסובוליבקה(=סאבאליווקע)-תרנו."},{"i":8533,"n":"בלכמן, מרדכי יהודה מקונסטנטין","f":"יעקב יוסף","bt":"תרמד","b":"נכד ותלמיד ר שמואל אברהם אלתר מקונסטנטין. נסמך מאת זקנו, ור חיים סולוביציק. רב בלנצקרוניא, קונסטנטין ישן-ווהלין-תרע על מקום זקנו. פרסם מאמרים ב\"אסיפת חכמים\" - אטוניא-בויאן תרע-תרעד."},{"i":8534,"n":"בלכמן, שמואל אברהם מקונסטנטין","b":"מצאצאי המהרש\"א וה\"פני יהושע\", ומצד אמו מצאצאי ר יעקב יוסף מפולנאה. רב בקונסטנטין ישן-ווהלין-תרך ונכדו ר מרדכי יהודה על מקומו אחריו-תרע."},{"i":8535,"n":"בלכר, ישראל","dt":"תשג","b":"רב באשמינע"},{"i":8536,"n":"בלמט, יצחק","b":"רב ברופשיץ-תרן. תשובה אליו בשות מהר\"ש."},{"i":8537,"n":"בלמש, אברהם מפדובה","f":"משה בן מאיר או מאיר","k":"בעל מקנה אברהם","bt":"ר","bp":"לישי-נפולי","dt":"רפב","dp":"פדובה","b":"תלמיד ר יהודה מסיר ליאון, ור משה שר שלום. חכם מדקדק פילוסוף ורופא בליצו-איטליה, פדובה. מרצה באוניברסיטת פדובה. חיבר \"מקנה אברם\" - ונציה - עם תרגום לטיני (החסיר אות ה' מאברהם - לזכר בנו שנפטר בחייו) - נפטר בטרם השלימו והשלימו ר קלונימוס בן דוד בן קלונימוס. חיבר ספרים בדקדוק."},{"i":8538,"n":"בלנדוין, יעקב יצחק מברטש","f":"דב","bt":"תרם","dt":"תרץ","b":"בחיר תלמידי מהר\"י שמלקיס בעל \"בית יצחק\". מחסידי בובוב. חתן ר מרדכי שפירא אב\"ד ברטש. ראב\"ד בברטש על מקום חמיו. בנו ר צבי אלימלך שפירא. מתורתו בכר\"ש-תשם. תולדותיו בעץ חיים."},{"i":8539,"n":"בלנדוין, צבי אלימלך","b":"פרסם מאמרים ב\"הכוכב\" - מונקטש-נ\"י תרצה."},{"i":8540,"n":"בלנק, אברהם מרוזניאטוב","dt":"תרנט - בערך","b":"רב ברוזניאטוב-תרמב. תשובה אליו ב\"שדה יצחק\"."},{"i":8541,"n":"בלנק, מאיר הלוי","b":"ראב\"ד נדבורנה. תשובות אליו \"מנחת יחיאל\"."},{"i":8542,"n":"בלנק, משה כהנא","f":"חנוך הניך","k":"בעל אהל משה","bt":"תרלח","b":"רב בבקוי-מולדובה-תרסז. נסמך מאת: ר אריה ליב הורביץ מסטניסלב, ר פנחס בורשטין מסערעט, ר בנימין אריה וייס מטשרנוביץ, ר אברהם מנדל שטינברג מברודי. חיבר \"אהל משה\" - בכת\"י."},{"i":8543,"n":"בלנקמן, אברהם יחיאל מאיר משבר","dt":"תשג","b":"רב בשברשין. פרסם מאמרים ב\"אהל מועד\" - איזביצא - בילגוריי - תרפו, \"אהל תורה\" - קראקא תרפח, \"בית מאיר\" - אוסטרובצה - פיעטרקוב - תרצא, \"דבר בעתו\" - וארשא תרצט, \"דגל הרבנים\" - וארשא תרפו, \"יגדיל תורה\" - פראגא-וארשא תרפז, \"הכרם\" - וארשא תרפז, \"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ, \"לקט ששנ\"ה\" - סטמר תרצד, \"עטרת תפארת\" - פודוולוטשיסק-בילגוריי תרצא, \"הפרדס\" פיעטרקוב-שיקגו תרעג-תרפז, \"שערי אורה\" - מיהאלביץ תרץ-תרצד, \"תלפיות\" - טרנוב תרצח, \"תפארת ישראל\" - וארשא-נ\"י-תל אביב תרצו, \"התפוח\" - בנדין תרפח, \"תצא תורה\" - קריניצה תרצא."},{"i":8544,"n":"בלנקמן, נתן משברשין","b":"רב בשברשין. פרסם מאמרים ב\"עמק הלכה\" - וארשא תרפו."},{"i":8545,"n":"בלנקשטין, אהרן יואל מקראקא","b":"מחכמי קראקא. חתן ר אלכסנדר סנדר אחי מהר\"י שמלקס שהזכירו ב\"בית יצחק\"-תרכו."},{"i":8546,"n":"בלעיש, אברהם","f":"שלום","k":"בעל יד אבשלום","bt":"תקלג","dt":"תריג","b":"רבה של טוניס-תקע ושר האוצר, עלה לירושלים, רב באלג'יר, רב בניצה, דיין בלונדון-ת\"ר, חיבר \"יד אבשלום\"","bk":[["תבואת יקב","מפרשי רמב\"ם"]]},{"i":8547,"n":"בלעיש, חיים","bt":"תרכד","dt":"תשז - כ סיון","b":"תלמיד ר' מרדכי סמאג'ה,התפרנס ממסחר בתבואה,מנהל ישיבת \"חברת התלמוד\",רב ראשי בתוניסיה-ת\"ש"},{"i":8548,"n":"בלעיש, יהודה חי","b":"מרבני תונס"},{"i":8549,"n":"בלעיש, רפאל מקירואן-תונס","b":"דיין בקירואן-תרסז, והתכתב עם ר ישראל זיתון."},{"i":8550,"n":"בלעם ן, יהודה","f":"שמואל","k":"בעל טעמי המקרא","bp":"טולידו","b":"מגדולי המדקדקים ומפרשי המקרא בספרד,חי בסיביליה-ד'תת\"נ,חלק על ר' משה ן' ג'קטיליה,חיבר \"ספר המישר\",חיבר סליחות,חכם גם בתלמוד והלכה,התווכח עם הקראים,הוערך בידי הראב\"ע והרמב\"ם"},{"i":8551,"n":"בלעק, משה","bt":"תרנט","dt":"תשיז","b":"רב בווינה-תרפ\"ד,ברוקלין-תרצ\"ד"},{"i":8552,"n":"בלף, שמואל","b":"תשובה אליו בשו\"מ."},{"i":8553,"n":"בלקובסקי, יצחק מאיר מסוסנוביץ","b":"פרסם מאמרים ב\"תלפיות\" - טרנוב תרצח."},{"i":8554,"n":"בלקיירי די, טודרוס","f":"יהודה","b":"מרבני מונטפלייר בזמן הרשב\"א,התנגד ללימודי חכמות"},{"i":8555,"n":"בלקין, שלום מרישא","b":"מחכמי רישא. תשובה אליו \"כוכב מיעקב\"."},{"i":8556,"n":"בלקן, אברהם צבי מפודגורזע","f":"יוסף מנחם מאושפיצין","k":"הו\"ל דברי שמחה","dt":"תש..","b":"מחכמי פודגורזע. חסיד רשי\"ב הלברשטם מצשינוב והדפיס את ספרי רבו ב\"דברי שמחה\" - קראקא תרצב. נספה בשואה."},{"i":8557,"n":"בלקסנהים, שמעון","dt":"תשד","b":"דומ\"צ בקלוזנבורג"},{"i":8558,"n":"בלר, אריה יהודה","dt":"תרע.. - בערך","b":"נכד ר צבי יוסף דומיניץ מרעדים. גביר עשיר ונדבן - מקורב לגדולי האדמורים. מצאצאיו הנוירולוג פרופ' בלר."},{"i":8559,"n":"בלר, זאב וולף","f":"אריה יהודה","dt":"תרפז","b":"תלמיד חכם וגביר בעל יערות. חתן ר חיים יעקב דומיניץ מרעדים. חסיד צאנז. סירב למלא מקום חותנו ברעדים (אמר שרק מי שאין לו נכסים לנהל שיהיה רב)."},{"i":8560,"n":"במברגר יצחק דב בן שמחה","bt":"1807","dt":"ה'תרלח 1878","bk":[["יד הלוי",""],["מורה לזובחים",""],["מלאכת שמים",""],["נחלי דבש",""],["נטיעה של שמחה",""],["קורא באמת",""]]},{"i":8561,"n":"במברגר, זעקל הלוי","b":"דומ\"צ בפפד\"מ-תר\"מ"},{"i":8562,"n":"במברגר, יהודה מפפד\"מ","f":"שמחה מאשפנבורג","bt":"תרכא","b":"סוחר ספרים בפפד\"מ. נפטר צעיר."},{"i":8563,"n":"במברגר, יעקב הלוי","f":"שמחה מאשפנבורג","k":"הו\"ל פירוש שיר השירי","b":"הו\"ל פירוש שיר השירים לר אביגדור כהן צדק-תרנט"},{"i":8564,"n":"במברגר, יעקב משוורזנץ","b":"פרסם מאמרים ב\"יגדיל תורה\" - ברלין-קראקא תרנא."},{"i":8565,"n":"במברגר, יעקב קופל הלוי מורמיזא","f":"משה יהודה סגל","bt":"תקמה","dt":"תרכה","b":"תלמיד אביו - רב בנקרבישופסהיים, ר אשר (בן בעל שאגת אריה) מקרלסרוה. חתן ר אליקום געטשליק ממנהיים. רב בוורמייזא כ-40 שנה. מתלמידיו ר צבי בנימין אוירבך בעל \"נחל אשכול\". פרסם מאמרים ב\"שומר ציון הנאמן\"."},{"i":8566,"n":"במברגר, יצחק דב זליגמן מוירצב","f":"שמחה במברגר","k":"בעל מלאכת שמים","bt":"תקסח","bp":"ויסנברון-גרמניה","dt":"תרלט - טז תשרי","b":"תלמיד ר וולף המבורג ור מנדל קארגוי בפיורדא, ר אברהם בינג בוירצבורג. לחם ברפורמים, מרביץ תורה בהידינגספלד, רב מדינת וירצבורג-תר ולימד רבים. חיבר ספרים חשובים בהלכה ובתלמוד. פרסם מאמרים ב\"כבוד הלבנון\" - ירושלים-פאריס תרכג-תרמב, \"שומר ציון הנאמן\" - אלטונא תרו-תרטז."},{"i":8567,"n":"במברגר, יצחק זעקל מקיזינגן","f":"שמחה מאשפנבורג","k":"בעל לקח טוב","bt":"תרכג","b":"תלמיד ביהמ\"ד לרבנים בברלין. נסמך מאת: ר יצחק אלחנן מקובנא, ר שמעון הורביץ מלייפציג, ר מיכאל כהן מקלינע-דלינגן, ר שלמה ברייער מפפד\"מ. רב בשוורזנץ-פלך פוזן-תרמח, שרים, קיסינגן(=קיזינגען). חיבר גם \"זכרון אברהם\", ועוד."},{"i":8568,"n":"במברגר, משה אריה מבאד קיסינגן","f":"יצחק דוב במברגר","bt":"תקצח","bp":"ויזנבורן","dt":"תרנט","b":"חתן בעל \"ערוך לנר\". רב בארי-קיסינגן-תרן. פרסם מאמרים ב\"יגדיל תורה\" - ברלין-קראקא תרנא."},{"i":8569,"n":"במברגר, משה אריה ממגנצא","b":"רבה האחרון של מיינץ(=מגנצא), ניצל מהשואה, ברח לאנגליה-תרצח בערך ועסק שם בחינוך."},{"i":8570,"n":"במברגר, משה אריה משנעלנקא","f":"שמחה במברגר","b":"רב בשידלבורג, שנלנקא(=שענלנאק)-תרע. פרסם מאמרים ב\"בית ועד לחכמים\" - סטמר תרפב, \"המאסף\" - ירושלים-אלכסנדריה תרנו-תרעג."},{"i":8571,"n":"במברגר, נתן הלוי מוירצבורג","f":"יצחק דב מוירצבורג","k":"בעל פקודת הלויים","bt":"תר","dt":"תרעט - כח ניסן","b":"רב בוירצבורג-תרלח על מקום אביו. פרסם מאמרים ב\"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז, \"יגדיל תורה\" - ברלין-קראקא תרנא, \"תורה מציון\" - ירושלים תרנה-תרסה. בנו - ר שמחה מואנדסבק, חתניו: ר מנחם וינברג מניימרקט, ר אברהם שוייצר מוקרסהיים, ר א' ורטהימר ממינכן."},{"i":8572,"n":"במברגר, פנחס הלוי","f":"שלמה במברגר","k":"בעל אוצר התורה","b":"רב בהמבורג-תר\"ס"},{"i":8573,"n":"במברגר, שלמה הלוי מבריסל","f":"שמחה - מלאכת שמים","k":"הו\"ל קול שמחה","bt":"תרלה","b":"תלמיד ר אברהם ליפמן ולדר משענלאנקע. מנהל ביה\"ס באשפנבורג-בווריה. רב בבריסל-תרסה. חיבר בגרמנית \"השקה על דברי ימי אחב\"י בעיר אשפנבורג\". הו\"ל \"קול שמחה\" לאביו עם הוספות ממנו."},{"i":8574,"n":"במברגר, שלמה הלוי מזנהיים","f":"יצחק דוב מוירצבורג","k":"בעל הגיון שלמה","bt":"תקצו","dt":"תרעח - כו אדר","dp":"וירצבורג","b":"מורה בזלצבורג-תרכח, רב בלנגוי-שוייץ-תרלב, נדר-הנגנטל(=ניעדע-האגענטאל)-שוייץ-תרלט, זנהיים-אלזס-תרמח. פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה. הו\"ל כתבי אביו יחד עם אחיו - ר משה אריה מקיסינגן."},{"i":8575,"n":"במברגר, שלמה מנחם מהנאו","f":"זעקל במברגר","b":"רב בהאנוי"},{"i":8576,"n":"במברגר, שמחה הלוי","b":"רב-שנת תק\"פ"},{"i":8577,"n":"במברגר, שמחה הלוי מאושפרונג","f":"יצחק דוב במברגר","k":"בעל מלאכת שמים","bt":"תקצב","dt":"תרנח","b":"רב בקלמר, פישך, אשפנבורג-תרמ. פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה - והספד עליו מאת ר יעקב אורנשטין. בנו - ר יהודה מפפד\"מ (סוחר ספרים)."},{"i":8578,"n":"במברגר, שמחה הלוי מואנדסבק","f":"נתן מוירצבורג","k":"בעל הנהגת האדם","bt":"תרל או תרלב","b":"תלמיד ביהמ\"ד לרבנים בברלין. רב בוורצלב-תרנט, ואנדסבק-תרסג (אחת משלוש קהלות אה\"ו), עלה לארץ. חיבר ספרים ומאמרים בגרמנית."},{"i":8579,"n":"במברגר, שמחה הלוי משטוטגרט","f":"יצחק זקל במברגר","k":"בעל שארית שמחה","bt":"תרנט","dt":"תשיח - ט תשרי","b":"רב בשטוטגרט,עלה לבני ברק-תרצ\"ט"},{"i":8580,"n":"במפי, דובער ממינסק","f":"ירוחם","bt":"תקפג","dt":"תרמח - כז אדר","dp":"מינסק","b":"גביר מחכמי מינסק."},{"i":8581,"n":"במפי, ישכר דובער ממינסק","b":"גביר מחכמי מינסק, וחוקר מנהגי ישראל-תרם בערך."},{"i":8582,"n":"בן אהרן, אהרן","f":"אברהם","b":"מחכמי בבל-ד'תרן. ממשפחת תלמידי חכמים ועשירים שנזכרו בתשובות רב שרירא גאון ובנו רב האי. אחיו של ר משה."},{"i":8583,"n":"בן אמוזג אליהו","bt":"1822","dt":"ה'תרס 1900","bk":[["אימת מפגיע",""],["טעם לש\"ד",""],["יענה באש",""]]},{"i":8584,"n":"בן אריה, צבי מאיר","b":"פרסם מאמרים ב\"היכל התלמוד\" - ת\"א תשא."},{"i":8585,"n":"בן אשר - משפחה","b":"משפחת בעלי מסורה מארץ ישראל - אחד מבניהם כתב את כתר אר\"ץ - שהיה בידי הרמב\"ם שסמך עליו."},{"i":8586,"n":"בן אשר, אברהם מחלב","f":"גדליה","k":"אב\"א - בעל אור השכל","dt":"שמו","dp":"צפת","b":"תלמיד ר יוסף קארו בצפת ונזכר בספריו. רב בחלב-של ור שמואל בן יוסף הכהן על מקומו אחריו. חיבר ספר אור השכל. מעדני מלך ונציא שכז, פירוש ספר שמות בכתי. גיסו של ר שניאור בן יהודה פאלקון."},{"i":8587,"n":"בן אשר, אהרן מטבריה","f":"משה","k":"בעל דקדוק הטעמים","b":"מחכמי המסורה בטבריה בשנים ד'תרסד (904) ותרפה (925), הוא האחרון בשושלת בן אשר וכתב את \"כתר ארם צובא\" שהרמב\"ם סמך את ידו עליו, חיבר גם \"דקדוק הטעמים\" לייפציג תרלח, ועוד בכתב יד. ישנה דעה שהיה קראי, ויתכן שהוא שרב סעדיה גאון התוכח עמו."},{"i":8588,"n":"בן אשר, אשר הגדול הזקן","b":"ראשון בשלשלת בעלי המסורה - ממשפחת בן אשר, ומצאצאיו הסופר אהרן בן אשר שכתב את כתר אר\"ץ."},{"i":8589,"n":"בן אשר, משה מטבריה","b":"מחכמי המסורה בטבריה בשנת ד'תרנה (895), ואביו של ר אהרן בן אשר בעל ה\"כתר\" (יש המייחסים את כתיבת הכתב לר משה עצמו)."},{"i":8590,"n":"בן דוד, אברהם מירושלים","b":"תלמיד ישיבת \"שערי ציון\" בירושלים. פרסם מאמרים ב\"בכורי ציון\" - ירושלים תשד."},{"i":8591,"n":"בן דוד, אלעזר"},{"i":8592,"n":"בן דוד, חכמון מטריפולי","bt":"תר","bp":"טריפולי","dt":"תרסח","dp":"צפת","b":"מקובל מחכמי טריפולי, עלה לצפת-תרם."},{"i":8593,"n":"בן דוד, טודרוס","k":"ר' טודרוס בן דאוואר","b":"רופא בקלעת-איוב,תלמיד הריב\"ש"},{"i":8594,"n":"בן דוד, יצחק","f":"שמואל","b":"תלמיד הרשב\"א. מחכמי ספרד בדור האחד עשר. אחיו של בעל הצרורות."},{"i":8595,"n":"בן דוד, יצחק מספרד","f":"שמואל","b":"תלמיד הרשב\"א. מחכמי ספרד, אחריו של \"בעל הצרורות\"."},{"i":8596,"n":"בן דעת, משה אהרן מבילסק","dt":"תשג","b":"רב בבילסק. פרסם מאמרים ב\"כנסת ישראל\" - וילנא תרץ."},{"i":8597,"n":"בן זאב, יהודה ליב מברלין","k":"בעל תלמוד לשון עברי","bt":"תקכח","bp":"קראקא?","dt":"תקעא","b":"מחכמי ברלין, ברסלוי. מגיה אצל אנטון שמיד של הש\"ס (ונפטר באמצע), נחשד בהשכלה ונרדף מאת ר דוד דייטש. חיבר \"שומר אמונה\" על \"אמונות ודעות\" לרס\"ג, \"בית הספר\", \"אוצר השרשים\", ועוד. השתתף בתרגום התנ\"ך שנדפס אצל שמיד. פרסם מאמרים וחתם - יל\"ק (יהודה ליב קראקא)."},{"i":8598,"n":"בן זיזא, אברהם"},{"i":8599,"n":"בן זרגיל, דון משה","b":"דיין בטולידו"},{"i":8600,"n":"בן חייא, אברהם","k":"ר' אברהם הנשיא","bt":"ד'תתל","dt":"ד'תתצה","b":"מגדולי חכמי ספרד, מדקדק, תוכן, רב בשוריא, ברצלונה, חיבר ספר \"העיבור\""},{"i":8601,"n":"בן חיים, י' מארה\"ב","b":"פרסם מאמרים ב\"כנסת ישראל\" - נ\"י תרצב - כתב עת הסתדרות תלמידי סלובודקה באמריקה."},{"i":8602,"n":"בן טובים, יצחק איזיק מביאליסטו","f":"שלמה זלמן בנדט","k":"בעל גאון יעקב","bt":"תריב","bp":"ראסיין","dt":"תרפו","dp":"ירושלים","b":"נכד ר שמואל חסיד-תלמיד הגר\"א. תלמיד ישיבת נוברדוק. סוחר בביאליסטוק ממקורבי ר שמואל מוהליבר. חבר בתנועת \"בני משה\" והיה ממיסדי בית החולים שם, עלה לארץ והתישב ביפו-תרן, עבר לירושלים-תרנט והיה יו\"ר \"בני ישראל\" למלחמה במסיון. פרסם ב\"חבצלת\" נגד המגמות החילוניות של \"בני משה\". חיבר קובץ דרשות \"גאון יעקב\", ו\"הגיוני אב\"."},{"i":8603,"n":"בן יהודה, אליעזר","f":"יהודה ליב","k":"בעל מילון הלשון העבר","bt":"1857","bp":"לושקי-פלך וילנא","dt":"1922","dp":"ירושלים","b":"תלמיד ישיבת דוינסק. למד רפואה בפאריס, עבר לאלג'יר בגלל מחלת שחפת ופרסם משם מאמרים ב\"השחר\", \"המגיד\", ועוד. עלה לירושלים-תרמא, יסד את העתונים \"הצבי\" ו\"האור\" ובהם הטיף לשפה העברית. נרדף ע\"י קנאים בירושלים, נאסר ע\"י התורכים לאחר הלשנה, לאחר שגורש ע\"י התורכים עבר לארה\"ב בזמן מלחמה\"ע ה-I ועבד שם על המילון העברי - הושלם אחר פטירתו, חזר לירושלים בסוף המלחמה. הרב קוק פרסם מכתב כנגדו בגלל כפירתו - ב\"הפלס\" - ברלין תרסא-תרסה.","bk":[["ריב\"א","מפרשי תורה"]]},{"i":8604,"n":"בן יעקב אברהם","bt":"1914","dt":"ה'תשסה 2005","bk":[["אוצר השירים, החבורים והדרשות של הרב יוסף חיים",""],["תורת הקרבנות",""],["תורת התרומה והמעשר",""]]},{"i":8605,"n":"בן יעקב, ברוך משלוניקי","b":"מנהל ביה\"ס ת\"ת בשלוניקי-אחרי חננאל חיים חסיד, וחבר באגודת הפייטנים בשלוניקי."},{"i":8606,"n":"בן יעקב, דן","b":"פרסם מאמרים ב\"תבונה\" - קובנא תרפא."},{"i":8607,"n":"בן יעקב, חסן","b":"דיין וראב\"ד במורבעה(תימן),חיבר ספר על ר' שלום שבזי ויהודי שרעב"},{"i":8608,"n":"בן יעקב, יצחק איזיק מוילנא","f":"יעקב","k":"בעל אוצר הספרים","bt":"תקסא","bp":"רמיגולה","dt":"1863","dp":"וילנא","b":"גדל בוילנא. ביבליוגרף מפורסם ומדפיס. ישב בריגה, לייפציג, וילנא-תרח. מוכר ספרים ומו\"ל \"דברים עתיקים\", \"שם הגדולים\" לחיד\"א, ועוד. עבד עם יוליוס פירסט שהיה בלשן עברי ומזרחן. חיבר \"מכתבים ושירים\" לייפציג תרב, \"אוצר הספרים\" ובו תיאור של כ-17000 ספרים וכת\"י שהופיעו עד תרכג - נדפס ע\"י בנו יעקב. הניח בכתובים מילון גרמני עברי, ומילון לתלמוד.","bk":[["אוצר הספרים",""],["דברים עתיקים",""]]},{"i":8609,"n":"בן יצו, יהודה","b":"יליד המערב,ראש ישיבה בתלמסאן-תרפ\"ד,חזר לוהראן"},{"i":8610,"n":"בן לביא, דון ווידאל","k":"ווידאל די קאלאבריאה","b":"מחכמי ספרד, חצרן משרי מסים של מלך ספרד-ק'-ק\"נ"},{"i":8611,"n":"בן לולו, אלעזר","bp":"מרוקו","dp":"ישראל","b":"ראש ישיבה בסאלי, עלה לא\"י, דיין ורב העיר בית שאן"},{"i":8612,"n":"בן מאיר, אברהם","f":"אהרן","r":"בעל ה'אבן עזרא'","bt":"ד'תתמט \\ תתנ \\ תתנג","dt":"ד'תתקכד \\ א' אדר ד' תתקנד","b":"גאון וראש ישיבת גאונים בארץ ישראל, ואולי מייסד מוסד הגאונים בא\"י. מופיע ברשימת נפטרים. בניו גאונים וראשי ישיבה, ונכדו יאשיה בן אהרן גאון ארץ ישראל.","bk":[["שפת יתר - להציל את הרס\"ג מהשגות דונש בן לברט, אבן עזרא - תנ\"ך",""],["אבן עזרא - תנ\"ך",""],["שפת יתר - להציל את הרס\"ג מהשגות דונש בן לברט",""]]},{"i":8613,"n":"בן מאיר, אהרן גאון","f":"משה","b":"גאון ארץ ישראל בשנים ד תרעה (915) - תרצב (932), ניהל מאבק עם הקראים בירושלים, אחד מאבות אבותיו ר מוסי \"נהרג בעזרה מתחת יד זרע ענן\", סבל רבות ואף היה חבוש בבית הסהר בגלל מחלוקת הקראים. הגיע לבגדד לגייס עזרה במלחמתו בקראים, היה מעורב במחלקות עם ר סעדיה גאון בענין קידוש החדש, כאשר בשנת תרפא חושב תאריך שונה לחג הפסח בין בבל לבין ארץ ישראל, ולאחר מכן גברו גאוני בבל (ועל כך חיבר רב סעדיה את ספר המועדים), מחבוריו נשארו 2 אגרות בענין זה. בניו: ר יאשיהו על מקומו אחריו, ר אברהם. מצאצאיו ר יאשיה גאון שהקים את הישיבה ברמלה בשנת ד'תשעה (1015)."},{"i":8614,"n":"בן מאיר, אהרן גאון מירושלים","f":"אברהם","b":"נכד ר אהרן בן מאיר גאון. ר\"מ בישיבה-ד'תשן. בניו: ר יאשיה - ר\"מ ברמלה, ר יצחק מישיבת רב יוסף הכהן גאון, רב מאיר - ראש הסדר במצרים."},{"i":8615,"n":"בן מאיר, אוהב","k":"אוהב בן מאיר הנשיא","b":"משורר, מחכמי ספרד"},{"i":8616,"n":"בן מאיר, יאשיהו","f":"אהרן","b":"מצאצי הגאון ר אהרן בן משה בן מאיר. חבר בסנהדרין הגדולה וראש ישיבת \"גאון יעקב\" בסוף תקופת הגאונים בארץ ישראל. הישיבה נדדה בשנים ד תשע (1010) - ד תשפ (1020), עקב רדיפות, מירושלים לרמלה ולעכו, חתום על מכתבי בקשת עזרה. חתימתו נמצאה על ספר פתרון ישעיה לר סעדיה גאון כבעלים."},{"i":8617,"n":"בן מאיר, יאשיהו","f":"אברהם","b":"אבד אצל הגאון ר יוסף בן שלמה הכהן, ראש ישיבת \"גאון יעקב\" אחר פטירת אביו, שימש כגאון בין השנים ד תש (940) - ד תשן (990) בערך."},{"i":8618,"n":"בן מבורך, יאשיה","b":"חכם כנראה מקדמוני תימן,עסק בתורת העיבור"},{"i":8619,"n":"בן מומו, יהודה","dp":"אופראן","b":"מצדיקי מרוקו,נשרף על קידוש ה'"},{"i":8620,"n":"בן מנואל, יהודה ממרוקו","b":"רב במוגדור-מרוקו-תרע."},{"i":8621,"n":"בן מנחם, יצחק מאיר מירושלים","f":"מנחם","k":"בעל פרשת המלך","r":"חתן הגרא\"ז מלצר","bt":"תרנח","dt":"תשכ - ז סיון","b":"עלה לארץ-תרפה, חבר הרבנות בפתח תקוה-תרצג, דיין בביה\"ד הגדול בירושלים-תשטז. פרסם מאמרים ב\"בית מדרש\" - תל אביב תשא, ב\"תבונה\" - ירושלים תשא-תשח, \"תורת ארץ ישראל\" - ירושלים תרץ.","bk":[["פרשת המלך",""]]},{"i":8622,"n":"בן מנחם, יצחק מפתח תקוה","b":"פרסם מאמרים ב\"תורת ארץ ישראל\" - ירושלים תרץ - ותשובה אליו מר יוסף דינקלס."},{"i":8623,"n":"בן מנחם, נפתלי (פריד)","b":"ביבליוגרף. פרסם מאמרים ב\"קבוצי אפרים\" - יאסי-בוקרשט תרעד."},{"i":8624,"n":"בן מצח, אברהם","b":"דיין בטוליטולה(ספרד)"},{"i":8625,"n":"בן מראד, אליהו","b":"מחכמי כורדיסטאן בעיר זאכו"},{"i":8626,"n":"בן נהוראי, ח' ג'רמון","k":"בעל צדקה לחיים","dt":"תקמא","dp":"תוניס","b":"חיבר \"צדקה לחיים"},{"i":8627,"n":"בן נון, אברהם אליהו מירושלים","f":"יעקב","dt":"תרמז - כ שבט","dp":"ירושלים","b":"מחכמי ירושלים, אחיו של ר יוסף רפאל בעל יאיר מבין. נפטר צעיר."},{"i":8628,"n":"בן נון, יהושע מצפת","b":"רב בצפת, הלך לדמשק אל ר חיים ויטאל שהיה כנראה רבו, להעתיק כתבי האר\"י. בשנת שס חותם בפסק עם ר יום טוב צהלון, מתשובותיו בספר \"זרע אנשים\", בשנת שכט חתם עם רבני צפת על תקנת הירושות. . נזכר ב\"עמק המלך\"."},{"i":8629,"n":"בן נון, יוסף רפאל מירושלים","f":"יעקב","k":"בעל יאיר מבין","bt":"תקצד או תקפה","bp":"ירושלים","dt":"תרסח (באו' תרמז","dp":"יפו","b":"מחכמי ירושלים, רב הקהלה הספרדית ביפו. חיבר \"יאיר מבין\" ירושלים תרסב. וכן פרסם ב\"המאסף\" לר בן ציון קואינקה. חתם שמו \"המבין\" (על שם ספרו)."},{"i":8630,"n":"בן נון, יעקב מירושלים","dt":"תרכג - טז שבט","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":8631,"n":"בן נון, יצחק","b":"קרובו של ר יהושע ן נון מצפת. נזכר בספר החזיונות לר חיים ויטאל."},{"i":8632,"n":"בן נון, מרדכי רפאל מירושלים","b":"מחכמי ירושלים, חתם על כתב הפשר עם האשכנזים-תרכד בדבר מנורת כסף שנשלחה לירושלים."},{"i":8633,"n":"בן נון, שמואל משלוניקי. דון","dt":"שטז - כה תמוז","dp":"שלוניקי","b":"מיוצאי ספרד, מחכמי שלוניקי."},{"i":8634,"n":"בן נפתלי - משפחה","b":"משפחת בעלי מסורה מארץ ישראל - בעלי מסורה שונה ממשפחת בן אשר."},{"i":8635,"n":"בן צבי, ישכר זאב מירושלים","k":"בעל יש שכר","b":"רב באפריקה, עלה לירושלים וכיהן כר\"מ בישיבת עץ חיים-תשי."},{"i":8636,"n":"בן ציון אברהם מירושלים","b":"מחכמי ירושלים, חתם בשנת תקסז על תעודה."},{"i":8637,"n":"בן ציון אריה הכהן משקוד","b":"דיין בשקוד"},{"i":8638,"n":"בן ציון הכהן מגרבה","b":"דומ\"צ בג'רבה-תר\"ע"},{"i":8639,"n":"בן ציון הכהן מוילנא","f":"ישראל משה הכהן","b":"מחכמי וילנא-תרך. אחיהם של ר בצלאל ור שלמה רבני וילנא. נפטר צעיר. חיבר הגהות לש\"ס ונדפסו בש\"ס וילנא."},{"i":8640,"n":"בן ציון כץ (כהנא) מוילנא","f":"שמואל","b":"רב בוילנא (אולי ראב\"ד), חתם-תלב על קיום צוואת ר משה ריבקש בעל באר הגולה."},{"i":8641,"n":"בן ציון מאוסטרהא","f":"יהושע","b":"רב באוסטרהא-שנות התק'."},{"i":8642,"n":"בן ציון מאוסטרובא","bt":"תרא","dt":"תרפו","b":"חסיד ר מנחם מנדל מקוצק - ובזקנותו נחשב לשריד האחרון לחבורה."},{"i":8643,"n":"בן ציון מבאהפאלי","f":"אהרן זאב","b":"פרסם מאמרים ב\"שמעתתי דרבנן\" - אודסה תרמז."},{"i":8644,"n":"בן ציון מביעלסק","b":"רב בביעלסק-תר\"כ"},{"i":8645,"n":"בן ציון מזלישטשיק","b":"מחכמי זלישטשיק - תשובה אליו \"בית שלמה\"-תריח."},{"i":8646,"n":"בן ציון מטישנישאצע","b":"מו\"צ בטישנישאצע-בסרביה-תר\"ע"},{"i":8647,"n":"בן ציון מטרשקין וירושלים","dt":"תרכה-ח -כא כסלו","dp":"ירושלים","b":"מו\"צ בטרשקין, עלה לירושלים."},{"i":8648,"n":"בן ציון מסערט","b":"רב בסרט-תרכ\"ז"},{"i":8649,"n":"בן ציון מקאלווריה","f":"אריה ליב","b":"פרסם מאמרים ב\"שמעתתי דרבנן\" - אודסה תרמז."},{"i":8650,"n":"בן ציון מקמינקא","f":"דוד מרבינו","k":"אדמור מקמינקא","b":"תלמיד הבעשט - אחד מ\"האחים הקדושים מקמינקא\". עלה לארץ. מתורתו ב\"שני המאורות\"."},{"i":8651,"n":"בן ציון מראסיין ווילקומיר","dt":"תרך","dp":"וילקומיר","b":"רב בראסיין, וילקומיר."},{"i":8652,"n":"בן ראובן, א' י' מירושלים","b":"פרסם מאמרים ב\"תבונה\" - ירושלים תשא-תשח."},{"i":8653,"n":"בן שבת, אברהם","f":"יעקב - יגל יעקב","bt":"תרב","bp":"מוגדור(מרוקו)","dt":"תרעז - ד טבת","dp":"חיפה","b":"מחכמי סאפי-מרוקו, ומראשי הקהלה ומושל ליהודים מטעם השולטן סידי מוחמד. עלה לארץ-תרנג והתישב בחיפה. חיבר ספרים - בכת\"י."},{"i":8654,"n":"בן שבת, יוסף מאופראן-מרוקו","f":"יעקב בן שבת","dt":"שסד","b":"נהרג עק\"ה ,רב שנת ש\"ה ,נטמן בין 50 הצדיקים במערה באופרן."},{"i":8655,"n":"בן שבת, יוסף מחיפה","f":"אברהם מחיפה","b":"נקרא ע\"ש בן משפחתו שנהרג עק\"ה באופראן. עבר למצרים, עורך \"ישראל\" בעברית בקהיר-תרפא."},{"i":8656,"n":"בן שבת, יעקב - הזקן","k":"בעל הנס","dp":"אופראן","b":"רב מקובל ומלוב\"ן. נהרג עק\"ה ונקבר בין חמשים צדיקים במערת אופראן. נכדו ר יעקב בן שבת מגיברלטר."},{"i":8657,"n":"בן שבת, יעקב מגיברלטר - הנכד","k":"בעל יגל יעקב","dt":"תריח - יט תשרי","dp":"ליזבואה","b":"מקובל, רב בגיברלטר. חיבר גם \"רוח יעקב\"."},{"i":8658,"n":"בן שבת, מסעוד מקזבלנקה וסוס","f":"יצחק","b":"רב בקזבלנקה, תארודנת(=תרודנת), סוס. חיבר שיר אזהרות בהלכות שחיטה."},{"i":8659,"n":"בן שבת, מרדכי יהודה","k":"בעל אדם קדמון","b":"מגדולי המקובלים"},{"i":8660,"n":"בן שבת, עזוז מאופראן","dt":"שפז","b":"מגדולי חכמי מרוקו,איש מופת. (במערת הצדיקים באופראן ליד מוגאדור)"},{"i":8661,"n":"בן שבת, שלמה ממרוקו","f":"אברהם","k":"בעל הלל גמור","b":"מקובל מחכמי תאמאנרת מנוף סוס-מרוקו - תפו. העתיק את \"מערת שדה המכפלה\" לר\"מ ן צור-תפו, וצירף הקדמה בשם \"הלל גמור\"."},{"i":8662,"n":"בן שבת, שמואל","f":"אברהם מחיפה","k":"בעל בסבך המקרא","b":"נקרא ע\"ש בן משפחתו שנהרג עק\"ה באופראן. עלה לארץ בילדותו, עסק בחינוך, מורה במסחה(=כפר תבור), חיפה. פעיל צבור, סופר בעתון \"החרות\". פרסם מאמרים בעתונים שונים. מדקדק וחוקר שפות המזרח."},{"i":8663,"n":"בן שבת, שמואל ממרוקו","f":"יעקב","dt":"תקנז","dp":"אופראן-מרוקו","b":"מחכמי מרוקו."},{"i":8664,"n":"בן שלום, אפרים","bt":"תרן","bp":"כוי סאנג'(כורדיסטאן)","dp":"אשקלון","b":"רבה של כוי סאנג', עלה לא\"י-תשי\"א, רב בטבריה, אשקלון"},{"i":8665,"n":"בן שלמה, חסדאי","b":"מגדולי דורו,רב וראש ישיבה בטודילה נבארה,עבר לולנסיה-קל\"ח"},{"i":8666,"n":"בן שלמה, יהודה מאלגיר","b":"רב בקצמטינא, העתיק והגיה את הלכות הרי\"ף-קה."},{"i":8667,"n":"בן שם, ראובן מבוצאץ","f":"יוסף","bt":"תרס","bp":"בוצאץ","dt":"תשם","b":"עלה לארץ-תרעט. מורה סופר וחוקר. יצא לאירופה ולמד בבימ\"ד לרבנים בוינה, עבר לפולין. ובזמן השואה היה מפקד בגיטו וארשא. ניצל ועלה לארץ שנית-תשה. ניהל גימנסיה ברמת גן."},{"i":8668,"n":"בן שמואל, אברהם"},{"i":8669,"n":"בן שמול, אברהם מארבאט","b":"סופר שטרות מחכמי ארבאט-שנות ה-תק'."},{"i":8670,"n":"בן שמול, אברהם מפאס","b":"רב בפאס, חתם-תנח על תקנה יחד עם ר מנחם סירירו, ר וידאל הצרפתי, היעב\"ץ, ועוד."},{"i":8671,"n":"בן שמול, אברהם מפאס","b":"נגיד בפאס-תנח ור סעדיה בן להבוז על מקומו אחריו-תעו."},{"i":8672,"n":"בן שמול, אפרים מראבאט","b":"מחכמי ארבאט(=ראבאט)-מרוקו-תקמב."},{"i":8673,"n":"בן שמול, יהודה ממרוקו","b":"שאלה אליו מקהלת פארו-פורטוגל-תרפח."},{"i":8674,"n":"בן שמול, יהודה מפאס","b":"סופר בי\"ד מחכמי פאס עם ר יוסף אשריקי, בזמן ר אליהו הצרפתי."},{"i":8675,"n":"בן שמול, יעקב מאלגיר","bt":"תקי","dt":"תקף - בערך","b":"מקובל רב ודיין בליידא(=בלידא)-אלגיר, אלגיר-העיר. תשובות ממנו ב\"גנזי שלום\" לר שלום שמעוני."},{"i":8676,"n":"בן שמול, יצחק מאלגיר","f":"מרדכי","bt":"תק","dt":"תקץ - בערך","b":"רב באלגיר-תקס."},{"i":8677,"n":"בן שמול, יצחק מפאס","b":"מחכמי פאס-תרט."},{"i":8678,"n":"בן שמול, מרדכי מאלגיר","f":"יצחק בן מרדכי","bt":"תקף","dt":"תרס - בערך","b":"רב ומשורר באלגיר. מעתיק ומגיה ספרים ובהם \"יוסיפון\" בערבית. אירח בביתו את ר יעקב אביחצירא (\"מעשה נסים\" ירושלים תשכח) וחיבר פיוט לכבודו."},{"i":8679,"n":"בן שמול, שמואל","b":"הראשון שידוע מבני המשפחה - נזכר ב\"יכין ובועז\"."},{"i":8680,"n":"בן ששת, זרחיה","b":"מגדולי ברצלונה-נ'"},{"i":8681,"n":"בן תיפא, אהרן","b":"מחכמי דמשק"},{"i":8682,"n":"בנבנטו, ברוך","k":"ברוך הרופא","b":"מקובל, רופא, אחרי הגירוש עבר מספרד לפיררה, נפולי-רס."},{"i":8683,"n":"בנבנישתי - משפחה","b":"משפחה מספרד ותורכיה."},{"i":8684,"n":"בנבנישתי דון, מאיר מספרד","b":"מחכמי שלוניקי, היה בעל ספריה עשירה. קרובו של דון שמואל בנבנשתי בעל הספריה \"מדרש שמואל\"."},{"i":8685,"n":"בנבנישתי הפייטן","f":"חייא","b":"פייטן בספרד."},{"i":8686,"n":"בנבנישתי הרופא מקושטא","b":"רופא ומקורב למלכות בקושטא-שמב, סייע לאחיו היהודים בקושטא, בבוסניה, ועוד."},{"i":8687,"n":"בנבנישתי משלוניקי","f":"שמואל יוסף משלוניקי","k":"שלוניקי","dp":"תרעב","b":"דיין וראב\"ד ועסקן צבור בשלוניקי-תרס. אחיו של ר יוסף שמואל משלוניקי."},{"i":8688,"n":"בנבנישתי, אברהם - הזקן מפורטוג","k":"דון אברהם בנבנשתי","b":"רב לכל מלכות קסטיליה-קצב, מקורב למלך אלפונס וצ\"ל יוהאן מספרד. כינס אסיפה של חכמי ספרד בואלי-אוליד-קצב, פעל להגן על היהודים בזמן עלילת הדם בעיר איסיגא יחד עם דון יוסף הנשיא ור שמואל ן שושן. (לפי אוצר הרבנים רב בשלוניקי, באוצר הגדולים נשאר בספרד). בניו: ר יהודה, ר יוסף על מקומו אחריו יחד עם ר יוסף בן ר שם טוב ור יצחק קנפנטון."},{"i":8689,"n":"בנבנישתי, אברהם - הנכד","f":"יוסף","bt":"קצג","bp":"ספרד","b":"מחכמי ספרד בזמן הגירוש. עבר לשלוניקי עם בנו ר יהודה. תמך בר יעקב ן חביב בעל \"עין יעקב\" שכתב עליו בהקדמה לספרו וסיפר שר יוסף אלבו בעל העיקרים דרש במסיבת ברית המילה של ר אברהם בספרד."},{"i":8690,"n":"בנבנישתי, אברהם מאזמיר","b":"גביר מחכמי אזמיר-שנות ה-ת', תמך בהדפסת \"לשון ערומים\" לר ברזילי יעבץ - יחד עם אחיו - יוסף."},{"i":8691,"n":"בנבנישתי, אברהם מאזמיר וי-ם","bt":"תרכב","bp":"אזמיר","dt":"תרצב - כה טבת","dp":"קושטא","b":"מורה בחברת כי\"ח בסמאקוף-תרמג, תונס-תרמז, מנהל הת\"ת באזמיר-תרנב, מנהל ביה\"ס כי\"ח בירושלים-תרסב, קושטא-תרסח וניהל את בתי הספר של כי\"ח."},{"i":8692,"n":"בנבנישתי, אברהם ממראקש","f":"יצחק","b":"רב במראקש-תצב."},{"i":8693,"n":"בנבנישתי, אברהם מקאשטוריאה","b":"דיין בקאשטוריאה-תע עם ר ישראל חזן ור מנחם בן חיים הכהן."},{"i":8694,"n":"בנבנישתי, בכור מסטרומיצה","b":"גביר בשלוניקי-תקסח."},{"i":8695,"n":"בנבנישתי, בן ציון מדרדנלים","f":"יהודה","b":"מחכמי יוון, אב\"ד בדרדנלים(=מגדלים). הדפיס ספר אביו \"זכר דבר\"."},{"i":8696,"n":"בנבנישתי, דוד","f":"יהודה","b":"מחכמי הדור-ר\"נ-ש'"},{"i":8697,"n":"בנבנישתי, דוד יעקב מירושלים","dt":"תרכ - יח אייר","b":"מגדולי רבני ירושלים"},{"i":8698,"n":"בנבנישתי, דוד ממצרים ותל אביב","bt":"תרנב","bp":"אזמיר","b":"עבר לאלכסנדריה, ממיסדי אגודת הספורט \"מכבי\", יסד חברה \"בני ציון\", עלה לארץ-תרעט התישב בתל אביב ועסק בפעילות ציבורית."},{"i":8699,"n":"בנבנישתי, דוד ממראקש","b":"רב ומו\"צ במראקש, חתם-תסט עם ר יעקב ן חיים, ר שלמה בן אברהם עמאר, ר יוסף ן סעדון."},{"i":8700,"n":"בנבנישתי, דוד משלוניקי","b":"רב בשלוניקי-שכ."},{"i":8701,"n":"בנבנישתי, דוד משלוניקי וירושלי","f":"שמואל","k":"בעל מורה דרך לסוריה","bt":"תרנז","bp":"שלוניקי","b":"עלה לארץ ועסק בחינוך, חוקר ארץ ישראל ופרסם מאמרים בנושא."},{"i":8702,"n":"בנבנישתי, וידאל מוינה","f":"אברהם מוינה","b":"גביר מראשי קהלת הספרדים בוינה-תקס בערך. סייע לר יהודה ן סיד בהדפסת ספרו \"נר מצוה\"."},{"i":8703,"n":"בנבנישתי, וידאל מספרד - א","f":"בנבשתי בן לביא","k":"בעל גרם המעלות?","b":"מחכמי ספרד, רופא, מראשי המדברים יחד עם ר' יוסף אלבו בויכוח עם המומר יהושע הלורקי - לפני האפיפיור בנדיקט - קיג או קעג. מיוחסים אליו הספרים: \"גרם המעלות\" ברפואה - שהעתיקו מלשון ערבית, \"קדש הקדשים\" - תשובות לטענות המומר הלורקי המכונה גראניסו די סנטה פה."},{"i":8704,"n":"בנבנישתי, וידאל מספרד - ב","f":"יוסף","b":"מרבני ספרד-ר\"נ"},{"i":8705,"n":"בנבנישתי, וידאל מספרד וקושטא","k":"בעל משלי אפר ודינה","b":"חכם מיוצאי ספרד מארגון שהתיישבו בקושטא, חיבר \"משלי אפר ודינה\" מליצה לפורים"},{"i":8706,"n":"בנבנישתי, וידאל משלוניקי","b":"גביר בשלוניקי. סייע בהדפסת \"מטה שמעון\" לר מרדכי שמעון-תקעד, \"באר המים\" לר יעקב מנשה-תקצו."},{"i":8707,"n":"בנבנישתי, חייא אברהם מירושלים","dt":"תרה","dp":"ירושלים","b":"מחכמי ירושלים"},{"i":8708,"n":"בנבנישתי, חיים - החבי\"ב","f":"ישראל מקושטא","k":"בעל כנסת הגדולה","bt":"שסג","bp":"קושטא","dt":"תלג - יג-ט אלול","dp":"אזמיר","b":"נכד(-אבי אמו) ר יהושע שונצינו. מגדולי הפוסקים בדורו, תלמיד ר צמח הנרבוני, ר יוסף סאמיגה, מהרימ\"ט - בישיבה שבבית ר יום טוב ן יעש. חתן הגביר ר דוד הכהן מאדרינופול, ובזיוו\"ש חתן נכדת ר שלמה הלוי משלוניקי. ממונה על איסור והיתר בקושטא-שפד(בגיל 21!), רב בתיריא(=טיריא)-תג, אזמיר-תיח, רב ראשי באיזמיר-תכו. בימי הש\"צ נטה קו והתפלג נגד הרב רבי אהרן לפפא (למעשה נטה - או העמיד פנים כנוטה - אחרי ש\"ץ בתחילת דרכו). חיבר \"כנסת הגדולה\" על הטור והשו\"ע, \"דינא דחיי\" על הסמ\"ג. גיסיו (-נשואים לאחיותיו) - ר אהרן ששון, ר שלמה וילייסיד, ואחייניו - ר אהרן ששון ור אברהם וילייסיד גדלו אצלו והיו תלמידיו."},{"i":8709,"n":"בנבנישתי, חיים יוסף מירושלים","b":"מחכמי ירושלים בזמן החיד\"א - תק בערך. הניח דרשות ושו\"ת - בכת\"י (במכון בן צבי)."},{"i":8710,"n":"בנבנישתי, חיים מאזמיר","r":"תלמיד של המהרי\"ט","bt":"שס\\ שסג","dt":"תלג - יט אלול","dp":"אזמיר","b":"מחכמי אזמיר.","bk":[["בעי חיי - שו\"ת",""],["כנסת הגדולה",""],["כנסת ישראל",""],["עץ הדעת - שו\"ת יו\"ד",""],["פסח מעובין",""],["שיירי כנסת הגדולה",""],["דינא דחיי",""],["חמרא וחיי – סנהדרין",""]]},{"i":8711,"n":"בנבנישתי, חיים ממראקש","b":"מו\"ץ במראקש. נפטר בן כ-110 שנה. בעל מופת."},{"i":8712,"n":"בנבנישתי, יהודה מירושלים","b":"מחכמי ישיבת \"יפאר ענוים\" בירושלים-תקיח."},{"i":8713,"n":"בנבנישתי, יהודה ממראקש","dt":"תקו - אחרי","b":"רב במראקש, בנו - ר שלמה, נזכר במכתב שנשלח אל בנו-תקו - והיה אז בחיים."},{"i":8714,"n":"בנבנישתי, יהודה מספרד ושלוניקי","f":"אברהם","bp":"טוליטולה","dt":"רעה - בערך","dp":"שלוניקי","b":"מגולי ספרד, ולאחר הגירוש רב בשלוניקי-רעב. \"אחד משלשת הרבנים עובדי עבודת הקדש\" יחד עם ר אליעזר השמעוני ור יוסף פאסי."},{"i":8715,"n":"בנבנישתי, יהודה משלוניקי","b":"מחכמי שלוניקי, רב בניקופול-שן בערך על מקום ר רפאל וינטורה."},{"i":8716,"n":"בנבנישתי, יהודה משלוניקי","k":"בעל זכר דבר","b":"מחכמי שלוניקי, רב בדרדנלים?. בנו - ר בן ציון מדרדנלים הו\"ל את ספרו - שלוניקי תרכג."},{"i":8717,"n":"בנבנישתי, יהודה משלוניקי","b":"מחכמי שלוניקי-שנות ה-ת'."},{"i":8718,"n":"בנבנישתי, יהושע רפאל מקושטא","f":"ישראל מקושטא","k":"בעל שדה יהושע","bt":"שנה","dt":"תל","b":"אחיו של ר חיים בעל \"כנסת הגדולה\". תלמיד ר יוסף טרני. מחכמי קושטא ואזמיר, ברושא-תב וחזר לקושטא. חיבר גם \"אזני יהושע\", \"לבוש מלכות\". נשאל והשיב ממקומות רבים ונאספו בספר \"שער יהושע\" (רוב הספר אבד בשריפה הגדולה-תך ורק חלק חשן משפט - שרד).","bk":[["שדה יהושע [על ירושלמי]",""]]},{"i":8719,"n":"בנבנישתי, יוסף בכור מירושלים","f":"רחמים שניאור","bt":"תר","bp":"ירושלים","dt":"תרעו - ט ניסן","dp":"ירושלים","b":"מחכמי ירושלים ודיין אצל ר יצחק טאג'ר, בשנת תרלד בשליחות, בתרמג בשליחות חברון, בתרמז בשליחות \"בית אל\" בהודו, ועוד. בשנת תרס ראש בית הדין של הספרדים בירושלים. בנו - ר סעדיה שהתישב בדרום אמריקה - החזיק בכתבי אביו."},{"i":8720,"n":"בנבנישתי, יוסף די שיגוביה מצפת","f":"משה","k":"בעל טעמי המצות","bp":"שלוניקי","dp":"שלוניקי","b":"עבר לאזמיר, עלה לצפת-שמ (לפי רוזניס עלה לצפת בילדותו) והיה מחכמיה. למד קבלה אצל האר\"י ולאחר מכן בבית המדרש של ר אלישע גליקו ור שמואל אוזידה. חיבר ספרים רבים בכתב יד, חיבר גם \"יכול יוסף\", כמה מכתביו בספר נכדו-בן בתו - ר שלמה אלגזי - \"דובב שפתי ישנים\" אזמיר תלא. בניו: דון וידאל, דון אברהם השני. (אולי המדובר בשני רבנים שונים האחד בן אברהם והשני בן משה)."},{"i":8721,"n":"בנבנישתי, יוסף יצחק מסופיה","dt":"תקעו - טו אב","dp":"סופיה","b":"רב בסופיה, בנו - ר יעקב שהיה דיין בסופיה-תקסז."},{"i":8722,"n":"בנבנישתי, יוסף מאזמיר","b":"גביר מחכמי אזמיר-שנות ה-ת', תמך בהדפסת \"לשון ערומים\" לר ברזילי יעבץ - יחד עם אחיו אברהם."},{"i":8723,"n":"בנבנישתי, יוסף מיאנינה","b":"מחכמי יאנינה-תעד."},{"i":8724,"n":"בנבנישתי, יוסף מירושלים","dt":"תרב - טז ניסן","b":"דיין בירושלים"},{"i":8725,"n":"בנבנישתי, יוסף מירקדו משלוניקי","b":"מחכמי שלוניקי-תרס."},{"i":8726,"n":"בנבנישתי, יוסף ממראקש","b":"רב במראקש-שנות ה-ת'-תק'. אולי הוא ר יוסף יעקב שחתם-תקמח עם חכמי אצווירא. בנו - ר ישראל בוריסא."},{"i":8727,"n":"בנבנישתי, יוסף משלוניקי","dt":"תקלט - אחרי","dp":"שלוניקי","b":"גביר בשלוניקי. סייע בהדפסת מחזור לימים נוראים-תקלט."},{"i":8728,"n":"בנבנישתי, יעקב בכור משלוניקי","dt":"תקעט","dp":"שלוניקי","b":"דיין בשלוניקי. נספד ע\"י ר יעקב מנשה ב\"עין המים\"."},{"i":8729,"n":"בנבנישתי, יעקב מאוילונה","b":"רב באוילונה-תן."},{"i":8730,"n":"בנבנישתי, יעקב מאזמיר","b":"מחכמי אזמיר-שנות ה-ת'."},{"i":8731,"n":"בנבנישתי, יעקב מירושלים","dt":"תקמט - יח טבת","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":8732,"n":"בנבנישתי, יעקב מסופיה","f":"יוסף יצחק","b":"דיין בסופיה-תקסז אצל ר חיים יעקב משה הלוי, יחד עם ר אלעזר נחמיאש."},{"i":8733,"n":"בנבנישתי, יעקב מראקסי-מרוקו","b":"מחכמי מרוקו, חיבר פירוש ומאמרים בכת\"י שהיה בידי משפחת אלבאז בצאפרו-מרוקו."},{"i":8734,"n":"בנבנישתי, יעקב משלוניקי","dt":"תרלז","dp":"שלוניקי","b":"גביר, פרנס וממונה על הצבור בשלוניקי."},{"i":8735,"n":"בנבנישתי, יעקב משלוניקי","b":"חתן הרופא דון יצחק בן שמואל אברבנאל. גביר מחכמי שלוניקי, הקים ספריה גדולה. בנו - ר שמואל, ונכדו - ר מאיר בעל \"אות אמת\"."},{"i":8736,"n":"בנבנישתי, יעקב משלוניקי","k":"בעל חוסן ישועות","dt":"תלה - יא חשון","b":"מחכמי שלוניקי-שנות ה-ת'."},{"i":8737,"n":"בנבנישתי, יצחק בכור משלוניקי","b":"גביר בשלוניקי. סייע בהדפסת \"ירך אברהם\" לר אברהם אישטרושה-תקעה."},{"i":8738,"n":"בנבנישתי, יצחק חיים מקאשטוריאה","b":"רב בקאשטוריאה-שנות ה-ת' לצד ר משה די מאיו-הנכד."},{"i":8739,"n":"בנבנישתי, יצחק מירושלים","dt":"תרעח - ח סיון","dp":"ירושלים","b":"שלם בדיעות,מגדולי ירושלים"},{"i":8740,"n":"בנבנישתי, יצחק מסרגוסה","f":"יוסף ן ברוך","k":"בעל ספר המאזניים","b":"מדקדק ומשורר מחכמי ספרד בדור הרביעי בסרגוסה ומלגה. חלמיד ר לוי בן יעקב ן אלתבאן. חברו של ר משה ן עזרא ור יהודה הלוי."},{"i":8741,"n":"בנבנישתי, יצחק מקאשטוריאה","f":"חיים","b":"דיין בקאשטוריאה-תע, עם ר מנחם בן חיים הכהן, ור יצחק אלבוכיר."},{"i":8742,"n":"בנבנישתי, יצחק מקאשטוריאה","b":"גביר מחכמי קאשטוריאה-שנות ה-תק'."},{"i":8743,"n":"בנבנישתי, יצחק משלוניקי","dt":"תקט","dp":"שלוניקי","b":"גביר בשלוניקי."},{"i":8744,"n":"בנבנישתי, יצחק משלוניקי","b":"מחכמי שלוניקי, ועסקן ציבור ופעל לטובת יהודי שכונת בארון הירש."},{"i":8745,"n":"בנבנישתי, ישראל מאזמיר - הנכד","f":"חיים - כנסת הגדולה","bt":"תד","bp":"טירייא(=תירייא)","dt":"תעד-פ - יח טבת","dp":"אזמיר","b":"רב בטיריא, אזמיר-תן על מקום אביו כ-40 שנה. בגיל !14 חיבר הקדמה לספר אביו \"כנסת הגדולה\"."},{"i":8746,"n":"בנבנישתי, ישראל מברוסה","k":"בעל כללים על הגט","b":"רב בברוסה-שנות ה-ת'. חיבר \"כללים על הגט\" ונדפס בסוף \"גט פשוט\"."},{"i":8747,"n":"בנבנישתי, ישראל ממראקש","f":"יוסף","b":"מחכמי מראקש."},{"i":8748,"n":"בנבנישתי, ישראל מקושטא","k":"בעל פרק בשיר","b":"רב בקושטא-שנות ה-ש'-ת'."},{"i":8749,"n":"בנבנישתי, ישראל מקושטא - הזקן","b":"מחכמי קושטא-ש\"פ, מוזכר בספר בנו - \"כנסת הגדולה\". אחיו של ר נסים מקושטא."},{"i":8750,"n":"בנבנישתי, ישראל מקושטא ב","f":"אליעזר בן ישראל","k":"בעל בית ישראל","b":"בן אחיו של ר חיים בעל \"כנסת הגדולה\". רב בקושטא-תכ. חיבר \"בית ישראל\". מתלמידיו - ר חיים הכהן בעל \"טור ברקת\"."},{"i":8751,"n":"בנבנישתי, מאיר מאזמיר","b":"מחכמי אזמיר-שנות ה-ת'."},{"i":8752,"n":"בנבנישתי, מאיר מירושלים","f":"שבתי","dt":"תקטו - ב אייר","dp":"ירושלים","b":"מחכמי ירושלים, דיין אצל ר נסים חיים משה מזרחי. חתם בשנת תקט על תקנת הרווקים בירושלים, חתם על כתב שליחות ר אברהם בן אשר ור יצחק זרחיה אזולאי. סייע בהדפסת ספריו של ר אליעזר נחום \"חזון נחום\" - קושטא תקג."},{"i":8753,"n":"בנבנישתי, מאיר מצפת","dt":"שיג - ה אלול","dp":"צפת","b":"ממגורשי ספרד שהגיע לצפת. תלמיד חכם ומקובל ועסק במסחר צמר והתעשר ותמך רבות בישיבות צפת בזמן ר יוסף קארו (כ-30 ישיבות)."},{"i":8754,"n":"בנבנישתי, מאיר משלוניקי","f":"שמואל בן יעקב","k":"בעל אות אמת","b":"מחכמי שלוניקי-שכ, מגיה ספרים וכתב\"י. חיבר \"אות אמת\" - שלוניקי שכה."},{"i":8755,"n":"בנבנישתי, מאסה מוינה","b":"גביר מראשי קהלת הספרדים בוינה-תקס בערך. סייע לר יהודה ן סיד בהדפסת ספרו \"נר מצוה\"."},{"i":8756,"n":"בנבנישתי, מרדכי מאדרינופול","b":"תלמיד ר אברהם גירון מאדרינופול. דיין באדרינופול-תקנה. חתם-תקעה עם ר יהושע גירון ור חיים הלוי. הו\"ל ספר רבו - \"אביר יעקב\"."},{"i":8757,"n":"בנבנישתי, משה מאוילונה","b":"רב באוילונה-תן."},{"i":8758,"n":"בנבנישתי, משה מאזמיר","f":"רפאל","b":"נתמנה לשליח-תקן בערך למסור ברודוס את הגט של המומר דניאל רולה."},{"i":8759,"n":"בנבנישתי, משה מצפת","k":"בעל שו\"ת","dp":"שלוניקי","b":"מחכמי שלוניקי, עלה לצפת בשנת שפ עם בנו ר יוסף, חיבר שות ונפטר בזמן שהדפיסים בשלוניקי."},{"i":8760,"n":"בנבנישתי, משה מקאשטוריה","b":"מראשי קהלת קשטוריאה(=קאשטוריה)-שנות ה-ש'."},{"i":8761,"n":"בנבנישתי, משה מקומירג'ינה","b":"רב בקומירג'ינה-תקנג."},{"i":8762,"n":"בנבנישתי, משה מקושטא","f":"נסים","k":"בעל פני משה","bt":"שסו-ח","bp":"קושטא","dt":"תלז","b":"נכד(-אבי אמו) ר אליהו בן חיים בעל שו\"ת ודרשות ראנ\"ח. תלמיד ישיבת ר שמואל ן וילייסיד. רב בקושטא-שץ, וראש ישיבת \"גברת\" שיסדה דונה חנה נשיא ודונה ריינה נשיא, בשנת תך נשרפה שכונת היהודים וגם הישיבה. חברו ובן דודו של ר חיים בנבנשתי בעל כנסת הגדולה. חיבר גם \"ריב לשונות. מתלמידיו - ר אליהו אלפנדרי בעל \"מכתב מאליהו\", ר אברהם ברודו בעל \"ברכת אברהם\", ר דניאל ג'יראסי בעל \"אודה ה'\"."},{"i":8763,"n":"בנבנישתי, משה משלוניקי","k":"בעל האגדות","dt":"של - אחרי","dp":"שלוניקי","b":"רב בשלוניקי."},{"i":8764,"n":"בנבנישתי, משה משלוניקי - ב","dt":"תרמה","dp":"שלוניקי","b":"רב בשלוניקי."},{"i":8765,"n":"בנבנישתי, משה משלוניקי וירושלי","f":"משה","bt":"תקע","bp":"שלוניקי","dt":"תרמה - יז טבת","dp":"ירושלים","b":"גביר מחכמי שלוניקי, עלה לירושלים-תקפט, ונאלץ לחזור לשלוניקי אחרי כ-3 שנים, ונדר שאם יצליח להשיג סכום קצוב שיאפשר לו להתפרנס בירושלים - יחזור ויעלה, ואכן לאחר כ-20 שנה קיים את נדרו ועלה שנית לירושלים-תריג. כיהן כגזבר הכוללות, וישב ב\"בית אל\", ולימים כיהן כראב\"ד - אך סירב לכהן כראשל\"צ. גיסו של ר שמעון מנשה. קינה לזכרו מר משה אוטולינגי."},{"i":8766,"n":"בנבנישתי, נסים מספרד","b":"מחכמי ספרד לפני הגירוש, התכתב עם ר יצחק די ליאון."},{"i":8767,"n":"בנבנישתי, נסים מקושטא","k":"חתן הראנ\"ח","b":"רב בקושטא-תי. חתן ר אליהו ן חיים-הראנ\"ח. בנו - ר משה בנבנשתי מקושטא. אחיו - ר ישראל מקושטא."},{"i":8768,"n":"בנבנישתי, נתן מירקדו משלוניקי","dt":"תרמד","dp":"שלוניקי","b":"רופא בשלוניקי."},{"i":8769,"n":"בנבנישתי, סעדיה מירושלים","f":"שניאור","bt":"תקלה","bp":"ירושלים","dt":"תר - כב ניסן","dp":"ירושלים","b":"מחכמי ירושלים, נכדו של ר סעדיה מרזוק מירושלים, הקים ישיבה-תקעב ועמד בראשה. בשנת תקצו חתם על מינוי ר יונה נבון לרבה של ירושלים."},{"i":8770,"n":"בנבנישתי, סעדיה מירושלים","f":"יוסף בכור מירושלים","bt":"תרלו","bp":"ירושלים","dt":"תשיז - ו אב","dp":"ירושלים","b":"רב בירושלים, ביירות-לבנון, רב בארגנטינה של קהילת קוריינטיס, חזר לירושלים-תרצז וכיהן כדיין."},{"i":8771,"n":"בנבנישתי, עזרא מירושלים","k":"בעל חנוך לנער","b":"עורך \"החבצלת\" - \"מבשרת ירושלים\" בלאדינו-תרלא, הו\"ל \"יהודית\" בפאריס. חיבר \"חנוך לנער\" בלאדינו - בלגרד תרך."},{"i":8772,"n":"בנבנישתי, עמנואל מאזמיר","dt":"תקנו - כא ניסן","dp":"אזמיר","b":"מחכמי אזמיר. נספד מאת ר נסים חיים שלום מרגונטו."},{"i":8773,"n":"בנבנישתי, צ' רבנו מירושלים","k":"רבנו ן בנישתי","b":"מראשי החברא קדישא-תריד בירושלים."},{"i":8774,"n":"בנבנישתי, רחמים שניאור","dt":"תריא","dp":"אלכסנדריה","b":"מחכמי ירושלים, בשנת תריא בשליחות בצפון אפריקה ונפטר בדרכו, נספד על ידי השליח ר אהרן אזריאל בספרו \"מקוה מים\"."},{"i":8775,"n":"בנבנישתי, רפאל יצחק משלוניקי","f":"מאיר","k":"בעל מעם לועז - רות","dt":"תרע","dp":"שלוניקי","b":"מחכמי שלוניקי, ונטה להשכלה. תרגם ללאדינו \"דגל התורה\" לר משה אוטולינגי. מנהל ביה\"ס ת\"ת."},{"i":8776,"n":"בנבנישתי, רפאל מאזמיר","dt":"תקלה - ז אד\"א","dp":"אזמיר","b":"מחכמי אזמיר."},{"i":8777,"n":"בנבנישתי, שלמה בכור מאזמיר","f":"דוד","b":"רב באזמיר. נספד ב\"דרוש אברהם\"."},{"i":8778,"n":"בנבנישתי, שלמה מאישקופיה","b":"גביר מראשי קהלת אישקופיה-תן, ברח לקושטא בזמן הכיבוש האוסטרי."},{"i":8779,"n":"בנבנישתי, שלמה ממראקש","f":"יהודה","b":"מו\"ץ במראקש, חתם-תקו על פס\"ד."},{"i":8780,"n":"בנבנישתי, שלמה ממראקש","b":"מחכמי מראקש, חתם-תעה על פס\"ד עם ר דוד בנבנישתי, ר אברהם מאמאן."},{"i":8781,"n":"בנבנישתי, שלמה מקושטא","b":"רב בקושטא - בשנים תק-תקן."},{"i":8782,"n":"בנבנישתי, שמואל יוסף משלוניקי","dt":"תרעב","dp":"שלוניקי","b":"ראב\"ד בשאלוניקי-תרמב כשלושים שנה. כל כתביו אבדו בשריפה."},{"i":8783,"n":"בנבנישתי, שמואל מספרד","f":"יעקב","k":"בעל אורך ימים","b":"מחכמי ספרד, חיבר ספר מוסר \"אורך ימים\" שתורגם במשך השנים ללשון אשכנז ולערבית. תרגם ספר נחמות הפילוסופיה, וספר רפואות לרמב\"ם. חיבר ספרים על חכמת הדקדוק (די רוסי)."},{"i":8784,"n":"בנבנישתי, שמואל מספרד ושלוניקי","f":"מאיר","b":"מחכמי ספרד, ובזמן הגירוש עבר לשלוניקי. מחכמי שלוניקי ובעל ספריה גדולה שכונתה מדרש ר שמואל בנבנשתי. היה ברשותו שו\"ת הרשב\"א בכת\"י והמהרשד\"ם השתמש בו בפסקיו. ונשרף-שה בזמן הדלקה הגדולה בשלוניקי, חכמי שלוניקי התאבלו על האבדה וחיברו על כך פיוטים וקינות. גם לקרובו דון מאיר בנבנשתי היתה ספריה גדולה."},{"i":8785,"n":"בנבנישתי, שמואל מקושטא","b":"נזכר ב\"אזני יהושע\" ו\"בית ישראל\" לר יהושע בנבנישתי."},{"i":8786,"n":"בנבנישתי, שמואל משלוניקי","b":"מגדולי חכמי שאלוניקי,עלה לירושלים-תרצ\"ב"},{"i":8787,"n":"בנבנישתי, שמואל משלוניקי","f":"טודרוס","dt":"שטו","dp":"שלוניקי","b":"מחכמי שלוניקי. אולי קרובו של ר שמואל בעל הספריה הגדולה."},{"i":8788,"n":"בנבנישתי, שמואל משלוניקי","f":"יעקב","b":"נכד(-אבי אמו) הרופא דון יצחק בן שמואל אברבנאל. גביר מחכמי שלוניקי. בנו - ר מאיר בעל \"אות אמת\"."},{"i":8789,"n":"בנבנישתי, שמעון","b":"נזכר בהקדמה ל\"יוסיף דוד\" לר דוד בן שמואל מועטי."},{"i":8790,"n":"בנבנשתי די שיגובה, יוסף מצפת","f":"אברהם","b":"מקובל,מחכמי צפת-ש\"מ. (יש בלבול בין שני חכמים - האחד בן ר אברהם והשני בן ר משה)."},{"i":8791,"n":"בנבנשתי די שיגובה, משה","b":"גדול בנגלה ונסתר בשיגוביה-שנת ש'. תלמיד חבר לר אהרן מטרני - דוד של המבי\"ט מאדריאנופול, והיה עוזר לו ברבנות. התגורר אצל הגביר ר שבתי ויריאוטי בקושטא. רוב כתביו אבדו ומתורתו בקבצי מחכמי דורו. בנו ר יוסף היה מתלמידי הארי בצפת, ונכדו - ר שלמה אלגזי"},{"i":8792,"n":"בנבנשתי משה בן נסים","bt":"1606","dt":"ה'תלז 1677","bk":[["פני משה",""]]},{"i":8793,"n":"בנגיס, זליג ראובן מליטא וירוש","f":"צבי הירש","k":"בעל לפלגות ראובן","bt":"תרכד-ז","bp":"שניפישוק","dt":"תשיג - ז סיון","dp":"ירושלים","b":"נכד ר אהרן ברוידא-ב מקלוואריה. תלמיד ישיבת וולוזין. חתן ר חיים צבי ברוידא משועקשנא. רב בבודקי-(=באדקי)-פלך גרודנא-תרנד, קאלוואריה-תרעב, סמולנסק, הוזמן-תרסח לכהן כרבה של ירושלים אך לא הסתייע, וכיהן כרב לעדה החרדית בירושלים-תרצח. בנו ר שמעון זאב. פרסם מאמרים ב\"הבאר\" - זאמושץ-וארשא - תרפד, \"הפלס\" - ברלין תרסא-תרסה, \"פרי עץ חיים\" - טלז תרצט - קובץ תלמידי ישיבת טלז, \"קול תורה\" - ירושלים תרץ, \"שערי ציון\" - ירושלים תרפא, \"תבונה\" - ירושלים תשא, \"תורת ארץ ישראל\" - ירושלים תרץ."},{"i":8794,"n":"בנגיס, יהודה אידל חיים מליבויא","f":"צבי הירש","bt":"תרכב","b":"רב בליבוי החדשה-קורלנד-תרנט. אחיו של ר זליג ראובן מירושלים."},{"i":8795,"n":"בנגיס, שמעון זאב מקאלווריה","f":"זליג ראובן","b":"רב בקאלוואריא-תרפ על מקום אביו. עורך \"חכמי ליטא\" - קלואריא תרמה, \"הנצח\" - לבוב תרפז."},{"i":8796,"n":"בנדגור, ישראל עקיבא מלובלין","b":"מו\"צ בפניעוונא-פולין, דיין ומו\"צ בלובלין-תרצה בביה\"מ בעלז."},{"i":8797,"n":"בנדו, אלעזר","dt":"תקנ - י טבת","b":"רב בבומסלא"},{"i":8798,"n":"בנדט מקרוז'","b":"גיסו של ר ישעיה מסלנט שהיה דיין בקרוז'. חתן ר אליהו בן מאיר מקרוז'-גיסו של הגר\"א. רב בקרוז' על מקום גיסו, וגיסו ר יעקב על מקומו אחריו. בניו: ר יצחק קראזר מואיגובה, ר יהושע השל אליאשזון משאקי יאנובה ונקרא - \"ראש הברזל\". בתו שרה צירל - למדנית ידועה ובעל ר איזיק מגדולי התורה בוילנא וקרוז'."},{"i":8799,"n":"בנדטזון, מנחם מנוש","k":"בעל הגיון לעתים","bt":"1817","bp":"גרודנא","dt":"1888","dp":"גרודנא","b":"סופר ומחבר בליטא. חיבר גם \"המוסר או אחרית רשע\" - ברסלוי תרז, \"אבן בוחן\" וילנא תרטז, ועוד."},{"i":8800,"n":"בנדטמן, יעקב מבויסק ושאוולי","f":"יהודה בן שמואל חסיד","k":"בעל זכרון יעקב","bp":"ראסיין","dt":"תרכא - כז אדר","b":"נתייתם בגיל צעיר וגדל אצל זקנו ר שמואל חסיד מראסיין-תלמיד הגר\"א. תלמיד דודו - ר אליהו קליקאלער-פילטענער. רב בניישטאט-טאווריג(=סיגינד) על מקום ר שלמה זלמן בן אליהו בן אברהם-אחי הגר\"א, שאוולי, בויסק-תקצא למעלה מ-30 שנה. הניח חדושים בכת\"י ובהם מביא שמועות ומעשים מהגר\"א מפי זקנו, נכדו - ר יהודה לוקגייצקי (ליקנייצקי?) הו\"ל מכתביו את הספר \"זכרון יעקב\" וילנא תרלד. חיבר גם \"תורת חסידים\" - ובו מתורתם של שלושת חסידי ראסיין בזמן הגר\"א שהיו ידועים בשם \"אגודת חסידים\" (ושאחד מהם - ר שמואל היה זקנו), והם: ר שמואל מראסיין, ר משה מטלז, ור מרדכי מפוקרוי. חתניו - ר אלכסנדר משה לפידות מרסיין, ר שמואל צבי הרץ לוקניצקי מזאגר ומיטאווי, ר דוד בן אברהם אבלי מזאגר, ר ישראל ליב ממיטאווי, ר אליעזר דב רוטנברג מוילקוביסק. (באוצר הרבנים נרשם כחתנו של ר שמואל חסיד ולא נכדו). חברו - קרובו - ר אליהו רגולר."},{"i":8801,"n":"בנדיגר, משה מפרשבורג","b":"מורה בביה\"ס של קהלת פרשבורג-תקפה."},{"i":8802,"n":"בנדיגר, שלמה מפרשבורג","b":"מורה בביה\"ס של קהלת פרשבורג-תקפה."},{"i":8803,"n":"בנדיט","b":"תשובה אליו ממהרם פדובה."},{"i":8804,"n":"בנדיטו, יוסף","f":"משה","b":"נזכר בכלבו בשם \"שין בנדיטו\", נזכר ב\"ארחות חיים\"."},{"i":8805,"n":"בנדינר, משה מפרשבורג","b":"תלמיד הנודע ביהודה, משכיל ומנהל ביה\"ס הלאומי בפרשבורג-תקסה - דתי אך החרדים התנגדו לו ולבית ספרו."},{"i":8806,"n":"בנדיקט בנט, יעקב גרשון מביטשקע","f":"אליהו","bt":"תרז","bp":"אויבן","dt":"תרעה - כד תשרי","dp":"פרשבורג","b":"תלמיד הכת\"ס, ודודו ר יעקב צבי ניימן מוראדיש. חתן ר גבריאל אבלס מסעדרוהל וישב אצלו. רב בביטשקע. בזיוו\"ש חתן דודו ר ליב בנט משטאמפען. רב בפעטראווסלע, פרשבורג-תרעה. הניח כת\"י מחדושי רבו הכת\"ס. בנו ר אליעזר בנדיקט מפרשבורג."},{"i":8807,"n":"בנדיקט, אליעזר שלמה מפרשבורג","f":"יעקב גרש' בנדיקט-בנט","bt":"תרלט","bp":"ביטשקע","dt":"תרצט - ח אלול","dp":"פרשבורג","b":"תלמיד השב\"ס, ור יצחק שוויגר מטאפלטשן. חתן ר יחיאל הכהן קליין מוינה-צעהלים. גיסו של ר יהודה סופר מאראד. מחכמי גאלאנטא, פרשבורג-תרסו ושימש כגבאי הת\"ת ומראשי הקהלה."},{"i":8808,"n":"בנדיקט, אשר עמנואל למל","b":"רב במטרסדורף. גיסו וחתנו של ר יצחק אהרן פדרווייס מסערדאוהל. זקנו של ר בנימין זאב מחיפה. פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":8809,"n":"בנדיקט, בנימין זאב מחיפה","f":"שמואל יוסף מוינה","bt":"תרעג","bp":"וינה","dt":"תשסב -- כב סיון","dp":"חיפה","b":"תלמיד הדעת סופר, וישיבת בית מאיר בקראקא. חתן ר צבי קופשטוק משדה לבן. רב בוינה, עלה לארץ-תרצט, דיין באמשטרדם-תשיג, אב\"ד האג-תשטז. רב שכונת אחוזה בחיפה-תשיח."},{"i":8810,"n":"בנדיקט, שמואל יוסף מוינה","f":"אשר עמנואל למל ממטרס","b":"רב החרדים במחוז התשיעי בוינה. בנו ר בנימין זאב מחיפה."},{"i":8811,"n":"בנדס, לואי מליטא וניו יורק","k":"בעל דאס אלטע און...","bt":"1866","bp":"וילנא","dt":"1927","dp":"ניו יורק","b":"עתונאי. ברח מליטא בגלל פעילותו המהפכנית והיגר לניו יורק. יסד את \"די ארבייטער צייטונג\" השבועון המרכסיסטי הראשון באידיש בארה\"ב. למד רפואה בברלין וחזר לניו יורק, יסד את העתון \"פארווערטס\", \"ווארהייט\", ועוד. חיבר \"דאס אלטע און נייע פאלצסטינע\", \"דער מוסר\" נ\"י תרעד."},{"i":8812,"n":"בנדר, אברהם","b":"תלמיד ר אברהם חזן-בנו של ר נחמן מטולצ'ין. ממנהיגי חסידות ברסלב."},{"i":8813,"n":"בנדר, אלפרד מדרום אפריקה","f":"פיליפ","bt":"תרכד","bp":"דבלין-אירלנד","b":"למד בקיימבריג'-אנגליה. רב בקייפטאון-דרום אפריקה-תרנב, ועסקן צבורי ודרשן."},{"i":8814,"n":"בנדר, דוד מארה\"ב","b":"פרסם מאמרים ב\"המתיבתא\" - נ\"י תשג."},{"i":8815,"n":"בנדר, לוי יצחק מירושלים","b":"מחשובי חסידי ברסלב. תלמיד ר אברהם הלוי חזן. חיבר \"שיח שרפי קדש\"."},{"i":8816,"n":"בנוביץ, יצחק אייזק","b":"רב בעגערסעג-תקס\"ג"},{"i":8817,"n":"בנויניטו, עמנואל ממנטובה","f":"יקותיאל","k":"בעל לוית חן","b":"מחכמי מנטובה, ונציה. רב בבנויניטו. תלמיד ר משה בסולה מפיזרו. חתנו - ר משה עבאסי. חיבר גם ספר על סדר הדורות, והו\"ל \"תיקוני הזהר\"."},{"i":8818,"n":"בנוסבסקי, אריה ליב","b":"פרסם מאמרים ב\"כנסת ישראל\" - וילנא תרץ."},{"i":8819,"n":"בנזימן, יצחק איזיק מונדזיגולה","bp":"ונדזיגולה","b":"היגר לקנדה - שו\"ב במונטריאול."},{"i":8820,"n":"בנט, אברהם","f":"יהודה אשכנזי","b":"תר\"כ"},{"i":8821,"n":"בנט, אברהם אבר ממרגא","f":"יעקב מאויבן","dt":"ב שבט","b":"רב במרגא."},{"i":8822,"n":"בנט, אברהם אברל מניקלשבורג","f":"מרדכי בנעט יפה","b":"רב בפוזנא,דיין בניקלסבורג-ת\"ק"},{"i":8823,"n":"בנט, אדוארד יחזקאל מברלין","f":"ירחמיאל דוד או ברוך","k":"בעל ר שמואל הנגיד","bt":"תרטו","bp":"ליפטא-סט מיקלוש","b":"תלמיד הכת\"ס בפרשבורג, ביהמ\"ד לרבנים בברלין. רב בקרוטשין-תרמד, ר\"מ בביהמ\"ד לרבנים בברלין-תרנז. חיבר גם \"מקור הפרושים והצדוקים\", ועוד."},{"i":8824,"n":"בנט, אשר מבאגעדא","f":"משה מגיירינג","b":"אביו של ר מרדכי מאיר משטיינמאנגר."},{"i":8825,"n":"בנט, ברוך מאיר מאושפיצין","b":"תלמיד ישיבת רדמוסק באושפיצין. פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט, \"כתר תורה\" - אושפיצין תרצט."},{"i":8826,"n":"בנט, גרשון וולף מאונגואר","f":"משה מניירינג","dt":"תרסט","b":"חתן ר שלמה גנצפריד מאונגואר. דומ\"צ באונגוואר, וראב\"ד על מקום חותנו. מתורתו ב\"בית הלל\". בנו - ר יחזקאל מס' ואראהל."},{"i":8827,"n":"בנט, דב בריש אברהם מקאליב","f":"ישעיה מקאליב","bt":"תקפד","dt":"תרסב","b":"רב בקאליב(=קאלוב)-תרכו וראש ישיבה על מקום אביו, ור מנחם ברוידא על מקומו אחריו. נזכר בשו\"ת \"יד יצחק\"."},{"i":8828,"n":"בנט, יהודה אריה ליב מקלושעק","b":"פרסם מאמרים ב\"כרם בית שמואל\" - פיעטרקוב תרצב - כתב עת תלמידי ישיבת אלכסנדר."},{"i":8829,"n":"בנט, יוחנן מאויבן","f":"אברהם מניקלשבורג","dt":"תקלט","dp":"בודפשט","b":"דיין באויבן(=בודפשט) אצל ר נתן בן מתתיה. בנו - ר יעקב."},{"i":8830,"n":"בנט, יוסף יוחנן","f":"מרדכי ליב","b":"תלמיד ר מאיר א\"ש מאוגוואר."},{"i":8831,"n":"בנט, יוסף יוחנן מקאליב","f":"יעקב מאויבן","dt":"תקפב-ג - ט כסלו","b":"תלמיד ר יצחק איזיק טויב מקאליב, ועל מקומו אחריו. רב בקאליב-תקפא. (במורשת הונגריה נרשם - נשטר תקפה) ור ישעיה בנט על מקומו אחריו. אחיו של ר יחזקאל מנייטרא."},{"i":8832,"n":"בנט, יחזקאל מוואראהל","f":"גרשון בנימין זאב","k":"בעל משיב טעם","bt":"תרכא-ג","bp":"אונגואר","dt":"תרעג - א סיון","dp":"סינער-ואראלי","b":"נכד ר שלמה גנצפריד שהיה גם רבו, תלמיד השב\"ס, ר חיים צבי מאנהיימר, ר אהרן פריד מבסרמין בעל שו\"ת מהרא\"ף. שימש בדיינות אצל זקנו באונגוואר. חתן ר אברהם יצחק גליק מטאלטשווא בעל \"יד יצחק\", דיין בטאלטשווא-תרמד אצל חותנו. רב וראש ישיבה בוואראהל(=סינער-ווארלי-וארול)-תרמט וחתנו ר ישכר דב הלוי על מקומו אחריו. מכתביו נדפס \"משיב טעם\", חיבר הקדמה ל\"שם שלמה\" ובו תולדות זקנו. פרסם מאמרים ב\"דבר בעתו\" - פאקש תרסט, \"כנסת חכמים\"- בורגו-פרונד - ס. וואראהל תרסה, \"מגד ירחים\" - סיגט תרנח. בנו - ר שלמה - הו\"ל \"שם שלמה\" לזקנו ר שלמה גנצפריד."},{"i":8833,"n":"בנט, יחזקאל מפאקש ונייטרא","f":"מרדכי או יעקב מאויבן","dt":"תרטו - ו-ז טבת","dp":"נייטרא","b":"רב בסעטשין, ראב\"ד בפאקש-תקפח, רב בנייטרא. היה בקשרי שו\"ת עם החת\"ס. מאמר ממנו ב\"הנשר\" - טירנוי תרצג-תשד, נזכר בשו\"ת הים. אחיו - ר משה מרדכי משטמפן."},{"i":8834,"n":"בנט, יעקב אברל מניקלשבורג","f":"מרדכי מניקלשבורג","k":"בעל גדולת מרדכי","bt":"תקלו","bp":"ניקלשבורג","dt":"תרכה","dp":"ניקלשבורג","b":"ספרא רבה ודומ\"צ בניקלשבורג. הו\"ל ספר אביו \"מגן אבות\". רשם בכת\"י את דרשות אביו בשם \"שבתות השנה\" (ונדפסו בהוצאת \"מכון ירושלים\")."},{"i":8835,"n":"בנט, יעקב מאויבן","f":"יוחנן","dt":"תקעב - טז אב","dp":"בודפשט","b":"דיין באויבן בזמן ר משה מינץ - וישב בדינו של ר אהרן חורין. בניו: ר מרדכי משטמפן, ר יוסף יוחנן, ר יחזקאל מנייטרא, ר אברהם אבר ממרגא. נכדו - ר יחזקאל מפאקש, חתנו - רב בראדוואני-מחזן גראן. (באוצר הרבנים תאריך פטירתו - תקפז - ו אלול)"},{"i":8836,"n":"בנט, ירחמיאל דב בריש מליפטא","f":"יחזקאל","bt":"תקעה","bp":"סעטשין","dt":"תרלז - ה תשרי","dp":"ליפטא","b":"תלמיד החת\"ס. חתן ר דוד שטסל מליפטא ועבר לשם. רב בקהלה החרדית בליפטא-סענט-מיקלאש, חתנו ר שלמה גרסטל על מקומו אחריו."},{"i":8837,"n":"בנט, ישעיה מקאליב","f":"מרדכי מניקלשבורג","bt":"תקנג","dt":"תרכו - יט כסלו","b":"חתן בעל שמן רוקח. רב בנאכוד, מיסליץ, קאליב וגליל סאבאלטש-תר על מקום קרובו ר יוסף יוחנן, ובנו ר בריש אברהם על מקומו אחריו. חתן ר אלעזר לעוו מסנטוב בעל \"שמן רוקח\". תמך במרד ההונגרי-1848 ושכנע את בני קהלתו לתמוך במרד. התנגד להקמת ביהמ\"ד לרבנים הניאולוגי בבודפשט והיה במשלחת הרבנים אל המלך פרנץ יוזף הראשון בענין זה - יחד הכת\"ס, ר יהודה אסאד, ועוד. חתנו - ר יצחק גליק מטולטשווא."},{"i":8838,"n":"בנט, מנחם מנדל","f":"מרדכי","dt":"תקנו - כב כסלו","dp":"קראלי"},{"i":8839,"n":"בנט, מנחם מנדל מפאקש","dt":"תרכ - כז אייר","b":"דומ\"צ בפאקש"},{"i":8840,"n":"בנט, מרדכי מאיר בנדיקט משטינמג","f":"אשר למל מבאגעדא","bt":"תריח","bp":"באגעדא","dt":"תשד - יז תמוז","dp":"אושוויץ","b":"תלמיד השב\"ס, ור יואל פלנדר באויהל. מחכמי מיאווע-תרמט לאחר נישואיו לשם (לבית ברודא), רב ביאקא-תרנז, שטיינמנגר-תרנח. נספה בשואה."},{"i":8841,"n":"בנט, מרדכי מניקלשבורג","f":"אברהם בנעט","k":"בעל פרשת מרדכי","bt":"תקיג","dt":"תקפט - יג אב","dp":"קרלסבד - ניקלשבורג","b":"תלמיד ר משלם איגרא. פוסק, גדול חכמי דורו, איש מופת, קרוב למלכות, רב בלונדנבורג, שוסבורג, רב המדינה בניקלשבורג-תקן. השתתף במשלחת אצל הקיסר-תקנא יחד עם ר קופל טעבן - בענין גזירת הגיוס לצבא. בנו - ר יעקב אבריל הו\"ל את ספרו \"מגן אבות\", וחיבר ספר \"גדולת מרדכי\" על אביו."},{"i":8842,"n":"בנט, משה מגיירינג ומלאצקי","f":"מרדכי משטמפן","dp":"מלצקי","b":"אחר חתונתו ישב בשטמפן, רב בגיירינג, מלצקי(=מאלאצקה)-תרל. בנו - ר גרשון וולף-חתן ר שלמה גנצפריד."},{"i":8843,"n":"בנט, משה מרדכי מאויבן ושטמפן","f":"יעקב מאויבן","bt":"תקלג-ח","dt":"תרי - ד כסלו","b":"חתן הגביר ר גרשון הכהן שטרן מבאטארקס. דיין באויבן על מקום אביו, רב בסעטשין-תקסח, יארמוט, שטמפן-תקעה. בניו - ר יחזקאל מפאקש, ר משה מניירינד וסלוצקי. חתנו - ר אהרן צבי ניימן מוראדיש. הסכים על \"בית יעקב\" לר יעקב ויילר, \"אמונת ישראל\" לר שמואל בן ציון הנדלר. בניו: אברהם, יוחנן, משה, יחיאל, ליב, שלמה, שמואל, יוסף, יעקב, אליהו. חתנו - ר יעקב הרש ניימאן."},{"i":8844,"n":"בנט, נפתלי משאפי","f":"מרדכי בנט","k":"בעל ברית מלח","bt":"תקמט","dt":"תריח - ב טבת","b":"רב בשאפא(=שאפי)-תקצו. חיבר \"אבל כבד\"-תר - ובו הספד על החת\"ס."},{"i":8845,"n":"בנט, שלמה","f":"יחזקאל מוארהאל","k":"הו\"ל שם שלמה","b":"נינו של ר שלמה גנצפריד, הו\"ל \"שם שלמה\" לזקנו. מוהל."},{"i":8846,"n":"בנט-יפה, מרדכי מניקלשבורג","f":"יום טוב יפה","dt":"תפה","b":"דיין בניקלסברג"},{"i":8847,"n":"בני משה - ישיבה בירושלים","b":"ישיבה בירושלים, נוסדה מאת ר משה זעפרן מאלגיר-שנות ה-תק'."},{"i":8848,"n":"בניאל, משה מאלכסנדריה","b":"מחכמי אלכסנדריה - שנות ה-ש', בזמן ר חיים חברייא."},{"i":8849,"n":"בנידיט, ברוך מבאסאן","k":"ר' ברוך מבאסאן","b":"מחכמי איטליה, אב\"ד ור\"מ בוירונה-שפ\"א"},{"i":8850,"n":"בניה הסופר מתימן","f":"סעדיה","k":"בנאי","b":"מחכמי תימן, סופר אמן-רל\"ד"},{"i":8851,"n":"בניהאד, דוד מרדכי מאפטא","dt":"תשד","b":"ראב\"ד באפטא"},{"i":8852,"n":"בניהאד, זאב וולף מסערדאוהל","b":"ראב\"ד בסערדאהעל-תר\"כ"},{"i":8853,"n":"בניהאד, שלמה זלמן מפרשבורג","k":"בעל מנחה טהורה","r":"ראב\"ד דק\"ק קיצע, ופרשבורג, תלמיד החתם סופר ומהר\"ם אש","dt":"תריח - ו תשרי","dp":"פרשבורג","b":"תלמיד החת\"ס, ור מאיר א\"ש. רב בקיצע, דיין בפרשבורג-תקצא על מקום ר משה טריטש, בזיוו\"ש חתן ר שמואל דייטש מפרשבורג בעל \"עבודת הקרבנות\". ראב\"ד בפרשבורג-תרו על מקום ר דניאל פרוסטיץ.","bk":[["מנחה טהורה – מנחות",""]]},{"i":8854,"n":"בניט, שם טוב מאלגיר","bt":"קע - בערך","dt":"רן - בערך","b":"מחכמי בג'איה-אלגיר. נזכר בשו\"ת הריב\"ש."},{"i":8855,"n":"בניינו בן יהוידע, קבור בביריה ליד צפת","dt":"א אדר"},{"i":8856,"n":"בנימין","k":"ר' בנימין בעל שם","b":"מגדולי הראשונים,מקובל,פייטן-ד'תתנ\"ו. חיבר יוצרות ולסליחות"},{"i":8857,"n":"בנימין","f":"בעל כתנות אור","b":"תשובות ממנו בספר אביו - \"כתנות אור\"."},{"i":8858,"n":"בנימין","k":"בעל פי שנים"},{"i":8859,"n":"בנימין אהרן חריף מטיקטין","b":"רב בטיקטין-שמז. חתם על כרוז ועד ד ארצות-שמז - שלא לקנות רבנות בכסף."},{"i":8860,"n":"בנימין אליהו מזלושין","b":"אב\"ד זאלשין. מרבני חסידי אלכסנדר. פרסם מאמרים ב\"בית ישראל\" - \"בית שמואל\" - לודז תרץ."},{"i":8861,"n":"בנימין אריה ממיקוליב","f":"שמחה","b":"מחכמי מיקוליב. תשובה אליו ב\"שם אריה\"."},{"i":8862,"n":"בנימין בונם מקראקא","b":"חתן ר יהודה ליב מראקוב. פרנס ור\"מ דגליל קראקא-תק."},{"i":8863,"n":"בנימין בושקא מזאמושט","f":"יעקב לודמיר","b":"נכד ר אריה יהודה מקראקא. נגיד וקצין בזאמוטשט-תקל. בניו - ר צבי הירש מאה\"ו, ר משה שלמה זלמן מקראקא. חתנו - ר עזריאל הלוי מקרושניק \"ראש הברזל\"."},{"i":8864,"n":"בנימין בייניש רבינסקי","f":"בריז\"ל","b":"דיין במוהילוב, חתם-תרלט עם ר משה יצחק הכהן רבינוביץ, ור בנימין אליהו הירשוביץ על מכתב לר שמואל סלנט בענין גט."},{"i":8865,"n":"בנימין ביינש ב\"ך מבריסק","b":"רב בבריסק. נזכר בשו\"ת המהר\"ם מלובלין. בנו - ר שמשון ב\"ך מבריסק ולבוב."},{"i":8866,"n":"בנימין ביינש הכהן מקרוטושין","k":"בעל שם טוב קטן","b":"גדול בתורה וחסידות בקאראטשין-תמ. ומקובל. חיבר \"אמתחת בנימין\"."},{"i":8867,"n":"בנימין ביינש מזזמיר","f":"צבי הירש","b":"רב בונדזיגולה, זזמיר-תקפ. בנו ר יצחק ר\"מ בוילנא."},{"i":8868,"n":"בנימין ביינש מפאלאצק וחברון","f":"משה בן ישראל","dt":"תרט - לפני","dp":"חברון","b":"מראשוני העולים אנשי חבד לחברון, חתם על ההסכם על הכולל הספרדי. בתקפז חתם על אגרת שליחות ר יצחק בן שלמה אשכנזי בשם עדת חבד בחברון, בשנת תקצה חתם על כתב שליחות ר נתן עמרם."},{"i":8869,"n":"בנימין ביינש מפוזנא","b":"חתן ר אפרים נפתלי הירש מלודמיר. מגדולי דורו, פרנס בפוזנא-שנת ת'. בניו - ר זכריה מנדל קלויזנר המכונה \"זכריה הנביא\", ר דוד טבלי מפוזנא בעל \"שערי ציון\". חתנו - ר משה קצנלנבוגן."},{"i":8870,"n":"בנימין ביינש מראסיין","f":"משה יהושע ניישטטער","b":"נכד-אבי אמו ר זעלמעלע מוילנא. מו\"צ בראסיין. הו\"ל כתבי אחיו ר שלום רבינוביץ מיאנישוק בשם \"דברי שלום ואמת\" ובראשו ספורים אודות זקנו ר זעלמעלע-אחיו של ר חיים מוולוזין וסדר יחוס משפחתם."},{"i":8871,"n":"בנימין בירבי יהודה","b":"חיבר ספר שירים ופיוטים, שנמצא בגניזה הקהירית והודפס"},{"i":8872,"n":"בנימין בן יעקב אבינו, קבור בכפר סבא","dt":"יא חשון"},{"i":8873,"n":"בנימין בן שמואל מסטופצי","bt":"1810","dt":"ה'תרנב 1892","bk":[["שארית בנימין",""]]},{"i":8874,"n":"בנימין בנדיט מברלין","f":"ירמיה פערשט מהמבורג","b":"בן הדיין מהמבורג. ממנהיגי קהילת ברלין. חתם על מינוי ר משה בן אהרן מלבוב ולייפניק לרבה של ברלין-תפט."},{"i":8875,"n":"בנימין בנדיט מלובלין","f":"פסח","b":"נהרג עק\"ה בלובלין."},{"i":8876,"n":"בנימין דוד מירושלים","f":"שמואל מוילנא","bt":"תקעג","dt":"תרנג","dp":"ירושלים","b":"עלה לירושלים-תקצט, מחכמי ירושלים, בשנת תרט מונה לדיין, חתום על פסקים ותעודות עם ר שמואל סלנט מהשנים תרטו - תרמט."},{"i":8877,"n":"בנימין הגדול הפייטן","b":"מגדולי הראשונים,פייטן,משורר-ד'תת\"פ"},{"i":8878,"n":"בנימין הכהן מאלגיר","bt":"ש","dt":"שע - בערך","b":"רב באלגיר. שאלה ממנו לר אברהם ן טוואה ונזכר ב\"שו\"ת נופך\"."},{"i":8879,"n":"בנימין הכהן מירושלים","b":"תלמיד ישיבת תורת חיים בירושלים. פעל יחד עם ר בן ציון ידלר בפעילות צבור והיה ממיסדי \"בית יעקב הישן\"."},{"i":8880,"n":"בנימין הכהן ממאגניסיאה","b":"מחכמי מאגניסיאה(=מאגנשיאה, מאגנצאה)-שנות ה-ת'."},{"i":8881,"n":"בנימין הכהן ממנטובה","b":"מקובל,רב במנטובה"},{"i":8882,"n":"בנימין הכהן ממרוקו ואלטונא","k":"ר בנימין הכהן ממרוקו","bt":"תקפד","bp":"מקאנס","dt":"תרמ - יז שבט","dp":"אלטונא","b":"למד תורה בפאס-מרוקו, עבר לאמשטרדם, אלטונא, מחכמי ביהמ\"ד שיסד ר אברהם זומביל במרוקו ליוצאי ספרד בהמבורג-תריג - ביהמ\"ד המכונה \"זומביל ישיבה\". חתן אחותו של הדיין ר יעקב כץ."},{"i":8883,"n":"בנימין הכהן מריגיו - רב\"ך","f":"אליעזר","k":"מוהרב\"ך","bt":"תיא","dt":"תפז-ח","b":"תלמיד הרמ\"ז. מגדולי המקובלים באיטליה. מתלמידיו ר שלום באזילה, ר יוסף אירגאס, וחתנו - ר ישעיה בסאן. הגן על הרמח\"ל-תפז בזמן המחלוקת כנגדו."},{"i":8884,"n":"בנימין הלוי","f":"יחיאל","k":"בעל גבעת בנימין","b":"חיבר \"גבעת בנימין\" על השו\"ע בסדר א\"ב - לובלין שעז."},{"i":8885,"n":"בנימין הלוי מאויבן","b":"מגדולי חכמי הספרדים,רב באויבן-ש\"ל"},{"i":8886,"n":"בנימין הלוי מאזמיר","f":"שלמה מירושלים ואזמיר","bt":"תך","dt":"תץ","dp":"אזמיר","b":"רב באזמיר-תס. ממתנגדי השבתאות יחד עם אביו, ופעל נגד נחמיה חייא חיון-תסח. נספד מאת ר ברזילי יעבץ. מתלמידיו ר אהרן בן משה אלפנדרי."},{"i":8887,"n":"בנימין הלוי מאזמיר","dt":"תפא - י תמוז","dp":"אזמיר","b":"מחכמי אזמיר."},{"i":8888,"n":"בנימין הלוי מברוד","dt":"תקסט - יג תמוז","b":"דרשן,מגיד בברוד"},{"i":8889,"n":"בנימין הלוי מטשבין","f":"יעקב","dt":"תש..","b":"ר\"מ בישיבה. נספה בשואה."},{"i":8890,"n":"בנימין הלוי מירושלים","f":"אשר אברהם","bt":"תרם","bp":"ירושלים","b":"אחיו של ר יוסף מרדכי-ראב\"ד ירושלים, חתן ר יעקב מרדכי הלוי מירושלים. מחכמי ירושלים, ועסקן ציבור. הניח חדושים בכת\"י."},{"i":8891,"n":"בנימין הלוי מנירנברג ושלוניקי","f":"מאיר","b":"רב הקהלה האשכנזית בסופיה, עבר עם אביו לשלוניקי-רצג ור נפתלי בן יצחק (הרש) הכהן על מקומו אחריו, מחכמי האשכנזים בשלוניקי. הו\"ל מחזור נוסח אשכנזי בשלוניקי."},{"i":8892,"n":"בנימין הלוי מקושטא","dp":"ירושלים","b":"גביר ודיין בקושטא-תך, עלה לירושלים. קנה מהמקובל ר יעקב צמח את כתב היד של חיבורו \"זר זהב\"."},{"i":8893,"n":"בנימין הלוי משלוניקי","f":"חיים","dt":"תא","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":8894,"n":"בנימין הנהונדי - הקראי","f":"משה","b":"מראשי הקראים בדור השני או השלישי-שנות ה-ד'תק, אולי תלמידו של יאשיה נכד ענן. נזכר אצל ר סעדיה גאון. תלמידיו נקראים בשם \"מקריים\" או \"מגריים\"."},{"i":8895,"n":"בנימין הפייטן","f":"זרח","b":"פייטן באשכנז או צרפת-ד'תתק. חיבר יוצרות לשבתות וסליחות. (ראה גם בנימין מפרס)"},{"i":8896,"n":"בנימין הפייטן","f":"חייא","b":"פייטן. חיבר \"ברית כרותה מלשכוח\", ועוד."},{"i":8897,"n":"בנימין הפייטן","f":"יהודה","b":"פייטן, חיבר קינות ומהם אצל די רוסי."},{"i":8898,"n":"בנימין הפייטן מצרפת","f":"עזריאל","b":"פייטן-המאה ה-11-12."},{"i":8899,"n":"בנימין הקראי מגוזלאוו","f":"אליהו","b":"נוסע קראי-תקמה."},{"i":8900,"n":"בנימין וולף","b":"רב-שנת תק\"י"},{"i":8901,"n":"בנימין וולף כ\"ץ מלבוב","f":"יהודה ליב","b":"ראב\"ד בלבוב, חתם-שפז בפנקס הקהלה."},{"i":8902,"n":"בנימין וולף מאזיראן","k":"ר וולוולע אזיראנער","b":"רב באזיראן-תרנ\"ז"},{"i":8903,"n":"בנימין וולף מהראדלי","f":"יקותיאל מחעלם","k":"בעל ענף עץ אבות","b":"רב בהראדלי(=קארדלא). חיבר \"ענף עץ אבות\" על פרקי אבות - אופיבאך תסט-תעט. בנו - ר מאיר מלכוביץ ודרישהאפליא."},{"i":8904,"n":"בנימין וולף מלבוב","f":"יואל","b":"דיין בלבוב, חתם-תיד עם ר אברהם גראפין, ור מאיר הלוי, חתם-תכא כנ\"ל."},{"i":8905,"n":"בנימין וולף מלובלין","f":"יעקב שלמה","bp":"זמושטש","b":"מחכמי לובלין. נזכר בפנקס קובץ פסקים אודות דין ודברים שהיו לו עם ר פנחס ר\"י ר\"ז אצל ר שאול מרגליות-תקמב."},{"i":8906,"n":"בנימין וולף מלובלין","f":"ר\"א ר\"ל","b":"מנהיג ועד ארבע ארצות, חתם-תמז ביריד ירוסלב. בניו - ר משה (נפטר ה שבט תקא), ר צבי (נפטר כו טבת תקיא)."},{"i":8907,"n":"בנימין וולף מקידאן","f":"יעקב","k":"ראש הברזל","dt":"תרכה - בערך","dp":"קידאן","b":"מו\"ץ בקידאן בזמן ר ראובן זקש ואב\"ד על מקומו אחריו. הסכים על ש\"ס סלאויטה. חתנו - ר יהודה ליב משה סירקין בעל \"סערות תימן\"."},{"i":8908,"n":"בנימין וולף מקידאן וירושלים","f":"ישכר בר","dt":"תרנא - כא טבת","dp":"ירושלים","b":"דיין בקידאן, עלה לירושלים ושימש כדיין."},{"i":8909,"n":"בנימין וולף מקניגסברג","b":"מו\"צ בקניגסברג-תק\"ס"},{"i":8910,"n":"בנימין וולף מקראקא","dt":"תמד - כה תשרי","b":"דיין בקרקא"},{"i":8911,"n":"בנימין וולף מרחמנוב ולבוב","dt":"שעב","dp":"לבוב","b":"מרביץ תורה, רב ברחמנוב, ר\"מ בלבוב."},{"i":8912,"n":"בנימין וולף סגל מסטרי","f":"ישראל סגל","b":"רב בסטריא-תקכ\"ג"},{"i":8913,"n":"בנימין וולף פוסוויילר","b":"תלמיד ר יונתן איבשיץ. אב\"ד פוסוויילר והמדינה, מרביץ תורה באלזס."},{"i":8914,"n":"בנימין וולף ראחשקז מלבוב","f":"משה יחזקאל","b":"תלמיד ר יהושע פאלק בעל הסמ\"ע, והגיה את ספרו \"מאירת עינים\" והוציאו לאור בפרג-שעד עם הקדמה ממנו."},{"i":8915,"n":"בנימין זאב הלוי מבאלטא","b":"רב בבאלטא"},{"i":8916,"n":"בנימין זאב וולף מזמיגראד וקראק","f":"שמואל דרשן או ישראל","k":"בעל עיר בנימין","dt":"תפא - ח ניסן","b":"חתן הגביר ר אברהם בן נתן הלוי מקראקא. מגדולי חכמי קראקא, רב בזמיגראד-תנח, דעסוי, מיץ-תסח, לוקטש, ועוד. בניו - ר יהושע מוולט, ר חיים. חתנו - ר פתחיה בן דוד לידא מלוקטש."},{"i":8917,"n":"בנימין זאב וולף מטימישואר","f":"[שלמה]","bp":"קראקא","dt":"תקלז","b":"רב בטימישואר-תקיב, נאזנאנפאלווא,רבה הראשון של קרלסבורג-תקכד, ורב הכולל בטרנסילבניה."},{"i":8918,"n":"בנימין זאב וולף מנעשוויז","f":"אריה ליב","dt":"תקפח - ה אדר","dp":"וילנא","b":"ר\"מ בנעשוויז."},{"i":8919,"n":"בנימין זאב וולף מפינטשוב","f":"שבתי מפינטשוב","k":"בעל מסגרת השלחן","b":"דיין בפינטשוב-תע. בנו ר שבתי הו\"ל את ספרו."},{"i":8920,"n":"בנימין זאב וולף סגל מזולקוא","f":"יעקב מדובנא","b":"מחכמי זולקוא, חתם-תקיא על החרם הגדול בזולקוא. נזכר בהקדמת \"מענה אליהו\". אולי בנו - ר גדליה."},{"i":8921,"n":"בנימין זאב יאקרלס מפרשבורג","k":"וולף פולאק","b":"רב בפרשבורג-תעד וחתם על פסק דין באיזנשטט. הסכים בשנת תפה על \"תולדות יעקב\" לר יעקב אילנברג מקראקא וסובורטן, ועל שו\"ת \"השיב ר אליעזר\" - בעל פה. חיבר פירוש על הסמ\"ק - בכת\"י (וחלקו נדפס בכתב העת \"נטעי בחורים\"-תרסז, ושו\"ת - נשרף."},{"i":8922,"n":"בנימין זאב יעקב מזרנובצא ואלבר","f":"משה המבורגר מבנדין","b":"רב בזרנובצא, ואלברום-תקס. אחיינו של ר אלימלך מליזנסק. בנו ר אברהם מרדכי הורביץ מפינטשוב."},{"i":8923,"n":"בנימין זאב מבאלטה","dt":"תקפג - כ כסלו","dp":"צפת","b":"תלמיד ר פנחס מקוריץ, וחברו של ר רפאל מברשאד - תלמידיהם כינו אותם \"שני המאורות הגדולים\". עלה לארץ בשיירת תקלז או סמוך לכך והתגורר בצפת. לתולדותיו ב\"אמרי פנחס השלם\" - בני ברק תשסג. העתיק בכתב ידו חלק מתורת רבו - שהתנגד להדפסת תורתו (ולכן במשך דורות הועתקו כתביו בכתיבת יד)."},{"i":8924,"n":"בנימין זאב מזברז","f":"המגיד מזלוטשוב","k":"בעל רזין דאוריתא","dt":"תקפב - ג ניסן","b":"אחד מ\"חמשה חומשי תורה\" - כפי שכונו בני המגיד מזלוטשוב. מתורתו ב\"רזין דאוריתא\", ו\"תפארת צבי זאב\". בנו ר יחיאל מיכל נפטר צעיר."},{"i":8925,"n":"בנימין זאב מזולקוא","f":"ישכר בער","b":"מחכמי זולקוא, חתם-תנד על תקנת הקהלה, ועל בחירת ראשי הקהלה-תמו."},{"i":8926,"n":"בנימין זאב מזולקוא","f":"יוסף","b":"דיין בזולקוא-תנב, נזכר ב\"דעת חכמה\"."},{"i":8927,"n":"בנימין זאב מזמיגראד","dt":"תרסב","b":"רב בזשמיגרד"},{"i":8928,"n":"בנימין זאב מזמיגראד (השני)","bt":"תקע","dt":"תרלג","b":"רבה של בוקובסק-תרד. אב\"ד דוקלא, זמיגרוד-תריח. חתנו ר מרדכי דוד אונגר יש על מקומו אחריו."},{"i":8929,"n":"בנימין זאב מירושלים","f":"דוד אשכנזי","k":"בעל שערי בנימין","b":"עלה מזאמושט לירושלים בשנת תצה, בשליחות באירופה לבנית בית המדרש של הבית יוסף בניקופול. מחבר ספר \"שערי בנימין\" זאלקווא תקיב, \"בן אוני\" אזמיר תח"},{"i":8930,"n":"בנימין זאב ממיקוליב","b":"רב במיקוליב. ממשתתפי אספת הרבנים בקראקא-תרסג."},{"i":8931,"n":"בנימין זאב מניקופול","f":"דוד","b":"מחכמי פליבנה-ליד ניקופול, בשליחות קהלת ניקופול-תקה לאחר השריפה הגדולה שם."},{"i":8932,"n":"בנימין זאב מפרס","f":"אליהו","k":"בעל מטעמי בנימין","b":"רב בפרס. חיבר דרשות בפרסית יהודית על ההפטרות בשם \"מטעמי בנימין\" - בכת\"י."},{"i":8933,"n":"בנימין זאב רוזנשטין מזמיגרוד","b":"תשובה אליו -ברכת יעקב\"-תריח."},{"i":8934,"n":"בנימין יוסף מלובלין","dt":"תריט - ג חשון","b":"תלמיד החוזה מלובלין - וסופרו, היהודי הקדוש מפשיסחא, ר שמחה בונם מפשיסחא ור יצחק מוארקי. היה מחלוקת נגדו בגלל היותו חסיד פשיסחא. נפטר ללא ילדים בגלל הקפדתו של החוזה."},{"i":8935,"n":"בנימין יעקב מהרודישץ","b":"נכד מהר\"ם מלובלין. רב בהרודשיץ-תר\"כ. אחיו של בעל \"גבעת שאול\". חתנו ר חיים סגלוביץ ונכדו ר יעקב מאיר - רב בהרודשיץ."},{"i":8936,"n":"בנימין יצחק מירושלים","f":"דוד","b":"מחכמי ירושלים, בשנת תקע חתם על מכתב ראשי הקהלה לר אברהם בן חסון."},{"i":8937,"n":"בנימין כץ מרגנשבורג","b":"מגדולי חכמי אשכנז,דיין ברגנשבורג"},{"i":8938,"n":"בנימין מאישקופיה","f":"בנימין דניאל","b":"רב באישקופיה-שסז."},{"i":8939,"n":"בנימין מארטא-יוון","f":"שמריה","b":"רב בשלוניקי-רמ, מרבותיו של ר שמואל קלעי מארטא. נזכר בשות הרד\"ך."},{"i":8940,"n":"בנימין מבוכרה","f":"יוחנן הכהן","k":"הו\"ל זכרון לפני ה'","b":"עלה מבוכארה בשנת תרמה, בשנת תרנב שליח בבוכרה, הדפיס ספר \"זכרון לפני ה'\" ירושלים תרמה"},{"i":8941,"n":"בנימין מבסקביץ","b":"מגיד ודיין בבסקוביץ-תק\"נ"},{"i":8942,"n":"בנימין מדוברובנא וירושלים","f":"אליהו","dt":"תר - א שבט","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":8943,"n":"בנימין מדיסנא","f":"בנימין","b":"מקובל,רב בדיסנא"},{"i":8944,"n":"בנימין מדלטין","b":"רב בדלטין."},{"i":8945,"n":"בנימין מדרויע","b":"רב בדרויא"},{"i":8946,"n":"בנימין מוילקומיר (רבינוביץ-תאו","f":"אברהם אבלי","k":"ר' בנימין הצדיק","b":"רב בווילקומיר, ראגובה. אביו של ר אליהו דוד רבינוביץ-תאומים."},{"i":8947,"n":"בנימין מזלוזיץ","f":"אהרן מגיד מואלטשיסק","k":"בעל אהבת דודים","bt":"תפ","dt":"תקנב - כה תשרי","b":"תלמיד הבעש\"ט והמגיד ממזריטש. מצאצאיו - ש\"י עגנון."},{"i":8948,"n":"בנימין מטבריה","dp":"טבריה","b":"נכד ר בנימין מהורודנקא. עלה לטבריה."},{"i":8949,"n":"בנימין מטודילא","f":"יונה","bp":"נבארא-ספרד","b":"מחכמי ספרד, סבב כשבע שנים בעולם. הנוסע החשוב ביותר בתקופתו, יצא מטודלה-ספרד-ד'תתקיט, תיאר בספריו את מסעותיו לארץ ישראל, ומשם לארצות ערב, והיה גם האירופאי הראשון שתיאר את סין בשמה, ספר מסעותיו הודפס בקושטא-ש\"ג"},{"i":8950,"n":"בנימין מטשכנוב","dt":"תרנה - כט חשון","b":"רב בטשעכאוו"},{"i":8951,"n":"בנימין מטשרנוביץ וירושלים","f":"משה","dt":"תרא - ג טבת","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":8952,"n":"בנימין מיאנעווי","f":"צבי הירש","b":"ראב\"ד ומו\"צ ביאנעווי. הסכים-תקצג על \"אבות דרבי נתן\" לר אליהו בן אברהם מדליטיץ."},{"i":8953,"n":"בנימין מיון","f":"מנחם","b":"חכם שלם מיוון"},{"i":8954,"n":"בנימין מירושלים","f":"יקותיאל","b":"היה מקהילת ר יהודה החסיד ושליח האחרון של האשכנזים בירושלים לפני חורבן הקהלה. הדפיס בעיר הענא שפד את \"ספר הכוונות\" להארי."},{"i":8955,"n":"בנימין מירושלים וסטופצי","f":"שמואל","b":"דיין בירושלים-תר\"נ"},{"i":8956,"n":"בנימין מל\"ב","f":"מאיר מלקנבך","b":"יש אומרים שהיה רב בלבוב ולדעת בובר היה בעיר אחרת אולי בלנדסברג, הסכים-תקל על \"טוב ויפה\" יחד עם ר שאול מפפד\"מ. לדעת ר יוסף לוינשטין אולי היה רב בלנדסבורג ואביו ר מאיר היה רב בלקנבך."},{"i":8957,"n":"בנימין מלבוב","f":"משה","k":"בעל תבנית הבית","dt":"שמ - ב ניסן","dp":"לבוב","b":"אב\"ד וראש ישיבה בלבוב. חיבר גם \"אהל של שמחה\"."},{"i":8958,"n":"בנימין מלבוב","f":"אליעזר","b":"חתם בלבוב-שפד על תקנות קהלת זולקווא עם ר אברהם בעל \"איתן האזרחי\", ור יוסף בן ירוחם, ור אברהם אשכנזי."},{"i":8959,"n":"בנימין ממארק","k":"בעל שדה יער","b":"רב במדינת מארק-ת\"כ"},{"i":8960,"n":"בנימין ממונטלסינו הפייטן","f":"יואב","b":"פייטן באיטליה-שנות ה-ר'-ש'. חיבר \"בקר אעיד אקראך\", ועוד."},{"i":8961,"n":"בנימין ממיטאווי","f":"זלמן מגולדינגן","dt":"תרלז - ט אב","dp":"לייפציג","b":"רב בוינדאווי-תרכז. בנו - ד\"ר לפילוסופיה יוסף מרקוזע."},{"i":8962,"n":"בנימין מנורמנדי הפייטן","f":"שמואל","b":"מגדולי הראשונים,פייטן,מרביץ תורה בקוסטני שבנורמנדיה-ד'תת\"ק"},{"i":8963,"n":"בנימין מסוקולוב"},{"i":8964,"n":"בנימין מסטויפיץ","f":"שמואל","bp":"נווהרדוק","dt":"תרנג","dp":"ירושלים","b":"עלה לירושלים בשנת תרלב והיה חבר בית הדין, חתום על פסקים בשנים תרלט - תרנב, חיבר ספר \"שארית בנימין\" ליק תרכג, \"אבל כבד\" ירושלים תרלה, חדושיו נדפסו בקבצים \"תורה מציון\". חותנו ר יצחק היה ראש ישיבה במינסק."},{"i":8965,"n":"בנימין מפוזנא","b":"רב בפוזנא-שנת ת'. חתן ר נתן שפירא בעל \"מגלה עמוקות\". מגדולי דורו, חתם עם הב\"ח, הט\"ז, המהרש\"א, בעל תוי\"ט, השל\"ה, בעל כלי יקר ועוד. נזכר בתשובת בעל הלבוש בענין הגט מוינה בשם 'בנימין דיין'. חיבר פירוש על דרישה ופרישה בכתב יד (בשולי הגליונות)."},{"i":8966,"n":"בנימין מפינטשוב","f":"שלמה","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":8967,"n":"בנימין מפרס","f":"זרח","b":"גלה ממלכות פרס ועבר לאשכנז ושוייץ והתישב בעיר האל. (ראה גם בנימין הפייטן)"},{"i":8968,"n":"בנימין מצפת","f":"מוהרמ\"ז","b":"מחכמי קהלת הפרושים בצפת. חתם-תקעה על מינוי הגבאים ר ישראל משקלוב, ר צבי הירש כץ, ר משה בן יוסף."},{"i":8969,"n":"בנימין מקראקא","dp":"ירושלים","b":"על מצבת אשתו כתוב: אסתר סי' די חכם בנימין קראקא"},{"i":8970,"n":"בנימין מרדכי הלוי","dt":"תשיג","b":"ראב\"ד לספרדים בירושלים"},{"i":8971,"n":"בנימין מרייגרוד","k":"בעל אבל כבד","b":"אב\"ד רייגרוד. חיבר \"אבל כבד\" - ירושלים תרלה - על פטירת ר איזל חריף, ר אברהם לנדא מצנסטחוב, ר יוסף שאול נתנזון מלבוב."},{"i":8972,"n":"בנימין משה מזולקוא","f":"אהרן","b":"מחכמי זולקוא, חתם-שפו על תקנת הקהלה."},{"i":8973,"n":"בנימין משובאץ","f":"דב מפינטניצע ושילאל","b":"חתן ר משה שמואל מישל שפירא מראגובה. רב בשובאט(=שובאץ)-קורלנד-תרע על מקום ר משה בן מרדכי רבינוביץ."},{"i":8974,"n":"בנימין משקלוב","b":"רב בשקלוב-תק\"פ"},{"i":8975,"n":"בנימין סגל","bp":"מעליץ","b":"נדד לאשכנז. הדפיס בפיורדא תקנא שני ספרי מוסר \"מרגניתא\" ו\"יורה חטאים\" עם תרגום לאשכנזית."},{"i":8976,"n":"בנימין סגל הלוי מברוד","f":"מאיר","k":"בעל אמרי בנימין","bt":"תק","dt":"תקסט","b":"רב בברדיטשוב, ברודי. חיבר \"אמרי בנימין\" טרנופול תקעד."},{"i":8977,"n":"בנימין סיני מאונסדורף","f":"משה","dt":"תסו - יח שבט","dp":"אונסדורף","b":"רב באונסדורף. בנו - ר חיים צבי."},{"i":8978,"n":"בנימין עוזיאל מאזמיר","dt":"תקמד - ב אב","dp":"אזמיר","b":"מחכמי אזמיר."},{"i":8979,"n":"בנימין עוזר מקלימנטוב וזולקוא","f":"מאיר","k":"בעל אבן העזר","dt":"תע - כה אייר","dp":"זולקוא","b":"אב\"ד קלימנטוב, ראש ישיבה בזולקוא. נכדו(-בן בתו) ר אהרן בן יהודה ליב מפינטשוב הו\"ל והוסיף הקדמה לספרו \"אבן העזר\"."},{"i":8980,"n":"בנימין קלצקער משקלוב","b":"תלמיד ר שניאור זלמן מליאדי. עבר מקלצק לשקלוב. השתדך עם בית רבו."},{"i":8981,"n":"בנימין רפאל מקושטא","bt":"תרלא","bp":"אדרינופול","dt":"תרפט - כג חשון","dp":"קושטא","b":"הו\"ל ספרים בלדינו, כתב בעתון \"החרות\", ועוד, עסק במסחר ספרים וביקר כמה פעמים בארץ, למד אצל אפרים דיינרד."},{"i":8982,"n":"בנימין, אליהו מבגדד","dt":"תשה - ט אדר","b":"ראש הרבנים בעיראק-תרצ\"ב"},{"i":8983,"n":"בנימינזון, אברהם ליב מניו יורק","f":"משה","k":"בעל מלחמה בשלום","bp":"לאחוביץ-ליד קלצק","dt":"תרעה","b":"משכיל וסופר בניו יורק-תרנח. חיבר גם \"עמק יהושפט\". גיסו של ר אברהם דובזביץ."},{"i":8984,"n":"בנימינזון, ירחמיאל","dt":"תשטו","b":"רב בגרובין,זלובין,לונדון-תרצ\"ה,מונטריאל-תש\"ה"},{"i":8985,"n":"בנימיני, יוסף","bt":"תרמז","bp":"דרבנט-דגסטאן","dt":"תרצג - כו שבט","dp":"עמק חפר","b":"עלה לארץ-תרסו, הגיע לארה\"ב והתגיס לגדוד העברי-תרעז. נהרג ע\"י ערבים בעמק חפר."},{"i":8986,"n":"בנין שלמה - ישיבה בירושלים","f":"ראה: חסד לאברהם"},{"i":8987,"n":"בנס, יעקב מקומרנא","f":"יהודה","bt":"תק","dt":"תקסג","b":"רבה של קומרנא אחרי ר שאול מרגליות ורבה של בעל \"ישועות יעקב\". היה מתנגד והתנגד אף לר אלימלך מליזנסק."},{"i":8988,"n":"בנסון, יהודה מארה\"ב","f":"צבי הירש בנסון","bt":"תרמ","bp":"ארשע-פלך מוהילוב","b":"תלמיד ישיבות מיר, סלובודקה. נסמך מאת: ר שלמה וילנר, ר רבונסקי מדובראווא, ר שיינון מטשאשניק(=שטריסק). חתן ר לוי יצחק מייבל מטשישרסק(=טשירסק) רב בטשירסק-תרס-ז, ארשע-תרסח, היגר לארה\"ב וכיהן כרב בברונקס-תרפח. חבר אגודת הרבנים באמריקה."},{"i":8989,"n":"בנסון, צבי הירש","b":"רב בארשע-תרנ\"ה"},{"i":8990,"n":"בנצר, ברוך","b":"הוציא לאור \"מצות השם\" ניו יורק תשנח."},{"i":8991,"n":"בנצר, מאיר שלום מסטרי","b":"מחכמי סטרי. תשובה אליו \"כוכב מיעקב\"-תרלח."},{"i":8992,"n":"בנק, משה מרישא","b":"מחכמי רישא. תשובה אליו \"כוכב מיעקב\"-תרלח."},{"i":8993,"n":"בנק, עמנואל מליטא - רוסיה","f":"ברוך","bt":"1840","bp":"לוקניק-ליטא","dt":"1891","dp":"שוייץ","b":"עורך דין. התחנך בבית דודתו הגב' סולוביציק (אמו של העסקן עמנואל סולוביציק). למד משפטים בפטרבורג ומוסקבה, ושירת במשרד המשפטים ברוסיה. פרש והחל לעבוד כעו\"ד - אחד המפורסמים ברוסיה. פעיל בציבור היהודים, חבר בועד חברת מפיצי השכלה, חבר במשלחת היהודית לצאר אלכסנדר ה-3 בעלותו על כס המלוכה."},{"i":8994,"n":"בנקר, משה צבי מזילקובקי","f":"יחיאל","bt":"תרלא","b":"רב בזלקבקי(=זילקאווקי)-תרסו."},{"i":8995,"n":"בנר, יונה מרדיחוב","f":"יהודה ליב","bt":"תרס","bp":"גלינא","dt":"תשב","b":"תלמיד המהרם שפירא. רב ברדיחוב וממנהלי בית יעקב. נספה בשואה."},{"i":8996,"n":"בס, אברהם משה מארה\"ב","bp":"ליקאווא","b":"רב בניו יורק בעל ספריה חשובה. אחיו ר שמואל."},{"i":8997,"n":"בס, ליב נח משווקאט","k":"בעל תיבת נח","bt":"תריט","bp":"גלוואן","dt":"תרסט - ד כסלו","b":"רב בשווקאט-תרנד, ראסיין. פרסם מאמרים ב\"כנסת הגדולה\" - וארשא תרן, \"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":8998,"n":"בס, מנחם מנדל מפפד\"מ - א","f":"יצחק אביגדור מקראקא","dt":"תכז - יד תשרי","dp":"פפד\"מ","b":"תלמיד ר יואל סירקש בעל הב\"ח. מגדולי חכמי דורו, מרביץ תורה בקרקא, רב וראש ישיבה בפפד\"מ-תיד על מקום ר יעקב שיף, ור אהרן שמואל קיידנובר על מקומו אחריו. חיבר תקנות בפפד\"מ על חובות הרופאים, ובעניני חינוך. היה מחלוקת כנגדו מצד כמה מראשי הקהל. היה מתומכי הספר הקבלי \"עמק המלך\" - שהיה מחלוקת כנגדו מצד המקובלים, ועל הספר הקבלי \"ויואל משה\" - פירוש על עשרה מאמרות לר מנחם עזריה. מתלמידיו: ר יאיר חיים בכרך בעל \"חוות יאיר\", חתנו ותלמידו - ר מאיר שטרן. לאחר פטירת חתנו חזרו האלמנה עם בנה ר מנחם מנדל שטרן לפפד\"מ והו\"ל את שו\"ת הב\"ח - שמצאה בעזבון אביה - שהיה תלמידו."},{"i":8999,"n":"בסאן - משפחה","b":"משפחת רבנים באיטליה וטורקיה. מוצא המשפחה בבוסאניה."},{"i":9000,"n":"בסאן, אברהם חזקיה מאמשטרדם","f":"יעקב מהמבורג","k":"בעל ישרש יעקב","b":"רב ומשורר באמשטרדם, המבורג. משיריו בספר \"גמול עתליהו\", \"דברי דוד\" ועוד. חיבר \"ישרש יעקב\" בעילום שמו (תחת השם - ר\"י באבאגי - כי פחד מהביקורת על ספרו). שיר ממנו ב\"פרי עץ חיים\" - אמשטרדם."},{"i":9001,"n":"בסאן, אהרן איש נווירה מונציה","f":"יוסף בן קלונימוס","b":"מחכמי ונציה. חתם על גבית עדות-שג ונזכר בשו\"ת מהר\"ם פאדובה."},{"i":9002,"n":"בסאן, בצלאל","b":"פרסם מאמרים ב\"כנסת הגדולה\" - וארשא תרן."},{"i":9003,"n":"בסאן, ברוך בנדיט מוירונה","f":"ישראל יעקב","b":"מחכמי איטליה, רב בוירונה-שסא. תשובה ממנו ב\"פלגי מים\"."},{"i":9004,"n":"בסאן, גרשון מוירונה","b":"מגדולי חכמי איטליה,רב בוירונה-שפד. חתום עם אביו אודות חרם בענין מחלוקת בין סוחרי וירונה ופיררה."},{"i":9005,"n":"בסאן, גרשון מרמסגט","bt":"תרכח","b":"רב ברמסגט-תר\"ע"},{"i":9006,"n":"בסאן, חזקיה מרדכי מוירונה","f":"שמואל חיים","k":"בעל מכתב לחזקיה","bt":"תקף-ץ","bp":"וירונה","dt":"תסד - ח כסלו","b":"תלמיד ר שמואל אבוהב בוירונה. רב בוירונה-תמח. חיבר \"מכתב לחזקיהו\", \"בכורים\", \"מאמר מרדכי\" - שנדפס ע\"י נכדו ר מנחם נווירה. תלמידו - ר ישעיה בסאן. חיבר \"ביקורים\" לחברת ביקור חולים, ואגרת מוסר, \"פני יצחק\". בניו - ר ישעיה ור שלמה."},{"i":9007,"n":"בסאן, חיים מרודוס וקושטא","f":"יעקב","dt":"שמט - אחרי","b":"רב ברודוס-שי, עבר לקושטא. התכתב עם ר יוסף ן לב, רשד\"ם, ר יוסף קארו ועוד. בנו - ר יחיאל ראש הרבנים בקושטא."},{"i":9008,"n":"בסאן, יהושע השל מירושלים","f":"אליהו","b":"מחכמי ירושלים-תרמט."},{"i":9009,"n":"בסאן, יום טוב מקושטא","b":"רב בקושטא-שנות ה-ש'. אולי אחיו של ר יחיאל."},{"i":9010,"n":"בסאן, יונתן מקושטא או שלוניקי","dt":"שפא","b":"רב בקהלת \"גרוש\". נכדו - בעל \"אזני יהושע\"."},{"i":9011,"n":"בסאן, יוסף דוד מריגיו","b":"תלמיד ר שלמה למפרונטי. חתן ר אברהם רוקא מפיררה. מחחכמי פיררה, רב בריגיו-תקסב עם ר שבתי אלחנן פיסארו ור חננאל ניפי, תחת ר יהודה חי מלאוידה."},{"i":9012,"n":"בסאן, יחיאל מקושטא","f":"חיים","k":"בעל שות מהר\"י בסאן","bt":"שי","bp":"רודוס","dt":"שפה","dp":"קושטא","b":"תלמיד ר יצחק איריסה ברודוס, עבר עם אביו לקושטא, ראש הרבנים בקושטא-שן. נכדו - ר יצחק הו\"ל את ספרו בשם \"שו\"ת מהר\"י בסאן\"."},{"i":9013,"n":"בסאן, יעקב מהמבורג","b":"אביו של ר אברהם יחזקיה מאמשטרדם."},{"i":9014,"n":"בסאן, יצחק","f":"משה","bt":"יאמבול-בולגריה","bp":"תרלג","b":"תלמיד ביהמ\"ד למורים בפאריס. מורה ומנהל בכי\"ח בסאמאקוב, האמדאן-פרס ופעל גם נגד ההטפה של הבאהים, חלב, בגדד בביה\"ס \"לאורה כדורי\", ירושלים-תרפד."},{"i":9015,"n":"בסאן, יצחק מקושטא","k":"הו\"ל שו\"ת מהר\"י בסאן","b":"נינו של ר יחיאל בסאן, גביר בקושטא-שנות ה-ת', הו\"ל ספר זקנו בשם שו\"ת מהר\"י בסאן."},{"i":9016,"n":"בסאן, ישעיהו מפדובה","f":"ישראל חזקיהו מוירונה","k":"בעל תודת שלמים","bt":"תלג","bp":"וירונה","dt":"תצט","dp":"פדובה או ריגיו","b":"מגדולי הפוסקים בדורו, תלמיד ר מרדכי בסאן, למד עם מהר\"י בריאל והרמ\"ז במנטובה. חתן ר בנימין הכהן מריגיו=מוהרב\"ך. רב בפדובה בזמן הרב יחכ\"ם. רב בריגיו לצד חותנו, וירונה. מתלמידיו הרמח\"ל, ר יצחק מאריני, ר ישעיה רומאנין ועוד. מתורתו בספרי חכמי דורו באיטליה. חיבר \"תודת שלמים\" ובו גם תשובות מבנו - ר ישראל בנימין."},{"i":9017,"n":"בסאן, ישראל בנימין מריגיו","f":"ישעיהו","k":"בעל תודת שלמים","bt":"תס - בערך","dt":"תקן","b":"נכד(-אבי אמו) ר בנימין בן אליעזר הכהן ויטאלי-רב\"ך. תלמיד הרמח\"ל בקבלה. רב בריגיו-ת\"ק. חיבר פירוש לספר אביו \"תודת שלמים\" בשם \"פרורי לחם\", ועוד חבורים רבים בכת\"י. מוזכר ב\"קול עוגב\". הרמח\"ל חיבר שיר לכבודו ביום נישואיו בשם \"מגדל עוז\"."},{"i":9018,"n":"בסאן, ישראל חזקיהו מפדובה","dp":"מונציליסי","b":"מגדולי חכמי איטליה. רב בפדובה, וירונה, בזמן בעל \"דבר שמואל\" שהשיב לו בספרו לוירונה. זקנו של בעל \"תודת שלמים\". תיקן חברת משמרת החדש וסדר ערב ראש חודש בקהילת פדובה."},{"i":9019,"n":"בסאן, מזל טוב מירושלים","b":"מחכמי ירושלים-סוף שנות ה-תק',"},{"i":9020,"n":"בסאן, מרדכי מוירונה","f":"יעקב","b":"רב בונציה-שפ, וירונה-שפה בזמן ר נתנאל טרבוט. תשובה ממנו ב\"משבית מלחמות\"-שסו."},{"i":9021,"n":"בסאן, משה מירושלים","dt":"תקמא - כב אלול","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":9022,"n":"בסאן, משה מנוביירה","dt":"רעח","b":"רב בונציה-רעה בזמן ר יחיאל טראבוטו. תשובה ממנו ב\"פסקי גאוני איטליה\" ונציה."},{"i":9023,"n":"בסאן, משה מקושטא","f":"יחיאל","b":"מחכמי קושטא-שצג, שאלה ממנו לר משה בנבנישתי מקושטא."},{"i":9024,"n":"בסאן, רפאל דוד מירושלים","dt":"תקעז - ו אייר","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":9025,"n":"בסולי, מרדכי רפאל מאיטליה","f":"יעקב","k":"בעל שער השמים","b":"מחכמי איטליה, מקובל ומשורר."},{"i":9026,"n":"בסוק, משה","f":"זלמן יהודה-נחלת יעקב","k":"בעל בשלבים","bt":"1907","bp":"קובנא","dt":"1966","dp":"אשדות יעקב","b":"סופר ומשורר. עלה לארץ-תרצו והצטרף לקיבוץ יגור, אשדות יעקב. חיבר \"בשלבים\" וארשא תרצד, \"בהדום מרחקים\" ת\"א תשא, ועוד."},{"i":9027,"n":"בסטומסקי, שלמה","f":"יעקב","k":"בעל ביים קוואל","bt":"1891","bp":"וילנא","dt":"1941","dp":"וילנא","b":"סופר ומחנך. מיסד בית ההוצאה \"די נייע אידישע פאלקס שול\" בוילנא. הו\"ל עתון לילדים \"די גרינינקע ביימעלעך\"."},{"i":9028,"n":"בסטיל, פרץ מקראקא","f":"שלמה זלמן","b":"מחכמי קראקא. תשובה אליו \"נדרי זריזין\"."},{"i":9029,"n":"בסין, מאיר מוילנא ושניפישוק","f":"משה","bt":"תרלג","bp":"רוזשינאי","dt":"תרצב - כא חשון","b":"חתן ר ליב רשקס. דרשן, רב בשניפישוק-תרס על מקום חותנו, וחתנו ר ישראל זאב גוטסמן על מקומו אחריו, בועד הרבנים בוילנא. פרסם מאמרים ב\"כנסת ישראל\" - וילנא תרץ."},{"i":9030,"n":"בסיס, יהושע מתונס","b":"רב ראשי בתוניס-תק\"ס"},{"i":9031,"n":"בסיס, ישועה מתונס","k":"בעל אבני צדק","bt":"תקלג","bp":"תונס","dt":"תרך - ט טבת","dp":"תונס","b":"תלמיד ר משה סלום (שלום) בעל \"ישמח משה\", וכנראה גם תלמיד ר יצחק טייב בעל \"ערך השלחן\", חבריו ר שלום שמעוני בעל \"גנזי שלום\" ור שלמה שמאמה בעל \"שורש ישי\" והזיכרוהו בספריהם. דיין אצל ר יצחק טייב, רב ראשי בתונס-תרז וראש הישיבה, על מקום ר יצחק טנוג'י, ועל מקומו אחריו ר נתן בורג'ל. מתלמידיו - ר אברהם הכהן יצחקי בעל \"משמרת כהונה\", ור אברהם חג'אג' בעל \"זרעו של אברהם\" שכיהן כדיין אצל רבו.","bk":[["אבני צדק",""]]},{"i":9032,"n":"בסכס, ברוך מגלינא","f":"יעקב","k":"בעל כבוד מלכים","bt":"תרכז","bp":"גלינא(=גליניאני)","dt":"תרצג","b":"נסמך מאת: מהרש\"ם מברעזן, ר יצחק אהרן איטינגא, ר משה ברז\"פ מליזנסק, ר פיבל רוהטין מזלוטשוב, ר בנימין אריה וייס מטשרנוביץ. רב בגלינא-תרנו, אב\"ד סאלקא - בוקובינה-תרסג, ובורדוזען. חיבר \"כבוד מלכים\" למברג תרס.כתב בגליון היובל של דראהביטשער צייטונג."},{"i":9033,"n":"בסכס, צבי הירש","b":"מחכמי זולקווא-תרט. תשובה אליו ב\"יד אליעזר\"."},{"i":9034,"n":"בסקין, זאב ולדימיר","bt":"1855","bp":"וילנא","b":"מבקר מוסיקלי. בוגר המחלה למשפטים בפטרברוג. כתב מאמרים בעתונות הרוסית על נושאי תרבות. חיבר דרמה ברוסית \"על פרשת דרכים\" - מחיי היהודים ברוסיה - והוצגה בהצלחה בזמנו."},{"i":9035,"n":"בסקין, שמואל מארה\"ב","f":"בנימין","k":"בעל עולת שמואל","bt":"תרמד","bp":"רוגטשוב-פלך מוהילוב","b":"תלמיד ישיבת רוגטשוב אצל ר אליקום גץ ארלוזרוב, בוברויסק אצל ר וולף ור ראובן דיקשטיין, ישיבת החפץ חיים בראדין, ר בן ציון חריף בישיבת רמייליס בוילנא. נסמך מאת: ר בנימין פרידמן מוילנא, הרידב\"ז, ר משה חיים רבינוביץ מברונזויל. חתן ר יצחק איזיק גוז מקאוועל-ווהלין. רב בדנבר-ארה\"ב-תרסז, קהלת משה מונטיפיורי בסולט לייק סיטי-תרעג, ניו ברונזויק-תרעט, ברוקלין-תרץ."},{"i":9036,"n":"בסר, יחזקאל מנ\"י","b":"תלמיד ישיבת \"כתר תורה\" - רדומסק, היגר לארה\"ב. הו\"ל ספר רבו - ר דוד משה רבינוביץ, בשם \"שבחי כהן\" - נ\"י."},{"i":9037,"n":"בעדאש, אליהו מלוב","bt":"תף","dt":"תקן - בערך","b":"רב במחוז ג'ריאן-לוב. לתולדותיו ב\"מחניים\" תשכד."},{"i":9038,"n":"בעדאש, ציון מלוב","bt":"תקי","dt":"תקף - בערך","b":"רב במחוז ג'ריאן-לוב. לתולדותיו ב\"מחניים\" תשכד."},{"i":9039,"n":"בעהם, יצחק איציק מקרולה","f":"צבי","dt":"תרמח - כה חשון","dp":"ירושלים","b":"חסיד צאנז ושינאווא. דיין בקרולה, היה במחלוקת עם הרב - ר מאיר פרלס - על שלא הצטרף למחנה האורתודוכסי, עלה לארץ-תרלה, וכיהן כדיין בירושלים. הסכים על \"ניתוץ הבית\" - שיצא כנגד ר עקיבא יוסף שלזינגר. הו\"ל \"אור החמה\" לר אברהם אזולאי, ועוד. הסכים על \"קול קורא\" מירושלים האוסר הקמת בתי ספר שם."},{"i":9040,"n":"בעזין, גרשון הלוי מצרפת","bt":"1784","bp":"מיץ","dt":"1864","b":"מורה בפפד\"מ, בעל בית מסחר לספרים במיץ, פרסם מאמרים בכתב עת."},{"i":9041,"n":"בעל קורא, משה","dt":"תרנב","b":"רב בהערץ"},{"i":9042,"n":"בעלאווס, ישראל ממוהילוב","b":"מו\"צ במוהילוב-תרסז, הסכים על אור ישן לר שניאור נתן ליפשיץ."},{"i":9043,"n":"בעלול"},{"i":9044,"n":"בעלול, אברהם מירושלים","dt":"תקנא - יב טבת","dp":"ירושלים","b":"מחכמי ירושלים ודיין, חתם-תקיד על שטר התקשרות עם חכמי ירושלים. בשנת תקיב נמנה על חכמי ישיבת דמשק אליעזר, חתנו - ר ראובן בן אברהם אשטיפי בעל דרך ישרה, הסכים על ספר יד רמה תקנב. חתום על כתב שליחות לאירופה ר רפאל שלמה בן יוסף הלוי. (לפי רוזניס נפטר ביג שבט)"},{"i":9045,"n":"בעלול, חזקיה מירושלים - א","dt":"תקח - יא תשרי","dp":"ירושלים","b":"מחכמי ירושלים, כנראה אחיו של ר אברהם."},{"i":9046,"n":"בעלול, חזקיה מירושלים - ב","dt":"תקמז-סז -ד סיון","dp":"ירושלים","b":"מחכמי ירושלים חתם על אגרת ראשי הקהל בשנת תקמז. אחיו של ר אברהם."},{"i":9047,"n":"בעלול, מרדכי מירושלים","dt":"תקעו","dp":"ירושלים","b":"מחכמי ירושלים, בשנת תקסט בשליחות עם ר שמואל בן דוד דידיע מאג'אר. נזכר בספר \"יוסף חן\" לר יוסף קונקי."},{"i":9048,"n":"בעלול, מרדכי מירושלים","dt":"תקעו - כא אדר","dp":"ירושלים","b":"מחכמי ירושלים. בשליחות-תקסט עם ר שמואל בן דוד דידיע מאג'אר. נזכר ב\"יוסף חן\" לר יוסף קונקי."},{"i":9049,"n":"בענא, יעקב מגטינגן","bt":"תרכט","bp":"ברסלוי","b":"תלמיד ביהמ\"ד לרבנים בברסלוי, בעל תואר ד\"ר. רב בגטינגן-תרנב. פרסם מאמרים ביהדות."},{"i":9050,"n":"בעניאש, אברהם יצחק ממוסניק","dt":"תשא","b":"רבה האחרון של מוסניק(=מושניק)-ליטא. נספה בשואה."},{"i":9051,"n":"בענין, אברהם מועגער","f":"צבי הירש","bt":"תרלו","bp":"חסלביץ-פלך מוהילוב","b":"רב בווגר(=ועגער)-פלך קובנא-תרסג."},{"i":9052,"n":"בער סגל מקובנא","b":"רב בקובנא-שצד."},{"i":9053,"n":"בערגאזון, זאב מוואלאמין","b":"חתן ר נפתלי יוסף פריינד מראזאן. רב בוואלאמין-פלך וארשא."},{"i":9054,"n":"בערזאהן, יעקב יוסף מלענטשא","b":"אב\"ד לענטשא. פרסם מאמרים ב\"אוצר החיים\" - זאמושט תרצז."},{"i":9055,"n":"בערטשע מוואשרהלי","f":"חיים","dt":"תש..","b":"ממשפחת אדמורי נדבורנא - קרטשניף. חתן ר יחיאל ממיהלוביץ. נספה בשואה."},{"i":9056,"n":"בעריל מיכאיילישקער מוילנא","b":"מחכמי \"ישיבת הארבעים\" בוילנא-תקפז."},{"i":9057,"n":"בערישעס, מנדל","b":"יצא בכרוז כנגד שרגא ויזנצברג-קושיץ תרצא."},{"i":9058,"n":"בערל ליב","b":"רב בהיידו צישק-תר\"נ"},{"i":9059,"n":"בערן, יוסף מפפד\"מ","f":"עקיבא","b":"ראש ישיבה בפפד\"מ-תע - בביהמ\"ד של ר דוד אופנהיים."},{"i":9060,"n":"בערעלע מתמיד ממאלאט","dt":"תרכג","b":"מחכמי מאלאט, נהרג ע\"י הקוזקים בדרכו מוילנא למאלאט בזמן המרד הפולני השני-תרכג."},{"i":9061,"n":"בצלאל בהרא\"ש מירושלים","dt":"תרכו - יא חשון","dp":"ירושלים","b":"מחכמי ירושלים. נפטר במגפת הכולירה בירושלים-תרכו."},{"i":9062,"n":"בצלאל בן שלמה","bt":"1640","dt":"ה'תנא 1691","bk":[["נופת צופים",""],["עמודיה שבעה",""],["פלח הרימון",""],["קרבן שבת",""]]},{"i":9063,"n":"בצלאל דרשן מסלוצק","f":"שמואל גינצבורג?","b":"חתן ר שמואל מאמדור מינסק והורדנא. רב בסלוצק-תקל. חתנו - ר יום טוב ליפמן מקאפוליא."},{"i":9064,"n":"בצלאל הכהן מאוסטרהא","f":"נפתלי כץ מאוסטרהא","dt":"תעז - כא סיון","b":"חתן ר יואל הלפרין מאוסטרהא. רב באוסטרהא על מקום אביו. נפטר בחיי אביו. (בזמן הלוייתו היו חייבים לעבור דרך בית מקלט היעזוטים שדרשו לתת להם נרות כדי לעבור בשלום ואם לא סקלו את אנשי ההלוויה - ור נפתלי אביו שהיה בעל קבלה מעשית סימן עיגול סביב המטה והגויים שחיכו להם עם אבנים לא ראו אותם). בניו - ר יצחק איזיק מאוסטרהא, ר נחמן הכהן (חתנו של ר חיים רפפורט מלבוב), ר יוסף (חתנו של ר יהודה ליב מייזלש ממיר), חתניו - ר משה רוקח מזלוטשוב, ר יוסף לנדא מקלימנטוב, ר דב בער בן ר שמואל רבי יעקליש מאוסטרהא."},{"i":9065,"n":"בצלאל הכהן מוילנא","f":"ישראל משה בן בנציון","k":"בעל ראשית בכורים","bt":"תקפ","bp":"וילנא","dt":"תרלח - י ניסן","b":"חתן ר אהרן משולח או ארציק רוזנטל - נישא בגיל 11 וחזר על הקידושין בהיותו בן 13. ובזיוו\"ש חתן הגביר ר יצחק א\"ש (זוערינצער), ובזיוו\"ש חתן הגביר ר צבי הירש באייארין. מו\"צ בווילנה-תרד על מקום ר יוסף שישקס, והיה מנהיגה הרוחני של הקהילה. חיבר גם \"מראה כהן\", \"תוספות בכורים\" ובו הכשיר את אתרוגי קורפו - לאחר שנסע לקורפו לראותם בעיניו והיה מחלוקת בספר \"תוכחת מגולה\" והשיב ב\"להוכיח במישור\" ו\"דברי מלואים\" ועוד. יצא כנגד \"סדרי טהרה\" והוא מסכת כלים החדשה לר גרשון חנוך מראדזין ונגד עשרה מגדולי הרבנים שהסכימו על הספר - כנגדו נכתב בשם בדוי אגרת ב\"המגיד\" וחתם שמחה שלמה יונגער לעווע.","bk":[["מראה כהן [עהש\"ס]",""],["מראה כהן",""]]},{"i":9066,"n":"בצלאל הכהן מירושלים","f":"אריה ליב","b":"בשנת תקפד בשליחות הפרושים בירושלים בליטא. ר ישראל משקלוב מזכירו בזכרונותיו כמביא התרומות מוילנא יחד עם ר יודיל מוילנא."},{"i":9067,"n":"בצלאל הכהן מלבוב","f":"משלם הכהן","b":"ראב\"ד ומג\"מ בלבוב-תק\"ד"},{"i":9068,"n":"בצלאל הכהן מפרג","f":"מרדכי","dt":"שנב","dp":"פרג","b":"מדפיס בפרג לצד אביו."},{"i":9069,"n":"בצלאל הלוי מזולקוא","f":"יהודה הלוי","k":"בעל בשם בצלאל","b":"נכד(-אבי אמו) ר חנוך מזולקוא. מחכמי זולקווא-תקל. חיבר פירוש לפרקי אבות בשם \"בצלאל\" - פפד\"א תקלא, הו\"ל תלמוד ירושלמי עם פירוש מהר\"א פולדא - פפד\"א תקב. חתנו - ר צבי הירש מואדיסלב בעל \"עשרה למאות\", בתו השניה - שבע - היתה אמו של ר אברהם שעבעס מקראקא."},{"i":9070,"n":"בצלאל הלוי מסלוצק","b":"חתן ר שמואל מאמדור בעל \"תשובת שמואל\". רב בסלוצק. בנו - ר אליהו סלוצקי ממיר."},{"i":9071,"n":"בצלאל הלוי משלוניקי","b":"מדפיס בשלוניקי-תקסג אצל מרדכי נחמן ורפאל קלעי."},{"i":9072,"n":"בצלאל חריף מקעלין","f":"ליווא-מהר\"ל מפרג","dt":"שפ","b":"מגולי חכמי דורו,רב ור\"מ בקעלין"},{"i":9073,"n":"בצלאל מאורלא","f":"יוסף יוזל","b":"רב באורלא."},{"i":9074,"n":"בצלאל מגלינא","b":"רב בגליגא-תר\"נ"},{"i":9075,"n":"בצלאל מוורמייזא - א","f":"יהודה ליוואי הזקן","k":"ר'בצלאל מווירמייזא","b":"מגדולי חכמי דורו בווירמייזא-ר\"מ"},{"i":9076,"n":"בצלאל מוורמייזא - ב","f":"חיים מוורמייזא","k":"אבי המהר\"ל","b":"מגדולי חכמי דורו,רב בפוזנא-רצ. בניו: ר חיים מפרידברג בעל \"אגרת הטיול\", ר סיני מפרג וניקלשבורג, ר שמשון מקרמניץ, ר יהודה ליוואי - המהר\"ל. (מסופר כי אביו ברכו שיצאו ממנו ארבע אורות וכו')."},{"i":9077,"n":"בצלאל מזארעץ","b":"תלמיד הצמח צדק ושליחו לעניי ה\"כולל\" בארץ ישראל."},{"i":9078,"n":"בצלאל מזולקוא","f":"נתן הקדוש","k":"בצלאל מוכסן","dt":"תנז - יט תשרי","dp":"זולקוא","b":"גביר מראשי הקהלה בזולקוא-תמה, מקורב למלך סוביסקי אשר בנה לו בית בזולקוא. נזכר בפנקס זולקוא. חתנו - הגביר ר חנוך הניך מזולקוא."},{"i":9079,"n":"בצלאל מלובלין","b":"מחברי הח\"ק בלובלין-תס."},{"i":9080,"n":"בצלאל מליבטשוב","b":"רב בליביטשוב-תרמו. תשובה ממנו ב\"נחמת יוסף\"."},{"i":9081,"n":"בצלאל מניישטט","dt":"ו אדר","b":"רב בניישטט"},{"i":9082,"n":"בצלאל מסאסוב","f":"נחמיה","b":"רב בסאסוב-תר\"ל"},{"i":9083,"n":"בצלאל מקאפוליא","dt":"תקצב - ו כסלו","b":"רב בקאפוליא"},{"i":9084,"n":"בצלאל מקוברין","f":"שלמה","k":"בעל קרבן שבת","b":"דרשן, רב בסלוצק, בוסקוביץ, פרמישלא-תיט. חיבר גם \"עמודיה שבעה\", \"ברית עולם\", \"זית רענן\"."},{"i":9085,"n":"בצלאל מקלם","b":"רב בקעלם-תר\"כ"},{"i":9086,"n":"בצלאל מקמניץ","f":"מנחם מנדל","b":"רב בקמניץ"},{"i":9087,"n":"בצלאל נפתלי מסעלץ","f":"חיים שלמה זלמן ממיר","b":"רב בסעלץ."},{"i":9088,"n":"בצלאלש, יצחק","b":"ראש גאוני דורו,מרביץ תורה,רב בלאדמיר-ש\"כ"},{"i":9089,"n":"בק אשכנזי, משה מאיר מירושלים","f":"שמואל ב\"ק","b":"מחכמי ירושלים, בשנת שכו ובשנת שנד חתם על תקנות הקהלה. יתכן שזהו ר משה אשכנזי המוזכר ב\"חרבות ירושלים\" בזמן פרעות אבן פארוך בשנת שפה, ויתכן שהוא אותו הרב."},{"i":9090,"n":"בק, אברהם מגורליץ","b":"רב בגורליץ-תרמח."},{"i":9091,"n":"בק, אברהם מהאליטש ולינדנבורג","k":"בעל אבני זכרון","dt":"תריא - יג שבט","b":"רב בלינדנבורג, קסטל, האליטש(=הליטש). נספד ב\"לקוטי חבר בן חיים\" - פרשבורג תרלח. חתנו - ר יחזקאל דייטש בן ר דוד בעל אוהל דוד."},{"i":9092,"n":"בק, אלכסנדר סנדר מהולשיץ","b":"רב בהולשיץ-תרפז, שו\"ב ברישא. מכתב לטובת הרבי מבלז נדפס ב\"העדות והמשפטים\"."},{"i":9093,"n":"בק, בנימין מליטא וארה\"ב","f":"זאב","k":"בנימין נאבלעד","bt":"תרנב","bp":"נאבלע-פלך מינסק","b":"תלמיד ישיבת פאהאסט-ליד פינסק, שקלוב אצל ר מאיר שקלוב, ור פסח פרוסקין והתגורר בביתו, ישיבת שטוצין אצל ר ליב חסמאן, ור אלתר-\"דער ליוביטשר עילוי\", סלובודקה, נוברדוק. נסמך מאת: ר משה מרדכי אפשטין, ר פסח פרוסקין, ר קרקובסקי מנוברדוק. רב בכמה קהלות באירופה, היגר לארה\"ב וסירב לשמש כרב. פרסם מאמרים ב\"פרדס\", ועוד. מראשי \"המזרחי\" בליטא-תרף, חבר אגודת הרבנים באמריקה, ונשיא אגודת \"מזרחי\" בקראון הייטס, ומנהל הת\"ת."},{"i":9094,"n":"בק, הירש מסאגאד","b":"רב בקהילה הניאולוגית בסאגאד-מחוז צ'ונגראד. בקי בעברית. לוחם נגד המחדשים בדת ונגד מחללי שבת."},{"i":9095,"n":"בק, הניך מפרשבורג","b":"מתומכי אגודת \"מבקשי תורה\" בפרשבורג-תרעו."},{"i":9096,"n":"בק, חיים נחום מירושלים","b":"תלמיד ישיבת \"ר ישראל אמריקנר\" בירושלים. פרסם מאמרים ב\"קובץ חדושי תורה\" - ירושלים תרצה."},{"i":9097,"n":"בק, יהודה מוילנא","k":"בעל עץ יהודה","bt":"1819","bp":"וילנא","dt":"1900","dp":"חרסון","b":"משכיל, וחוקר בוילנא, מלמד בביהמ\"ד לרבנים בוילנא-1848. הוריש את ספרייתו ל\"ספריית שטרשון\" בוילנא."},{"i":9098,"n":"בק, יוסף מסיגט","f":"אברהם","dt":"תשה - ח שבט","b":"חתן ר מאיר דוד טאבאק מסיגט, דיין בסיגט על מקום חותנו. חיבר הערות והוספות לספר אחיו ר אהרן צבי - \"מצח אהרן\". נספה בשואה."},{"i":9099,"n":"בק, יוסף מקולבסוב","b":"ממשתתפי \"קהילת אשר לנדא\"."},{"i":9100,"n":"בק, יעקב זאב מקרוטושין","b":"מחכמי קרוטושין-תרנט. ממשתתפי \"אהל מועד\"."},{"i":9101,"n":"בק, יעקב חיים","f":"אברהם בק","b":"רב בווערבווצי-תר\"י"},{"i":9102,"n":"בק, יעקב ממיץ (רישר)","f":"יוסף רישר מפרג","k":"בעל חק יעקב","bp":"פרג","dt":"תצג - ה-ט שבט","dp":"מיץ","b":"חתן ר בנימין וולף שפירא. רב בפרג, וורמייזא-תעה וראש ישיבה, אב\"ד מיץ, ור יעקב יהושע פאלק בעל \"פני יהושע\" על מקומו אחריו (גם ר יונתן איבשיץ היה מועמד לשבת על מקומו). מחותן עם הגביר ר יוזפא מדיסלדורף, בנו ר שמעון מהר\"ש."},{"i":9103,"n":"בק, יעקב משה מאפשא","k":"בעל חמדת משה","b":"רב באפשא, ניו יורק."},{"i":9104,"n":"בק, יצחק ממאסיף","f":"אברהם","dt":"תשד","b":"חתן ר יחזקאל וידמן מסיטשל(סיצ'ל). רב בסיצ'ל לצד חותנו. רבה האחרון של מעסיעף(=מאסיף)-מארמרוש-תרצז. נספה בשואה. הו\"ל \"מצח אהרן\" לאחיו ר אהרן צבי."},{"i":9105,"n":"בק, ישראל מירושלים","f":"אברהם","bt":"תקנב","bp":"ברדיטשוב","dt":"תרלה - א כסלו","dp":"ירושלים","b":"חסיד ר ישראל מרוזין. עלה לצפת-תקצא והקים בית דפוס, לאחר הרעש-תקצז עבר לג'רמק, ולירושלים-תר. בנו ר ניסן. חתניו - ר יצחק רוקח, ר ישראל דב פרומקין בעל החבצלת."},{"i":9106,"n":"בק, מאיר מבוקרשט","b":"רב ניאולוגי בבודפשט. הסכים על \"בית ועד לחכמים\" - יאסי תרסט."},{"i":9107,"n":"בק, מאיר מלמברג","b":"עבר מלמברג להרימלוב. תשובה אליו בטוט\"ד."},{"i":9108,"n":"בק, מנחם מנדל מקרומוני","f":"אברהם מלונדנבורג","bp":"לונדנבורג","dp":"פרייטשטט","b":"תלמיד החת\"ס. רב בקרומוני-תקצב, עבר לליסא לצד בנו ר שמואל האב\"ד."},{"i":9109,"n":"בק, מרדכי מאונגריש בראד","b":"תלמיד החת\"ס, והכת\"ס. נספד ב\"ברכת יצחק\"."},{"i":9110,"n":"בק, ניסן מירושלים","f":"ישראל","bt":"תקעג-ה","bp":"ברדיטשוב","dt":"תרן - ח-י כסלו","dp":"ירושלים","b":"עלה לארץ-תקצא. ראש הישוב החסידי בירושלים על מקום אביו. נסע אל ר ישראל מרוזין ובנו ר אברהם יעקב מסדיגורא. הקים את בית הכנסת החסידי הגדול \"תפארת ישראל\" שכונה על שם רבו. והיה שותף לבניית שכונות ובתי כנסת בירושלים."},{"i":9111,"n":"בק, נפתלי הרץ מבלז","f":"שלום","bt":"תרנג","dt":"תשג","b":"מחכמי בלז, החזיר בתשובה את אחיו ר משה. רב בלוביטש-תרפד. נספה בשואה. אחיו ר מאיר רב בלובטיש."},{"i":9112,"n":"בק, נתן מקראמוי","f":"אברהם מלונדנבורג","b":"רב בקראמוי-תר\"כ"},{"i":9113,"n":"בק, פאלק מניקלשבורג","b":"ראש קהילת ניקלשבורג - תקן-תקס, עמד מאחורי מינוי ר מרדכי בנט לרב בניקלשבורג."},{"i":9114,"n":"בק, קלמן זאב מקורטשין","b":"רב בקורטשין, קהל יראים בקעלין. תשובה אליו במהרש\"ם."},{"i":9115,"n":"בק, שמואל מטריטש","b":"מחכמי טריטש-תקס בערך, נזכר ב\"עמודי שיטים\" לר לוי פולק מטריטש."},{"i":9116,"n":"בק, שמואל מליסא","f":"מנחם מנדל מקרומונוי","k":"בעל יסודות התורה","bt":"תקצד","bp":"קרומונוי","dt":"תרעב - כט אייר","dp":"ליסא","b":"שם אביו לפי \"אהלי שם\" - נתן. תלמיד הכת\"ס, ור שמשון ב\"ר רפאל הירש מפפדמ, ביהמ\"ד לרבנים בוינה. חתן ר אברהם פלאטשעק מבסקביץ ורב המדינה במעהרין. רב בשאפא-תריט, בעהמישע-לייפא-תרך, ליסא-תרכב. בנו - ד\"ר ליאו בק מברלין. חיבר \"הקדמונים והעבריים\", \"יסודות התורה\", ועוד."},{"i":9117,"n":"בק, שמואל מסמיחאוו","f":"ליב משוראן","k":"בעל מעיל קטן","bt":"תרא","bp":"פריישטט","dt":"תרנט - כ סיון","dp":"פרג","b":"תלמיד הכת\"ס, ור חזקיה פיבל פלויט משוראן.רב ומטיף בלייטמאריץ, סמיחאוו-תרלג, ומורה דת בפרג."},{"i":9118,"n":"בק, שמואל משוראני","dt":"תר - יז תמוז","b":"רב בשוראני"},{"i":9119,"n":"בק, שמעון מאיטליה וצפת","b":"מחכמי צפת, עלה מאיטליה בשנת שמב ולמד קבלה אצל ר יוסף מוגרבי תלמיד הארי. כתב אגרות למשפחתו באיטליה בשנים שמב - שמז. עבר לירושלים בשנת שמד. אגרותיו פורסמו ב\"ירושלים\" ו\"המעמר\"."},{"i":9120,"n":"בק, שמעון מלבוב","f":"בנימין בינוש ליפשיץ","b":"מגדולי מרביצי התורה בלבוב-ת\"ל"},{"i":9121,"n":"בק, שמשון מירושלים","f":"שמואל","k":"בעל אגרות ר שמשון בק","b":"מגורי האר\"י, ותלמיד ר יוסף ן טבול (תלמיד האר\"י). רב בקהלת האשכנזים בירושלים-שן, חתם עם ר שמעון אנסבורג. נזכר אצל היש\"ר מקנדיא. אגרותיו מהשנים שמב-שמד התפרסמו ב\"ירושלים\" וב\"המעמר\". חיבר גם \"סדר האצילות\". אחיו - ר משה מאיר."},{"i":9122,"n":"בקאבין, יוסף","f":"יעקב","b":"תשובה ממנו ב\"חכם צבי\"."},{"i":9123,"n":"בקארי, אברהם מצפת","b":"מקובל בצפת, תלמיד האר\"י."},{"i":9124,"n":"בקבוק, ישכר ממצרים","b":"מחכמי מצרים-רפ - מקהלת המערבים, בזמן הרדב\"ז."},{"i":9125,"n":"בקון (ר\"ת -בני קדושים וטהורים)"},{"i":9126,"n":"בקון, חיים מדעש","f":"יצחק מקולבסוב","b":"חזן בדעש, ברלין וקלויזנבורג. בנו החזן ר שלמה ראובן."},{"i":9127,"n":"בקון, יהודה (יידל) מלנצהוט","dt":"תשיד","b":"חזן בלנצהוט, לייפציג. ניצל מהשואה ועבר לניו יורק שם כיהן כחזן."},{"i":9128,"n":"בקון, יצחק מקולבסוב","b":"אבי משפחת החזנים מקולבסוב."},{"i":9129,"n":"בקון, יצחק מקשנוב ובאר שבע","f":"צבי יהודה הרש מקשנוב","bt":"תרעט","b":"תלמיד ישיבת \"כתר תורה\". ניצל מהשואה. חזן בקשנוב. עלה לארץ והיה ראש הקתדרה לאידיש באוניברסיטת באר שבע. העלה על הכתב מנגוני אביו. וחיבר על אביו - \"החזן ר הירש ליב בקון\" תשנא."},{"i":9130,"n":"בקון, ישראל מברלין וקראקא","f":"צבי יהודה הרש מקשנוב","bt":"תרסט","dt":"תשג","b":"חזן בקאשוי, ברלין, קראקא. נספה בשואה."},{"i":9131,"n":"בקון, משה ממיץ","f":"צבי יהודה הרש מקשנוב","bt":"תרסג","dp":"צרפת","b":"השתתף במקהילת אביו בברלין. חזן במיץ. ניצל מהשואה."},{"i":9132,"n":"בקון, צבי יהודה הירש","bt":"תרלה","b":"למד בטרנוב. חתן ר יוסף שמעיה מצאנז. הקים מקהלה וחיבר לה ניגונים. חזן בקשנוב-תרסה. (חיבר מאות ניגונים על \"לכה דודי\"). חזן בברלין-תרעט יחד עם בנו ר ישראל. חזר לקשנוב-תרפד. חסיד בובוב וממקורבי רד\"ב מטשבין. השאיר חדושי תורה - בכת\"י."},{"i":9133,"n":"בקון, שלמה ראובן מלונדון","f":"חיים מדעש","bt":"תרנט","bp":"שצקובה","dt":"תשמו","b":"חזן בלונדון וביוהניסבורג. (בצעירותו שר באופרה בקלויזנבורג - שם השליכה מלכת רומניה לעברו פרח - וכך נודע הדבר לאביו החזן ובקשו להתפטר, ומאז עסק רק בחזנות)."},{"i":9134,"n":"בקורה, יעקב ממצרים (רומנו)","f":"יצחק","k":"בעל מאזני משפט","bt":"שמ","bp":"קושטא","dt":"תי","dp":"ירושלים","b":"ביבליוגרף וסופר, בלשן בלשונות ערבית, תורכית ורומית. חיבר ספרי ביבליוגרפיה (והשתמש בהם בוקסדורף בספרו). ניסה להקים בית דפוס בקושטא. לדעת איזנשטין המדובר בר יעקב רומנו."},{"i":9135,"n":"בקוריה, יצחק אברהם מטבריה","b":"מחכמי טבריה, בשנת תריז בשליחות בצפון אפריקה. בשנת תרלד חתם בקונטרס \"כנסיה לשם שמים\"."},{"i":9136,"n":"בקי, יוסף אליעזר מרדומסק","dt":"תשג","b":"דומ\"צ ברדומסק"},{"i":9137,"n":"בקירשטיר, יצחק מיאסי","f":"מרדכי","b":"ראש ומנהיג קהל \"עדת ישורון\" ביאסי."},{"i":9138,"n":"בקיש, יוסף מפאס","b":"מחכמי פאס, אולי אחיו או בנו של ר ישעיה."},{"i":9139,"n":"בקיש, ישעיה מפאס","b":"תלמיד ר יהודה עוזיאל. מו\"ץ ומקובל בפאס-שע עם ר\"ש ן דנאן, ר וידאל הצרפתי, ר\"ש ן חביב, ר\"ש סירירו. תלמידו - ר יוסף בן שמואל שהו\"ל את ספר הישר - ונציה שפה. כתביו בקבלה אבדו."},{"i":9140,"n":"בקיש, נסים מוידין","b":"רב בוידין, נזכר ב\"מזכרת משה\"."},{"i":9141,"n":"בקל, עובדיה מברודשין","b":"דיין בברודשין-תרלא. תשובה אליו ב\"בית שלמה\"."},{"i":9142,"n":"בקמייסטר, ישראל","f":"משה חיים אלתר","bt":"תרלז","bp":"קיעלץ","dt":"תשטו","b":"מגיד מישרים באירופה, עלה לארץ, חזר לאירופה, ושוב עלה וכיהן כראש ישיבת \"תפארת ישראל\" בתל אביב. חיבר ספר זכרונות - בכת\"י."},{"i":9143,"n":"בקנרוט, אברהם יוסף","f":"דובריש מסכודניצה","dt":"תרצד","b":"גביר מחסידי צורטקוב. חתן ר משה יצחק הכהן הלר (נכד הקצות)."},{"i":9144,"n":"בקנרוט, אלימלך שרגא מבוריסלב","f":"דוד צבי","bp":"דרוהוביטש","dt":"תשא","b":"גביר בעל בארות נפט בבוריסלב. חסיד צורטקוב."},{"i":9145,"n":"בקנרוט, דובריש מסכודניצה","b":"חתן ר הרצל לנדוי (ונקרא עם רעייתו - זוג הזהב - כי אחרי אירוסיו מצא חותנו קידוח נפט והתעשר), עבר לדולינא. רב בסכודניצה. תלמיד ר יהושע פנחס בומבך בדרוהוביטש. רבו השיב לו ב\"אהל יהושע\"."},{"i":9146,"n":"בקנרוט, יוסף צבי","bt":"תרסד","b":"היגר מגליציה לארה\"ב-תרץ, עבר לארגנטינה ליד בתו וחתנו - ר יחזקאל מושייבסקי מארגנטינה. עלה לארץ-תשלג."},{"i":9147,"n":"בקנרוט, יצחק מסכודניצה","b":"חתונו של ר אברהם יוסף גרינולד (בן \"ערוגות הבושם\")."},{"i":9148,"n":"בקר יעקב","bt":"1902","dt":"ה'תשכו 1966","bk":[["חכמת החיים של עם ישראל",""]]},{"i":9149,"n":"בקר, דב זונדל מפאגיר","f":"אפרים יצחק","bt":"תרטו","b":"רב בפאגיר-פלך קובנא-תרמ."},{"i":9150,"n":"בקר, זונדל","bp":"תרכ\"ה","dt":"תרפט - ב טבת","b":"רב בפאגר,עלה לא\"י"},{"i":9151,"n":"בקר, חיים מלנצק","f":"אלתר","k":"בעל שערי חיים","bt":"תרל","bp":"מישלניץ","dt":"תרפב","b":"חסיד ר משה מברדיוב. אב\"ד לאנצק. חתן ר צבי אלימלך בלייך אב\"ד לאבאווא. חתנו ר מאיר רפאל בוימל ישב על כסאו אחריו. חיבר \"שערי חיים\" ניו יורק תשלז."},{"i":9152,"n":"בקר, יוסף מבוכניה","f":"עוזר","dt":"תרנג","b":"רב בבוכניה."},{"i":9153,"n":"בקר, יעקב מארה\"ב","f":"ישראל","bt":"תרכג","bp":"ועקסנע-פלך קובנא","b":"תלמיד ישיבת ועקסנע(=ואקשנא) אצל ר משה פלס, ישיבת סלובודקה אצל ר יצחק בלזר. נסמך מאת: ר צבי יעקב אופנהיים. חתן ר ברוך יצחק הלוי. ר\"מ בקעלם, רב בנאווא-אדעס-פלך חרסון, היגר לארה\"ב וכיהן כרב בקהלת \"חברה תהלים בני ישראל\" בפילדלפיה. חבר אגודת הרבנים בארה\"ב."},{"i":9154,"n":"בקר, יעקב מנרול","b":"מחכמי נרול - תשובה אליו ב\"אמרי כהן\"-תרצו."},{"i":9155,"n":"בקר, מנחם מסניאטין","k":"בעל פרפראות לתורה","bt":"תרפג","bp":"סניאטין","b":"עלה לירושלים. בוגר סמינר מזרחי. עסק בהוראה וכתיבת ספרי לימוד. בעל תכנית יהדות ברדיו. חיבר \"פרפראות לתורה\"."},{"i":9156,"n":"בקר, תנחום בנימין מאוזרוב","f":"דוד אליהו","k":"אדמור מאוזרוב בת\"א","bt":"תשי","b":"נכד ר משה יחיאל אפשטין מאוזרוב. חתן ר משה יעקב בורק מטורונטו. אדמור מאוזרוב בתל אביב."},{"i":9157,"n":"בקרי, דוד הכהן מאלגיר","f":"שמואל","k":"דוד הכהן בוזי","bt":"קע","dt":"רן - בערך","b":"מצאצאי ר שאול אשתרוק הכהן - אולי נכדו. מגדולי תלמידי הרשב\"ש בישיבה באלגיר. דיין בבג'איה-אלגיר. התכתב עם רבו שהזכירו רבות בספרו, ואח\"כ עם בנו ר צמח."},{"i":9158,"n":"בקרי, יוסף הכהן מאלגיר","f":"יעקב","dt":"תקעא","b":"נגיד הקהלה באלגיר-תקסו על מקום אביו. נאסר לאחר הלשנה ונהרג עק\"ה ע\"י השליט התורכי."},{"i":9159,"n":"בקרי, יעקב הכהן מאלגיר","dt":"תקצה - בערך","b":"נגיד הקהלה באלגיר-תקעה, לאחר הכיבוש הצרפתי תקץ - חודש המינוי וכיהן כראש האומה היהודית באלגיר."},{"i":9160,"n":"בקרי, משה הכהן מאלגיר","bt":"שי","dt":"שף - בערך","b":"רב בבג'איה-אלגיר, מיליאנה-אלגיר. שאלה ממנו לר אברהם ן טוואה ונזכר ב\"חוט המשולש\"."},{"i":9161,"n":"בקרי, שמואל הכהן מאלגיר","f":"דוד מאלגיר","bt":"רל - בערך","dt":"שי - בערך","b":"רב בבג'איה-אלגיר, מקורב לר שמעון בן הרשב\"ש. אולי הוא הנזכר ב\"חוט המשולש\" שעמד לדין לפני הרב המחבר - ר אברהם ן טוואה."},{"i":9162,"n":"בקשט, אהרן דוד","f":"משה","k":"בעל פעולות אדם","b":"רב בליובטש-תר\"ל"},{"i":9163,"n":"בקשט, אהרן יוסף מליטא","bt":"תרכז","bp":"איווייה-ליטא","dt":"תשא - טז תמוז","dp":"שאוולי","b":"תלמיד ישיבות וולוזין, סלובודקה. נטה לתנועת המוסר של קעלם. רב בביסגולה-תרנז על מקום ר שמואל אביגדור פיבלסון ור אברהם יצחק בן שמואל אביגדור על מקומו אחריו, סמיטיץ, צרצין, שאדובה-עד תרעה והקים בה ישיבה, עם גירוש היהודים שם במלחה\"ע ה-I נדד לרוסיה והיה רב בטולא ופולטאבה, חזר לליטא-תרפב וכיהן כרב בסובאלק, לומזה-תרפה ונאלץ לעזוב בגלל התנגדותו לציונות, רבה האחרון של שאוולי-תרץ. נספה בשואה."},{"i":9164,"n":"בקשט, אריה ליב","bt":"ה'תרעח","dt":"ה'תשסד","b":"ניצל מהשואה והגיע לשנחאי-סין. פרסם מאמרים ב\"מאור תורה\" - שנחאי-סין תשד - קובץ תלמידי ישיבת מיר בשנחאי, \"התבונה\" - נ\"י תשז - קובץ תלמידי ישיבת מיר.","bk":[["קול אריה",""]]},{"i":9165,"n":"בקשטנסקי, אליעזר מפינסק","f":"נחום מייזל מלובטש","b":"תלמיד ר יהונתן משה וואלינער בעל \"מרגניתא טבא\""},{"i":9166,"n":"בקשטר, חיים"},{"i":9167,"n":"בקשטר, שמואל מלובטש","bt":"תקמג","dt":"תרלו","b":"תלמיד ר חיים מוולוזין (כנראה עוד קודם ליסוד הישיבה-תקסג). מחכמי לובטש-פלך נוברדוק. חתניו: ר יהונתן משה וואלינער מלובטש, ר אברהם דב מרגליות מרדישקוביץ, ר נחום מייזל מלובטש-אחיו של ר אליהו חיים."},{"i":9168,"n":"בר אדון, יוסף משלוניקי","dt":"תקפד","dp":"שלוניקי","b":"דרשן ומספיד, אב\"ד בשלוניקי-תקנה - מומחה לדיני חזקות ונזקי שכנים. חיבר שו\"ת בכת\"י ונזכר אצל חכמי דורו, הספיד את ר שלמה בולה ב\"לחם שלמה\"."},{"i":9169,"n":"בר אדון, יחיאל מירושלים","dt":"תשג","b":"דיין בירושלים-תרנה אצל ר רפאל יצחק ישראל יחד עם ר אברהם מבורך. גיסו של ר יוסף שלום בן עבדאללה מחברון."},{"i":9170,"n":"בר אדון, ראובן","dt":"תרפא - כט אד\"ב","dp":"ירושלים","b":"מחכמי ירושלים, נתמך בידי הגביר רחמים מזרחי."},{"i":9171,"n":"בר אילן מאיר","bt":"1880","dt":"ה'תשט 1949","bk":[["רבן של ישראל",""]]},{"i":9172,"n":"בר בונדר, חסן(יפת)","k":"שר הקהילות","b":"מחכמי תימן,הנגיד הראשון ליהודי תימן בעדן"},{"i":9173,"n":"בר גיאון, יהודה","b":"מגדולי חכמי דורו במרוויקוס-שנת ל'"},{"i":9174,"n":"בר דוד, חייא מאיר","b":"מחכמי איטליה בטורקיה,דיין,רב בפטרץ"},{"i":9175,"n":"בר הלל, אברהם","b":"פייטן, משורר, מחכמי מצרים"},{"i":9176,"n":"בר זכאי, דוד","b":"מחכמי בבל, ראש גלות בבל, היתה לו מחלוקת עם ר' סעדיה גאון"},{"i":9177,"n":"בר זכרי הרופא ממצרים","b":"רופא מחכמי מצרים בזמן הרדב\"ז."},{"i":9178,"n":"בר יוסף, אהרן מבבל","dt":"ד'תשיט","b":"מחכמי בבל, ראש ישיבת \"גאון יעקב\" בפומבדיתא\""},{"i":9179,"n":"בר כודדת, יוסף","b":"מרביץ תורה בקווקז-תר\"נ"},{"i":9180,"n":"בר מזאר, אברהם","b":"מחכמי ספרד, תלמיד הרא\"ש"},{"i":9181,"n":"בר מיכאל, אליעזר ממצרים","b":"מחכמי מצרים"},{"i":9182,"n":"בר משה, אברהם מספרד","b":"מחכמי ספרד, תלמיד הרא\"ש"},{"i":9183,"n":"בר עובדיה, אברהם מספרד","b":"מחכמי ספרד, דיין, אבי סבו של הרמב\"ם"},{"i":9184,"n":"בר שאול, אלימלך","dt":"תרלח - כב תמוז","b":"פרסם מאמרים ב\"שילה\" - ירושלים תשה."},{"i":9185,"n":"בר תמר, אפרים","b":"מגדולי הראשונים,מרביץ תורה בפפד\"מ-ד'תתנ\"ו"},{"i":9186,"n":"בר, הרמן מניו יורק","bt":"תקפו","bp":"שטטהאגן","b":"תלמיד ביהמ\"ד למורים ביענא. מורה בזיעזען, ליברפול-אנגליה, היגר לאמריקה והיה מנהל בית היתומים היהודי בניו יורק. חיבר ספרים בתולדות ישראל - באנגלית - בכת\"י."},{"i":9187,"n":"בר, זאב וולף מאיסטריק","f":"יחיאל צבי הירש","dt":"תש..","b":"רב באיסטריק. חתן ר זישא טרטנר. נספה בשואה."},{"i":9188,"n":"בר, יהודה מפפד\"מ","f":"נפתלי הרץ פער מברלין","dt":"תקכד - סיון","dp":"פפד\"מ","b":"פרנס בפפד\"מ. שם משפחתו הפך לבער (במקום פער). חתן ר יצחק שאול בן שמואל זנויל מפפד\"א. בנו ר יהודה בער - ושם המשפחה בהמשך הפך לביר."},{"i":9189,"n":"בר, יואל מסן פאולו","f":"יעקב שלמה מוינה","k":"אדמור מרצפערד","bt":"תרפב-ג","bp":"וינה","dt":"תשנג-ח","dp":"ברזיל","b":"תלמיד ה\"דמשק אליעזר\" בויזניץ. הגיע לאנגליה-תרצח, ארה\"ב-תשא. רב בניו יורק. חתן ר משולם זושא בן ר שלום אליעזר הלברשטם מרצפרט. נתמנה לאדמור ע\"י הרבי מסטמר - על מקום זקנו. אדמור מרצפערד בסן פאולו-ברזיל - תשיח, בנו ר משולם זישא אדמור על מקומו אחריו. חתניו: א. האדמור מקרטשנוף-רחובות, ב. האדמור מקרלסבורג-מונטריאול, ג. האדמור מטשרקס-מונסי, ד. הרב שנבלג מאדגווד-אנגליה. ה. האדמור מקליבלנד-ויליאמסבורג. ו. רח,א וייס ממונסי. ז. ר\"מ שנבלג מויליאמסבורג. ח. האדמור מאולינוב-סן פאולו ר יצחק דוד הורביץ."},{"i":9190,"n":"בר, יוסף ברוך מוידאמא פשדבורז","f":"ישעיה מוידאמא","k":"אדמור מוידאמא בפשדבו","dt":"תש..","b":"חתן ר ליביש מטומשוב (שושלת רופשיץ). רב ואדמור בפשדבורז-תרצד. נספה בשואה."},{"i":9191,"n":"בר, יוסף מטרנוב","dt":"תרנב - בערך","b":"מחכמי טרנוב - תשובות אליו תרלט-תרנא בספרי השו\"ת."},{"i":9192,"n":"בר, יחיאל צבי הירש מהוסקוב","f":"ישכר דב","bt":"תרנג","dt":"תשג","b":"רב במעדיקה (ליד פשמישל), רב בהוסקוב (והיה שם מחלוקת עם ר יצחק טיטלבוים) וגבאי ארץ ישראל. חתן ר יעקב שלום הרציג אב\"ד ניזנקוביץ. נספה בשואה."},{"i":9193,"n":"בר, יעקב שלום מניזנקוביץ","bp":"קרוסנא","b":"רב בניזנקוביץ בין שתי מלחמות העולם."},{"i":9194,"n":"בר, יצחק יהודה מרעדים","f":"יעקב יהושע","bt":"תרכה","bp":"קרוסנא","dt":"תרצה","dp":"וינה","b":"חתן ר פישל וולוסקר מלינסק."},{"i":9195,"n":"בר, יצחק צבי מליטוביסק","f":"פנחס אלימלך","bt":"תרם","dt":"תשג","b":"רבה של ליטוביסק על מקום אביו. חסיד בובוב."},{"i":9196,"n":"בר, ישכר בער מדאברי","f":"צבי מאיר - אמרי הצבי","dt":"תש..","b":"נכד ר ישכר וינגוט מטשנסחוב. רב בדאברי-תרעו על מקום אביו. נספה בשואה. מתורתו בספר אביו - אמרי הצבי. גיסו - ר אברהם בנימין זילברברג מפיטסבורג."},{"i":9197,"n":"בר, ישכר דב בר מליטוביסק","f":"נפתלי","k":"אדמור מנייטרא","bt":"תרלג","dt":"תשג","b":"אב\"ד ליטוביסק על מקום אביו, רב ואדמור בנייטרא. בנו ר שמואל זנויל אב\"ד מקוב (ליד קראקא)."},{"i":9198,"n":"בר, ישכר דב בריש מליטוביסק","f":"שמואל זנויל מליטוביס","k":"אדמור מאיסטריק וליטו","bt":"תקן","dt":"תריט - ה תמוז","dp":"ארץ ישראל","b":"תלמיד ר נפתלי צבי מרופשיץ. חתן ר אלעזר רוקח - נכד ה\"מעשה רוקח\". רב ואדמור בליטוביסק ובאיסטריק על מקום אביו. עלה לארץ. בניו ר נפתלי על מקומו בליטביסק ור משה אבא על מקומו באיסטריק. חתנו ר ישעיה זלמן קלך עלה לצפת."},{"i":9199,"n":"בר, ישעיה מוידאמא","f":"קלונימוס קלמן מוידאמ","k":"אדמור מקילץ","dt":"תש..","dp":"קילץ","b":"חתן ר אליעזר מחנטשין (שושלת לובלין). אדמור על מקום חותנו בקילץ. נספה בשואה."},{"i":9200,"n":"בר, משה אבא מאיסטריק","f":"ישכר דב בריש מליטובי","k":"אדמור מאיסטריק","bt":"תקעה","dt":"תרמ","b":"חתן ר יוסף ברוך עפשטיין ה\"יהודי הטוב\" מניישטט. רב ואדמור באיסטריק על מקום אביו, וחתנו ר יהודה ליביש דומיניץ מברזוב על מקומו אחריו באיסטריק, חתנו השני ר ישראל הורביץ מוייסליץ."},{"i":9201,"n":"בר, נפתלי מליטוביסק","f":"ישכר דב בריש מליטובי","bt":"תקף","dt":"תרצא - כח טבת","b":"חתן ר אליעזר ליפא אלוביץ מזבורוב(=זבראז)-הונגריה-נכד ר אלימלך מליזנסק. אב\"ד ליטוביסק."},{"i":9202,"n":"בר, פנחס אלימלך מליטוביסק","f":"נפתלי בער מליטוביסק","bt":"תר-תרך","dt":"תרף","b":"אב\"ד ליטוביסק-תרס על מקום אביו, חתנו ר מאיר ויינברגר מילא את מקומו אחריו. פרסם מחאה ב\"במחז\"ה\" - על שראשי הקהל פרסו מכרז לרב."},{"i":9203,"n":"בר, צבי יהודה מפרשבורג","f":"ישכר דב","bt":"תריח","bp":"סימערינג","dt":"תשג - כח סיון","dp":"פרשבורג","b":"תלמיד השב\"ס. מחכמי פרשבורג. מתורתו (באגדתא) בספר \"אהל מועד\" לר אברהם ביק."},{"i":9204,"n":"בר, צבי מאיר מדאברי","f":"יוסף","k":"בעל אמרי הצבי","r":"רב בדאברי","bt":"תרה","dt":"תרעו - כ אד\"ב","b":"חתן ר ישכר וינגוט אב\"ד טשנסטוכוב בעל \"פתחי שערים\". רב בניישטט-תרכו, סומפולני, דאברי (פולין)-תרם ובנו ר ישכר בער על מקומו אחריו. חיבר \"אמרי הצבי\" וארשא תרמח, ועוד.","bk":[["אמרי הצבי – ב\"ק וקנינים",""],["גרגירי כסף – בראשית",""]]},{"i":9205,"n":"בר, קלונימוס קלמן מוידאמא","f":"משה אבא מאיסטריק","k":"אדמור מוידאמא איסטרי","bt":"תריג","dt":"תרפח - י סיון","b":"חתן ר עמנואל מפשדבורז. רב ואדמור בוידאמא."},{"i":9206,"n":"בר, שלום מדובצק","b":"רב בדובצק-תרמט, טשילקא-תרפב."},{"i":9207,"n":"בר, שמואל זנויל מליטוביסק","f":"יצחק צבי ברווער","k":"אדמור מאיסטריק","bt":"תקכ","dt":"תקצז - כז תמוז","b":"בראווער היה שמו ושינהו לבר. כינויו - \"ר זאנויל חריף\". תלמיד חבר לחוזה מלובלין. רב ואדמור בליטוביסק ובאיסטריק הסמוכה - היה היהודי הראשון באיסטריק. הניח חיבור על הש\"ס וציוה שלא להדפיסו. מחדושיו בספר \"סמוכים לעולם\". אביו ר יצחק צבי בן ר ישכר בר מלינסק חיבר \"אלף המגן\" על מגן אברהם - ולא נדפס כי קדמו \"מחצית השקל\"."},{"i":9208,"n":"בר, שמואל זנויל ממאקוב","f":"ישכר דב בר","b":"רב במאקוב-גליציה. חתן ר נתן דוד הולנדר מאמסנא. וגיסו ר שמואל הולנדר הזכיר אותו ואת בנו - ר חיים יוסף - בספרו \"ש\"ם הכהן\"."},{"i":9209,"n":"בר-יקר, יעקב","k":"רבו של רש\"י","dt":"ד'תתכד","b":"מגדולי חכמי התורה הראשונים,רב במגנצא,וורמייזא"},{"i":9210,"n":"בר-שאול, אלימלך","k":"בעל הגות לב","r":"רב בישוב שדה יעקב, משגיח בישיבת הדרום, ואח\"כ רב ברחובות","bt":"תרעג","dt":"תשכה","b":"משפיע,מחנך,רב בשדה יעקב,רחובות","bk":[["מן הבאר - שיחות לפרשת שבוע",""],["מערכי לב - דברי תשובה לצעירים בענייני השקפה",""],["מצוה ולב - בירור דברי הגות",""],["ריח מים - רשמי עיון במקראות ובמדרשות",""]]},{"i":9211,"n":"ברא די, משה הכהן מג'מיקה","dt":"תקח","dp":"[ג'מיקה]","b":"רב בג'מיקה-תעג, על מקום ר יאשיהו פארדו, במשך כ-35 שנה."},{"i":9212,"n":"ברא\"ד, שלמה זלמן סגל מברדיטשוב","b":"רב בברדיטשוב. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד."},{"i":9213,"n":"בראהן, יצחק איצא מאושיקוב","f":"אברהם","bt":"תרלו","b":"רב באושיקוב-פלך קאליש-תרסט."},{"i":9214,"n":"בראהן, שמואל שלמה מליקובא","b":"פרסם מאמרים ב\"מציון תצא תורה\" - זאמושט תרפט."},{"i":9215,"n":"בראווע, יצחק משה מקורקיל","bt":"תרל","b":"רב בקורקיל-פלך קובנא-תרנד. נסמך מאת: ר יצחק אלחנן מקובנא, ר שלמה הכהן מוילנא. בנו - ר יהודה."},{"i":9216,"n":"בראוין, ישראל מארה\"ב","b":"פרסם מאמרים ב\"כנסת ישראל\" - נ\"י תרצב - כתב עת הסתדרות תלמידי סלובודקה באמריקה."},{"i":9217,"n":"ברא\"ז, יוסף יעקב","f":"ראובן בן משה","b":"נינו של ר אלכסנדר זיסקינד בעל יסוד ושרש העובדה - ברא\"ז (=בן ר אלכסנדר זיסקינד). ביאור ממנו בספר גיסו ר צמח לנדא - \"עט סופר החדש\"."},{"i":9218,"n":"ברא\"ז, ישעיה","dt":"תקנח","b":"רב בזבארז,עבר לברודי"},{"i":9219,"n":"ברא\"ז, ליפמן","b":"חכמי ברודי"},{"i":9220,"n":"ברא\"ז, ראובן מויסאקי-דוואר","f":"שמעון","bt":"תרלה","b":"מצאצאי ר אלכסנדר זיסקינד בעל \"יסוד ושורש העבודה\" - ומכאן שם המשפחה (ר\"ת - בן ר אלכסנדר זיסקינד). רב בויסוקי-דבור(=ויסאקי-דוואר)-פלך וילנא-תרס, עלה לארץ-תרסב, ור מרדכי רבינוביץ על מקומו אחריו."},{"i":9221,"n":"בראזה, משה חיים מברוסה ירושלים","dt":"תקעז - כג תשרי","dp":"ירושלים","b":"מחכמי ברוסה, עלה לירושלים."},{"i":9222,"n":"בראזני, אברהם","f":"יעקב","b":"מקובל, מחכמי כורדיסטאן, רב בבגדד, חתן ר' יהודה משה פתייא, עלה לירושלים-תרצ\"ד"},{"i":9223,"n":"בראזר, משלם נתן מסוראקי","k":"בעל צדקת ציון","bt":"תרכב","bp":"ברדיטשוב","b":"מחכמי סורוקוה ועסק במסחר, מקורב לציונות. חיבר \"צדקת ציון\" - ברדיטשוב תרסג, \"חוקרי עם\" - בכת\"י."},{"i":9224,"n":"בראיו, מיכאל מפרטץ-יון","b":"רב ודיין בפטרץ-יון, עבר ללאריסה-תמה לאחר שפטרץ נכבשה בידי ונציה, והיה מראשי קהלת הפליטים בלאריסה."},{"i":9225,"n":"בראך, אלעזר מנייטרא","b":"חתן ר יעקב מאיר צבי פרידלנדר משוראן."},{"i":9226,"n":"בראך, אלעזר מקרולה","f":"שאול מקרולה וקאשוי","dt":"תש..","b":"חתן ר מנחם צבי רוזנבורג מנאדפאלו. רב בקרולה תחת אביו. נספה בשואה."},{"i":9227,"n":"בראך, נפתלי צבי","f":"שאול ברך","dt":"תשד","b":"רב במוגנדורף"},{"i":9228,"n":"בראך, שאול מנייטרא ממגנדורף","f":"אלעזר מנייטרא","k":"בעל שאול שאל","bt":"תרכה","bp":"נייטרא","dt":"תש - כו-ט שבט","b":"תלמיד בישיבת מהר\"ם שיק בחוסט, בישיבת בעל \"חתן סופר\" במטרסדורף. חתן ר נפתלי צבי קרויס באויהל. למרות ששמר על נוסח אשכנז היה מקורב לאדמורי סיגט, צאנז ובלז. רב וראש ישיבה במגנדורף-תרן, קרולה(=קראלי)-תרע וראש ישיבה חסידית שם, ור יואל מסטמר על מקומו אחריו, קאשוי-תרפה וראש ישיבה שם, קאשוי-תרפג. ביקר בארץ-תרסה, מתנגד לציונות וגם לאגו\"י. חיבר בעילום שמו \"משמרת אלעזר\" מונקטש תרנז. חיבר גם \"ליבא בעי\", \"שאול שאל\", ועוד. רבים מכתביו אבדו בשואה. נספה בשואה. הסכים על \"שערי אורה\" - מיהאלביץ תרץ-תרצד."},{"i":9229,"n":"בראך, שמואל מחוסט","dt":"תשד","b":"רב בחוסט"},{"i":9230,"n":"בראך, שמואל מניר-מאדא","k":"בעל דרך ימה","bt":"תריד","dt":"תרעט - כא טבת","b":"תלמיד מהר\"ם שיק. רב בנירמאדע-תרנד. הו\"ל ספר רבו - שו\"ת מהר\"ם שיק."},{"i":9231,"n":"בראנן, יעקב","b":"מגדולי חכמי דורו,מובהק בהוראה,דיין בנירברג,אויגשבורג-קע\"ב-קצ\"ח,בוכנברק,בר\"ד בערפורט"},{"i":9232,"n":"בראנץ, יוסף מטריפולי","bt":"תם","dt":"תקי","b":"רב וסופר בטריפולי. חתם בפנקס בי\"ד טריפולי."},{"i":9233,"n":"בראנץ, יעקב מלוב","f":"מבורך","k":"בעל מילי דאבות","dt":"תרעא","b":"נכד ר משה חדד בורתא. רב במצראתה-לוב. נפטר ללא ילדים. חיבר \"מילי דאבות\" ונדפס לאחר פטירתו ג'רבה תרעו."},{"i":9234,"n":"בראנץ, מבורך מבנגזי","f":"מוסא","k":"בעל יבורך גבר","bt":"תקף","bp":"לוב","dt":"תרלה-נד","b":"רב ומלמד לתלמידים בבנגזי. מתורתו ב\"באר לחי\" ליוורנו תרמח. חיבר הגדה \"ליל שימורים\" אלכסנדריה תרנו, \"יבורך גבר\" תונס תרנח."},{"i":9235,"n":"בראנץ, מרדכי מטריפולי","f":"שמעון","bt":"תרעז","bp":"טריפולי","dt":"תשנד","b":"תלמיד ר חואתו לוזון, ור יוסף זרוק. עלה לארץ וכיהן כרב בפרדס חנה."},{"i":9236,"n":"בראף, אליהו חיים מטורנא.","b":"רב בטורנא. פרסם מאמרים ב\"אסיפת חכמים\" - אושפצין תרצד."},{"i":9237,"n":"בראשי, יצחק","dt":"תשנה","b":"רב העדה הכורדית בישראל."},{"i":9238,"n":"בראשית, אברהם מירושלים","b":"מחכמי ירושלים. נזכר ב\"שפר חזקה\"-תקצב, אודות מכירת חזקת חצר לר נתן נטע בן מנחם מנדל. (ראה גם אברהם באראכאת)."},{"i":9239,"n":"ברבוט, חיים מאלגיר","f":"יוסף","b":"רב ודיין בתנס-אלגיר (לא העיר תונס), נזכר בשו\"ת הרשב\"ש, מאמר עליו ב\"ספונות\"."},{"i":9240,"n":"ברבי - משפחה","b":"מקור המשפחה בעיירה בארבי-ליד הלברשטט."},{"i":9241,"n":"ברבי, יוסף מירושלים","b":"מחכמי ישיבת אברהם מיוחס בירושלים-תקיח."},{"i":9242,"n":"ברבי, מאיר מהלברשטט ופרשבורג","f":"שאול מהלברשטט","k":"בעל חדושי מהרם","r":"אב\"ד פרשבורג","bt":"תפט","bp":"בארבי-ליד הלברשטט","dt":"תקמט - ה אב","dp":"פרשבורג","b":"תלמיד ר צבי הירש מהלברשטט, ר יעקב הכהן פופר מפפד\"מ בעל \"שב יעקב\". דיין אצל רבו בהלברשטט, וראב\"ד וראש ישיבה בהלברשטט-תצח כ-25 שנה, האללע, פרשבורג-תקכג על מקום ר יעקב יצחק דוקלא כ-26 שנה, ו ר משלם איגרא טיסמניץ על מקומו אחריו (יש שרשמו בטעות כי היה בנו). היה בקשרי הלכה וידידות עם ה\"נודע ביהודה\" - ופעם התלונן לפניו על שענה לשאלה שנשלחה אליו מאזור רבנותו-באזור פרשבורג - והנודע ביהודה התנצל שאינו בקי בגיאוגרפיה ולא ידע שזהו בתחומו. מתלמידיו: ר דוד דייטש בעל \"אהל דוד\", ר משה פרלס מקראלי, ר קאפל חריף מאלטנקונשטט, ר ישראל ורמן מפעשט, ר דניאל פרוסטיץ מפרשבורג, ר שלמה רוזנטל ור אליהו רוזנטל, ר בער מסט מיקולש, ר גץ שוערין מבאיא, ר מרדכי בנט, ר יצחק פרנקל, ר זליגמן זולצבך, ועוד. בתקופותו היתה מחלוקת בין שני ראשי הקהלה בין ר אברהם טעבן ור מנדל לייטרסורדף - ור מאיר הכריחם לעשות שלום - בערב יוה\"כ. ישב בדינו של ר נתן ארהולץ משטמפן והדיחו מרבנותו. חתנו - ר זליגמן זולצבך.","bk":[["חידושי הלכות מהר\"ם ברבי",""],["חידושי מהר\"ם ברבי",""]]},{"i":9243,"n":"ברבי, משה מתונס","dt":"תרסב","b":"תלמיד ר אברהם יצחק בעל משמרות כהונה. רב בתונס-תרס."},{"i":9244,"n":"ברבי, פנחס מטריפולי","bt":"תל","dt":"תק - בערך","b":"רב בטריפולי. נזכר בפנקס בי\"ד טריפולי."},{"i":9245,"n":"ברבר, אברהם מקשנוב","f":"שלמה","dt":"תרעג - בערך","b":"חתן ר שלמה אריה זייפמן."},{"i":9246,"n":"ברבר, יצחק מקשנוב","f":"שלמה","k":"איטשע פיווניטשער","dt":"תרצב","b":"חתן ר מרדכי הכהן הולנדר. חסיד בובוב (מהשלושה שהכתירו את ר בן ציון על מקום אביו). עלה לירושלים והתידד עם ר חיים זוננפלד. חזר לקשנוב-תרעט. מבניו: ר אהרן - חסיד בובוב ורב בקשנוב, ר אשר - חסיד בובוב ומראשי הקהלה בסנוק."},{"i":9247,"n":"ברבר, ישעיה חנוך מלודז","dt":"תרצג - כז כסלו","b":"חתן ר ישראל משה ליפשיץ האדמור מפרושקוב. הו\"ל \"מי הים\" לחותנו זקנו."},{"i":9248,"n":"ברבר, מאיר","k":"בעל אמונה ומדות","b":"נכד ר יצחק אהרן מקשנוב. מחכמי בני ברק. חיבר \"אמונה ומדות לאור השמיטה\" - בני ברק תשמז."},{"i":9249,"n":"ברבר, מרדכי מסנוק","f":"אשר","bt":"תרעט","dt":"תש..","b":"תלמיד ישיבות בובוב בסנוק ובבובוב. נספה בשואה."},{"i":9250,"n":"ברבר, סיני אריה מאושפיצין","b":"תלמיד ישיבת \"כתר תורה\" מאושפיצין. פרסם מאמרים ב\"כתר תורה\" - אושפיצין תרצט."},{"i":9251,"n":"ברבש, גרשון","f":"משה","b":"אחיו של ר שמשון. נכדי ר פייביש הלר. תשובה אליו \"שערי בנימין\" ועוד."},{"i":9252,"n":"ברבש, חיים זאב וולף מטופרוב","b":"דיין בטופרוב-תרמד. תשובות אליו ב\"מחזה אברהם\"."},{"i":9253,"n":"ברבש, יעקב מחרסקוב","dp":"תרנז","b":"רבה של חורוסטקוב-תרנח (=חרסקוב) אחרי ר צבי הירש תאומים."},{"i":9254,"n":"ברבש, משה יוסף מזלישטשיק","b":"רב בזלישטשיק, תלמיד ר אברהם תאומים. תשובות אליו ב\"דבר משה\", רבו ב\"חסד לאברהם\"."},{"i":9255,"n":"ברבש, שמשון","f":"משה","b":"תשובה אליו ב\"יוסף דעת\"-תרכו."},{"i":9256,"n":"ברג, אליהו מסמיאטיץ","b":"רב בסמיאטיץ(=סעמיאטיץ)."},{"i":9257,"n":"ברג, יוסף מאסאד(=אסויד)","dt":"תשמד","b":"רבה האחרון של אסאד. נואם מוכשר. ניצל מהשואה. עלה לארץ והתישב בנתניה."},{"i":9258,"n":"ברג, ישראל זאב מפודקמין","f":"משה","k":"בעל וזאת לפנים בישרא","bt":"תקעג","dt":"תרסה","b":"רב בפודקמין. חסיד בלז. חיבר \"וזאת לפנים בישראל\" למברג תרס."},{"i":9259,"n":"ברג, מרדכי גימפל","k":"בעל באר מרדכי","b":"מרבני טבריה-תרצ\"ד"},{"i":9260,"n":"ברגא, משה מסטניסלב","f":"ישראל","bt":"תרלד","bp":"זבלטוב","dt":"תשב","b":"חתן ר יוסף הורביץ אב\"ד אוסציא וראב\"ד סטניסלב. רב בסטניסלב על מקום חמיו וקראקא. רב בבוקרשט-תרעט על מקום אביו."},{"i":9261,"n":"ברגהויער, פנחס הלוי","bt":"תרלד","dt":"תרפז - טז אב","b":"רב במרברטוב"},{"i":9262,"n":"ברגובסקי, ברוך בן ציון מרדומיש","f":"מרדכי ישראל מרדומישל","bt":"תרכז","b":"חתן ר ישראל אהרן ממזריטש-ווהלין. רב בראדמאשלא(=רדומישל)-פלך קיוב-תרס על מקום אביו. נסמך מאת: ר מרדכי דב בעל \"עמק שאלה\"."},{"i":9263,"n":"ברגובסקי, מרדכי ישראל מרדומישל","dt":"תרס - ז אד\"א","b":"רב בראדעמישלא(=רדומישל)-פלך קיוב-תרלח, ובנו ר ברוך בן ציון על מקומו אחריו. הניח חדושים ושו\"ת - בכת\"י. בנו גם - ר שמואל דב מיעלסק. חתניו: ר יונה הוכמן ממאלין, ר אשר זילברשטין ממזריטש."},{"i":9264,"n":"ברגובסקי, שמואל דב מיעלסק","f":"מרדכי ישראל מרדומישל","bt":"תרמא","b":"חתן ר אברהם ליב גרמן מבארדיאנקע-פלך קיוב. רב ביעלסק-פלך מינסק-תרסז. נסמך מאת: ר יחיאל מיכל אפשטין, ר דוד אורטינבורג מברדיטשוב."},{"i":9265,"n":"ברגוין, יוסף ישראל","f":"שמואל","dt":"תרנב","dp":"ירושלים","b":"היה רב בקמניץ ועלה לירושלים, והתמנה לבית הדין."},{"i":9266,"n":"ברגופן, ליפא מקראקא","b":"מוהל בקראקא. תשובה אליו - \"מנחם משיב\"-תרפא."},{"i":9267,"n":"ברגזין, זאב וולף מואלאמן","f":"מנחם","bt":"תרמב","dt":"תשג","b":"מצאצאי בעל \"חמדת שלמה\". רב בוואלומין(=וואלמאן)-פלך וארשא-תרסד. נסמך מאת: ר משה נחום ירושלמסקי מקיעלץ, ור יעקב מנאשעלסק בעל \"טהרת אזוב\"."},{"i":9268,"n":"ברגילון, יצחק מברצלונה","bp":"ברצלונה","dt":"רסט - ג תשרי","dp":"שלוניקי","b":"מחכמי ברצלונה, אחרי הגירוש הגיע לשלוניקי-רסט בזמן הרא\"ם, וחברו של ר יצחק אמריליו."},{"i":9269,"n":"ברגילון, שמואל ממרוקו","b":"מחכמי מרוקו. חתם-תרטז על פס\"ד של ר יצחק ן ואליד."},{"i":9270,"n":"ברגלס, חיים ליבוש מקראקא","bp":"קראקא","dp":"תש..","b":"חסיד גור. מחשובי ישיבת חכמי לובלין. חתן ר שבתי הכהן רפפורט אב\"ד פינטשוב. נספה בשואה."},{"i":9271,"n":"ברגלס, קלמן","dt":"תש..","b":"חתן ר חיים אריה הורביץ בעל \"זכרון משה\". נספה בשואה עם משפחתו."},{"i":9272,"n":"ברגלס, שמחה מריגליץ","b":"גביר מחכמי ריגליץ וממלא מקום הרב. חתנו - ר חיים לוי ברגלס מדומברובה."},{"i":9273,"n":"ברגמן, אברהם אש מירושלים ונ\"י","b":"פרסם מאמרים ב\"המעין\" - בודפשט תשז (לאחר השואה!)."},{"i":9274,"n":"ברגמן, אברהם צבי מיאסין","f":"יהודה","bt":"תרט","dt":"תרעח","b":"רב ביאסין(=קרעשמעזא)-תרלה כ-43 שנה."},{"i":9275,"n":"ברגמן, אברהם צבי מניו יורק","b":"תלמיד השב\"ס. רב בניו יורק-תרצז. פרסם מאמרים ב\"המעין\" - בודפשט תשז (לאחר השואה!)."},{"i":9276,"n":"ברגמן, אברהם צבי מצאנז","f":"אשר","dp":"בודפשט","b":"ר\"מ בצאנז."},{"i":9277,"n":"ברגמן, אליהו מצאנז","b":"רב בצאנז ומחנך בניו של ה\"דברי חיים\". היה בין האסורים בשנת תרלו בגלל פרשת החרם."},{"i":9278,"n":"ברגמן, אליעזר מאשכנז וירושלים","f":"יוסף בנימין מהידנהים","k":"בעל בהר יראה","bt":"תקנח-ט","dt":"תריב - יב ניסן","dp":"ברלין","b":"תלמיד ר אברהם ביעהם בגנצהויזן, ר וולף המבורגר בפיורדא ור אברהם בינג בוירצבורג. חתן השתדלן ר מנדל רוזנבוים מצעל (שהיה שר האוצר של ליאופולד מלך בווריה). עלה לירושלים-תקצד ויסד את כולל הו\"ד (הולנד ודוישטלנד) והיה מחלוקת על כך עם כוללות הפרושים והיה בידידות עם ראשי הספרדים ובהם ר יצחק קובו, את בנו ר בנימין - השיא לבת למשפחה ספרדית והוסיף לשמו את הכנוי מירקאדו כמנהג הספרדים, בשליחות-תרט ונפטר בשליחותו. בנו גם - ר יהודה-חתן ר נחום משאדיק, חתנו - ר בנימין יחזקאל יהודה. מתלמידיו - ר יוחנן שלאנק. (באוצר תאריך פטירתו - יט ניסן תריט)"},{"i":9279,"n":"ברגמן, דב בר (דוד) מסטוקלישוק","bt":"תרמא","dt":"תשא - אב","b":"רב בסמיישק(=סמילישוק), רבה האחרון של סטקלישאק(=סטוקלישוק). נספה בשואה."},{"i":9280,"n":"ברגמן, דוד מירושלים","b":"תלמיד ישיבת \"ר ישראל אמריקנר\" בירושלים. פרסם מאמרים ב\"קובץ חדושי תורה\" - ירושלים תרצה."},{"i":9281,"n":"ברגמן, דוד מקליין-לייפניק","b":"תלמיד השב\"ס. מחכמי קליין-ליפניק-תרן. תשובה אליו ב\"שבט סופר\"."},{"i":9282,"n":"ברגמן, זאב וולף מברוד","b":"רב בברודי בזמן המהרש\"ק."},{"i":9283,"n":"ברגמן, זאב וולף מגורליץ","b":"רב בגורליץ על מקום ר ברוך מגורליץ. נקרא פיבלס (כנראה ע\"ש חותנו). פרסם מאמרים ב\"הלבנון\" - גורליץ תרפח."},{"i":9284,"n":"ברגמן, יהודה מירושלים","f":"אליעזר","b":"חתן ר נחום משאדיק."},{"i":9285,"n":"ברגמן, יוסף מירושלים","b":"רב בירושלים"},{"i":9286,"n":"ברגמן, יוסף מסאסוב","bt":"תרנח","dt":"תשא","b":"שו\"ב בסאסוב. עסקן באגו\"י. חיבר מחזות ופרסם בעתוני אידיש. נספה בשואה."},{"i":9287,"n":"ברגמן, יוסף משה מירושלים","b":"תלמיד ישיבת \"ר ישראל אמריקנר\" בירושלים. פרסם מאמרים ב\"קובץ חדושי תורה\" - ירושלים תרצה."},{"i":9288,"n":"ברגמן, יצחק צבי מניעשויז","b":"רב בניעסביץ. פרסם מאמרים ב\"קובץ דרושים\" - פיעטרקוב תרפג, \"קובץ מפרשי התורה\" - מארגרטן תרצג, \"בית המדרש החדש\" - גריבה תרפח."},{"i":9289,"n":"ברגמן, ירחמיאל יצחק צבי","bt":"תרמג","dt":"תרצב - יד כסלו","b":"רב בנעשוויז-תרס\"ח"},{"i":9290,"n":"ברגמן, ישכר דב מארה\"ב","f":"שלמה מיאסין","bt":"תרעא","bp":"יאסין-הונגריה","b":"תלמיד ישיבת חברון בירושלים. נסמך מאת: ר משה מרדכי אפשטין, ר אברהם יצחק כהן קוק, ר איסר זלמן מלצר. חתן ר נפתלי וייס מבילקא הי\"ד(-נכדת האדמור מבלז). רב בניו יורק-תרצז. פרסם מאמרים ב\"כנסת ישראל\" - נ\"י תרצב - כתב עת הסתדרות תלמידי סלובודקה באמריקה. עורך \"מארגען זשורנאל\"-תשט. חבר אגודת הרבנים באמריקה."},{"i":9291,"n":"ברגמן, מאיר מצפת","f":"יצחק שמחה","k":"בעל עין פנים","bt":"תרמט","bp":"לאפאש (טרנסילבניה)","dt":"תשי","b":"עלה עם אביו לצפת. למד בישיבות החת\"ס והרידב\"ז בצפת. רב בבוקרשט. חיבר \"עין פנים\" - בכת\"י."},{"i":9292,"n":"ברגמן, מרדכי ליב מפוטיק","f":"זכריה","dt":"תרעט","dp":"וינה","b":"גביר בעל אחוזה בפוטיק. תשובה אליו - \"הרי בשמים\"-תרסב."},{"i":9293,"n":"ברגמן, משה חיים מסטניסלב","dt":"תרצט","dp":"סטניסלב","b":"נכד ר מרדכי ליב. גביר מחכמי סטניסלב. פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח."},{"i":9294,"n":"ברגמן, משה מיאסין","f":"אברהם צבי מיאסין","bt":"תרלח","bp":"יאסין","dt":"תשד","b":"תלמיד השב\"ס. רב ביאסי, יאסין-תרעח על מקום אביו. נספה בשואה."},{"i":9295,"n":"ברגמן, נחום מירושלים","b":"רב בירושלים-תרסט."},{"i":9296,"n":"ברגמן, נחום מירושלים","f":"יהודה","k":"ירושלים","dp":"תרפו - יח אלול","b":"למדן ועסקן צבור ומוהל בירושלים."},{"i":9297,"n":"ברגמן, פנחס מטרנוב","b":"רב בטרנוב. תשובה אליו - \"חדושי אנשי שם\"."},{"i":9298,"n":"ברגסון, תמריל","b":"עשירה. גיסתו של ר משה שמחה אלפסי מאופוטשנא."},{"i":9299,"n":"ברגפלד, אהרן (נרשם ברנפלד בטע)","dt":"תשד","b":"דומ\"צ בריסקווא"},{"i":9300,"n":"ברגפלד, אהרן מריסקווה","f":"צבי מנימוזה","dt":"תש..","b":"חתן דודו ר אברהם שלמה מריסקווה, דיין בריסקווה אצל דודו. נספה בשואה."},{"i":9301,"n":"ברגפלד, צבי הירש מנימוזה","dt":"תרעה - י טבת","b":"תלמיד ר יקותיאל יהודה טיטלבוים בסיגט. חתן ר אהרם גרינפלד מוויטקא. רבה הראשון של נימוז'ה. מתשובותיו ב\"ארחות המשפטים\"."},{"i":9302,"n":"ברגר, אליהו חיים משיקגו","f":"יצחק יעקב מסעליש","bp":"סעליש","dt":"תשיז - אחרי","b":"תלמיד הדעת סופר. רב בשיקגו-תרפה."},{"i":9303,"n":"ברגר, אלימלך מסנוק","f":"דב בריש","bt":"תרעה","bp":"סנוק","dt":"תשנז","b":"ניצל מהשואה וגלה לסיביר, ואחריה רב בגליידיץ וקטוביץ. עלה לארץ-תשי וכיהן כרב במושבים בני ציון ובצרה."},{"i":9304,"n":"ברגר, בנימין מבאלאד","dt":"תשד","b":"תלמיד ר משה בעל \"ערוגת הבשם\", ור שלמה האדמור מבובוב. גביר מחכמי באלאד(=בעלעד) יסד ישיבה בכספו ובה מאות תלמידים. נספה בשואה."},{"i":9305,"n":"ברגר, גרשון אברהם ממינסק","k":"גרשון הענקעס","b":"גביר מחכמי מינסק-תרם, היה ממקורבי \"הגדול ממינסק\" אולם במשך הזמן נפרדו דרכיהם לצערו של ר ירחם יהודה."},{"i":9306,"n":"ברגר, חיים יעקב ישראל מארה\"ב","f":"משה צבי","k":"בעל אהבת ישראל","bt":"תרמז","bp":"ראווא-פולין","dt":"תשכא","b":"תלמיד ר אברהם בורנשטין מראווא, ר מנחם מנדל פרייס מביאלא בעל \"תפארת מנחם\", נסמך מרבותיו ומבד\"ץ וארשא. רב בפולין, היגר לארה\"ב וכיהן כרב בקהלת \"שומרי שבת\" בקליבלנד, קהלת \"אהבת ישראל\". פרסם מאמרים ב\"הפוסק\" - תל אביב תש-תשיד. גיסו - ר ירחמיאל ישעיה מינצברג מלוקאוו. חיבר גם \"כל ישראל חברים\", \"שארית יעקב\", ועוד. חבר אגודת הרבנים באמריקה."},{"i":9307,"n":"ברגר, טוביה מקרמנד","b":"רב בקרמנד-תק\"צ"},{"i":9308,"n":"ברגר, יהודה ליב ליפא מואשוואר","b":"רב בוואשוואר-תרי, על מקום ר דוד שוורצברג."},{"i":9309,"n":"ברגר, יוסף דוד משאוולי ונ\"י","f":"גדליה","bt":"תרל","b":"תלמיד ישיבת קובנה, סלובודקה וקידאן. רב בשאוולי, ניו יורק-תרסג בביהכ\"נ \"סלוצקער שול\", רב באוטבה-קנדה-תרסח. נסמך מאת: ר נחום שפירא משאט, ר חיים ראצקר מיאנוב בעל \"אורח לחיים\", ר שמעון שימא לוריא, ר מרדכי לאצקובר."},{"i":9310,"n":"ברגר, יוסף הלוי מסאמאש","f":"אפרים שלום מנאסוד","bt":"תריט","bp":"נאסוד","dt":"תרצה - יא תשרי","dp":"סאמאש-אויוואר","b":"תלמיד השב\"ס, ור יהושע אהרן צבי וינברגר ממארגרטן. חתן ר פנחס הכהן פולופ מקורטיוש. עלה לצפת-תרסו. רב בלונדון-תרעד, התישב בסאמאש-אויוואר."},{"i":9311,"n":"ברגר, יוסף שמואל הלוי מסיגט","b":"חסיד ויזניץ. שו\"ב וכפר לעה-ליד ביטשקוב, רב בסיגט - והיה מקורב לראבד בעל \"עצי חיים\" שהיה מתיעץ עמו בפסקיו."},{"i":9312,"n":"ברגר, יחיאל מיכל מקישלעטע","dt":"כא אייר","b":"גדל אצל דודו-אחי אמו ר קלונימוס בעל \"מאור ושמש\" מקראקא, הוסמך ע\"י דודו לאדמורות אך סירב לשמש בה. שו\"ב בקישלעטע-גליל נירבאטור. חסיד ר יצחק איזיק מקאליב באשווער. מתולדותיו ב\"עשר עטרות\". בנו ר יצחק שמחה מניגרלשט בעל \"מנחת יצחק\" ונכד ר ישראל בעל \"עשר קדושות\"."},{"i":9313,"n":"ברגר, יעקב ישראל מארה\"ב","k":"בעל כל ישראל חברים","b":"רב בארה\"ב-תשד."},{"i":9314,"n":"ברגר, יצחק שמחה מלאפוש","f":"יחיאל מיכל מקישלעטע","k":"בעל שמחת יצחק-תש","bt":"תקפא","dt":"תרנה - ב חשון","dp":"צפת","b":"גדל בין חסידי אשוואר, ניהל ישיבה, עבר לכפר ניגרלשט-ליד דעש, רב וראש ישיבה במאדיאר-לאפוש. אביו הוסמך לאדמור בידי דודו בעל \"מאור ושמש\" - אך סירב לשמש כאדמור. חתן ר בנימין הרטמן משאמלוי, ובזיוו\"ש חתן ר יחזקאל פאנט בעל \"מראה יחזקאל\". עלה לצפת-תרנא. בניו - ר ישראל בעל \"עשר צחצחות\" ור מאיר בעל \"אמרי ישראל\" מטורונטו."},{"i":9315,"n":"ברגר, ישראל מבוקרשט","f":"יצחק שמחה מלאפוש","k":"בעל ילקוט ישראל","r":"אב\"ד בוקרסט","bt":"תרטו","bp":"לאפוש","dt":"תרעט - כא אייר","b":"חסיד זידיטשוב. תלמיד ר יקותיאל טיטלבוים מסיגט, ה\"דברי חיים\" מצאנז, ור מנחם מנדל פאנט מדעש. חתן ר מנחם מנדל האגר מזאבלטוב (באוצר כתבי עת מופיע - חתן ר יחזקאל מיכלסון מפלונסק). רב בפוריזנא(=פרביזנא)-תרלט, דורנא-ואטרא, דארנא-ניאמץ, פיאטרא-ניאמץ-תרן, בוזא-תרנז, בוקרשט-תרנח. חיבר גם \"עשר קדושות\", \"זכות ישראל\", \"עטרת יעקב וישראל\" למברג תרמא, ועוד. סופר וחוקר חסידות. פרסם מאמרים ב\"אהל מועד\" - פודגורזע תרנח, \"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז, \"המאסף\" - ירושלים תרנו.","bk":[["זכות ישראל ובו עשר קדושות, עשר צחצחות, עשר אורות, עשר עטרות - תולדות",""],["ילקוט ישראל ובו ג' ספרים א. לשון ישראל - קדושת הלשון ב. ברית ישראל - קדושת הברית. ג. ממון ישראל - שמירה מכל ענפי עוול",""],["רצון ישראל - תהלים",""],["זכות ישראל ובו עשר קדושות",""],["עשר צחצחות",""],["עשר אורות",""],["עשר עטרות - תולדות",""]]},{"i":9316,"n":"ברגר, מ' חיים ממישקולץ ונ\"י","k":"בעל אמרי חיים","b":"רב במישקולץ, ניו יורק."},{"i":9317,"n":"ברגר, מאיר מלאפאש וטורונטו","f":"יצחק שמחה","k":"בעל אמרי ישראל","bt":"תרמט","bp":"מאדיארפאש","dt":"תשי - א חשון","dp":"טורונטו","b":"תלמיד ישיבת חת\"ס בצפת, הרידב\"ז וחתנו-ר יוסף קנביץ. נסמך מאת: ר אליעזר דייטש מבאניהאד בעל \"תבואות השדה\", ר ישראל ברגר מבוקרשט, ר אפרים לנדא, ר דוד גודמן ור יצחק לנדמן. חתן ר יוסף ברגר. רב בבוקרשט-תרעד, ראש כולל זיבענבידגען בצפת-תרעז, רב בטורונטו-קנדה-תרפד.. חיבר גם \"שמחת יצחק\"."},{"i":9318,"n":"ברגר, מאיר מצפת וטורונטו","f":"יצחק שמחה מלאפוש","bt":"תרן","bp":"לאפוש","dt":"תשא - בערך","dp":"טורונטו","b":"עלה לצפת בילדותו עם משפחתו. תלמיד בישיבת ר יעקב רידבז בצפת, ביקר אצל אחיו בבוקרשט-תרעא, רב בכולל זיבענירגען בצפת-תרעד, עבר לקנדה וכיהן כרב עדת רומניה בטורונטו-[תרע..]."},{"i":9319,"n":"ברגר, משה מבוקרשט","f":"ישראל מבוקרשט","bt":"תרלד","b":"חתן ר יוסף הורביץ מאוסניצא, וסטניסלב. מו\"צ בסטניסלב-תרס על מקום חותנו, קראקא, אב\"ד בבוקרשט-תרעט. נסמך מאת: מהרש\"ם מברעזן, אב\"ד סטניסלב. חתם ראשון כדיין עם ר חיים רבינוביץ ור חנוך הניך שפרן. הו\"ל ספרי זקניו \"בר ליואי\", \"תורת הרמ\"ל\", \"אהבת שלום\" לר מנדלי מקוסוב."},{"i":9320,"n":"ברגר, משה קוטנדורף מפרשבורג","f":"בר מקוטנדורף","dt":"תרמא - טז אייר","dp":"פרשבורג","b":"תלמיד החת\"ס. נכד ר מנחם דייטש מקיצע. חתן ר דניאל פרוסטיץ-שטינשנידר מפרשבורג. רב בפרשבורג-תקצה וראב\"ד אצל הכת\"ס על מקום ר נתן נטע ליבר."},{"i":9321,"n":"ברגר, נטע יעקב מאודוואהרי","f":"מרדכי דב","k":"בעל נטעי נאמנים","bt":"תריח","dt":"תרע.. - בערך","b":"תלמיד ר יקותיאל יהודה טיטלבוים מסיגט. רב ודיין באודווארהי-ליד סטמר-תרנא."},{"i":9322,"n":"ברגר, נפתלי צבי מסמרקוביץ","b":"פרסם מאמרים ב\"העץ\" - לובלין תרצג."},{"i":9323,"n":"ברגר, צבי","bp":"פרשבורג","b":"גביר ונדבן, תרם לבנין ישיבת הכת\"ס בפרשבורג."},{"i":9324,"n":"ברגשטין שלום בן שמעון מרדכי","bt":"1904","dt":"ה'תשלז 1977","bk":[["פרדס שלום",""],["רעיונות בראשית",""]]},{"i":9325,"n":"ברגשטין, אליהו מירושלים","b":"פרסם מאמרים ב\"תורת ירושלים\" - \"תפארת ירושלים\"- \"תורה מציון\" ירושלים תרצו."},{"i":9326,"n":"ברגשטין, ישראל","b":"פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":9327,"n":"ברד\"ח יוניאר, אליהו מוינה","k":"בעל עקדת יצחק","bp":"לבוב","dt":"1864","dp":"וינה","b":"חיבר גם \"מעריך המערכת\" - קיצור אוצר השורשים של בן זאב, נדפס אחר פטירתו בהשגחת אהרן ילינק, עם תולדות המחבר לר\"מ הלוי לעטעריס."},{"i":9328,"n":"ברדיצבסקי, מיכה יוסף","f":"משה אהרן מדובובה","k":"מי\"ב","b":"תלמיד ישיבת וולוזין. מסופרי ההשכלה. עורך כתב העת \"בית המדרש\" - קראקא תרמח. פרסם מאמרים ב\"המסדרונה\" - פפד\"מ-ירושלים תרמה."},{"i":9329,"n":"ברדיצבסקי, משה אהרן מדובובה","f":"צבי הירש","b":"רב בדובובה-תר\"ס. בנו הסופר המשכיל מיכה יוסף."},{"i":9330,"n":"ברדס הכהן מגרבה","b":"פרסם מאמרים ב\"קרן דוד\" - גרבה תרעו."},{"i":9331,"n":"ברדע, דוד מתונס","dt":"תשח - טו אד\"א","b":"דיין בתונס"},{"i":9332,"n":"ברדע, יצחק מטריפולי","f":"עמוס","k":"בעל מנחת ערב - תשמט","b":"רב בטריפולי, עלה לארץ וכיהן כרב ברמת גן."},{"i":9333,"n":"ברדע, משה מתונס","b":"מחכמי תונס, והסכים שם על \"שפת רננות\"-תקצו ועוד. עלה לירושלים-תר, והסכים בירושלים-תרג על \"דברי שלום\"."},{"i":9334,"n":"ברדק-קלגסברון, דוד מוישניץ","k":"דוד \"גרף\"","b":"חתן ר ישראל הלל וסטרייך מגריבוב ובריגל. רושם תורתו של ר קלונימוס קלמן שפירא בעל \"מאור ושמש\". חתנו - ר מאיר יהושע האדמור מסטבניץ."},{"i":9335,"n":"ברדקי, יוסף זונדל מירושלים","f":"שלמה","dt":"כה חשון","b":"נכד(-אבי אמו) ר שמואל סלנט."},{"i":9336,"n":"ברדקי, ישעיה מירושלים","f":"ישכר בר","bt":"תקנז","bp":"לבוב או רוסיה","dt":"תרכג","dp":"ירושלים","b":"מחכמי ירושלים, עלה מפינסק-תקפו או תקפח, חתן ר ישראל משקלוב ולאחר פטירת חותנו הפך למנהיג עדת הפרושים בירושלים. השאיר כתבים רבים בכתב יד שרבים מהם אבדו. בניו - ר שלמה-חתן ר שמואל סלנט, ר שמואל עקיבא-חתן ר יעקב ענתבי מדמשק. חתנו - ר אליהו חזן מאלכסנדריה."},{"i":9337,"n":"ברדקי, ישראל מירושלים","f":"ישעיה","bt":"תרך","bp":"ירושלים","b":"חזן ביהכ\"נ החורבה בירושלים. מחותן עם ר פנחס אפשטיין-ראב\"ד העדה החרדית. בנו - ר אברהם."},{"i":9338,"n":"ברדקי, נתן מירושלים","bp":"ירושלים","b":"עו\"ד בירושלים."},{"i":9339,"n":"ברדקי, שלמה מירושלים","f":"ישעיה","b":"נכד(-אבי אמו) ר ישראל משקלוב. חתן ר שמואל סלנט (שם אשתו חיה, שלחה-תרם שנה טובה לפקידים ואמרכלים באמשטרדם)."},{"i":9340,"n":"ברדקי, שמואל עקיבא","f":"ישעיה מירושלים","b":"חתן ר יעקב ענתבי מדמשק (שם אשתו - אסתר)."},{"i":9341,"n":"ברהום, חנניה ממצרים וירושלים","k":"בעל כלי שרת","dt":"תט - ב-ט ניסן","b":"מרבני מצרים-שנות ה-ת', תלמיד ר' אברהם סכנדרי."},{"i":9342,"n":"ברהום, שמואל ירושלמי ממצרים","f":"שלום","b":"תלמיד הרדב\"ז, רב באלכסנדריה."},{"i":9343,"n":"ברהין ן, שלמה מתימן","f":"ברהין","bt":"תר..","bp":"סנואן-חוגריה-תימן","dt":"תשח - לפני","dp":"סנואן-תימן","b":"מקובל במחוזר חוגריה בתימן חברו של מרי יחיא בן דוד אביו של מרי חיים סנואני, והיו מגדולי המקובלים בדרום תימן. שם אביו ברהין הוא כנראה אברהם, משום שהמוסלמים באזור אסרו על היהודים להשתמש בשם אברהם, ולכן השתמשו היהודים בכינויים המזכירים את השם."},{"i":9344,"n":"ברהין, רפאל יוסף ממצרים","f":"יוסף","dt":"תכט - יט אב","dp":"מצרים","b":"שר האוצר וג'יליבי(=פקיד היהודים) בקהיר, עשה צדקה וחסד עם אחיו, ותומך ברבנים. סייע לש\"ץ בהיותו בקהיר המיר דתו בעקבותיו וחזר ליהדות. נהרג ע\"י המשנה למלך במצרים. והיה הג'יליבי האחרון במצרים. הזמין את ר שמואל בן חיים ויטאל למצרים שיורה לו דרך תשובה לאחר שחזר ליהדות."},{"i":9345,"n":"ברהנץ, סאסי מתונס","f":"יצחק","b":"רב בתונס. חברו של ר אברהם יצחקי בעל \"משמרות כהונה\". ונזכר גם אצל ר יוסף גג' ב\"פי המדבר\"."},{"i":9346,"n":"ברודא (ברוידא) - משפחה","b":"מקור השם - באו מאונגאריש בראד שבמעהרין."},{"i":9347,"n":"ברודו, אברהם ג'יליבי מקושטא","f":"אליהו","k":"בעל ברכת אברהם","bt":"שפה או שצ","bp":"קושטא","dt":"תע-ז","dp":"ירושלים","b":"מצאצאי ר אברהם ברודו הספרדי, תלמיד ר משה בנבנשתי מקושטא, רב בקושטא - חתום על פסקים מקושטא משנת תיג. ראש ישיבה באדרינופול במשך כ-50 שנה. יצא לפדות שבויים שנשבו במלחמת ונציה, נדד באיטליה, גרמניה, אוסטריה, הולנד, נפגש עם החכם צבי הכותב עליו, וכן ר אברהם ברודא בפרג, עלה לירושלים והיה ראש החכמים בה, וחתם הסכמה ל\"עין יהוסף\" תסד. וכן על כתב שליחות ר' אברהם רויגו תסד. מחבר ברכת אברהם ונציא תנו. היה נוטה לשבתאות וחזר בו. אחיו - ר משה."},{"i":9348,"n":"ברודו, אברהם מירושלים - הזקן","b":"נזכר בשו\"ת ר יוסף טאיטצאק אודות הצוואה שעשה בירושלים, אולי הוא זקנו של ר אברהם ברודו בעל ברכת אברהם"},{"i":9349,"n":"ברודו, אשר משלוניקי","dt":"שפא - ד תמוז","dp":"שלוניקי","b":"סגי נהור. מחכמי שלוניקי-שן. מתלמידיו - ר אשר ן ארדוט הכהן."},{"i":9350,"n":"ברודו, יהודה משלוניקי","b":"מחכמי שלוניקי, ר\"מ באופן זמני בק\"ק \"שלום\" - אחרי שסא."},{"i":9351,"n":"ברודו, יצחק מקושטא","b":"גביר מחכמי קושטא-ש'. השיב עם ר יוסף טאיטצק, ור תם ן יחיא."},{"i":9352,"n":"ברודו, יצחק משלוניקי","bt":"תרלח","dt":"תשג","b":"דיין בשאלוניקי-תר\"צ"},{"i":9353,"n":"ברודו, יצחק משלוניקי","b":"מורה בביה\"ס ת\"ת בשלוניקי-לפני השואה."},{"i":9354,"n":"ברודו, יצחק משלוניקי","f":"עמנואל","dt":"תש..","b":"דיין בשלוניקי. נספה בשואה. אחיו של ר מרדכי."},{"i":9355,"n":"ברודו, מנואל מפורטוגל","k":"בעל טעמי המצוות","b":"רופא מחכמי פורטוגל, ואחרי הגירוש עבר לטורקיה."},{"i":9356,"n":"ברודו, מרדכי משלוניקי","f":"מרדכי","dt":"תש..","b":"דיין בשלוניקי. נספה בשואה. אחיו של ר עמנואל."},{"i":9357,"n":"ברודו, משה מקושטא","b":"דיין בקושטא-תטו עם ר ברוך ן חיים. אחיו - ר אברהם."},{"i":9358,"n":"ברודו, עובדיה משלוניקי וירושלי","k":"ירושלים","b":"מחכמי שלוניקי-תרס."},{"i":9359,"n":"ברודו, עמנואל יצחק משלוניקי","bt":"תריז","dt":"תרפו","dp":"שלוניקי","b":"רב בשלוניקי-תרפד, והצטיין בדרשותיו. ממלא מקומו (בתואר - \"לוקום טינינס\") של ר בן ציון חי עוזיאל-תרפד, ור חיים חביב על מקומו אחריו. ממיסדי חברת \"דובב שפתי ישנים\"-תרנו."},{"i":9360,"n":"ברודו, שלמה עובדיה משלוניקי","b":"מחכמי שלוניקי-תרף."},{"i":9361,"n":"ברודט, נחמיה ממעליץ","f":"צבי יעקב","k":"בעל תורת המקדש","dt":"תשכו","b":"חסיד בלז. ניצל מהשואה, גלה לסיביר (שם פעל בעניני יהדות ובחברה קדישא). הגיע לארה\"ב והיה מחשובי וזקני החסידים שם. עלה לארץ. נכדו ר אברהם שמשון חיבר \"תורת המקדש\" ניו יורק תשנב."},{"i":9362,"n":"ברודי, דוד מפפד\"מ","b":"מראשי קהילת פפד\"מ-תפ בערך."},{"i":9363,"n":"ברודי, ישראל איסר","dt":"תרכה - כ שבט","b":"רב באושפיצין"},{"i":9364,"n":"ברודי, משה מנחם מאונגוואר","k":"בעל הארת השמש","dt":"תשד","b":"רב באונגוור"},{"i":9365,"n":"ברודי, שלמה זלמן מאונגואר","bt":"תקצט","dt":"תרעט - כו אד\"א","b":"חתן ר שלמה גנצפריד, מהר\"ם א\"ש. דיין באונגוואר. (באוצר הרבנים תאריך פטירתו כא אד\"א תרעז)."},{"i":9366,"n":"ברודי, שלמה ממרגנטהיים","f":"אברהם מפפד\"מ","b":"רב במרגנטהיים, ור נפתלי הירש קצנלנבוגן על מקומו אחריו-תקא."},{"i":9367,"n":"ברודמן, דוד מבוכניה","f":"שמואל","bt":"תרמח","bp":"טימאווא","dt":"תרפח","b":"רב ברוטרדם. חסיד בובוב."},{"i":9368,"n":"ברודנא, אברהם צבי מקופישוק","f":"משה","k":"בעל חסד לאברהם","bt":"תרח","bp":"דוינסק","dt":"תרצו","dp":"ירושלים","b":"תלמיד ישיבת וולוזין, נסמך מאת: ר יצחק אלחנן מקובנא. רב בקופישוק-פלך קובנא-תריג, ברעזין-פלך מינסק-תרסב, בשנת תרפב עלה לירושלים. חיבר גם \"חיי משה\", \"ברכת אברהם\", ועוד. פרסם מאמרים ב\"בית ועד לחכמים\" - סטמר תרפב, \"שערי ציון\" - ירושלים תרפא. שבעת בניו נפטרו בחייו."},{"i":9369,"n":"ברודנא, זוסמן","b":"רב בראזאליא-פלך פוניבז-תר\"ס. חתנו - ר יום טוב ליפמן לוין מארה\"ב."},{"i":9370,"n":"ברודנא, משה ליפמן מפניעוונא","k":"בעל אלה הדברים","dt":"תש..","b":"אבב\"ד פניעוונא-פולין. חיבר קובץ דרשות \"אלה הדברים\" וארשא תרצח. כנראה נספה בשואה."},{"i":9371,"n":"ברודנא, שמואל","b":"ניצל מהשואה והגיע לשנחאי-סין. פרסם מאמרים ב\"מאור תורה\" - שנחאי-סין תשד - קובץ תלמידי ישיבת מיר בשנחאי, \"התבונה\" - נ\"י תשז - קובץ תלמידי ישיבת מיר."},{"i":9372,"n":"ברודסקי, אליהו מקלינובקה","f":"יעקב שמואל ברודסק","bt":"תרכה","dt":"תרפד","b":"נכד ר יעקב שמואל בעל \"תפארת שמואל\". רב בקאלינובקה-פודוליה."},{"i":9373,"n":"ברודסקי, אלעזר (אליעזר) מקיוב","f":"ישראל מזלטופול","bt":"תרח","bp":"זלטופול-פלק קיוב","dp":"בזל","b":"גביר תלמיד חכם בקיוב. חתן ר שמחה לוריא ממינסק-נכד הרד\"ל. הקים מוסדות צדקה וחסד בזלטופול ובקיוב, הקים ביכ\"נ בקיוב בשם \"בראדסקיס שול\". בעל אותות כבוד ממשלות רוסיה וצרפת."},{"i":9374,"n":"ברודסקי, חיים שרגא מארה\"ב","k":"בעל נהור שרגא","bt":"תריג","b":"דרשן, רב בפילדלפיה-תרמט, ניו יורק-תרס. חיבר גם \"מעשה חש\"ב\" נ\"י תרסז."},{"i":9375,"n":"ברודסקי, יהושע יוסף מזאזאוו","f":"אליהו מקאלינווקא","k":"בעל ישועת יוסף","bt":"תרמב","dt":"תרפט - ג ניסן","b":"מצאצאי ר יעקב שמואל מיאנישפאלי בעל \"תפארת שמואל\". רב בזוזוב,פיקוב,קאלנובקה-תרפד. נסמך מאת: ר משה דונשבסקי מסלובודקא. חיבר גם \"תולדות אדם\"."},{"i":9376,"n":"ברודסקי, יהושע מאומאן","b":"משכיל. פרסם מאמר ב\"הכרמל\" ובו התחזה לחסיד ברסלב, דבר שעורר פולומוס בין משכילים שונים שלא הבחינו בזיוף והתיחסו למאמר ובהם רש\"י פין ועוד."},{"i":9377,"n":"ברודסקי, יעקב שמואל מיאנישפולי","k":"בעל תפארת שמואל","dt":"תרעט","b":"רב ביאנושפולי-ווהלין. נהרג עק\"ה."},{"i":9378,"n":"ברודסקי, שמשון מארה\"ב","b":"פרסם מאמרים ב\"התבונה\" - נ\"י תשז - קובץ תלמידי ישיבת מיר."},{"i":9379,"n":"ברודסקי, שרגא","dt":"תרצז - יד אדר","b":"רב בניו יורק,פילדלפיה,ניו ג'רסי"},{"i":9380,"n":"ברודר, יצחק מאיר מיאנוב","b":"רב ביאנוב. נזכר ב\"אמרי כהן\". פרסם מאמרים ב\"קובץ דרושים\" - פיעטרקוב תרפג."},{"i":9381,"n":"ברודר, משה","dt":"תש..","b":"תלמיד החבצלת בטרנופול. ישיבת חכמי לובלין, וקיבוץ גבוה דרדומסק בסוסנובצה אצל ר יוסף לסר ור משה רבינוביץ. נספה בשואה."},{"i":9382,"n":"ברודר, נחמן גדליה מירושלים","bt":"תריז","dt":"תש - א אב","b":"מגדולי חכמי ירושלים"},{"i":9383,"n":"ברודר, שמואל","dt":"תרלו","b":"רב בוואסילקובה-תקפ\"ו"},{"i":9384,"n":"ברוור, אברהם אלכסנדר","b":"ר\"מ בלובלין-תר\"מ"},{"i":9385,"n":"ברוור, אברהם יעקב מסטרי","f":"מיכאל","k":"בעל אבק דרכים","bt":"תרמד","bp":"סטרי","dt":"תשלו","b":"למד בבית מדרש לרבנים בוינה, עלה לירושלים-תרעב. רב בקהלה האשכנזית בקושטא-בזמן מלחמת העולם הראשונה. חזר לארץ-תרף. חיבר \"אבק דרכים\", ועוד."},{"i":9386,"n":"ברוור, יהודה מארה\"ב","f":"משה יצחק מארה\"ב","bt":"תרנא-ב-ה","bp":"לעגעמיאן-פלך וילנא","b":"תלמיד ישיבות טלז, וולוזין, פוניביז, ואצל ר חיים עוזר בוילנא. נסמך מאת: ר רפאל שפירא מוולוזין, ר צבי הירש מה יפית מולקוביסק. חתן הגביר ר עקיבא איצקוביץ מליעגעמיאן. היגר לארה\"ב-תרעג וכיהן כרב באקרון-אוהיו, קנזס-סיטי-תרפג ויסד שם ישיבה-תרצה \"תורת משה\", מקסיקו-סיטי-תשד, לוס אנג'לס-תשח. חבר אגודת הרבנים באמריקה, וחבר בתנועת ה\"מזרחי\"."},{"i":9387,"n":"ברוור, יהודה נח מבארנוב","f":"אברהם אלכסנדר","k":"בעל ילקוט פרי עץ הדר","bt":"תרך או תרל","bp":"בלזיץ (ליד לובלין)","dt":"תש - כח כסלו","dp":"ירושלים","b":"תלמיד ר דוד מורגנשטרן בנו של ר מנדלי מקוצק, ור שניאור זלמן מלובלין בעל \"תורת חסד\" והיה היחיד מתלמידיו שנסמך על ידו. רב ביאנובצה-תרנז ליד קוזמיר, בארנוב-תרנח, בשנת תרפה עלה לירושלים. חיבר \"ילקוט פרי עץ הדר\" פיעטרקוב תרנט, ועוד. פרסם מאמרים ב\"שער בת רבים\" - וארשא תרפב."},{"i":9388,"n":"ברוור, מיכאל מקאלוש","f":"משה","k":"בעל פאר יצחק","bt":"תרכג","bp":"קאלוש","dt":"תשט","dp":"ירושלים","b":"חסיד זידיטשוב. עלה לארץ-תרפה התפרנס כל ימיו מעבודתו ועסק בתורה לשמה. חיבר \"פאר יצחק\" למברג תרפח, ועוד."},{"i":9389,"n":"ברוור, משה יצחק מליטא וארה\"ב","bt":"תרכז","dt":"תרצו - כ ניסן","b":"רב בקורקיל(=קורקלי)-תרנד, קלוואריה-תרסו, וילקוביסק-תרעד, היגר לארה\"ב-תרפד וכיהן כרב בסיו-סיטי-איווה, \"שערי ציון\" - ירושלים תרפא."},{"i":9390,"n":"ברוור, צבי מנ\"י","b":"פרסם מאמרים ב\"נר מערבי\" - נ\"י תרפד - קובץ ישיבת ר יצחק אלחנן."},{"i":9391,"n":"ברוורמן, אלעזר מקראטי","f":"אהרן משה מקראטי","k":"אדמור מקראטי","dt":"תרמב - יב אייר","b":"תלמיד ר דוד מטולנא (טשרנוביל)."},{"i":9392,"n":"ברוורמן, אריה ליב מקראטא","f":"דוד מקראטא","bt":"תרלב","b":"חתן ר יחיאל מיכל מקוריץ (שושלת זלוטשוב). רב בקראטא(=קארטי)-פודוליה-תרסה."},{"i":9393,"n":"ברוורמן, דוד מקראטי","f":"אליעזר מקראטי","k":"אדמור מקראטי","dt":"תרסה","b":"רב בקראטא-תרם. חתן ר יוסף קצנלנבוגן מגראסעלס-חתן ר אריה ליב מבענדר."},{"i":9394,"n":"ברוורמן, זרח ראובן מירושלים","b":"תלמיד מהרי\"ל דיסקין. ר\"מ בישיבת לומזה, עלה לירושלים והיה ממיסדי ישיבת \"מאה שערים\"."},{"i":9395,"n":"ברוורמן, מרדכי","k":"בעל דברי דרך ארץ","b":"חיבר \"דברי דרך ארץ\" נ\"י תרסד."},{"i":9396,"n":"ברוורמן, מרדכי מקראטי","f":"אריה ליב מקראטי","dt":"תשג","b":"רב באוסטילא-בנדין. חתן ר נחמיה מקוידנוב-ברנוביץ. נספה בשואה."},{"i":9397,"n":"ברוט, שמואל הלוי מליפנא","bt":"תרמו","dt":"תשכג","b":"דרשן, רב פעלים לישוב א\"י, רב בליפנא, טומשוב, אנטורפן, ניו יורק, דיין בירושלים-תשט. פרסם מאמרים ב\"קול תורה\" - פאביאניץ תרפו."},{"i":9398,"n":"ברוידא חלפן, גבריאל מאיבשיץ","f":"יוסף חלפן","b":"רב באייבשיץ-תקמ\"ה"},{"i":9399,"n":"ברוידא, אברהם אהרן מהאלוסק","f":"שלום מוילנא","k":"בעל בית ועד","bp":"וילנא","dt":"תרב - בערך","b":"אב\"ד סטראבין, הלוסק. חיבר גם \"בית הגדול\" פירוש לפרקי ר אליעזר - וילנא 1838, ועוד. אביו היה מראשי הקהילה בוילנא במאה ה-19. גיסו - ר יונה מוילקומיר (נפטר תקפו)."},{"i":9400,"n":"ברוידא, אברהם יוסף מלבוב","b":"פרסם מאמרים ב\"יגדיל תורה\" - ברלין-קראקא תרנא."},{"i":9401,"n":"ברוידא, אברהם מברזנא","f":"שלמה זלמן מאונסדורף","k":"בעל פרי החג","bt":"תקפה","bp":"אונגוואר","dt":"תרמב - א טבת","dp":"ברזנא","b":"למד בישיבת פרשבורג. חתן ר אברהם יצחק ויינברגר מקליינורדין ועבר לשם. רב בברזנא-תרלב. חיבר \"פרי החג\". תשובה אליו ב\"כתב סופר\" ו\"שבט סופר\"."},{"i":9402,"n":"ברוידא, אברהם מטרנופול","f":"צבי הירש","dt":"תקנב - י שבט","b":"רב בטרנופול"},{"i":9403,"n":"ברוידא, אברהם מירושלים","b":"חתן ר יעקב דוד ספקטור-אחיו של ר יצחק אלחנן מקובנא. אביו של ר שמחה זיסל-ראש ישיבת חברון בירושלים"},{"i":9404,"n":"ברוידא, אברהם מסערהיי","f":"חיים מיאנוב","b":"רב בסערהיי-תקן. חברו של הגר\"א בנסתר. אחיו: ר אהרן מקאלואריה, ר יצחק חריף ממייצער."},{"i":9405,"n":"ברוידא, אברהם מפרג ופפד\"מ","f":"שאול","k":"בעל אשל אברהם","bt":"תי","dt":"תעז - ל ניסן","dp":"פפד\"מ","b":"תלמיד ר יצחק לנדא חריף מאפטא וקראקא. רב בליכטנשטט, רודניץ-תנב, ר\"מ בפרג, מיץ-תסט, פפד\"מ-תעב ור יעקב פופרש על מקומו אחריו. חיבר גם \"תולדות אברהם\". חתנו - ר יוסף בן דוד ברסלוי מקרופלד בעל \"חק יוסף\". חיבר בפפד\"מ תקנות ללבושים וחגיגות בפשטות - ונדפס בצנעה - והיתה הלשנה על כך לשלטונות מצד שודט. בניו - ר דוד, ר משה שחיבר הגהות לספר אביו בשם \"אהל משה\", ר שלמה ממרגנטהיים. החרים את ישעיה-חתן יהודה משיח על שאחז בשבתאות עד שחזר בתשובה."},{"i":9406,"n":"ברוידא, אברהם שמואל משיקגו","k":"בעל בית אברהם","bp":"מיטאוי-קורלנד","dt":"תרסז","b":"רב בשיקגו"},{"i":9407,"n":"ברוידא, אהרן דב ממינסק","f":"אריה ליב מקאלוואריא","bt":"תקעט","bp":"קאלואריא","dt":"תרנו - טו טבת","dp":"מינסק","b":"מחכמי מינסק, ועסקן בזמן כהונת הגדול ממינסק. חתניו - הגביר ר שמואל בויאנער מגראדייע."},{"i":9408,"n":"ברוידא, אהרן טייבילס מוילנא","f":"יעקב בן אהרן","k":"אהרעלע טייביל'ס","dt":"תרו - כח ניסן","dp":"וילנא","b":"בזיוו\"ש חתן ר אהרן צקהויזר מוילנא. רב בקלוואריע(=קלואריא), דיין בוילנא על מקום חותנו וראש ישיבה בקלויז יסו\"ד בהשגחת ר חיים גיטקע טויבעס. נכדו ר זליג ראובן בנגיס - רב בקלווריה. מבניו: ר נחמיה פו\"מ בוילנא, וגבאי בשניפישוק."},{"i":9409,"n":"ברוידא, אהרן מקאלווריה - א","f":"חיים מיאנוב וקלווריה","b":"רב בקאלווריה(=קאלואריא) על מקום אביו. בניו: ר בנימין מהורדנא, ר צבי הירש מסלנט, ר דב בר מזלודובא, ר אריה ליב מקלווריה, ר נפתלי הרץ, ר שמואל יונה'ס, ר יוסף מטיקטין. חתניו ר יהושע השל אשכנזי, ר פנחס."},{"i":9410,"n":"ברוידא, אהרן מקובנא","dt":"תשא","b":"רב בקובנה"},{"i":9411,"n":"ברוידא, אהרן מקרמליטא","dt":"תשא","b":"רב בקרמליטא"},{"i":9412,"n":"ברוידא, אלתר מוילקומיר","bt":"תרנט","dt":"תשא","b":"ר\"מ בישיבת וילקומיר."},{"i":9413,"n":"ברוידא, אפרים מריגא","b":"ר\"מ ומשגיח בישיבת ריגא. פרסם מאמרים ב\"פלפול החברים - ריגא תרפד - מאסף תלמידי ישיבת ריגא."},{"i":9414,"n":"ברוידא, אריה ליב מלבוב","f":"אברהם יוסף","k":"בעל מצפה אריה","bt":"תרא","bp":"הורדנא","dt":"תרפח - כח תמוז","b":"חתן ר צבי הירש אורנשטיין מבריסק ולבוב. רב בלמברג-תרסז על מקום ר יצחק שמלקיש. חיבר \"מצפה אריה\" למברג תרם (ר ברוך הרמלין חיבר כנגדו \"אפוד בד\"). \"מוקדם ומאוחר\" למברג תרף."},{"i":9415,"n":"ברוידא, אריה ליב מקאלווריה","f":"אהרן מקלוואריא","dt":"תקצט","b":"צדיק ועשיר, רב בקובנא, קאלואריא(=קאלווריה)-תקס על מקום אביו. חתניו - ר חיים ברוידא, ר אליהו בן יעקב מוילנא המכונה \"ר אלינקע יעקילס\". נספד ב\"אבן בוחן\" קרוטושין תרג."},{"i":9416,"n":"ברוידא, אריה ליב מקריווטש","f":"נפתלי הירץ","bt":"תקל","dt":"תקץ","b":"אב\"ד קריווטש. חתן ר שמואל מרגליות אב\"ד זלישטשיק."},{"i":9417,"n":"ברוידא, בנימין ביינש מזעזמיר","f":"שמואל יונה'ס","dt":"תקס","b":"מחכמי זעזמיר, פרנס בוילנא. אחיהם של - ר יעקב מוילנא, ר שלום מוילנא."},{"i":9418,"n":"ברוידא, בנימין מהורדנא","f":"אהרן מקאלואירא","dt":"תקעח - כט אב","dp":"הורדנא","b":"הראב\"ד האחרון בהורדנא על מקום ר אליעזר בעל מהדורה קמא והיה מחלוקת על הרבנות עם ר תנחום בנו של ר אליעזר. חתנו - ר יהושע השל אשכנזי על מקומו אחריו בהורדנא ועבר ללובלין על מקום אבותיו. בניו - ר חיים בעל תורה אור, ר דוד צבי מהורדנא (על מקום אביו?), חתניו - ר פנחס בן יוסף לנדא (חתנו של הנודע ביהודה), ר יהושע השל אשכנזי מלובלין."},{"i":9419,"n":"ברוידא, ברוך מקלם","f":"יעקב","k":"בעל בית יעקב","dt":"תרנו","dp":"ירושלים","b":"חיבר ספר \"בית יעקב\" ירושלים תרמד, \"מקור ברוך\" בתוך ספר \"נעימה קדושה\" שהדפיס מזקנו הגאון. פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":9420,"n":"ברוידא, גרשון זאב מליטא וארה\"ב","f":"יצחק איזיק","bt":"תרסז","bp":"טלז","b":"תלמיד ישיבת טלז. רב ברוקפורד-ארה\"ב-תרצא, פרובידנס-תרצב."},{"i":9421,"n":"ברוידא, דב בר מזבלודובה","f":"אהרן מקלוואריא","b":"רב בזאבלודאווא(=זאבלודוב)."},{"i":9422,"n":"ברוידא, דב בריש","f":"חיים ברודא","k":"בעל דברי בינה","b":"רב-שנת תר\"ל"},{"i":9423,"n":"ברוידא, דב מטלז וירושלים","dp":"ירושלים","b":"מחכמי טלז, עלה לירושלים. חתניו - ר אליהו ור משה פרלמן - בניו של הגדול ממינסק."},{"i":9424,"n":"ברוידא, דוד מאונגואר","b":"דיין באונגואר. פרסם מאמרים בשבח הציונות ב\"תל תלפיות\" - תרנב."},{"i":9425,"n":"ברוידא, דוד מוילנא","f":"שמעון","dt":"תקמז - י אלול","dp":"וילנא","b":"סו\"ד קהילת וילנא בזמן המחלוקת עם ר שמואל בן אביגדור-רבה האחרון של וילנא. הסכים על הביאור של ר שלמה דובנא-תקמג."},{"i":9426,"n":"ברוידא, דוד צבי מהורדנא","f":"בנימין מהורדנא","b":"רב בהורדנא."},{"i":9427,"n":"ברוידא, זאב וולף משאוולאן","b":"רב בשאוולאן-תרסג עד תרעה."},{"i":9428,"n":"ברוידא, חיים מהורדנא","f":"בנימין מהורדנא","k":"בעל תורה אור","dt":"תקפו - כז שבט","dp":"הורדנא","b":"רב וגביר בהורדנא. חתניו - ר בנימין קורנגולד, ר אליעזר לנדא מהורדנא בעל דמשק אליעזר."},{"i":9429,"n":"ברוידא, חיים מיאנוב וקאלווריה","f":"שלום בן יוסף","b":"רב בקלוואריע(=קאלווריה)-תקי, יאנוב-תקל. בנו ר אהרן על מקומו אחריו, עוד מבניו: ר אברהם מסערהיי, ר יצחק חריף ממייצער. אחיו - ר צבי הירש מלאזדווא, והורדנא"},{"i":9430,"n":"ברוידא, חיים צבי הירש מליטא","f":"יהושע","k":"בעל שארית חיים","b":"חתן ר יצחק מרעזיצע-\"איצעלע רעזיצער\". רב במחצית השניה של המאה ה-19 באליטא, נאמוקשט, שווקשנה, זאגר חדש, עלה לירושלים."},{"i":9431,"n":"ברוידא, יהודה יודל","b":"פרסם מאמרים ב\"שמעתתי דרבנן\" - אודסה תרמז, בהסכמת ר יוסף מוואקשנא בעל \"פורת יוסף\"."},{"i":9432,"n":"ברוידא, יהודה יידל","b":"רב-שנת תר\"ע"},{"i":9433,"n":"ברוידא, יהודה ליב מאראד","b":"רב באראד-תקס\"ו"},{"i":9434,"n":"ברוידא, יהודה ליב מפוסוואל","f":"יצחק ז\"ק","b":"רב בפאסוואל"},{"i":9435,"n":"ברוידא, יהודה ליב מצפת","b":"מחכמי קהלת הפרושים בצפת. חתם-תקעה על מינוי הגבאים ר ישראל משקלוב, ר צבי הירש כץ, ר משה בן יוסף."},{"i":9436,"n":"ברוידא, יהודה ליב משימאנדא","dt":"תקנו - לפני","b":"רב בשימאנדא, ואראד. הסכים על \"לדוד ברוך\" (בכת\"י) לר ברוך בן שמואל זאנויל בעל \"זרע שמואל\"."},{"i":9437,"n":"ברוידא, יהודה ממיקוליניץ","f":"נפתלי הירץ","k":"בעל זכרון יהודה","bt":"תקכ","dt":"תקף","b":"רב במיקוליניץ על מקום אביו. חתן ר מרדכי זאב אב\"ד למברג. גיסו של \"הישועות יעקב\". בזיווג שני חתן ר בריש הלפרין מברזאן. חיבר \"זכרון יהודה\" למברג תרנה."},{"i":9438,"n":"ברוידא, יהושע ראובן משעביז","f":"חיים צבי-שארית חיים","bt":"תרלז","b":"רב בשעביז-פלך ויטבסק-תרסד. פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס. חיבר ספר על הרמב\"ם ושו\"ע - בכת\"י."},{"i":9439,"n":"ברוידא, יוסף - א","f":"חיים","b":"בנו - ר שלום, נכדיו - ר חיים מיאנוב, ר צבי הירש מלאזדייא והורדנא."},{"i":9440,"n":"ברוידא, יוסף - ב","f":"חיים ברודא","b":"רב-שנת תר\"כ. בנו - ר אריה ליב בעל \"מצפה אריה\"."},{"i":9441,"n":"ברוידא, יוסף מטיקטין","f":"אהרן מקלוואריא","b":"רב בטיקטין."},{"i":9442,"n":"ברוידא, יוסף ממיאווע","f":"מרדכי ממיאווע","bt":"תרכז או תרלא","bp":"מיאווע","dt":"תשד-ה","dp":"אושוויץ","b":"תלמיד השב\"ס, ור מרדכי יהודה ליב וינקלר מהעדילא-מאדע. חתן ר ישראל פרנקל משטמנסדורף. רב במיאווע(=מיאווא)-תרסג על מקום גיסו - ר עקיבא שטרסר שעבר לטאקייא. נסמך מאת: אביו בעל שו\"ת מהר\"ם ברודא, בעל \"ישב מצרף\", השב\"ס. נספה בשואה. מתורתו ב\"שארית יוסף\". הו\"ל עם גיסו - ר עקיבא שטרסר - \"שו\"ת מהר\"ם ברודא\" לאביו. חתנו ר אליהו הלוי רוזנבליט דיין במיאווע."},{"i":9443,"n":"ברוידא, יעקב","f":"צבי הירש ברודא","b":"רב בקיצע-תר\"פ"},{"i":9444,"n":"ברוידא, יעקב מוילנא","f":"שמואל יונה'ס","dt":"תרנז - יד כסלו","dp":"וילנא","b":"גביר ופרנס מחכמי וילנא, וגבאי בימ\"ד הגר\"א, וחבר בכמה חברות קדש. נספד ב\"מקור חיים\" וילנא תרנה לר חיים סגלוביץ."},{"i":9445,"n":"ברוידא, יצחק חריף ממיצער","f":"חיים מיאנוב","b":"סגי נהור. רב במייצער."},{"i":9446,"n":"ברוידא, יצחק מליטא וארה\"ב","bt":"תרמד","bp":"שאט","dt":"תרצב - יג סיון","b":"רב בגירטיגולה-ליטא על מקום ר מאיר סטולביץ, דנוור-ארה\"ב."},{"i":9447,"n":"ברוידא, יקותיאל מקוריץ","f":"יוסף מזלוטשוב","b":"חתן ר אריה ליב מקרמניץ, וגיסו של ר יצחק איזיק מרובנא. רב בקוריץ, קרמניץ. נינו של הרבי ר השל."},{"i":9448,"n":"ברוידא, ישראל ליב","b":"מרביץ תורה ב\"תורת חסד\" בלודז-תר\"ס"},{"i":9449,"n":"ברוידא, ישראל מאונגוואר","b":"תלמיד ר יחזקאל מנייטרא. גביר מחכמי אונגוואר. נכדו - ר משה ברודי מאונגואר."},{"i":9450,"n":"ברוידא, ישראל ממיהאלוביץ","f":"שמואל מאונגוואר","k":"בעל אשי ישראל","dt":"תשד","b":"חתן ר אברהם שלמה גרינפלד מאונגוואר. דומ\"ץ במיהאלביץ(=מיהאלוביץ)."},{"i":9451,"n":"ברוידא, ליב","b":"רב-שנת תר\"ל"},{"i":9452,"n":"ברוידא, ליבש מקריוויש","dt":"תקעו - א אלול","b":"רב בקריוויש"},{"i":9453,"n":"ברוידא, מאיר מסעניץ","f":"מרדכי ברודא","b":"רב בסעניץ-תק\"ס"},{"i":9454,"n":"ברוידא, מנחם מקאליב","f":"אברהם ברודא","bt":"תרכב","dt":"תרצח - ח אב","b":"חתן ר פיבש מטאש. רב בטאש-תרלט וראש ישיבה על מקום חותנו, קאליב-תרנט וראש ישיבה על מקום ר דב בריש אברהם בנט. חבר המועצה הארצית לקהלות האורטודוכסיות בהונגריה."},{"i":9455,"n":"ברוידא, מרדכי","b":"תשובה אליו - מהר\"י הכהן."},{"i":9456,"n":"ברוידא, מרדכי מאונסדורף","b":"נכד ר אברהם ברוידא מפפד\"מ. דיין באונסדורף-תקעב, וממלא מקום זמני לר זלמן וולף בעל \"עמק המלך\". נכדו - ר אברהם בעל \"פרי החג\"."},{"i":9457,"n":"ברוידא, מרדכי ממיאווע","f":"נתן נטע משוסבורג","k":"בעל חדושי מהר\"ם ברוד","r":"אב\"ד מיאווא, וטורא לוקא","bt":"תקעז","dt":"תרמג - ג טבת","b":"תלמיד מהר\"ם א\"ש מאוגנוואר. רב במיאווע(=מיאווא) כ-50 שנה. רבו המהר\"ם א\"ש אמר עליו ש\"הכלה כמותו בכל מקום\".","bk":[["חידושי ושו\"ת מהר\"מ ברודא",""]]},{"i":9458,"n":"ברוידא, מרדכי מראווא","b":"פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":9459,"n":"ברוידא, מרדכי משוסבורג","dt":"תקעה - ז אייר","b":"רב בשוסבורג"},{"i":9460,"n":"ברוידא, משה ברוך משקודוויל","b":"מגיד שיעור \"דף\" לבעלי בתים למדנים בשקודוויל."},{"i":9461,"n":"ברוידא, משה זאב מואקשנא","f":"יוסף","k":"ר משה'ל חריף","bt":"תקפח","dt":"תרלג","b":"ר\"מ בואקשנא. אחיו מאמו - ר אברהם שניצר מראסיין וראזאליא. מתלמידיו - אחיינו (בן אחותו) ר יוסף יהודה ליב בלוך מטלז."},{"i":9462,"n":"ברוידא, משה חיים ממינסק","dt":"תרנב - כד אדר","dp":"וארשא","b":"גביר במינסק-תרל-תרם. חתן ר יוסף צוקרמן ממינסק, והיה מראשי הת\"ת יחד עם חותנו."},{"i":9463,"n":"ברוידא, משה מאונגוואר","f":"שמואל מאונגוואר","b":"דיין באונגוואר. אחיו של ר ישראל בעל \"אשי ישראל\"."},{"i":9464,"n":"ברוידא, משה מטיקטין","f":"אברהם מפרג-אשל אברהם","k":"בעל אהל משה","dt":"תקב - כו כסלו","b":"חתן ר ירמיה (או ישראל) פירסט מאה\"ו. מרביץ תורה, רב בהענא, טיקטין-תעד, בומברג-תעט, וורמייזא-תצב, פפד\"מ. חיבר הגהות לספר אביו \"אהל משה\". גיסו (נשואים לשתי אחיות) - ר משה בן מרדכי רוטנברג מאלטונא."},{"i":9465,"n":"ברוידא, נחום חיים מוארשא וילנא","f":"שמריהו מקרעווע","dt":"תרטו - ח ניסן","dp":"וארשא","b":"גביר מחכמי וילנא. אחיו של ר יצחק יהודה ליב רבינוביץ מוילנא. נזכר ב\"נחלת עולמים\". מצבתו שנוסחה בידי אד\"ם הכהן נדפסה ב\"יתר שירי אדם\"."},{"i":9466,"n":"ברוידא, נחמיה מוילנא","f":"אהרן טייבילס","dt":"תרמא - טז סיון","b":"פו\"מ בוילנא. גבאי בשניפישוק."},{"i":9467,"n":"ברוידא, ניסן מהורודוק","bt":"תריז","dt":"תרסד - יב ניסן","b":"דרשן,מראשוני חובבי ציון, רב בשינבקה-תרלא, קראווי-תרלח, הורודוק-תרנא וחתנו ר אברהם זליג ציוני על מקומו אחריו."},{"i":9468,"n":"ברוידא, נפתלי הרץ ממיקוליניץ","f":"אהרן מקלוואריא","bt":"תק","dt":"תקע","b":"(יש הסבורים כי היה בנו של ר יצחק אשכנזי מברודי). חתן רא\"ל אוירבך מסטניסלב. אב\"ד מיקוליניץ-תקם. בנו ר אליעזר ליפמן - רב בלנצקרינין וקמניץ-פודולוסק."},{"i":9469,"n":"ברוידא, נתן נטע משוסבורג","f":"מרדכי ברודא","b":"רב באנדוש,שוסבורג-תק\"פ"},{"i":9470,"n":"ברוידא, צבי הירש","f":"לייב","bt":"תרכה","bp":"שקוד-ליטא","dt":"תרעג","dp":"קלם","b":"חתנו ובן אחיו של ר שמחה זיסל זיו מקלם. מנהל הישיבה בקלם על מקום חותנו. מתלמידיו ר אליהו לאפיאן, ר אליהו דסלר, ר ירוחם ליבוביץ, ועוד. עלה לארץ-תרסז והצטרף לאביו שציוהו לחזור אל תלמידיו בקלם."},{"i":9471,"n":"ברוידא, צבי הירש מלאזדיי","f":"שלום בן יוסף","b":"חתן ר ישראל בן שלום ז\"ק מבירז. רב בזאבלודוב, לאזדיי(=לאזדווא)-תפח, הורדנא. אחיו - ר חיים מיאנוב."},{"i":9472,"n":"ברוידא, צבי הירש מסלנט ואלסיאד","f":"אהרן מקלוואריא","b":"רב באלסיאד, טלז, סלנט-תר. רבו של ר ישראל סלנטר."},{"i":9473,"n":"ברוידא, צבי הירש מקיצע וסמניץ","f":"דוד מברודא","k":"בעל תאומי צביה","bp":"אונגריש-בראד","dt":"תקפא-ד -כא כסלו","dp":"קיצע","b":"חתן ר יעקב. רב בסעמניץ, קיצע-תקלה - כ-46 שנה ור ליב פופר על מקומו אחריו. נספד ע\"י החת\"ס. חיבר \"תאמי צביה\" ונדפס עם \"ארץ צבי\" - וינה תקפג. הסכים על \"בינה לעתים\" לר יונתן איבשיץ-תקנז."},{"i":9474,"n":"ברוידא, שאול","b":"רב-שנת ת\"כ"},{"i":9475,"n":"ברוידא, שלום מוילנא","f":"שמואל יונה'ס","dt":"תקסה","b":"מחכמי וילנא. אחיהם של - ר יעקב מוילנא, ר בנימין ביינש מזעזמיר ווילנא. בנו - ר אברהם בעל \"בית ועד\"."},{"i":9476,"n":"ברוידא, שלום מוילנא","f":"אהרן","dt":"תקסח - טו ניסן","dp":"וילנא","b":"מחכמי וילנא, בנו - ר אברהם אהרן בעל בית הגדול."},{"i":9477,"n":"ברוידא, שלמה זלמן מירושלים","b":"ר\"מ בישיבת חברון בירושלים."},{"i":9478,"n":"ברוידא, שלמה זלמן ממרגנטהים","f":"אברהם מפרג ופפד\"מ","dt":"תקב - ו אייר","dp":"מרגנטהיים","b":"רב במרגנטהיים-תפט."},{"i":9479,"n":"ברוידא, שמואל","b":"דומ\"צ בנייזטץ-תקע\"ג"},{"i":9480,"n":"ברוידא, שמואל מאונגוואר","f":"ישראל מאונגוואר","dt":"תרסח - טו תשרי","dp":"אונגוואר","b":"נכד ר מרדכי ברודא מאונסדורף. תלמיד הכת\"ס, ור אברהם יצחק וינברגר מקלינורדין. חתן ר שמעון יהודה ליכטשין מסאבינוב. מחכמי אונגוואר. מתורתו בספר בניו ר ישראל ברודי - בעל \"אשי ישראל\", ר משה מאונגואר."},{"i":9481,"n":"ברוידא, שמואל מבריסק","b":"מחכמי בריסק, נזכר ב\"גבעת שאול\" לר שאול מלומזה."},{"i":9482,"n":"ברוידא, שמחה זיסל מירושלים","f":"אברהם","b":"נכד ר יעקב דוד ספקטור-אחיו של ר יצחק אלחנן מקובנא. ראש ישיבת חברון בירושלים"},{"i":9483,"n":"ברוידא, שמחה יצחק מחברון","dt":"תרפט","dp":"חברון","b":"תלמיד ישיבת וילקומיר, עלה לארץ ולמד בישיבת חברון. נרצח עק\"ה במאורעות. פרסם מאמרים בפרסם מאמרים ב\"תבונה\" - קובנא תרפא."},{"i":9484,"n":"ברוידא, שמריהו","b":"רב בתולרה,מו\"צ בקרעווי"},{"i":9485,"n":"ברוידס, אברהם מליטא וארץ ישראל","f":"יצחק","k":"בעל בתלם","bt":"1907","bp":"וילנא","b":"משורר. עלה לארץ-1923, ממייסדי הסתדרות הנוער העובד, מזכיר אגודת הסופרים. חיבר ספרי שירה ובהם גם \"אשנב\" - 1934, \"מבית\", ועוד."},{"i":9486,"n":"ברוידס, יצחק","f":"מנחם מאיר","k":"בעל א שטיין אין וועג","bt":"1897","bp":"וילנא","dt":"1946","b":"תלמיד ישיבת סלובודקה. עסקן ציוני, למד באוניברסיטת ברלין. עורך \"פריינד\" בטאון ציוני בליטא, עלה לארץ 1924. מזכיר התאחדות בעלי מלאכה. חיבר גם \"וילנא הציונית ועסקניה\" ת\"א תש, \"אגדות ירושלים דליטא\", ועוד."},{"i":9487,"n":"ברוידס, ראובן אשר","f":"יוסף","k":"בעל הדת והחיים","bt":"1851","bp":"וילנא","dt":"1902","b":"נתפרסם כעילוי בגיל 12 בוילנא, לאחר שנתייתם נדד במקומות שונים. סופר ומשורר מתנועת ההשכלה. חיבר גם \"מודה ועוזב\", ועוד."},{"i":9488,"n":"ברויל, נפתלי הרץ מקולוניא","f":"קלונימוס","dt":"תטז - יב תמוז","dp":"דייץ","b":"רב בדייץ ומדינת קולוניא."},{"i":9489,"n":"ברוין, אביגדור מקאפוש","b":"מראשי קהלת קאפוש, חתם-תרמב על מינוי ר יהושע פריד."},{"i":9490,"n":"ברוין, אליעזר מוינה","b":"פרסם מאמרים ב\"הלכות החדש\" - טירוני תרצא - קובץ מאת תלמידי ר שמואל דוד אונגר מטירנוי."},{"i":9491,"n":"ברוין, אפרים מטשאבא","dt":"תרכא","b":"רב בטשאבא"},{"i":9492,"n":"ברוין, זאב מקאפוש","dt":"תרפא - כו אב","b":"תלמיד ר יהושע פריד האדמור מקאפוש."},{"i":9493,"n":"ברוין, חיים יהודה מדעש","f":"ישראל מנחם מבריזאויץ","bt":"תרנו","dt":"תשד","dp":"אושוויץ","b":"תלמיד ר משה גרינוולד בחוסט. חתן ר יצחק יחיאל פאנט מדעש. ר\"מ בישיבת דעש-תרפה, רב באיקלוד-ליד סאמוש-אויוואר והקים שם ישיבה \"תורה ומלאכה\" ובה למדו נגרות ואת תוצרת הישיבה מכרו בקלויזנבורג (רהיטי ביה\"ח היהודי שם היו מתוצרת הישיבה), בתרצט עברה הישיבה לקלויזנבורג והתאחדה עם ישיבת הרב גלזר שם. נספה בשואה. הו\"ל ירחון \"הלכה למעשה\" דעש תרצג. פרסם מאמרים ב\"מקבציאל\" - גרבה תרצה."},{"i":9494,"n":"ברוין, חיים מאיר מלונדון ונ\"י","k":"בעל אמרי חיים","b":"רב בלונדון, ניו יורק."},{"i":9495,"n":"ברוין, חנניה יו\"ט ליפא","f":"ישראל ברוך","k":"בעל זכור לאברהם","b":"תלמיד ר אליעזר דוד גרינוולד בסטמר. חתן ר מאיר הולנדר מכפר אורישור. מחכמי גרוסורדין. חסיד סיגט-סטמר. נספה בשואה. חיבר גם \"צדיק כתמר יפרח\", ועוד."},{"i":9496,"n":"ברוין, יהושע מפודקמין","b":"מחכמי פודקמין. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד."},{"i":9497,"n":"ברוין, יוסף יהודה מניו יורק","dt":"תשיח","b":"רב בברונקס"},{"i":9498,"n":"ברוין, יעקב יואל מפרשבורג","bp":"סלובקיה","b":"למד באוניברסיטה בשוייץ, התקרב למזרחי, הצטרף לאגודת ישראל והיה מראשי אגודת ישראל בפרשבורג-תרף. מעורכי \"יידישע פרעסע\" של אגודת ישראל."},{"i":9499,"n":"ברוין, ישראל ברוך","f":"חיים מאיר","k":"בעל כנסת ישראל","dt":"תשא - יז כסלו","dp":"גרוסורדין","b":"תלמיד ר יהודה ליכטנשטין מבעטלען. חתן ר אברהם שטרן מביהר קערעסטעש. מחכמי סאסרגן, אזדי סט פטר, גרוסורדין. חיבר גם \"אבן ישראל\"."},{"i":9500,"n":"ברוין, ישראל חיים (העברי) מבוד","k":"בעל בית ישראל","bt":"תרכו או תרכט","dt":"תשו - כט תשרי","dp":"בודפסט או קאלוב","b":"נכד ר כלב פיבל מדיאנדיאש (ולא בנו כפי שיש שרשמו בטעות). תלמיד השב\"ס, ור יקותיאל יהודה טיטלבוים מסיגט. בזיוו\"ש חתן ר ברוך בנדיט ליכטנשטין מקראסנא. רב בהעללע (אשכנז)-תרנח, בודפשט-תרעג (בביהמ\"ד ארץ ישראל שטיבל). ניצל מהשואה. חיברת \"מקוה ישראל\" ועוד."},{"i":9501,"n":"ברוין, ישראל מנחם מברזוביץ","bt":"תרכא-ב","dt":"תשה - ה כסלו","b":"חתן ר עמרם גרינוולד, וגיסו של בעל \"ערוגת הבושם\". תלמיד ר שמואל שמלקא קליין בעל \"צרור החיים\". רב בברזוביץ-הונגריה-תרן כ-50 שנה. נספה בשואה. חתנו הוא אחיינו - ר יעקב חזקיה גרינוולד בעל \"ויגד יעקב\" האדמור מפאפא."},{"i":9502,"n":"ברוין, ישראל מענטש(=אנץ')","b":"דיין בענטש(=אנץ')-מחוז אבאוי טורנא כ-40 שנה. בשנת תקץ הפכה הקהלה לעצמאית ואז התמנה ר יחזקאל שרגא ציטרון כרבה הראשון."},{"i":9503,"n":"ברוין, כלב פיבל מדיאנדיאש-פאטא","b":"רב בדיאנדיאש-פאטא. נכד או חתן לר פיבל בוסקוביץ מדיאנדיאש. בניו - ר כלב פיבל מדיאנדיאש, ור עזריאל משארקאני."},{"i":9504,"n":"ברוין, מאיר מוויצען","b":"שו\"ב בוייצען."},{"i":9505,"n":"ברוין, משה מדאברי","f":"שמואל","b":"רב בדאברא-תר. סירב להוראת ר נפתלי מרופשיץ לכהן כאדמור. תלמיד חבר של הדברי חיים. בנו ר אברהם יעקב על מקומו אחריו בדאברא - עלה לארץ (ומסר את הרבנות לנכדי צאנז-רופשיץ). בנו ר יוסף שו\"ב בדאברא."},{"i":9506,"n":"ברוין, עזריאל משארקאני","bp":"דיאנדיאש-פאטא","dt":"תרצד - בערך","b":"נכד ר כלב פיבל בוסקוביץ מדיאנדיאש. תלמיד השב\"ס. חתן ר נתן מילר מסעטשין. רב בשארקאני(=סיל שארקני)-תרמו. פרסם מאמרים ב\"וילקט יוסף\". אחיו - ר ישראל חיים מהאללע."},{"i":9507,"n":"ברוין, שלמה זלמן מניו יורק","k":"בעל שערים מצויינים","b":"רב בארה\"ב-תשט. פרסם מאמרים ב\"הפוסק\" - תל אביב תש-תשיד."},{"i":9508,"n":"ברוין, שלמה זלמן מפוטנוק","dt":"תרלג","b":"רב בפוטנוק-תרי. בקי בשפות וניסה להנהיג בקהילה דרשות בהונגרית ובגרמנית - והיה מחלוקת כנגדו מצד ר הלל ליכטנשטין מסיקסו-הסמוכה לפוטנוק."},{"i":9509,"n":"ברוין, שלמה מפודקמין","b":"מחכמי פודקמין. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד."},{"i":9510,"n":"ברוין, שמואל יהודה","dt":"תרן - טז חשון","b":"נפטר ללא ילדים."},{"i":9511,"n":"ברוין, שמעון","b":"פרסם מאמרים ב\"החיים\" - אונגואר תרפב."},{"i":9512,"n":"ברוינורט","k":"ראה: ברוינרט","b":"פרסם מאמרים ב\"בית הכנסת\" - תל אביב תשו."},{"i":9513,"n":"ברוינפלד, אריה ליב מקרעניץ","f":"נתן יוסף","bt":"תרי","dt":"תרפב - כד חשון","b":"אב\"ד קרעניץ (=קריניצה)-גליציה וגבאי ארץ ישראל בהשתדלות הדב\"ח. חתן ר יצחק רוטנברג מגורליץ. נכדו ר דוד צימטבוים רב על מקומו אחריו-תרפב."},{"i":9514,"n":"ברוינפלד, יעקב מזמיגרוד","k":"בעל אמרי יעקב","bt":"תרמ","bp":"קראקא","dt":"תשב","b":"חתן ר ברוך גרוס, מחכמי זמיגרוד. נספה בשואה. חיבר \"אמרי יעקב\". פרסם מאמרים ב\"אסיפת חכמים\" - אושפצין תרצד, \"אהל מועד\" תרנח, \"קהלת אשר\" - אושפיצין תרפג."},{"i":9515,"n":"ברוינפלד, נפתלי מזמיגרוד","f":"יעקב","k":"בעל דברי נפתלי","bt":"תרסה","dt":"תשכו","b":"חתן ר ברוך יוסף וקסמן, ובזיוו\"ש חתן ר דן ולד. מחכמי אושפיצין(=אושביץ), איבד את משפחתו בשואה. עבר למינכן אחרי השואה לסייע לניצולים, עבר לניו יורק. חיבר \"דברי נפתלי\" כפר חבד תשכח, ועוד שנדפסו בקבצים שונים. פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח, \"אחיאסף\" - סטריזוב תרפט, \"אסיפת חכמים\" - אושפצין תרצד, \"הבאר\" - זאמושץ-וארשא תרפד, \"דגל הרבנים\" - וארשא תרפו, \"יבנה\" - לבוב תרפט, \"כתר תורה\" - אושפיצין תרצט, \"הנצח\" - לבוב תרפז, \"קהילת יעקב\" - זבארוב-סלובקיה תרפה, \"שערי ציון\" - ירושלים תרפא."},{"i":9516,"n":"ברוינפלד, נתן יוסף מקרניץ","b":"היהודי הראשון שבא מצאנז והתישב בקריניצה-קרניץ. עלה לצפת. בנו ר אריה ליב - רב בקרניץ."},{"i":9517,"n":"ברוינפלד, צבי הירש מקששוביץ","f":"מאיר","bt":"תרלה","bp":"קראקא","dt":"תש","b":"מחכמי בקששוביץ(=בזששאוויץ). פרסם מאמרים ב\"אסיפת חכמים\" - אושפצין תרצד, \"אהל מועד\"-תרסא."},{"i":9518,"n":"ברוינפלד, שבתי שפטל מערדא","f":"יצחק","bt":"תר","dt":"תרעח - ד טבת","b":"תלמיד הכת\"ס, ור יהודה אסאד. גר במעזא-טשאטה-תרלד, רב בערדא-טעלעק-תרלט. חתנו ר מנחם גליק מערלוי(=אויהל)."},{"i":9519,"n":"ברוינר, אברהם","f":"יהודה","dt":"תשנח","dp":"ירושלים","b":"נכד ר אברהם הלוי גרובנר. עלה לארץ-תרפג. חתן ר אלעזר קרימלובסקי מראדום. חסיד גור מאנשי פאג\"י."},{"i":9520,"n":"ברוינר, אהרן יהושע מדזיאלשיץ","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":9521,"n":"ברוינר, נחמיה מקשנוב","f":"דוד","dt":"תרצו","b":"מחכמי קשנוב. חתן ר אברהם גרובנר מאושפיצין שהיה מחסידי רדומסק שם (ובגלל חותנו היה היחיד שהלך עם ספודיק גבוה). בנו ר יהודה עלה לארץ-תרף."},{"i":9522,"n":"ברוינר, שלום אלחנן","b":"פרסם מאמרים ב\"אור תורה\" - לבוב תרפו."},{"i":9523,"n":"ברוינר-בראונר, ישראל","f":"דוד הלוי","b":"חתן ר מנחם מנדל מבורשטשוב ודוקלא. מלמד במושציסק. הו\"ל \"נחלת בנימין\" - הוסיאטין תרסז. מחותן עם ר יוחנן לוריא."},{"i":9524,"n":"ברוינרט, חיים מרדכי מטשכנוב","k":"בעל סתירת זקנים","bt":"תרמ-א","bp":"אוסטרלנקה-ליד לומזה","dt":"תשי - ג אדר","b":"חסיד אלכסנדר. תלמיד הרב מקאליש, והרב מסוכטושב. רב בצורבין(=טשרווין)-תרסח, כורזיל(=הורז'ל)-תרעד, טשכנוב-תרעו, מראשי ה\"מזרחי\" בפולין. עלה לארץ-תשג וכיהן כראב\"ד בתל אביב. חיבר גם \"אוצר החיים\", \"אומר ודברים\". פרסם מאמרים ב\"בית שמואל\" - וארשא תרצו, \"ירושלים\" - וארשא תרצו, \"בית הכנסת\" - תל אביב תשו."},{"i":9525,"n":"ברויצר, יצחק מקומרנא","dt":"תשג","b":"דיין בקומרנא אצל ר מרדכי גלנצר. נספה בשואה."},{"i":9526,"n":"ברוך"},{"i":9527,"n":"ברוך"},{"i":9528,"n":"ברוך","b":"מפורסם בצדקתו,נפלאות מדובר בו,מג\"מ בפרויקו-תק\"פ"},{"i":9529,"n":"ברוך","f":"דוד","k":"ר' ברוך מארץ יון","b":"שר ונגיד-תק\"י. בנו ר אלעזר - חתן היעבץ."},{"i":9530,"n":"ברוך","f":"אריה ליב מסדילקוב","b":"רב-שנת תר\"ל"},{"i":9531,"n":"ברוך","f":"אברהם משה מרישא","b":"נכד ר יעקב בן ברוך מטיטשין, והעתיק בכת\"י את ספר זקנו."},{"i":9532,"n":"ברוך (בורוכוביץ), יהודה ליב","k":"בעל אוצר ספרות ישראל","bt":"1873","bp":"טאווריג","dt":"1953","dp":"תל אביב","b":"סופר ומחנך. תלמיד ישיבות ליטא, ד\"ר מאוניברסיטת ברן. מורה לספרות בגימנסיה העברית בוילנא. חיבר שירים ספורים ומאמרים בכתבי עת עבריים. חיבר גם \"ראשי פרקים בתלמוד\", ועוד. תרגם ספרים שונים."},{"i":9533,"n":"ברוך (ישראל) מלאזניא","f":"שניאור זלמן","dp":"סעלעש","b":"חתן ר ברוך בן קדש. רב בלאזניא-תק\"כ. בניו - ר שניאור זלמן בעל התניא, ר יהודה ליב מיאנוביץ בעל \"שארית יהודה\"."},{"i":9534,"n":"ברוך - מדפיס בוילנא","f":"צבי מנווידווהר","b":"מדפיס בוילנא-תקנד."},{"i":9535,"n":"ברוך - משפחה","b":"משפחת רבנים."},{"i":9536,"n":"ברוך בירך מקולבסוב","bp":"[חרסון]","b":"למד אצל בעל ההפלאה בפפד\"מ. התקרב לר לוי יצחק מברדיטשוב. מחכמי קולבסוב. בספר \"זכרון יעקב\" לר יעקב הלוי ליפשיץ, כותב אודותיו שהיה דרשן נודד שהגיע לליטא ומשך אחריו את ההמון עד שר חיים מוולזין הזהיר מפניו. אביו היה רב בחרסון. נדד ברחבי אירופה, הופיע במינסק ועסק בדרשות ורפואות. ר חיים מוולוזין יצא בחריפות כנגדו. ומאז גורש מכל מקום אליו הגיע. הדפיס חובת הלבבות מקוצר ומתורגם."},{"i":9537,"n":"ברוך בן יעקב משלוניקי","k":"בעל נעים זמירות","dt":"תש..","b":"מורה והיסטוריון בשלוניקי, נשיא אגודת \"נעים זמירות\"-תרפה. הו\"ל ספר פזמונים \"נעים זמירות\" עם מבוא בעברית מההיסטוריון שלמה רוזניס, ובלאדינו מאת ברוך בן יעקב - שלוניקי תרפט. נספה בשואה."},{"i":9538,"n":"ברוך בן יעקב משקלוב","bt":"1752","dt":"ה'תקע 1810","bk":[["דרך ישרה",""],["עמודי השמים",""],["קנה המדה",""]]},{"i":9539,"n":"ברוך בן ציון ממוסט","f":"נח חיים","b":"רב במאסט"},{"i":9540,"n":"ברוך בנדט","f":"אליהו קאליקולר","b":"בנו - ר אהרן מאיר יואלסון ונכדו ר אליהו מפרידריכשטט."},{"i":9541,"n":"ברוך בנדט מבאשן ווירונה","b":"רב בוירונה-שסא. תשובה ממנו ב\"פלגי מים\" אודות מחלוקת המקוה ברוויגו."},{"i":9542,"n":"ברוך בנדט מגורזד - א","f":"רב בפוזנא","b":"ניצל בפרעות תח ותט בלובלין. מחכמי גורזד. מצאצאיו - ר שמואל חסיד מראסיין."},{"i":9543,"n":"ברוך בנדט מגורזד - ב","f":"יהודה ליב מגורזד","b":"רב בגורזד-פלך קובנא על מקום אביו. אחיו - ר אליעזר מזאגער."},{"i":9544,"n":"ברוך בנדט מהאלוסק","f":"שמחה בונם מפיחאוויטש","b":"מג\"מ בהאלוסק, נעשוויז. בנו - ר מנחם מנדל משקלוב וירושלים."},{"i":9545,"n":"ברוך בנדט מהורדנא וזלבלדובה","k":"בעל נר תמיד","b":"ר\"מ ודרשן בהורדנא, רב בזבלדובה, זעטל-תקכ. חיבר \"נר אלקים\", \"נר תמיד\" - נוידואהר תקמט."},{"i":9546,"n":"ברוך בנדט מטאווריג","f":"מרדכי יהודה","b":"דיין בטאווריג, חתם-תרסג עם ר אברהם אהרן בורשטין ור ברוך נתנאל נייויידל."},{"i":9547,"n":"ברוך בנדט ממזריטש(=ליד פפד\"מ)","f":"מיכאל משה","b":"מחכמי מזריטש-ליד פפד\"מ-תקעב. חיבר \"גירסא דינקותא\" יחד עם ר יצחק איזיק אוירבך - אלטונא תקסח."},{"i":9548,"n":"ברוך בנדט מפרשבורג","b":"דיין בפרשבורג-תר\"י"},{"i":9549,"n":"ברוך בנדט משאוויל(=שעוועל)","f":"שמואל חסיד מראסיין","dp":"שעוויל","b":"מחכמי שעוועל"},{"i":9550,"n":"ברוך בנדט משקלוב","b":"רב בשקלוב-ת\"ק"},{"i":9551,"n":"ברוך בנדיט בר\"י כץ מברלין","b":"מראשי הקהילה בברלין-תקד, חתם על כתב ההסכם עם ר דוד פרנקל הראב\"ד בברלין."},{"i":9552,"n":"ברוך בנדיט מאלטונא","f":"מנש","k":"ר בנדיט ר מנש","dt":"תקיב - כט ניסן","b":"מוהל ודיין באלטונא-תעב בזמן ר יחזקאל קצנלנבוגן ומילא את מקומו עד שהגיע ר יונתן איבשיץ. היה מתומכי ר יונתן איבשיץ במחלוקת. חתנו ר ישעיה יפה."},{"i":9553,"n":"ברוך ברסלוי מפרשבורג","b":"מראשי קהלת פרשבורג. חתם על תקנות ר מאיר ברבי-תקכח."},{"i":9554,"n":"ברוך גד מירושלים","b":"מחכמי ירושלים, בשנת תו בשליחות לבבל ופרס ובשובו סיפר על פגישה עם אחד מבני עשרת השבטים, ואף הביא אגרת שנכתב על ידי בני משה. האגרת עשתה רושם רב בירושלים והועתקה לבקשת שליח האשכנזים ר נתן שפירא בשנת תיז."},{"i":9555,"n":"ברוך הכהן הפייטן","f":"יחיאל","b":"חיבר סליחה \"אני הוא הקונן\" על גזרות ה'קז."},{"i":9556,"n":"ברוך הכהן מביעלסקי","f":"נתן מתתיהו הכהן","b":"רב בביעלסקי"},{"i":9557,"n":"ברוך הכהן מלעבעדאווא","f":"נחום שטיינקריצער","b":"מחכמי לעבעדאווא. חתן או נכד ר ליב מוויליקא. חתנו - ר יצחק יעקב תורק מקאחאווקא."},{"i":9558,"n":"ברוך הכהן מניו יורק","k":"בעל שביל הזהב","b":"רב בניו יורק-תרסג."},{"i":9559,"n":"ברוך הכהן מסרייבו","b":"רב בסרייבו-שץ,"},{"i":9560,"n":"ברוך הכהן מקושטא","b":"מחכמי קושטא-שנת ת'"},{"i":9561,"n":"ברוך הלוי מאלסנדרי","f":"אברהם הלוי","b":"רב באלסנדרי"},{"i":9562,"n":"ברוך הלוי מבריסק","b":"בזיוו\"ש חתן ר דוד אשכנזי בן ה\"חכם צבי\". מחכמי בריסק, ברוד והיה גבאי ארץ ישראל. עלה לארץ, בשליחות בברודי לטפל בקופה שהוזנחה עקב עזיבתו. בניו ר דוד שלמה מברסטשקא, ר משה חיים מדובנא, ר אברהם יקותיאל מסטעפין."},{"i":9563,"n":"ברוך הלוי מקאליש ולבוב","k":"ר' ברוך הלוי מקאליש","b":"דיין ור\"מ בלבוב, חתם-תנב מטעם הקהלה."},{"i":9564,"n":"ברוך הנשיא ממצרים","b":"ראש עדת הקראים במצרים-תב."},{"i":9565,"n":"ברוך ישראל מוואהין","dt":"תרמד","b":"חתן ר אשר לעמיל מוואהין. רב בוואהין על מקום חותנו."},{"i":9566,"n":"ברוך כץ מאוהניב","f":"יהושע השל","b":"גביר באוהניב-תקלה, יצא לחופשי לאחר הלשנה, יחד עם בנו - צבי הירש."},{"i":9567,"n":"ברוך מאוסטרהא","f":"זאב וולף בן ברוך מאו","dt":"תקמו - יז אד\"ב","dp":"אוסטרהא","b":"בנו של פרנס אוסטרהא. מחכמי אוסטרהא."},{"i":9568,"n":"ברוך מאוסטרהא","f":"ישראל","dt":"תקנט","dp":"אוסטרהא","b":"מחכמי אוסטרהא, גבאי בח\"ק. חתם כמה פעמים בפנקס ועל תקנה-תקלב והמגילה-תקנב."},{"i":9569,"n":"ברוך מאיטליה","f":"שמואל","b":"מחכמי איטליה והיה מהמתירים במחלוקת המקוה ברוויגו."},{"i":9570,"n":"ברוך מאיר מניאמץ","b":"רב בניאמץ"},{"i":9571,"n":"ברוך מאלשאן מוילנא","f":"מנחם נחום מאלשאן","dt":"תקצא - כו סיון","dp":"וילנא","b":"מחכמי וילנא. תלמיד הגר\"א."},{"i":9572,"n":"ברוך מאר\"ץ","f":"יצחק","bt":"ד'תתי","bp":"ספרד","dt":"ד'תתפה","b":"ראש ישיבה, מחכמי ארם צובא, חיבר חידושים לש\"ס"},{"i":9573,"n":"ברוך מאשכנז","b":"מחכמי אשכנז-ר\"פ"},{"i":9574,"n":"ברוך מברזניץ","b":"רב בברזניץ-תק\"מ"},{"i":9575,"n":"ברוך מבריסק","b":"עלה לארץ בשיירת תקלז או סמוך לכך."},{"i":9576,"n":"ברוך מגולדינגן","f":"אהרן","b":"מחכמי גולדינגן-תרה, העתיק את פנקס הקהלה."},{"i":9577,"n":"ברוך מגיד מישרים מריקא","f":"מאיר","bt":"תפא","dt":"תקצא - כה אייר","b":"מצאצאי בעל ה\"אקדמות\". ליוה את הבעשט בכמה ממסעותיו. תלמיד ר לוי יצחק מברדיטשוב ומלמד לילדיו. מגיד בריקא. נזכר ב\"ספרן של צדיקים\"."},{"i":9578,"n":"ברוך מגרמייזא","f":"יצחק","k":"בעל ספר התרומה","b":"מגדולי הפוסקים ובעלי התוספות-ד'תתקס. תלמידו של ר יצחק בן משואל מדנפירא, חברו של ר שמשון משאנץ. כתב ספר \"התרומה\" ונציה רפג. בשנת ד תתקצז (1237) עלה לארץ דרך קנדיא. בהיותו בארץ ישראל הגיה את ספרו של ר אשתורי הפרחי \"כפתור ופרח\" וכמה מהערותיו שובצו בספר. יש המזהים אותו עם ר ברוך מארץ יוון (המופיע ברא\"ש)."},{"i":9579,"n":"ברוך מדוברומיל","f":"יעקב מהרובישוב","dt":"תרא - ו שבט","dp":"למברג","b":"חתן ר מאשיל. רב בדוברומיל. (במצבות קדש - תאריך פטירתו - תסא)."},{"i":9580,"n":"ברוך מוורמייזא - אבי המהר\"ם","f":"מאיר","dt":"לה-ו","dp":"ורמייזא","b":"אביו של המהר\"ם מרוטנברג."},{"i":9581,"n":"ברוך מוילנא","f":"שלמה זלמן מברסטביץ","k":"ברוך בר\"ז","dt":"תרכא - כז אלול","dp":"וילנא","b":"גביר מחכמי וילנא ונדד לרגל עסקיו וחזר בסוף ימיו לוילנא. תרם סכום גדול לקנית חצר קלצקי לטובת גמ\"ח - ומההכנסות חילקו כל שנה לעניים. נפטר ללא ילדים."},{"i":9582,"n":"ברוך מוילנא","f":"שמואל מזסקביץ","dt":"תקפט - א סיון","dp":"וילנא","b":"מחכמי וילנא, נקבר לצד אחיו - ר יוסף זסקביצר."},{"i":9583,"n":"ברוך מזאלודק","dt":"תרח - כה אב","dp":"הורדנא","b":"רב בזאלודק."},{"i":9584,"n":"ברוך מזולקוא","f":"ישראל","b":"מחכמי זולקוא, חתם-תיט על תקנת הקהלה, ועל בחירת ראשי הקהלה-תמו."},{"i":9585,"n":"ברוך מזליחוב","b":"תלמיד ר אשר מסטולין."},{"i":9586,"n":"ברוך מחלב","f":"שמואל","k":"רבנו ברוך מארץ יון","b":"נמנה על חכמי דרום איטליה המכונה איטליה של יון, מפרש התלמוד בשנים תתמ (1080) - תתק (1140), עלה לארץ ולבסוף התיישב בחאלב."},{"i":9587,"n":"ברוך מטבריה","f":"מנחם מתתיהו","b":"ממונה \"כולל ווהלין\"-תרטו. חתם על הסכמה לר אברהם מסלונים להיות הממונה על איסוף הכספים לכולל."},{"i":9588,"n":"ברוך מטשעכוב","b":"תלמיד החוזה מלובלין. רב בטשעכוב-ליד לובלין."},{"i":9589,"n":"ברוך מיוון ואיטליה","f":"שמואל","k":"ר' ברוך מארץ יון","bt":"ד'תתמ","dt":"ד'תתק","b":"מגדולי הפוסקים הראשונים בדרום איטליה, עלה לא\"י ד'תת\"פ. עבר לארם צובא. שלח שאלות בהלכה לר' שמואל בן עלי ראש ישיבת בגדד, חיבר פירוש לש\"ס ונשאר ממנו פירוש למסכת הוריות."},{"i":9590,"n":"ברוך מירושלים","b":"רב בירושלים-שנת נ'"},{"i":9591,"n":"ברוך מירושלים ומצרים","f":"בנימין ישראל","dp":"מצרים","b":"מחכמי ירושלים, חתם-תיז על אגרת ר ברוך גד בענין עשרת השבטים. עבר למצרים. ר משה בן חביב בספרו \"שמות הגיטין\" מסיק לכתוב בנימן ללא יו\"ד, מתוך זה שר בנימין ור ישראל בנו חתמו שמם ללא יו\"ד. חתם-תו על תקנת שחרור תלמידי חכמים ממסים, תשובותיו נמצאות בספר \"משפטי צדק\", וכן בשו\"ת \"באר מים חיים\" לר שמואל ויטל."},{"i":9592,"n":"ברוך מלבוב","f":"ישראל","dt":"תס - א תשרי","dp":"לבוב","b":"דרשן, מרביץ תורה, רב בלבוב."},{"i":9593,"n":"ברוך מלבוב","f":"מרדכי","dt":"תכד - ח אייר","dp":"לבוב","b":"מחכמי לבוב. נהרג עק\"ה."},{"i":9594,"n":"ברוך מלבוב","f":"מנחם מנדל","b":"אולי הוא שהיה חתן ר חיים רפפורט. מראשי קהלת לבוב, חתם-תקד על תקנת הקהל, הסכים על \"שערי בנימין\" לר בנימין אשכנזי."},{"i":9595,"n":"ברוך מלובלין","f":"ישראל משה יוסף","dt":"תד - כב סיון","dp":"לובלין","b":"מחכמי לובלין."},{"i":9596,"n":"ברוך מלובלין","f":"משה קאפילש","dt":"תנג - ב תמוז","dp":"לובלין","b":"\"נאמן\" קהילת לובלין."},{"i":9597,"n":"ברוך מלובלין","f":"משה יצחק","dt":"תקלא - כו כסלו","dp":"לובלין","b":"מחכמי לובלין."},{"i":9598,"n":"ברוך מליסא","b":"מחכמי ליסא-תק\"פ"},{"i":9599,"n":"ברוך מליפאנטו","f":"משה","b":"רב בליפאנטו-שנות ה-ש'."},{"i":9600,"n":"ברוך ממגנצא","b":"חיבר חדושים על מסכת יו\"ט - בזל."},{"i":9601,"n":"ברוך ממגנצא - א","f":"שמואל","k":"בעל ספר החכמה","bt":"ד'תת","dt":"ד'תתפא","b":"תלמיד ר יהודה בן קלונימוס משפירא. מגדולי הפוסקים הראשונים, דיין במגנצא. בנו - ר שמואל מבונבורק."},{"i":9602,"n":"ברוך ממגנצא - ב","f":"שמואל","dt":"ד'תתקפא","b":"פוסק, פייטן, במגנצא-ד'תתק\"פ וחתם על תקנות עם בעל הרוקח ועם ר דוד בן קלונימוס. קרובו של הראבי\"ה. חיבר זמירות לשבת ובהם \"ברוך אל עליון\"."},{"i":9603,"n":"ברוך ממז'בוז'","f":"יחיאל - חתן הבעשט","k":"ר' ברוך ממזיבוז","r":"נכד הבעש\"ט","bt":"תקיג-ז","dt":"תקעב - יח כסלו","b":"נכד הבעשט. חתן ר טוביה קצקש מאוסטרהא, ובזיוו\"ש חתן ר אהרן מטיטיוב. אדמור בטולטשין-תקמב, מז'בוז'-תקס. מתורתו ב\"בוצינא דנהורא\", \"אמרות טהורות\". תולדותיו ב\"מקור ברוך\". חתניו ר יעקב פנחס אוירבוך, ר דובער מטולשטין בן ר שלמה מקרלין, ר יצחק דרוהוביטשר בן ר יוסף מימפולא האדמור מזלוטשוב."},{"i":9604,"n":"ברוך ממינסק","f":"צבי","b":"דיין במינסק-תר בערך."},{"i":9605,"n":"ברוך מסאוורן","f":"משה צבי מסוורן","b":"רב-שנת תר\"כ"},{"i":9606,"n":"ברוך מסוכטושב","k":"בעל זרע ברוך","dt":"תקעד - י אדר","b":"רב בסוכטשוב,וישיגרד"},{"i":9607,"n":"ברוך מסופיה","f":"שמעון","b":"מחכמי קהלת האשכנזים בסופיה-שנות ה-ש'?"},{"i":9608,"n":"ברוך מספרד ומרוקו","b":"מגולי ספרד, מחכמי מרוקו. נזכר אצל ר שמואל בן סעדיה ן דנאן יחד עם חבריו: ר ישעיה בקיש, ר עמרם השוחמי, ר עמרם בן ראש."},{"i":9609,"n":"ברוך מפאס","f":"חיים","b":"רב בפאס-שנות ה-ש-ת, חברו של ר שמואל בן סעדיה דנון שהזכירו בספרו."},{"i":9610,"n":"ברוך מפדובה","f":"אשר","b":"רב בפדובה."},{"i":9611,"n":"ברוך מפולוניא","k":"בעל אגודת אזוב","b":"רב-שנת שע\"ה"},{"i":9612,"n":"ברוך מצאוויע","b":"מקובל, מתלמידי ר מנחם מנדל מקוצק."},{"i":9613,"n":"ברוך מציזאווי","k":"אדמור מציזאווי","dt":"תרלז - כב חשון","b":"י\"א תאריך פטירתו - א אב."},{"i":9614,"n":"ברוך מצפת","f":"שמואל","bp":"פינסק","dt":"תקצג","dp":"צנעא","b":"מתלמידי הגרא, עלה לצפת בתקעט. ר יעקב ספיר מתארו כאיש בעל תורה וגבור חיל בעל ידע ברפואה. בשנת תקצא יצא לבקש את עשרת השבטים במדבריות ערב בשליחות קהילת האשכנזים ובידיו אגרת שנכתבה על ידי ר ישראל משקלוב, האגרת נחתמה גם על ידי ר אברהם דב מאבריטש מנהיג קהילת החסידים. ר ברוך הגיע לצנעא בשנת תקצג, ומשם יצא אל המדבר בלווית הדיין מארי יחיא אל אביאץ והגיעו עד חיידאן שם מצאו רועה יהודי והפקידו בידיו את האגרת, הם חזרו לצנעא ושם ריפא את האימם, שמינהו לרופא החצר, המוסלמים העלילו עליו והאימם הרגו. אחר מותו באו יהודים מחיידאן לצנעא וספרו שבאו רוכבים ערבים לחיידאן ושאלו על היהודי מירושלים."},{"i":9615,"n":"ברוך מצרפת או אשכנז","f":"אליעזר","b":"מגדולי הראשונים מפרשי התורה באשכנז-ד'תת\"ס"},{"i":9616,"n":"ברוך מקאוולי ורדזינוב","k":"בעל מקור ברוך","dt":"תקנא - ט חשון","b":"רב ברדזינוב,פלונסק,גנזין"},{"i":9617,"n":"ברוך מקאליב","b":"י\"א שהיה חתן ר שמואל שמלקא מניקלשבורג, ורבו של ר יצחק איזיק מקאליב."},{"i":9618,"n":"ברוך מקוסוב","f":"אברהם","k":"בעל יסוד האמונה","bt":"תפ","dt":"תקמב - יג חשון","b":"תלמיד ר מנחם מנדל מפרמישלן, ויתכן שפגש גם את הבעשט. מגיד מישרים ברדיטשוב, קוסוב, ולחם בשרידי השבתאות והפרנקיסטים אחרי שהרב הראשון ר ירחמיאל נתפס לאפיקורסות. חיבר \"נחמד ונעים יסוד האמונה\" ו\"עמוד העבודה\" טשרנוביץ תריד. בניו ר יוסף מבוטושאן, ור אברהם. חתנו ר אברהם כץ-(נפטר ג תשרי תקעב). מחדושיו ב\"פקודת המלך\"."},{"i":9619,"n":"ברוך מקמניץ","b":"רב בקמניץ-תקל\"א"},{"i":9620,"n":"ברוך מקמניקא","b":"תלמיד הבעשט אשר ביקרו בביתו."},{"i":9621,"n":"ברוך מרגנשבורג","bt":"ד'תתע","b":"מגדולי חכמי אשכנז,מבעלי התוספות,דיין ברגנסבורג"},{"i":9622,"n":"ברוך מרדכי ממינסק","b":"ר\"מ במינסק-תר\"צ"},{"i":9623,"n":"ברוך מרדכי מקלינורדין","dt":"תרטו","b":"רב בקליינוורדיין"},{"i":9624,"n":"ברוך מרויסטשיק ופוהרליץ","b":"רב בפוהרליץ-תקמו ור צבי הירש בן ר שלמה זלמן מפרישטיק על מקומו אחריו. בנו - ר ליב מסאבאטיש."},{"i":9625,"n":"ברוך משאריגרד","b":"דיין בשאריגרד-תק\"ל"},{"i":9626,"n":"ברוך משלוניקי","f":"אליקים","b":"רב בשלוניקי-שפ. נזכר בשו\"ת המבי\"ט."},{"i":9627,"n":"ברוך משלוניקי","b":"דיין בשלוניקי-שמה, וחתם אז בשות מהרש\"ך. בנו ר שמואל שהיה רב מחוץ לשלוניקי והשיב לחכמי שלוניקי-שע."},{"i":9628,"n":"ברוך משלוניקי","b":"מראשי קהלת ליסבון בשלוניקי-ש' היה מעורב במחלוקת שגרמה לפילוג בקהלה ולצדו עמדו ר שלמה חסון וחבריו וכנגדו ר יוסף ן לב, והיה במחלוקת על כך עם ר משה המון מקושטא."},{"i":9629,"n":"ברוך ן, ברוך מקושטא ונציה","f":"שמואל או משה","k":"בעל אלה תולדות אדם","dt":"שפט - יז תמוז","dp":"שלוניקי","b":"רב בשלוניקי-שמה, קושטא-שן, מחבר, פילוסוף, עבר לאיטליה והתישב בונציה בזמן בעל \"מדבר יהודה\". חיבר \"אלה תולדות אדם\", \"קהילת יעקב\" ונציה שנט. מגיה ומו\"ל בונציה, וכן תפילות ופיוטים כגון \"וידוי קרוב למלקות\". אחיו - ר משה ן ברוך."},{"i":9630,"n":"ברוך ן, דוד הכהן ממרוקו","dt":"תקכא - ג טבת","dp":"באהמ'ו - נוף כוס","b":"מלוב\"ן במרוקו"},{"i":9631,"n":"ברוך ן, משה משלוניקי","f":"אברהם","dt":"תכא","dp":"שלוניקי","b":"רב בשלוניקי."},{"i":9632,"n":"ברוך ן, משה משלוניקי - א","b":"מחכמי שלוניקי, נזכר אצל ר שמואל ן חיון-שסו, חתם על הסכמה-שפג בענין מינוי פרנסים."},{"i":9633,"n":"ברוך ן, רפאל משלוניקי","dt":"שצח - יג כסלו","dp":"שלוניקי","b":"גביר מחכמי שלוניקי, עסקן צבור."},{"i":9634,"n":"ברוך ן, שמואל משה משלוניקי","f":"משה","bp":"שלוניקי","dt":"ת","dp":"סרייבו","b":"תלמיד ר שמואל חיון, רב בויריאה-שפב, רב בסרייבו-שץ אצל ראש הרבנים ר מצליח מוג'אג'ון. חתם ב\"עיגונא דאתתא\"-שצד."},{"i":9635,"n":"ברוך ן, שמואל משלוניקי","b":"מגדולי חכמי שאלוניקי-ש\"פ"},{"i":9636,"n":"ברוך עוזיאל חזק","b":"נשא ונתן עם מהר\"ם פדובה."},{"i":9637,"n":"ברוך עוזיאל משלוניקי","dt":"שמב - בערך","b":"ממגורשי ספרד?, רב בשלוניקי. נפטר בגיל מבוגר."},{"i":9638,"n":"ברוך עוזר מאה\"ו","f":"מאיר בן ליב בן ברוך","k":"בעל אלה דברי הברית","bt":"תקג","bp":"פרג","dt":"תקפג - ג כסלו","b":"דיין בהמבורג-תקמג, וראב\"ד-תקפג על מקום ר אלעזר לאזי ברלין, נאבק בריפורמים, והוציא פסק דין כנגדם עם הסכמות מרבים מחכמי הדור. בניו: ר יעקב, אורי פיבש, מאיר יוקב."},{"i":9639,"n":"ברוך פאסקובער","b":"נפצע בפרעות תח בזאמוט, עבר לקאלואריא ושם פגש את ארוסתו (ועל כך סיפור מצורף), התישב בגורזד."},{"i":9640,"n":"ברוך ציון משלוניקי","b":"חזן להלויות מתים בשלוניקי. נספה בשואה."},{"i":9641,"n":"ברוך שאמר, יצחק","b":"גדול בדורו-שנת ש'"},{"i":9642,"n":"ברוך שאמר, שמעון מפרג וירושלים","f":"אלעזר","k":"בעל ברוך שאמר","bt":"ק","bp":"אשכנז","b":"מחכמי פרג וסופר סתם ידוע, הגיה והוציא לאור \"ברוך שאמר\" לר אברהם זינצהיים, דובנא תקנו. חידש את הישוב היהודי בחברון."},{"i":9643,"n":"ברוך שמואל","f":"מאיר פייבל","b":"רב בקריניצא"},{"i":9644,"n":"ברוך שמחה משלוניקי","dt":"תמב","dp":"שלוניקי","b":"רב בק\"ק אשכנז בשלוניקי. נפטר במגפה-תמב."},{"i":9645,"n":"ברוך שמעון משקלוב","f":"ברוך סטופלר","bt":"פאלוצק?","b":"חתן ר גרשון חיט פלטישר. מגיד מישרים בשקלוב. אחיו - ר מנחם מנדל ממינסק בעל זכרון מנחם."},{"i":9646,"n":"ברוך ש\"ץ מפיורדא","f":"אלקנה","k":"בעל עטור בכורים","b":"חיבר \"עטור בכורים\" פיורדא תקיב."},{"i":9647,"n":"ברוך שקלאבער","f":"יעקב משקלוב בן יהודה","k":"הו\"ל אוקלידס","b":"דיין בשקלוב. בקי בכל המדעים וגם רופא. תרגם והו\"ל ספר אוקלידס בהוראת הגר\"א, והו\"ל \"יסוד עולם\" לר יצחק הישראלי עם הגהות ממנו. לעת זקנתו עבר למינסק, ולסלוצק ושימש כרופא לנסיך ראדזיויל. בנו ר אהרן."},{"i":9648,"n":"ברוך, ידידיה מירושלים","f":"שמואל","bt":"תרמה","bp":"ירושלים","b":"עסקן צבור בועד העדה הספרדית בירושלים."},{"i":9649,"n":"ברוך, יהודה מטימישואר","f":"אברהם","dt":"תקצא - טו שבט","b":"רב בקהלה הספרדית בטימישואר - תחילת המאה ה-19."},{"i":9650,"n":"ברוך, יהושע בועז","k":"בעל שלטי גבורים","b":"בקי,מגדולי חכמי ספרד בתקופת הגירוש-רנ\"ב,בא לאיטליה. חיבר עין משפט נר מצוה."},{"i":9651,"n":"ברוך, יוסף מרקו","bt":"תרלב","bp":"קושטא","dt":"תרנט - כא אלול","dp":"פירנצה","b":"למד בקושטא לתואר ד\"ר, עבר לבולגריה. מראשוני התנועה הציונית המדינית בזמנם של ר יהודה שלמה חי אלקלעי ור ברוך בן יצחק מטרני. עורך כתב העת \"כרמל\" בצרפתית בהנהלת נסים בן יהודה."},{"i":9652,"n":"ברוך, יעקב מקושטא וירושלים","f":"יצחק","k":"בעל המדבר","bt":"תרנ","bp":"ירושלים","dt":"תשטז","b":"חתן ר בכור אהרן אלנקוה. מורה בקושטא, רב בטוקאט-אנטוליה, דיין בקושטא, מזכיר ביה\"ד לעדת הספרדים בירושלים-תרפד. חיבר ספרי לימוד."},{"i":9653,"n":"ברוך, יצחק מירושלים","dt":"תרצב - כד אד\"ב","dp":"ירושלים","b":"מחכמי ישיבת הגביר טראנטו."},{"i":9654,"n":"ברוך, משה מבודפשט","k":"בעל שערי תורת התקנות","b":"ראש ביהמ\"ד לרבנים בבודפשט-עד 1907. חוקר המשפט התלמודי."},{"i":9655,"n":"ברוך, משה מבוכרה","f":"נתנאל","k":"בעל תיבת משה","bt":"תקצא","bp":"בוכרה","dt":"תרנט - יא טבת","dp":"ירושלים","b":"מחכמי בוכרה, עלה לירושלים - תרנא או תרנו. חיבר \"תיבת משה\"."},{"i":9656,"n":"ברוך, משה משלוניקי","f":"שמואל ן ברוך","dt":"ת - ו אב","dp":"שלוניקי","b":"תלמיד ר דניאל אישטרושא. דיין בשלוניקי."},{"i":9657,"n":"ברוך, נסים מירושלים","f":"משה","bt":"תרלו","bp":"אדרינופול","b":"מחכמי אדרינופול, מוסיקאי, עבר לקושטא, ש\"ץ בסופיה. דיין אצל ר דוד פיפאנו ונזכר בספרו \"אבני האפוד\". הו\"ל קובץ תפלות ופיוטים לימים נוראים."},{"i":9658,"n":"ברוך, נפתלי מירושלים","f":"שמואל","bt":"תרלב","bp":"ירושלים","b":"תלמיד ישיבת \"דורש ציון\" בירושלים. מחכמי ירושלים. גבאי ח\"ק, ישיבת \"בית אל\", ועוד."},{"i":9659,"n":"ברוך, נתן מירושלים","f":"שמואל","bt":"תרמב","bp":"ירושלים","b":"מחכמי ירושלים, עבר לצרפת, מצרים, ארגנטינה, פרו, סין, ארה\"ב, חזר לירושלים והיה בועד העדה הספרדית."},{"i":9660,"n":"ברוך, נתנאל","b":"מגדולי חסידי בוכארה-ת\"ר"},{"i":9661,"n":"ברוך, ראובן מטימישואר ווינה","f":"יהודה מטימישואר","bt":"תקעא","bp":"טימישואר","dt":"תרלה - אייר","dp":"וינה","b":"אביו היה רב הקהלה הספרדית בטימשואר-טרנסילבניה. למד אצל חכמי הספרדים בליוורנו, קושטא ואזמיר. רב הקהלה הספרדית בוינה-תר, ודיין שם אצל ר אלעזר הורביץ. השתתף בספר \"נחלה לישראל\" לר משה ישראל חזן מרומא. הו\"ל \"שיירי ברכה\" לחיד\"א והוסיף לו הקדמה."},{"i":9662,"n":"ברוכוביץ, חיים יהודה מפינשטוב","b":"\"כרם בית שמואל\" - פיעטרקוב תרצא, \"כרמנו\" - אלכסנדר-לודז תרצג."},{"i":9663,"n":"ברוכוביץ, עקיבא מקראסנאפאל","f":"יצחק אליהו","k":"בעל עקב רב","bt":"תרכו-ח","bp":"סקידל-פלך גרודנא","b":"מצאצאי בעל הש\"ך. תלמיד ביהמ\"ד חברת ש\"ס בגרודנא. רב בקרסנופול(=קראסנאפאל)-פלך סובאלק-תרנו."},{"i":9664,"n":"ברוכי, יהושע מסנוק","f":"ישראל ברוך","bt":"תרע","bp":"סנוק","b":"עלה לארץ-תרצב והצטרף לקיבוץ הדתי. עבר לירושלים ועסק בפעילות צבורית."},{"i":9665,"n":"ברוכי, ישראל ברוך טרטנר מסנוק","b":"עסקן בסנוק. חסיד רוזין. ניצל מהשואה. עלה לארץ-תשה."},{"i":9666,"n":"ברוכיאל","f":"אבא מארי","k":"בעל יסוד האמונה","bt":"רמה - יא חשון","b":"מקובל מחכמי איטליה-ר, חיבר \"יסוד האמונה\""},{"i":9667,"n":"ברוכיאל, יצחק מסרייבו","b":"גביר מראשי קהלת סרייבו-שנות ה-ת'."},{"i":9668,"n":"ברוכיל, דוד מאלגיר","bt":"תקץ - בערך","dt":"תרס","b":"שו\"ב ורב בסעידא-אלגיר. נזכר אצל ר אפרים אנקאווא, \"שמו יוסף\", דרשה ממנו ב\"מלל לאברהם\"."},{"i":9669,"n":"ברוכים, אברהם הלוי מצפת וירו","f":"אליעזר?","k":"בעל תקוני שבת","b":"מתלמידי האר\"י מכת הרביעית, חסיד ובעל סיגופים בעיר צפת, מקובל בירושלים-שן. לדעת בעל אור החיים ותג\"י זהה עם ר אברהם בן אליעזר הלוי. חיבר הקונטרס \"תקוני שבת\" המצורף לספר קיצור ראשית חכמה לר יעקב פויטו וינציה שס"},{"i":9670,"n":"ברוכים, אברהם השני מירושלים","b":"נמנה על חכמי ישיבת גדולת מרדכי שיסד ר מרדכי טאליק(=טאלוק) עם ר זרחיה אזולאי. שדר חברון החל בשנת תמט בצפון אפריקה, ונתבקש לחקור אודות טביעתו של השדר ר אברהם חברון בים. אחר כך היה באיטליה. תשובה ממנו מהעיר קזאל דמונפירטו ב\"פחד יצחק\" אות ק. אולי הוא נכדו של בעל תוספות יו\"ט, שהיה שדר וחתם על גביית עדות בעיר מכנאס בשנת תפד, חדושי תורה ממנו בספר לקוטי שושנים לר יעקב טולידנו."},{"i":9671,"n":"ברוכים, אברהם מצפת","dt":"רס ?","b":"מקובל בצפת"},{"i":9672,"n":"ברוכים, יעקב הלוי","bp":"צפת","dt":"תעה-ו","b":"מחכמי צפת, תלמיד ר משה גלנטי ועבר עמו לירושלים. מצאצאי ר אברהם ברוכים מתלמידי הארי. בשנת תמב בשליחות חברון באלגיר, בשנת תן נפגש עם ר שמואל צרפתי בפאס, ובחזרתו דרך איטליה היה במודנא אצל ר אברהם רוויגו. בשנת תס חתם על תעודה בדבר חלוקת כספים. בשנת תעה בהיותו חזרה משליחות בדרך ממצרים לישראל נרג על ידי שודדים ומקום קבורתו לא נודע."},{"i":9673,"n":"ברוכמן, יצחק"},{"i":9674,"n":"ברוכסון, יצחק מסלובודקא","b":"תלמיד בכולל סלובודקה. פרסם מאמרים ב\"בית ישראל\" - קובנא תרפב, \"כנסת ישראל\" - נ\"י תרצב - כתב עת הסתדרות תלמידי סלובודקה באמריקה."},{"i":9675,"n":"ברוכסון, פנחס מבאלטא","f":"פסח","bt":"תרכט","b":"רב בבאלטא-תרנד על מקום אביו."},{"i":9676,"n":"ברוכסון, פסח מבאלטא","b":"רב בבאלטא-תרל, ובנו ר פנחס על מקומו אחריו."},{"i":9677,"n":"ברול, יוסף לואי מליטא וניו יור","bt":"1894","bp":"וילנא","b":"רב רפורמי. היגר לניו יורק ולמד בישיבה קולג' והיברו יוניון קולג'. רב בביהכ\"נ \"עמנואל\" בדוונפורט. מיסד הקהלה הרפורמית \"יהודה\"-1923, רב במילווקי-1924, פרופס' בביהמ\"ד למורים במילווקי, חבר ב\"היברו יוניון קולג'\"-סינסינטי. חיבר ספרים באנגלית, וחלק ראשון של אנתולוגיה מדבריהם של לא יהודים על היהדות והיהודים."},{"i":9678,"n":"ברום די, חיים משלוניקי","b":"מחכמי שלוניקי-רץ."},{"i":9679,"n":"ברום-בראם, שמואל מלוצרן","b":"רב בלוצרן בדור שלפני השואה."},{"i":9680,"n":"ברומא, אברהם","b":"מגדולי רבני מצרים-ת\"מ"},{"i":9681,"n":"ברומברג, אברהם יצחק מגרודזאנדז","f":"נתן","k":"בעל חומת ירושלים","b":"אב\"ד גרודזאנדז, רב בצבא הפולני בזמן מלחמת העולם, עלה לירושלים. חיבר גם \"מקורות לפסקי הרמב\"ם\"."},{"i":9682,"n":"ברומברג, אברהם ירחמיאל מלענטשא","f":"ישראל יחיאל מיכל","k":"בעל ברית אברהם","bt":"תרלז","b":"רב בפרלוב(=פערליא)-תרסא, לענטשנא-פלך לובלין-תרסו. נסמך מאת: ר משה נחום ירושלמסקי מקיעלץ, הגאון מאסטראוויצי. חיבר גם \"מרגליות אברהם\", \"עמק אברהם\", ועוד. פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח, \"הבאר\" - זאמושץ-וארשא - תרפד, \"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז, \"קובץ דרושים\" - פיעטרקוב תרפג."},{"i":9683,"n":"ברומברג, דוד יצחק חריף מאויאז","f":"ראובן מפיעטרקוב","k":"בעל בית דוד","dt":"תקפז - כח שבט","b":"רב בטשנסטחוב,ראב\"ד בפיוטרקוב. חתן המאור ושמש"},{"i":9684,"n":"ברומברג, יונה","b":"פרסם מאמרים ב\"היכל התורה\" - מיר-נוברדוק תרצה."},{"i":9685,"n":"ברומברג, יעקב מפיעטרקוב","f":"דוד יצחק ברומברג","b":"ראב\"ד בפיעטרקוב-ת\"ר"},{"i":9686,"n":"ברומברג, יצחק","dt":"תש","b":"מרבני פולין"},{"i":9687,"n":"ברומברג, נחום מסיווען","f":"אברהם משה","b":"רבה הראשון של סיווען-מודלביה - תרם."},{"i":9688,"n":"ברומר, אלעזר","f":"משה","k":"בעל משפט כתוב","bt":"תרלו","bp":"סנוק","dt":"תשד","dp":"קירגיזיה","b":"חסיד בלז. חתן ר יהודה כץ ראב\"ד סנוק, רב בסנוק-תרפז על מקום חותנו. חיבר \"משפט כתוב\" בילגורי תרצח."},{"i":9689,"n":"ברומר, יהודה יחיאל מסנוק","f":"אלעזר","b":"תלמיד יח\"ל. ניצל מהשואה - גלה לסיביר, ואחריה רב בביאלא-ביליץ. רב בפריז, עבר לארה\"ב-תשיג. עסק בכתבי יד."},{"i":9690,"n":"ברומר, יחיאל מאיר מיכל ממילניצ","f":"משה","bt":"תקפג","bp":"בוזנוב","dt":"תרסז","b":"רב במילניצה-תריא, בוצאץ. חתן ר נתן אשכנזי מדוקלא. חתנו ר משה רוזנפלד על מקומו במילניצה."},{"i":9691,"n":"ברומר, משה מבוזנוב","f":"יחיאל מאיר מיכל","k":"בעל זכרון משה","bt":"תקם","dt":"תרה","b":"רב בבוזנוב-תקפא. חיבר \"זכרון משה\" הוסיאטין תרסו."},{"i":9692,"n":"ברונא, מנשה","f":"ישראל ברונא","b":"מגדולי חכמי פרג-ר\"ס"},{"i":9693,"n":"ברונגר, אברהם משטמפן","b":"מחכמי שטמפן, חתם-תריב על מינוי ר אליעזר וינטר לרב בשטמפן."},{"i":9694,"n":"ברונדון, ראובן ממונשטיר","b":"רב במונשטיר-שץ."},{"i":9695,"n":"ברונהוט, משה מברוד","b":"מחכמי ברודי - תשובה אליו \"שערי דעה\"."},{"i":9696,"n":"ברונהים, יעקב מקראקא","b":"תשובה אליו - \"מנחת יחיאל\"."},{"i":9697,"n":"ברונן, איצק משטמפן","b":"מחכמי שטמפן, חתם-תקסט עם ראשי הקהלה."},{"i":9698,"n":"ברוננגרבר, פסח","bt":"תקם","bp":"רידיק","dt":"תרם - בערך","b":"רב ברידיק, ראש משפחת שוחטים ומוהלים שם."},{"i":9699,"n":"ברונפלד, שבתי","dt":"תרעח - ד טבת","b":"רב בערדאטעלעק"},{"i":9700,"n":"ברונר, אהרן משטמפן","b":"מחכמי שטמפן, חתם-תריב על מינוי ר אליעזר וינטר לרב בשטמפן."},{"i":9701,"n":"ברונר, דוד משטמפן","b":"מחכמי שטמפן, חתם-תריב על מינוי ר אליעזר וינטר לרב בשטמפן."},{"i":9702,"n":"ברונר, יחזקאל מבנדין","b":"תשובה אליו ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט - מאת ר נחום וידנפלד מדומברובא."},{"i":9703,"n":"ברונר, שמואל מקראקא","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":9704,"n":"ברונשוויג, משה","b":"גדול השוחטים בקרקא-ש\"ד,מחבר ספר על השחיטה"},{"i":9705,"n":"ברונשווייג, יהודה ליב מברלין","b":"מראשי הקהילה בברלין, חתם על כתב הרבנות של ר צבי הירש מלונדון וברלין-תקלב."},{"i":9706,"n":"ברוסא ממצרים","f":"אשר","b":"מחכמי מצרים בזמן הרדב\"ז."},{"i":9707,"n":"ברופמן, משה דב מקראקא","k":"בעל אבן משה","b":"מחכמי קראקא. חיבר \"אבן משה\" - בכת\"י. הו\"ל ירחון \"שערי תורה\" - קראקא תרפה, \"חדרי תורה\" - קראקא תרפו. עורך \"שערי תורה\" - קראקא תרפה."},{"i":9708,"n":"ברוצקוס, דב בר (בוריס)","f":"דוד","k":"בעל כלכלה חקלאית","bt":"1874","bp":"פולנגן","dt":"1938","dp":"ירושלים","b":"עסקן צבורי וכלכלן. אחיו של יהודה יוליוס. ריכז את ההדרכה החקלאית במושבות היהודיות מטעם יק\"א, עיבר את החומר של מפקד 1897 על האוכלוסיה היהודית ופרסם את מסקנותיו ב-2 כרכים. חיבר \"דרכי המושבות היהודיות\" ובהם ביקר את שיטת ההתישבות של הברון רוטשילד בארץ. פרסם בכתבי עת רבים באידיש ורוסית."},{"i":9709,"n":"ברוצקוס, יהודה יוליוס","f":"דוד","bt":"1870","bp":"פולנגן","dt":"1951","dp":"תל אביב","b":"רופא, הסטוריון, ועסקן ציוני. פרסם מורה דרך ביבליוגרפי לספרות על היהודים, עורך \"ווסחוד\" ועוד. ציר באספה הכל רוסית מ טעם יהודי פלך מינסק-1917, ציר בסיים הליטאי ומיניסטר לעניני היהודים בליטא-1922, מראשי התנועה הרביזיוניסטית, הגיע לאמריה, ועמד בראש התאחדות ציוני רוסיה, עלה לארץ. חוקר תולדות היהודים במזרח אירופה ומלכות הכוזרים בדרום רוסיה."},{"i":9710,"n":"ברוצקוס, יואל","f":"דב","bt":"1885","bp":"פולנגן","dt":"1951","dp":"סיביר","b":"מחנך ומתמטיקאי. מנהל הגימנסיה העברית בקובנא-1928. הוגלה לסיביר-1940 ונפטר שם."},{"i":9711,"n":"ברוק, אברהם יעקב","dt":"תרעד","b":"מו\"צ בסלונים"},{"i":9712,"n":"ברוק, אליעזר בן ציון מירושלים","f":"בנימין","k":"הו\"ל מדרגת האדם","bt":"תרסד","bp":"רוגצ'וב","b":"תלמיד ישיבות לובביץ, נוברדוק. ממיסדי ומנהלי ישיבות \"בית יוסף\" בלוצק וגריובה. עלה לארץ-תרצד וכיהן כמשגיח בישיבת \"בית יוסף\" בתל אביב, ר\"מ ומנהל ישיבת \"בית יוסף\" בירושלים-תרצח, ממיסדי הכולל \"עץ יוסף\" בירושלים. פרסם מאמרים ב\"תבונה\" - ירושלים תשא."},{"i":9713,"n":"ברוק, בן ציון מירושלים","b":"תלמיד ר יוסף יוזל הורביץ מנוברדוק. ממיסדי \"בית יוסף\" נוברדוק בירושלים-תרצז עם ר זאב חפץ."},{"i":9714,"n":"ברוק, בנימין מבאר יעקב","f":"יהודה ליב","bt":"תרך","bp":"סלאויטה","b":"עלה לארץ-תרעד והתישב בבאר יעקב. בנו - ר אליעזר בן ציון."},{"i":9715,"n":"ברוק, דוד מברלין","b":"מראשי הקהילה בברלין-תקד, חתם על כתב ההסכם עם ר דוד פרנקל הראב\"ד בברלין."},{"i":9716,"n":"ברוק, יואל פיבש מקלימטוב","f":"יהודה","dt":"כח שבט","dp":"קראקא","b":"אב\"ד קלימטוב."},{"i":9717,"n":"ברוק, יחיאל מיכל נפתלי מקדלבור","b":"אב\"ד קדלבורג. חתנו - ר יוסף נובל מהלברשטט."},{"i":9718,"n":"ברוקאזש, משה הכהן מפיעטריקוב","f":"צבי","bt":"תקן","dt":"תרמא - טו אדר","b":"עבד כרצף בפיעטריקוב, ר ישראל המגיד מקוזניץ קרבו ועשאו למשרתו, לאחר מכן נדד ברחבי פולין והתפרסם בפיעטרקוב כבעל מופת, ונסעו אליו חסידים רבים. היה מחלוקת כנגדו מצד אדמורים אולם הם לא הרשו לפגוע בו. בזקנותו נעזב ע\"י חסידיו ונפטר תוך עוני."},{"i":9719,"n":"ברוקאש, אברהם מליפאנטו","f":"חייא","b":"רב בליפאנטו-ש'. תשובה אליו ב\"דברי ריבות\"-שכ. אחיו של ר יוסף."},{"i":9720,"n":"ברוקאש, חייא מפטרץ","b":"מחכמי טורקיה, רב בפטרס(=פטרץ) בזמן מהרשד\"ם, והיה מחותמי ההסכמה על איחוד הקהלות. בניו ר אברהם, ר יוסף."},{"i":9721,"n":"ברוקמן, יעקב יוסף מטולשטש","dt":"תשב","b":"רב בטולשטש-תרע\"ב"},{"i":9722,"n":"ברוקנטל, הלל","bt":"תרסט","bp":"גליציה","dt":"תשמא","dp":"רחובות","b":"תלמיד מהר\"ם שפירא בסנוק. למד בישיבת ר יוסף ברויאר בפפדם. ר\"מ בישיבה בפיומי-איטליה, כשנסגרה עלה לארץ-תרצה. הצטרף לקיבוץ הנוער האגודתי. בשליחות-תרצז בהולנד. נלקח בשבי ע\"י הנאצים, ושוחרר בחלופי שבויים-תשג, הצטרף לקבוץ חפץ חיים והיה שם רב ומנהל ביה\"ס."},{"i":9723,"n":"ברוקנשטין, ישראל נתן מסקלט","f":"מרדכי","dt":"תשטו","b":"שו\"ב ביאנוב-תרסט. עבר ללמברג והיה תעשיין. עלה לארץ-תרפו ובנה ביח\"ר למרגרינה. ממקורבי האדמור מהוסיאטין והשתדל בהצלתו. נדיב לפרט ולכלל. הו\"ל פירוש רד\"ק לתהלים."},{"i":9724,"n":"ברוקש, חייא","b":"מגדולי חכמי ספרד בגירוש,בא לפטרוס(יון)-רנ\"ב"},{"i":9725,"n":"ברוקשטין, חיים יוסף מפיסטין","f":"יהושע יצחק","k":"בעל תוספות חיים","r":"אב\"ד פיטסין","bt":"תקלה","bp":"באהוסלב","dt":"תרכה - כד חשון","b":"חתן ר אליעזר חיות בן ה\"זרע יצחק\". גדל אצל הסבא משפולה. תלמיד ר אהרן מטיטיוב, ר לוי יצחק מברדיטשוב, בעל התניא, ר מנחם מנדל מקוסוב ובנו ר חיים. רב בפיסטין(=פוסטין), קליינוורדין. חיבר \"תוספות חיים\" טשרנוביץ תרכא, ועוד. בניו ר ישראל נתן אלתר, ר פנחס. חתנו ר חיים יוסף גוטליב מסטרופקוב","bk":[["תוספת חיים",""]]},{"i":9726,"n":"ברוקשטין, ישראל נתן אלתר מפיסט","f":"חיים יוסף מפיסטין","k":"בעל מנחת ישראל","bt":"תקצז","dt":"תרכח","b":"אב\"ד פיסטין על מקום אביו. חתן ר אליעזר ליפא ד(ק)אוולער אב\"ד סקלט. חיבר \"אגרת קץ חי\" טשרנוביץ תרכד. בנו ר משה במרמורוש שביתו שימש אכסניה לאדמורים כיובל שנים - עד פטירתו-תרץ."},{"i":9727,"n":"ברור יהודה נח בן אברהם אלכסנדר","bt":"1860","dt":"ה'תרצט 1939","bk":[["אבני הלבנון",""],["ילקוט פרי עץ הדר",""],["שער דלתי הלבנון",""]]},{"i":9728,"n":"ברור, חיים","b":"תלמיד המבי\"ט"},{"i":9729,"n":"ברור, משה מדמשק","b":"רב קהלת הספרדים בדמשק על מקום ר משה ברוך - שנות ה-ש', עבר לטריפולי-לבנון."},{"i":9730,"n":"ברושטין, ח' ד' מריגא","b":"פרסם מאמרים ב\"פלפול החברים - ריגא תרפד - מאסף תלמידי ישיבת ריגא."},{"i":9731,"n":"ברושיליש, משה מספרד","f":"משה - עק\"ה","k":"בעל חזה התנופה","b":"מגדולי הראשונים, מרביץ תורה בבריסל-שנת צ' (?), מחכמי ספרד-קן והובא בשות הריב\"ש. בן לאביו ר משה שנהרג עק\"ה. חיבר קיצור תשובות הראש בשם \"חזה התנופה\"."},{"i":9732,"n":"ברזובסקי, נחום זאב מבני ברק","f":"משה אברהם מברנוביץ","bt":"חרסג","bp":"ברנוביץ","dt":"תשכט - כט טבת","dp":"בני ברק","b":"תלמיד ישיבת \"תורת חסד\" בברונביץ. עלה לארץ-תרצה וכיהן כרב לחסידי סלונים בבני ברק."},{"i":9733,"n":"ברזובסקי, שלום נח מסלונים","f":"משה אברהם מברנוביץ","k":"בעל נתיבות שלום","r":"אדמו\"ר מסלונים","bt":"תרעא","bp":"ברנוביץ","dt":"תשס - ז אב","dp":"ירושלים","b":"חתן ר אברהם וינברג האדמור מסלונים ירושלים. אביו היה ראש הקהל בברנוביץ ומחשובי חסידי סלונים שם. היה כותב דברי תורתו של רבו האדמור מסלונים ברנוביץ. עלה לארץ וכיהן כראש ישיבת חב\"ד בתל אביב, ראש ישיבת \"בית אברהם\" בירושלים-תש.","bk":[["נתיבות שלום (סלונים)",""],["נתיבות שלום - עה\"ת ומוסר",""],["שיעורי הנתיבות שלום - נשים נזיקין",""],["שיעורי הנתיבות שלום - נשים נזיקין, נתיבות שלום - עה\"ת ומוסר",""]]},{"i":9734,"n":"ברזילי","k":"בעל ספר ברזילי","b":"נזכר אצל רב האי גאון."},{"i":9735,"n":"ברזילי אלחיט משלוניקי","dt":"רעה - סיון","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":9736,"n":"ברזילי הכהן מחברון","b":"מחכמי חברון, בשנת תכא חתם על אגרת שליחות ר חייא דיין, בשנת תמה על שטר הרשאה לשד\"ר ר יעקב הלוי"},{"i":9737,"n":"ברזילי הכהן מרודוס","b":"גביר ברודוס-שנות ה-ש'-ת'."},{"i":9738,"n":"ברזילי המומר משלוניקי","b":"לדברי ל' קרבונירי-קונסול הולנד בתורכיה-1836 - היה מתלמידי שבתי צבי והתאסלם כ-12 שנה אחריו עם מאות משפחות - והיה מראשי אחד הפלגים בכת ה\"דונמה\"."},{"i":9739,"n":"ברזילי יהודה מצפת","b":"מחכמי צפת-שצ\"ה-ת\"ל"},{"i":9740,"n":"ברזילי, אברהם אהרן משלוניקי","b":"מנצח באגודת הפייטנים \"נעים זמירות\" בשלוניקי-תרפה."},{"i":9741,"n":"ברזילי, אברהם מאזמיר","b":"רב באזמיר-שץ-תל."},{"i":9742,"n":"ברזילי, אברהם משלוניקי","dt":"תקג","dp":"שלוניקי","b":"גביר בשלוניקי. יסד ישיבה לבנו - ר יעקב."},{"i":9743,"n":"ברזילי, אליהו מאתונה","b":"רב באתונה לפני השואה, סירב לשתף פעולה עם הגרמנים ובזכות פעולותיו ניצלו יהודים רבים."},{"i":9744,"n":"ברזילי, ברוך מצפת","f":"יהודה או אברהם","bp":"קושטא?","dt":"תכה משוער","dp":"צפת","b":"מחכמי קושטא, צפת-שצז, חתם בשנת שצז על מכתב לקהילת מנטובה, רבו של ר משה גלנטי (המגן), היה רב וראש הישיבה בצפת יחד עם ר יונתן גלנטי. גלה לצידון עם אחיו ר מאיר וחזרו לצפת. חיבר ספרים בכתב יד, ותשובותיו בספרי חכמי דורו. בשנת תטו שליח צפת בתורכיה ואולי גם באשכנז, יחד עם ר יונתן גלנטי, תשובה מהם מעיר תירייא ליד אזמיר. הספידו ר דוד הכהן בספרו \"בן הא הא\". אולי הוא שהיה גם בקושטא."},{"i":9745,"n":"ברזילי, ברוך מקושטא","b":"מחכמי קושטא-שנות ה-ת'."},{"i":9746,"n":"ברזילי, גבריאל משלוניקי","dt":"תק - בערך","b":"מחכמי שלוניקי."},{"i":9747,"n":"ברזילי, יהודה מצפת","dt":"שע","dp":"צפת","b":"מחכמי צפת, בשנת שסב חתם בכפר בוקיעא על פסק הלכה המופיע בשות מהריט, בניו ר ברוך ור מאיר היו מחכמי צפת."},{"i":9748,"n":"ברזילי, יהושע החסיד משלוניקי","b":"ר\"מ בחברת \"תלמוד תורה\" בשלוניקי-שנות ה-ש'."},{"i":9749,"n":"ברזילי, יעקב משלוניקי","f":"אברהם","dt":"תקטז","dp":"שלוניקי","b":"מחכמי שלוניקי, החזיק ישיבה והקים בית כנסת."},{"i":9750,"n":"ברזילי, יצחק משלוניקי","dt":"תרל","dp":"שלוניקי","b":"רב וראש ישיבה בשלוניקי. מתלמידיו - קרובו ר אשר קובו, ור משה קסטרו בעל \"ירים משה\"."},{"i":9751,"n":"ברזילי, מאיר מצפת","f":"יהודה או אברהם","bp":"קושטא?","b":"אחיו של ר ברוך. מחכמי קושטא, רב בצפת-שצז. גלה לצידון עם אחיו וחזרו לצפת. ראש ביהמ\"ד \"אברהם אבוב\" על מקום ר יהודה קרישפין-תד. בשליחות באיטליה-תט, בצפת-תטו, במודנא-תיח ושהה שם כמה שנים. ראש הרבנים בצפת לאחר פטירת ר חיים פינטו לאחר תכד."},{"i":9752,"n":"ברזילי, מואיז ביג משלוניקי","b":"רופא צבאי בשלוניקי-תרס."},{"i":9753,"n":"ברזילי, מנחם עזרא משלוניקי","b":"מחכמי שלוניקי-תרס."},{"i":9754,"n":"ברזילי, משה מקושטא","b":"מחכמי קושטא-שנות ה-ש'."},{"i":9755,"n":"ברזילי, משה משלוניקי","b":"נספד ע\"י ר\"י ן שאנגי ב\"באר יצחק\"."},{"i":9756,"n":"ברזילי, משה משלוניקי","b":"רופא בשלוניקי בזמן הרשד\"ם."},{"i":9757,"n":"ברזילי, סעדיה מתימן","f":"שמעון","bt":"תרצג","bp":"תימן","dt":"תשנה - יב אד\"ב","b":"עלה מתימן, ולמד בישיבת \"קול תורה\", והיה מקורב לר שלמה זלמן אוירבך. הקים ישיבה ועמד בראשה בישוב \"גני תקוה\"."},{"i":9758,"n":"ברזילי, עזרא משלוניקי","b":"גביר בשלוניקי. סייע בהדפסת \"בתי אבות\" לר יוסף דוד-תקפה, יחד עם חתנו - יהושע אמארג'י."},{"i":9759,"n":"ברזילי, פנחס משלוניקי","f":"עזרא","dt":"תשא - יט שבט","dp":"שלוניקי","b":"דיין בשלוניקי, ורב על מקום ר שלמה מולכו עד השואה. תלמיד ר חיים מנשה שהיה דיין אצל ר שמואל בנבנשתי. הרבה בנסיעות ברחבי יוון בולגריה ותורכיה ועמד בקשרים עם הקהילות במדינות אלו, והשיב לשאלותיהם. תשובה ממנו ב\"אבני האפוד\" לר דוד פיפאנו. הגיה \"כוכב מיעקב\"-תרעה לר יעקב קובו."},{"i":9760,"n":"ברזילי, שם טוב","f":"יוסף פלט","b":"נזכר במהרי\"ק בתשובה."},{"i":9761,"n":"ברזילי, שמואל משלוניקי","dt":"תנט","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":9762,"n":"ברזינסקי, אברהם מביעלסק","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":9763,"n":"ברזינסקי, אפרים דובער מויגובה","f":"שלמה זלמן מקורשאן","k":"בעל פליטי אפרים","bt":"תרכ","bp":"קורשאן-מחוז שאוויל","b":"תלמיד ישיבת סלנט, טלז, קובנא, וולוזין. רב בויגובה(=ואיגאווה)-תרסב על מקום ר ישעיהו ממוש. הניח חדושים בכת\"י. נסמך מאת: הנצי\"ב."},{"i":9764,"n":"ברזינסקי, יעקב צבי מארה\"ב","k":"בעל קונטרס משלש","b":"רב בארה\"ב-תרפח."},{"i":9765,"n":"ברזל, אברהם","b":"רב באלקצר(מרוקו), עבר לארגנטינה"},{"i":9766,"n":"ברזל, אפרים צבי מצפת","f":"מאיר","bt":"תרט","bp":"צפת","dt":"תרפו","dp":"צפת","b":"חתן ר יעקב שפירא מבוברקא, ובזיוו\"ש חתן ר משה משיוף. יסד בנק בצפת-תרסה עם יואל ברשד ואליהו קלינגר. בנו זלמן - גואל אדמות."},{"i":9767,"n":"ברזל, יקותיאל יהודה מקיטוב","f":"זלמן ליב","bt":"תקלו אות תקכח","bp":"קיטוב","dt":"תריג","b":"תלמיד רז\"ו מטשרני-אוסטרהא. חתן הגביר ר מאיר הויער מסרעט. עלה לארץ-תקנט (לפי גליס תקמח) והתישב בטבריה ליד ר אברהם מקליסק. חתם כממונה על מעות ארץ ישראל. נכדו של ר יחזקאל לנדא בעל ה\"נודע ביהודה\", היה הממונה על החלוקה מטעם ר ברוך ממזבוז' ור אברהם יהושע השל מאפטא."},{"i":9768,"n":"ברזל, משה מירושלים","b":"גבאי כולל ישוב ארץ ישראל בירושלים, חתם-תרץ עם ר זלמן לנדנר, ר שמעון גרוסמן."},{"i":9769,"n":"ברז\"ם, שאול מהולנד","k":"בעל זכרון שאול","bt":"תרפו","bp":"הולנד","dt":"תשכד","b":"נכד ר שאול מיברוב. ניצל מהשואה. עלה לארץ-תשה. חתן ר יעקב ישראל קניבסקי והתגורר בבית דודו החזון איש. חיבר \"זכרון שאול\" - בני ברק תשכו."},{"i":9770,"n":"ברז\"ם, שאול מיברוב","b":"מצאצאי ר זכריה מנדל מבלז בעל \"באר היטב\" - ומכאן מקור שמו. מחכמי יברוב-תרכט."},{"i":9771,"n":"ברזני, אהרן ממוסול","f":"מכלוף","dt":"תרסב","b":"רב במוסול ובנו ר דוד על מקומו אחריו-תרסו."},{"i":9772,"n":"ברזני, אליהו ירושלים","dt":"תרעו - ה תשרי","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":9773,"n":"ברזני, גדליה בנימין מירושלים","b":"תלמיד ישיבת \"שערי ציון\" בירושלים. פרסם מאמרים ב\"בכורי ציון\" - ירושלים תשד, \"מוריה\" - ירושלים תשג."},{"i":9774,"n":"ברזני, דוד ממוסול","f":"אהרן ממוסול","bt":"תרלא","b":"רב במוסול-עיראק-תרסו על מקום אביו."},{"i":9775,"n":"ברזני, יהודה מירושלים","b":"מחכמי ישיבת בית אל בירושלים-תרצב."},{"i":9776,"n":"ברזני, יהודה מכורדיסטן","dp":"ארביל","b":"מחכמי ורבני כורדיסתאן,רב ושו\"ב בכפר ביתוותא(כורדיסתאן),נפטר בגיל 38"},{"i":9777,"n":"ברזני, יוסף מירושלים","f":"אברהם","bt":"תרלא","bp":"ירושלים","b":"עסקן העדה הספרדית ופעיל צבור בירושלים."},{"i":9778,"n":"ברזני, יצחק מבגדד","b":"רב ראשי בבגדד-תעג על מקום ר שמעון בן בנימין מברזאן. ר שלמה בן שמעון מזרחי על מקומו אחריו."},{"i":9779,"n":"ברזני, יצחק מכורדיסטן","f":"יעקב","bt":"תרנב","bp":"כפר צפייה (מחוז מוצול)","dt":"תשם - יח חשון","dp":"עין העמק","b":"תלמיד דודו ר משה ברזני, וחכמי בגדד. רב בארביל עם ר יצחק נח. עלה לארץ-תשא וכיהן כרב מושב עין עמק וחבל מגידו. דרשן ומגדולי רבני העדה הכורדית."},{"i":9780,"n":"ברזני, מאיר ממוסול-עירק","b":"מלמד במוסול-עירק בתחילת המאה ה-20."},{"i":9781,"n":"ברזני, מלכיאל מירושלים","b":"מחכמי ישיבת בית אל בירושלים-תרצב."},{"i":9782,"n":"ברזני, סלימן ממוסול","dt":"תשכא - כט תשרי","dp":"טירת הכרמל","b":"תלמיד ישיבת בית זלכה בבגדד, ולמד שם עם ר יעקב מוצפי. רב במוצול-עירק-תרפד, עלה לארץ-תשיא, וכיהן כרב במעברת טירה (טירת הכרמל) שם התגוררו רבים מבני עדתו."},{"i":9783,"n":"ברזני, עבדאללה מירושלים","bp":"ירושלים","dt":"תרסו","dp":"ירושלים","b":"ממונה על הקדש היהודים ביפו מיסודו של הגביר ר ישעיה אג'ימאן, חזר לירושלים."},{"i":9784,"n":"ברזניץ, אשר מברעזאווא","f":"יוסף","b":"רב בברעזאווא. אחיו של מהרם שיק."},{"i":9785,"n":"ברזניץ, יוסף מואכטרליץ","f":"אשר מברעזאווא","dt":"תרלח","b":"רב בווכטרליץ-תר\"ג, וחתנו ר יצחק איזיק פרישמן על מקומו אחריו-תרלח."},{"i":9786,"n":"ברזניץ, יעקב ממאריאל","dt":"תשד","b":"רב במאריאל"},{"i":9787,"n":"ברזניץ, יצחק מוורטבורג","f":"יוסף מוכטערליץ","bt":"תריח","bp":"ברעזאווא","dt":"תרעט - כד אב","b":"תלמיד השב\"ס, ודודו זקנו מהרם שיק, ודודו ר יעקב סנידרס מראב. חתן ר מנחם מנדל שעהן מרעטה. רב בוורטברוג-תרמט ובנו ר מנחם מנדל על מקומו אחריו."},{"i":9788,"n":"ברזניץ, מנחם מנדל מוארטבורג","f":"יצחק","bt":"תרמה","bp":"וארטבורג","dt":"תשד - כו סיון","dp":"אושוויץ","b":"תלמיד השב\"ס והדעת סופר, ור מרדכי מאיר בנט משטיינמאנגר. חתן ר ישעיה פרידמן מטאפלטשן. רב בפאסטא-תרסח, וארטבורג-תרפג על מקום אביו. נספה בשואה."},{"i":9789,"n":"ברזניץ, מנחם מנדל מסערץ","f":"יצחק מסעמפץ","dt":"תשד","b":"רב בפאסטו(=פאסטא)-תרסח, סענץ(=סעמפץ?) על מקום אביו. פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":9790,"n":"ברז\"פ","k":"ראה: רפפורט","b":"צאצאי ר זלמן פערליס מברודי. שם המשפחה ראשי תיבות - בני ר זלמן פערליס."},{"i":9791,"n":"ברז\"פ, משה מליזנסק","b":"רב בליזנסק-ר\"נ"},{"i":9792,"n":"ברזק, שלמה יצחק ממוסניק","dt":"תש..","b":"מו\"ץ ושו\"ב במוסניק-ליטא. נספה בשואה."},{"i":9793,"n":"ברזשנסקי, משה צבי מטרליצא","b":"רב בטרליצא-תרן על מקום אביו, ובנו ר פנחס על מקומו אחריו."},{"i":9794,"n":"ברזשנסקי, פנחס מטרליצא","f":"משה צבי מטרליצא","bt":"תרל","b":"רב בטרליצא-תרנו, על מקום אביו. נסמך מאת: ר משה מיאנוב. חיבר חדושים על שו\"ע - בכת\"י."},{"i":9795,"n":"בר\"ח, אריה יהודה ליבש מלמברג","f":"מאיר","k":"בעל מלאכת חרש","b":"ידיד הדברי חיים. תלמיד ה\"ברוך טעם\". חתן ר משה אולמן מליפטוי סט. מיקלוש, בזיוו\"ש חתן ר משה ניימן - שני חותניו היו חתני הדיין ר ליב קירץ. רב בטליא-תקצב, פיכוב (פוחאף) - תקצד. טאפאליא-תריט. חיבר \"מלאכת חרש\" וינה תרכד."},{"i":9796,"n":"בר\"ח, יעקב מרדיחוב","bt":"תרעא","bp":"רדיחוב","dt":"תש..","b":"מחכמי רדיחוב. נספה בשואה."},{"i":9797,"n":"ברח\"ד, משה מבוברקא","b":"רב בבוברקא. תשובה אליו בשו\"מ."},{"i":9798,"n":"ברט אהרן","bt":"1890","dt":"ה'תשיז 1957","bk":[["מצוות למה ניתנו",""]]},{"i":9799,"n":"ברט, צבי הירש מאיסטריק","b":"תשובה אליו - \"מנחת סולת\"-תרצה."},{"i":9800,"n":"ברטהאער, מנחם מאיר מפרשבורג","dt":"תרפה - ה חשון","b":"חתן ר מיכאל זלצר מסערדאוהל - הבן. חתנו - ר יוסף וייסמנדל מטירנא."},{"i":9801,"n":"ברטינובסקי, גבריאל מירושלים","b":"רב ברודקי, ר\"מ בישיבת שער השמים בירושלים-תרע."},{"i":9802,"n":"ברטפלד, אהרן מפרוביזנא","dt":"תרצב - בערך","b":"תלמיד ר\"י ויידנפלד מהרימלוב. גביר מחכמי מפרוביזנא."},{"i":9803,"n":"ברטרם, אלעזר אלימלך מטשיטש","b":"מחכמי טשיטש - תשובה אליו \"הרי בשמים\"-תרמט."},{"i":9804,"n":"ברטרם, שלמה הכהן מקראקא","f":"זאב דב","bt":"תקן","dt":"תריח","b":"רב בשצ'קצ'ין, קראקא. חתנו ר אליעזר דוד הלוי בורנשטין רב בקראקא."},{"i":9805,"n":"ברטרם, שמואל דוד מטשיטש","f":"חיים","bt":"תרז","dt":"תש","b":"חיבר חדושים על הש\"ס. חסיד שינאווא וממקורבי האדמור. חתן ר יעקב שורץ מסוקולוב ועבר לשם. בנו ר ירוחם."},{"i":9806,"n":"ברטשין, פנחס מסקרן","f":"מרדכי","bt":"תרכט","b":"רב בסקרן-בסרביא-תרנו. נסמך מאת: ר שמואל אברהם מקונסטנטין. חתנו - ר שלמה הלר מסקרן."},{"i":9807,"n":"ברטשנידר-קסירר, בן ציון מסקאלא","f":"צבי","k":"בעל דינים חדשים","bt":"תרן","dt":"תש","b":"מחכמי סקאלא, היה דרשן נודד. חיבר \"דינים חדשים מד' ובנציון\" פשמישל תרפח."},{"i":9808,"n":"ברטשפיז, אברהם דוד מזורובנא","b":"רב בזורובנא, בנו ר משה על מקומו אחריו - נספה בשואה."},{"i":9809,"n":"בריא, יצחק מאוהניב","b":"מראשי הקהלה באוהניב."},{"i":9810,"n":"בריאוס, דניאל הלוי די מקורדובה","b":"שר צבא מלך פורטוגל שהתגייר באמשטרדם. חיבר ספרים בספרדית על מעלת עם ישראל, ושירים."},{"i":9811,"n":"בריאל, יהודה ממנטובה","f":"אליעזר","k":"בעל כללי הדקדוק","bt":"תג","bp":"מנטובה","dt":"תפב - ו אב","b":"מגדול חכמי איטליה, דיין אצל ר משה זכות, רב וראש ישיבה במנטובה. ידע מדעים ולטינית, נלחם באנטישמיות, התנגד לקבלה, לחם בשבתאות, והחרים את נחמיה חיא חיון. מתלמידיו בעל \"פחד יצחק\", בעל \"אמונת חכמים\", בעל \"קול מוסר\", הרב פינצי, ר\"י מינדולה ועוד. מתורתו בספרי חכמי דורו ותלמידיו. חיבר ספרי ויכוחים כנגד אויבי הדת, חיבר \"כללי הדקדוק. הסכים על \"ראשית בכורי קציר\" - ונציה-פיררה תעה."},{"i":9812,"n":"בריזל אלעזר","bt":"1910","dt":"ה'תשסז 2007","bk":[["אזהרות לצניעות",""],["זכרון עקידת יצחק",""],["חוקת ישראל",""]]},{"i":9813,"n":"בריזל, דב אריה","b":"אדמו\"ר מוויעלעפאלי בירושלים"},{"i":9814,"n":"בריזל, זלמן מירושלים","b":"מראשי חסידי קרלין בירושלים-תשה."},{"i":9815,"n":"בריזל, חיים אורי מרישא","f":"יוזפ מננש","bt":"תקעד","dt":"תקפט","b":"שינה שמו לבריז\"ל. מקורב לגדולי האדמורים. חתן ר צבי יעקב משנדישוב. רב ברישא, שנדישוב."},{"i":9816,"n":"בריזמן, אלתר יעקב מאיר מלאפי","b":"רב בסוארז, לאפי, וארשא, לודז, עלה לארץ. פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח, \"עמק הלכה\" - וארשא תרפו, \"קהילת יעקב\" - זבורוב-סלובקיה תרפה."},{"i":9817,"n":"בריזמן, דב אהרן מקולנא","f":"משה יוסף","k":"בעל באר מים","bt":"תרכג","b":"רב בקולנה(=קאלנא)-פלך לומזה-תרמט על מקום אביו. נסמך מאת: ר יצחק מאיר מסלובודקא."},{"i":9818,"n":"בריזמן, יעקב מאיר מלאפי","b":"פרסם מאמרים ב\"קובץ דרושים\" - פיעטרקוב תרפג."},{"i":9819,"n":"בריזמן, משה יוסף מקולנא","b":"מו\"צ ור\"מ בקולנא(=קאלנא)-פלך לומזה-תרמ, ובנו ר דב אהרן על מקומו אחריו."},{"i":9820,"n":"ברי\"ט, זבולון ליב מפלונגיאן","dt":"תרסג","b":"תלמיד ביהמ\"ד בקובנא - ופגש שם את הגדול ממינסק. רב ברשנישוק, גודלבה, פיליפובה-תרלב, קראזש, פלונגיאן. חתנו - ר דב משה נאמיוט בעל \"דברי משה\"."},{"i":9821,"n":"בריט, חיים מדוקלא","f":"דוד","k":"בעל צפחת השמן","bt":"תקץ","bp":"דוקלא","dt":"תרס","b":"חתן ר מנחם מנדל מלר ראב\"ד קודלא. נדד בארצות שונות בחיפוש אחר כתב יד ישנים. ההדיר \"כד הקמח\" עם פירושו \"צפחת השמן\" למברג תרם-תרנב. חיבר \"תולדות מגדולי עולם וחיבוריהם\" בכתב יד."},{"i":9822,"n":"בריט, יעקב קובנר מוילנא","f":"יהודה ליב","k":"יענקעל קאוונער","bt":"תקנז","bp":"סימנא-ליטא","dt":"תרמג - כז אד\"א","dp":"וילנא","b":"התיתם בילדותו והיה תלמיד ר\"י ראש ישיבה בסלובודוקה. חתן ר ברי\"ט מוילנא ומכאן שמו \"בארי\"ט\" (=ב\"ר יהודה טייץ), ובזיוו\"ש חתן נכדת ר יצחק מקאלואירא בוילנא-קרובתו של ר אבלי מוילנא, ובזיוו\"ש חתן ר אהרן טויבער - פריידקעס מוילנא. ר\"מ בישיבת ר חיים נחמן פרנס בוילנא, ודיין. בקי בשפות, פגש את השר מוניפיורי בביקורו בוילנא והשתתף במשלחת אל הצאר ניקולאי הראשון-תריז והיה שם ראש המדברים. חבר באסיפת הרבנים בפטרבורג בתרטז, בתרכב ותרכח, והיה יוצא ונכנס בעניני היהודים אצל השרים נזימוב ופוטאפוב שכיבדוהו מאוד. הגן על היהודים כנגד המשומד ברפמאן שכתב מלשינות נגד היהודים - שר הפלך קופמן מינהו לועדה שבדקה את כתב השיטנה. השתתף במשלחת לצאר אלכסנדר השני מטעם קהלת וילנא לרגל חגיגות האלף למלכות רוסיה. זקן רבני וילנא. מתלמידיו ר שבתי רוזנברג מניו יורק. פרסם מאמרים ב\"פליטת סופרים\" - וילנא תרכג."},{"i":9823,"n":"בריט, מרדכי מטיסמניץ","b":"נכד הט\"ז והב\"ח. פרנס הדור. חתן נכד ר שמואל רוקח מברודי - זקנו של השר שלום. בנו ר שמואל שמלקא אלעזר מלמברג - ממקורבי השר שלום."},{"i":9824,"n":"בריט, שלום","f":"שמואל שמלקא אלעזר","bt":"תקצא","bp":"למברג","dt":"תרסג","b":"חתן ר יעקב יושע השל בוימינגר מקראקא. מקורב לאדמורי דורו. מחכמי קראקא - האדמור מהר\"י מבלז קם לפניו מלוא קומתו."},{"i":9825,"n":"בריט, שמואל שמלקא אלעזר מלמברג","f":"מרדכי מטיסמניץ","dt":"תרלג","dp":"קראקא","b":"גביר בלמברג ממקורבי השר שלום. מכובד ע\"י אדמורי דורו. חתן ר יוסף שרנציל."},{"i":9826,"n":"בריטו די, יצחק מאמשטרדם","f":"דנא","b":"רב ק\"ק ספרדים באמשטרדם-תע עם חברו ר דוד ישראל אטיאס(=עטיאש) ור שלמה שלם מסופיה ובלגרד על מקומו אחריו (לפי רוזניס - לאחר שהחיד\"א סירב לרבנות). חתם על הסכמות רבות עם שאר רבני אמשרטדם-תצג. מעורכי \"פרי עץ חיים\" - אמשטרדם."},{"i":9827,"n":"בריטמן, דוד יעקב מטרנופול","f":"פישל מקמניץ","b":"נכד ר פנחס מקוריץ. גביר מחכמי טרנופול-תרצב. אביו היה דיין בקמניץ-פודולסק. חתנו - המהר\"ם מלובלין. (שלח את ר מנחם מאניס גולד מטרנופול לבדוק את המהר\"ם בטרם לקחו לחתן)."},{"i":9828,"n":"בריטעפנשיין, גבריאל מואשוואר","f":"ר\"מ","b":"מחכמי ואשוואר-הונגריה."},{"i":9829,"n":"בריידנבך, וולף","bt":"תקיא","bp":"כפר בריידנבך-ליד העסען","dt":"תקפט","dp":"אופנבך","b":"למד תורה וחכמה בפפד\"מ, שחקן שח, גביר ומקורב לשרים ונסיכים. שתדלן לטובת אחיו. חיבר \"קול קורא לאחינו..\" - תקסד. סייע לר וולף הידנהיים בהעתקת המחזור ופירושו, וסייע בהוצאות ההדפסה."},{"i":9830,"n":"ברייזך, וולף מפרשבורג","b":"ראש הקהל בפרשבורג. ממיסדי ביה\"ס \"הפרימער שוהלע\" - בפרשבורג-תקף כנגד דעת החרדים ובראשם ר אברהם הירש לבוב - שקרע את בגדיו עם פתיחת ביה\"ס, ונוטה לריפורמה. חתם על תקנות ביה\"ס למלאכה שע\"י הקהלה-תקפא יחד עם החת\"ס. (בתו עברה לוינה ולפריס ונכדתה הסופרת האנגליה גודוין ב שטרנהולדוארט שחיברה את הספר \"מטריארך\")."},{"i":9831,"n":"ברייער, אלעזר יעקב ממטרסדורף","b":"חתן ר בנימין זאב וולף אבלס מטאב."},{"i":9832,"n":"ברייער, אשר מפעלעדיהאז","b":"חתן בזיוו\"ש (לאחר פטירת בעלה ר קלמן זויבר) ר מאיר רייניץ מיאטשיע. נזכר ב\"פרי השדה\"."},{"i":9833,"n":"ברייער, בנימין זאב וולף מטאב","f":"אלעזר יעקב","k":"בעל נחלת בנימין","r":"אב\"ד טאב והגליל","bt":"תקץ","bp":"מטרסדורף","dt":"תרנג - כה כסלו","dp":"טאב","b":"תלמיד הכת\"ס, וראהרן זינגר ממטרסדורף. חתן ר יוסף צבי קוויטנר מנייטרא ועבר לשם. רב ברגנסדורף-תריז, טאב-תרלא, בנו ר שמחה בונם ברייער על מקומו אחריו. באוצר הרבנים שם האב: זאב וולף אבלס.","bk":[["נחלת בנימין – שו\"ת",""]]},{"i":9834,"n":"ברייער, בצלאל ממטרסדורף","f":"משה אליהו ממטרסדורף","dt":"תקסו - יט טבת","dp":"מטרסדורף","b":"תלמיד החת\"ס. נפטר בבחרותו. החת\"ס הביא מחדושיו בספרו."},{"i":9835,"n":"ברייער, ברוך מאיר","b":"רב בבלז-תרמו."},{"i":9836,"n":"ברייער, דוד מאיר מבלז","b":"רב בבלז. חתן ר זיסקינד זישא מבלז."},{"i":9837,"n":"ברייער, זאב וולף מרידיק","b":"רב ברידיק - תשובה אליו בשו\"מ."},{"i":9838,"n":"ברייער, יואל מסעליש","b":"מחכמי סעליש-תרמב. אביו של ר שמואל שמלקא מנאדי-קאטא."},{"i":9839,"n":"ברייער, יוסף מהונגריה","b":"רב בהונגריה-תרכה, חתם על מכתב ר משה טפלטשין כנגד הרב הריפורמי ד\"ר יהודה לעף מסנדין."},{"i":9840,"n":"ברייער, יוסף מניו יורק","f":"שלמה זלמן מפרנקפורט","k":"בעל דברי יוסף","b":"נכד הרש\"ר הירש מפרנקפורט. רב \"עדת ישורון\" בניו יורק."},{"i":9841,"n":"ברייער, יוסף מנמירוב","b":"מחכמי נמירוב - תשובה אליו ב\"בית דוד\"-תרסז."},{"i":9842,"n":"ברייער, יעקב","b":"פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":9843,"n":"ברייער, יצחק מפפדמ","f":"שלמה זלמן מפאפא","k":"בעל נחליאל","bt":"תרמג","bp":"פאפא","dt":"תשו - יג אב","dp":"ירושלים","b":"תלמיד השב\"ס. חתן ר יעקב הלוי אייזנמן. מחכמי פפדמ, עלה לירושלים-תרצז - והיה מגדולי העסקנים ביהדות החרדית. הו\"ל \"מוריה\" ועוד."},{"i":9844,"n":"ברייער, מרדכי מסאנטוב","b":"רב בסנטוב. חתן ר שמעון וינר מלאשברין. בנו ר שלמה זלמן מפפדמ."},{"i":9845,"n":"ברייער, משה מהונסערד-אוהל","b":"תלמיד ר שמואל דוד אונגר בישיבת טירנוי. פרסם מאמרים ב\"הלכות החדש\" - טירוני תרצא - קובץ מאת תלמידי ר שמואל דוד אונגר מטירנוי, \"משא ומתן\" - טירנוי תרצא."},{"i":9846,"n":"ברייער, נחום דובער מבויאן","f":"מנחם מנדל","k":"אדמור מבויאן-רוזין","b":"נכד האדמור ר מרדכי שלמה פרידמן מבויאן. חתן ר משולם זושא בן ר אברהם יהושע השל מקופיטשניץ (אפטא). אדמור מבויאן-תשמה על מקום זקנו."},{"i":9847,"n":"ברייער, פנחס מוינה","f":"בנימין זאב וולף מטאב","b":"דיין בוינה."},{"i":9848,"n":"ברייער, שלמה זלמן מפפד\"מ","f":"מרדכי מסנטוב","r":"רב קהל עדת ישורון בפפד\"ם","bt":"תרי","bp":"סאטוב","dt":"תרפו - ו אב","b":"נכד ר שמעון וינר. תלמיד הכת\"ס, ודודו ר צבי דב וינר מנייטרא, וזקנו מלאשברין. ודודו ר יוסף וינר מלאשברין. מורה אצל ר שמואל בונדי במיינץ. חתן ר שמשון ב\"ר רפאל הירש מפפד\"מ-תרלו, רב בפאפא-תרלו (ובתחלה היתה מחלוקת כנגדו בגלל השכלתו - עד שעמדו על גדלותו והשלימו), פפד\"מ על מקום חותנו וראש ישיבה. בניו - ר רפאל אב\"ד אשפנבורג, ר יצחק מירושלים ור יוסף רב \"עדת ישורון\" בניו יורק. פרסם מאמרים ב\"יגדיל תורה\" - ברלין-קראקא תרנא.","bk":[["דברי שלמה",""]]},{"i":9849,"n":"ברייער, שמואל שמלקא מנאדי-קאטא","f":"יואל מסעליש","bt":"תרם","bp":"סעליש","dt":"תשד","b":"תלמיד השב\"ס, ור פנחס חיים קליין מסעליש. חתן ר יהודה ליב לנדסברג מסענהאלאם. רב בנאדי-קאטא-תרסד. נספה בשואה."},{"i":9850,"n":"ברייער, שמחה בונם מטאב","f":"בנימין זאב וולף מטאב","k":"בעל קול שמחה","bt":"תרכח","dt":"תרצח - י אד\"א","b":"רב בטאב-תרנ\"ד על מקום אביו, חתנו ר דוד גרוס על מקומו אחריו-תרצח. פרסם מאמרים ב\"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז."},{"i":9851,"n":"בריל יואל","bt":"1762","dt":"ה'תקסב 1802","bk":[["עמודי הלשון",""]]},{"i":9852,"n":"בריל, אברהם חנוך הניך מפיעטרקו","b":"פרסם מאמרים ב\"בית אברהם\" - וארשא תרצד, \"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס, \"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":9853,"n":"בריל, אברהם מארה\"ב","f":"מרדכי","bp":"אונדסבורג","b":"תלמיד ביהמ\"ד לרבנים בסינסינטי. רב ריפורמי בהילינא-ארקנסו, היברו יוניון קונגרייגישן בגרינוויל-מיסיסיפי."},{"i":9854,"n":"בריל, אברהם קדיש מארה\"ב","f":"חיים יצחק","b":"מחכמי פיטסבורג-ארה\"ב. אביו הקדיש לו את ספרו \"תולדות הגדולים\" סט לואיס תרפא."},{"i":9855,"n":"בריל, דוד מפרשבורג","f":"חיים מפרשבורג","bt":"תרט","dt":"תרנא - כט כסלו","dp":"פרשבורג","b":"תלמיד הכת\"ס. מראשי הקהלה בפרשבורג."},{"i":9856,"n":"בריל, זלמן מפרשבורג","b":"גבאי ח\"ק בפרשבורג-תקעא, יחד עם ר בער פרנק."},{"i":9857,"n":"בריל, זנויל מפרשבורג","f":"עזריאל מפפד\"מ","bt":"תפב","dt":"תקסב","dp":"פרשבורג","b":"מראשי קהלת פרשבורג, וחתם על תקנות ר משה לבוב בעניני השחיטה-תקטו, ועל תקנות ר מאיר ברבי-תקכח."},{"i":9858,"n":"בריל, חיים ממישקולץ","b":"דומ\"צ במישקולץ-תרלו."},{"i":9859,"n":"בריל, חיים מפרשבורג","f":"שמואל זנויל","bt":"תקעח","bp":"פרשבורג","dt":"תרנא - י ניסן","dp":"רשבורג","b":"נימול ע\"י החת\"ס. חתן ר אלעזר הלוי הורביץ מוינה. גבאי בישיבת פרשבורג בזמן הכתב סופר והשבט סופר."},{"i":9860,"n":"בריל, יואל לעווי","f":"יהודה ליב","k":"בעל תולדות השיר","bt":"תקכב","dt":"תקסב - ט אד\"א","dp":"ברסלוי","b":"מתלמידי מנדלסון, סופר ומדקדק. גדל אצל הגביר ר אהרן יורש. מלמד את בני דוד פרידלנדר בברלין. חיבר ספרים בתולדות השיר ובלשון."},{"i":9861,"n":"בריל, יוסף ממינסק (איוב)","bt":"תקצט","bp":"הארקא-פלך מוהילוב","b":"תלמיד ישיבת שקלוב, עזב בגלל מחלוקת כנגדו שעסק גם בהשכלה, עבר לוארשא, ויטבסק, צעשניק, מינסק - ועסק בהוראה (לימד גם את שרה ברודסקי - אשת הגביר לאזאר ברודסקי מקיוב, בת הגביר ר שמחה לוריא). פרסם מאמרים ב\"המגיד\", \"המליץ\", \"הצפירה\", ועוד. הניח כתבים רבים ובהם ספר מאסף למדרשים."},{"i":9862,"n":"בריל, יחיאל מירושלים","k":"עורך \"לבנון\"","bt":"תקצו","bp":"הודו","dt":"תרמז - יד חשון","dp":"לונדון","b":"הגיע עם אביו לקושטא, ומשם לרוסיה, עלה לירושלים, גלה לפאריס (בגלל עלילה), עבר למגנצא(=מיינץ) והקים שם דפוס. חתן ר יעקב ספיר. הו\"ל \"הלבנון\", \"כבוד הלבנון\" - ירושלים-פאריס תרכג-תרמב, \"השולמית\", הו\"ל כמה מספרי הקדמונים. פעל להתישבות חקלאית בארץ, והיה ממיסדי המושבה עקרון."},{"i":9863,"n":"בריל, יעקב מגאיטין","f":"מיכל","k":"בעל מבוא המשנה","bt":"תקעב","bp":"רוסטיץ","dt":"תרן - ו כסלו","dp":"גאיטיין","b":"תלמיד החת\"ס. חתן ר נחום טרעביטש מניקלשבורג. רב ברוסטיץ-תרצט, גאיטין-תרד. חיבר \"דורש לציון\", \"בן זקנים\" ועוד."},{"i":9864,"n":"בריל, יעקב קופל משימלויא","f":"יהושע משימלויא","bt":"תרי","dt":"תרצד - ה אב","b":"תלמיד הכת\"ס והשב\"ס. ראש הקהלה בשימלויא."},{"i":9865,"n":"בריל, ישראל מפאלוטא","b":"רב בפאליטא-תקמג. חתנו - ר חיים קיצע מאירשא."},{"i":9866,"n":"בריל, מרדכי שמואל","b":"פרסם מאמרים ב\"תבונה\" - ירושלים תשא."},{"i":9867,"n":"בריל, משה מנאויסלעץ","b":"רב בנאוי-סעלץ. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד."},{"i":9868,"n":"בריל, נפתלי מוורנה","b":"רב בוורנה-תק\"צ"},{"i":9869,"n":"בריל, עזריאל מבודפשט","k":"בעל הדרת קדש","b":"דומ\"צ בבודפשט-תקצח. חיבר גם \"עין הארץ\"."},{"i":9870,"n":"בריל, עזריאל מפרשבורג","f":"זנויל מפרשבורג","dt":"תקעח - כג אייר","dp":"פרשבורג","b":"מצאצאי ר יצחק ברילין ממנהיים. תלמיד ר מאיר ברבי, ר מרדכי בנט, ר לוי פולק מטריטש, ובעל \"עמודי שטים\" - שהביא ממנו בספרו. חתן הגביר השתדלן ר קופל טעבן. גביר נדבן ותלמיד חכם מראשי קהלת פרשבורג-תקסז, ניהל מו\"מ עם נציגי נפוליאון בענין המס על היהודים והצליח להורידו. הקדיש את ביתו לביכ\"נ שנקרא ע\"ש - לאות תודה על שהיה אחד הבתים הבודדים שלא נפגע במלחמת נפוליאון. נספד ע\"י החת\"ס."},{"i":9871,"n":"בריל, צבי הירש מטיסא-איגאר","b":"רב בטיסא-איגאר-ת\"ר"},{"i":9872,"n":"בריל, צבי טעבן מלאשברין","b":"רב בלאשברין-תק\"ע"},{"i":9873,"n":"בריל, שמואל ליב מבודפשט","f":"עזריאל בריל","bt":"תקעה","bp":"בודפשט","dt":"תרנז - ו ניסן","dp":"בודפשט","b":"תלמיד החת\"ס, ור יצחק משה פרלס מבאניהאד. מלמד אצל משפחת פפנהיים בפרשבורג. תלמיד ר שמואל יהודה ליב קוידר מפרג. רב לצד אביו בבודפשט, ועל מקומו אחריו-תריג. רב הקהלה הניאולוגית-תרלג בבודפשט."},{"i":9874,"n":"ברילובסקי, שלמה זלמן מברדיטשוב","b":"רב בברדיטשוב. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד."},{"i":9875,"n":"ברילין, אליעזר זוסמן","b":"רב בפולדא-ש\"פ"},{"i":9876,"n":"ברילין, יצחק איציק ממנהיים","f":"משלם זוסמן ברילין","dt":"תלח - כג אדר","b":"רב בהמילבורג(=הילבורג)-תיט, אחרי גירוש-תלא עבר לוורמייזא, אב\"ד במנהיים ומדינת פפאלץ. בנו ר עזריאל מפפד\"מ. גיסו - ר יאיר בכרך בעל \"חוות יאיר\"."},{"i":9877,"n":"ברילין, משלם אליעזר זוסמן מפול","bt":"שנ","dt":"תכב","b":"מרביץ תורה, רב בוורמייזא-תד, פולדא(=בולדא)-תיב. חותנו של החוות יאיר. אביו של ר יצחק ממנהיים."},{"i":9878,"n":"ברילין, עזריאל מפפד\"מ","f":"יצחק ממנהיים","b":"רב בהיידינגספלד ומדינת ווירצבורג-ת\"י, פרנס בפפד\"מ. הסכים על \"יואל משה\" פירוש \"עשרה מאמרות\"."},{"i":9879,"n":"ברים, אברהם חיים מירושלים","f":"מרדכי דוד","bt":"תרפב","bp":"ירושלים","dt":"ה'תשסב","b":"תלמיד ישיבת עץ חיים בירושלים, מקורב לר איסר זלמן מלצר, לר יצחק זאב סולוביציק, ולחזון איש. חתן ר ישראל טויסיג בעל \"בית ישראל\". מראשוני ישיבת מיר בירושלים. ר\"מ בישיבת סלובודקה בבני ברק, ממיסדי ישיבת \"אהל יעקב\" - בדרך הלימוד של החזון איש, ראש ישיבה בסקווירא-ארה\"ב. מקורב לאדמור מבויאן. חבר קרוב לר שלמה זלמן אוירבך. מחותן עם ר שמואל הלוי ואזנר מבני ברק.","bk":[["מרבה חיים",""],["מרבה חיים - עובדות והליכות",""]]},{"i":9880,"n":"ברים, יהושע השל מירושלים","b":"פרסם מאמרים ב\"כרם ציון\" - ירושלים תרצה-תשיג - קובץ \"מדרש בני ציון\", \"תורת בית הוראה\" - ירושלים תשג - קובץ ישיבת רבנו חיים יוסף."},{"i":9881,"n":"ברין, דוד","b":"תשובה אליו בשו\"מ."},{"i":9882,"n":"ברין, יעקב יהודה לאש מפרשבורג","dt":"תקעט - כו תמוז","dp":"פרשבורג","b":"מחכמי פרשבורג."},{"i":9883,"n":"ברינג, יהודה מאנטורפן","b":"תשובה אליו ב\"שרגא המאיר\"."},{"i":9884,"n":"ברינג, יוסף מאנטורפן","f":"ברוך","dt":"תשמד"},{"i":9885,"n":"ברינקד, צבי נטע מאוטיאן","b":"רב באוטיאן, סטוק."},{"i":9886,"n":"ברינר, אליהו הלוי מפרשבורג","f":"נתן ברוך בנדיט משארו","dt":"תרע - טו ניסן","dp":"פרשבורג","b":"תלמיד הכת\"ס. חתן ר אשר אנשיל הירשלר מאנמסוויט. רב בנאמסוויט, ר\"מ בפרשבורג."},{"i":9887,"n":"ברינר, ברוך בנדט (בנדל)","b":"רב בשארוואר-תרך על מקום ר משה אנגל."},{"i":9888,"n":"ברינר, יוסף אשר מלמברג","bt":"תריא","dt":"תרנט","b":"חסיד בובוב מחכמי למברג. נסע לארץ ישראל להתרפא - וע\"י מעשה מופת שקרה לו נעשה ר בצלאל ברנשטין מירושלים לחסיד בובוב. נזכר ב\"טעמי המנהגים\"."},{"i":9889,"n":"ברינר, יעקב מלמברג","b":"תשובה אליו - \"מנחת יחיאל\"."},{"i":9890,"n":"ברינר, משה מלמברג","f":"אליהו אביגדור","k":"בעל בית התלמוד","bt":"תרעה","bp":"למברג","dt":"תש..","b":"מחכמי למברג. תשובות אליו \"דובב מישרים\", \"חלקת יעקב\". נספה בשואה. חיבר \"בית התלמוד\" - היה מוכן לדפוס לפני השואה."},{"i":9891,"n":"ברינר, נתן","f":"משה","dt":"תשיא","dp":"וינה","b":"חסיד בובוב."},{"i":9892,"n":"ברינר, נתן ברוך סגל משארוואר","b":"חתן ר טוביה ברגר מקארמענד. רב בשארוואר-תר\"ל. חתנו - ר צבי עקשטין מפאפא."},{"i":9893,"n":"ברינשטיין, משה","b":"גביר ותלמיד חכם. חתנו - ר שלום בן אפרים זלמן זוסמן מאוסטרהא."},{"i":9894,"n":"ברינשטין, אברהם מארה\"ב","b":"חכם תורני בארה\"ב. חיבר ערכים לתולדות תנאים ואמוראים ב\"אוצר ישראל\"."},{"i":9895,"n":"ברינשטין, משה מירושלים","k":"בעל דבר משה","dt":"תשטז","b":"ר\"מ בישיבת קמניץ בירושלים"},{"i":9896,"n":"ברינשטין, פישל מירושלים","b":"מו\"צ לחסידים בירושלים-תרע\"ז"},{"i":9897,"n":"בריסק, אהרן צבי","f":"מרדכי מטשאנד","bt":"תרע","bp":"מארגרטן","dt":"תשיט - כח סיון","dp":"ארה\"ב","b":"חתן דודו ר נתן צבי בריסק מצ'יקה, רב בצ'יקה על מקום חותנו - שעבר לסאלונטה. ניצל מהשואה ואחריה ראש ישיבת \"בית משה\" באראד (היתה בשעתה הישיבה היחידה ברומניה). עלה לארץ והתישב בנתניה והקים ישיבת \"מהר\"ם בריסק\"."},{"i":9898,"n":"בריסק, אריה ליב מירושלים","k":"בעל בריח התיכון","b":"חיבר \"בריח התיכון\" - והוא מפתח לכתב העת \"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":9899,"n":"בריסק, דוד יעקב מטיסא-דאדא","f":"יהושע מטיסא-דאדא","dt":"תשד","b":"אב\"ד טיסא-דאדא-תרעג על מקום אביו. נספה בשואה. חתנו - ר משה נתן יונגרייז בנו של ר אשר אנשל מיארמוט."},{"i":9900,"n":"בריסק, יהודה אירה ליב מקירטעש","b":"רב בקירטעש, אנטורפן. חתן ר יעקב יחיאל שוורץ מקראלי."},{"i":9901,"n":"בריסק, יהודה ליב ממחוז אראד","f":"נתן צבי מסאלונטה","bt":"תרעה - בערך","dt":"תש..","b":"תלמידי דודו ר מרדכי בריסק מטשאנד. רב בקורטיץ-מחוז אראד, והתגורר אצל אביו בסאלונטה (כי בקהילתו לא היה מנין בימות החול). חתן ר יחיאל יעקב שוורץ מקרולה. נספה בשואה."},{"i":9902,"n":"בריסק, יהושע מטיסא-דאדא(=טידאד","f":"משה שמואל מניאראד","bt":"תרז","dt":"תרעח - כח כסלו","b":"תלמיד הכת\"ס, ור חיים סופר מבודפשט, ור יעקב טננבוים מפוטנק. חתן ר מנחם גרשן גרינוולד מבאדרג-קערסטור, ובזיוו\"ש חתן ר דוד יעקב מנאדי-טאראניא. רב במעזא-זאמבור, דאדא(=טידאד)-תרלג, בנו ר דוד יעקב על מקומו אחריו, בניו גם: ר נתן צבי ממאדיאר טשעקע, ר מרדכי ממארגרטען. חתנו - ר משה דוד פרידמן מגרוסורדין בן ר יעקב פרץ."},{"i":9903,"n":"בריסק, יואל מפרשבורג","b":"מחכמי פרשבורג. חתם על כתב מנוי רבנות לחת\"ס-תקסז."},{"i":9904,"n":"בריסק, ישראל נח","b":"חתן ר צבי הרש פרגר מפאפראד. עלה לארץ וכיהן כרב בקרית אתא. פרסם מאמרים ב\"אהל שם\" - רומניה תשב."},{"i":9905,"n":"בריסק, מרדכי מטאשנד","f":"יהושע מטיסא-דארא","k":"בעל שו\"ת מהרם בריסק","bt":"תרמו","bp":"טיסה-דארא","dt":"תשד - יא סיון","b":"תלמיד ר מרדכי ליב וילקלר ממאד. חתן ר שמואל זלמן וינברגר ממארגרטן, דיין במארגרטן-תרח אצל חותנו. רבה האחרון של טשאנד-תרעט והקים ישיבה שהיתה הגדולה בישיבות טרנסילבניה. נספה בשואה. חתנו ר שמואל גרינברג הו\"ל מספריו.","bk":[["שו\"ת מהר\"ם בריסק",""]]},{"i":9906,"n":"בריסק, משה שמואל","dt":"תרלט - כג טבת","b":"רב בניאראד, פוטנאק.חתן ר שמעון ליברמן משעניא."},{"i":9907,"n":"בריסק, משה שמואל","f":"נתן צבי מסאלונטה","dt":"תש..","b":"תלמיד דודו ר מרדכי בריסק בטשאנד. חתן ר שמעון ליכטנשטין מלעכניץ בעל \"שמן המאור\". רב בלונקא-ג'ימש. נספה בשואה."},{"i":9908,"n":"בריסק, נפתלי מביהר-נאדי","f":"נתן צבי מסאלאנטא","dt":"תשד","b":"רב בביהר-נאדי-באייאם-תרפו. חתן ר מנחם מנדל שיק מסיקסא."},{"i":9909,"n":"בריסק, נתן צבי מסאלונטה","f":"יהושע מטיסא-דאדא","k":"בעל נחלת צבי","r":"אב\"ד סאלאנטא","bt":"תרמג","dt":"תשד","b":"חתן ר נפתלי הכהן שוורץ ממאד בעל \"בית נפתלי\". רב בצ'יקה(=טשעקע)-ליד גרוסורדין-תרסט, רב בסאלונטה-תרפז בקהלה החרדית שהתפלגה מהניאולוגים. נספה בשואה.חיבר גם \"נחל דמעה\", \"כבוד שבת\", ועוד. פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד. מתורתו בספר חותנו \"בית נפתלי\". נספה בשואה. חתנו - ר אלעזר אריה יונגרייז מהומנא.","bk":[["מאמר אסתר - על התורה",""],["נחלת אבות - הגדה של פסח",""],["נחלת צבי - אבות",""],["נחלת שבעה - מועדים",""]]},{"i":9910,"n":"בריסקין, יהושע מאודסה","f":"חיים ישראל","k":"בעל תיו יהושע","b":"רב בקונסטאנט-נגראד, טולטשין-תרמ, אודסה. חיבר גם \"חוט המשולש\"."},{"i":9911,"n":"בריסקמן, משה מוילנא","dt":"תשג","b":"רב בווילנה"},{"i":9912,"n":"בריסקר, אריה ליב מלבוב","b":"דיין בלבוב, חתם-תפא עם ר שמריה שמרל הורביץ, ר יהושע פאלק שור ועוד."},{"i":9913,"n":"בריסקר, טעבל מבריסק","b":"מחכמי בריסק-שנות ה-ת'."},{"i":9914,"n":"בריסקר, יואל מפרשבורג","f":"שמעון - ראב\"ד פרג","dt":"תקצה - ג שבט","dp":"פרשבורג","b":"תלמיד ר יחזקאל לנדא בעל \"הנודע ביהודה\" שבירכו שלא יזדקק לרבנות. מגדולי חכמי פרשבורג בזמן החת\"ס."},{"i":9915,"n":"בריסקר, יחיאל מיכל מלבוב","f":"אריה ליב בריסקר","dp":"לבוב","b":"מרביץ תורה ודיין בלבוב-תקטו, חתם-תקכב עם ר ישכר בער איגרא, ועוד."},{"i":9916,"n":"בריסקר, יחיאל מיכל מלבוב","f":"אליהו מלבוב","dp":"לבוב","b":"דיין בלבוב. (לפי בובר שם אביו אליהו זו טעות וצריך להיות בן אריה ליב)."},{"i":9917,"n":"בריעה רובין, משה אליקים","dt":"תשג","b":"רב בסאנדז"},{"i":9918,"n":"בריעה, אלעזר אלתר אליקים מקלוש","f":"דוד יוסף בידרמן מללו","b":"נכד ר אלעזר בריעה מקוזניץ מצד אמו - ומכאן מקור שמו \"בריעה\". חתן ר ישראל הלפרין-חתן ר שלמה חיים מקוידנוב. אדמור בקאלושין על מקום האדמור ר מאיר שלום מקאלושין. בנו ר מרדכי בידרמן."},{"i":9919,"n":"בריעה, מרדכי זאב מקאלביעל","f":"משה אליקים","b":"מצאצאי החוזה מלובלין. חתן ר יעקב צבי מפוריסוב (פשיסחא)."},{"i":9920,"n":"בריעה, משה אליקים מקאלביעל","f":"מרדכי זאב הורביץ","k":"ר משה רייזל'ס","b":"מצאצי החוזה מלובלין. שם משפחתו כשם זקנו מצד אמו. תלמיד ר ישכר בער מרדושיץ, מקורב לאדמורי פוריסוב."},{"i":9921,"n":"בריעה, משה אליקים מקוזניץ","f":"ישראל -המגיד מקוזניץ","k":"אדמור מקוזניץ","bt":"תקיז","dt":"תקפח - יב אלול","b":"חתן ר יהודה ליב הכהן מאניפולי בעל \"אור הגנוז\", ובזיוו\"ש חתן ר אלעזר מליזנסק. נתמנה לאדמור בהוראת החוזה מלובלין. חיבר \"באר משה\", \"דעת משה\", ועוד. בנו - ר אלעזר הופשטין. חתניו - ר יוסף אונגר (8124), ר יצחק שלמה מזליחוב (11500)."},{"i":9922,"n":"ברי\"ף, מרדכי מלונא","b":"רב בלונא-תרנג. פרסם מאמרים ב\"כנסת הגדולה\" - וארשא תרן."},{"i":9923,"n":"בריק גנץ, ישראל מגלזנקירכן","b":"רב בגעלזנקירכן-גרמניה. פרסם מאמרים ב\"שערי אורה\" - מיהאלביץ תרץ-תרצד."},{"i":9924,"n":"בריקס, אליעזר הלוי משברשין","f":"אפרים ברוך","k":"בעל אור תורה ממזרח","bp":"שברשין","b":"תלמיד ישיבת \"בית יוסף\" בפינסק אצל ר שמואל וינטרויב מקרלין, ר שמחה זליג מבריסק, ר אברהם יאפהן (בארה\"ב). ניצל מהשואה וברח דרך רוסיה לשנחאי וכיהן כדיין שם. היגר לארה\"ב-תשו וכיהן כרב בקהלת \"זרע ישראל\" בדנבר על מקום ר יהודה ליב גינצבורג. הו\"ל \"אור תורה ממזרח\" - שנחאי תשא. חיבר גם \"לקוטי אליעזר\". חבר אגודת הרבנים באמריקה."},{"i":9925,"n":"ברירו, שלמה מאלגיר","bt":"קפ","bp":"לקנאדסא-מרוקו","dt":"רן - בערך","dp":"תימנתית או קולומב-מרוקו","b":"מצדיקי מרוקו הקדומים. רב בתימנתית-אלגיר (מחוז תוואת). נספה עם בנו ר יצחק בדרך לעיר בשאר ושם קברם - שהפך למקום מקודש וכונה \"מול בשאר\" (פטרונה של בשאר)."},{"i":9926,"n":"בריש","b":"רב בחמלניק-תקנ\"ה"},{"i":9927,"n":"בריש","dt":"תריד - יז כסלו","b":"רב בסארנאק"},{"i":9928,"n":"ברי\"ש שטרוק, יחיאל","f":"אליעזר שטרוק","dt":"תרלו - כו כסלו","b":"מו\"צ בקוטנא"},{"i":9929,"n":"בריש, אליעזר מקוטנא","f":"משה יעקב","k":"בעל פעולת צדיק","b":"דרשן ודיין בליסא אצל בעל חוו\"ד, רב בקוטנא-תקעט. בנו - ר יעקב, ונכדו - ר יחיאל מקאליש הו\"ל ספר זקנו \"פעולת צדיק\" ובו גם תולדות המחבר."},{"i":9930,"n":"בריש, יחיאל מלודז","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":9931,"n":"בריש, יצחק ישכר","f":"זאב וואלף","dt":"תקכד","b":"פרנס דד\"א,מנהיג מדינה אחרון של רייסין"},{"i":9932,"n":"בריש, מרדכי יעקב מסוקל","f":"חיים","k":"בעל החזיון והתיקון","bt":"תרנה","bp":"סוקל","dt":"תשלז - יד כסלו","dp":"ירושלים","b":"תלמיד ר שבתי הרציג מסקול. חסיד בלז. רב באלסק, דיסבורג-תרפח, באטראפ-תרצב, צירך-תרצד. חיבר \"החזיון והתיקון\" בילגורי תרצג, \"חלקת יעקב\" ירושלים תשיא, ועוד. בנו ר שאול על מקומו.","bk":[["חלקת יעקב","שו\"ת - אחרונים"],["החזיון והתיקון",""],["חלקת יעקב – שו\"ת",""],["שו\"ת חלקת יעקב",""]]},{"i":9933,"n":"ברישניק, הרב","b":"רב בפראן על מקום ר אברהם יעקב ניימרק."},{"i":9934,"n":"ברישנסקי, ישעיה","dt":"תשג","b":"רב בריגא. פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":9935,"n":"ברישנסקי, רפאל מרדכי מהומלה","f":"יוסף","k":"בעל חדושי תורה","bt":"תרכו","bp":"ליפנישוק-פלך וילנא","b":"תלמיד ישיבות איישישוק, מיר, קובנא. נסמך מאת: ר שמואל מוהליבר, ר יצחק אלחנן ספקטור, רידב\"ז, ר יצחק מאיר מסלובודקה. רב בהומלה-תרנג, היגר לארה\"ב-תרפד וכיהן כר\"מ בת\"ת \"תורת משה\" בניו יורק, רב בוושינגטון-תרפו, רב בברונקס-תרפט. חיבר חדושים - בכת\"י. ציר בקונגרס הציוני, נואם מוכשר, חבר אגודת הרבנים באמריקה."},{"i":9936,"n":"ברישנסקי, רפאל מרדכי מנ\"י","bt":"תרכז","dt":"תשיא - כט חשון","b":"רב בהומל-תרנג, וושינגטון-תרפד, נ\"י. פרסם מאמרים ב\"היכל התורה\" - נ\"י תרצג, \"הפוסק\" - תל אביב תש-תשיד, \"תלפיות\" - נ\"י תשד."},{"i":9937,"n":"ברך, אהרן","dt":"תשא","b":"מנהל ועד הישיבות בווילנה"},{"i":9938,"n":"ברך, זלמן משלם מגוריציאה","f":"אברהם","k":"הו\"ל חסד לאברהם","b":"ממגורשי וינה-תל, רב בגוריציאה-תלז. תשובה אליו ב\"דבר שמואל\" לר שמואל אבוהב. הו\"ל \"חסד לאברהם\" לר אברהם אזולאי."},{"i":9939,"n":"ברכאל, אליהו מבגדד","dt":"תרעח","b":"מחכמי בבל, ראש ישיבה בכפר יחזקאל הנביא, בגדאד"},{"i":9940,"n":"ברכאת, אברהם מאלגיר וירושלים","bt":"תף","dt":"תקן - בערך","b":"ממשפחה מאלגיר, מחכמי ישיבת \"גדולת מרדכי\" של ר מרדכי תלוק מאלגיר בירושלים. בשליחות במרוקו מטעם קהלת ירושלים."},{"i":9941,"n":"ברכה - משפחה","b":"משפחה מיוחסת משלוניקי. ראש המשפחה ר משה ברכה ובנו ר יצחק. בני המשפחה החזיקו בחזקת השחיטה, במשך מאות שנים היו השוחטים בשלוניקי מבני 3 משפחות: ברכה - החל משנות ה-ש', מולכו, אישטרושה(=איסטרומסה) ורק להם היתה הזכות לכך."},{"i":9942,"n":"ברכה יוסף משלוניקי","b":"מחכמי שלוניקי. בשליחות קהלת שלוניקי באמשטרדם-תקיט יחד עם ר דניאל פלורנטין - לקבלת עזרה מהקהלה הספרדית לטובת יהודי שלוניקי."},{"i":9943,"n":"ברכה, אברהם משלוניקי","b":"מחכמי שלוניקי-תקן. הגיה את \"ויקרא יהושע\" לר יהושע פרחיה הכהן עם הוספות ממנו."},{"i":9944,"n":"ברכה, אברהם משלוניקי","f":"יצחק","dt":"תרפו","dp":"שלוניקי","b":"מחכמי שלוניקי, וראש השוחטים בשלוניקי. תלמיד ר אברהם הכהן משלוניקי. נכד ר משה ברכה-הרב הכולל בשלוניקי, ונכד-אבי אמו ר אברהם שיראנו - והגיה את ספר זקנו \"לאברהם למקנה\". הו\"ל \"ויקרא יהושע\" לקרובו ר יהושע הכהן פרחיה, והוסיף לו מתורתו ומתורת זקנו ר משה ברכה."},{"i":9945,"n":"ברכה, בן ציון חביב","dt":"תשסה - יד תשרי","b":"מקובל, ראש ישיבה"},{"i":9946,"n":"ברכה, בנימין מטריפולי","f":"ישעיה","dt":"תקצז","b":"רב ודיין בטריפולי. חתם בפנקס בי\"ד טריפולי."},{"i":9947,"n":"ברכה, חי מטריפולי","dt":"תרעב","dp":"טריפולי","b":"רב בטריפולי."},{"i":9948,"n":"ברכה, יוסף משלוניקי","bt":"תקך","dt":"תקץ","b":"סופר קהלת טריפולי. חתם בפנקס בי\"ד טריפולי."},{"i":9949,"n":"ברכה, יעקב משלוניקי","b":"גביר בשלוניקי ותרם לת\"ת בשלוניקי-תלה."},{"i":9950,"n":"ברכה, יעקב משלוניקי","b":"שו\"ב בשלוניקי-שן."},{"i":9951,"n":"ברכה, יעקב משלוניקי","dt":"תרמג-סג","dp":"שלוניקי","b":"דיין בשלוניקי."},{"i":9952,"n":"ברכה, יצחק מחלב וירושלים","f":"יעקב","k":"בעל ברך יצחק","dt":"תקלב - טז אד\"ב","dp":"ירושלים","b":"רב ודיין בחלב. הגביר ר אליהו סילוירה החזיק בידו ואפשר לו ללמוד ללא טרדת הפרנסה. רב בשלוניקי, עלה לירושלים. בניו - ר חיים ור אליהו. חיבר \"ברך יצחק\" ונציה תקכג."},{"i":9953,"n":"ברכה, יצחק מטריפולי-לבנון","b":"רב בטריפולי-לבנון-שפ. אחיו - ר שלמה מטריפולי-לבנון."},{"i":9954,"n":"ברכה, יצחק משלוניקי","dt":"תרד","dp":"שלוניקי","b":"מחכמי שלוניקי. חתן ר אברהם שיראנו. הניח חיבור בכת\"י. בנו - ר אברהם."},{"i":9955,"n":"ברכה, יצחק משלוניקי הזקן","f":"משה משלוניקי","dt":"תקנה","dp":"שלוניקי","b":"רב בשלוניקי-תקנב - נתמנה בגיל 90 כאחד מ\"רבני הכולל\" על מקום ר רפאל חיים אברהם קובו."},{"i":9956,"n":"ברכה, יצחק משלוניקי הנכד","f":"אברהם משלוניקי","bt":"תרן","bp":"שלוניקי","b":"ראש השוחטים בשלוניקי, עלה לארץ-תרצו יחד עם ר משה ארירה ור שמואל חיים מולכו ור יוסף שמואל שלם ועוד. רב בביהכ\"נ \"הדר קודש\" ועוד. חיבר \"ישא ברכה\" בכת\"י."},{"i":9957,"n":"ברכה, ישראל מסופיה","b":"חתן ר יהודה סיד בעל \"נר מצוה\"."},{"i":9958,"n":"ברכה, מצליח מאזמיר","dt":"תקל - ז כסלו","dp":"אזמיר","b":"רב באזמיר."},{"i":9959,"n":"ברכה, מרדכי אברהם משלוניקי","b":"מחכמי שלוניקי. ממיסדי חברת \"דובב שפתי ישנים\"-תרנו."},{"i":9960,"n":"ברכה, מרדכי משלוניקי","f":"אברהם","dt":"תש..","b":"דיין בשלוניקי. נספה בשואה."},{"i":9961,"n":"ברכה, משה מאזמיר","dt":"תקכט - י סיון","dp":"אזמיר","b":"מחכמי אזמיר"},{"i":9962,"n":"ברכה, משה משלוניקי","dt":"תרלז - לפני","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":9963,"n":"ברכה, משה משלוניקי - א","dt":"תקטו","dp":"שלוניקי","b":"מחכמי שלוניקי. מנכדיו - ר אברהם אלקלעי בעל \"זכור לאברהם\"."},{"i":9964,"n":"ברכה, משה משלוניקי - ב","f":"יצחק משלוניקי","dt":"תקצה - יב אדר","dp":"שלוניקי","b":"רב הכולל בשלוניקי-תקצב על מקום ר יעקב מנשה יחד עם ר מרדכי מטלון. חתמו על פסק ר אשר קובו-תקצה, ובענין יתומי טאראגנו מקושטא. בניו - ר יצחק, ר אהרן נהרג עק\"ה-תקפה בגומירג'ינה ע\"י היוונים בזמן המרד. חתם-תקפד עם ר מנחם גטניו ור אברהם ן חסון."},{"i":9965,"n":"ברכה, נסים מירושלים","b":"מחכמי חלב, ירושלים בישיבת \"נוה שלום\", נמנה על בית דינו של ר נסים חיים מזרחי. בשליחות בבלקן-תקג, חתם על תקנת החזקות-תקט, חתם על התקנה בענין משחק הקלפים-תקיד, ועל איסור לנשים ללכת ללא רעלה על פניהן בירושלים - בזמן ר יצחק רפפורט בעל \"בתי כהונה\". חתנו - החיד\"א, המזכירו בספריו. הסכים על \"שער יוסף\"-תקיז, \"חיי עולם\"-תקיב."},{"i":9966,"n":"ברכה, עמנואל משלוניקי","dt":"תמו","dp":"שלוניקי","b":"רב בשלוניקי."},{"i":9967,"n":"ברכה, עמנואל משלוניקי - ב","b":"חתם על שטר בוררות-תקם בין בני ר יצחק מולכו לבין גבאי הקהל."},{"i":9968,"n":"ברכה, שלמה מדמשק","b":"פייטן מחכמי דמשק-ת'."},{"i":9969,"n":"ברכה, שלמה מטריפולי-לבנון","b":"מראשי קהלת טריפולי-לבנון-שפ. אחיו - ר יצחק מטריפולי-לבנון."},{"i":9970,"n":"ברכה, שלמה מצפת","b":"מחכמי צפת, חתם-תקנא על כתב שליחות ר חיים מודעי."},{"i":9971,"n":"ברכה, שלמה מקהיר","b":"רב בקהיר-שנח וחתם אז על קבלת עדות. נזכר בשו\"ת ר חיים כפוסי."},{"i":9972,"n":"ברכהן, אלעזר הכהן מפלאצק","f":"דב בר יהודה ליב","b":"רב בפלאצק(=פלוצק)."},{"i":9973,"n":"ברכות, סעדיה ממצרים","b":"רב במצרים. מגדולי תלמידי הרמב\"ם."},{"i":9974,"n":"ברכיאל מארם צובא","b":"ראש קהילות ישראל בארם צובה-ד'תתק\"כ"},{"i":9975,"n":"ברכיה בירך מקלמנטוב - הנכד","k":"בעל זרע ברך השלישי","bt":"תל","dt":"תק","b":"נכד ר ברכיה בירך בעל \"זרע ברך\". רב בקלמנטוב, דרשן ביאברוב. בנו ר יצחק רופא מלובלין. בתו הרבנית חיה-נפטרה בלובלין תקיב."},{"i":9976,"n":"ברכיה ברך מראווה","b":"שו\"ב בראווה, ברודי-תקעח. תשובה אליו - \"בית אפרים\"-תקעב."},{"i":9977,"n":"ברכיה הכהן"},{"i":9978,"n":"ברכיה הכהן ממזריטש","f":"יצחק הכהן","b":"רב במזריטש"},{"i":9979,"n":"ברכיה הלוי מצרפת","b":"מגדולי הראשונים מחכמי צרפת-שנת ס'"},{"i":9980,"n":"ברכיה הנקדן קרשביהו","f":"נטרונאי","k":"בעל משלי שועלים","b":"מדקדק, נקדן, מתרגם, דרשן בנורמנדי או פרובנס-ד'תתק. תרגם משלי אזופוס מערבית - בשם \"משלי שועלים\" - מנטובה. חיבר קיצור מספר האמונות לר סעדיה גאון. ספר מוסר בכת\"י (ברשימת די רוסי)."},{"i":9981,"n":"ברכיה מאוזדא","dt":"תריג-ד","b":"אב\"ד אוזדא-פלך מינסק. מתלמידיו - ר ישראל שלמה מראסיין (המכונה ר שלמה מתמיד)."},{"i":9982,"n":"ברכיה מאנגליה - ניקולא","f":"משה","k":"ברכיה מניקולא","b":"מגדולי הראשונים באנגליה-ד'תתס\"ו"},{"i":9983,"n":"ברכיהו (בורוכוב), אהרן מיכל","f":"אבא יעקב","k":"בעל נכסים וערכים","bt":"1870","bp":"וילנא","dt":"1946","dp":"ירושלים","b":"מורה וסופר. תלמיד ישיבות וולוזין, סלובודקה. למד באוניברסיטת ברן. פרסם מאמרים בעתוני רבים ובהם \"המליץ\", \"הזמן\". עלה לארץ-1912. מורה לתלמוד בביהמ\"ד למורים ובגימנסיה בירושלים. ציר בקונגרסים ציוניים."},{"i":9984,"n":"ברכיהו (בורוכוב), מרדכי","f":"אבא יעקב","k":"בעל בית הספר והתלמיד","bt":"1882","bp":"מאישיגולה","dt":"1959","dp":"ירושלים","b":"רופא ועתונאי. תלמיד ישיבת טלז, למד רפואה בבזל. עלה לארץ-1912 והיה רופא בגימנסיה העברית \"הרצליה\". חיבר מאמרים רבים וכמה ספרים בעניני חינוך ורפואה."},{"i":9985,"n":"ברכין, משה הלוי מקרופקה","f":"צבי הירש","bt":"תרכג","b":"רב בקרופקה(=קרופקי)-פלך מוהילוב-תרנג, מו\"צ במוסקבה-תרעב."},{"i":9986,"n":"ברכן, משה מקרעשוב","b":"מו\"צ בקרעשוב-ת\"ר"},{"i":9987,"n":"ברכפלד, יהודה ליב מרישא","bt":"תקעה","dp":"טיטשין","b":"בעל אחוזה בטיטשין. אבי משפחת ברכפלד."},{"i":9988,"n":"ברכפלד, יחזקאל שרגא מבובוב","f":"יצחק דוד","bt":"תרנט","bp":"בובוב","dt":"תשמא","b":"היגר לאנטורפן ועסק ביהלומים. ניצל מהשואה ועבר למכסיקו ועמד שם בראש המזרחי, נשיא המזרחי בבלגיה."},{"i":9989,"n":"ברכפלד, מנדל ממישלניץ","f":"יוסף הלל","k":"בעל יוסף הלל","bt":"תרעח","bp":"מישלניץ","dt":"תשמד","b":"מחכמי מישלניץ, עבר לניו יורק אחר השואה. מחשובי חסידי בובוב. תשובה אליו \"חזון נחום\". חיבר \"יוסף הלל\" ניו יורק תשמז."},{"i":9990,"n":"ברכר, גדליה","k":"בעל פירוש לכוזרי","b":"חיבר פירוש על ספר הכוזרי - פרג תקצח."},{"i":9991,"n":"ברכר, דוד הכהן","f":"דוד","dt":"תשטו","b":"בניו ר יוסף, ר שמשון, ור יחיאל מיכל."},{"i":9992,"n":"ברכר, חיים מרדכי הכהן מפודהייץ","f":"יוסף אריה","k":"הו\"ל תורה שלמה","bt":"תרם","bp":"פודהייץ","dt":"תשכו","b":"עבר לניו יורק והיה רב קהילת פודהייצה-\"משאת בנימין\" שם. עסק שנים רבות בהוצאה לאור ועריכה של ספרי קודש וביניהם \"תורה שלמה\" ניו יורק תרץ."},{"i":9993,"n":"ברכר, יעקב","b":"תשובה אליו - \"מחזה אברהם\"-תרמג."},{"i":9994,"n":"ברכר, יעקב יוסף מדרשביץ","b":"רב בדרשביץ. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד."},{"i":9995,"n":"ברכר, שרגא פיבל הלוי מובצץ","f":"צבי אריה","bt":"תרסג","bp":"בוצאץ","dt":"תשלד","dp":"בני ברק","b":"חסיד צורטקוב וסדיגורא. חתן ר פנחס דיסטנפלד. רב בסן רימו בגנואה באיטליה-תרצד, רב בקיטו-אקוודור, קאלי-קולומביה. עלה לארץ בתשכ\"ה."},{"i":9996,"n":"ברל לייפציקער מטלז","f":"מרדכי","b":"מראשי קהלת טלז-תקץ בזמן המרד הפולני."},{"i":9997,"n":"ברל, אליעזר דוד מקולבסוב","f":"משה יוסף","bt":"תרנה","bp":"קולבסוב","dt":"תשלג","b":"תלמיד ר יחיאל ויינמן. היגר לארה\"ב וכיהן ברבנות. הלחין ושימר את ניגוני דזיקוב. התכתב עם גדולי הרבנים בארה\"ב."},{"i":9998,"n":"ברל, חיים יהודה מקולבסוב","f":"משה יוסף","k":"בעל רבי יצחק מקאמרנא","bt":"תרסג","bp":"קולבסוב","dt":"תשב","b":"תלמיד רא\"ל טיטלבוים מקולבסוב ור יחיאל ויינמן מקולבסוב. עבר לניו יורק-תרפא וכיהן כרב בניו יורק. חיבר \"ר יצחק אייזיק מקאמרנא\" ירושלים תשכה."},{"i":9999,"n":"ברלין (בר אילן), מאיר","f":"נפתלי צבי יהודה","k":"בעל מוולוזין עד ירוש","bt":"תרם","bp":"וולוזין","dt":"תשט - יט ניסן","b":"בן הנצי\"ב. תלמיד ישיבת וולוזין, טלז, בריסק, נוברדוק. למד באוניברסיטה בברלין, הצטרף למזרחי והיה ציר בקונגרס הציוני, ישב בארה\"ב בזמן מלחה\"ע ה-I והיה פעיל בארגונים יהודים, ונשיא ישיבת ר יצחק אלחנן. חיבר גם \"בשבילי התחיה\"."},{"i":10000,"n":"ברלין יעקב בן אברהם","bt":"1708","dt":"ה'תקי 1750","bk":[["באר יעקב",""],["זכרון יעקב",""]]},{"i":10001,"n":"ברלין נח חיים צבי בן אברהם מאיר","bt":"1734","dt":"ה'תקסב 1802","bk":[["מעין החכמה",""],["עצי אלמוגים",""],["עצי ארזים",""]]},{"i":10002,"n":"ברלין, אברהם","f":"יעקב מפיורדא-באר יעק","b":"סייע בהדפסת ספר אביו."},{"i":10003,"n":"ברלין, אברהם מהלברשטט ואמשטרדם","f":"יהודה יודא מברלין","dt":"תצ - כד אדר","dp":"אמשטרדם","b":"נכד \"ר משה ר מנדלס\" מפוזנא. תלמיד ר עוזיאל מקאליש-אביו של ר יחיאל מיכל בעל \"נזר הקדש\". רב בהלברשטט-תנב, רב לעדה האשכנזית באמשטרדם-תעז. הסכים על כמה ספרים ובהם \"מקור חיים\" לר חיים קרוכמל. תשובה ממנו ב\"אבן השהם\"-תנב. חיבר \"התנצלות התלמוד נגד מתנגדיו\", ואגרת אודות תפילת \"עלינו לשבח\". חתנו - ר יצחק בן זיסקינד מאמשטרדם."},{"i":10004,"n":"ברלין, אהרן מנייטרא","b":"רב בנייטרא-תקכב. ישב כנציג קהלת פרשבורג (במקומו של ר יצחק לנדא הראב\"ד - שחלה) בבוררות ביערגן-תקכא - בסכסוך שבין קהלות פרשבורג שטמפן וסערדהאלי - יחד עם ר שמעון דוד מסערדהאלי ור יצחק איזיק קאליש."},{"i":10005,"n":"ברלין, אליעזר ליפמן מברלין","f":"יהודה יודא מברלין","dt":"תפ - אחרי","dp":"ברלין","b":"אחיו של ר אברהם מהלברשטט ואמשטרדם. חתן הגביר ר יוזפא מדיסלדורף. גביר מחכמי ברלין. חתנו - ר יצחק איזיק בן בער אורשעל."},{"i":10006,"n":"ברלין, אלעזר","b":"רב בשנת תק\"ס"},{"i":10007,"n":"ברלין, אריה ליב","f":"שאול - בשמים ראש","k":"בעל מקור הברכה","bt":"ה'תצז","dt":"ה'תקעד","dp":"פפד\"מ","b":"גדל אצל זקנו-אבי אמו ר יצחק יוסף תאומים בברסלוי. תלמיד ר פנחס הורביץ מפפד\"א. חיבר גם \"אילת אהבים\", \"אשת נעורים\" ונדפס רק ההקדמה בשם \"כוכב נוגה\". היה מחלוקת כנגדו ולימים המיר דתו, אך חזר בתשובה לפני פטירתו.","bk":[["הגהות רבי לייב ברלין [עהש\"ס]",""]]},{"i":10008,"n":"ברלין, אריה ליב מבומברג","f":"(אברהם) מאיר","bt":"תצז","dt":"תקעד","b":"מראשי קהלת פיורדא, רב בבומברג-תקן, קסל-תקנד ומדינת האסן. אחיו - ר נח חיים צבי בעל \"עצי אלמוגים\". בנו - ר זאב וולף מפיורדא."},{"i":10009,"n":"ברלין, ברוך מיאנוביץ","b":"רב ביאנוביטש-תר\"ל"},{"i":10010,"n":"ברלין, דוד טבלי מירושלים","f":"שלמה מלונדון","dt":"תריב - טז חשון","dp":"לונדון או ירושלים","b":"נכד ר צבי הירש מלונדון וברלין. עלה לירושלים-תקצח, שמש ונאמן חורבת \"רבי יהודה החסיד\"-\"מדרש ציון\". פרסם מאמר \"דער טרייע ציאנסוועכטער\". (אצל ריבלין מחליף בינו לבין ר דוד טבלי שיף שנפטר - תקנב)."},{"i":10011,"n":"ברלין, דוד מהמבורג","f":"אריה ליב מוכיח מפרשב","k":"בעל חדושים על הש\"ס","dt":"תקלא - יח אדר","dp":"אלטונא","b":"אחיו של ר ישעיהו פיק. מגדולי דורו. ראב\"ד במרקברייט, ראש מדינה בשוורצבורג, רב בדעסוי-תקכג על מקום ר משה אהרן שעבר לברלין, רב באה\"ו-תקכז על מקום ר יצחק הלוי הורביץ ור ישעיה יפה על מקומו אחריו (כממלא מקום זמני). תשובה ממנו בענין הגט מקליווא ב\"אור ישראל\". מתורתו בספר גיסו ר יוסף שטינהרט - \"זכרון יוסף\", ב\"בית אבל ובית משתה\" אלטנא תקל. הסכים על ספרים רבים ובהם \"באר יעקב\", \"אור עולם\", \"לשם זבח\", ועוד."},{"i":10012,"n":"ברלין, דניאל מברלין","b":"מראשי הקהילה בברלין. חתם על הסכם ויתור מס הקהילה ממשה מנדלסון-תקכג, ועל אישור מיוחד למנותו לפרנס עם יבחר לכך כנגד התקנות הרגילות-תקלא"},{"i":10013,"n":"ברלין, זאב וולף מפיורדא","f":"אריה ליב מבומברג","b":"פרנס ומנהיג בפיורדא. חתנו - ר מאיר בן איצק מאנשבאך."},{"i":10014,"n":"ברלין, חיים מירושלים","f":"נפתלי צבי יהודה-הנצי","k":"בעל אמרי חיים","bt":"תקצב","bp":"וולוזין","dt":"תרעג","dp":"ירושלים","b":"רב במוסקבה, וולוזין, קוברין-תרנב, יליזבטגרד(=אליזבטגרד)-תרנז על מקום ר יהודה ליב אפשטין. בשנת תרמט סגן ראש הישיבה בוולוזין. עלה לירושלים-תרסו ואחרי פטירת ר יצחק בלזר בשנת תרסז מינהו ר שמואל סלנט לממלא מקומו ברבנות ירושלים. רבה של ירושלים-תרסט על מקום ר שמואל סלנט. היה בעל ספריה גדולה והכל הוריש לישיבת עץ חיים. חדושי תורה ממנו בספרי שות ובקבצים רבים. חיבר \"אמרי חיים\" תל אביב תשך. פרסם מאמרים ב\"כבוד הלבנון\" - ירושלים תרכג, \"מכילתא דרבנן\" - אודסה תרמו, \"פרח הלבנון\" - וארשא תרעח, \"שערי תורה\" - וארשא תרסג. חתנו - ר אפרים סמונוב מוינדאווי."},{"i":10015,"n":"ברלין, חיים ממוהילוב","f":"מאיר ברלין","b":"רב במוהיליב-תרכ\"ט. פרסם מאמרים ב\"תבונה\" - ממל-קניגסברג תרכא."},{"i":10016,"n":"ברלין, טבלי מפיעטרקוב","f":"צבי הירש ברלין","dp":"פיעטרקוב","b":"חתנו ר גציל הורביץ בן מרדכי מקראקא בן ר פנחס הורביץ בעל ההפלאה."},{"i":10017,"n":"ברלין, יהודה הכהן","f":"נתן הכהן","b":"אחיו של בעל ר משה מרדכי בעל צאן קדשים. בנו - הגביר ר איציק ברלין."},{"i":10018,"n":"ברלין, יהודה יודא מברלין","f":"אליעזר ליפמן מגטינגן","b":"אחיו של ר יצחק בנימין וולף מברלין. גביר ופרנס בברלין ומקורבים לשלטון ובמיוחד למלך פרידריך הראשון מלך פרוסיה. יסד עם אשתו אסתר בית מדרש, וסייע לחתנו ר אהרן בן אחיו להתמנות לרב וראש ישיבה בברלין. היה במחלוקת עם ר קופל ריז הלוי שהקים את ביהכ\"נ הראשון בברלין., והיה גם במחלוקת עם ר מרדכי בן מנלין ראנבאך שביקש לאחד את כל הקהילה בביכנ\"ס אחד והמחלוקת פלגה את הקהילה - וגם אחר פטירתו נמשכה המחלוקת בהנהגת אשתו אסתר, ולאחר פטירת המלך ועליית בנו פרידריך וילהלם גורשה מברלין. בניו: ר אברהם ברלין אב\"ד הלברשטט, ר אליעזר ליפמן מברלין, חתנו - ר נפתלי הרץ פער בן אהרן אופנהיים מפפד\"מ."},{"i":10019,"n":"ברלין, יעקב ממיר וירושלים","f":"יהודה אידל בן יוסף","k":"אבי הנצי\"ב","dt":"תרכח - יד חשון","dp":"ישראל","b":"אחיו של ר מאיר ממוהליב, נכד ר יוסף רוזעש משקלוב (יחד עם אחיו ר יעקב - כונו האחים רוזעש). חתן ר מיכאל איזנשטט. רב במיר, עלה לירושלים, חתם-תרך על כתב שליחות. (תאריך הפטירה בעיר וילנא - י חשון תרל בערך). בניו - הנצי\"ב מוולוזין, ר חיים ברלין מוילנא."},{"i":10020,"n":"ברלין, יעקב מפיורדא","f":"אברהם","k":"בעל באר יעקב","b":"תלמיד ר יעקב פופרש מפפד\"מ. חתן ר יוסף שטינהרט מפיורדא. מגדולי חכמי דורו, רב בפיורדא-תקי. חיבר \"באר יעקב\", \"זכרון יעקב\", ובנו - ר אברהם ואחיו - ר יצחק סייעו בהדפסת ספריו. גיסו - ר יוסף מאיר שנייטוך. ר יצחק פפלצבורג סייע ערך את ספריו והכינם לדפוס והוסיף הערות וביאורים."},{"i":10021,"n":"ברלין, יצחק איזיק","f":"אלעזר לאזי","bt":"תקנג","bp":"המבורג","dt":"תרכה - כו סיון","dp":"אלטונא","b":"מדקדק, מחכמי הקלויז בהמבורג על מקום ר חיים גורדון, ר\"מ בהמבורג על מקום אביו. חיבר פירוש ותרגם למחזור הנובר-תקצט, הו\"ל מחזור המבורג-תרכד."},{"i":10022,"n":"ברלין, ישראל","b":"פרסם מאמרים ב\"כנסת הגדולה\" - וארשא תרן."},{"i":10023,"n":"ברלין, מאיר מהאלוסק ומוהילוב","dt":"תרכט","b":"רב בהאלוסק(=הלוסק)-תקפט, מוהילוב, ובנו ר חיים על מקומו אחריו. אחיו - ר צבי הירש, ר יעקב ממיר-אבי הנצי\"ב."},{"i":10024,"n":"ברלין, מאיר משאווילן","bt":"תרלו","dt":"תשח","b":"חתן בנו של ר צבי הירש רלבה משאווילן. רב בסאבילן(=שאווילן) על מקומו אחריו, עלה לארץ-תר\"ד?, ר\"מ בישיבה בתל אביב. פרסם מאמרים ב\"מוריה\" - ירושלים תשג, פרסם מאמרים ב\"נר מערבי\" - נ\"י תרפד - קובץ ישיבת ר יצחק אלחנן."},{"i":10025,"n":"ברלין, משה מהמבורג","f":"אלעזר לאזי","bp":"פוזן","dt":"תקפט - טז אדר","dp":"אלטונא","b":"תלמיד זקנו ר יוסף בברלין. מראשוני ביהמ\"ד המכונה \"ר ליב בר שאול קלויז\" בהמבורג יחד עם ר אליעזר ליפמן בן יוחנן. מו\"צ בהמבורג-תקסט. הו\"ל ספר אביו \"משנת דרבי אליעזר\" עם הקדמה ממנו"},{"i":10026,"n":"ברלין, משה ממנצסטר","f":"יצחק איזיק","bt":"תרי","b":"תלמיד ר אנשל שטרן מהמבורג, ר עזריאל הילדסהימר, בעל תואר ד\"ר מפרוסיה. מצאצאי ר אלעזר לאזי מאה\"ו. רב בפארטסי-אנגליה, ניו פורטמוק-אנגליה, מנצסטר."},{"i":10027,"n":"ברלין, משה משקלוב ופטרבורג","b":"משכיל. חיבר \"תולדות החסידות\" ברוסית - בכת\"י, ובו מביא לידיעת פקידי השלטון הרוסים את הסכנה בחסידות בכלל ובחסידות חב\"ד בפרט."},{"i":10028,"n":"ברלין, נח חיים צבי הירש מהמבור","f":"(אברהם) מאיר","k":"בעל עצי אלמוגים","r":"אב\"ד ברייט, פייערשטראף, מגנצא ובסוף ימיו באה\"ו","bt":"תצד","dt":"תקסב - ג אדר","dp":"אה\"ו","b":"חתן ר אליהו דב שוואבאך. דרשן, מרביץ תורה, דיין בפיורדא-תקכה, רב בברייט, פפיירשטוף, מגנצא או מיץ, המבורג-תקס על מקום ר רפאל הכהן. חברו של ר פנחס הורביץ בעל ההפלאה, והיה אחד משני ה\"גדולים\" שבעל \"נודע ביהודה\" סמך על פסקם במעשה שהיה עם גירוש אישה בעל כרחה. חיבר גם \"עצי ארזים\", \"עצי בשמים\", ועוד. אחיו - ר אריה ליב מבומברג. תלמידו - ר שמשון וולף מהידנהיים. הסכים על \"דגול מרבבה\" מגנצא תקנד, מחזור אלטונא. לזכרו - \"ארבע כוסות\" (אוצר החיים 336). ר חיים מוולוזין פנה אליו בשאלה אחר פטירת הגר\"א - וכתב לו כי לאחר פטירת רבו אין לו למי לפנות כי אם אליו.","bk":[["מעין החכמה – מצוות התורה",""],["עצי אלמוגים – נט\"י עירובין ושניות",""],["עצי ארזים – אה\"ע",""],["עצי אלמוגים",""],["עצי ארזים",""],["מעין החכמה",""]]},{"i":10029,"n":"ברלין, נחום גרשון הכהן משוינצ","f":"יעקב","bt":"תרלה","bp":"ביעשניקוביץ-פלך ויטבסק","b":"תלמיד ישיבות וילנא וקובנא. חתן ר מרדכי לאצקעוור מקובנא (שליט). רב באגנלינא(=אגאנאלינא)-פלך וילנא(מחוז שוינציאן)-תרנט, קהלת החסידים בשוינציאן-פלך וילנא-תרסב, הרדניא(=האראדניא)-פלך צרניגוב-תרע. נסמך מאת: ר יצחק אלחנן ובנו ר צבי הירש רבינוביץ, ר שלמה הכהן מוילנא, ר משה דנישבסקי, ר מאיר נח לוין מוילנא, ר שמריה נח שניאורסון מבוברויסק, ר יוסף רוזין-הרוגצובר. פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה. חיבר חדושים, שו\"ת - בכת\"י."},{"i":10030,"n":"ברלין, נפתלי צבי יהודה-הנצי\"ב","f":"יעקב ברלין","k":"הנצי\"ב- בעל העמק דבר","r":"ראש ישיבת וואלז'ין","bt":"תקעז","bp":"מיר","dt":"תרנג - כח אב","b":"חתן ר יצחק מוולוזין. מחנך,גדול מרביצי התורה בדור האחרון,ראש ישיבת וולוזין-תריג עד לסגירתה-תרנב. פרסם מאמרים ב\"עיטור סופרים\" - וילנא תרמח.","bk":[["העמק דבר","מפרשי תורה"],["הרחב דבר","מפרשי תורה"],["רינה של תורה [לנצי\"ב] - הקדמה","מפרשי נ\"ך"],["רינה של תורה [לנצי\"ב] - מטיב שיר","מפרשי נ\"ך"],["רינה של תורה [לנצי\"ב] - מטיב שיר בקיצור","מפרשי נ\"ך"],["שאר ישראל [לנצי\"ב]","מפרשי תנ\"ך"],["מרומי שדה [על הגמרא]","מפרשי ש\"ס - אחרונים"],["מרומי שדה [על המשנה]","מפרשי ש\"ס - אחרונים"],["מרומי שדה [מכתבים ותשובות]","מפרשי ש\"ס - אחרונים"],["מרומי שדה","מפרשי ירושלמי"],["משיב דבר","שו\"ת - אחרונים"],["נצי\"ב",""],["דבר העמק - נ\"ך",""],["העמק דבר הרחב דבר - עה\"ת",""],["העמק שאלה – שאילתות",""],["משיב דבר – שו\"ת",""],["עמק הנצי\"ב",""],["רינה של תורה",""]]},{"i":10031,"n":"ברלין, נתנאל מאמציסלב","f":"יעקב ברלין","bt":"תקפה","dt":"תרלב","b":"רב בסלאצי,אמציסלב. אחיו של הנצי\"ב."},{"i":10032,"n":"ברלין, עקיבא משאוולאן","dt":"תשג","b":"רבה האחרון של שאוולאן-תרפט. נספה בשואה."},{"i":10033,"n":"ברלין, פייטל מברלין - א","f":"אפרים","b":"פו\"מ בברלין-תץ. גביר תקיף ומקורב לשלטון והיה במחלוקת נגד ר יעקב יושע בעל \"פני יהושע\" שפסק כנגדו בדין עד שגרם לעזיבתו למיץ."},{"i":10034,"n":"ברלין, פייטל מברלין - ב","b":"מראשי הקהילה בברלין. חתם על הסכם ויתור מס הקהילה ממשה מנדלסון-תקכג, ועל אישור מיוחד למנותו לפרנס עם יבחר לכך כנגד התקנות הרגילות-תקלא."},{"i":10035,"n":"ברלין, צבי הירש","f":"שלמה","dt":"תרלב - ד אב","b":"עלה לא\"י-תרי\"ג, בנה חורבות ירושלים."},{"i":10036,"n":"ברלין, צבי הירש","bt":"תפא","dt":"תקס","b":"אחיו - ר מאיר ממוהילוב.","bk":[["הגהות רצ\"ה ברלין",""]]},{"i":10037,"n":"ברלין, צבי הירש מליסא","f":"אריה ליב מוכיח","b":"רב בליסא. אחיהם של - ר ישעיה ברלין פיק, ר דוד - אב\"ד אה\"ו."},{"i":10038,"n":"ברלין, שאול מברלין","f":"צבי הירש ברלין","k":"בעל מצפה יקותיאל","bt":"תק","dt":"תקנה - כג חשון","dp":"לונדון","b":"חתן ר יצחק יוסף תאומים מברסלוי. רב בפפד\"א-תקכ\"ב. חיבר בעילום שמו \"מצפה יקותיאל\" כנגד \"תורת יקותיאל\" לר רפאל הכהן מהמבורג, ועל כך הוחרם הספר בידי בי\"ד אה\"ו ורוב רבני אשכנז, וכמעט הוחרם המחבר בידי אביו רבה של ברלין שלא ידע כי בנו הוא המחבר (חתם שמו בספר - עובדיה בן ברוך). וחיבר גם \"כתב יושר\" - מחברת תשובה כנגד רבני אה\"ו, וכנראה הוא מחבר המאמר \"ויכוח שני ריעים זרח ופרץ\" תקמט, והביא מכתב תמיכה מאביו לבל יחרימוהו, גם ר יחזקאל לנדא בעל \"נודע ביהודה\" יצא כנגד החרם - למרות שלא הסכים לדברי ר שאול. חיבר גם \"בשמים ראש\" ובו תשובות לא ידועות מהרא\"ש ואמר שקבצם ר יצחק די מולינא, והגיעו לר חיים בן יונה זאבי מתורכיה והגיעו אליו - ר שאול כשפגשו באיטליה - רוב רבני אשכנז ופולין הודיע כי הספר הינו זיוף. חיבר גם \"ערוגת הבושם\", ועוד. בניו - ר אריה ליב בעל \"מקור ברכה\", ר שלמה מפרנצלויא, ר טעבלי מפיעטרקוב. חתנו - ר יעקב משה בן אחיו ר שאול מאמשטרדם."},{"i":10039,"n":"ברלין, שאול מזאגדמישל","f":"שלמה מלונדון","b":"נכד ר צבי הירש מלונדון וברלין. מחכמי זאגדמישל. נפטר בחיי אביו."},{"i":10040,"n":"ברלין, שבתי מסוחאואלי","f":"דוד","b":"רב בסוחאואלי(=סאחוואליע), הסכים-תרסה על \"חמדת ימים\" לר קלמן חיים מיטקס."},{"i":10041,"n":"ברלין, שלמה מפרנצלויא ולונדון","f":"צבי הירש ברלין","k":"שלמה הירשל","bt":"תקכד","dt":"תרג - כט חשון","b":"חתן משפחת קניגסברג. גיסו של הגביר ר ליב בר בער מליסא. עשיר,בעל אלפי ספרים והרבה כתבי יד, רב בפרנצלוי, רב בלונדון והמדינה-תקנב או תקסב על מקום ר דוד טבלי שיף בעל \"לשון זהב\". בניו: ר צבי הירש מירושלים, דוד טבלי מירושלים, ר שאול מזנדמישל - נפטר בחיי אביו,"},{"i":10042,"n":"ברלין-היילבוט, אליעזר לאזי","f":"יוסף בן לאזי הלברשטט","k":"בעל משנת רבי אליעזר","bt":"תקא-ז","bp":"ברלין","dt":"תקעד - א שבט","dp":"המבורג","b":"נכד ר אליעזר לאזי הלברשטט בן יהושע המקובל מברלין. תלמיד ר טבלי שייער ממיינץ בהיותו בבומברג, ר גדליה משוערזנץ. חתן הפרנס ר טודרוס מונק מפוזן. דיין בברלין?, פוזן אצל ר רפאל הכהן, גאטיין(=גוטיין)-מורביה, דיין ואח\"כ ראב\"ד באה\"ו על מקום ר רפאל הכהן. חתם בהמבורג-תקמט על החרם כנגד הספר \"מצפה יקותיאל\" - שפנה נגד ר רפאל הכהן מהמבורג, בימיו ניסו נפוליאון ואנשיו לפצל את שלש הקהלות. בניו: ר משה הו\"ל את ספרו \"משנת דרבי אליעזר\" אלטונא תקעה, ר מאיר פרייס מהילסהיים, ר יוסף לאזרוס מהמבורג, ר זוסמן מדובלין-אנגליה, נתן-פרופסור בדובלין, ר יצחק איזיק מהמבורג. חתנו - ר חיים בן יוסף מיכל מהמבורג (או ר יוסף מיכל עצמו), ר נחום מהמבורג."},{"i":10043,"n":"ברלין-פיק, ישעיה - הגרי\"פ","f":"אריה ליב מוכיח","k":"בעל הפלאה שבערכין","bt":"תעט","bp":"פרשבורג או איזנשטט","dt":"תקנט - ה-ח אייר","b":"נכד ר מרדכי מוכיח מפרשבורג. הגיע בילדותו עם אביו לברלין, תלמיד ר צבי הירש חריף בעל \"עטרת צבי\" מהלברשטט. חתן הגביר ר וולף פיק מברסלוי וישב אצלו - ומכאן שמו. סירב לרבנות ורק בגיל 75 הסכים לכהן כרב בברסלוי-תקנד ומדינת שלזיה על מקום ר יוסף תאומים. חתנו ר יוסף מאיי. חיבר הגהות על הש\"ס, \"שאילת שלום\", \"יש סדר למשנה\", \"הפלאה שבערכין\", ועוד. גיסו - ר יוסף שטינהרט בעל \"זכרון יוסף\"."},{"i":10044,"n":"ברלינגר, יעקב מברונסבך","f":"מנחם ברלינגר","bt":"תרכה","b":"תלמיד ר מיכאל הכהן מפולדא, בעל תואר ד\"ר. נכד ר הירש מברלינגן. רב בברונסבך(=ברויזשבאך)-גרמניה-תרנד על מקום אביו."},{"i":10045,"n":"ברלינגר, יעקב מברלינגן","b":"רב בברלינגן-תק\"ע"},{"i":10046,"n":"ברלינגר, מנחם מברונסבך","f":"צבי הירש ברלינגר","b":"רב בברונסבך-תרל, ובנו ר יעקב על מקומו אחריו."},{"i":10047,"n":"ברלינגר, צבי הירש מברלינגן","f":"יעקב","b":"רב בברלינגן-תרה"},{"i":10048,"n":"ברלינר, אברהם דוד טבל מברלין","f":"צבי הירש מברלין","bt":"תקצד","bp":"אברזייקא-פלך פוזנא","b":"תלמיד ר מיכאל שטרוק מלייפציג, בעל תואר ד\"ר. רב ומטיף בקהלת \"ישורון\" בארנסואלדע, מורה בביהמ\"ד לרבנים בברלין-תרלד. חיבר גם \"זכור לאברהם\", \"פליטת סופרים\", \"לקורות היהודים בפוזן\", ועוד."},{"i":10049,"n":"ברלינר, אברהם נתן מסמילא","f":"אלחנן ברלינר","b":"רב בסמילא"},{"i":10050,"n":"ברלינר, אלחנן מהורדדנא","k":"בעל התוספות","b":"חתן ר משלם זלמן מירלש מאה\"ו. רב בהורדנא. בנו - ר משה מרודניא ונכדו ר שמריה מהאלזמין."},{"i":10051,"n":"ברלינר, אריה ליב מברסלוי","f":"שאול","bt":"תקכה","dt":"תקעו - כז חשון","b":"רב בברסלוי-תק\"ס"},{"i":10052,"n":"ברלינר, יהודה","f":"יוסף"},{"i":10053,"n":"ברלינר, יעקב מרומנוב","f":"אברהם נתן","b":"רב ברומאנוב"},{"i":10054,"n":"ברלינר, יצחק נתן נטע מבילגוריא","f":"אברהם דוד טבלי","dt":"תרכד - ט אייר","dp":"בילגוריי","b":"מצאצאי החכם צבי. חתן ר אביגדור מייזלש מבילגוריי. דרשן, רב בגוריי, בילגורייא-תקעג על מקום חותנו כ-50 שנה. הניח חדושים ודרוש, מתורתו בשו\"ת \"נודע בשערים\"."},{"i":10055,"n":"ברלינר, משה","b":"חברו של ר יעקב צבי בעל \"הכתב והקבלה\" (תקמה-תרכה) ונזכר בספרו (שמות כג, טז)."},{"i":10056,"n":"ברלינר, משה מסעליש","f":"שרגא מרדכי","dp":"סעליש","b":"מצאצאי ר אריה ליבמ וכיח מפרשבורג. תלמיד הכת\"ס, ור שמואל שמעלקא קליין מסעליש. מחכמי סעליש. נטמן ליד ר ישראל ברוך אביו של בעל התניא."},{"i":10057,"n":"ברלינר, משה מרודני","f":"אלחנן ברלינר","k":"בעל תקנתא דמשה","b":"רב ברודניי-ת\"צ. בנו ר שמריהו הו\"ל את ספר אביו."},{"i":10058,"n":"ברלינר, נטע ירוחם מוארשא","k":"אושוויץ","bp":"תרנז","dt":"ראדזמין","dp":"תשד","b":"ממיסדי תנועת \"צא\"י\" (צעירי אגודת ישראל), וכותב הימנונה. מנהל הסמינר למחנכים בוארשא, ומנהל מוסדות \"בית יעקב\" בלודז."},{"i":10059,"n":"ברלינר, שמריהו מיאנוביץ","f":"משה מרודני","k":"בעל תקנתא דמשה","b":"אב\"ד יאנוביץ. הו\"ל מחדושי אביו בספרו \"תקנתא דמשה\" ובספר נוסף ספר מוסר ממנו, וגם \"שביל הישר\" לדודו החכם צבי. בניו: ר נתן טושקאווער, ר שלמה אב\"ד מיילאט-מחותנו של השאגת אריה, ר יעקב קאפיל מועליז, ר אהרן זליג מיאנוביץ, ר ישעיה אב\"ד יאנוביץ על מקום אביו ועלה לירושלים."},{"i":10060,"n":"ברלינרה","k":"בעל זכור לאברהם","bt":"תקצד","dt":"תרעה - ח אדר","b":"רב בארנסולד,רב וספרן בברלין"},{"i":10061,"n":"ברלנד, יצחק מניו יורק","k":"בעל תורת המדות","b":"חיבר \"אידישע עטיק\" - תורת המדות - יסודות היהדות על פי פרקי אבות - ניו יורק תש.."},{"i":10062,"n":"ברל\"ש, מאיר מקארניק ואמשטרדם","f":"משה קארניק מגלוגא","k":"בעל הדרי קודש","b":"משורר באמשטרדם, מחכמי גלוגא. חיבר גם \"עזרת הסופר\"."},{"i":10063,"n":"בר\"ם-ברא\"ם, מאיר מראווה","b":"תלמיד השו\"מ."},{"i":10064,"n":"בר\"ם-ברא\"ם, מרדכי מקורטשין","b":"רב בקורטשין - תשובה אליו בשו\"מ."},{"i":10065,"n":"ברמי, שלום מבטנא-אלג'יר","b":"רב בבטנא-אלג'יר-תשא, לצדו של ר ישועה לאלום."},{"i":10066,"n":"ברמן מלבוב","f":"מאיר ליוויש","b":"חתן ר יצחק שרנצלס מלבוב. מחכמי לבוב, חתנו - אחיו ר הירש המכונה ר הירש ר ברמאנס."},{"i":10067,"n":"ברמן מרדכי שלמה","r":"ראש ישיבת פוניבז'","bt":"1930","dt":"ה'תשסד 2004","bk":[["אשר לשלמה",""],["אשר לשלמה – מועד, נדרים, יבמות, סנהדרין, ב\"ק, שביעית ועניינים",""]]},{"i":10068,"n":"ברמן, אבא מרדכי","bt":"ה'תרעט","dt":"ה'תשסה","b":"פרסם מאמרים ב\"תלפיות\" - שנחאי תשו.","bk":[["עיון התלמוד",""]]},{"i":10069,"n":"ברמן, אברהם אביש מטורקא","dt":"תשב","dp":"חיפה","b":"גביר בטורקא. חסיד בויאן. עלה לחיפה-תרפה ועסק במסחר - פעל לחיזוק היהדות בעיר. יצא לביקור בטשרנוביץ אצל האדמור מבויאן."},{"i":10070,"n":"ברמן, אברהם יהושע מדרוהוביטש","f":"מרדכי זאב","b":"רב בדרוהוביטש-תריב על מקום אביו, בנו ר ליב על מקומו אחריו."},{"i":10071,"n":"ברמן, אברהם פנחס מזוונטשיק","f":"צבי דב","bt":"תרטו","b":"רב בזוונטשיק-פודוליה-תרנה."},{"i":10072,"n":"ברמן, אברהם צבי מבוצאץ","f":"שמואל הכהן","b":"רב בהוסיאטין, מחכמי בוצאץ. אחיו ר דודל חתן ר יונה ביק מברודי."},{"i":10073,"n":"ברמן, אהרן","f":"מרדכי","k":"בעל תולדות החנוך ביש","bt":"1895","bp":"לודז","b":"מחנך. תלמיד ישיבות טלז, וולוזין, פוניבז. ד\"ר לרפואה מגרמניה וציריך. מלמד בגימנסיה העברית בקובנה, מנהל-1925, עלה לארץ-1936, הקים את ביה\"ס התיכון החדש\" בתל אביב-1937. חיבר גם \"תורת החנוך וההוראה\" ועוד."},{"i":10074,"n":"ברמן, אליעזר יצחק מקרמנצוג ויר","k":"הגדול מקרמנצוג","b":"חתן ר אברהם מוולוזין. רב בקרמנצוג, עלה לירושלים ויסד שם ישיבה. גיסיו - ר שמחה זיסל, ר רפאל שלמה היימן, ר נחמיה מוצלאוו."},{"i":10075,"n":"ברמן, אפרים מארה\"ב","f":"אברהם דוד","k":"בעל נועם אפרים","bt":"תרנט","bp":"שצוצין-פלך לומזה","b":"נכד ר דוד יצחק ברמן מפיורדא. תלמיד ישיבות סלובודקה, נוברדוק, ר כתריאל אהרן נאטאן מאוסטוב בעל \"כתר המלך\", ונסמך ממנו ומאת: ר ברוך הורביץ מסלובודקה, ר יהושע מרדכי מדראסיין. חתן ר אברהם הלוי סוכן. היגר לארה\"ב וכיהן כרב קהלת \"אוהב שלום\" בפילדלפיא-תרפד ור\"מ בישיבה, קהלת \"בית אהרן בית שלום בניו יורק-תרמז. פרסם מאמר ב\"היהודי\" - נ\"י תרצו - לתולדותיו של ר ברוך הלוי הורביץ, \"כנסת ישראל\" - נ\"י תרצב - כתב עת הסתדרות תלמידי סלובודקה באמריקה."},{"i":10076,"n":"ברמן, אריה ליב מדרוהוביטש","dt":"תקסז","b":"רב ומקובל בדרוהוביטש. תלמיד ר חיים חייקל מהמדורא תלמיד הבעשט. מקורב לאדמורי דורו. חבוריו עלו באש בשרפת קומורנא-תקעא. בנו ר ישכר בר בעל \"חוט המשולש\" נפטר בצעירותו ור אריה גידל את נכדו מרדכי זאב."},{"i":10077,"n":"ברמן, דוד יצחק מפיורדא","b":"רב בפיורדא,אנסבך"},{"i":10078,"n":"ברמן, חיים הלוי מסנקוישאוקע","b":"רב בסענקויטשווקע. פרסם מאמרים ב\"העץ\" - לובלין תרצג."},{"i":10079,"n":"ברמן, יהודה ליב מדרוהוביטש","b":"נכד ר אברהם יהושע ור מרדכי זאב. רב בדרוהוביטש-תרעב על מקום אבותיו."},{"i":10080,"n":"ברמן, יהושע זבולון מפוסוואל","b":"חתן הגביר ר ישכר בר בן מאיר מפוסוואל. רב בפוסוואל."},{"i":10081,"n":"ברמן, יוסף אלימלך מויליפולי","b":"מחכמי ויליפולי. תשובה אליו ב\"מנחת יואל\"."},{"i":10082,"n":"ברמן, יוסף הלל מרוסטוב-דאן","f":"ישראל","bp":"וולוזין","dt":"תרפח","b":"נכד ר הלל פריד מהורדנא, ומצאצאי ר חיים מוולוזין. תלמיד ישיבת טלז. רב בפלונגיאן(=פאלאנגען)-קורלנד-תרמח עד תרנח, פרידריכשטט(=נאווארא)-קורלנד-תרנח, רוסטוב על הדון(=ראסטאוו-דאן)-תרסז. לחם נגד הריפורמה."},{"i":10083,"n":"ברמן, יעקב","f":"יחזקאל מאיר","k":"בעל תורת המדינה בישר","bt":"1878","bp":"סלנט","b":"תלמיד ישיבת טלז. למד משפטים בפטרבורג. ציר בועידה הציונית במינסק, ציר בועידת המזרחי בלידא ובה יזם את הקמת ישיבת לידא. ר\"מ בישיבה הגדולה באודסה. רב בברדיטשוב. עלה לארץ-תרפא, והיה מפקח על החנוך בזרם ה\"מזרחי\"-תרפט. מיסד מכון תורני פדגוגי לבוגרי ישיבות בירושלים וברחובות. פרסם מאמרים רבים בנושאי דת חינוך וציונות. פרסם מאמרים ב\"בית הכנסת\" - תל אביב תשו."},{"i":10084,"n":"ברמן, יצחק איזיק מגיזנקוביץ","b":"מחכמי גיזנקוביץ - תשובה אליו \"שושנים לדוד\"."},{"i":10085,"n":"ברמן, יצחק מירושלים","f":"אברהם","b":"מחכמי ירושלים, בשנת תקכג חתם על בקשת עזרה מקהילת מיץ."},{"i":10086,"n":"ברמן, ישכר מבודון","b":"רב בבודון-שנות ה-ת'."},{"i":10087,"n":"ברמן, ישראל פליסקוב","f":"אליהו","bt":"תרטז","b":"רב בפליסקוב-פלך קיוב-תרמג. נסמך מאת: ר שאול מחאטין, ר שאול לנדא מסאד\"ג. חתנו - ר משה בן ניסן מקאזאטין, ר חיים בן אלתר מליניץ."},{"i":10088,"n":"ברמן, מנחם מנדל יצחק מאנגליה","f":"משה אברהם","bp":"קארטינגא-פלך קובנא","dt":"תרפט - יט אד\"א","b":"נכד-אבי אמו ר צבי הירש האנעס מקעלעס. תלמיד ישיבת וולוזין, קיבוץ איישישוק. נסמך מאת: הנצי\"ב, ר רפאל שפירא. רב בגרימסבי-אנגליה-תרסד, גייטסהד, מידלסברו-תרסז, ר\"מ במנצסטר-תרעח."},{"i":10089,"n":"ברמן, מרדכי זאב מדרוהוביטש","f":"ישכר בר מדרוהוביטש","k":"בעל קול הרמ\"ז","bp":"דרוהוביטש","dt":"תרכג - כח תשרי","b":"נתייתם בילדותו וגדל אצל זקנו ר אריה ליב. רב בדרוהוביטש על מקום אבותיו. מתלמידיו קרוביו מהרי\"א איטינגא, ר נתן נטע מוערשילפקי. כשגר בקומורנא נשרפו הכתבים שברשותו. חיבר \"קול הרמ\"ז\" סעניק תרעב."},{"i":10090,"n":"ברמן, מרדכי שמואל גולנץ","b":"רב בברמן-ת\"ר,רב בהכנ\"ס בלונדון. בנו - ר חיים גולנץ מלונדון."},{"i":10091,"n":"ברמן, משה יהודה ליב מהורדלא","dt":"תשג","b":"רב בהורודולה(=הוראדלי). פרסם מאמרים ב\"קובץ דרושים\" - פיעטרקוב תרפג, \"מציון תצא תורה\" - זאמושט תרפט, \"העץ\" - לובלין תרצג."},{"i":10092,"n":"ברמן, משה מאנטיפליא","f":"שרגא פישל","bt":"תרכה","b":"רב באנטיפאליא-פלך גרודנא-תרנב."},{"i":10093,"n":"ברמן, משה מארה\"ב","bt":"תרמה","dt":"תרצב - כג חשון","b":"רב קהלת אגודת אחים בלוס אנג'לס-קליפורניה."},{"i":10094,"n":"ברמן, פסח הרץ מנעמעניץ","f":"בנימין","bt":"תרלא","b":"תלמיד ר אליעזר שמחה רבינוביץ מקלווריה(=קאלואריה), כולל קובנא. רב בנעמעניץ-פלך וילנא-תרנב. נסמך מאת: ר יצחק אלחנן מקובנא, ר אליעזר שמחה רבינוביץ מקאלואריא."},{"i":10095,"n":"ברמן, צבי מאויהל","b":"רב בדרצ'קא על מקום ר אליהו איזנשטטר ור שלמה סופר-בן הכת\"ס על מקומו אחריו, אויהל."},{"i":10096,"n":"ברמן, שלמה","b":"פרסם מאמרים ב\"כנסת הגדולה\" - וארשא תרן."},{"i":10097,"n":"ברמן, שלמה מבני ברק","b":"ר\"מ בישיבת פוניבז בבני ברק."},{"i":10098,"n":"ברמן, שמואל מקאוינאט","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":10099,"n":"ברמן, שמעון מטלז","k":"בעל אור בהיר","bt":"תרד","bp":"טלז","b":"תלמיד ביהמ\"ד לרבנים בוילנא. חוקר מקרא ופרשן. רב מטעם בטלז(=טעלשי). חיבר פירוש לספר ישעיהו."},{"i":10100,"n":"ברמסון, אברהם מארה\"ב","f":"חיים","b":"רב באומהא-נברסקה."},{"i":10101,"n":"ברמסון, משה מקובנא","f":"ברוך","b":"ממנהיגי הקהלה בקובנא. עסקן וחובב ציון. חבר משלחת של יהודי קובנא שקבלה את פניו של הרצל בוילנא."},{"i":10102,"n":"ברמסון, שמואל יעקב מראייגרד","f":"צבי","k":"בעל שמשא דשמואל","dp":"תרנט?","b":"מחכמי ראייגורד-פלך לומזה. חיבר גם \"ווים לעמודים\", והניח כתבים נוספים בכת\"י. חתנו - ר שמעון חיים גרייבסקי (בנו של ר אלעזר בעל \"גנת אגוז\")."},{"i":10103,"n":"ברמשנקה, אריה מקאניבלד","bp":"אוסטרייך","b":"רב בקניבלאד-פלך קיוב. בנו - ר מרדכי מקאליארקא."},{"i":10104,"n":"ברמשנקה, מאיר","f":"מרדכי ברמשנקה","b":"רב-שנת תר\"כ"},{"i":10105,"n":"ברמשנקה, מרדכי אריה מזועניגרדק","f":"מאיר בן מרדכי","bt":"תרטז","b":"נכד-אבי אביו ר מרדכי מקאליארקא, ונכד-אבי אמו ר אברהם דב מחמלניק. רב בסווניגרודקה(=זוועניגראדקא)-פלך קיוב-תרמד. נסמך מאת: הנצי\"ב, ר יצחק אלחנן מקובנא, ר משה נחום ירושלימסקי מקיעלץ, ר משה מרחמיסטריווקא. חתניו: ר בנציון מטשינישעצא-בסרביא, ר ירחמיאל מויניגראד-פלך קיוב. חיבר שו\"ת - בכת\"י. נזכר ב\"משיב דבר\" לנצי\"ב, ואצל ר משה נחום ירושלימסקי."},{"i":10106,"n":"ברמשנקה, מרדכי מקאליארקא","f":"אריה מקאניבלאד","b":"רב בקאליארקה-פלך קיוב. בנו - ר מאיר, ונכדו ר מרדכי אריה מזועניגרודקא."},{"i":10107,"n":"ברנבורג, משה","b":"תשובה אליו בשו\"מ."},{"i":10108,"n":"ברנבורג, פנחס","b":"תשובה אליו בשו\"מ."},{"i":10109,"n":"ברנד, אליעזר דוד מירושלים","b":"פרסם מאמרים ב\"שערי תורה\" - ירושלים תשה."},{"i":10110,"n":"ברנד, יוסף זאב מנדבורנה","f":"גרשון","k":"בעל דברי יוסף","bt":"תרה","bp":"יברוב","dt":"תרעה","b":"חסיד צורטקוב. חיבר \"דברי יוסף\" למברג תרעא."},{"i":10111,"n":"ברנד, צבי אריה מדולינה","f":"קלונימוס משה","k":"בעל ארשת צדיקים","bt":"תרם","dt":"תש","b":"מחכמי דולינא, חיבר \"ארשת צדיקים\" קראקא תרפה."},{"i":10112,"n":"ברנדוין - לנגנר, יצחק איזיק","f":"יהודה צבי מסטרטין","k":"אדמור מסטרטין","bt":"תרכה","dt":"תשז - כא תמוז","dp":"ארה\"ב","b":"רב ואדמור בסטרטין-תרסז על מקום אביו, בוברקא-תרע, ארה\"ב-תרף. חיבר פירוש לתהלים - בכת\"י."},{"i":10113,"n":"ברנדוין, אברהם","f":"יהודה צבי ברנדוין","bt":"תרכז","dt":"תרעה - כח תמוז","b":"רב בקניהיטש"},{"i":10114,"n":"ברנדוין, אברהם","f":"אהרן מפעלשטין","dt":"תרצט","dp":"צפת","b":"אדמור בצפת, ממונה בכולל גליציה. בנו - ר יהודה צבי מסטרטין-גיסו ותלמידו של בעל הסולם."},{"i":10115,"n":"ברנדוין, אברהם מסטרטין","f":"יהודה צבי","k":"אדמור מסטרטין","r":"האדמו\"ר מרדזין","bt":"תקסה","dt":"תרכה - ג טבת","b":"רב ואדמור בסטרטין על מקום אביו. תלמיד השרף מסטרליסק. מתורתו ב\"דגל מחנה יהודה\". חתנו ר פנחס ברנדוין-עלה לארץ.","bk":[["דגל מחנה יהודה",""]]},{"i":10116,"n":"ברנדוין, אברהם מסטרטין חיפה","f":"אורי מאוזופולי","k":"אדמור מסטרטין בחיפה","dt":"תשלג - כט טבת","b":"חתן ר יעקב שלמה מגורא-הומור (שושלת פרמישלן). אדמור בפיאטרה-ניאמץ, עלה לארץ והתישב בחיפה."},{"i":10117,"n":"ברנדוין, אהרן יעקב מניו יורק","f":"יחיאל מיכל מטורקא","k":"אדמור מסטרטין בנ\"י","bt":"תרצה","bp":"ניו יורק","b":"בנו של האדמור מסטרטין. אדמור מסטרטין אליק בניו יורק. חיבר \"טל אורות\" - מתורת ותולדות חסידות אליק - ניו יורק תשלה, \"מנהגי קודש לרבותינו מסטרטין\" ניו יורק תשסא."},{"i":10118,"n":"ברנדוין, אהרן מפלשטין וצפת","f":"צבי אריה לנדא-מאליק","k":"אדמור מאליק סטרטין","bt":"תרב","dt":"תרסז - כח כסלו","dp":"צפת","b":"משושלת אליק-סטרטין. חתן ר אברהם צבי מסטרטין וקרא לעצמו בשם חותנו - ברנדוין. גדל אצל דוד אמו - ר ישראל מרוזין - שהכתירו לאדמור ואף מסר לו \"קוויטל\" ו\"פדיון\". מחסידי רוזין והיה ישן שם בחדר עם ר דוד משה מצורטקוב. חתן ר אברהם מסטרטין. עלה לצפת-תרלג עם אביו ופתח בית מדרש \"ר ארהלס קלויז\". בניו - ר אהרן ברנדוין מפלטשין, ר יוסף דוד בצפת חתן רמ\"מ מגלוגוב, וחתנו ר פנחס דוד הורביץ מבוסטון."},{"i":10119,"n":"ברנדוין, אורי מאזיפולי","f":"אליעזר","k":"אדמור מאזיפולי סטניס","bt":"תרה","dt":"תרסה","b":"נכד ר יוסף וידרמן מבילקמין. רב ואדמור באזיפולי על מקום אביו, סטניסלב. חתן דודו ר בצלאל בן יוסלי וידרמן מבילקמין."},{"i":10120,"n":"ברנדוין, אליעזר מאזיפולי","f":"אורי","k":"אדמור מאזיפולי","bt":"תרל","dt":"תשב","b":"אדמור מאזיפולי ורב בסטניסלב על מקום אביו. נקרא בשם הקטן להבדילו מבן דודו שהיה גם הוא אדמור שם. נספה בשואה."},{"i":10121,"n":"ברנדוין, אליעזר מאזיפולי","f":"יהודה צבי","k":"אדמור מאזיפולי","bt":"תקס","dt":"תרכה - כ אב","dp":"סטרטין","b":"חתן ר יוסלה וידרמן מבילקמין. אדמור באזיפולי על מקום אביו לחלק מחסידי אביו ונוספו אליו חסידים רבים בהונגריה. אחיו הגדול ר אברהם אדמור מסטרטין."},{"i":10122,"n":"ברנדוין, אליעזר מבורשטין","f":"יוסף","k":"הו\"ל שארית יהודה","bt":"תרך","dt":"תרף","b":"מחכמי קניהניטש ובורשטין. הוציא לאור את ספרי סטרטין \"שארית יהודה\" ו\"דגל מחנה יהודה\". נפטר ללא ילדים."},{"i":10123,"n":"ברנדוין, אליעזר מבורשטין","f":"נחום - אמרי ברכה","k":"אדמור מבורשטין בסטני","bt":"תרכט","bp":"סטרטין","dt":"תשג - שבט","dp":"סטניסלב","b":"חתן האדמור ר שמואל שמקלא רובין מסערט. אדמור מבורשטין בסטניסלב על מקום אביו. נספה בשואה."},{"i":10124,"n":"ברנדוין, דב בריש מלמברג","k":"אדמור מסטרטין-למברג","b":"חתן ר מאיר יחיאל מרדיכוב. האדמור מסטרטין בלמברג, בנו ר יהודה הירש על מקומו אחריו."},{"i":10125,"n":"ברנדוין, דוד מבורשטין ניו יורק","f":"שלמה יעקב זידא מבורש","b":"בן האדמור מבורשטין בנ\"י. חתן ר משה אליקים בריעה כהנא מספניקא בני ברק. רב קהילת \"בית יעקב\" בורשטין בניו יורק."},{"i":10126,"n":"ברנדוין, חיים יוסף מירושלים","f":"יעקב מרדכי","dt":"תשנד","dp":"ירושלים","b":"חסיד בויאן."},{"i":10127,"n":"ברנדוין, חיים מנדבורנא","f":"שמואל זנויל מסטרטין","b":"נכד האדמור ר יהודה צבי מסטרטין. עלה לארץ."},{"i":10128,"n":"ברנדוין, יהודה צבי","f":"יצחק ברנדווין","dt":"תרסז","b":"אדמו\"ר בסטרטין"},{"i":10129,"n":"ברנדוין, יהודה צבי מסטרטין","f":"אברהם בן אהרן מפלטשי","k":"אדמור מסטרטין בת\"א","r":"האדמו\"ר מסטרטין","bt":"תרסג","bp":"צפת","dt":"תשכט - יח ניסן","dp":"ירושלים","b":"חתן ר שלמה וקסלר. נכד הצדיקים מליזנסק וברדיטשוב. תלמיד גיסו המקובל ר יהודה ליב אשלג בעל \"הסולם\". כיהן כאדמור מסטרטין בתל אביב וירושלים. חיבר \"מעלות הסולם\" על תקוני הזהר.","bk":[["מעלות הסולם – תיקוני זוהר",""]]},{"i":10130,"n":"ברנדוין, יהודה צבי מסטרטין","f":"שמואל זנויל מזואליב","k":"בעל שארית יהודה","bt":"תקם","dt":"תרד - יא אייר","b":"תלמיד ר אהרן ליב מפרמישלן ור אורי מסטרליסק. חתן ר אלעזר כהנא מרוזדול. רב בסטרטין על מקום חותנו. ואדמור אחרי רבו מסטרליסק. חיבר \"שארית יהודה\" למברג תרסט. מתורתו ב\"דגל מחנה יהודה\"."},{"i":10131,"n":"ברנדוין, יוסף דוד מסטרטין צפת","k":"אדמור מסטרטין","dt":"תשמט","dp":"ירושלים","b":"עלה לירושלים."},{"i":10132,"n":"ברנדוין, יוסף דוד מצפת","f":"אהרן מפלשטין וצפת","b":"בן האדמור מאליק-סטרטין. חתן רמ\"מ מגלוגוב, גיסו של ר פנחס דוד הורביץ מבוסטון. דיין בצפת."},{"i":10133,"n":"ברנדוין, יוסף מסאהל","f":"שמואל זנויל הנכד","bt":"תר","dt":"תרס - כט תמוז","b":"חתן ר אברהם משה אב\"ד סאהל. אב\"ד בסאהל-תר\"ל."},{"i":10134,"n":"ברנדוין, יוסף שמואל - מוריה","f":"נפתלי חיים מצפת","bt":"תרנו-ח","bp":"ירושלים","dt":"תשלד - כח ניסן","dp":"ירושלים","b":"למד בישיבת רידב\"ז בצפת. חתן דודו האדמור ר פנחס דוד הורביץ מבוסטון. היה אדמור סטרטין בפרובידנס - ארה\"ב. חזר לארץ בתשח והיה רב בעין כרם - ירושלים."},{"i":10135,"n":"ברנדוין, יחיאל מיכל מטורקא","f":"אהרן לנדא מפלטשין","k":"אדמור מטורקא סטרטין","bt":"תרלא","bp":"פלשטין","dt":"תרצט - כג אדר","b":"נקרא \"ברנדויין\" ע\"ש זקנו מצד אמו האדמור ר אברהם מסטרטין. מקורב לר דוד משה מצורטקוב שהכתירו כאדמור. עלה לצפת עם משפחתו. חתן ר אלתר אברהם יוסף הורביץ מטבריה. יצא לגליציה והתישב בטורקא והיה שם אדמור. בתרפו הגיע לארה\"ב, יסד קהלה בניו יורק-תרפו. מתורתו בספר בנו \"אור צדיקים\" לר אהרן יעקב נדפסו ב\"טל אורות\". חתנו ר דוד הלוי הורביץ אדמור מבוסטון."},{"i":10136,"n":"ברנדוין, יעקב מרדכי מירושלים","f":"ישראל מסטרטין","dt":"תשיד","b":"בן האדמו\"ר מסטרטין."},{"i":10137,"n":"ברנדוין, יצחק","f":"משה ברנדוויין","dt":"תשג","b":"רב בסטאניסלאב"},{"i":10138,"n":"ברנדוין, יצחק","b":"רב בטארקוב-תר\"ל"},{"i":10139,"n":"ברנדוין, יצחק איזיק מנחם מנ\"י","f":"שלמה יעקב זידא מבורש","b":"בן האדמור מבורשטין בנ\"י. חתן ר שמואל בן יהושע בוקסבוים מגלנטא. רב קהילת גלנטא-ניו יורק על מקום חותנו."},{"i":10140,"n":"ברנדוין, ישראל מברזאן","f":"פנחס","k":"אדמור סטרטין","bt":"תרלה","dt":"תשג","b":"אדמור סטרטין בברזן על מקום אביו. חתן ר חיים יוסף רבינוביץ. נספה בשואה. בנו - ר יעקב מרדכי."},{"i":10141,"n":"ברנדוין, מנחם מנדל מטבריה","f":"צבי אריה","bt":"תרף","bp":"טבריה","dt":"תשמט","b":"תלמיד ר משה קלירס. חתן ר דב רוזנשטין. מפרנסי טבריה."},{"i":10142,"n":"ברנדוין, מרדכי מנריוב","f":"אברהם","bt":"תפה","dt":"תקמה","b":"אב\"ד נריוב. בנו ר שמאל זנויל אב\"ד זוולוב."},{"i":10143,"n":"ברנדוין, משה יוסף","f":"זלמן הלל","dt":"תשנח","dp":"בני ברק"},{"i":10144,"n":"ברנדוין, משה מבורשטין","f":"אליעזר","k":"אדמור מבורשטין","bt":"תרן","dt":"תשג","b":"חתן ר שלמה מייער מסאסוב. התמנה אדמור בבורשטין-תרצה. נספה בשואה."},{"i":10145,"n":"ברנדוין, משלם זוסיא מירושלים","f":"נפתלי מצפת","bt":"תרס","bp":"מירון","dt":"תשכח","b":"מחכמי ירושלים."},{"i":10146,"n":"ברנדוין, נחום דוד משה מטורקא","f":"יחיאל מיכל מטורקא","k":"אדמור מסטרטין ב\"ב","dt":"תשמח - ח כסלו","dp":"בני ברק","b":"בן האדמור מטורקא-סטרטין."},{"i":10147,"n":"ברנדוין, נחום מבורשטין","f":"אליעזר","k":"אדמור מסטרטין-אמרי ח","bt":"תרז","bp":"סטרטין","dt":"תרעה - טו אלול","b":"נכד האדמור ר יהודה צבי מסטרטין. חתן ר צבי הירש הגר מפיטשניזין. אדמור בסטרטין על מקום אביו. רב ואדמור בבורשטין-תרל, עבר לסטניסלב-תרעד בגלל שריפה בחצירו. בנו ר אליעזר היה אדמור מבורשטין בסטניסלב על מקומו. חיבר \"אמרי טוב\" למברג תרנא, \"אמרי חיים\", ועוד."},{"i":10148,"n":"ברנדוין, פנחס מברזאן","f":"יעקב יוסף בן מרדכי","k":"אדמור מסטרטין בברזאן","bt":"תרו","dt":"תרעז - כז כסלו","dp":"ירושלים","b":"חתן ר אברהם האדמור מסטרטין. מקורב לאדמורי סדיגורא ובויאן. היה רב ואדמור בברזאן. עלה לירושלים-תרסב, בשליחות-תרעב."},{"i":10149,"n":"ברנדוין, שלמה יעקב זידא","f":"יצחק איזיק מנחם מפוד","k":"אדמור מבורשטין נ\"י","bt":"תרנט","bp":"בורשטיין","dt":"תשכד - ט חשון","b":"גדל אצל זקנו ר נחום ברנדוין מבורשטיין ושינה שמו משם אביו \"איכנשטין\" לשם זקנו ברנדוין. חתן ר טוביה משנדישוב, ובזיוו\"ש חתן ר אלעזר וינברגר מחוסט רב בפודהייץ-תרפד, היגר לארה\"ב-תרצו, כיהן כאדמור מבורשטיין. חיבר \"שמע יעקב\" בכתב יד. תולדותיו בספר \"צדיק מה פעל\" ירושלים תשס. בניו ר יצחק איזיק מנחם מגלנטא נ\"י, ר דוד."},{"i":10150,"n":"ברנדוין, שמואל זנויל מהרץ","f":"דוד אריה","b":"רב בהרץ-רומניה. השתתף ב\"קבוצי אפרים\"."},{"i":10151,"n":"ברנדוין, שמואל זנויל מזוולוב","f":"מרדכי","bt":"תקה","dt":"תקעה","b":"אב\"ד זוולוב. תלמיד המגיד ממזריטש."},{"i":10152,"n":"ברנדוין, שמואל זנויל מסטרטין","f":"יהודה צבי","k":"אדמור מסטרטין","bt":"תקעה","dt":"תרמז - ג אדר","b":"חתן הגביר ר דוד ליב מצאצאי ה\"מגלה עמוקות\". ר ישראל מרוזין הכתירו כאדמור, התגורר בסטרטין אך הרבה בנסיעות. מבניו: ר יוסף מסאהל, ר חיים מנדבורנא."},{"i":10153,"n":"ברנדוין, שמלקא","dt":"תשג","b":"רב בסטאניסלב"},{"i":10154,"n":"ברנדוין-לנדא, צבי אריה מפלטשין","f":"יוסף דוד לנדא מאליק","bt":"תקף","dt":"תרמד - כח תשרי","b":"חתן דודו ר יצחק יעקב מגראנוב (זלוטשוב). רב ואדמור בפלשטיין, שינה את שם משפחתו לברנדוין. עלה לארץ-תרמד. בנו - ר אהרן ברנדוין מפלטשין וצפת. (באוצר הרבנים תאריך פטירתו - תרכט)."},{"i":10155,"n":"ברנדון, בנימין רפאל דיאש מאמשט","k":"בעל אורות המצות","b":"ראש ישיבת \"נוה שלום\" באמשטרדם-תק. חיבר \"אורות המצות\" \"עמק בנימין\" - אמשטרדם תקיג."},{"i":10156,"n":"ברנדיל, ל' מפודוולוטשיסק","b":"מדפיס בפודוולוטשיסק, והדפיס כתב העת \"עטרת תפארת\"."},{"i":10157,"n":"ברנדיס, חיים דב","f":"רי\"מ","b":"מחכמי בוצאץ-תרלא, רב באיסטריק-תרעג."},{"i":10158,"n":"ברנדיס, משה מפרג","b":"חזן בפרג בזמן ה\"נודע ביהודה\" שקנס אותו לאחר שביזה את ר יונתן איבשיץ."},{"i":10159,"n":"ברנדלס, יוסף מאיר מאישציא","f":"שמריה שמרל ברנדלס","b":"רב באישציא,הרימלוב"},{"i":10160,"n":"ברנדמן, יחזקאל שרגא מרדומישל","b":"מחכמי רדומישל - מתורתו ב\"תל תלפיות\"-תרעח."},{"i":10161,"n":"ברנדס, גבריאל משה","dt":"תקה - כא כסלו","b":"עק\"ה,מרביץ תורה,רב בבומסלא"},{"i":10162,"n":"ברנדס, חיים דב מבאזיליא-רוסיה","dt":"תרפז","b":"חסיד סדיגורא. רב בבאזיליא-רוסיה - תרעא. מתלמידיו ר גדליה פלדר. בנו ר יוסף מתלמיד סמינר לרבנים בברלין."},{"i":10163,"n":"ברנדס, חיים סגל","b":"מגדולי חכמי םראג-שצ\"ה"},{"i":10164,"n":"ברנדס, יהודה הלוי מבומסלא","f":"בצלאל","k":"בעל לשון חכמים","b":"רב בבומסלא. חיבר \"לשון חכמים\" - פרג תקעה."},{"i":10165,"n":"ברנדס, יעקב הלוי מזאריק","f":"שמעון ברנדס","b":"רב בזאריק-ת\"כ"},{"i":10166,"n":"ברנדס, ישכר דב בר מקראקא","f":"שלמה דוד","k":"בריל רדומסקר-דברי יש","bt":"תרד","bp":"רדומסק","dt":"תרפב","b":"מחכמי קראקא, למד עם בעל \"תפארת שלמה\". חיבר \"דברי ישכר\" קראקא תרפד. פרסם מאמרים ב\"שערי תורה\" - קראקא תרפה."},{"i":10167,"n":"ברנדס, מרדכי","f":"אליעזר","k":"בעל זכרון מעשה לשים","b":"חיבר קונטרס בשנת תקיג, אודות המחלוקת בפפד\"מ בין סיעת קולפא לסיעת קן. קונטרס נוסף יצא באותה השנה \"זכרון תרועה להבין תקיעה\" - ממחבר לא ידוע."},{"i":10168,"n":"ברנדס, משה הלוי","f":"יעקב","k":"משה חריף","bp":"פרג","dt":"תקכז - כז סיון","b":"נכד המהר\"ל. תלמיד ר אברהם ברודא בפרג. חתן ר גבריאל לוי מפיורדא (השתדלן מפיורדא שהיה בעלה בזיוו\"ש של גליקל מהאמלין), ישב בקלויז שיסד חותנו בפיורדא ולימד שם תורה-תסא, רב בשנייטוך ומדינת אנשבאך-תעג,,בומסלא-בוהמיה-תעז על מקום חותנו של ר יונתן איבשיץ (ר יצחק שפירא?), מנגנצא-תצג."},{"i":10169,"n":"ברנדס, שמעון הלוי מפרג","k":"חתן המהר\"ל מפרג","b":"ראש ומנהיג בפרג-ש\"ע"},{"i":10170,"n":"ברנדס, שמעון הלוי מפרג","f":"שמואל הלוי","b":"מגדולי פרג-ת\"י"},{"i":10171,"n":"ברנדסדורפר, יהודה טרייטל","f":"יהודה טרייטל","k":"בעל שבט יהודה","bt":"תרסז","dt":"תשנה","b":"תלמיד חותנו רש\"י טייכטל מפישטיאן. עבר לאנטורפן ועסק ביהלומים. ניצל מהשואה. עלה לירושלים והתקרב לאדמור מתולדות אהרן. בנו - ר מאיר בעל \"קנה בושם\". חיבר \"שבט יהודה\" ירושלים תשנט."},{"i":10172,"n":"ברנדסדורפר, יחזקאל שרגא מקשנוב","f":"יהושע","dt":"תשמה","b":"למד בישיבת בובוב. עלה לירושלים-תרצו. חתן ר בצלאל לייזר מישליסק. מגיד שיעור בשכונת זכרון משה בירושלים. חיצר \"אוצר פתגמים ושיחות\" - ירושלים תשלג."},{"i":10173,"n":"ברנדסדורפר, יצחק מצאנז","f":"אליה"},{"i":10174,"n":"ברנדסורפר, שלמה מירושלים","b":"אחיו - ר מאיר ברנדסורפר-דיין בירושלים."},{"i":10175,"n":"ברנדר, אלישע מבייטש","b":"בא מגורליץ לכהן כדיין בבייטש לבקשת ר מרדכי וגשל, תשובות אליו ב\"אהל יהושע\" ועוד."},{"i":10176,"n":"ברנדר, יעקב יהושע מדוברומיל","bp":"ריבטיטש","b":"עבר לדוברומיל ונעשה חסיד. מקורב לבלז ולבלוזוב."},{"i":10177,"n":"ברנדר, מאיר מבוריסלב","b":"רב בבוריסלב בין שתי המלחמות."},{"i":10178,"n":"ברנדר, שלום מירוסלב","f":"דוד הכהן","k":"בעל חוקת היום","bt":"תרעב","dt":"תשס - יז כסלו","b":"חסיד בלז. ניצל מהשואה וגלה לסיביר (נעשה לו נס כאשר חצב בקרח לטבילה ואיבד את הפתח לצאת), חזר לפולין. חתן ר פנחס אנגלנדר. עבר לפריס ולבלגיה. עלה לירושלים-תשיא וכיהן כראש ישיבת בלז בירושלים ואחר כך בבני ברק. חיבר \"חוקת היום\" בני ברק תשמט."},{"i":10179,"n":"ברנדריס, יוסף מאיר מאוסיצא","f":"שמריה שמריל מאוסציא","bt":"תקס","dt":"תרכד","b":"אב\"ד אוסציא, הרימלוב על מקום אביו (שעלה לארץ)."},{"i":10180,"n":"ברנדריס, שמריה שמרל מהרימלוב","f":"יעקב","k":"בעל ראש פינה","dt":"תריז - כב טבת","b":"תלמיד ר אפרים זלמן מרגליות מברודי. רב בהרימלוב, עלה לירושלים. חיבר \"ראש פינה\", \"קהלות יעקב\". נזכר אצל ר שלמה קלוגר בספריו. בנו - ר יוסף מאיר מאיציא והרימלוב."},{"i":10181,"n":"ברנהולץ, חיים מלופטין","f":"אברהם","bt":"תרל","bp":"לופטין","dt":"תשג","b":"תלמיד זקנו האב\"ד ר משה יהודה. היה מיועד לרבנות על מקום חותנו אך פנה למסחר. נספה בשואה."},{"i":10182,"n":"ברנהולץ, משה יהודה מלופטין","bt":"תקעה","dt":"תרנח","b":"חתן ר חיים דיסטנפלד מלופטין. רב בלופטין בהמלצת האדמור מבלז. החליף שו\"ת עם המהרש\"ם והמהרש\"ק. היה מחלוקת עם הרב לשצובר שנתמנה ע\"י חסידי הוסיאטין."},{"i":10183,"n":"ברנהרד, יעקב יצחק","f":"ד\"ר חיים דוד מפיעטרק","b":"חסיד ואלברוזש."},{"i":10184,"n":"ברנהרד, יצחק מפאפא","b":"רבה הראשון של פאפא."},{"i":10185,"n":"ברנוביץ, ליב","b":"ניצל מהשואה והגיע לשנחאי-סין. פרסם מאמרים ב\"מאור תורה\" - שנחאי-סין תשד - קובץ תלמידי ישיבת מיר בשנחאי, \"התבונה\" - נ\"י תשז - קובץ תלמידי ישיבת מיר."},{"i":10186,"n":"ברנזון, צבי הירש","b":"דיין בטרנופול-תקסח. תשובה אליו ב\"ספר יהושע\"."},{"i":10187,"n":"ברנזון-ביאלר, שמואל","dt":"תרטז - כא אד\"א","b":"דומ\"צ בוורשה-תקצ\"ח"},{"i":10188,"n":"ברנט, אברהם נתן","f":"ישראל","k":"בעל גדולת הבעשט","bt":"תרע","bp":"מארגרטן","b":"תלמיד ר יהודה רוזנר בסעקעיהיד, ור יואל טיטלבוים בקרולה. מחכמי שאמלוי. ניצל מהשואה וחזר לשאמלוי.עלה לארץ-תשטז. חיבר גם \"קול אליהו\" שאמלויא תשח, ועוד."},{"i":10189,"n":"ברנט, גרשון","b":"פרסם מאמרים ב\"כנסת ישראל\" - וילנא תרץ."},{"i":10190,"n":"ברנט, זרח מליטא וירושלים","f":"נחום","k":"בעל זכרונות ר זרח בר","bt":"1843","bp":"ציטוביאן","dt":"1935","dp":"תל אביב - ירושלים","b":"תלמיד ישיבות ליטא. היגר ללונדון, חתן ר יצחק הכהן מלונדון, הקים תעשיית פרוות בלונדון וארגן את יהודי מזרח אירופה, עלה לירושלים ואיבד את רכושו, חזר ללונדון ועלה שוב כך פעמיים. גואל אדמות וממיסדי פתח תקוה. חזר ללונדון ומשם המשיך בפעולותיו למען הישוב בארץ. נפגש אצל הברון רוטשילד לצורך עזרה לפתח תקוה. עלה לארץ פעם רביעית ובנה ביתו בפתח תקוה. במהלך השנים נסע 15 פעמים ללונדון בעניני עסקיו. בנה בתל אביב ביהכ\"נ \"שונה הלכות\", את ישיבת \"אור זורח\". חיבר זכרונות ונדפסו בירושלים."},{"i":10191,"n":"ברנייס, יצחק מהמבורג","f":"יעקב","bt":"תקנב","bp":"גערא-ליד מיינץ","dt":"תרט - ט אייר","dp":"המבורג","b":"תלמיד ישיבת ר אברהם בינג בוירצבורג, תלמיד חבר לר יעקב עטלינגר. גדול במדע בנאום ובדרוש (למד באוניברסיטת וירצבורג), רב בהמבורג-תקפא על מקום ר ברוך עוזר, פרסם מאמרים בעילום שמו ב\"דער ביכלישע אריענט\". מתלמידיו: ר שמשון רפאל הירש, ד\"ר שמשון נאטאן, ר מיכאל גוטליב מהמבורג, ועוד. בניו: יעקב-פרופ' בבון, ברמן מהמבורג ווינה, מיכאל-פרופ' במינכן, יהודה מהמבורג, חתניו - זלמן היינע, לעוו בר ממהרין."},{"i":10192,"n":"ברניץ, מנחם מסענעץ","b":"פרסם מאמר ב\"המעין\" - בודפשט תשז (לאחר השואה!)."},{"i":10193,"n":"ברנס, מרדכי מטריפולי","k":"ישראל","bt":"תרעז","bp":"טריפולי","dp":"תשנד - יד ניסן","b":"תלמיד ר יצחק חואתו לוזון, ור יוסף חיים זארוק מטריפולי. רב בטריפולי. עלה לארץ והתישב בפרדס חנה."},{"i":10194,"n":"ברנפלד שמעון","bt":"1860","dt":"ה'תש 1940","bk":[["חיי אנשי השם – גבריאל ריסר",""]]},{"i":10195,"n":"ברנפלד, אריה ליב מזלישטשיק","f":"שמעון מטיסמניץ","bt":"תרב","bp":"סניאטין","dt":"תרפט - ו אייר","b":"חתן ר נחום מרגושס מזלישטשיק. רב בסניאטין-תרלג, קוצן(=קאטצמאן), ויזניציא, זלישטשיק. נחשב לזקן רבני גליציה."},{"i":10196,"n":"ברנפלד, יונה צבי מדברצין","f":"יוסף מטאפלטשן","k":"בעל דרשות ר יונה צבי","bt":"תקצד","bp":"טאפלטשן","dt":"תרנא - כז חשון","dp":"דברצין","b":"תלמיד הכת\"ס, ור שלמה דייטש מנייטרא. עמד להתחתן עם אסתר - בתו היתומה של החת\"ס - ונפטרה לפני החתונה. חתן ר דוד יהודה ליב דיאמנט מפריישטט ועבר לשם. רב באירשא-תריד, דברצין-תרלב."},{"i":10197,"n":"ברנפלד, יוסף מטפלטשאן","f":"יעקב","bp":"בסקביץ","b":"תלמיד החת\"ס, ור שמואל קעלין מבסקביץ בעל מחצית השקל. עזב את עירו ועבר לטאפאלטשאן (בגלל גזירת המלכות שרק הגדול בבית יכול להנשא)."},{"i":10198,"n":"ברנפלד, יעקב מקראקא","b":"פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח."},{"i":10199,"n":"ברנפלד, יצחק","f":"יונה צבי מדברצין","b":"תלמיד הכת\"ס."},{"i":10200,"n":"ברנפלד, יצחק צבי מגענף","f":"שמואל יהודה מטאפלטשן","k":"בעל סופר המלך","r":"אב\"ד חוג חת\"ס","bt":"תרעז","bp":"טאפלטשאן","dt":"תשנח - יז תמוז","dp":"ירושלים","b":"תלמיד הדעת סופר, ודודו ר מאיר יהודה ליב פרייא משוראן, ור דוד ועסלי מפרשבורג ועוד. חתן ר שמעון זאב שנקר מירושלים. עלה לירושלים וכיהן כרב שכונת פאג\"י. רב במלבורן-תשיז, סידני, ברוקלין, גענף (שוויץ), בני ברק-תשלא - רב של חוג חתם סופר. פרסם מאמרים ב\"עטרת צבי\" - ירושלים תשא.","bk":[["סופר המלך - שו\"ת על הרמב\"ם",""],["ריצבש\"י - חידושים על הש\"ס בשיטת הרמב\"ם",""],["ריצבש\"י - חידושים על הש\"ס בשיטת הרמב\"ם, סופר המלך - שו\"ת על הרמב\"ם",""]]},{"i":10201,"n":"ברנפלד, צבי הירש","dt":"תרעה - י טבת","b":"רב בנימוזשא"},{"i":10202,"n":"ברנפלד, שמואל יהודה מטאפלטשאן","b":"נכד ר יוסף ברנפלד מטאפלטשאן. חתן ר יצחק צבי פרייא מסערדאוהל - חתן הכת\"ס."},{"i":10203,"n":"ברנפלד, שמעון מבלגרד","f":"משה","k":"בעל אברהם ן עזרא","bt":"תריב","bp":"סטניסלב","b":"תלמיד חכם ובקי בספרות ישראל, עורך עתון בקניגסברג, עבר לברסלוי, ליק - והיה עוזר בעריכת \"המגיד\" לגורדון, תלמיד ביהמ\"ד לרבנים בברלין ובעל תואר ד\"ר. רב קהילת הספרדים בבלגרד-תרמו. פרסם מאמרים בעתוני התקופה."},{"i":10204,"n":"ברנצ'יק, יואל","bt":"תרלו","dt":"תשג","b":"מגדולי מרביצי תורה ר\"מ בריגא"},{"i":10205,"n":"ברנצקי-שץ, מאיר יונה מסויסלוב","f":"שמואל זלמן","k":"בעל הר המוריה","bt":"תקעז","bp":"סוחובולי-פלך גרודנא","dt":"תרנא","b":"רב בפורוזובה, קנישין, סויסלוביץ(=סיסלאוויטש, סויסלאץ), בריסק על מקום ר יהושע ליב דיסקין ור יוסף דב סולוביציק על מקומו אחריו, סויסלוביץ(=סבילוביץ)-תריז. חיבר גם \"מי השלח\", \"שער החדש\", ועוד. רבים מכתביו אבדו בשריפה בסוויסלוביץ. לתולדותיו ב\"מתיבות\" ירושלים תרצד."},{"i":10206,"n":"ברנקופ, ליבוש","f":"גימפל","b":"דיין ברדומישל אצל ר חיים אנגל."},{"i":10207,"n":"ברנר, אברהם מנדבורנה","b":"מחכמי נדבורנה - תשובה אליו בשו\"מ."},{"i":10208,"n":"ברנר, איתמר מסטניסלב","b":"תשובה אליו לסטניסלב - \"בית דוד\", לסטריזוב - תרסט."},{"i":10209,"n":"ברנר, אלישע אהרן מרוהטין","b":"רב ברוהטין, בנו ר יהושע על מקומו אחריו."},{"i":10210,"n":"ברנר, אפרים אלישע","b":"מופיע בשם הגדולים השלישי."},{"i":10211,"n":"ברנר, דב בריל מסלטוינה","f":"יעקב","bt":"תר","dt":"תרע","b":"דיין בסלטוינה על מקום חותנו, קרמניץ, טשרנוביץ."},{"i":10212,"n":"ברנר, דוב","bt":"תריא","dt":"תרפד - יז אד\"א","b":"דיין בטשערנוביץ"},{"i":10213,"n":"ברנר, יהושע מרוהטין","f":"אלישע אהרן","b":"רב ברוהטין על מקום אביו. תשובה אליו - \"בית שלמה\"-תריא."},{"i":10214,"n":"ברנר, יעקב מנדבורנה","f":"אפרים אלישע","bt":"תקע","dt":"תרם","b":"חתן ר חיים וגנר אב\"ד שאץ. דיין בנדברונה, ראב\"ד טשרנוביץ-תרכה, ובנו ר דב ישב אחריו על כסאו. (זקנו של הסופר יוסף חיים)."},{"i":10215,"n":"ברנר, יעקב קופל מרזפניק","f":"זאב וולף","bp":"סטניסלב","b":"רב ברזפניק, הלמין-הונגריה. חתן ר יצחק הלברשטם מקראקא, בזיוו\"ש חתן ר לייביש שפילברג מאודסה."},{"i":10216,"n":"ברנר, יצחק סגל","b":"פרסם מאמרים ב\"מגד ירחים\" - סיגט תרנח."},{"i":10217,"n":"ברנר, ישראל מקששוביץ","b":"תשובה אליו - \"יד שלום\"."},{"i":10218,"n":"ברנר, ישראל נחום מארה\"ב","k":"בעל נחמות ישראל","b":"רב בארה\"ב-תרסב."},{"i":10219,"n":"ברנר, מנחם מנדל מסניאטין","b":"רב בסניאטין-תרסה. בנו - ר שמעון מארה\"ב."},{"i":10220,"n":"ברנר, קופל","b":"אב\"ד רופניק, רב בסטניסלב-תרמט."},{"i":10221,"n":"ברנר, שאול","b":"תשובה אליו - \"חזון נחום\"-תרצו."},{"i":10222,"n":"ברנר, שמעון מארה\"ב","f":"מנחם מנדל מסניאטין","bt":"תרסה","bp":"סניאטין-פולין","b":"תלמיד ישיבות ירושלים - \"מאה שערים\", \"עץ חיים\". נסמך מאת ר איסר זלמן מלצר, רי\"מ חרל\"פ, רי\"מ הורביץ. חתן ר מנחם מנדל פרוש מירושלים (ראש השובי\"ם). היגר לארה\"ב וכיהן כרב קהלת \"בית ישראל\" בניו יורק-תרצא. חבר אגודת הרבנים באמריקה, ותנועת המזרחי."},{"i":10223,"n":"ברנרטה, חיים מרדכי מצ'כנוב","b":"פרסם מאמרים ב\"בית המדרש החדש\" - גריבה תרפח."},{"i":10224,"n":"ברנשטיין, אהרן מברלין","k":"בעל פאלקס צייטונג","bt":"1812","bp":"דנציג","dt":"תרמה - יח שבט","dp":"ברלין","b":"עבר לברלין. חיבר ספרים מאמרים ושירים בלשון אשכנז. היה מקורב לריפורמים אך היה במחלוקת עם הקיצונים כהאלדהיים."},{"i":10225,"n":"ברנשטין יהודה דוד","bt":"1863","dt":"ה'תש 1940","bk":[["הלכתא רבתא לשבתא",""]]},{"i":10226,"n":"ברנשטין שמעון גרשון","bt":"1884","dt":"ה'תשכב 1962","bk":[["ספר יובל לכבוד שמואל קלמן מירסקי",""]]},{"i":10227,"n":"ברנשטין, אברהם זאב מליניץ","f":"יצחק מליניץ","bt":"תרלב","bp":"ליניץ-פלך קיוב","b":"נכד ר חיים גדליהו מליניץ. רב בליניץ-תרנז-ח על מקום אביו וזקניו, חרסון-תרסד, אנאניוו-תרסח. נסמך מאת: ר אהרן מטשודנוב, ר פנחס, ר מאיר מרגלית מברדיטשוב, ר ניסן רבלסקי מקוזומין."},{"i":10228,"n":"ברנשטין, אברהם מאלכסנדר","b":"ממנהלי כתב העת \"בית אברהם\" - וארשא תרצד."},{"i":10229,"n":"ברנשטין, אברהם מפשמישל","b":"מחכמי פשמישל, ראווה. תשובה אליו \"בית יצחק\"-תרלב."},{"i":10230,"n":"ברנשטין, אברהם משה מוילנא","bt":"1865","bp":"שאצק","dt":"1933","dp":"וילנא","b":"משורר אצל החזן רבינוביץ בקובנא. חזן ראשי בביהכ\"נ הכוראלי \"טהרת הקדש\" בוילנא כ-30 שנה.חיבר למעלה מ-200 קומפוזיציות לשירי ילדים בעברית ובאידיש. פרסם מאמרים על חזנות ומוסיקה יהודית."},{"i":10231,"n":"ברנשטין, אהרן מירושלים","f":"ירוחם פישל יהושע","bt":"תרעח","bp":"ירושלים","dt":"תשנה","dp":"ירושלים","b":"תלמיד בישיבת אביו. חתן ר יצחק מאיר הגר מסטנוביץ. ר\"מ בישיבת חיי עולם וחבר בד\"צ אגו\"י ומועצת גדולי התורה. בנו ר יצחק מאיר מניו יורק הו\"ל \"פרי אהרן\" - ניו יורק תשנו."},{"i":10232,"n":"ברנשטין, איזיק מזלוטשוב","b":"רב בזלוטשוב. מובא ב\"שבעה עינים\", וקונטרס תיקון העולם\"."},{"i":10233,"n":"ברנשטין, אליהו נחום וואלוויש","dt":"תרצג - ח תמוז","b":"פרסם מאמרים ב\"בית אברהם\" - וארשא תרצד (נדפס אחר פטירתו)."},{"i":10234,"n":"ברנשטין, אריה ליבוש מברוד","f":"ישכר בריש יצחק","bt":"תץ","dt":"תקמט - כא תשרי","b":"אביו שינה שמו מרבינוביץ באבד לברנשטין. חתן ר צבי הירש מזמושץ אב\"ד ברודי. רב בזברז, בשנת תקלח נתמנה כרב המדינה בגליציה וישב בברודי-תקלח לאחר שהנודע ביהודה סירב לעזוב את פרג לצורך המינוי. (המשרה בטלה בתקמו)."},{"i":10235,"n":"ברנשטין, אריה ליבוש מלבוב","f":"יחיאל מיכל","bt":"תקם","dt":"תרג","b":"מחכמי למברג, הניח פירוש גדול על המסורה - בכתב יד."},{"i":10236,"n":"ברנשטין, באלא מנירג-האזה","dt":"תשד","b":"רב הקהילה הניאולוגית בשטיינמנגר-1892, נירג-האנה. חוקר תולדות היהודים בהונגריה. חיבר \"רבנו בחיי בן אשר\" - בהונגרית, ספר על השתתפות היהודים במלחמת השחרור ההונגרית. תרגם פרשות בתורה וההפטרות. נספה בשואה."},{"i":10237,"n":"ברנשטין, בנימין יהודה ליב מירו","f":"ירוחם פישל אוירבך","bt":"תקצט או תרה","bp":"צפת","dt":"תרסה - ב שבט","b":"בן ר ירוחם מאומאן וצפת, ונכד ר יוסף יהודה ליב מבאלטא-תלמיד המגיד ממזריטש. נולד בברכת ר משה צבי מסאווראן. חתן ר יצחק דוד בידרמן מללוב. ראש הישיבה החסידית הראשונה בירושלים - \"חיי עולם\". בשליחות באירופה. בנו ר בצלאל ישעיה מירושלים. מתולדותיו ב\"צבי לצדיק - סאווראן\"."},{"i":10238,"n":"ברנשטין, בנימין משה","b":"ניצל מהשואה והגיע לשנחאי-סין. פרסם מאמרים ב\"מאור תורה\" - שנחאי-סין תשד - קובץ תלמידי ישיבת מיר בשנחאי."},{"i":10239,"n":"ברנשטין, בצלאל ישעיה מירושלים","f":"בנימין יהודה ליב","bp":"ירושלים","b":"חתן ר ירוחם ליפשיץ-טיטלבים מטורנא."},{"i":10240,"n":"ברנשטין, דב הכהן מלנצקורניא","f":"צבי","bt":"תרכה","b":"רב בלנצקרוניא(=לאנצקרוניא)-פודוליה-תרנב. פרסם מאמרים ב\"אסיפת חכמים\" - אטוניא-בויאן תרע-תרעד."},{"i":10241,"n":"ברנשטין, הרמן מליטא וארה\"ב","bt":"1876","bp":"ניישטט שאקי","dt":"1935","dp":"שפילד-מסצוסטס","b":"עתונאי ודיפלומט. היגר לארה\"ב, והיה עתונאי בחו\"ל. מייסד ה\"טאג\". חקר את הפרעות ביהודי פולין-1919. ייצג את הג'וינט ביפו. תבע לדין את הנרי פורד על מאמר אנטישמי ואילצו להתנצל בפומבי. חשף את הזיוף של \"הפרוטוקולים של זקני ציון\". שגריר ארה\"ב באלבניה. חיבר מאמרים רבים וכמה ספרים באנגלית."},{"i":10242,"n":"ברנשטין, חיים גדליה מליניץ","f":"יהודה ליב מליניץ","dt":"תרמ","b":"נכד ר דובער מליניץ בעל \"שבחי הבעש\"ט\". רב בליניץ-תקצה על מקום אביו כ-45 שנה, ובנו ר יצחק על מקומו אחריו."},{"i":10243,"n":"ברנשטין, חיים חייקל ממינסק","f":"נחום","dt":"תרן - ג ניסן","dp":"מינסק","b":"מחכמי מינסק-בזמן ה'גדול ממינסק'."},{"i":10244,"n":"ברנשטין, יהודה דוד (דב) מנ\"י","f":"נתן","k":"בעל הלכתא רבתא לשבתא","bt":"תרכג","bp":"אלקסוט-ליטא","b":"תלמיד ישיבת סלובודקה ונודע בכינוי \"העילוי מספיזישוק\". היגר לארה\"ב-תרנג כיהן כרב בניו יורק והקים את ישיבת ר' יצחק אלחנן בניו יורק-תרנג. פרסם חדושי תורה בעתונות התורנית. פרסם מאמרים ב\"בית ועד לחכמים\" - נ\"י תרסג, \"המאסף\" - ירושלים-אלכסנדריה תרנו-תרעג. בקי בחכמת ההנדסה."},{"i":10245,"n":"ברנשטין, יהודה ליב מבירז","bt":"תרמז","dt":"תשא - תמוז","b":"רב בבירז וראש הישיבה על מקום ר בנימין מובשה. נספה בשואה."},{"i":10246,"n":"ברנשטין, יהודה ליב מליניץ","f":"דוב בער מליניץ","dt":"תקצד - בערך","b":"רב בליניץ-תקן, ובנו ר חיים גדליה על מקומו אחריו."},{"i":10247,"n":"ברנשטין, יוסף יהודה מפילטען","dt":"באלבירשוק","b":"רב ברודמינע, רעגאווע,לוקניק, פילעטין-תריט -32 שנה, באלאבירשוק."},{"i":10248,"n":"ברנשטין, יחזקאל מקובנא","k":"בעל דברי יחזקאל","dt":"תשג","dp":"קובנא","b":"מרביץ תורה בקובנא, ראש ישיבת \"אור ישראל\" בסלובודקה - מתלמידיו שם גם הרב אליעזר מנחם שך. פרסם מאמרים ב\"בית ישראל\" - קובנא תרפב. נספה בשואה (בפורט השביעי בקובנא)."},{"i":10249,"n":"ברנשטין, יעקב יצחק הלוי","b":"שו\"ב, נסמך-תרעג בידי ר יהודה גולדשטין מסאבינוב."},{"i":10250,"n":"ברנשטין, יעקב מברודי","f":"אריה ליב ברנשטיין","dt":"תקע - כו שבט","b":"רב בברודי"},{"i":10251,"n":"ברנשטין, יעקב נפתלי הרץ","f":"אריה ליבוש","bt":"תקעד","bp":"למברג","dt":"תרלג - ה שבט","dp":"לבוב","b":"מצאצאי ה\"פני יהושע\". מנהיג החרדים בלבוב. הניח ספרים רבים בכתב יד."},{"i":10252,"n":"ברנשטין, יצחק מליניץ","f":"חיים גדליה מליניץ","dt":"תרנח","b":"נכד ר יהודה ליב מליניץ. רב בליניץ-תרם על מקום אביו וזקנו, ובנו ר אברהם זאב על מקומו אחריו."},{"i":10253,"n":"ברנשטין, יצחק מנחם משדליץ","b":"רב בשדליץ. פרסם מאמרים ב\"בית אברהם\" - וארשא תרצד."},{"i":10254,"n":"ברנשטין, יצחק פישל","b":"פרסם מאמרים ב\"תצא תורה\" - קריניצה תרצא."},{"i":10255,"n":"ברנשטין, ירוחם מירושלים","f":"יצחק דוד","bt":"תרעד","bp":"ירושלים","dt":"תשנג","b":"חבר הנהלת \"חיי עולם\"."},{"i":10256,"n":"ברנשטין, ירוחם פישל יהושע","f":"בצלאל ישעיה","k":"בעל תורת ירוחם","r":"ראב\"ד חסידים ירושלם וראש ישיבת חיי עולם","bt":"תרם","dt":"תשט","b":"ראש ישיבת \"חיי עולם\" וראב\"ד לחסידים בירושלים. מצאצאי אדמורי ללוב וחסיד ללוב. חיבר \"תורת ירוחם\" בתוך ספר בנו \"פרי אהרן\". פרסם מאמרים ב\"קול תורה\" - ירושלים תרץ.","bk":[["תורת ירוחם (ר' פישל דיין. נד' עם פרי אהרן)",""],["תורת ירוחם",""]]},{"i":10257,"n":"ברנשטין, ישכר בריש מאמשטרדם","f":"שמואל מאמשטרדם","bt":"תקסח","dt":"תרנד - ח טבת","b":"נכד ר ישכר בריש מהנובר, ומצאצאי ה\"פני יהושע\". דיין באמשטרדם, רב בהאג-תרח. הניח חיבורים רבים בכת\"י."},{"i":10258,"n":"ברנשטין, ישכר דב מהנובר","f":"אריה ליב בן הפני יהו","bt":"תקז","bp":"פפד\"מ","dt":"תקסח-ג - ל חשון","dp":"הנובר","b":"נכד הפני יהושע. חתן ר יצחק הורביץ (10595). גדול בחכמה ומדע, מקורב למלכות, רב בהנובר והמדינה-תקמט על מקום אביו. בניו: ר שמואל ברנשטין (19067), ר נתן לוינשטין (16331). חתנו - ר יצחק אליהו (11257)"},{"i":10259,"n":"ברנשטין, ישראל יעקב מירושלים","b":"מראשי בית היתומים דיסקין בירושלים-תרסח."},{"i":10260,"n":"ברנשטין, ישראל מלבוב","f":"מרדכי","bt":"תקם","dt":"תרג","b":"מחכמי למברג. חיבר בכתב יד \"ישראל נושע\". הדפיס בזולקווא \"תבואות שור\"."},{"i":10261,"n":"ברנשטין, לייב","dt":"תשג","b":"רב בבירזש"},{"i":10262,"n":"ברנשטין, מאיר מסוכטשוב","b":"פרסם מאמרים ב\"בית אברהם\" - וארשא תרצד."},{"i":10263,"n":"ברנשטין, מנחם מקראקא","b":"תשובה אליו - \"דור רביעי\"-תרנו."},{"i":10264,"n":"ברנשטין, מרדכי מזעגר","k":"בעל מסתרי האוואנא","bt":"תרלב","bp":"פלאצק","b":"נסמך לרבנות ע\"י ר חיים הלפרין מביאליסטוק, מחכמי זעגר ועסק במסחר. חיבר \"מסתרי האוואנא\" - \"מלכת הזהב\" - וארשא תרסג, \"אשל מרדכי\" - בכת\"י."},{"i":10265,"n":"ברנשטין, מרדכי מניישטט-שירווינ","b":"מראשי קהילת ניישטט-שירווינט-ליטא. פרסם מכתב ברכה מטעם הקהילה ב\"בית ועד לחכמים\" - לונדון תרסב."},{"i":10266,"n":"ברנשטין, משה יעקב מנאשלסק","b":"רב בנאשעלסק. פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח, \"יגדיל תורה\" - פראגא-וארשא תרפז, \"התפוח\" - בנדין תרפח, \"אחיאסף\" - סטריזוב תרפט, \"יגדיל תורה\" - פראגא-וארשא תרפז."},{"i":10267,"n":"ברנשטין, משה ליב מארה\"ב","f":"יעקב","bt":"תרכט","bp":"פיסאצנע-פלך מינסק","b":"תלמיד ישיבת וולוזין. רב באליזבט-ניו ג'רזי-ארה\"ב-תרסב. נסמך מאת: ר צבי ואלק מפינסק. פרסם מאמרים ב\"בית ועד לחכמים\" - נ\"י תרסג, \"המאסף\" ירושלים."},{"i":10268,"n":"ברנשטין, משה מאנטשיקרק","f":"אשר","bt":"תרלה","b":"רב באנטשקרק(=טארוטינא)-בסרביה-תרנח. נסמך מאת: ר אלתר מקונסטנטין, ר יוזפא אפרתי, ר דוד אורטינבורג מברדיטשוב."},{"i":10269,"n":"ברנשטין, משה מקמניץ","f":"אברהם אליהו","b":"חתן ר ברוך דב ליבוביץ. ר\"מ בישיבת \"כנסת בית יצחק\" בקמניץ-תרצח."},{"i":10270,"n":"ברנשטין, נח טוביה מאמור","f":"יוסף יהודה","k":"בעל מי נח","bt":"תרלג","bp":"פילעטין-קורלנד","b":"תלמיד ישיבות מיר אצל ר חיים טיקטין, איישישוק, סלובודקה, וילנא. רב באמור-פלך יקטרינסלב-תרנט. נסמך מאת: ר שלמה הכהן מוילנא, ר צבי הירש רבינוביץ מקובנא, ר משה דנישבסקי."},{"i":10271,"n":"ברנשטין, נפתלי הרץ מקרמניץ","f":"חיים צבי","k":"בעל צנתרות זהב","bt":"תרי","b":"נכד ר דוד צבי מקרעמניץ. רב בקרמניץ-ווהלין-תרלח."},{"i":10272,"n":"ברנשטין, נפתלי צבי","b":"פרסם מאמרים ב\"בית אברהם\" - וארשא תרצד."},{"i":10273,"n":"ברנשטין, צבי הירש","b":"רב-שנת תר\"כ"},{"i":10274,"n":"ברנשטין, צבי הירש","f":"ישכר בריש","bt":"תץ","dt":"תקמז","b":"אביו שינה שמו מרבינוביץ באבד לברנשטין. מחכמי ברודי. חתן ר יעקב אב\"ד אלענקא."},{"i":10275,"n":"ברנשטין, צבי הירש","f":"משה","bt":"1846","bp":"ניישטט שאקי","dt":"1907","dp":"ניו יורק","b":"עתונאי ומו\"ל. השתתף ב\"המגיד\", \"הכרמל\", ועוד.היגר לארה\"ב-1870 ויסד שם עם צבי גרשוני את העתון היהודי הראשון \"די פאסט\", ואת \"היברו ניוז\" ב-4 שפות (עברית, אידיש, אנגלית וגרמנית), ואת השבועון העברי הראשון בארה\"ב \"הצופה בארץ החדשה\". התעשר מעסקי בנקאות. היה מעוזי יהודה דוד איזנשטין בהוצאת האנציקלופדיה \"אוצר ישראל\"."},{"i":10276,"n":"ברנשטין, צבי יהודה מבוכניה","f":"משה אהרן","bt":"תרסז","bp":"בוכניה","b":"גיסו של ר יצחק איזיק ראטה. ניצל מהשואה - גלה לסיביר. עלה לארץ והתישב ברמלה והיה מלמד ומוהל. חסיד בלז וצאנז."},{"i":10277,"n":"ברנשטין, רפאל","f":"נתן מלברטוב","dt":"תרלח - טז כסלו","b":"רב בליקאב"},{"i":10278,"n":"ברנשטין, שלום מניו יורק","k":"בעל פרדס שלום","b":"רב בניו יורק."},{"i":10279,"n":"ברנשטין, שלמה ממינסק","b":"עסקן מחכמי מינסק-תרמג."},{"i":10280,"n":"ברנשטין, שמואל יצחק מלודז","b":"רב בלודז. פרסם מאמרים ב\"בית מאיר\" - אוסטרובצה - פיעטרקוב - תרצא."},{"i":10281,"n":"ברנשטין, שמואל מאמשטרדם","f":"ישכר דוב בעריש","bt":"תקלג","dt":"תקצט - ד טבת","b":"נכד בעל \"פני אריה\". חתן ר יעקב משה לוונשטם מאמשטרדם. רב בגרנינגל-תקסב, לוורדן-תקסז, אמסשרדם-תקעה ובנו ר ישכר בעריש על מקומו אחריו."},{"i":10282,"n":"ברסון, מיכאל","dt":"תשכז - יז שבט","b":"רב בארה\"ב"},{"i":10283,"n":"ברסלא אריה ליב בן חיים","bt":"1741","dt":"ה'תקסט 1809","bk":[["פני אריה חלק א",""]]},{"i":10284,"n":"ברסלוי, אריה ליב מרוטרדם","f":"חיים","k":"בעל פני אריה","bt":"תקא","bp":"ברסלוי","dt":"תקסט - ו אלול","b":"למד בליסא, מלומדי בית המדרש של הגביר ר דניאל יפה בברלין. רב בעמדין, רוטרדם-תקמא. חיבר ספר שו\"ת \"פני אריה\". חיבר תפילות מיוחדות (בזמן מלחמת נפוליאון) ופיוטים. בניו: ר אברהם ממזריטש ועמדין בעל \"עת לדבר\", ר חיים מלוורדין-הולנד בעל \"דרך חיים, ר מרדכי-דיין ברוטרדם בעל \"בית מרדכי\".","bk":[["פני אריה",""]]},{"i":10285,"n":"ברסלוי, יוסף משה מברסלוי","f":"דוד","k":"בעל חק יוסף","r":"אב\"ד באמבורג","bt":"ה'תנא","dt":"תקיב - ו שבט","b":"חתן ר אברהם ברודא. רב בקרופלד-מדינת בומברג-תק. חיבר גם \"חק יוסף\" על חק יעקב לר יעקב רישא, \"כתנת יוסף\" ונדפס ע\"י בנו ר אברהם עם חדושי זקנו - ר אברהם ברודא - בשם \"תולדות אברהם\" פיורדא תקכט.","bk":[["חק יוסף [על הל' פסח]",""],["שורש יוסף [על מיגו]",""],["חק יוסף",""],["שרש יעקב",""]]},{"i":10286,"n":"ברסלוי, ישראל מהמבורג","f":"מיכל מברסלוי","bt":"תקטו","bp":"ברסלוי","dt":"תקסט - יט אדר","dp":"המבורג","b":"סופר ודיין בהמבורג אצל ר יעקב עמדן ונזכר בספרו \"דברי אמת ומשפט שלום\" אודות המחלוקת באה\"ו. הו\"ל רשימת ספרים חשובים מספריית ר דוד אופנהיים, אגרת מליצה בתוך \"תוכחת מגילה\"."},{"i":10287,"n":"ברסלוי, משה מפרשבורג","f":"ברוך","b":"מחכמי פרשבורג. חתם על תקנות ר מאיר ברבי-תקכח."},{"i":10288,"n":"ברסלוי, פיבל מפרשבורג","b":"מחכמי פרשבורג. חתם על כתב מנוי רבנות לחת\"ס-תקסז."},{"i":10289,"n":"ברסלוי, ראובן משטמפן","f":"פיבל פיזינג מברסלוי","dt":"תקכח - כד טבת","dp":"שטמפן","b":"גביר בוינה, שטמפן-תקכג."},{"i":10290,"n":"ברסלר, ישראל מטשרניוב","b":"רב בטשרניוב (ליד סטניסלב). חתן ר שמעון שרייבר מדלטין. נספה בשואה."},{"i":10291,"n":"ברסלר, מנחם מנדל זאב","bt":"תרכה","b":"נכד ר שמואל אב\"ד טשעכנוב, ונכד-אבי אמו אברהם יהודה ליב מברוק בעל \"איל מלואים\". חתן אב\"ד וישקוב. מו\"צ בוישקוב(=וישקאוו)-פלך וארשא-תרנח. נסמך מאת: ר יהושע מקוטנא, ר מלכיאל צבי טננבוים מלומזה."},{"i":10292,"n":"ברסקי, שמשון מאומאן","dt":"תרפט","b":"נכד ר נחמן מברסלב. ראש הקלויז באומאן יחד עם ר געצ'ה. בנו ר נתן ונכדו ר שמשון מנהיג חסידי ברסלב בבני ברק."},{"i":10293,"n":"ברעוודא, שלמה מבני ברק","b":"רב בבני ברק, חתם-תשכג על בקשת עזרה מטעם הת\"ת של הסטייפלר."},{"i":10294,"n":"ברעזווייץ, יוסף","b":"רב בווייצן"},{"i":10295,"n":"ברעסלויר, מנחם מנדל מברסלוי","f":"יצחק","k":"בעל קיצור שו\"ע","bt":"תרמז","bp":"קעמפנא","dt":"תשכג - כח תשרי","dp":"תל אביב","b":"תלמיד זקנו ר שלמה מרדכי שייער מקעמפנא, הרב ד\"ר ליאו מינץ בעל \"תורת נשים\". רב ביהכ\"נ שקלווער בברסלוי (בעבר כיהן בו ר ישעיה פיק בעל \"מסורת הש\"ס\"). ערך את הקיצור שו\"ע להתאימו לנערים. עלה לארץ-תרצג עם ספרייתו החשובה, הקים בית ספר חרדי ברחובות, עבר לתל אביב וסירב להצעה לכהן כרב יוצאי גרמניה שם, כיהן כרב ביהכ\"נ \"עדת ישורון\" בתל אביב לצד חברו הרב מיכלסקי. חיבר גם \"פאת השלחן\"."},{"i":10296,"n":"ברף, אליהו חיים מזמיגרוד","b":"מחכמי זמיגרוד-תרסד, עבר להאג. תשובות אליו \"אמרי יושר\" ו\"מחזה אברהם\"."},{"i":10297,"n":"ברפלד, אהרן מהרימלוב","b":"מחכמי הרימלוב. תלמיד ר\"י ויידנפלד מהרימלוב."},{"i":10298,"n":"ברצ'ה, רחמים מטריפולי","dt":"תרפט","b":"רב בטריפולי."},{"i":10299,"n":"ברקאהן, אליהו מפפד\"מ","k":"בעל פירוש על ירושלמי","dt":"תצא - ד אד\"א","dp":"פפד\"מ","b":"מחכמי פפד\"מ."},{"i":10300,"n":"ברקאי בנימין יעקב","bt":"1904","dt":"ה'תשמ 1980","bk":[["נחלת בנימין",""]]},{"i":10301,"n":"ברקו, יום טוב","b":"מגדולי רבני מצרים-ש\"ס"},{"i":10302,"n":"ברקו, יוסף משלוניקי","b":"רב בשלוניקי-שנות ה-ש'."},{"i":10303,"n":"ברקוביץ, אברהם דב בר מירושלים","bt":"תקפה","dt":"תרס - כח תשרי","dp":"ירושלים","b":"חתן ר נחמן יעקב ליפשיץ. רב בקוזן-הורדק(=קאזאנהארדאק), לעכווא(=לאחווא)-ליד פינסק ובניו ר דוד ור יצחק צבי על מקומו אחריו, עלה לירושלים-תרנט. בנו גם - ר מרדכי מירושלים."},{"i":10304,"n":"ברקוביץ, איכל מקאשוי","f":"אליעזר","dt":"תשד - כד אייר","b":"תלמיד השב\"ס, מחכמי קאשוי וחבר בהנהלת הקהלה ושימש כבורר בדיני תורה. נספה בשואה."},{"i":10305,"n":"ברקוביץ, בנציון יהודה מוילנא","f":"אליהו","k":"בעל עוטה אור","bt":"תקסג","bp":"וילנא","dt":"תרלט - יח אייר","dp":"וילנא","b":"חתן ר זלמן סאקער וכונה ר בענטשיל סאקער'ס וחותנו החזיקו עד יום פטירתו-תריח. משכיל בן תורה, חוקר הלשון הארמית. פרסם מאמרים בכתבי עת שונים. חיבר \"עוטה אור\" על תרגום אונקלוס - וילנא תרג, \"לחם ושמלה\" על תרגום אונקלוס, \"לווית חן\" על \"חדושי נתן\" לר נתן אדלר, ועוד. חיבר מילון ארמי בכת\"י. הניח כתבים נוספים בכת\"י והיו בידי ר חי\"ל מארקאן בוילנא ונמכרו לאוצר הגביר פרידלנד בפטרברוג-תרמט."},{"i":10306,"n":"ברקוביץ, דוד מדאווד-הורדוק","f":"אברהם דב בר מירושלים","k":"בעל חנה דוד","bt":"תרט","dt":"תרנט (באו' תרצו","dp":"ירושלים","b":"מו\"ץ בלאחווא-ליטא-תרן אצל אביו, רב בדאווד-הורדק-תרן, עלה לירושלים-תרנט. חיבר \"חנה דוד\" נדפס בתוך \"זכר אברהם\" לאביו פינסק תרצו. בנו - ר יצחק צבי."},{"i":10307,"n":"ברקוביץ, דוד משסבורג","dp":"ירושלים","b":"חתן ר יוסף אדלר משסבורג. רב בשסבורג על מקום חותנו שעבר לטורדה(=טורדא), ניצל מהשואה. רב בלונדון. עלה לירושלים."},{"i":10308,"n":"ברקוביץ, חיים","b":"ניצל מהשואה והגיע לשנחאי-סין. פרסם מאמרים ב\"מאור תורה\" - שנחאי-סין תשד - קובץ תלמידי ישיבת מיר בשנחאי, \"התבונה\" - נ\"י תשז - קובץ תלמידי ישיבת מיר."},{"i":10309,"n":"ברקוביץ, חיים אלתר","b":"מרביץ תורה בווייצן"},{"i":10310,"n":"ברקוביץ, יהושע מקולומיאה","b":"דיין בקולומיאה אצל ר זכריה מנדל זילבר."},{"i":10311,"n":"ברקוביץ, יוסף","dt":"תשג","b":"מרביץ תורה בישיבת אסטרא."},{"i":10312,"n":"ברקוביץ, יוסף","b":"פרסם מאמרים ב\"כנסת ישראל\" - וילנא תרץ."},{"i":10313,"n":"ברקוביץ, יוסף ברוך מקולומיאה","dt":"תרצו - בערך"},{"i":10314,"n":"ברקוביץ, יעקב דוד מטיסא לוק","k":"בעל עת הזמיר","b":"רב בטיסא לוק-מחוז סאבולץ."},{"i":10315,"n":"ברקוביץ, יצחק צבי מלאחווא","f":"אברהם דב בר מירושלים","bt":"תריח","dt":"תרצה - יט כסלו","b":"מו\"צ בקוזק-הורודוק, רב בלאחווא-תרנט על מקום אביו שעלה לארץ. חיבר שו\"ת, חיבור על הש\"ס - בכת\"י."},{"i":10316,"n":"ברקוביץ, ישראל יהודה מאילאווא","bt":"תרסה","bp":"טשעפע","dt":"תש..","dp":"אושוויץ","b":"תלמיד הדעת סופר. רב באילאווא-תרצה. נספה בשואה."},{"i":10317,"n":"ברקוביץ, מרדכי מירושלים","f":"אברהם דב מירושלים","b":"חתן ר חיים טיטלבוים-חתנו של ר אלעזר משה הורביץ מפינסק. עלה עם אביו לירושלים."},{"i":10318,"n":"ברקוביץ, משה","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":10319,"n":"ברקוביץ, משה יהושע מקולומיאה","f":"אברהם יהודה","dt":"תרסד - כט שבט","b":"ראש ישיבה בהאגר, רב וראש ישיבה בקולומיאה, בנו ר אלתר על מקומו אחריו."},{"i":10320,"n":"ברקוביץ, קלונימוס קלמן מסאוורן","b":"פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס, \"שמעתתי דרבנן\" - אודסה תרמז."},{"i":10321,"n":"ברקובסקי, אליהו דוד","bt":"תרכה","dt":"תשג - כה אד\"א","b":"מרביץ תורה בישיבת בית יוסף בנוברדוק,בלידא,תל אביב-תרפ\"ד"},{"i":10322,"n":"ברקום, קלונימוס קלמן ממיטאוי","f":"זליגמן","dt":"תקפח - יט סיון","dp":"מיטאוי","b":"גביר במיטאוי-תקלח ומקורב לשלטון ופעל לטובת אחיו היהודים, יחד עם אחיו ר שמשון. מכספו נבנה ביהכ\"נ במיטאוי-תקמד. חתנו - ד\"ר עלריך - יועץ הקיסר."},{"i":10323,"n":"ברקום, שמשון ממיטאוי","f":"זליגמן","dt":"תקפח - כ תמוז","dp":"מיטאוי","b":"גביר במיטאוי ומקורב לשלטון ופעל לטובת אחיו היהודים, יחד עם אחיו ר קלונימוס קלמן."},{"i":10324,"n":"ברקון ן, חנניה מירושלים","b":"מחכמי ורבני ירושלים-שפ\"ג"},{"i":10325,"n":"ברקי, אברהם משלוניקי","dt":"שמח","b":"מחכמי שלוניקי. נהרג עק\"ה."},{"i":10326,"n":"ברקי, אליהו משלוניקי","dt":"תז","dp":"ירושלים","b":"תלמיד ר חיים שבתי בשלוניקי, דיין מגדולי חכמי שלוניקי, מגדולי חכמי איטליה בנגלה ובנסתר בליוורנו, ובעל בית דפוס שם-תרל. מתלמידיו - ר יוסף קרסו ור יצחק פרנסיס, ר אהרן לאפפא בספרו \"בני אהרן\" מביא תורה משמו. הסכים על \"שו\"ת שלמה הלוי\", תשובה ממנו בסוף ספר \"התרומה\", בסוף ימיו עלה לירושלים. בנו - ר יצחק."},{"i":10327,"n":"ברקי, דוד בכור","f":"משה","bp":"אזמיר","b":"עלה לחיפה-תרסח, עבר בביירות, דמשק, חמה ושם סייע לפליטי יון בזמן מלחמה\"ע ה-I. חבר בועד העדה הספרדית-תרצה."},{"i":10328,"n":"ברקי, יוסף מטוקאת","b":"רב בטוקאת-שנות ה-ת'."},{"i":10329,"n":"ברקי, יוסף מצפת","b":"מחכמי צפת, חתם-תפא על כתב שליחות ר משה ישראל מרודוס."},{"i":10330,"n":"ברקי, יוסף משלוניקי","dt":"תף - בערך","dp":"שלוניקי","b":"מחכמי שלוניקי-תם."},{"i":10331,"n":"ברקי, יצחק משלוניקי","f":"אליהו","dt":"תז","b":"רב ור\"מ בשלוניקי, עלה לירושלים (כך באוצר הרבנים). מתלמידיו ר יוסף קרסו, ור יצחק פרנסיס. כתב הגהות בגליון הטור בכת\"י, ומהם בספר \"מורה צדק\" לר מיכאל הכהן."},{"i":10332,"n":"ברקי, משה מאזמיר","k":"בעל מזכרת הגטין","dt":"תרעג - ד סיון","dp":"אזמיר","b":"תלמיד ר חיים פאלג'י ובנו ר אברהם פאלג'י שהביא מתורתו בספריו \"חקקי לב\" ואחרים. כיהן כדיין אצל ר אברהם באזמיר. ישב כדיין עם חברו ר יהודה די שיגורה, ור יצחק פיג'ון. כיהן כממונה על הגיטין וקדושין באזמיר, ורב הראשי על מקום ר רחמים נסים יצחק פאלג'י לצדו של ר יסוף בן סינייור. רוב כתביו אבדו, ומדבריו נערך \"מזכרת הגטין\"."},{"i":10333,"n":"ברקמן, אהרן אבא","dt":"תש","b":"רב בסווירז"},{"i":10334,"n":"ברקמן, יחיאל מיכל מאריחוב","f":"יצחק","k":"בעל לב ים","bt":"תריח","b":"רב באריחאוו-פלך טבריא-תרן. חיבר גם \"אפיקי ים\" - בכת\"י."},{"i":10335,"n":"ברקמן, ישעיה","dt":"תשג","b":"רב בדנקר"},{"i":10336,"n":"ברקמן, מאיר אבא","dt":"תשג","b":"רב בסוויר"},{"i":10337,"n":"ברקמן, צבי הירש זסקוויצר","f":"יצחק מוילנא","dt":"תרם - ו חשון","dp":"וילנא","b":"חתן ר יוסף מזסקביץ, וגיסו של הרש\"ש מוילנא."},{"i":10338,"n":"ברש, יוסף מטרנופול","b":"תשובה אליו - \"אמרי דוד\"-תרצא."},{"i":10339,"n":"ברשטין, אריה ליב מהורדנא","f":"זאב","dt":"תרנו","b":"רב בהורדנא. הניח דרשות והספדים בכת\"י. נספד ב\"דרוש כבוד התורה\" לר ישראל בנימין למפרט מירושלים. אולי בנו - ר משה הניך מלונדון בעל \"אוצר פתגמים מחכמים\"."},{"i":10340,"n":"ברשטין, משה הניך מלונדון","f":"אריה ליב","k":"בעל אוצר פתגמים","b":"רב בלונדון לקהילת יוצאי הורדנא ולודז. חיבר \"אוצר פתגמים מחכמים\" לונדון תרסד."},{"i":10341,"n":"ברשטר, רפאל","b":"רב-שנת תק\"כ,מתלמידי הבעש\"ט, ור פנחס שפירא מקורץ."},{"i":10342,"n":"בש, אפרים מאפושטג-הונגריה","b":"רב ניאולוגי באפושטג-1858 והקים שם בית ספר."},{"i":10343,"n":"בש, חיים","dt":"תקמא - א חשון","b":"רב בקרסטור(=קרסטיר)"},{"i":10344,"n":"בשארי, יהודה","f":"יחיא","bt":"תרם","bp":"אלגבי(תימן)","dt":"תשלה","dp":"ראש העין","b":"רב הקהילה באלגבי"},{"i":10345,"n":"בשארי, שלמה מתימן","f":"יחיא","b":"דיין בשרעב-תימן - לפני תשח. חתם עם חבריו ר דאוד יודא ויהודה סאלם, על מסמך המאשר קבלת סיוע מהתאחדות התימנים בישראל-תשח, הכסף נתקבל באמצעות ועד הרבנים בצנעא."},{"i":10346,"n":"בשביץ, ברוך מרדלהיים","bt":"תקכה","bp":"פפד\"מ","dt":"תקצו","dp":"רדלהיים","b":"מדפיס ברדלהיים, שותפו של ר וולף היידנהיים."},{"i":10347,"n":"בשורי, יחיא","k":"בעל חבצלת השרון","b":"מלומד בנסים,מגדולי חכמי תימן בצנעא-ש\"פ"},{"i":10348,"n":"בשייצי, אליהו מקושטא","f":"משה בן מנחם","k":"בעל אדרת אליהו","b":"חכם קראי בקושטא-רמ, תלמיד ר מרדכי כומטינו (שהיה רב תלמודי). ר משה הגולה מקיוב למד אצלו חכמת התכונה בקושטא-רמ. חיבר גם \"ספר המצוות\". גיסו של ר כלב אפונדופולו."},{"i":10349,"n":"בשייצי, מנחם מאדרינופול","b":"מראשי עדת הקראים באדרינופול. בזמנו התירו לקראים לראשונה להדליק נר בערב שבת כמנהג היהודים."},{"i":10350,"n":"בשייצי, משה מאדרינופול","f":"מנחם","b":"מראשי עדת הקראים באדרינופול. בזמנו התירו לקראים לראשונה להדליק נר בערב שבת כמנהג היהודים."},{"i":10351,"n":"בשקביץ, אברהם אריה מארה\"ב","f":"שלום משה","bp":"לומזה","b":"ממיסדי קהלת \"עדת ישורון\" בברונזויל-ניו יורק. אחיהם של ר יעקב צבי, הש\"ץ ר ישראל הלל."},{"i":10352,"n":"בשקס, אריה ליב","b":"רב בשניפישוק,עלה לירושלים-תרנ\"ז"},{"i":10353,"n":"בת שבע - משפחה","b":"משפחת מדפיסים באיטליה עברו לשלוניקי-שנב לבקשת ר משה בן שמואל די מדינה."},{"i":10354,"n":"בת שבע, אברהם משלוניקי","b":"מדפיס בשלוניקי, יסד דפוס בדמשק עם האחים יעקב ויצחק בני אברהם אשכנזי - המדפיסים מצפת."},{"i":10355,"n":"בת שבע, יעקב ואשתו הנדל","f":"עזריאל גרוניס","k":"ר יעקב שמילעס","dt":"שצד","dp":"ינוגבונצלוי - פרג","b":"גביר ופרנס בפרג-שן, גיטשין, ומקורב למלכי אוסטריה, קיבל רשות לבנות ביכ\"נ בביתו בפרג, סייע לר יום טוב ליפמן הלר ונתן מכספו כדי לסייע לו. אשתו הנדל - ר יעקב. פעלה רבות למען היהודים."},{"i":10356,"n":"בת שבע, מתתיה מאיטליה ושלוניקי","b":"מדפיס בונציה, עבר לשלוניקי-שנב עם בניו ויסד שם דפוס, בהשפעת ובעזרת ר משה בן שמואל די מדינה."}];
